// مولّدة آلياً بواسطة scripts/split-fatwas.mjs — لا تُعدَّل يدوياً.
export default [{"id":13,"question":"امرأة تسأل وتقول: إنها تتنمَّص من أجل تجمّلها لزوجها، وهي محجَّبة، ولا تُبدي زينتها إلا لزوجها، فماذا يجب عليها؟","title":"هل يجوز للمرأة أن تتنمَّص لزوجها؟","answer":"الجواب: الرسول ﷺ لعن النَّامصة والمُتنمِّصة، والواشمة والمُستوشمة، والواصلة والمُستوصلة، كل هؤلاء جاءت الأحاديثُ الصَّحيحةُ بلعنهم، فهي أتت منكرًا وإن كانت تدَّعي بهذا أنها تتزين لزوجها، فالزينة للزوج تكون بالمباح، لا بالحرام، تتزين بالملابس، بالطِّيب، بالكحل، أما بما حرَّم الله فلا، لا تتزين له بالوشم، ولا بالنمص من حاجبيها، ولا من وجهها، ولا تتزين له بما حرَّم الله من الأمور الأخرى التي لا تجوز لها.","link":"https://binbaz.org.sa/fatwas/2792/هل-يجوز-للمراة-ان-تتنمص-لزوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0265.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":46,"question":"ما حكم الإسبال من غير قصد المَخِيلة؟","title":"ما حكم الإسبال من غير قصد المَخِيلة؟","answer":"الجواب: الإسبال محرم ولا يجوز، وإذا كان عن قصد المَخِيلة فهو أشد إثمًا؛لقول النبي ﷺ: ما أسفل من الكعبين من الإزار فهو في النار ولم يشترط الخيلاء.\nوقال ﷺ: ثلاثة لا يكلمهم الله ولا ينظر إليهم يوم القيامة ولا يزكيهم ولهم عذاب أليم: المسبل إزاره، والمنَّان فيما أعطى، والمنفِّق سلعته بالحلف الكاذب رواه مسلم في الصحيح.\nقال عليه الصلاة والسلام: إياك والإسبال فإنه من المخيلة.\nفلا يجوز الإسبال مطلقًا؛ لكن إذا كان عن خيلاء صار أشد في الإثم.\nأما إذا غلبه، فارتخى ثوبه أو (بشته) عن غير قصد الخيلاء، بل غلبه في بعض الأحيان، فهذا يعفى عنه، كما جرى للصديق  حينما قال له رسول الله ﷺ إنك لم تفعله خيلاء، لما قال له: يسترخي إلا أن أتعاهده، فإذا تعاهد الإنسان إزاره، ثم انتقض عليه بعض الشيء، وتعاهده ورفعه حتى لا يُخاط، فلا شيء عليه.\nأما أنه يتعمد سحب (البشت)، أو سحب الإزار، أو سحب السراويل،؛فهذا منكر.","link":"https://binbaz.org.sa/fatwas/2826/ما-حكم-الاسبال-من-غير-قصد-المخيلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0019.mp3","categories":["اللباس والزينة"]},{"id":55,"question":"هنالك أخت أخرى تسأل وتقول: ما حكم تقليد الغرب في أزيائهم وملابسهم عن طريق مجلات الأزياء؟","title":"ما حكم تقليد الغرب في أزيائهم وملابسهم؟","answer":"الجواب: لا يجوز للمسلمات ولا للمسلمين تقليد الغرب ولا الشرق في أزيائهم الخاصة التي ليست من عادة المسلمين؛ لأن الله جل وعلا نهانا عن التخلق والتشبه بأعدائنا قال : وَلَا تَكُونُوا كَالَّذِينَ نَسُوا اللَّهَ فَأَنْسَاهُمْ أَنْفُسَهُمْ أُولَئِكَ هُمُ الْفَاسِقُونَ [الحشر:19] وقال: وَخُضْتُمْ كَالَّذِي خَاضُوا [التوبة:69] ذمًا لهم وعيبًا لهم في خوضهم كما خاض الأعداء، وقال النبي ﷺ: مَن تشبَّه بقوم فهو منهم، وقال: قصوا الشوارب وأعفوا اللحى خالفوا المشركين، وقال: جزوا الشوارب وأرخوا اللحى خالفوا المجوس، في أحاديث كثيرة، فالواجب على رجال الإسلام ونساء الإسلام ألا يتشبهوا بأعداء الله في أزيائهم الخاصة، وأن يبتعدوا عن ذلك في أي مكان كانوا؛ لما تقدم من الأدلة.","link":"https://binbaz.org.sa/fatwas/2966/ما-حكم-تقليد-الغرب-في-ازياىهم-وملابسهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0029.mp3","categories":["اللباس والزينة"]},{"id":67,"question":"سائلة تقول: هل يجوز لبس البنطلون أمام النساء، وأمام الزوج، والمحارم؛ علمًا بأن البنطلون فضفاض وواسع؟","title":"حكم لبس البنطال للمرأة أمام النساء والمحارم","answer":"الجواب: إذا كان من جنس لباس النساء ما فيه تشبُّه بالكفرة، من جنس اللباس الذي يلبسه نساء بلدها ما فيه تشبُّه بالكفار فلا بأس، وإلا تعتني بلباس أهل بلدها لا تشذ عنهم، يكون لباسها لباس أهل بلدها حتى لا يحصل لها شذوذ، ولا شهرة.","link":"https://binbaz.org.sa/fatwas/2983/حكم-لبس-البنطال-للمراة-امام-النساء-والمحارم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0042.mp3","categories":["اللباس والزينة"]},{"id":98,"question":"إن تشخيص بعض الحالات المرضية للجنين يتم للمرأة الحامل، وذلك في الأشهر 4 و5 و6، وهذه الأمراض غالبًا ما تكون ذات تأثيرٍ على المريض: من تخلُّفٍ عقليٍّ، أو من تخلُّفٍ جسماني، فهل من الجائز أن يعمل إسقاط للجنين في هذه الأشهر، مع مراعاة تلك العواقب التي قد يعيش فيها الطفلُ: من التَّخلف، أو من المرض المُستديم في المجتمع؟ أفيدونا جزاكم الله خيرًا؛ لأنَّ هذه الحالة تُحيّر الأطباء","title":"حكم إسقاط الجنين في الأشهر الأوائل","answer":"الجواب: هذا موضوعٌ درسه مجلسُ هيئة كبار العلماء، وقرروا فيه قرارًا سنُعطي المدير نسخةً منه إن شاء الله، ومُلخصه: أنه إذا كان الضَّرر على الطفل فهذا لا يجوز إسقاطه إذا تخلَّق أو نُفِخَتْ فيه الروح. أما إذا كان الضَّرر عليها هي -خطرٌ على نفسها فقط لو تُرِكَ- والخطر يعني: الموت؛ فهذا يُسقط ولو كان في السادس أو السابع أو الثامن، إذا كان الخطر عليها، ولو بقي لهلكت هي، فهذا يُسقط.\nأما إذا لم يكن عليها خطرٌ فلا يُسقط؛ لأنه نوع قتلٍ، فيُترك حتى تلد، وإذا ولدت فالأمر إلى الله، إن كان سليمًا فالحمد لله، وإن كان مُشَوَّهًا فإنا لله وإنا إليه راجعون، ولا يجوز قتله.\nأما إذا كان قبل الأربعة أشهر فهذا إن كان فيه ضررٌ بيِّنٌ عليها جاز إسقاطه، وإن لم يكن فيه ضررٌ بيِّنٌ تُرِكَ.\nونُعطي إن شاء الله المدير صورةً، فسوف يُرسَل لنا غدًا أو بعد غدٍ ونُعطيكم الصورة إن شاء الله حتى يقرأها عليكم.","link":"https://binbaz.org.sa/fatwas/3127/حكم-اسقاط-الجنين-في-الاشهر-الاواىل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0078.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":147,"question":"أختٌ مسلمةٌ تلبس ثوبًا يكسي جميع الجسد، وهو غير شفَّافٍ، وتلبس العباءة، والتي كذلك تُغطي كل الثوب حتى الأرض، وهو مقفولٌ من الأمام، وكذلك غطاء الوجه، فهل يجوز لها أن تخلع العباءة فقط إذا زارت بعض النِّساء المسلمات؟ ما الحكم؟ وما الدليل؟","title":"ماذا يجوز كشفه من المرأة أمام النساء؟","answer":"الجواب: لا شكَّ أن المرأة عورة، وعليها الاحتجاب عن الرجال غير المحارم، أما إذا زارت النساء فلا بأس؛ لأنه لا يجب عليها الاحتجاب عن النساء، وإنما تحتجب عن الرجال، فإذا زارت النساء وطرحت عباءتها فلا بأس ولا حرج في ذلك، والله قال: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]، وقال: وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ إلى أن قال: أَوْ نِسَائِهِنَّ [النور:31]، فإبداء الزينة للنساء ليس فيه شيءٌ، ولا حرج في ذلك.","link":"https://binbaz.org.sa/fatwas/3684/ماذا-يجوز-كشفه-من-المراة-امام-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0140.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":149,"question":"ما حكم استعمال العطور المعروفة بـ\"الكالونيا\"، والتي يوجد فيها كحول؟","title":"حكم العطور التي تحتوي على نسبة كحول","answer":"الجواب: العطور التي يُعرف أنَّ فيها كحولًا؛ مُسكرة، لا تُستعمل، مثل: \"الكالونيا\".\nوقد حدَّثنا كثيرٌ من الأطباء أنها لا تخلو من الإسبرتو، وأنه متفاوتٌ فيها: بعضه أكثر من بعضٍ، فبعضه فيه 80%، وبعضه 60%، وبعضه 40%، إلى غير ذلك، فهذا ينبغي ألا يُستعمل، وإن كان بعض الناس تساهل فيه واستعملوه، لكن نصيحتي لطالب العلم ألا يستعمل هذا المعروف، وهو \"الكالونيا\" المعروفة التي فيها الإسبرتو، وهو مسكر.\nأما العطور الأخرى فلا أعرفها، لكن إذا عرفت أنَّ فيها شيئًا مُسكرًا، وأنَّ كثيره يُسكر؛ فلا تستعملها، واستعمل الطيب المعروف: من دهن الورد، ودهن العنبر، ودهن العود المعروف الذي ليس فيه شيء.","link":"https://binbaz.org.sa/fatwas/3686/حكم-العطور-التي-تحتوي-على-نسبة-كحول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0142.mp3","categories":["اللباس والزينة"]},{"id":156,"question":"في هذا العصر انتشر لباسُ الغرب، ومنها البنطلون، ومن صفته أنه ضيقٌ، فما حكم لبس هذا البنطلون أولًا؟ ثم ما حكم الصلاة فيه، مع أنه يفصل العورة بوضوحٍ أثناء السجود؟ وما الحل؟","title":"حكم لبس البنطلون والصلاة فيه","answer":"الجواب: أما لبس البنطلون فقد شاع بين الناس، ولم يبقَ خاصًّا بالكفار، شاع بين المسلمين وانتشر بينهم، وصار في جنودهم، فلم يكن الآن خاصًّا بالكفار، بل انتشر بين المسلمين وغيرهم، مثل: لبس الكنادر، وركوب السيارات، وركوب الطائرات، فهذا عمَّ الناس كلهم، ولم يبقَ خاصًّا بالكفار.\nلكن يجب أن يكون واسعًا لا ضيقًا، وأن يتحرز من هذا الشيء الذي يفصل العورة ويُبَيِّن حجمها ويُؤذيه في صلاته، فينبغي على المسؤولين أن يضعوا شيئًا واسعًا جيدًا يستر العورة ولا يُبين حجمها، ويُعينه على صلاته ووضوئه وغير ذلك، أما هذا الضَّيق الذي يُؤذيه ويُبرز عورته فلا ينبغي لبسه، والذي يظهر أنه لا يجوز، وعليه أن يُعالج هذه الأمور مع المسؤولين حتى يُغيّروا هذه الملابس الضَّارة الضيقة.\nولعلنا إن شاء الله نفعل ما نستطيع في هذا -إن ذُكّرنا بذلك- ونمنعه الآن إن شاء الله، ونرجو من الله أن يُعيننا على ذلك، فإنَّ تذكير المسؤولين مهمٌّ بهذا، وهم من كل خيرٍ قريبون -نسأل الله لنا ولهم الهداية.","link":"https://binbaz.org.sa/fatwas/3693/حكم-لبس-البنطلون-والصلاة-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0149.mp3","categories":["اللباس والزينة","ستر العورة للمصلي"]},{"id":157,"question":"ورد في الحديث الصَّحيح: لعن الله الواشمات والمُستوشمات، والنامصات والمُتنمصات... إلى آخره، فهل التَّنمُّص مُقَيَّدٌ بنتف الحواجب أم بالإمكان إزالة بعض شعر الوجه؟ ثم هل يدخل الرجلُ تحت هذا النَّهي أم هو للنساء فقط؟","title":"حكم النمص في حق النساء والرجال","answer":"الجواب: الحديث صحيحٌ في \"الصحيحين\"، والنَّامصات: اختلف أئمَّةُ اللغة وغريب الحديث؛ فبعضهم خصَّ به الحواجب، وقال: إنه نتف شعر الحواجب، الإنماص هو الإنقاش، وقال آخرون: بل يعمُّ الحاجب، ويعم الوجه كله، وهو نتف الشعر من الوجه مطلقًا: من الخدّين، ومن الحاجبين.\nولم يذكروه إلا في النِّساء عند حديث النَّامصات، ولكن مقتضى العلَّة قد يُقال أنه يعمُّ، والحديث جاء في النامصات، ولكن مقتضى العلة -وهو أنه تغييرٌ لخلق الله وتشويه لخلق الله- يعمُّهما جميعًا، فلا يخصّ النساء، وإن كان الحديثُ ورد فيهنَّ، فالسبب والله أعلم أنهنَّ المُعتادات لذلك، وهن الحريصات على هذا الشيء، يزعمن أنهن يتزيّن بذلك لأزواجهن، فلهذا جاء الحديثُ فيهن، وإلا فالذي يظهر أنه عامٌّ.\nولهذا فالوشم حرامٌ حتى على الذكور، وجاء في الحديث: الواشمات، ولو فعلها الرجلُ حرم عليه، فهكذا مسألة النَّمص، فالذي يظهر أنه عامٌّ، وأنه ليس للرجل أن ينمص حاجبيه، وهكذا شعر الوجه؛ لأنَّ الخدين من اللحية، وقد قال في \"القاموس\" وغيره: \"اللحية: ما نبت على الخدّين والذقن\"، وعلى كل حالٍ، فأشده النَّمص، أشد النَّمص ما تعلَّق بالحاجبين.","link":"https://binbaz.org.sa/fatwas/3694/حكم-النمص-في-حق-النساء-والرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0150.mp3","categories":["اللباس والزينة"]},{"id":174,"question":"سماحة الشيخ، نرجو التكرم بتوجيه كلمة للنساء عن خطر التَّبرج والسُّفور؟","title":"ما أخطار التبرج وآثاره وكيفية مواجهتها؟","answer":"الجواب: الواجب على كل امرأةٍ الحذر من التبرج والسُّفور وأسباب الفتنة؛ لأن المرأة عورة، والرجال ميَّالون إليها، وهي ميَّالة إليهم، والمعصوم مَن عصمه الله، والمحفوظ مَن حفظه الله.\nفالواجب على الرجال الحذر، وعلى النساء الحذر، الرجل يحذر ويغُضّ بصره، ويحذر الخلوة، ويحذر كل أسباب الفتنة، والمرأة كذلك عليها أن تحذر أسباب الفتنة: من الخلوة بالرجل، والتبرج في الأسواق بإظهار المحاسن والمفاتن، والسفور الذي عند الأجانب، يقول الله جلَّ وعلا: وَقَرْنَ فِي بُيُوتِكُنَّ أي: الزمنَ بيوتكن، وَلَا تَبَرَّجْنَ تَبَرُّجَ الْجَاهِلِيَّةِ الْأُولَى [الأحزاب:33].\nقال العلماء: معنى التبرج: إظهار المحاسن والمفاتن من الرأس والرقبة والوجه والصدر والأقدام والسّيقان، كل هذه فتنة، فالواجب التَّستر، ولهذا قال : وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]، أطهر لقلوب الجميع من وراء حجاب، يعني: من وراء بابٍ أو سترٍ أو جدارٍ أو ملابس تستر، وقال جلَّ وعلا في النساء: وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ الآية [النور:31].\nفعلى الجميع التعاون على البر والتقوى: المرأة عليها أن تحتجب، وأن تبتعد عن التبرج، وألا تخرج إلى الأسواق إلا للحاجة، وإذا خرجت للحاجة تكون متسترةً بعيدةً عن الفتنة، سواء لبيتٍ أو للسوق أو لغير ذلك من الحاجات، فتكون متسترةً بعيدةً عن أسباب الفتنة، وعلى الرجال غضّ البصر، والحذر من مُغازلة النساء ومُتابعتهن، فعلى الرجل أن يحذر ويبتعد عن الفتنة، قال تعالى: قُلْ لِلْمُؤْمِنِينَ يَغُضُّوا مِنْ أَبْصَارِهِمْ وَيَحْفَظُوا فُرُوجَهُمْ ذَلِكَ أَزْكَى لَهُمْ الآية [النور:30]، ويقول سبحانه: وَقُلْ لِلْمُؤْمِنَاتِ يَغْضُضْنَ مِنْ أَبْصَارِهِنَّ وَيَحْفَظْنَ فُرُوجَهُنَّ [النور:31].","link":"https://binbaz.org.sa/fatwas/3720/ما-اخطار-التبرج-واثاره-وكيفية-مواجهتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0172.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":181,"question":"ما حكم لبس البرقع، خاصةً وأنَّ بعض النساء توسَّعن في ذلك؟ وهل هو حجاب شرعي؟","title":"ما مواصفات البرقع الجائز للمرأة؟","answer":"الجواب: إذا كان بقدر العين أو العينين فهو حجابٌ شرعي، وإن جعلت لها خمارًا مع ذلك احتياطًا فحسنٌ، وإلا فالبرقع لا بأس به، إلا المُحرمة فإنها لا تلبس البرقع، المحرمة بالحج أو العمرة ليس لها لبس البرقع، بل تُغطي وجهها بالشيلة ونحوها، أما إن كانت غير محرمةٍ فلها لبس البرقع، وليس لها أن تُخرج إلا العين أو العينين فقط، والبقية مستور.","link":"https://binbaz.org.sa/fatwas/3753/ما-مواصفات-البرقع-الجاىز-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0183.mp3","categories":["اللباس والزينة"]},{"id":201,"question":"ما حكم أدوات الزينة للمرأة: كالمكياج، والحمرة، وتوابعها؟","title":"ما حكم أدوات التجميل التي تستعملها النساء؟","answer":"الجواب: لا حرج في ذلك، أدوات الزينة لا حرج فيها إذا كانت طاهرةً وغير ضارَّةٍ؛ لا تضرّها: كالكحل، وما يُوضع في الشّفة من أنواع الحمرة، وما يُغسل به الوجه كله، إذا كان غير ضارٍّ لا بأس، إذا كان طاهرًا لا يضرّ، أما إذا كان يضرُّ الوجه أو يضرُّ البدن فلا تستعمله.\nوأما إذا كان يُجمّلها عند زوجها وعند بنات جنسها ولا يضرُّ فلا حرج، أما عند الرجال الأجانب فهذا لا يجوز، يجب عليها التستر والتَّحجب عن الأجنبي، وأخو الزوج من الأجانب، أخو الزوج وعمه وخاله كلهم أجانب يجب التَّحجب عنهم، وهكذا زوج الأخت، وزوج الخالة، وزوج العمَّة، كلهم أجانب يجب التَّستر عنهم، وإنما المحارم هم: أبو الزوج، ابن الزوج، زوج البنت، زوج بنت البنت، زوج بنت الابن، هؤلاء محارم، أما أخو الزوج وعمُّه وخاله فهؤلاء أجانب، وهكذا زوج الأخت، وزوج العمَّة، وزوج الخالة، أجانب.","link":"https://binbaz.org.sa/fatwas/3802/ما-حكم-ادوات-التجميل-التي-تستعملها-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0208.mp3","categories":["اللباس والزينة"]},{"id":206,"question":"ما الحكم في لبس الخاتم الفضَّة في اليد؟","title":"ما السُّنة في لبس الخاتم؟","answer":"الجواب: لبس الخاتم لا بأس به، سواء كان في اليمنى أو في اليسرى، والأفضل في الخنصر كما لبسه النبيُّ ﷺ والصحابة. أما خاتم الذهب فلا يجوز للرجال، وإنما هو للنساء، خاتم الذهب أو \"كرفتة\" من الذهب أو سلسلة من الذهب يُعلقها عليه؛ هذا لا يصلح للرجال، فالنبي ﷺ نهى عن خواتم الذهب للرجال، ولما رأى رجلًا في يده خاتمًا من ذهبٍ نزعه وطرحه وقال: يعمَد أحدُكم إلى جمرةٍ من النار فيضعها في يده.","link":"https://binbaz.org.sa/fatwas/3975/ما-السنة-في-لبس-الخاتم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0213.mp3","categories":["اللباس والزينة"]},{"id":222,"question":"ما وجهة نظركم في اللَّعب بسروالٍ قصيرٍ وخروج بعض الفخذ؟","title":"حكم لعب الرياضة بسراويل تكشف الفخذ","answer":"الجواب: اللعب بالسَّراويل القصيرة لا يجوز، قد تنازع العلماءُ في الفخذ: وهل هو عورة أو غير عورةٍ؟ والصواب أنه عورة، وقد جاءت في هذا عدةُ أحاديث تدل على أنَّه عورة، وهو وسيلةٌ إلى كشف العورة الكبرى، فالصواب في هذا أنَّ الفخذ عورة، وأنه لا يجوز اللعب بالسَّراويل القصيرة، لا الكرة، ولا غيرها.","link":"https://binbaz.org.sa/fatwas/4062/حكم-لعب-الرياضة-بسراويل-تكشف-الفخذ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0229.mp3","categories":["اللباس والزينة"]},{"id":246,"question":"ما حكم إظهار القدم والكفّين لغير المحارم؟ وما الدليل على ذلك؟","title":"حكم إظهار الكفين والقدمين لغير المحارم","answer":"الجواب: الحكم المنع؛ لعموم قوله جلَّ وعلا: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ، هذا يعمُّ بدنها كله، ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]، وقوله ﷺ: المرأة عورة، وهكذا قوله جلَّ وعلا: وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ الآية [النور:31].","link":"https://binbaz.org.sa/fatwas/4135/حكم-اظهار-الكفين-والقدمين-لغير-المحارم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0288.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":251,"question":"لقد قرأتُ مقالًا لأستاذٍ في جامعة الأزهر في مصر مضمونه أنَّ غطاء الوجه للمرأة أمرٌ اختياري، ليس بإلزامي، فما قولكم في ذلك؟","title":"ما الرد على حجج كشف المرأة وجهها؟","answer":"الجواب: أما ما يتعلق بالحجاب فقد تكاثرت أقوالُ أهل العلم في ذلك ما بين مُبيح وما بين مُحرّم، والأدلة الشرعية لمَن تأمَّلها واضحة في وجوب الحجاب والستر، وأن كشف المرأة وجهها ومحاسنها من أعظم الفتن، ومن أعظم أسباب ظهور الفواحش في البلاد، وقد صنَّف العلماء في ذلك رسائل وكتبًا مفيدةً، وبيَّن القرآنُ الكريم هذا المقام، وممن صنَّف في ذلك أبو العباس ابن تيمية وآخرون.\nالمقصود أنَّ الحجاب أمره مهمٌّ، وقد وقع في هذا العصر من الناس اضطرابٌ واختلافٌ ما بين مُبيح، وما بين محرّم، وقد يكون لكل واحدٍ وجهته وقصده الخير والطيب، ولكن كثيرًا من الناس يميل بهم الهوى إلى الإباحة والتَّساهل، وبعض الناس له نية صالحة وقصد صالح، ولكن هذا مبلغ اجتهاده، وهذا مبلغ علمه، فلا ينبغي للعاقل أن يتساهل في هذا الأمر.\nوالصواب أنَّ الواجب الحجاب على المرأة في وجهها وشعورها وبدنها؛ لأنها عورة، سمَّاها الرسولُ عورةً، ولأنها فتنةٌ، يقول النبيُّ ﷺ: ما تركتُ بعدي فتنةً أضرّ على الرجال من النِّساء، هكذا جاء في \"الصحيحين\"، فأمر النساء فتنة، والرجال مفتونون بالميل إلى النساء، والنظر إلى النساء، والنساء مفتونات بذلك، فالواجب البُعد عن الخطر، الواجب أخذ الحيطة، وأخذ الأسباب التي تمنع الخطر، وتحول بين الصّنفين من الوقوع فيما حرَّم الله، أو تُقلل ذلك، والله يقول جلَّ وعلا في كتابه العظيم: وَقَرْنَ فِي بُيُوتِكُنَّ وَلَا تَبَرَّجْنَ تَبَرُّجَ الْجَاهِلِيَّةِ الْأُولَى [الأحزاب:33]، قال أهل التفسير: التَّبرج: إظهار المحاسن والمفاتن، هذا هو التبرج، سُمِّي تبرُّجًا لإظهاره كمثابة الشيء القائم، البرج القائم الذي يُرى من بعيدٍ.\nفإظهارها المحاسن والمفاتن أمرٌ يضرُّها ويضرُّ مجتمعها، ويُسبب الفحشاء والمنكر، فإظهار الوجه، الوجه أعظم الزينة، وإذا كان معه الرأس مكشوفًا صارت الفتنة أكبر وأعظم.\nويقول جلَّ وعلا: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] فجعل الحجاب أطهر لقلوب الجميع، للذكور والإناث جميعًا، ومَن قال: إنَّ هذا خاصٌّ بالنساء بأزواج النبي ﷺ فلقد أبعد النُّجعة، وقد غلط؛ لأنه إذا كانت أزواج النبي ﷺ يُؤْمَرن بالحجاب مع تقواهنَّ وتقدمهنَّ في الخير، وكونهن في القمة في الخير، فغيرهن من باب أولى؛ لأنهن دونهن في هذا الباب، فإذا وجب على الأفضل الحجاب، فوجوبه للمفضول من باب أولى؛ لأنَّ الخطر عليه أكثر.\nوقد صح عن عائشة في \"الصحيحين\" رضي الله عنها أنها قالت في قصة الإفك لما سمعت صوت صفوان بن معطل يسترجع قالت: \"وكان قد رآني قبل الحجاب، فلما سمعتُ صوته خمّرتُ وجهي\"، فدلَّ ذلك على أنهم كانوا قبل الحجاب يكشفون الوجوه، وبعدما نزلت آيةُ الحجاب غطّوا وجوههم، تخمّروا؛ للبُعد عن الفتنة، وهل يُوجد شيء أعظم من الوجه؟! أي شيءٍ أعظم من الوجه؟! هو أعظم من اليد، وأعظم من القدم، وأعظم من الرأس، الوجه هو مجمع الزينة، يظهر منه جمالها أو دمامتها.\nفالواجب على النساء أن يتقين الله، وعلى أوليائهن أن يتَّقوا الله في الحجاب والبُعد عن السفور وعن أسباب الفتنة.\nومَن قال بالجواز فقد غلط، سواء كان حسن القصد أو بخلاف ذلك، مَن قال بالجواز فقد غلط ولم يُعطِ المقام حقَّه من النظر، بل وقف مع أشياء وفاتته أشياء.\nومَن قال: يجوز إذا كان بالعادة، ليس فيه تحسين، لا كحل، ولا كذا، ولا كذا، أما إذا كان فيه الكحل والتزين؛ حرم؛ فهذا شيءٌ لا ضابطَ له.\nومَن يقول: إن المرأة تجتنب هذا وتجتنب هذا، كل هذا شيءٌ لا وجه له، فالجمال لخِلقتها، سواء تحسنت بالكحل أو لم تتحسن بالكحل، فخِلقتها التي خلقها الله عليها من دمامةٍ أو جمالٍ هو المقصود، وإذا كان مع جمال الخِلقة المُزينات بالمكياج والكحل وغير ذلك؛ صارت الفتنةُ أعظم، وصار الفسادُ أكبر.\nفالحاصل أنَّ الواجب الاحتجاب والتَّستر والبُعد عن مظانِّ الفتنة، هذا هو الواجب في الوجه وغيره، هذا هو الواجب على النِّساء المؤمنات اللاتي يتقين الله ، وعليهنَّ أن يحذرن هذه الكتب وهذه المقالات التي تدعو إلى السُّفور، وتدعو إلى التحلل والتبرج، فإنها والله ضارَّة غير نافعةٍ، سواء حسن قصد فاعلها أو ساء قصد فاعلها، فمَن حسن قصده فالله يغفر له بما أخطأ فيه، وله أجر الاجتهاد، ومَن ساء قصده جمع الله له الشرين والذّنبين، ولا حول ولا قوة إلا بالله.","link":"https://binbaz.org.sa/fatwas/4242/ما-الرد-على-حجج-كشف-المراة-وجهها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0293.mp3","categories":["قضايا المرأة","ردود وتعقيبات","اللباس والزينة"]},{"id":274,"question":"سائلة تقول: لقد كثر في هذه الأيام التَّبرج والسُّفور من بعض فتياتنا هداهنَّ الله، وانتشر ما يُسمَّى بـ\"الحجاب الإسلامي\"، الذي أعتبره بداية النهاية للفضيلة -تقصد فيه كشف الوجه- حبَّذا لو تكرم سماحتكم ووجَّه نصيحةً إلى فتياتنا وإلى التَّنبيه من هذا الخطر القادم وفقكم الله.","title":"ما النصيحة تجاه مظاهر التبرج والسفور؟","answer":"الجواب: لا ريب أن التَّبرج من أقبح الخصال، ومن أشنع أمور الجاهلية، وهو من أعظم أسباب الفساد والفتنة للرجال بالنساء، والنساء بالرجال، والله يقول سبحانه: وَقَرْنَ فِي بُيُوتِكُنَّ وَلَا تَبَرَّجْنَ تَبَرُّجَ الْجَاهِلِيَّةِ الْأُولَى [الأحزاب:33].\nوالتَّبرج: هو إظهار المحاسن والمفاتن، والتَّكسر في القول، والخضوع في القول، كل هذا من أسباب الفتنة، ومن المُحرَّمات.\nوقد قال الله جلَّ وعلا في كتابه العظيم: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] فجعل إسدال الحجاب أطهر لقلوب الجميع، وليس للرجل أن يراها من دون حجابٍ، وأن يتَّصل بها إلا مع الحجاب إذا كان أجنبيًّا منها: كابن عمِّها، وابن خالها، وأخي زوجها، ونحو ذلك.\nوقال سبحانه: وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ الآية [النور:31]، ولا ريب أن شعرها ووجهها وبدنها كله من الزينة، فالواجب ستر ذلك والتَّحجب.\nوقال جلَّ وعلا أيضًا: يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلَابِيبِهِنَّ ذَلِكَ أَدْنَى أَنْ يُعْرَفْنَ فَلَا يُؤْذَيْنَ [الأحزاب:59].\nوأما ما يقوله بعضُ العلماء من أنَّ الوجه ليس بعورةٍ فهو قولٌ غلطٌ ومرجوحٌ، وبعضهم يُقيد إذا كان ما فيه تجميلٌ: لا بكحلٍ، ولا غيره، وكل هذه الأشياء لا وجهَ لها؛ فالوجه هو عنوان المرأة جمالًا ودمامةً، وهو سبب الفتنة عند ظهوره، وسبب جرأتها على التَّحدث مع الرجال، والجلوس مع الرجال.\nوبذلك قامت الأدلةُ على وجوب الحجاب، ووجوب ستر الوجه عن غير المَحْرَم، ومن ذلك ما تقدَّم من قوله سبحانه: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]، ولم يقل: إلا الوجه، وقال: وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ [النور:31]، ولم يقل: إلا الوجه، وقوله: إِلَّا مَا ظَهَرَ مِنْهَا [النور:31] في الآية قبلها يعني: الملابس الظاهرة، كما قال ابنُ مسعودٍ وغيره، وأما قول مَن قال: إنه الوجه والكفَّان، فهو قولٌ ضعيفٌ مرجوحٌ يُخالف الأدلة.\nوقد قالت عائشة رضي الله عنها: أنَّ الناس كانوا قبل الحجاب تُعرف وجوههم، أما بعد الحجاب فقد أُمِرْنَ بستر الوجه، ولهذا قالت -كما جاء في \"الصحيحين\"- أنَّ صفوان بن المعطل عرفها، وكان قد رآها قبل الحجاب: \"فلما سمعتُ صوتَه خمَّرْتُ وجهي، وكان قد رآني قبل الحجاب\".\nوقال عليه الصلاة والسلام: صنفان من أهل النار لم أرهما: رجال بأيديهم سياطٌ كأذناب البقر يضربون بها الناس، ونساء كاسيات عاريات، مائلات مُميلات، رؤوسهن كأسنمة البُخْت المائلة، لا يدخلون الجنةَ، ولا يجدون ريحها، وهذا يدل على تحريم التَّبرج وإظهار المحاسن: كالثياب القصيرة والرقيقة.\nوقوله: نساء كاسيات عاريات يعني: أنهن كاسيات في الاسم لا في الحقيقة، كاسيات بملابس قصيرة أو شفَّافة رقيقة، فهي كسوةٌ لا كسوة، كسوة معها عُري.\nمائلات مُميلات يعني: مائلات عن الحقِّ، وعن العِفَّة، مُميلات لغيرهنَّ.\nهذا يُوجب على المؤمن والمؤمنة أن يحذر كلٌّ منهما ما حرَّم الله عليه، وألا يتساهل المؤمنُ في هذا الباب مع زوجته، أو أخته، أو أمه، أو غير ذلك، وألا تتساهل هي مع زوج أختها، أو مع أخي زوجها، أو عمِّ زوجها، أو نحو ذلك.\nفالكل يجتهد في الحجاب والستر، حذرًا من الفتنة التي تترتب على كشف الحجاب، وعلى إبداء الزينة، وعلى إظهار المفاتن والمحاسن.","link":"https://binbaz.org.sa/fatwas/4271/ما-النصيحة-تجاه-مظاهر-التبرج-والسفور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0321.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":285,"question":"يأمر المسؤولون في المعاهد العلمية الطلاب بحلاقة رؤوسهم، وإبقاء الشعر سُنة، فما تعليق سماحتكم على ذلك؟","title":"حكم أمر الطلاب بحلق رؤوسهم","answer":"الجواب: الأمر في هذا واسعٌ، حلق الرأس ليس بواجبٍ؛ النبيُّ ﷺ كان يُربي رأسه، والصحابة كثيرٌ منهم يُربّون رؤوسهم، والحلق جائزٌ، والتربية مشروعةٌ في الجملة، لكن إذا كان القائمون على المعهد فعلوا ذلك لأسبابٍ شرعيةٍ؛ لئلا يفتن بالنساء، أو لئلا يكون وسيلةً للفتنة بالنساء، أو لأسبابٍ رأوها في مصلحة الطالب فلا بأس، هم أعلم بها، فإذا رأوا مصالح ورأوا أنَّ من المصلحة ذلك فليستجب، فإنَّ هذا من طاعة ولاة الأمور بالمعروف.","link":"https://binbaz.org.sa/fatwas/4283/حكم-امر-الطلاب-بحلق-رووسهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0332.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":292,"question":"فتاة تقول: أنا في الثانية والعشرين من العمر، أعيش مع أهل أمي عند أجدادي، ويعيش أيضًا في منزل الأجداد ثلاثٌ من أبناء خالتي، وتسأل عن الحجاب تقول: أخذتُ أصنع الحجابَ؛ لأنَّهم غير محارمٍ، فتحجَّبْتُ، وبعد فترةٍ سمعتُ عن غطاء الوجه، فسمعتُ أنه واجبٌ، والآخر يقول أنه ليس واجبًا، وعندما تضايق أهلُ بيتنا من ذلك وذلك بقولهم: أنَّهم أيتام، أين يذهبون؟ أو: أنت فعلت ذلك، فما الحكم في ذلك؟","title":"حكم حجاب المرأة المسلمة أمام المحارم","answer":"الجواب: الشيخ: نعم الواجب على المرأة الحجاب عن بني عمِّها وبني خالها وأبناء عمَّتها وخالتها، ليسوا محارم، فعليها أن تحتجب عنهم: شعرها ووجهها وبدنها؛ لأنَّهم ليسوا محارم، وهي فتنةٌ وعورةٌ، لكن إذا كانوا محارم -كالخال والعمّ- فلا بأس، أما ابن الخال وابن العمّ وابن العمّة وابن الخالة والجيران فليسوا محارم، فالواجب التَّحجب عنهم بغطاء الوجه وستر البدن.","link":"https://binbaz.org.sa/fatwas/4291/حكم-حجاب-المراة-المسلمة-امام-المحارم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0340.mp3","categories":["اللباس والزينة"]},{"id":307,"question":"ما حكم لبس الثوب القصير أمام المحارم، ولبس الكم القصير؟","title":"ما حكم لبس المرأة القصير أمام المحارم؟","answer":"الجواب: ينبغي للمرأة أن تستر جسمها، وتحذر التَّساهل، ولا تُبدي للمحرم إلا الشيء المعتاد: كالوجه، والكفين، والقدمين، هذا هو أسلم لها وخيرٌ لها.\nوقد اختلف العلماء فيما يجوز لها إبداؤه للمحرم: كثيرٌ من العلماء على أنها تُبدي له الوجه والكفّين، وبعضهم ذكر القدمين، وبعضهم ذكر الرأس.\nفالحاصل أنه ينبغي لها أن تتحفظ وتكتفي بالوجه والكفّين والقدمين، وإذا دعت الحاجة إلى ظهور شيءٍ من الرأس فلا بأس عند المحرم: كأخيها، وعمِّها، لكن التَّحرز في هذا العصر أولى، التَّحرز من بعض المحارم أولى؛ لأنَّ بعض المحارم معدوم الدين أو قليل الدين؛ فينبغي التَّحرز من هذا الأمر وقت الخلوة به، وأن تكون في غاية من التَّستر للشيء الذي قد يفتن، ويكفي الوجه والكفَّان عنده، ولا سيما مَن لا يُؤْمَن.","link":"https://binbaz.org.sa/fatwas/4310/ما-حكم-لبس-المراة-القصير-امام-المحارم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0357.mp3","categories":["اللباس والزينة"]},{"id":322,"question":"ما حكم وضع المكياج في الوجه في رمضان؟","title":"ما حكم وضع المرأة \"المكياج\" في رمضان؟","answer":"الجواب: المكياج: إن كان يضرُّ: يُسبب بقعًا في الوجه، أو سوءًا في الوجه؛ لم يجز، أما إن كان مثل الصَّابون ومثل غيره مما يُنوّر الوجه ولكن لا يضرّ الوجه، فلا يضرّ، ولو في الصيام، ولو في رمضان. أما إن كان يضرّ الوجه؛ لأنَّه بلغني أنَّ بعض المكياج يضرّ، كما تحصل بسببه بُقَعٌ وسوادٌ؛ هذا لا يجوز.","link":"https://binbaz.org.sa/fatwas/4403/ما-حكم-وضع-المراة-المكياج-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0374.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":327,"question":"ما حكم مَن تخرج من البيت لمدرستها وهي لم تضع طِيبًا، ولكن إذا دخلت مدرستها وضعت الطِّيبَ، وهي تجلس في المدرسة حوالي أربع ساعات؟","title":"حكم وضع الطِّيب للمرأة بحضرة النساء","answer":"الجواب: لا مانع من وضع الطِّيب وهي بين النساء، لا مانع من ذلك، وعند الخروج إذا كانت تخرج مع محرمها لا يضرُّ أيضًا.  أما إذا كانت تخرج مع سائقٍ ليس بمحرمٍ فينبغي لها في هذا أن تستعمل الطيب الذي يُرى، ولا تكون له رائحةٌ بينةٌ، فهذا رُوي عن النبي ﷺ أنه طِّيبها الذي ينبغي أن يغلب، وإن كان في سنده ضعفٌ. لكن ينبغي لها أن تُلاحظ هذا الشيء، لا تتعاطى الطِّيب في الطّرقات، ولا مع السائق الأجنبي، وإذا كانت تتعاطاه في نفس المدرسة، شيء خفيف حتى تزول قوته عند خروجها؛ فالأمر في هذا واسعٌ.","link":"https://binbaz.org.sa/fatwas/4415/حكم-وضع-الطيب-للمراة-بحضرة-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0380.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":374,"question":"يقول السائل: هل يجوز للمرأة أن تقصَّ شعرها، أو تضع عليه بعض الصباغ، وذلك تجمُّلًا لزوجها؟","title":"حكم قص المرأة لشعرها وصبغه","answer":"الجواب: قص الشعر يختلف: إن كان بقصد التَّشبُّه بأعداء الله فلا يجوز، التَّشبه بالكافرات لا يجوز، أما إذا كان على سبيل التَّخفيف والجمال برضا من زوجها ومُوافقة من زوجها؛ فلا بأس بتخفيف الشعر.\nوأما الأصباغ فلا مانع من الصبغ بغير السواد، أما السواد فلا يجوز؛ النبي عليه الصلاة والسلام قال: غيِّروا هذا الشَّيب، وجنِّبوه السواد، فالنَّهي عن الصبغ بالسواد هو المشهور عن النبي ﷺ، أما بالأحمر أو بالأصفر فلا بأس في ذلك.","link":"https://binbaz.org.sa/fatwas/4633/حكم-قص-المراة-لشعرها-وصبغه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0430.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":420,"question":"في التلفزيون تُعرض المصارعة أمام النساء، وعورة المصارعين واضحة أمامهنَّ، فما رأي سماحتكم في ذلك؟","title":"حكم ظهور العورة في رياضة الرجال","answer":"الجواب: لا يجوز عرض ما تبدو فيه العورات: لا في المصارعة، ولا في المسابقات: كرة القدم، ولا في غيرها، كل لعبٍ تظهر فيه العورات أو تضيع فيه الصَّلوات لا يجوز حضوره. أما إذا كانت تُحفظ فيه العورات، ولا يُرتكب فيه محرم، ولا تضيع فيه الصَّلوات؛ فالأمر سهل. لكن إذا كان في المصارعة ظهور العورة؛ حَرُم على الرجال والنساء جميعًا، وهكذا في مباريات القدم إذا ظهرت العورات والأفخاذ؛ حَرُم ذلك على الجميع، وإذا ترتب على هذا إضاعة الصلاة في وقتها أو في الجماعة؛ حَرُم على الجميع -نسأل الله الهداية.","link":"https://binbaz.org.sa/fatwas/4844/حكم-ظهور-العورة-في-رياضة-الرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0478.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":446,"question":"بما يُزال الشيب؟ وما حكم تغيير الشيب بالكتم أو الحناء؟","title":"حكم إزالة الشيب وتغييره","answer":"الجواب: الشيب لا يُزال، نهى النبي ﷺ عن نتف الشيب، لكن يُغيَّر بالصُّفرة والحُمرة، وكذلك ما بين السواد والحُمرة ولا يُغيَّر بالسواد، النبي ﷺ قال: غيروا هذا الشيب واجتنبوا السواد السُّنة يُغيَّر بالحناء والكتم أو بغير ذلك من أنواع الصبغ، إلا السواد الخالص لا.\n(دروس شرح بلوغ المرام، كتاب البيوع)","link":"https://binbaz.org.sa/fatwas/6156/حكم-ازالة-الشيب-وتغييره","audio":"https://files.zadapps.info/binbaz.org.sa/sab3'004.mp3","categories":["اللباس والزينة"]},{"id":510,"question":"هل الساعات التي لونها أصفر يشبه الذهب يجوز لبسها، أفيدونا جزاكم الله خيرًا؟","title":"حكم لبس ساعات لونها أصفر يشبه الذهب","answer":"الجواب: إن كانت ذهبًا ما يجوز إلا للنساء خاصة.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6340/حكم-لبس-ساعات-لونها-اصفر-يشبه-الذهب","audio":"https://files.zadapps.info/binbaz.org.sa/maram75 - 01 -  Start.mp3","categories":["اللباس والزينة"]},{"id":527,"question":"ورد في بعض الأحاديث أنه نهى عن لبس الحديد؛ لأنه حلية أهل النار؟","title":"ما حكم لبس الحلية من الحديد؟","answer":"الجواب: لا، هذا الحديث..... دل على جواز لبس الحديد، السيف حديد يلبسونه، و....... الأحاديث في النهي عن الحديد ضعيفة، وإن صححها بعض الناس فهي ضعيفة.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6358/ما-حكم-لبس-الحلية-من-الحديد","audio":"https://files.zadapps.info/binbaz.org.sa/maram093 - 04 - .mp3","categories":["اللباس والزينة"]},{"id":563,"question":"زينة النساء كوضع أحمر الشفاة ما يدخل في الواشمة؟","title":"حكم وضع المرأة لأحمر الشفاه","answer":"الجواب: ما فيه شيء، هذا من زينة النساء، لكن عليها التستر عن الأجنبي، أما مع زوجها ومع النساء لا بأس.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6394/حكم-وضع-المراة-لاحمر-الشفاه","audio":"https://files.zadapps.info/binbaz.org.sa/maram129 - 02 - .mp3","categories":["اللباس والزينة"]},{"id":564,"question":"أكثر زينة النساء في الوقت الحاضر قدمت من الغرب مثل تسريحات الشعر وطرق اللباس؟","title":"ما الضابط في التشبه بلباس الكفار؟","answer":"الجواب: إذا صار عادة للمسلمين ما هو تشبه، التشبه في الشيء الذي يختصون به دون المسلمين. أما إذا كان يفعله المسلمون ما يصير \"تشبه\"، يصير مشتركًا، مثل ركوب السيارة والطائرة.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6395/ما-الضابط-في-التشبه-بلباس-الكفار","audio":"https://files.zadapps.info/binbaz.org.sa/maram130 - 02 - .mp3","categories":["اللباس والزينة"]},{"id":565,"question":"الجراحة الحديثة لزراعة الشعر؟","title":"ما حكم زراعة الشعر؟","answer":"الجواب: إذا كان للتداوي ما هو داخل في هذا، إذا كان للتداوي ما هو للعبث أو الزينة أو التشبه بأعداء الله، هذا للتداوي.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6396/ما-حكم-زراعة-الشعر","audio":"https://files.zadapps.info/binbaz.org.sa/maram131 - 02 - .mp3","categories":["الطب والتداوي","اللباس والزينة"]},{"id":641,"question":"الصلاة مضطبعًا؟","title":"ما حكم صلاة المضطبع؟","answer":"الجواب: يصح؛ لأن أحد العاتقين مستور، لكن أن يستر العاتقين أوْلى.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6577/ما-حكم-صلاة-المضطبع","audio":"https://files.zadapps.info/binbaz.org.sa/maram209 - 03 - .mp3","categories":["ستر العورة للمصلي","اللباس والزينة"]},{"id":645,"question":"س: إن صلى مكشوف العاتقين؟","title":"حكم صلاة من عاتقاه مكشوفان","answer":"الجواب: فيه نظر، ينبغي له أن يعيد؛ لقوله ﷺ: لا يصلي أحدكم في ثوب واحد ليس على عاتقه منه شيء وفي اللفظ الآخر: ليس على عاتقيه منه شيء متفق على صحته، فينبغي له أن يستر عاتقيه أو أحدهما على الأقل إذا قدر. أما إذا كان ما عنده شيء فاتقوا الله ما استطعتم.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6675/حكم-صلاة-من-عاتقاه-مكشوفان","audio":"https://files.zadapps.info/binbaz.org.sa/maram213 - 03 - .mp3","categories":["ستر العورة للمصلي","اللباس والزينة"]},{"id":761,"question":"السلام عليكم ورحمة الله وبركاته، وبعد: نريد من سعادتكم أن تُخبرونا بأحكام الأمور الآتية:أولًا: إسبال الثياب.ثانيًا: حلق اللِّحى.ثالثًا: إطالة الشَّوارب.جزاكم الله عنا خيرًا.","title":"حكم الإسبال وحلق اللحى وإطالة الشوارب","answer":"الجواب: ثبت عن رسول الله ﷺ في هذه المسائل الثلاث ما يدل على تحريمها والتَّحذير منها: فقال عليه الصلاة والسلام: ثلاثةٌ لا يُكلِّمهم الله، ولا ينظر إليهم يوم القيامة، ولا يُزَكِّيهم، ولهم عذابٌ أليمٌ: المسبل إزاره، والمنَّان بما أعطى، والمُنَفِّق سلعته بالحلف الكاذب، وقال عليه الصلاة والسلام: ما أسفل من الكعبين من الإزار فهو في النار رواه البخاري في \"الصحيح\".\nفهذا يُبين لنا أن الإسبال محرَّمٌ، وأنَّ فيه الوعيد، وما ذاك إلا لأنه وسيلة للتَّكبر والتَّعاظم، ولأنه إضاعة للمال، وإفساد له، وإسراف، ولأنه وسيلةٌ إلى تلطخه بالنَّجاسات والأوساخ، فهو محرَّمٌ من وجوهٍ كثيرةٍ:\nمنها: أنَّ الله جلَّ وعلا بيَّن تحريمه على لسان نبيه عليه الصلاة والسلام.\nومنها: أنه من الإسراف، والله حرَّم الإسراف.\nومنها: أنه وسيلةٌ إلى التَّكبر والتَّعاظم لمن جرَّه لغير هذا القصد، فإنه وسيلةٌ إلى تعاظمه وتكبُّره على إخوانه، والغالب على مَن جرَّ ثوبه التَّكبر، ولهذا قال عليه الصلاة والسلام: مَن جرَّ ثوبَه خُيلاء لم ينظر الله إليه يوم القيامة، فمع الخُيلاء صار أعظم وأكبر.\nأما ما قد يقع من انفلات الثوب وانطلاق خمنته وهو لا يُريد التَّكبر ولا يرضى بالإسبال، بل يتعاهد ثوبه ويرفعه، ولكن قد ينحلّ في بعض الأحيان، ثم يتعاهده ويرفعه؛ ما يضرُّه هذا، لكن مَن يُطلقه عمدًا ويسحبه عمدًا فهذا قد تعمَّد الإسبال، فقد تعرض لغضب الله في هذا ووعيده، ولهذا قال عليه الصلاة والسلام: إياك والإسبال، فإنه من المخيلة، سماه \"مخيلةً\" يعني: أنه من الكبر، وإن زعم صاحبُه أنه ما أراد الكبر، مع ما فيه من إضاعة المال، وإفساد الملابس بالوسخ والنَّجاسة، ومع ما فيه من الإسراف.\nوأما قصّ اللِّحى وحلقها وإطالة السّبالات -وهي الشَّوارب- فقد نبَّه النبيُّ على هذا عليه الصلاة والسلام، وبيَّن حُرمة ذلك، فقال عليه الصلاة والسلام: قصُّوا الشَّوارب، وأعفوا اللِّحَى، خالفوا المشركين متفق عليه في \"الصحيحين\"، وقال عليه الصلاة والسلام: قصُّوا الشوارب، ووفروا اللِّحَى رواه البخاري في \"صحيحه\"، وقال: جزوا الشَّوارب، وأرخوا اللِّحى، خالفوا المجوس رواه مسلم في \"صحيحه\"، وقد جمع ﷺ بين جزِّ الشَّوارب وقصّها، وبين إكرام اللِّحى وإرخائها وتوفيرها، هذا هو الواجب.\nولا ينبغي لعاقلٍ أن يغترَّ بالناس ويقول: الناس فعلوا! فإنَّ مَن قلَّد الناس وقع في المعاطب، فالناس فيهم المشرك والكافر، وفيهم الفاسق، وفيهم الظالم، وفيهم العاقّ لوالديه، وفيهم المرابي، إلى غير هذا، فمَن قلَّد الناسَ وتابعهم هلك.\nفالواجب الحذر، الواجب أن يحذر، وألا يتأسَّى بالناس في الباطل، إذا كنتَ مُتأسيًا فعليك بالتأسي بأهل الحقِّ والاستقامة، لا بأهل الباطل، الرسول ﷺ هو أولى بالتأسي، قال الله : لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ [الأحزاب:21]، وقال ﷺ: مَن رغب عن سُنتي فليس مني، وهكذا أصحابه بعده  وأرضاهم هم قدوة المؤمنين وأسوتهم، فلا يجوز للمؤمن أن يحيد عن سبيل الاستقامة إلى سبيل النَّدامة والانحراف، والله المستعان.","link":"https://binbaz.org.sa/fatwas/20683/حكم-الاسبال-وحلق-اللحى-واطالة-الشوارب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0584حكم اسبال الثياب وحلق اللحى واطالة الشوارب؟ ابن باز فتاوى المحاضرات.mp3","categories":["اللباس والزينة","سنن الفطرة"]},{"id":786,"question":"ما حكم إزالة المرأة للشعر الذي على يديها ورجليها بالمُزيل أو غيره؟","title":"حكم إزالة المرأة لشعر اليدين والرجلين","answer":"الجواب: لا نعلم فيه شيئًا، هذا مما سكت الله عنه، فلا حرج في إزالة شعر اليدين والرجلين، وهكذا لو نبتت لها لحيةٌ أو شارب، فإن هذا مُثلة يُشوّهها، فلا مانع من إزالة ذلك، إنما المنكر إزالة الحاجبين، أو الشعر المعتاد في الوجه، هذا يُمنع؛ لأنه من النَّمص، والرسول ﷺ لعن النَّامصة.","link":"https://binbaz.org.sa/fatwas/20790/حكم-ازالة-المراة-لشعر-اليدين-والرجلين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0620ما حكم إزالة المرأة لشعر اليدين والرجلين؟ ابن باز فتاوى المحاضرات.mp3","categories":["اللباس والزينة"]},{"id":789,"question":"هل لبس اللون الأبيض للنساء تشبّه بالرجال؟ أفيدونا جزاكم الله خيرًا.","title":"هل لبس اللون الأبيض للنساء تشبّه بالرجال؟","answer":"الجواب: إذا كان على صفة لبس الرجال صار تشبُّهًا، وإذا كان بكيفيةٍ أخرى لا يفعلها إلا النّساء ما يكون تشبُّهًا، التَّشبه يكون بالصِّفة التي يفعلها الرجالُ، حتى ولو بالأحمر، حتى ولو بالأسود، لو لبست جُبَّةً سوداء من جنس لبس الرجال؛ حَرُم عليها، أو جبَّة حمراء من جنس لبس الرجال؛ حَرُم عليها.\nفلا بد أن يكون لباسها متميزًا لا يُشابه الرجال، سواء كان اللباسُ أسود أو أحمر أو أخضر أو أبيض أو غير ذلك. لكن الأبيض الخالص الذي اعتاده الرجالُ ينبغي لها ألا تلبسه؛ لأنه في الظاهر فيه نوعٌ من التَّشبه، لكن إذا غُيّر في تفصيله وكيفيته على كيفيةٍ تختصّ بها النساء لم يكن تشبُّهًا: كالأحمر والأسود.","link":"https://binbaz.org.sa/fatwas/20787/هل-لبس-اللون-الابيض-للنساء-تشبه-بالرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0617هل لبس اللون الأبيض للنساء تشبه بالرجال؟ ابن باز فتاوى المحاضرات.mp3","categories":["اللباس والزينة"]},{"id":790,"question":"هل لبس القفازين للمرأة بدعة؟ أرجو الإفادة.","title":"ما حكم لبس القفازين للمرأة؟","answer":"الجواب: لا بأس بالقفازين؛ لأنها تستر الكفَّين عن الأجانب، إلا في الإحرام، إذا كانت مُحْرِمَةً فلا تلبس القفازين، لا في عمرةٍ، ولا في حجٍّ، حتى تحلّ من إحرامها، كما أنها لا تلبس النِّقاب في الإحرام حتى تحلّ من إحرامها، لكن تُغطي وجهها وتُغطي كفَّيها بغير النقاب وبغير القفازين، في حال الإحرام، تُغطي بعباءةٍ، تتحجَّب بشيءٍ من حجابها، بخمارها.","link":"https://binbaz.org.sa/fatwas/20785/ما-حكم-لبس-القفازين-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0616هل لبس القفازين للمرأة بدعة؟ ابن باز فتاوى المحاضرات.mp3","categories":["اللباس والزينة"]},{"id":791,"question":"ما حكم تطويل الأظفار ولبس الثوب نصف الكمّ للمرأة؟ وما حكم قصّ الشعر؟","title":"حكم تطويل الأظفار ونصف الكم للمرأة","answer":"الجواب: الرسول ﷺ أمر في قصِّ الشارب وفي الإبط والأظفار والعانة: ألا يُترك ذلك أكثر من أربعين ليلة، قال أنس: \"وقَّت لنا في قصِّ الشارب وقلم الأظفار ونتف الإبط وحلق العانة ألا نترك ذلك أكثر من أربعين ليلة\"، فإذا بقي الظفرُ أقلَّ من أربعين، أو الشَّارب، أو العانة، أو الإبط، فلا حرج، ولا يجوز أن يبقى أكثر من ذلك.\nوإن طوّلت أظفارها بقصد التَّشبه بالكفرة صار محرَّمًا بهذا القصد، إذا طوّلت أظفارها أو فعلت شيئًا لقصد التَّشبه بالكافرات هذا لا يجوز: مَن تشبَّه بقومٍ فهو منهم.\nوأما لبس الكم القصير بين النساء فلا بأس، لكن بين الرجال الأجانب لا، أما عند النساء فلا بأس، لكن ينبغي لها أن تعتاد الطويل، حتى لا تعتاد القصير؛ لأنها إذا اعتادت القصيرَ قد تبرز به عند أخي زوجها، أو عند خادمها، أو عند سائقها، قد تتساهل، فالأولى بها أن تعتاد الكم الطويل والثياب الطويلة، حتى إذا خرجت إلى هنا أو هنا فإذا هي في ملابس ضافية وكافية.\nوالسنة للمُؤمنة أن تكون ثيابُها طويلةً، تُغطي أقدامَها شبرًا إلى ذراعٍ، أو عليها جوارب في رجليها تسترها، والكمّ يكون طويلًا يُغطي ساعدها كله إلى رسغها، وإذا كان عندها أجنبيٌّ سترت كفَّيها، كما تستر وجهها أو بدنها. أما بين النِّساء فالأمر في هذا واسعٌ، لكنه يُخشى أن تعتاده، فلهذا قلنا: إنَّ الأولى بها ألا تعتاد ذلك ولو عند النساء، حتى لا تفعله عند غيرهن.","link":"https://binbaz.org.sa/fatwas/20784/حكم-تطويل-الاظفار-ونصف-الكم-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0615حكم تطويل الأظفار ولبس الثوب نصف الكم للمرأة؟ ابن باز فتاوى المحاضرات.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":827,"question":"هنالك مَن أفتى بحُرمة قصِّ شعر رأس المرأة، فما القول الراجح في هذه المسألة؟","title":"ما القول الراجح في قص شعر المرأة؟","answer":"الجواب: رأسها جمال، والأوْلى تركه؛ لأنه جمال، لكن لو قصَّت منه أو خفَّفتْ منه؛ فلا حرج في ذلك فيما نعلم، ولا نعلم دليلًا يمنع ذلك، إنما الممنوع الحَلْق على الصحيح.\nقصّ رأس المرأة تقدَّم أن الأوْلى والأفضل الاستفادة منه؛ لأنه جمال وزينة، حتى قال بعضُ أهل العلم: إنَّ الأخذ منه مُثْلَةٌ، ولكن ليس هناك دليلٌ ظاهرٌ على التحريم، بل يجوز القص للتَّخفيف.\nوقد ثبت أنَّ أمهات المؤمنين رضي الله عنهن بعد وفاة النبي ﷺ جَزَزْنَ من رؤوسهنَّ للتَّخفيف.\nولكن ينبغي أن يُلاحظ ألا يكون ذلك على سبيل التَّشبه بالكافرات، أو التَّشبه بالرجال، فلا يجوز أن تقصد المرأة التَّشبه بالرجال في شيءٍ، أو بالكافرات في شيءٍ، كما قال عليه الصلاة والسلام: لعن الله المرأة تلبس لبس الرجل، ولعن الله الرجل يلبس لبس المرأة، ولعن المتشبِّهين من الرجال بالنساء، والمتشبِّهات من النساء بالرجال، وقال: مَن تشبَّه بقومٍ فهو منهم، فلا بدّ من كون القصِّ على وجهٍ لا يتضمن مُشابهةً للنساء الكافرات، ولا للرجال، والله المستعان.","link":"https://binbaz.org.sa/fatwas/20864/ما-القول-الراجح-في-قص-شعر-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0659ما هو القول الراجح في قص شعر المراة؟ ابن باز فتاوى المحاضرات.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":875,"question":"يستدل بعضُ العلماء على عدم وجوب النِّقاب للمرأة بما يلي فما رأيكم؟قُلْ لِلْمُؤْمِنِينَ يَغُضُّوا مِنْ أَبْصَارِهِمْ [النور:30]، إنه يقول: غضّ البصر يكون على هذا، إذا كانت المرأة مُغطاة جميعًا ولا أن تبدل ببعض.....؟","title":"هل الأمر بغض البصر دليل على نفي وجوب النقاب؟","answer":"الجواب: المقصود أنَّ هذا يحتج به مَن يقول: إنَّ الحجاب ليس بلازمٍ؛ لأنه إذا كانت مُتحجبةً كيف يغضّ البصر عنها؟ ما دامت مستورة كيف يغضّ البصر عنها؟\nوالجواب عن هذا: أنَّ المرأة قد لا تغض قد لا تحتجب، قد تتساهل، قد يُصادفها في وقتٍ ما احتجبت فيغضّ بصره، ولهذا لما سُئل النبيُّ ﷺ عن نظر الفجأة قال: اصرف بصرك، قد تبدو من بابٍ، أو من سكةٍ، ما عندها أحد، كاشفة، فيُصادفها، فيغضّ بصره، النبي عليه الصلاة والسلام قال: اصرف بصرك، وقال لعليٍّ: إنَّ لك الأولى، وليس لك الأخرى يعني: الأولى التي صادفتها صدفةً، والأخرى التَّعمد، ليس له التَّعمد والنَّظر.\nفلا يلزم من الأمر بغضّ البصر أن تكون مكشوفةً، وأن يكون جائزًا لها الكشف، ولكن متى تساهلت أو صادفها في وقتٍ ما درت عنه لم تستعد للحجاب غضَّ بصره، والله يقول سبحانه: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]، ولم يقل: إلا الوجه، قال: فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ، ثم بيَّن أنَّ هذا أطهر لقلوب الجميع، وأبعد عن نجاسة الفاحشة.\nوقال جلَّ وعلا في كتابه العظيم في الآية الأخرى: وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ [النور:31] إلى آخره، والتي قبلها: إِلَّا مَا ظَهَرَ مِنْهَا، فسره ابنُ مسعودٍ بأنه الملابس الظاهرة، أما تفسيره بأنه الوجه واليدان فليس عليه دليلٌ، كما يُروى عن ابن عباسٍ وجماعة، وقال آخرون: مراد ابن عباس وجماعة قبل الحجاب، كانت المرأة تُبدي وجهها وأطرافها قبل الحجاب، ثم نُسخ ذلك، وأُمِرْنَ بالحجاب؛ ولأن أعظم ما في المرأة من الزينة الوجه، هذا أعظم زينتها، أو الدَّمامة، هو الدليل على دمامتها وعلى جمالها وزينتها، فإذا أبدت الوجهَ فما بقي؟!","link":"https://binbaz.org.sa/fatwas/20895/هل-الامر-بغض-البصر-دليل-على-نفي-وجوب-النقاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0690الرد على من يقول أن الحجاب ليس بلازم لأن إذا كانت متحجبة فما الفائدة من عض البصر؟ ابن باز.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":879,"question":"ما حكم قصّ السّبالين؟","title":"ما حكم قصّ السّبالين (طرفي الشوارب)؟","answer":"الجواب:\n\nواجب، الرسول عليه الصلاة والسلام قال: قصّوا الشوارب، قصّوا السبالات، وهي أطراف الشَّوارب، لا يفتلها ليطولها، لكن يجوز تركها أقلّ من أربعين ليلة، قال أنسٌ : \"وقَّت لنا في قصّ الشارب وقلم الظفر ونتف الإبط وحلق العانة ألا نترك ذلك أكثر من أربعين ليلةً\" رواه مسلم في \"صحيحه\"، فإذا تركها إلى هذه المدة فلا حرج، ولكن الأفضل أن يتعاهده قبلها، فإذا تمت المدةُ وجب عليه القصّ.\nوهكذا حلق العانة، ونتف الإبط، وقلم الأظفار، لا يزيد على أربعين ليلةً، بل يُلاحظ ذلك، ويعتني به قبل الأربعين.\nوهذا في الرجل والمرأة جميعًا، عامٌّ للرجال والنساء: نتف الإبط، وحلق العانة، وقلم الأظفار للجميع، أما قصّ الشارب فمعلومٌ أنه تبع الرجال.\nأما اللحية فالواجب إكرامها وإعفاؤها وتوفيرها وإرخاؤها، كما أمر به النبيُّ ﷺ، وليس لأحدٍ أخذها، لا جندي، ولا غير جندي، الواجب إعفاؤها، كما قال ﷺ: قصُّوا الشوارب، وأعفوا اللحى، قصُّوا الشوارب، ووفِّروا اللِّحى، قصوا الشَّوارب، وأرخوا اللحى، خالفوا المجوس، خالفوا المشركين، هكذا ثبت عنه عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/20922/ما-حكم-قص-السبالين-طرفي-الشوارب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0717ما حكم قص السبالين؟ ابن باز فتاوى المحاضرات.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":898,"question":"ما حكم قصّ الشعر بالنسبة للمرأة؟ هل هو حرامٌ أم لا؟","title":"ما حكم قصّ الشعر بالنسبة للمرأة؟","answer":"الشيخ: قصُّ الشعر فيه تفصيل: إذا كان عن رضا والديها وزوجها -إن كان لها زوجٌ- على وجهٍ ما فيه تشبُّه بالكافرات، وإنما المقصود التَّخفيف والزينة فلا بأس، وقد قصَّ أزواجُ النبي ﷺ رؤوسهنَّ بعد وفاته ﷺ للتَّخفيف.\nأما إذا كان لقصد التَّشبه بالكافرات، أو التَّشبه بالرجال، أو لمقاصد سيئة؛ هذا لا يجوز، أو لعصيان الزوج، أو لعصيان الوالدين، لا يجوز، لكن إذا كان باتِّفاقٍ مع الوالدين، أو مع الزوج -إن كان لها زوجٌ- على وجهٍ ما فيه تشبُّه بالكافرات، فيه مصلحة وزينة، بدون تشبُّهٍ بالكافرات؛ فلا بأس، ولا تشبّه بالرجال.","link":"https://binbaz.org.sa/fatwas/20928/ما-حكم-قص-الشعر-بالنسبة-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0724ما حكم قص الشعر بالنسبة للمرأة؟ ابن باز فتاوى المحاضرات.mp3","categories":["اللباس والزينة"]},{"id":935,"question":"ما حكم تعليق اللَّوحات التي بها آيات قرآنية وأحاديث نبوية وتُوضع على جدران المنازل والمحلّات؟","title":"حكم تعليق لوحات الآيات بالمنازل والمحلّات","answer":"الجواب: لا نعلم فيها شيئًا إذا كانت آيات وأحاديث صحيحة. أما المساجد فلا يُعلَّق فيها شيءٌ؛ لأنها تشغل المصلين، ولا يُكتب في جدرانها، أما مكتبه أو مجلسه ما نعلم فيها شيئًا.","link":"https://binbaz.org.sa/fatwas/20978/حكم-تعليق-لوحات-الايات-بالمنازل-والمحلات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0774ما حكم تعليق اللوحات التي بها آيات وأحاديث وتوضع على جدران المنازل والمحلات؟ ابن باز.mp3","categories":["القرآن وعلومه","اللباس والزينة"]},{"id":974,"question":"ما حكم لبس ساعة بها صفائح من الألماس بالنسبة للرجل، مع أنه ليس يقصد الكبرياء بلبسها؟","title":"ما حكم لبس الرجل ساعة بها ألماس؟","answer":"الجواب: الماس ليس من الذهب، ولا من الفضة، معدنٌ آخر، فلا أعلم فيه شيئًا، لكن إذا ترك ذلك من باب التَّواضع والخضوع لله والخوف من الإسراف فهذا حسنٌ إن شاء الله، وإلا ما أعلم فيه شيئًا. إنما الممنوع أن يلبس ذلك من الفضة أو الذهب، أما الماس فلا نعلم فيه شيئًا؛ لأنه معدنٌ آخر، ولكن تركه من باب التواضع، ومن باب الحذر من أن يُوصَف بالإسراف أو التَّبذير، ويكفيه الساعة العادية التي يلبسها الناس. أما في حقِّ النساء فالأمر أسهل ولا حرج.","link":"https://binbaz.org.sa/fatwas/21008/ما-حكم-لبس-الرجل-ساعة-بها-الماس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0805ما حكم لبس ساعة بها صفائح من الألماس بالنسبة للرجل؟ ابن باز فتاوى المحاضرات.mp3","categories":["اللباس والزينة"]},{"id":992,"question":"هل يجوز للمرأة أن تقصَّ شعرها أو تقصَّ شيئًا منه؟","title":"هل يجوز للمرأة قصَّ شعرها أو جزء منه؟","answer":"الجواب: لها أن تقص شيئًا من شعرها إذا أرادت بذلك التَّخفيف أو الجمال، وإذا كان لها زوجٌ وافق على ذلك زوجها، من دون قصد التَّشبه بالكافرات، بقصد التزين والتَّجمل لزوجها، أو لأنه صار عُرْفًا لبلادها، من غير تشبُّهٍ بالكافرات؛ فلا بأس، فليس في السنة ما يدل على تحريم القصّ، وقد ثبت أنَّ أمهات المؤمنين -زوجات النبي ﷺ- بعد وفاته قصصن شعورَهنَّ للراحة من بعض التَّكلُّف.","link":"https://binbaz.org.sa/fatwas/21044/هل-يجوز-للمراة-قص-شعرها-او-جزء-منه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0840هل يجوز للمرأة أن تقص شعرها أو تقص شيئاً منه؟ ابن باز فتاوى المحاضرات.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":1003,"question":"إني أحبُّكم في الله، كثيرٌ من الناس يتهاونون في السنة: كحلق اللحية، وتطويل الثياب، نطلب التَّوجيه، جزاكم الله خيرًا.","title":"ما النصيحة تجاه التهاون بالإسبال واللحية؟","answer":"الجواب: أولًا: أحبَّك الله الذي أحببتنا له، والتَّحابُّ في الله من أفضل القربات، بل من الواجبات، وقد قال عليه الصلاة والسلام في الحديث الصحيح: سبعة يُظلهم الله في ظلِّه يوم لا ظلَّ إلا ظله: إمام عادل، وشابٌّ نشأ في عبادة الله، ورجلٌ قلبه مُعلَّقٌ بالمساجد، ورجلان تحابَّا في الله، اجتمعا على ذلك، وتفرَّقا عليه، ورجلٌ دعته امرأةٌ ذات منصبٍ وجمالٍ فقال: إني أخاف الله ومثله امرأةٌ دعاها ذو منصبٍ وجمالٍ فقالت: إني أخاف الله، والسادس: رجلٌ تصدَّق بصدقةٍ فأخفاها، حتى لا تعلم شمالُه ما تُنْفِق يمينه، والسابع: رجلٌ ذكر الله خاليًا –يعني: ما عنده أحدٌ- ففاضت عيناه بكاءً من خشية الله عزَّ وجل.\nوقال أيضًا عليه الصلاة والسلام: يقول الله يوم القيامة: أين المتحابُّون بجلالي؟ اليوم أظلهم في ظلي يوم لا ظلَّ إلا ظلي، والتَّحاب في الله يقتضي التَّعاون على البر والتقوى، ويقتضي التَّناصح والأمر بالمعروف والنَّهي عن المنكر، هكذا يكون المتحابُّون في الله.\nأما ما يتعلق بإعفاء اللِّحى وإسبال الثياب: فهذه أمورٌ واجبة، ليست مجرد سنةٍ في اصطلاح مَن يرى أنَّ السنة يُثاب فاعلها ولا يُعاقَب تاركها، بل إعفاء اللحية من الواجبات، وأخذها من المحرَّمات، والإسبال من المحرمات، فلا يجوز للمؤمن حلق لحيته ولا قصّها، بل يجب إعفاؤها وإكرامها وتوفيرها، قال عليه الصلاة والسلام: قصُّوا الشَّوارب، وأعفوا اللحى، خالفوا المشركين، وقال عليه الصلاة والسلام: قصُّوا الشوارب، ووفروا اللِّحى، خالفوا المشركين، وقال عليه الصلاة والسلام: جزُّوا الشَّوارب، وأرخوا اللِّحى، خالفوا المجوس، فالواجب إعفاؤها وإكرامها وإرخاؤها، وإن قصَّها الناسُ لا تكن مع الناس، كن مع الحقِّ، ولو كنتَ وحدك، لو كان أهلُ قريةٍ أو قبيلةٍ قد قصُّوا أو حلقوا لا تكن معهم، الزم الحقَّ ولو كنتَ وحدك.\nوهكذا جرُّ الملابس، الملابس حدُّها الكعب للرجل، فما أسفل من الكعبين يجب تركه، ويحرم فعله، يقول عليه الصلاة والسلام: ما أسفل من الكعبين من الإزار فهو في النار رواه البخاري في \"الصحيح\"، ويقول ﷺ: إياك والإسبالَ، فإنه من المخيلة، ويقول عليه الصلاة والسلام: ثلاثةٌ لا يُكلِّمهم الله ولا ينظر إليهم يوم القيامة ولا يُزكّيهم، ولهم عذابٌ أليم: المسبل إزاره، والمنَّان بما أعطى، والمُنَفِّق سلعتَه بالحلف الكاذب رواه مسلم، وما ذاك إلا لأنَّ الإسبال يُعطي دلالةً على التَّكبر والتَّعاظم، مع ما في ذلك من الإسراف وإفساد الثياب بالأوساخ والنَّجاسات.\nومَن زعم أنه يجوز إذا كان على غير تكبرٍ؛ فقد غلط، فالرسول نهى وعمَّم عليه الصلاة والسلام، وتوعَّد على ذلك، وجعل الإسبالَ من المخيلة، ثم القلوب لا يعلمها إلا الله، مَن أسبل فقد تظاهر بظاهر الكِبر؛ فوجب منعه والإنكار عليه.\nوأما ما جاء في حديث ابن عمر: أنَّ الصديق  لما سمع قوله ﷺ: مَن جرَّ ثوبه خُيلاء لم ينظر الله إليه يوم القيامة، قال: يا رسول الله، إنَّ إزاري يسترخي إلا أن أتعاهده، فقال له رسولُ الله ﷺ: لستَ ممن يفعله للكبر، فهذه شهادةٌ من النبي ﷺ للصديق أنه لا يفعله للكبر، وإنما قد يرتخي إزاره من غير قصدٍ منه، فيتعاهده، أما هؤلاء فيجرونها تعمُّدًا، ولا يتعاهدونها، ومَن يعلم قلوبهم إلا الله ؟ فظاهرهم الإسبال والخيلاء والتَّكبر، وإن زعموا خلاف ذلك.\nثم إنهم قد تظاهروا بمخالفة شرع الله، وبما نهى الله عنه، فوجب عليهم ترك ذلك، والإنكار عليهم، أما المرأةُ فلها إرخاء الثياب، يُشرع لها إرخاء الثياب؛ لأنها عورةٌ تستر أقدامها.","link":"https://binbaz.org.sa/fatwas/21050/ما-النصيحة-تجاه-التهاون-بالاسبال-واللحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0846كثير من الناس يتهاونون في تطبيق السنة فما نصيحتكم؟ ابن باز فتاوى المحاضرات.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":1019,"question":"لقد وُلد لي مولودٌ ذكرٌ، وهو مختونٌ، هل يجوز أن أختنه مرةً أخرى؟","title":"حكم من وُلِد له مولودٌ مختون؟","answer":"الجواب: إذا كان مختونًا فالحمد لله، كفاك الله مُؤنته، فليس عليك ختانٌ، ماذا يُختن منه ما دامت القلفة قد ذهبت ولم يكن له قلفة؟ هذا يقع في كثيرٍ من الأحيان، بعض الذكور يقع ليس له قلفة، فأنت كُفيت المؤنة، فاحمد ربَّك، واشكر الله، وليس عليك شيءٌ.","link":"https://binbaz.org.sa/fatwas/21057/حكم-من-ولد-له-مولود-مختون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0853يقول السائل لقد ولد لي مولود ذكر وهو مختون فهل أختنه مرة أخرى؟ ابن باز فتاوى المحاضرات.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":1075,"question":"ما حكم صبغ المرأة شعرها بالألوان الموجودة في الأسواق للتزين لزوجها، علمًا بأنها تُعتبر صغيرة في السن؟","title":"ما حكم صبغ شعر المرأة للتزين لزوجها؟","answer":"الجواب:\nالرسول  نهى عن تغيير الشَّيب فقط بالسواد، أما إذا كان غير ذلك بالصُّفرة والحُمرة؛ لا حرج في ذلك، أما التي قد أصابها الشيبُ، أو الرجل أصابه الشيبُ فليس له أن يُغير بالسواد، النبي عليه الصلاة والسلام قال: غَيِّروا هذا الشَّيب، وجنِّبوه السواد. أما كونها تُزين بحمرةٍ أو صفرةٍ أو غير ذلك وهي شابَّة ليس فيها شيبٌ؛ ما يضرُّ ذلك، على حسب ما تتفق مع زوجها عليه من أنواع التَّجمل الذي لا يُخالف الشرع.\nس: وهل يكون فيه تقليدٌ أو تشبُّهٌ؟\nالشيخ: إذا وُجِدَ شيءٌ يختص بالكفار ما يفعله المسلمون، لا يفعله المسلم، يكون تشبُّهًا، أما إذا كان شيئًا مُشتركًا يفعله المسلمون وغيرهم؛ ما يكون تشبُّهًا.","link":"https://binbaz.org.sa/fatwas/21142/ما-حكم-صبغ-شعر-المراة-للتزين-لزوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0938ما حكم صبع شعر المرأة بالألوان الموجودة في الأسواق للتزين لزوجها علماً بأنها صغيرة؟ابن باز.mp3","categories":["اللباس والزينة"]},{"id":1118,"question":"توجد في بعض الملابس النّسائية بعض التَّشكيلات والرسومات من جهة الصدر تُسمَّى: بالموديل، وكذلك بعض الملابس الناصعة البياض.والسؤال هو: هل في لبسها شيءٌ من التَّحريم، علمًا بأنها كما تقول: لا تكشفها إلا لزوجها، وأحيانًا في مجلس النساء فقط وبينهنَّ؟ ترجو توضيح ذلك لها ولأخواتها في الله، وجزاكم الله عن الجميع خير الجزاء.","title":"حكم الرسومات والتشكيلات في ملابس النساء","answer":"الجواب:\nالأصل في هذا الباب أنَّ الملابس من أي جنسٍ جائزة للرجال والنساء، من جميع الألوان، لكن بشرط ألا يكون تشبُّهًا، فيكون للرجال لباسهم اللائق بهم، ويكون للنساء لباسهن اللائق بهن، فلا يلبس الرجلُ لبسة المرأة، ولا يتشبَّه بها، ولا تلبس المرأةُ لبسة الرجل، ولا تتشبَّه به، يقول النبيُّ عليه الصلاة والسلام: لعن الله الرجلَ يلبس لبسة المرأة، ولعن الله المرأةَ تلبس لبسة الرجل، ولعن المترجِّلات من النساء، يعني: المتشبِّهات بالرجال.\nفإذا كانت الصورةُ التي ذكرت السائلةُ ليس فيها تشبُّه بالرجال ولا بالكفرة؛ فلا بأس، ولو فيها رسوم، إذا كانت الرسوم غير صور، إذا صار فيها رسوم نقوش في الصدر أو في اليدين لا حرج في ذلك، النقوش في الملابس لا حرج فيها إذا كانت ملابس تختص بالنساء، ليس فيها تشبُّه بالرجال، وليس فيها تشبه بالنساء الكافرات، ليست من اختصاصات الكافرات، بل هي ملابس يلبسها المسلمون، فلا بأس، ولو كانت فيها نقوش في صدرها أو في يديها أو في حلقها، لكن إن كانت النقوشُ صورًا من صور الحيوانات فلا يجوز، إن كانت فيها صورة مثل صورة الأسد، أو الرجال، أو النساء، أو الطيور، أو غير هذا من الصور لذوات الأرواح؛ فلا تُلبس الملابس التي فيها صور لذوات الروح، أما صورة شيء ما فيه روح؛ فلا حرج في ذلك: كالجبل، والسيارة، وشبه ذلك.\nوينبغي أن تكون ملابس النساء متوسطةً، لا ضيقة تبين حجم الأعضاء والعورة، ولا واسعة ترى منها العورة أيضًا، ولكن وسطًا، وتكون ساترةً. ولباسها عند زوجها: هذا موسَّعٌ فيه؛ لأنَّ لزوجها أن يرى عورتها، فلباسها عند زوجها أمره واسعٌ، في فراشها وغيره، وهكذا عند النساء الأمر أوسع مما يتعلق بالرجال، فعليها في لباسها أن تكون مستورة العورة عند النساء مُتحشمة.  وأما عند الرجال فالأمر أعظم؛ يجب أن تكون محتجبةً، ساترةً لجميع بدنها عند الرجال الأجانب، يعني: الرجل غير المَحْرم، أما عند زوجها فالأمر في ذلك واسع؛ لأنها عند زوجها تُباح له ويُباح لها.","link":"https://binbaz.org.sa/fatwas/21161/حكم-الرسومات-والتشكيلات-في-ملابس-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0957ما حكم الرسومات والتشكيلات في لباس النساء من جهة الصدروحكم ليس الثياب الناصعة البياض للنساء.mp3","categories":["اللباس والزينة"]},{"id":1136,"question":"ما حكم إزالة شعر المرأة من وجهها؟","title":"هل يحوز للمرأة إزالة شعر الوجه؟","answer":"الجواب:\nالشعر قسمان: الشعر العادي: لا يجوز التَّعرض له، لا الحاجبان، ولا الوجه؛ لأنه من النَّمص. أما الشعر غير العادي الزائد الذي يُسبب تشويهًا: كالشَّارب واللِّحية، فهذا لا بأس أن يُزال.","link":"https://binbaz.org.sa/fatwas/21196/هل-يحوز-للمراة-ازالة-شعر-الوجه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0992هل يجوز للمرأة إزالة شعر الوجه؟.mp3","categories":["اللباس والزينة"]},{"id":1139,"question":"ما حكم لبس ملابس الرجال للنِّساء في الفترات التَّمثيلية الإسلامية الهادفة، والتي تكون في الحفلات الخيرية، والتي تُقام من أجل أغراضٍ دينيةٍ كحفل خصص لصالح أفغانستان وفلسطين، وأعمال خيرية؟","title":"هل يجوز لباس الرجل للمرأة لغرض التمثيل؟","answer":"الجواب:\nلا يجوز التَّشبه بالرجال ولا بالنساء، لا يجوز للمرأة أن تلبس لباس الرجال ولو لمقصدٍ صالحٍ، ولا للرجل أن يلبس لباس المرأة ولو لقصدٍ صالحٍ، يجب الحذر من هذا، فالرسول ﷺ لعن المتشبّهين من الرجال بالنساء، ولعن المتشبّهات من النساء بالرجال، فلا يجوز هذا العمل، ولا التَّحيل عليه بالاحتفال بكذا أو كذا، كل هذا منكر، الواجب على المرأة أن تبتعد عمَّا حرَّم الله عليها، ومن ذلك التَّشبه بالرجال، والرجل كذلك.","link":"https://binbaz.org.sa/fatwas/21193/هل-يجوز-لباس-الرجل-للمراة-لغرض-التمثيل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0989هل يجوز للمرأة أن تلبس لباس الرجل لغرض التمثيل فقط؟.mp3","categories":["اللباس والزينة"]},{"id":1169,"question":"يسأل عن حكم لبس الماس للرجال؟","title":"ما حكم لبس الألماس للرجال؟","answer":"الجواب:\nلا أعلم أنَّ فيه شيئًا الماس. المنهي عنه الذهب للرجل، أما خاتم الفضة أو خاتم الماس ما أعلم فيه شيئًا، قد لبس النبيُّ ﷺ خاتم الفضة، والصحابة، والماس ليس من الذهب، الماس نوعٌ آخر من المعادن، فهو إلى الفضَّة أقرب، ولا يُعطى حكم الذهب إلا بدليلٍ شرعيٍّ، وإذا كانت فيه شُبهة، وأحبَّ الإنسانُ تركَه؛ لأنَّ فيه مُغالاة، وقيمته كبيرة، واكتفى بخاتم فضةٍ، يكون أحسن، من باب ترك المغالاة، وترك الإسراف، إذا كان غاليًا، إذا كان ذا قيمةٍ كبيرةٍ، يجعل القيمة الكبيرة في شيءٍ ينفعه وينفع المسلمين، أما إذا كان ليس فيه إسراف، وقيمته ليس فيها ما يضرُّ وما يُسبب -يعني- تساؤل الناس والتَّحدث عنه بأنه –يعني- مسرف أو كذا، فالأمر سهلٌ.\nفالحاصل أن خاتم الماس ما نعلم فيه شيئًا، إلا إذا كان ذا قيمةٍ كبيرةٍ فتركه أحوْط؛ لئلا يُقال: إنه مسرف، أو أنه ما يُبالي بالمال، من باب صيانة العرض، ويكتفي بخاتم الفضة.","link":"https://binbaz.org.sa/fatwas/21225/ما-حكم-لبس-الالماس-للرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1169ما حكم لبس الألماس للرجال؟ ابن باز فتاوى.mp3","categories":["اللباس والزينة"]},{"id":1182,"question":"ما حكم استعمال جلد الثعبان؟ لعله يقصد في الزينة والحقائب وما أشبه ذلك.","title":"حكم استعمال جلد الثعبان في الزينة والحقائب","answer":"الجواب:\nأهل العلم اختلفوا فيما يُطهّره الدِّباغ: ذهب قومٌ إلى أن الدباغ يُطهّر كلَّ الجلود: الثعبان والأسود والذئاب وغير ذلك، واحتجُّوا بحديث: إذا دُبِغَ الإهابُ فقد طَهُر، دباغ جلود الميتة طهورها، أيما إهاب دُبغ فقد طهر. وقال آخرون: يختصّ بما كان مأكول اللحم خاصةً، قالوا: والإهاب في اللغة كما قال النَّضر بن شُميل: \"الإهاب: جلد ما يُؤكل لحمه خاصةً\"، وقالوا: يقول ﷺ: ذكاة الأديم دباغه، فهذا يدل على أنَّ الدباغ إنما يُؤثر فيما تنفع فيه الذكاة، بخلاف الأسود والنمور والكلاب والثعالب، فهذه مُحرَّمة، فكما أنها محرَّمة جلودها كذلك لا تطهر بالدباغ.\nفالمقام مقام شبهة، والأرجح أن الدباغ إنما يُؤثر في جلود الميتة؛ لأن الرسول ﷺ قال للناس لما قال: دباغ الميتة طهورها، ولما رأى امرأةً عندها شاة ميتة قال: ألا أخذتُم إهابها فدبغتُموه فانتفعتم به، قال: ذكاة الأديم دباغه؛ فهذا يدل على أن المراد: ما يتعلق بالحيوانات التي تنجس جلودها بالموت، وهي الإبل والبقر ونحوها، أما التي في الأصل خبيثة نجسة: كالثعالب والأسود والنمور والكلاب؛ فهذه لا يُؤثر فيها الدبغ، هي على أصل النَّجاسة.\nهذا هو القول الأحوط والأرجح من حيث الدليل، والمسألة فيما قلتُ لكم خلافية بين أهل العلم.","link":"https://binbaz.org.sa/fatwas/21250/حكم-استعمال-جلد-الثعبان-في-الزينة-والحقاىب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1144ما حكم استعمال جلد الثعبان؟ ابن باز فتاوى.mp3","categories":["اللباس والزينة"]},{"id":1298,"question":"سائلة تقول: هل يجوز كشف القدم في الصلاة؟","title":"هل يجوز للمرأة كشف القدم في الصلاة؟","answer":"الجواب:\nأكثر أهل العلم على أنها تسترها في الصلاة، المرأة تستر قدمها في الصلاة، وفي حديثٍ عن أمِّ سلمة أنها سُئلت عن هذا: تُصلي المرأةُ في درعٍ وخمارٍ، فقالت رضي الله عنها: \"إذا كان الدرعُ سابغًا يُغطي ظهور قدميها\"، جاء مرفوعًا عنها، وموقوفًا، والموقوف عند أهل العلم أصحّ، فالمشروع لها أن تُغطي قدميها بالثياب الساترة، أو جوارب، هذا هو الأحوط لها، وهو الذي ينبغي لها، وهو واجبٌ عند جمهور أهل العلم.\nأما الكفَّان: فأمرهما أوسع، إن غطّتهما فهو أحسن، وإن كشفتهما في الصلاة مع الوجه فلا بأس.\nأما الوجه: فالسُّنة كشفه للمرأة في الصلاة، إلا أن يكون عندها أجنبي فتستره، أما إذا كان ما عندها إلا محارمها، أو نساء، أو ما عندها أحدٌ؛ فالسنة كشف الوجه.  أما اليدان –الكفَّان- فسترهما أفضل، وإن كشفتهما صحَّت الصلاةُ على الصحيح، وأما القدمان فالواجب سترهما، هذا هو الذي عليه أكثر أهل العلم.","link":"https://binbaz.org.sa/fatwas/21371/هل-يجوز-للمراة-كشف-القدم-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1114سائلة تقول هل يجوز كشف القدم في الصلاة؟ ابن باز فتاوى.mp3","categories":["ستر العورة للمصلي","اللباس والزينة"]},{"id":1395,"question":"بعض الناس إذا أحَدٌ إزاره إلى أنصاف ساقيه قال: هذا متنطع؟","title":"هل رفع الإزار إلى نصف الساق مِن التَّنَطُّع؟","answer":"الجواب:\nلا، هذا غلط اللي يقوله جاهل، الإزرة من نصف الساق إلى الكعب، من فعل هذا أو هذا فلا بأس، إلى النصف أو إلى آخر الساق، بس لا تنزل عن الكعب، حدها الكعب ولا تزيد فوق النصف.","link":"https://binbaz.org.sa/fatwas/21488/هل-رفع-الازار-الى-نصف-الساق-من-التنطع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صفة إزار المسلم وهل رفعها إلى نصف الساق تنطع.mp3","categories":["اللباس والزينة"]},{"id":1516,"question":"الحناء السوداء، إذا حنيتُ لحيتي فطلعت سوداء؟","title":"حكم الصَّبغ بالسَّواد للشاب والكبير","answer":"الجواب:\nإذا كان فيها شيبٌ فلا، أما إذا كان الشعر أسود وما فيه شيب فما يُخالف، لكن إذا كان شيبٌ فلا يُغير الشَّيبَ بالسواد، يُغيره بالحُمرة أو الصُّفرة، أو بالسواد بين الحمرة والسواد –يعني المخلوط- فالنبي ﷺ قال: غيِّروا هذا الشيب، واجتنبوا السواد، والغالب التدليس؛ لأنه إذا صبغه بالسواد دلَّس على الناس حيث يظنونه شابًّا.\nس: بعض الناس يقول: إنه إذا كان شابًّا يُسمح له؟\nج: غيِّروا هذا الشيب، واجتنبوا السواد هكذا أمر ﷺ، وقال: يأتي في آخر الزمان قومٌ يخضبون بالسَّواد كحواصل الحمام، لا يريحون رائحة الجنة -نسأل الله العافية.\nس: لعله يريد أن يتزوج مثلًا، يقول: أنا عمري كذا، فيغش؟\nج: بعض الشباب يأتيه الشيبُ مُبكرًا، فعليه ألا يصبغ بالسواد، فالحديث عام، الرسول ﷺ قال: غيِّروا هذا الشيب، وجنِّبوه السواد مطلقًا، للمرأة والرجل.","link":"https://binbaz.org.sa/fatwas/21615/حكم-الصبغ-بالسواد-للشاب-والكبير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم صبغ اللحية بالحناء السوداء.mp3","categories":["اللباس والزينة"]},{"id":1530,"question":"إذا كان الثوبُ على الكعبين مباشرةً وليس تحت الكعبين؟","title":"ما حد إسبال الثياب؟","answer":"الجواب:\nالنبي ﷺ يقول: ما أسفل من الكعبين، لكن كونه يرفعه أزين له وأبعد عن الشبهة.\nس: إذا لمس الكعبين لا حرج؟\nج: لا حرج، الرسول ﷺ يقول: ما أسفل من الكعبين.","link":"https://binbaz.org.sa/fatwas/21630/ما-حد-اسبال-الثياب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حد إسبال الثياب.mp3","categories":["اللباس والزينة"]},{"id":1620,"question":"هل يُؤخذ من حديث زينب أنَّ الحُلِيَّ كان جائزًا للنساء؟","title":"ما حكم الحُلِيَّ للنساء؟","answer":"الجواب:\nالحُلِيَّ جائز للنساء، في الأحاديث الصحيحة جواز الحُلِيَّ للنساء، لكنه حرام على الرجال، الذهب على الرجال حرام، أما خاتم الفضة فيُباح للجميع: الرجال والنساء.","link":"https://binbaz.org.sa/fatwas/21725/ما-حكم-الحلي-للنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الحلي للنساء.mp3","categories":["اللباس والزينة"]},{"id":1714,"question":"كشف المرأة وجهها لرجلٍ ليس له شهوة؟","title":"حكم كشف المرأة وجهها لرجلٍ ليس له شهوة","answer":"الجواب:\nهذا مثلما بيَّن القرآن: الرجل الذي ليس برجلٍ في الحقيقة.\nس: يعني: لا بأس أن تكشف له وجهها؟\nج: هذا يُقال له: \"غير أولي الإِرْبَة\" يعني: ليس من أهل النساء، فلا يجب عليها الاحتجاب عنه: أَوِ التَّابِعِينَ غَيْرِ أُولِي الْإِرْبَةِ مِنَ الرِّجَالِ [النور:31].\nس: ما المقصود بالتابعين؟\nج: الذي يكون بين النساء ما هو معروف بالشهوة.\nس: هل هو المُغَفَّل...؟\nج: الذي ما له شهوة، ما يشتهي النساء.\nس: ابن كثير يقول:.....؟\nج: لا، غير أولي الإِرْبَة، الإِرْبَة: الشهوة.","link":"https://binbaz.org.sa/fatwas/21820/حكم-كشف-المراة-وجهها-لرجل-ليس-له-شهوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم كشف المرأة وجهها لرجلٍ ليس له شهوة.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":1777,"question":"شراء طيور الزينة ووضعها في أقفاص، مثل العصافير؟","title":"حكم شراء طيور الزينة ووضعها في أقفاص","answer":"الجواب:\nما فيه بأس، إذا أكرمها ولم يظلمها وأعطاها حاجتها من الحبوب والماء؛ ما في بأس.","link":"https://binbaz.org.sa/fatwas/21884/حكم-شراء-طيور-الزينة-ووضعها-في-اقفاص","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم شراء طيور الزينة ووضعها في أقفاص.mp3","categories":["اللباس والزينة"]},{"id":1812,"question":"بالنسبة للرجل الأعمى إذا كان مدرسًا في إحدى مدارس البنات، أحيانًا تكون الطالبات أو المعلمات يَتَطَيّبن، فما الحكم؛ لأنه يشم رائحتهن؟","title":"حكم تَعَطُّر النساء عند المدرس الأعمى","answer":"الجواب:\nهذا عليهنَّ هن، فعليهنَّ ترك الطِّيب، ويُخاطبن هن إذا كن يُخالطن الرجال، سواء معلمات أو غير معلمات، عليهن ترك الطِّيب.","link":"https://binbaz.org.sa/fatwas/21920/حكم-تعطر-النساء-عند-المدرس-الاعمى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم تطيب النساء عند المدرس الأعمى.mp3","categories":["قضايا المرأة","النظر والخلوة والاختلاط","اللباس والزينة"]},{"id":1813,"question":"الرُّكْبَة هل تدخل في العورة؟","title":"ما حدود العورة؟ وهل الرُّكْبَة منها؟","answer":"الجواب:\nلا، الرُّكْبَة وما تحتها ليس من العورة، فالنبي ﷺ جلس ذات يومٍ في بئرٍ وأبدى ركبتيه، وهكذا جلس معه أبو بكر وعمر وعثمان.\nس: وما فوق الركبة؟\nج: ما فوق الركبة عورة، والركبة وما تحتها ليس بعورةٍ.\nس: تقسيم بعض أهل العلم العورة إلى: مُخَفَّفة ومُغَلَّظة؟\nج: المُغَلَّظة الفَرْج: الدبر والقبل، هذه مُغَلَّظة، وما دونها غير مُغَلَّظة إلى الركبة.\nس: لكن الحكم في السّتر واحد؟\nج: نعم، يجب سترها.","link":"https://binbaz.org.sa/fatwas/21921/ما-حدود-العورة-وهل-الركبة-منها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/العورة وحدودها.mp3","categories":["ستر العورة للمصلي","اللباس والزينة"]},{"id":1815,"question":"في بعض الدول الإسلامية يظن النساء أنَّ الحجاب هو تغطية الرأس مع الأذن والذقن، فما توجيهكم لهن؟","title":"ما مواصفات الحجاب الشرعي للمرأة؟","answer":"الجواب:\nالحجاب تغطية البدن كله، قال الله جل وعلا: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]، تغطية الرأس والوجه والبدن كله، هذا هو الحجاب، فقد رُخِّص لهنَّ في أول الإسلام في عدم الحجاب، فكانت المرأة تجلس مع الرجل وتكلمه وهي كاشفة، ثم أمر الله بالحجاب في الوجوه وغيرها، كما قالت عائشة رضي الله عنها لما وقعت وقعةُ الإفك ومرَّ عليها صفوان وهي في محلها الذي فارقها فيه القوم، قالت: \"فلما رآني عرفني، وقد كان رآني قبل الحجاب، فخمَّرتُ وجهي\".\nالمقصود أن المرأة كانت قبل الحجاب تكشف وتُكلِّم الرجل، وتجلس مع الرجال وتُخاطبهم، ثم أنزل الله آية الحجاب، وهي قوله سبحانه: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] فأُمرن بالحجاب، ومُنعن من الكشف؛ لأنَّ ذلك فيه خطر وفتنة، والحجاب فيه ستر وعافية وبُعْدٌ عن الشر، ولله الحكمة البالغة ، وهو الحكيم العليم جلَّ وعلا.","link":"https://binbaz.org.sa/fatwas/21923/ما-مواصفات-الحجاب-الشرعي-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ماهية الحجاب وصفته.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":1816,"question":"هناك من العلماء مَن يقول أنَّ الوجه ليس من العورة؟","title":"ما حكم القول بأن وجه المرأة ليس بعورة؟","answer":"الجواب:\nهذا قول ضعيف مرجوح، هذا غلط.\nس: ويستدلون ببعض الأحاديث؟\nج: لا، حديث لا تنتقب المرأة هذا في المُحْرِمَة، فإنها لا تنتقب وتلبس النقاب الذي تظهر منه العينان، لكنها تستر وجهها بغير النقاب، قالت عائشة رضي الله عنها: \"كن إذا مرَّ بنا الرجالُ ونحن مع النبي في حجة الوداع سدلت إحدانا خمارها على وجهها، فإذا جاوزونا كشفناه\"، فالمرأة منهية عن الحجاب بالبرقع الذي تبدو منه العينان، وهو النقاب، أما ستره بغير ذلك فلا بأس، مثلما أنَّ المرأة منهية عن القفازين في يديها، وتستر يديها بغير القفازين: بالعباءة أو بالجلباب، والرجل منهيٌّ عن ستر بدنه بالقميص، ويستر بدنه بالإزار والرداء، ولا يستره بالقميص ولا بالسّراويل.","link":"https://binbaz.org.sa/fatwas/21924/ما-حكم-القول-بان-وجه-المراة-ليس-بعورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم كشف وجه المرأة وهل هو عورة.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":1819,"question":"إذا كان نفسُ الحجاب فاتنًا هل تأثم المرأةُ بأنها فتنت الرجال؟","title":"ما حكم الحجاب الذي فيه فتنة للرجال؟","answer":"الجواب:\nعلى كل حال مثلما قال الله: وَلَا تَبَرَّجْنَ تَبَرُّجَ الْجَاهِلِيَّةِ الْأُولَى [الأحزاب:33]، فالمرأة مأمورةٌ بالحجاب، ومأمورة بعدم الزينة والتَّبرج الذي يَفْتِن، وعليها أن تلبس اللباس العادي، لا تفتن الرجال.\nس: الآن يعملون عبايات ويكتبون عليها اسم المرأة؟\nج: هذا غلط، هذه فيها نظر وفتنة.\nس: من الشهرة؟\nج: ما يصلح هذا، فيها فتنة، ما يجوز؛ لأنَّ هذا معناه أنها تُعرِّف الناسَ الذين يمرون بها.","link":"https://binbaz.org.sa/fatwas/21927/ما-حكم-الحجاب-الذي-فيه-فتنة-للرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الحجاب الفاتن للرجال.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":1821,"question":"بعض النساء هناك عندهم شدة في الإسلام ويسألون، وهم في الأصل لا يلبسون حجابًا ولا نقابًا؟","title":"كيف يكون التدرج في دعوة المسلمات الجدد؟","answer":"الجواب:\nهذا ما عاشوا عليه، مساكين، عاشوا في جاهليةٍ.\nس: هل يمكن أن تبدأ بالحجاب ثم النقاب، فلا يُقال لها من البداية: النقاب واجب؟ ماذا تقول لها: الحجاب أولًا أم النِّقاب؟\nج: الحجاب هو النقاب، لكن النِّقاب سُمِّي نقابًا لأنه تُنقب فيه العينان.","link":"https://binbaz.org.sa/fatwas/21929/كيف-يكون-التدرج-في-دعوة-المسلمات-الجدد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المسلمات الجدد عندهم شدة في الإسلام تبدأ بالحجاب ثم النقاب هل يُقال لها من البداية النقاب واجب.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":1824,"question":"حلق اللحية هل يكون من التَّخنُّث في شيءٍ؟","title":"هل يُعَدُّ حلق اللحية من التَّخنُّث؟","answer":"الجواب:\nهو محرَّم، وفيه تشبُّه بالنساء؛ لأنَّ النساء ليس لهنَّ لحًى.\nس: لكن بعض الفقهاء يُدخِل حالقَ اللحية تحت حكم التَّخنُّث؟\nج: حكاه ابنُ عبدالبر عن بعض أهل العلم؛ لأنَّ وجود لحيةٍ بدون شعرٍ فيه تشبُّه بالنساء.","link":"https://binbaz.org.sa/fatwas/21932/هل-يعد-حلق-اللحية-من-التخنث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حلق اللحية هل يكون من التَّخنُّث.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":1826,"question":"بعض النساء تلبس ما يُسَمَّى \"الكاب\"، فإذا لبسته المرأة يُبرز الكتفين، فما الحكم؟","title":"حكم لبس ما يُسَمَّى بـ\"الكاب\" للمرأة","answer":"الجواب:\nإذا كانت مستورةً فالحمد لله، فكون أعضائها مستورة أطيب وأكمل.\nس: يُبرز الكتفين؟\nج: الحجم ما يضر إذا كانت مستورة الشعر والبدن واللحم، فالأمر سهل.\nس: يصف اللحمَ، يعني: إذا لبسته المرأة يفتن الرجال؛ لأنه يُبين أجزاء المرأة: يبين كتفها وعجيزتها؟\nج: ما يجوز هذا، الذي يُبين شيئًا من صفاتها هذا منكر، لا بدّ أن تكون متسترةً.","link":"https://binbaz.org.sa/fatwas/21934/حكم-لبس-ما-يسمى-بـالكاب-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم لبس ما يُسَمَّى بالكاب للمرأة.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":1827,"question":"\"البنطلون\" للنساء؟","title":"ما حكم لبس \"البنطلون\" للنساء؟","answer":"الجواب:\nتلبس لباس جماعتها الذي ما يُشابه الرجال، تلبس لباس النساء اللاتي من جماعتها، ولا يكون شهرةً، ولا مُشابهًا للرجال، والرجل كذلك يلبس لباس الرجال أمثاله.","link":"https://binbaz.org.sa/fatwas/21935/ما-حكم-لبس-البنطلون-للنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما حكم لبس البنطلون للنساء؟.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":1828,"question":"بعض النساء تُغير إلى لونٍ أحمر؟","title":"حكم تغيير لون الشعر إلى الأحمر أو غيره","answer":"الجواب:\nلا بأس، الأحمر لا بأس به، الممنوع السواد، أما إذا غُيّر بأحمر أو بين الحمرة والسواد أو بشكل أصفر؛ فلا بأس.\nس: لو كان قصدهم الموديل أو الموضة؟\nج: المقصود تغيير الشيب بغير السواد، لا بأس به على أي قصدٍ، لكن لا يكون فيه تشبه، فإذا كان شيئًا خاصًّا بالكفرة فلا يجوز لهم.\nس: من الموضة: هل هذا من التشبه بالكفار؟\nج: إذا كان في بلاد الكفرة لا يتشبَّه بهم، أما إذا كان أهلُ بلده يفعلون ذلك من المسلمين: أصفر، أو أحمر، أو رأى أن هذا أنسب له وما قصد التشبه؛ فلا بأس.","link":"https://binbaz.org.sa/fatwas/21936/حكم-تغيير-لون-الشعر-الى-الاحمر-او-غيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم تغيير لون الشعر إلى الأحمر أو غيره.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":1830,"question":"لو استعان بالزعفران؟","title":"حكم استعمال الزعفران للرجال","answer":"الجواب:\nالرجل لا يتزعفر، أما المرأة فلها ذلك، فالرسول ﷺ نهى عن التزعفر للرجال.","link":"https://binbaz.org.sa/fatwas/21938/حكم-استعمال-الزعفران-للرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم استعمال الزعفران للرجال.mp3","categories":["اللباس والزينة"]},{"id":1832,"question":"بالنسبة للمرأة إذا رأت أنها تقصّ من شعرها لتتجمّل لزوجها؟","title":"حكم قص شعر المرأة للتَّجَمُّل لزوجها","answer":"الجواب:\nلا بأس إذا قصت من أطرافه، لكن لا تحلقه، إذا قصت منه لأنه كثير أو طويل يُؤذيها أو يرى زوجها أنَّ فيه تخفيف المؤونة أو أنه أجمل لها؛ فلا بأس.\nس: حدّ القصّ في المرأة؟\nج: ما فيه حدٌّ محدود، الشرط ألا يكون فيه تشبّه بالرجال، ولا تشبّه بالنساء.","link":"https://binbaz.org.sa/fatwas/21940/حكم-قص-شعر-المراة-للتجمل-لزوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قص المرأة لشعرها لتتجمل لزوجها.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":1837,"question":"هل الأَوْلَى الخِضَاب (في اللحية)؟","title":"حكم تخضيب اللحية بالحُمرة والصُّفرة","answer":"الجواب:\nالأفضل الخِضَاب، يخضبها بالحمرة، بالصفرة، لا بالسواد، أو بالسواد مع الحمرة فيصير مخلوطًا بين السواد والحمرة، أما الأسود الخالص فلا، يقول النبيُّ ﷺ: غيِّروا هذا الشَّيبَ، واجتنبوا السَّواد.","link":"https://binbaz.org.sa/fatwas/21946/حكم-تخضيب-اللحية-بالحمرة-والصفرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تغيير اللحية وتخضيبها.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":1840,"question":"بالنسبة لكدَّ اللحية مثلًا للتَّجمل وما شابهه، هل فيه شيء؟","title":"حكم كَدِّ اللحية للتَّجَمُّل وما شابهه","answer":"الجواب:\nما أعرف الكدَّ، لكن الكدَّ يقطعها.\nس: بالنسبة للذي يحلق لحيته أو يأخذ منها شيئًا هل يأثم؟\nج: نعم، يأثم، لا شكّ، فهذه معصية، يقول النبي ﷺ: قصُّوا الشَّوارب، ووفِّروا اللِّحَى، خالفوا المشركين، ومخالفة الأوامر معصية.","link":"https://binbaz.org.sa/fatwas/21949/حكم-كد-اللحية-للتجمل-وما-شابهه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم كد اللحية للتجمل أو أخذ شيء منها.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":1841,"question":"بعض الإخوان إذا سُئِل: لماذا تصبغ لحيتك بالسَّواد؟ يقول: أنا أحسن ممن يحلقها؟","title":"حكم صبغ اللحية بالسواد والأخذ منها","answer":"الجواب:\nيُداوي معصيةً بمعصية! هذا ما يصح.\nس: أيهم أفضل: الأخذ منها أو حلقها؟\nج: لا يجوز: لا حلقها، ولا الأخذ منها، قال الرسول ﷺ وفِّروها، أمر بالتَّوفير.","link":"https://binbaz.org.sa/fatwas/21950/حكم-صبغ-اللحية-بالسواد-والاخذ-منها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسائل في اللحية.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":1843,"question":"بعض الذين يأخذون من لحاهم يحتجُّون بحديث ابن عمر ويقولون: كان يأخذ كذا وكذا؟","title":"حكم الاحتجاج بحديث ابن عمر في اللحية","answer":"الجواب:\nابن عمر ما هو معصوم.\nس: حجتهم باطلة؟\nج: ما هو معصوم ابن عمر، المعصوم الرسول ﷺ، هو المُبَلِّغ عن الله، الله يقول: وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ [الحشر:7]، أو قال: وما آتاكم ابنُ عمر فخذوه؟!\nس: حجتهم باطلة؟\nج: ما في شك، الله يهدي الجميع، كل واحدٍ قد يغلط.","link":"https://binbaz.org.sa/fatwas/21952/حكم-الاحتجاج-بحديث-ابن-عمر-في-اللحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الاحتجاج بحديث بن عمر في جواز الأخذ من اللحية.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":1846,"question":"النَّعل بجلد الخنزير؟","title":"ما حكم النعل المتخذ من جلد الخنزير؟","answer":"الجواب:\nالأوْلى ترك ذلك، الأحوط ترك ذلك، وليتخذ نعلًا من جلودٍ مباحةٍ: الإبل، والغنم، والبقر؛ لأن الخنزير في حِلِّ جلده إذا دُبِغَ خلافٌ، فبعض أهل العلم يُحرِّمه ولو دُبِغَ.\nس: تركه أحسن؟\nج: تركه أحوط دَعْ ما يُريبُكَ إلى ما لا يُريبُكَ.","link":"https://binbaz.org.sa/fatwas/21955/ما-حكم-النعل-المتخذ-من-جلد-الخنزير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم النعل المتخذ من جلد الخنزير.mp3","categories":["اللباس والزينة"]},{"id":1858,"question":"هل يُفْصَل بين الشارب واللحية؟","title":"ما حكم الفصل بين الشارب واللحية؟","answer":"الجواب:\nالحدّ معروف.\nس: يعني: يُفْصَل؟\nج: نعم، حتى يتبين الشارب من اللحية، الشارب يقصه ويحفه واللحية يبقيها.","link":"https://binbaz.org.sa/fatwas/21967/ما-حكم-الفصل-بين-الشارب-واللحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الفصل بين الشارب واللحية.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":2025,"question":"إذا كان في نسبة من الحرير مثل المشالح؟","title":"ما المقدار الذي يجوز مِن الحرير والذهب؟","answer":"الجواب:\nموضع أصبعين أو ثلاث أو أربع من الحرير يباح للرجل مثل الزرار ومثل الرقعة الصغيرة وأشباه ذلك.\nس: والذهب؟\nالشيخ: الذهب لا، حرام مطلقًا لا قليل ولا كثير.\nس: من قال بجواز اتخاذه للنساء فقط الذهب والفضة؟\nالشيخ: الأحاديث عامة يا ولدي، يعم الرجال والنساء.\nس: بالنسبة للحرير في الحرب هل ورد فيه شيء؟\nالشيخ: إذا دعت الحاجة إليه من الحكة وأشباهها مثل ما لبسه الزبير، رخص النبي ﷺ للزبير وعبدالرحمن بن عوف من أجل المرض، ومجرد الحرب ما يكفي، لا يبيحه.\nس: الجلوس عليه وتلبيس الكَنَب؟\nالشيخ: ما يجوز، هذا ما يجوز.\nس: لا للنساء ولا للرجال؟\nالشيخ: لا يجوز للرجال لبس الحرير ولا الجلوس عليه، أما النساء لهن لبس الحرير.\nس: اتخاذه للجلوس؟\nالشيخ: لا ما يصلح؛ لأن المجالس يأتيها الرجال .\nس: يعني اتخاذه للنساء مقصور على اللباس؟\nالشيخ: الإذن خاص بالملابس، قميص سروال ما يخالف، أما البُسُط والمجالس هذه يأتيها الرجال والنساء، ما يصلح.\nس: المرأة لها الجلوس على الحرير؟\nالشيخ: ما يجوز اتخاذه مجالس؛ لأنها إذا اتخذته جلس عليه زوجها وجلس عليه أبوها، وسيلة إلى جلوس الرجال عليه.\nس: ما هو الديباج؟\nالشيخ: الغليظ من الحرير، الغليظ يسمى \"ديباج\"، واللمعان يسمى \"استبرق\"، اللي يلمع.\nس: عندنا تعريف آخر للديباج نتمنى أن تصوبه إن كان خاطئًا يقول: بكسر الدال وسكون الياء بعدها باء: ثوب سُداه ولُحْمَته الحرير.\nالشيخ: لا، المعروف هو هذا الديباج، هو الغليظ من الحرير.","link":"https://binbaz.org.sa/fatwas/22141/ما-المقدار-الذي-يجوز-من-الحرير-والذهب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم اللباس إذا كان فيه نسبة من الحرير أو ذهب.mp3","categories":["اللباس والزينة"]},{"id":2027,"question":"بعض الساعات مُرَصَّعة بالذهب؟","title":"حكم الساعات والسيارات المُرَصَّعة بالذهب","answer":"الجواب:\nيعطيها امرأته.\nس: من اشترى سيارة واكتشف أنها مطلية بالذهب؟\nالشيخ: محل نظر: إذا كان يمكن حكه وإزالته فيحك ويُزال، إذا كان بالإمكان إزالته فالحمد لله.\nس: بالنسبة للسيارات يا شيخ؟\nالشيخ: إن صح الخبر يمكن إزالته بأشياء؛ تزول وينتفع بالسيارة.","link":"https://binbaz.org.sa/fatwas/22143/حكم-الساعات-والسيارات-المرصعة-بالذهب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الساعات والسيارات المرصعة بالذهب.mp3","categories":["اللباس والزينة"]},{"id":2032,"question":"المعصفر هو الأصفر؟","title":"هل المعصفر هو الأصفر؟ وما حكم لبسه؟","answer":"الجواب:\nنعم، هو هو.\nس: النهي خاص بالتزعفر بالمعصفر والزعفران أما لو لبس ثوبًا أحمر قانيًا؟\nالشيخ: النبي ﷺ لبس الأحمر ولبس الأسود ولبس الأخضر، لكن هذا الأصل ليس فيه الزعفران كالمعصفر، أخبر النبي أنه من زي النساء ومن زي الكفرة.\nس: الثياب الآن المصبوغة العادية التي يكون نفس لونها أصفر يلبسها الرجل؟\nالشيخ: إذا كان ما هو من زي الكفار، ولا هو من زي النساء، ما في بأس، أما المزعفر؛ لا.","link":"https://binbaz.org.sa/fatwas/22148/هل-المعصفر-هو-الاصفر-وما-حكم-لبسه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم اللباس المعصفر أو الأصفر.mp3","categories":["اللباس والزينة"]},{"id":2033,"question":"(ما حكم) بعض الأقمشة يصنعونها من الحرير الصناعي وليس الأصلي؟","title":"حكم الأقمشة المصنوعة من الحرير الصناعي","answer":"الجواب:\nهذا الأحوط تركه للنساء؛ لأنه يشبه الحرير، الذي من المادة -من مادة الدابة- فتركه للرجل المرأة أوْلى به، وإلا ما يصير محرمًا من جنس الحرير الذي على الدابة.","link":"https://binbaz.org.sa/fatwas/22149/حكم-الاقمشة-المصنوعة-من-الحرير-الصناعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم لبس الأقمشة المصنوعة من الحرير الصناعي.mp3","categories":["اللباس والزينة"]},{"id":2034,"question":"قلتم أن الأحوط ترك الأحمر إذا كان مصمتًا، الدليل؟","title":"حكم لبس الثوب الأحمر الخالص","answer":"الجواب:\nجاء في بعض الروايات النهي عن الأحمر القاني، يعني الشديد الحمرة، يعني ما فيه خلط بالمرة، بعض أهل العلم كرهه، ولكن النبي ﷺ ثبت عنه أنه لبس الأحمر، ولبس حلة حمراء، عليه الصلاة والسلام، فالأمر فيه واسع.\nس: بعض الناس احتجوا بهذا الحديث، يقولون: لا يجوز لبس الشماغ لأنه يغلب عليه الحمرة؟\nالشيخ: لا، هذا جهل، أقول \"جهل\"، الشماغ مخلوطة.","link":"https://binbaz.org.sa/fatwas/22150/حكم-لبس-الثوب-الاحمر-الخالص","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الدليل على عدم لبس الأحمر إذا كان مصمتا.mp3","categories":["اللباس والزينة"]},{"id":2035,"question":"الملابس الرياضية أليست مِن لِبْس الكفار؟","title":"هل الملابس الرياضية من زي الكفار؟","answer":"الجواب:\nلا يجوز التشبه بالكفار من تشبه بقوم فهو منهم لا بدّ يغير الملابس على وجه لا يكون مشابهًا للكفار، سواء في اللعب والمسابقة أو في غير ذلك.","link":"https://binbaz.org.sa/fatwas/22151/هل-الملابس-الرياضية-من-زي-الكفار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الملابس الرياضية من لبس الكفار.mp3","categories":["اللباس والزينة"]},{"id":2047,"question":"ما هي الطَّيَالِسَة؟","title":"ما هي الطَّيَالِسَة؟ وما حكم لبسها؟","answer":"الجواب:\nثياب تلبس على الكُتُوف مثل الأردية، يشق وسطها ويدخل رأسه فيها تصير على الكتف، وفي وسطها شق يدخل رأسه فيها، وتكون على الكتوف.\nس: لبس الطاليسة جائز؟\nالشيخ: لا ما ينبغي لبسها، تَشُبُّهٌ باليهود، لاـ يلبس الأردية المعتادة.","link":"https://binbaz.org.sa/fatwas/22165/ما-هي-الطيالسة-وما-حكم-لبسها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما هي الطيالسة وما حكم لبسها.mp3","categories":["اللباس والزينة"]},{"id":2077,"question":"سائِلٌ يُريد مزيدًا من التَّوضيح في مسألة المسياد، يقول: إنَّ المسياد للنساء أصلًا، فهل يجوز استخدامه للرجال؟","title":"هل يجوز استخدام \"المسياد\" للرجال؟","answer":"الجواب:\nإذا كان للنظافة: كنظافة الوجه وإزالة الأوساخ؛ فلا بأس به، ما هو بخاصٍّ بالنساء، فالصابون والأشنان والمكياج وكل شيء يُنَظِّف فهو للجميع، هذا ليس كالتَّشَبُّه باللباس أو الزي أو الكلام أو المشي، أمَّا ما تحصل به النظافة فلا بأس به.","link":"https://binbaz.org.sa/fatwas/22195/هل-يجوز-استخدام-المسياد-للرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز استخدام المسياد للرجال.mp3","categories":["اللباس والزينة"]},{"id":2319,"question":"بالنسبة لوصل الرموش: تُباع في السّوق رموشٌ تصل بها الرموش الموجودة فيصير طولٌ في الرموش التي في العين؟","title":"هل تدخل الرموش الصناعية في الوَصْل؟","answer":"الجواب:\nالأظهر لي أنه ينبغي ترك هذا، ما له حاجة.\nس: لكن يشملها الوعيد؟\nج: ما يُسمَّى: نمصًا، هذه زيادة تعليقٍ، والنَّمص: أخذٌ.\nس: ما يدخل في الواصلة؟\nج: الوصل: وصل شعر الرأس. وترك هذا أحوط، أمَّا التَّحريم فالله أعلم.","link":"https://binbaz.org.sa/fatwas/22443/هل-تدخل-الرموش-الصناعية-في-الوصل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الرموش الصناعية هل تدخل في الوصل.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":2328,"question":"ما الدليل على ستر يدي المرأة وقدميها في الصلاة؟","title":"ما دليل ستر يدي المرأة وقدميها بالصلاة؟","answer":"الجواب:\nليس هناك إلا حديث: المرأة عورة، إطلاق الحديث، وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ [الأحزاب:53]، وأقرب ما احتُجَّ به في هذا هو إطلاق: المرأة عورة، والصواب كشف الوجه فقط، أمَّا اليدان فإن كشفتهما فلا بأس، وإن سترتهما فهو أفضل، وحديث أم سلمة في غطاء القدمين.","link":"https://binbaz.org.sa/fatwas/22452/ما-دليل-ستر-يدي-المراة-وقدميها-بالصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ستر يدي المرأة وقدميها في الصلاة.mp3","categories":["ستر العورة للمصلي","اللباس والزينة"]},{"id":2330,"question":"مَن قال أن ستر أحد العاتقين في الصلاة سنة وليس بواجبٍ؟","title":"حكم ستر العاتقين في الصلاة","answer":"الجواب:\nما هو بواجبٍ؛ لقول النبي ﷺ: ليس على عاتقه، وفي بعض الروايات: عاتقيه، فإذا ستر أحد العاتقين حصل المطلوبُ، لكن سترهما أفضل وأحوط.","link":"https://binbaz.org.sa/fatwas/22454/حكم-ستر-العاتقين-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ستر العاتقين في الصلاة.mp3","categories":["ستر العورة للمصلي","اللباس والزينة"]},{"id":2456,"question":"صلاة الرجل حاسِرَ الرأس؟","title":"ما حكم صلاة الرجل حاسِرَ الرأس؟","answer":"الجواب:\nلا حرج، المحرم بالحج والعمرة يصلي حاسِرَ الرأس مدة الإحرام، ما عليه إلا إزاره ورداؤه، إلا إذا لبس زينته يكون أكمل.","link":"https://binbaz.org.sa/fatwas/22585/ما-حكم-صلاة-الرجل-حاسر-الراس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صلاة الرجل حاسر الرأس.mp3","categories":["ستر العورة للمصلي","اللباس والزينة"]},{"id":2507,"question":"في بعض البلدان العربية تُلبس ملابس تُشبه ملابس الكافرين لكنها غير مقصودة، تعارفوا عليها أنها ملابسهم مثل البنطلونات والقمصان؟","title":"حكم لبس ما يُشبه ملابس الكافرين دون قصد","answer":"الجواب:\nما دام يلبسها المسلمون؛ ما يصير تَشَبُّه.","link":"https://binbaz.org.sa/fatwas/22637/حكم-لبس-ما-يشبه-ملابس-الكافرين-دون-قصد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/لبس ملابس تشبه ملابس الكافرين لكنها غير مقصودة.mp3","categories":["اللباس والزينة"]},{"id":2513,"question":"قوله ﷺ: أكْثَرَتُ عليكم في السواك؟","title":"معنى حديث \"أكْثَرَتُ عليكم في السواك\"","answer":"الجواب:\nيعني لتأكُّده وفضله.\nس: هذه الأحاديث تدل على أن السواك للوجوب؟\nالشيخ: لا، مستحب، ولذلك قال: لولا أن أشق عليكم لأمرتكم.. فجعله الله مستحبًا.","link":"https://binbaz.org.sa/fatwas/22643/معنى-حديث-اكثرت-عليكم-في-السواك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/السواك وأحكامه.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":2517,"question":"السواك في خطبة الجمعة؟","title":"حكم استعمال السواك أثناء خطبة الجمعة","answer":"الجواب: ما يصلح وقت الخطبة، ينصت ويترك الحركة، لا بالسواك ولا بغيره، يكون مُنْصتًا للخطيب، لا يشتغل بالسواك ولا بغيره.","link":"https://binbaz.org.sa/fatwas/22647/حكم-استعمال-السواك-اثناء-خطبة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم السواك في خطبة الجمعة.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":2521,"question":"التحديد بالنسبة لتقليم الأظافر؟","title":"ما أقصى مدة لترك تقليم الأظفار؟","answer":"الجواب: لا يُترك أكثر من أربعين يومًا، يجب أن يأخذ قبل أربعين يومًا.","link":"https://binbaz.org.sa/fatwas/22652/ما-اقصى-مدة-لترك-تقليم-الاظفار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أكثر وقت تقليم الأظافر.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":2522,"question":"بعض كبار السن يَحلقون اللحية ويُبقون الذقن، ويقولون إن هذا ما زاد عن قبضة اليد؟","title":"ما حكم مَنْ يحلق اللحية ويترك الذقن فقط؟","answer":"الجواب: هذا غلط، والواجب إعفاؤها، هذا يُروى عن ابن عمر أنه كان يفعله في الحج والعمرة، يأخذ ما زاد على القبضة، لكن نقول: اجتهاده  خالف فيه السنة؛ اجتهادًا، غير مصيب، والصواب ما هو بحديث، هو يُروى عن ابن عمر مِن فِعله، وأما أنه كان يأخذ من لحيته؛ هذا حديث ضعيف غير صحيح، ما كان يأخذ منها عليه الصلاة والسلام، بل كان يعفيها ويُوَفِّرها، عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/22653/ما-حكم-من-يحلق-اللحية-ويترك-الذقن-فقط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حلق اللحية وإبقاء الذقن.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":2523,"question":"بالنسبة لخصال الفطرة: يوم الجمعة أفضل؟","title":"حكم تخصيص يوم معين لخصال الفطرة","answer":"الجواب: ما لها يوم معين.","link":"https://binbaz.org.sa/fatwas/22654/حكم-تخصيص-يوم-معين-لخصال-الفطرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تخصيص يوم معين لخصال الفطرة.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":2525,"question":"الخِتَان بالنسبة للنساء؟","title":"حكم الخِتان للنساء","answer":"الجواب: إذا تيسر؛ الخاتنة تفهم، أو الخاتن يفهم؛ فلا بأس سنة، إذا تيسر من يختنها من الرجال والنساء العارفين فهو السنة.\nس: تركه بالنسبة للنساء؟\nالشيخ: إذا تُرك لا بأس، إذا ما تيسر مَنْ يختن، إذا ما تيسر حاذق يعرف ذلك.","link":"https://binbaz.org.sa/fatwas/22656/حكم-الختان-للنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الختان للنساء.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":2526,"question":"ما يقال أن الختان واجب؟","title":"ما الصحيح في حكم الختان؟","answer":"الجواب: هو قول جمع من أهل العلم؛ لأنه يروى في بعض الأحاديث، لما أسلم بعض الكفار قال له النبي ﷺ: ألق عنك إزار الكفر واختتن لكن الأشهر أنه سنة؛ لأن الرسول ﷺ ما أمر الناس أن يختتنوا كلهم، دل على أنه سنة.\nس: عدم الاختتان ما يكون فيه مشابهة للمشركين؟\nالشيخ: لا ما فيه مشابهة، بعض المشركين يختتن، اليهود تختن.","link":"https://binbaz.org.sa/fatwas/22657/ما-الصحيح-في-حكم-الختان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الختان وحكمه وحكم تركه.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":2527,"question":"هذا بمعنى التحريم: مَن يتعدى أكثر من شهرين أو ثلاثة (خصال الفطرة)؟","title":"ما أكثر مدة تُترك فيها خِصال الفطرة؟","answer":"الجواب: أكثر من أربعين ما يجوز.","link":"https://binbaz.org.sa/fatwas/22658/ما-اكثر-مدة-تترك-فيها-خصال-الفطرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أكثر مدة يترك فيها خصال الفطرة.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":2528,"question":"من قال أن الطهارة لا تتم إلا بالختان؟","title":"هل للختان تَعَلُّق بالطهارة؟","answer":"الجواب: قول ضعيف، الطهارة ما لها تَعَلُّق بالختان، إذا استنجى يكفي.  لكن الخِتان مطلوب بين الوجوب وبين السُّنة المؤكدة.","link":"https://binbaz.org.sa/fatwas/22659/هل-للختان-تعلق-بالطهارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل للختان تعلق بالطهارة.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":2611,"question":"إنسان عنده سروال ويصلي فيه، وفيه في مكان العورة مثل حبة الذرة مشقوق، وصلى به صلوات عديدة، ويسأل عن صلاته؟","title":"حكم صلاة مَن في ملابسه شِقٌّ يسير","answer":"الجواب: ولا عليه شيء غيره؟\nس: لا ليس عليه شيء؟\nالشيخ: وما درى عنه؟\nس: يظن أنه جائز الشيء اليسير جدًّا؟\nالشيخ: يلاحظه في المستقبل، يتفقّده، واللي مضى يعفو الله عنه، لكن يتفقده في المستقبل حتى يكون مستورًا من جميعه، ولو قليل.","link":"https://binbaz.org.sa/fatwas/22746/حكم-صلاة-من-في-ملابسه-شق-يسير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من صلى وفي ملابسه شق.mp3","categories":["ستر العورة للمصلي","اللباس والزينة"]},{"id":2623,"question":"هناك بعض الإخوة إذا أتى إلى المسجد يرفع البنطلون على أساس أنه مسبل، فهل هو على صوابٍ في حال الصلاة فقط؟","title":"حكم تجنب إسبال الثياب للصلاة فقط","answer":"الجواب: الواجب عليه رفعه دائمًا، ما هو فقط في حال الصلاة، الواجب عليه دائمًا أن يُلاحظ البنطلون وغير البنطلون، فيرفعه، ولو قالوا له: أرخه، ما يُطيعهم، الطاعة في المعروف، ما في المعاصي.\nس: الثوب عندما يكون إلى نصف الساق وأصبح شهرةً بين الناس؟\nج: يُرخيه إلى الكعب حتى لا يكون شهرةً بين الناس، حتى لا يتأذَّى ويُسبب مشاكل، ما في بأس؛ لأنَّه مباح إلى النصف، قُصاراه أن يكون مستحبًّا، لكن ترك المستحب إذا كان فيه مصلحةٌ لا بأس.\nس: ما ورد: ما أسفل من الركبة بأربعة أصابع؟\nج: هذا جاء في بعض الأحاديث، لكن في صحته نظر، وإن جاء فمحمولٌ على هذا المعنى، يعني: أربعة أصابع حول نصف الساق، فالأمر قريب.","link":"https://binbaz.org.sa/fatwas/22758/حكم-تجنب-اسبال-الثياب-للصلاة-فقط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أراد أن يصلي فيرفع البنطلون على أساس أنه مسبل.mp3","categories":["اللباس والزينة"]},{"id":2624,"question":"الإسبال في الإزار والقميص والعِمامة، كيف يكون الإسبالُ في العِمامة؟","title":"كيف يكون الإسبال في العِمامة؟","answer":"الجواب: إذا طوَّلها وراحت تمشي في الأرض، إذا طوَّل ذيلها حتى تتعدَّى الكعب.","link":"https://binbaz.org.sa/fatwas/22759/كيف-يكون-الاسبال-في-العمامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الإسبال في العمامة.mp3","categories":["اللباس والزينة"]},{"id":2768,"question":"تقول إحدى الأخوات أهدي إليها ثوب وهذا الثوب فيه صليب، وصَلَّت وهي لابسة هذا الثوب، تقول: هل تعيد الصلاة أم لا شيء عليها؟","title":"ما حكم الصلاة في ثوب عليه صليب؟","answer":"الجواب: الصلاة صحيحة، لكن تترك هذا اللباس، أو يُحَكُّ الصليب أو تغسله بشيء.\nس: الثوب الذي فيه صليب يَحْرُم لبسه؟\nالشيخ: نعم، والصور كذلك وصور ذوات الأرواح، إلا إذا طمست؛ ما في بأس.\nس: بالنسبة للأطفال الصغار أيضًا؟\nالشيخ: حتى الأطفال؛ لأنه يُعَلَّق ويُحْفَظ.","link":"https://binbaz.org.sa/fatwas/22916/ما-حكم-الصلاة-في-ثوب-عليه-صليب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صلى وكان على الثوب صليب.mp3","categories":["اللباس والزينة","مسائل متفرقة في الصلاة"]},{"id":2828,"question":"هذا سائل يسأل عن حكم لبس البنطلون للرجال؟","title":"ما حكم لبس البنطلون للرجال؟","answer":"الجواب: إذا كان ساترًا ما في شيء، إذا كان ما فيه تَشُبُّه بأعداء الله من كونه يلبسه المسلمون، فإذا كان يلبسه المسلمون ولا فيه تَشُبُّه بأعداء الله ويستر العورة؛ لا بأس.","link":"https://binbaz.org.sa/fatwas/22977/ما-حكم-لبس-البنطلون-للرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم لبس البنطلون للرجال.mp3","categories":["اللباس والزينة"]},{"id":2861,"question":"السُّنة في قص الشارب: هل الإطار، أو يُحْلَق؟","title":"ما السُّنة في قص الشارب وكيفيته؟","answer":"الجواب: السُّنة الإحفاء أحفوا الشوارب بالقص، ما هو بالحَلْق.","link":"https://binbaz.org.sa/fatwas/23014/ما-السنة-في-قص-الشارب-وكيفيته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/السنة في قص الشارب.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":2871,"question":"شعر الخدين في الوجه: هل جائز أخذه؟","title":"هل يجوز أخذ شعر الخدين؟","answer":"الجواب: اللحية ما نبت على الخدين والذقن، هذا في عرف اللغة، على الخدين والذقن هذه اللحية، لا يأخذ من الخدين ولا يأخذ اللحية.","link":"https://binbaz.org.sa/fatwas/23026/هل-يجوز-اخذ-شعر-الخدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز أخذ شعر الخدين.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":2945,"question":"لبس الأحمر القاني؟","title":"ما حكم لبس الأحمر القاني من الثياب؟","answer":"الجواب: تَرْكُه أوْلَى، تَرْكُه أحْوَط.","link":"https://binbaz.org.sa/fatwas/23101/ما-حكم-لبس-الاحمر-القاني-من-الثياب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم لبس الأحمر القاني.mp3","categories":["اللباس والزينة"]},{"id":2955,"question":"العدسات الملونة للمرأة في عينها؟","title":"حكم عدسات العين الملونة للمرأة؟","answer":"الجواب: تركها أحوَط، إلا إذا كانت تعين على النظر، تنفع في النظر.","link":"https://binbaz.org.sa/fatwas/23111/حكم-عدسات-العين-الملونة-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/لبس العدسات للمرأة.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":3097,"question":"هل كن أمهات المؤمنين يكشفن وجوههن عند المؤمنين؟","title":"هل كانت أمهات المؤمنين يكشفن وجوههن؟","answer":"الجواب: لا لا، كذلك، أمهات المؤمنين من جهة الحكم الشرعي؛ من جهة الاحترام، لا من جهة المحرمية.","link":"https://binbaz.org.sa/fatwas/23257/هل-كانت-امهات-المومنين-يكشفن-وجوههن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل كن أمهات المؤمنين يكشفن وجوههن عند المؤمنين.mp3","categories":["اللباس والزينة"]},{"id":3114,"question":"حلق اللحية مِن الكبائر أو مِن الصغائر؟","title":"هل حلق اللحية مِن الكبائر؟","answer":"الجواب: مُنكر ومعصية، أما كونه كبيرة فالله أعلم.\nس: الإصرار على حلق اللحية ألا يصيّرها مِن معصية إلى كبيرة؟\nالشيخ: المقصود أنها معصية، توفير اللحية واجب، وقصها وحلقها من المعاصي، أما كونها كبيرة محل بحث آخر.","link":"https://binbaz.org.sa/fatwas/23274/هل-حلق-اللحية-من-الكباىر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل حلق اللحية من الكبائر.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":3122,"question":"إذا تُوفي الإنسان وفيه سِنُّ ذهب يُقْلَع؟","title":"حكم لِبْس أسنان الذهب وهل تُقْلع من الميت؟","answer":"الجواب: يُقلع أحسن، ينتفعون به ويبيعونه.\nس: لكن لِبسه؟\nالشيخ: لاـ يَلبس أسنانًا من الفضة أو من معدن آخر، لا ينبغي لُبْس الذهب إلا عند الضرورة إذا ما تيسر شيء آخر.\nس: ما يكون تمثيلًا بالميت أن نقلع سِنّ الذهب مِن فمه؟\nالشيخ: لا ما فيه تمثيل، قَلْعُه سهل.","link":"https://binbaz.org.sa/fatwas/23283/حكم-لبس-اسنان-الذهب-وهل-تقلع-من-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/لبس أسنان الذهب.mp3","categories":["اللباس والزينة"]},{"id":3123,"question":"الأحمر الخالص الذي ما فيه شوائب؟","title":"ما حكم لِبْس الأحمر الخالص؟","answer":"الجواب: كره بعض أهل العلم الأحمر الخالص الذي ليس فيه خلط، وبعضهم لم يكرهه؛ لإطلاق الأحاديث الأخرى في لبس الأحمر والأسود، وبعضهم كره الذي مشوب بالحمرة جدًّا ليس فيه خلط؛ لأحاديث وردت في ذلك.\nس: والصواب؟\nالشيخ: الله أعلم، الذي يظهر أن لِبس الأحمر جائز؛ لأنها أصح، أحاديث لِبس الأحمر أصح وأثْبَت.\nس: إذا كان الأحمر لباس شهرة؟\nالشيخ: لباس الشهرة ما يجوز أحمر ولا أخضر ولا أسود ولا أبيض.","link":"https://binbaz.org.sa/fatwas/23284/ما-حكم-لبس-الاحمر-الخالص","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم لبس الأحمر الخالص.mp3","categories":["اللباس والزينة"]},{"id":3124,"question":"إذا امرأة لَبِسَت فَنِيلة زوجها؟","title":"هل يجوز لبسُ المرأة بعضَ ثياب زوجها؟","answer":"الجواب: إذا كانت الفنائل تختلف لا تَلْبَس فنيلة الرجل، وإن كانت الفنائل ما تختلف فالأمر واسع؛ لأن الفنيلة مِن اللباس الداخلي.","link":"https://binbaz.org.sa/fatwas/23285/هل-يجوز-لبس-المراة-بعض-ثياب-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/لبس الزوجة بعض ملابس زوجها.mp3","categories":["اللباس والزينة"]},{"id":3128,"question":"حكم لِبْس البناطيل؟","title":"ما حكم لبس البناطيل المنتشرة بين المسلمين؟","answer":"الجواب: التي فيها تَشَبُّه بالكفرة لا يجوز، إذا كانت من لباس الكفرة كما هو معروف لا يُلبس. أما إذا كان أهل بلد اصطلحوا على بناطيل خاصة بالمسلمين لا تُشبه بناطيل الكفار؛ لا بأس، إذا كانت بناطيل تستر العورات ولا يبدو منها العورة ولا يشبه فيها الكفرة على نمط آخر؛ لا بأس.\nس: إذا صارت عادة للمسلمين؟\nالشيخ: إذا صار لباس المسلمين مشتركًا ما فيه تشبه؛ ما في شيء، إنما التشبُّه إذا كان تشبّه لَبِس لِبْسا خلاف جماعته، أما إذا كان لِبْس أهل بلد ولكن صادف أنهم شابهوا بعض المشركين؛ ما يضر، ما دام هو لُبْسهم ما قَصَدوا المشابهة.","link":"https://binbaz.org.sa/fatwas/23289/ما-حكم-لبس-البناطيل-المنتشرة-بين-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما حكم لبس البناطيل.mp3","categories":["اللباس والزينة"]},{"id":3129,"question":"لو كان هذا الثوب الذي لبسه النبي ﷺ لا يلبسه أحد من أهل البلد كالأحمر مثلًا ألا يصبح ثوب شُهرة؟","title":"هل مِن الشُّهرة ما لا يَلْبسه أهلُ البلد؟","answer":"الجواب: إذا كان في بلد لا يَلبسون لا يَلبس، إذا كان في بلد كلهم متفقون على نوع خاص أبيض أو أحمر لا يخالفهم.","link":"https://binbaz.org.sa/fatwas/23290/هل-من-الشهرة-ما-لا-يلبسه-اهل-البلد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل من لباس الشهرة الثوب الذي لا يلبسه أحد من أهل البلد.mp3","categories":["اللباس والزينة"]},{"id":3131,"question":"متى يكون اللباس شُهرة؟","title":"متى يكون اللباسُ لباسَ شُهرة؟","answer":"الجواب: إذا خالف أهل البلد بزيٍّ يخالفهم، إما أحسن أو أردأ، إما ثوب مشقق أو ثوب يخالفهم في الغلاء والشُّهرة.\nس: لو كان نصف الساق بعضهم يقول هذا شُهرة؟\nالشيخ: هذا ما يُسمّى باللباس، هذا في الكيفية، كيفية اللباس إذا وافق السنة ما عليه مِن الناس.","link":"https://binbaz.org.sa/fatwas/23292/متى-يكون-اللباس-لباس-شهرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى يكون اللباس شهرة.mp3","categories":["اللباس والزينة"]},{"id":3132,"question":"إذا لبس شخص \"فستان\" من نوع جِلْدٍ من الخنزير؟","title":"حكم لبس ثياب مِنْ جِلْد الخنزير","answer":"الجواب: مِنْ جِلْدِ خنزير؟\nالطالب: نعم.\nالشيخ: ما ينبغي لبسه، وإن كان بعض أهل العلم يرى جوازه إذا دُبغ، لكن تَرْكُه أوْلى.","link":"https://binbaz.org.sa/fatwas/23293/حكم-لبس-ثياب-من-جلد-الخنزير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم لبس ما كان من نوع جلد من الخنزير.mp3","categories":["اللباس والزينة"]},{"id":3134,"question":"الإسراف في إطالة العمامة خمسة أمتار أو أربعة؟","title":"ما حكم الإسراف في إطالة العمامة؟","answer":"الجواب: ما أعرف لهذا أصلًا، لا يكون شهرة، بين الكتفين يكفي، يكون طرفها بين الكتفين.","link":"https://binbaz.org.sa/fatwas/23295/ما-حكم-الاسراف-في-اطالة-العمامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الإسراف في إطالة العمامة.mp3","categories":["اللباس والزينة"]},{"id":3135,"question":"متى يُمنع لباس \"البنطلون\" للمرأة؟","title":"حكم لبس \"البنطلون\" للمرأة","answer":"الجواب: \"البنطلون\" لا تَلْبَسه، لباس يشبه الكفار، لا بنطلون ولا غيره، ليس للمرأة أن تتشبَّه بالكفار ولا بالرجال، وليس للرجل أن يتشبَّه بالنساء ولا بالكفار.\nس: وإذا وضعت المرأة فوق البنطلون تنورة؟\nالشيخ: المقصود: لا تتشبَّه بالكفار ولا بالرجال، إذا كان لِباس ما فيه تشبُّه مِنْ لِبْس جماعتها لا بأس، إذا كان لِباس مِن لِبْس الجماعة، أما مِنْ لِبْس الكفار لا أو لِبْس الرجال لا.\nس: يكون من تحت الملابس؟\nالشيخ: تحت أو فوق؛ إذا كان مِن لِبْس الكفار لا.\nس: نهيتم عن لِبْس البنطلون للمرأة؟\nالشيخ: إذا كان الشيء يُشْبِه الرجال أو الكفار، ولو عند الزوج.","link":"https://binbaz.org.sa/fatwas/23296/حكم-لبس-البنطلون-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى يمنع لباس البنطلون للمرأة.mp3","categories":["اللباس والزينة"]},{"id":3136,"question":"والحرير؟","title":"حكم لبس الحرير للرجال وما يجوز منه","answer":"الجواب: لبس الحرير لا يجوز للرجال ولكن للنساء خاصة.\nس: المختلط؟\nالشيخ: أربع أصابع فأقل للرجال، إذا كان قدر أربع أصابع فأقل مثل الرقعة مثل الزرار أشبه أشياء خفيفة.","link":"https://binbaz.org.sa/fatwas/23297/حكم-لبس-الحرير-للرجال-وما-يجوز-منه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم لبس الحرير للرجال وما يجوز منه.mp3","categories":["اللباس والزينة"]},{"id":3140,"question":"الإسبال من الكبائر أو معصية؟","title":"ما حكم إسبال الثياب؟","answer":"الجواب: يُخشى أنه من الكبائر؛ لهذا الوعيد (لم ينظر الله إليه يوم القيامة)، التَّكَبُّر من الكبائر، نسأل الله العافية.\nس: الإمام النووي يرى كراهته في غير الخيلاء؟\nالشيخ: فيه نظر، الصواب أنه محرم مطلقًا، لكن إذا كان مع الخيلاء يكون أشد، ولهذا قال النبي ﷺ: ما أسفل من الكعبين من الإزار فهو في النار ولم يقيّد بالخيلاء، والنصوص يفسر بعضها بعضًا، ولا يُحمل المطلق على المقيّد في هذا، كله وعيد.","link":"https://binbaz.org.sa/fatwas/23302/ما-حكم-اسبال-الثياب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم إسبال الثياب.mp3","categories":["اللباس والزينة"]},{"id":3142,"question":"جعل القميص تحت الركبة بأربع أصابع كما ورد في الحديث؟","title":"حكم جعل القميص تحت الركبة بأربع أصابع","answer":"الجواب: لا، إلى النصف، نصف الساق.\nس: لكن الفعل للكراهة لو فعل؟\nالشيخ: من نصف الساق لا بأس، الأمر واسع إلى الركبة، كله واسع.","link":"https://binbaz.org.sa/fatwas/23304/حكم-جعل-القميص-تحت-الركبة-باربع-اصابع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/جعل القميص تحت الركبة بأربع أصابع.mp3","categories":["اللباس والزينة"]},{"id":3148,"question":"رجل نُصح فقال: عادة قومي أن يُسْبِلوا؟","title":"حكم مَنْ كان الإسبالُ عادةً لقومه","answer":"الجواب: ولوْ كان عادةَ قومه، لا يوافقهم، لا يُسْبِل كما أسْبَلوا، يخالفهم وينصحهم.","link":"https://binbaz.org.sa/fatwas/23310/حكم-من-كان-الاسبال-عادة-لقومه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا كان الإسبال عادة للقوم.mp3","categories":["اللباس والزينة"]},{"id":3149,"question":"الإزار هل يكون على حَدّ الكعب أو يكون دون ذلك؟","title":"ما حَدُّ الإزار حتى لا يكون مُسْبَلًا؟","answer":"الجواب: حَدُّه الكعب.\nس: إذا كان على نفس الكعب؟\nالشيخ: لا يضر، لكن لا ينزل عن الكعب ما أسفل من الكعبين فهو في النار.\nس: لكن لو كان على الكعب ما في حرج؟\nالشيخ: لكن لو رفع عن الكعب يكون أبعد عن الشبهة إلى نصف الساق.\nس: رواية: ولا حظ للكعب من الإزار؟\nالشيخ: جاء في بعض الروايات ولكن أصح منه: ما أسفل من الكعبين فهو في النار رواه البخاري في الصحيح.","link":"https://binbaz.org.sa/fatwas/23311/ما-حد-الازار-حتى-لا-يكون-مسبلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حد الإزار حتى لا يكون مسبلا.mp3","categories":["اللباس والزينة"]},{"id":3150,"question":"عندنا مدرس يأخذ من لحيته ويقول إنه جائز ويستدل بقول الإمام الشافعي أظنه صحيح...؟","title":"ما الرد على مَنْ يجيز الأخذ مِن اللحية؟","answer":"الجواب: يُنصح يُنصح، ما لأحد كلام مع السنة، الرسول ﷺ يقول: قصوا الشوارب، ووفروا اللحى، خالفوا المشركين.\nس: الشافعي يقول: أنه جائز الأخذ؟\nالشيخ: ولو، ولو، يُعَلّم، الشافعي وغير الشافعي ما هو بحجة في مخالفة السنة، لا الشافعي ولا غيره.\nس: يقول: المشايخ ابن باز وابن عثيمين يستدلّون بقول الإمام أحمد؟\nالشيخ: إذا قال رسول الله انتهى، لا أحمد ولا غيره، لا الشافعي ولا غيره، ابن عباس: (يوشك أن تنزل عليكم حجارة من السماء أقول قال رسول الله، وتقولون قال أبو بكر وعمر) أبو بكر وعمر وينهم، وأين الشافعي وأحمد؟ أبو بكر وعمر أعظم من الشافعي وأحمد وأبي حنيفة ومالك، أنكر عليهم ابن عباس لما خالفوا السنة لقول أبي بكر وعمر.","link":"https://binbaz.org.sa/fatwas/23312/ما-الرد-على-من-يجيز-الاخذ-من-اللحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الاستدلال على جواز الأخذ من اللحية بقول الشافعي.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":3152,"question":"لبس الخاتم ما حكمه؟","title":"ما حكم لبس الخاتم للرجال؟","answer":"الجواب: لا بأس به، خاتم من الفضة، لا بأس، ما هو سنة، جائز.\nس: الرسول ﷺ هل ورد أنه لبس الذهب، خاتم الذهب؟\nالشيخ: نعم ثم طرحه ثم لبس الفضة ﷺ.\nس: ذهب أبيض..؟\nالشيخ: لا، فضة، فضة، لما رأى رجلًا في يده خاتم من ذهب طرحه وقال: يعمد أحدكم إلى جمرة من نار فيضعها في يده ونهى عن التختم بالذهب ﷺ.","link":"https://binbaz.org.sa/fatwas/23314/ما-حكم-لبس-الخاتم-للرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم لبس الخاتم من الذهب أو الفضة.mp3","categories":["اللباس والزينة"]},{"id":3153,"question":"المرأة رفعته (ثوبها) متعمدة؟","title":"حد الإسبال للرجال والنساء","answer":"الجواب: لا يجوز لها، ولا يجوز لها إبداء قدمها؛ لأنها من العورة، تُنصح.\nس: زيادة المرأة عن الذراع يكون من الإسبال؟\nالشيخ: ما يجوز، النبي ﷺ قال: ولا يزدن على ذلك الحد ذراع.\nس: وفي رواية: حد الركبة بأربعة أصابع؟\nالشيخ: جاء في رواية، لكن نصف الساق أثْبَت.\nس: قول المصنف في الترجمة: وكره ذلك لغير؟\nالشيخ: هذا قوله ورأيه رحمه الله، وهو ضعيف، والصواب تحريم الإسبال مطلقًا، لكن مع الخيلاء يكون الإثم أشد.\nس: يحتجون بحديث أبي بكر إنك لست منهم؟\nالشيخ: هذا كان يغلبه -يغلب أبا بكر- ما هو قصده الخيلاء، يغلبه ولا يرخيه، أما هؤلاء يتعمدون إرخاءه.\nس: إذا كان في نصف الكعب هل يعتبر إسبالًا؟\nالشيخ: الإسبال ما تحت الكعب، لكن كونه فوق الكعب أبعد عن الشر؛لأن الرسول قال: ما أسفل من الكعبين من الإزار فهو في النار يُسمى إسبال.","link":"https://binbaz.org.sa/fatwas/23315/حد-الاسبال-للرجال-والنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حد الإسبال للرجال والنساء.mp3","categories":["اللباس والزينة"]},{"id":3154,"question":"استعمال الماس للرجال؟","title":"حكم استعمال الماس للرجال","answer":"الجواب: الماس لا بأس به، مثل الفضة، المُحَرّم الذهب.","link":"https://binbaz.org.sa/fatwas/23316/حكم-استعمال-الماس-للرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم استعمال الماس للرجال.mp3","categories":["اللباس والزينة"]},{"id":3161,"question":"موضع قدر الأصبع -أحسن الله إليك- والزرار؟","title":"ما الحدُّ الجائز من الحرير للرجال؟","answer":"الجواب: أصبعين أو ثلاث أو أربع من الحرير الرقعة.\nس: من غير حاجة؟\nالشيخ: إذا دعت الحاجة إليها.\nس: لكن من غير حاجة يجوز...؟\nالشيخ: ما حد حاطها إلا لحاجة، المقصود موضع أصبعين أو ثلاث قد رخص فيها النبي ﷺ.","link":"https://binbaz.org.sa/fatwas/23324/ما-الحد-الجاىز-من-الحرير-للرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحد الجائز لبسه من الحرير.mp3","categories":["اللباس والزينة"]},{"id":3163,"question":"تحريم الذهب المحلق؟","title":"ما حكم الذهب المُحَلّق؟","answer":"الجواب: الذهب مُحَرّمٌ على الذكور، مباح للنساء، سواء حَلَقة أو ما هو بحَلَقة.","link":"https://binbaz.org.sa/fatwas/23326/ما-حكم-الذهب-المحلق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الذهب المحلق.mp3","categories":["اللباس والزينة"]},{"id":3164,"question":"بالنسبة لأربع أصابع في الحرير، العلة في التحليل؟","title":"ما علة تحليل أربع أصابع في الحرير؟","answer":"الجواب: لأنه قد يحتاجه الإنسان، رقعة أو زرار أو ما أشبه، من رحمة الله، هذا من تيسير الله جل وعلا.","link":"https://binbaz.org.sa/fatwas/23327/ما-علة-تحليل-اربع-اصابع-في-الحرير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/علة تحليل أربع أصابع في الحرير.mp3","categories":["اللباس والزينة"]},{"id":3366,"question":"ترجيل الشعر مع استخدام الزيت أو بدون؟","title":"حكم تَرْجيل الشعر يوميًا مع دهنه","answer":"الجواب: ما فيه شيء، إيش المانع من الدهان؟\nس: إذا كان يغسل شعره يوميًّا هل يدخل في النهي عن الترجيل؟\nالشيخ: السنة غِبًّا، سواء كان بالزيت أو بغير زيت.\nس: كيف نجمع بين نهي الرسول ﷺ وإذنه لأبي قتادة؟\nالشيخ: هذا خاص لأبي قتادة.\nس: وقول الرسول ﷺ من كان له شعر فليكرمه؟\nالشيخ: لا أعرف عن سنده، لكن هذا ثابت عن النبي ﷺ من جهة الفعل، أما من كان له شعر... يحتاج إلى مراجعة السند، فِعْلُ النبي كافٍ ﷺ.","link":"https://binbaz.org.sa/fatwas/23533/حكم-ترجيل-الشعر-يوميا-مع-دهنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في ترجيل الشعر.mp3","categories":["اللباس والزينة"]},{"id":3449,"question":"امرأة تستعمل دواء للرأس، وفيه نسبة قليلة من الكحول، فهل يجوز هذا؟","title":"حكم الكحول في الطِّيب والدواء","answer":"الجواب: إذا كان فيه مُسكر ما يَصلح أن تداوَى به: ما أسكر كثيره فقليله حرام.\nس: استعمال هذا الشيء الذي فيه نسبة قليلة من الكحول لو كان خارج البدن، لا يؤكل، لا يشرب؟\nالشيخ: ولو، يُمنع، ظاهر السنة المنع؛ لأن وجوده وسيلة إلى استعماله في الشرب، والأكل.\nس: ما ينسب لشيخ الإسلام -رحمه الله- أنه أجاز هذا؟\nالشيخ: ما يظهر لي، ما كان يُسكر لا يُستعمل، ما كان فيه مُسكر لا يُستعمل، لا دهون، ولا في الرأس، ولا في الأدوية عباد الله تداووا، ولا تداووا بحرام.\nس: كذا الأطياب التي فيها نسبة من الكحول يا شيخ؟\nالشيخ: نعم، فيما بلغنا الكولونيا التي يسمونها الكولونيا فيها إسبرت، ومسكر.\nس: بعضها نسبة قليلة؟\nالشيخ: إذا وجد شيء يُسكر فيُترك، لا يُستعمل إذا عرف أن فيها مُسكر ًا من المسكرات التي يتعاطاها الناس.\nس: قوله ﷺ: وكل مسكر حرام، التداوي، واستعماله؟\nالشيخ: كل مسكر خمر، وكل مسكر حرام ما أسكر كثيره فقليله حرام عام.","link":"https://binbaz.org.sa/fatwas/23624/حكم-الكحول-في-الطيب-والدواء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم استعمال الطيب والدواء فيه نسبة من الكحول.mp3","categories":["اللباس والزينة","الطب والتداوي"]},{"id":3539,"question":"قول العلامة ابن القيم: إن العورة عورتان، عورة مغلّظة، وعورة مخفّفة، الفخذان عورة مخفّفة؟","title":"حكم ستر الفخذينللكبير والصغير","answer":"الجواب: لا شك أن العورة \"القُبُل والدُّبُر\" عورة مغلّظة، ولكن الفخذ حِماها، الفخذ حِمَىً للعورة المغلظة.\nوالصواب أنها عورة، والأحاديث الثلاثة يشدّ بعضها بعضًا حديث محمد بن جحش، وجرهد، وابن عباس، يشدّ بعضها بعضًا فتكون ناسخة لما وقع منه ﷺ.\nس: الذي يلبس سروالًا قصيرًا، عليه ثوب شفاف؟\nالشيخ: ما يجوز هذا، لا بدّ من ستر الفخذين.\nس: الصبي يستر الفخذ؟\nالشيخ: إذا بلغ الحُلُم، لكن سترها إذا كان ابن  عشرة أو نحوها أحوط وأحسن، وأبعد عن الفتنة.","link":"https://binbaz.org.sa/fatwas/23721/حكم-ستر-الفخذين-للكبير-والصغير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/العورة عورتان مغلظة، ومخففة فهل الفخذ عورة مخففة.mp3","categories":["ستر العورة للمصلي","اللباس والزينة"]},{"id":3625,"question":"حديث: ما زال جبريل يوصيني بالسواك حتى خشيت على أسناني؟","title":"هل صح حديث (حتى خشيت على أسناني)؟","answer":"الجواب: ما أعرفه.","link":"https://binbaz.org.sa/fatwas/23808/هل-صح-حديث-حتى-خشيت-على-اسناني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسائل في السواك.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":3677,"question":"يعني -أحسن الله إليك- السِّتْر الذي لا حاجة إليه.. الستائر التي على النوافذ؟","title":"حكم الستائر على الجدران والنوافذ","answer":"الجواب: النوافذ لا بأس بها؛ لكن على الجدران لا، مثل ما قال: متى صارت الكعبة عندكم.. أما إذا كان على النوافذ لا بأس مثل ما يُحطّ على الأبواب.\nس: عائشة عندما وضعت الستر، النبي ﷺ أنكر الصورة، ولم ينكر الستر؟\nالشيخ: هذا على الباب موضوع، الستر على الباب وعلى الطاقات ما يخالف.","link":"https://binbaz.org.sa/fatwas/23866/حكم-الستاىر-على-الجدران-والنوافذ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الستائر التي لا حاجة إليها.mp3","categories":["اللباس والزينة"]},{"id":3679,"question":"يشمل هذا السُّقُف والجدران.. المبالغة في تزيينها؟","title":"حكم تزيين السُّقُف والجدران","answer":"الجواب: الأقرب -والله أعلم- أنه يُكره إذا كان للزينة، أما إذا كان للسُّقُف أو لأسباب أخرى فلا بأس؛ مثل ما تُسقف بالحجارة أو بالخشب أو بغيره، أما الجدران إذا كان للزينة فهذا هو المكروه.","link":"https://binbaz.org.sa/fatwas/23868/حكم-تزيين-السقف-والجدران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم ستر السقف ونحوه للزينة.mp3","categories":["اللباس والزينة"]},{"id":3701,"question":"الذي يخاف على نفسه مثلًا يقول: إذا لم أحلق لحيتي قد أسجن؟","title":"حكم حلق اللحية لمن خاف على نفسه","answer":"الجواب: لا، هذا من الشيطان ومن تخويف الشيطان، أما إذا أُكره فالإكراه بابه معروف حتى في الشرك: مَنْ كَفَرَ بِاللَّهِ مِنْ بَعْدِ إِيمَانِهِ إِلَّا مَنْ أُكْرِهَ [النحل: 106] الإكراه الذي فيه الضرب.. الإكراه له حكمه.\nس: لا، هو يخاف؟\nالشيخ: لا، ما هو بعذر، العذر الإكراه بس.\nس: الإكراه يكون بالفعل؟\nالشيخ: يكون بالضرب والسجن والتهديد من قادر.","link":"https://binbaz.org.sa/fatwas/23891/حكم-حلق-اللحية-لمن-خاف-على-نفسه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم حلق اللحية لمن خاف على نفسه.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":3722,"question":"حلق اللحية من التخنث؟","title":"هل حلق اللحية من التخنث؟","answer":"الجواب: قد يُلحق بذلك، لكن أمره خاص، حلق اللحية محرم مطلقًا ولو ما قصد التخنث، يحرم عليه حلقها مطلقًا، وإذا أراد التخنث صار شرًّا إلى شر.","link":"https://binbaz.org.sa/fatwas/23914/هل-حلق-اللحية-من-التخنث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل حلق اللحية من التخنث.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":3737,"question":"بيع الملابس المتبرجة...؟","title":"ما حكم بيع الملابس المتبرجة؟","answer":"الجواب: هذا يختلف: إذا كنت تعلم أنهن يلبسن ذلك على صفة تخالف الشرع لا تبع عليهن.  وإذا كنت لا تعلم، واللباس يصلح لهذا وهذا، قد يكون تحت الثياب، ما يلزم يكون فوق الثياب، قد يكون تحت الثياب أو عند الزوج، فالأمر فيه تفصيل.","link":"https://binbaz.org.sa/fatwas/23929/ما-حكم-بيع-الملابس-المتبرجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/بيع الملابس المتبرجة.mp3","categories":["البيوع","اللباس والزينة"]},{"id":3771,"question":"استعمال الشامبو الذي إذا استعمله الإنسان ذهب بالشيب، الشعر الأسود ما يكون من جنس السواد؟","title":"حكم استعمال \"الشامبو\" الذي يذهب بالشيب؟","answer":"الجواب: ... يستعمل دواء ما يبيّض، ما يجيه الشيب.\nس: لكن لو كان فيه شيب؟\nالشيخ: لا، هذا يصير صبغ أسود ما يصلح.","link":"https://binbaz.org.sa/fatwas/23967/حكم-استعمال-الشامبو-الذي-يذهب-بالشيب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/استعمال الشامبو الذي إذا استعمله الإنسان ذهب بالشيء.mp3","categories":["اللباس والزينة"]},{"id":3836,"question":"الفضة للرجال.. هل فيه تحديد.. الإكثار منها للرجال؟","title":"حكم لبس الفضة للرجال وحَدّ ذلك","answer":"الجواب: ما أعلم فيها إلا الخاتم، وقبيعة السيف، ونحوه، ما أعلم فيه غير هذا، الأواني ممنوعة، ما في إلا الخاتم للرجال، أو ما يتعلق بقبيعة السيف ونحوه.\nس: لو تختم بأكثر من خاتم فضة؟\nج: ما أعلم فيه شيئًا... لكن تركه أولى، النبي ﷺ استعمل خاتماً واحداً، والصحابة استعملوا خاتماً واحداً في الخنصر.","link":"https://binbaz.org.sa/fatwas/24038/حكم-لبس-الفضة-للرجال-وحد-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/لبس الفضة للرجال.mp3","categories":["اللباس والزينة"]},{"id":3837,"question":"لو تختم بأكثر من خاتم فضة؟","title":"حكم التختم بأكثر من خاتم فضة للرجال","answer":"الجواب: ما أعلم فيه شيئًا، لكن تركه أوْلى، النبي استعمل خاتمًا واحدًا، والصحابة استعملوا خاتمًا واحدًا، في الخنصر.","link":"https://binbaz.org.sa/fatwas/24039/حكم-التختم-باكثر-من-خاتم-فضة-للرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم التختم بأكثر من خاتم من الفضة للرجال.mp3","categories":["اللباس والزينة"]},{"id":3851,"question":"قد يُقال أن الكحل من السنة؟","title":"هل الاكتحال من السنة؟","answer":"الجواب: يُفيد أنَّ هذا معروف عندهم الكحل، وقد كان النبي ﷺ يكتحل، فالأظهر أنه من السنة، وأنه مشروع في كل عينٍ ثلاثة أميال؛ لأن فيه خيرًا كثيرًا مثلما في الحديث: إنه يُنبت الشعر، ويصفي، وينقي البصر، وهو الطيب الذي هو الإثمد، فيه نفعٌ كثير.\nس: في حقِّ الرجال والنِّساء؟\nج: نعم.","link":"https://binbaz.org.sa/fatwas/24060/هل-الاكتحال-من-السنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الكحل من السنة.mp3","categories":["اللباس والزينة"]},{"id":3870,"question":"ما يُقال أن تحريم الإسبال له سبب.. هو التكبر؟","title":"هل تحريم الإسبال مقيّد بالتكَبُّر؟","answer":"الجواب: هو وسيلة لذلك، وأيش الذي حمله على جرِّه إلا التكبر؟ ما حمله إلا التَّكبر.\nس: إذا كان من الخياط؟\nج: إذا كان من الخياط يغيّر، خليه يرفعه، ترفعه الزوجة، يرفعه أخوه، ما يحملهم إلا التكبر والتساهل في أمر الله، وعدم المبالاة.  ثم هذا فتح باب الإسبال، فتح باب البلاء، ثم بعض الناس ما يبالي إذا كان مكروهًا ما يبالي، عنده المكروه لا بأس، يُرتكب ولا يبالى به.","link":"https://binbaz.org.sa/fatwas/24084/هل-تحريم-الاسبال-مقيد-بالتكبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/علة تحريم الإسبال التكبر.mp3","categories":["شروح الحديث","اللباس والزينة"]},{"id":3871,"question":"مَن يقول إن اللبس إلى نصف الساقين الآن من الشُّهرة؟","title":"هل يُعَدُّ اللبس إلى نصف الساقين من الشُّهرة؟","answer":"الجواب: لا، غلط، إلى نصف الساق جائز، بل هو أفضل عند جماعةٍ من أهل العلم، إلا إذا كان يترتب عليه شيء، يرخيه إلى الكعب، والحمد لله، ولا يعرض نفسه لشيءٍ يُؤذيه، فما بين نصف الساق والكعب كله جائز.","link":"https://binbaz.org.sa/fatwas/24085/هل-يعد-اللبس-الى-نصف-الساقين-من-الشهرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الرد على من يقول أن اللبس إلى نصف الساقين الآن من الشُّهرة.mp3","categories":["شروح الحديث","اللباس والزينة"]},{"id":3872,"question":"الجَيْب الذي يوضع الآن في الصدر يسمى \"جيب\"؟","title":"ما معنى \"الجَيْب\" في الثوب وسبب تسميته؟","answer":"الجواب: هو جَيْبُه، جَيْبٌ متصل بالحلقة التي عند العنق، ما يسمى هذا جَيْبًا إلا لهذا الجَيْب، وهو من الجَوْب وهو الشَّقّ: وَثَمُودَ الَّذِينَ جَابُوا الصَّخْرَ بِالْوَادِ [الفجر:9] يعني شقوا الصخر، جاب البلاد يجوبها: إذا مشى فيها وسار فيها وساح فيها، فالجَوْب: الشَّقّ، يسمى الجَيْبُ جَيْبًا؛ لأنه يُشَقُّ حتى يدخل الرأسُ والمنكبان عند لبس الثوب وعند خلعه.","link":"https://binbaz.org.sa/fatwas/24086/ما-معنى-الجيب-في-الثوب-وسبب-تسميته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تسمية الجيب بهذا الاسم.mp3","categories":["اللباس والزينة"]},{"id":3876,"question":"كيف يكون الإسبال في العمامة؟","title":"كيف يكون الإسبال في العمامة؟","answer":"الجواب: يطوّلها حتى تصل الأرض من وراء.","link":"https://binbaz.org.sa/fatwas/24091/كيف-يكون-الاسبال-في-العمامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كيف يكون الإسبال في العمامة.mp3","categories":["اللباس والزينة"]},{"id":3886,"question":"التحقيق بالتزعفر، ولبس الثوب المعصفر؟","title":"حكم التزعفرولبس الثوب المعصفر للرجال","answer":"الجواب: هو الأظهر، الأظهر مثل ما تقدم، الرجال لا ينبغي لهم التزعفر؛ لأنه من زي النساء، ولأنه قد يسبب الفتنة.  وأما الأحمر فالأفضل أن يكون مخططًا، جمعًا بين الأقوال كالقول السابق، أو يحمل على أنه إذا كان من زي النساء فالنهي عنه لأنه من زي النساء ذاك الوقت، أو كان شهرة كما قال بعضهم، يعني يترك إذا كان فيه علة أخرى تسبب تركه، وإلا فالنبي لبسه عليه الصلاة والسلام. فإذا كان هناك ما يسبب تركه؛ لأنه في وقت ما زي للنساء أو زي للأعاجم أو فيه شهرة ترك، وهذا لا يختص بالأحمر، يعم غيره أيضًا.\nس: القول بأن التزعفر نهي خاص بالمحرم؟\nج: ما هو خاص بالمحرم.","link":"https://binbaz.org.sa/fatwas/24102/حكم-التزعفرولبس-الثوب-المعصفر-للرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/لا ينبغي للرجال التزعفر، ولا لبس الثوب المعصفر.mp3","categories":["اللباس والزينة"]},{"id":3888,"question":"يجوز للرجل أن يُضَفِّر رأسه؟","title":"هل يجوز للرجل أن يُضَفِّر رأسه؟","answer":"الجواب: نعم، ما في بأس، كان النبي يتَّخذه إلى اللمة -إلى المنكب- وليس فيه نهي، لا أعلم فيه نهيًا، إلا إذا عُرف من صاحبه أنه يتعرض للنساء ويقصد الشرَّ، فحينئذٍ يُمنع، كما فعل عمر لما بلغه أنَّ نصر بن الحجاج تعرض للنساء أمر بحلق رأسه.","link":"https://binbaz.org.sa/fatwas/24104/هل-يجوز-للرجل-ان-يضفر-راسه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز للرجل أن يُضفر رأسه.mp3","categories":["اللباس والزينة"]},{"id":3889,"question":"بعض الناس يُرَبِّي شعر رأسه ويحلق لحيته؟","title":"حكم مَنْ يُرَبِّي شعر رأسه ويحلق لحيته","answer":"الجواب: التربية شيء، وحلق اللحية شيء، حلق اللحية محرم، وتربية الرأس جائزة، ما هي محرمة، ولا مشروعة متأكدة، لكن حلق اللحية محرم.","link":"https://binbaz.org.sa/fatwas/24105/حكم-من-يربي-شعر-راسه-ويحلق-لحيته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من يُربي شعر رأسه ويحلق لحيته.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":3890,"question":"ما يدخل التوالتيت في القزع المعروف؛ لأنه تخفيف، يُخفف من الوراء ويترك الذي قدامه، أو يُخفف الذي قدام ويترك الذي وراء؟","title":"ما صفة القزع المنهي عنه؟","answer":"الجواب: أخشى، ليس هو القزع، لكن أخشى أن يكون من باب التَّشويه، فالذي ينبغي تركه؛ لأنه يُشبه القزع، وليس هو القزع، لكن يُشبهه.","link":"https://binbaz.org.sa/fatwas/24106/ما-صفة-القزع-المنهي-عنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يدخل التوالتيت في القزع.mp3","categories":["اللباس والزينة"]},{"id":3891,"question":"ما حكم القَزَع؟","title":"حكم القَزَع (حلق بعض الرأس وترك بعضه)","answer":"الجواب: المشهور عند العلماء الكراهة، والأصل في النَّهي التحريم، هذا هو الأصل، النووي ذكر عن العلماء كراهة ذلك، ولكن قد يُقال: ما هو الصارف؟\nس: من قال إن حلق القفا من أفعال المجوسية، هل في دليل على هذا؟\nج: الله أعلم، يكفي أن الرسول ﷺ نهى عن هذا، ويكفي.","link":"https://binbaz.org.sa/fatwas/24107/حكم-القزع-حلق-بعض-الراس-وترك-بعضه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم القزع.mp3","categories":["اللباس والزينة"]},{"id":3905,"question":"حكمه يُقال الحرمة أو الكراهة: من لبس ساعة فيها صليب؟","title":"حكم لبس ساعة فيها صليب","answer":"الجواب: لا، ممنوع، هذا ما يجوز، يُغطى هذا الصليب بشيءٍ؛ بحكٍّ، أو يجعل عليه شيئًا من الدواء يزيله: من بُوية أو غيره. س: إذا كان غير مقصودٍ؟ ج: ولو غير مقصودٍ، النبي ما ترك شيئًا فيه تصليب إلا قضبه، الساعة التي فيها تصليب لا بدّ أن يشقوا الصليب منها، أو يحطوا عليها شيئًا من البويه تُخفيه.","link":"https://binbaz.org.sa/fatwas/24122/حكم-لبس-ساعة-فيها-صليب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من لبس ساعة فيها صليب.mp3","categories":["اللباس والزينة"]},{"id":4041,"question":"كشف الفخذ من العورة؟","title":"هل الفخذ من العورة؟","answer":"الجواب: نعم، الفخذ من العورة.","link":"https://binbaz.org.sa/fatwas/24277/هل-الفخذ-من-العورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الفخذ من العورة.mp3","categories":["ستر العورة للمصلي","اللباس والزينة"]},{"id":4045,"question":"مَنْ لم يختتن يأثم؟","title":"هل يأثم مَنْ لم يختتن؟","answer":"الجواب: الجمهور على السنية، وذهب أحمد رحمه الله وابن عباس وجماعة إلى الوجوب.\nس: من لم يختتن يأثم؟\nالشيخ: من قال بالوجوب يأثم، ومن قال بأنه سنة لا يأثم، والذي ينبغي: فعله، كما قال ابن عباس وشدد فيه، وقال النبي لبعض الصحابة لما أسلم: ألق عنك شعر الكفر واختتن لكن في سنده ضعف.","link":"https://binbaz.org.sa/fatwas/24282/هل-ياثم-من-لم-يختتن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يأثم من لم يختتن.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":4046,"question":"اختتان النساء؟","title":"ما حكم اختتان النساء؟","answer":"الجواب: يستحب، إذا تيسر من يحسن ذلك.\nس: دليل اختتان النساء؟\nالشيخ: العموم، الفطرة خمس، وجاء في بعض الروايات التصريح بذلك.\nس: المرأة تختتن ولو كبرت؟\nالشيخ: إذا كان ما يخشى الخطر على الكبير: الرجل والمرأة، أما لو كان يخشى شيء؛ يسقط.","link":"https://binbaz.org.sa/fatwas/24283/ما-حكم-اختتان-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة اختتان النساء.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":4052,"question":"بياض إبطيه هل هذا خاص بالنبيﷺ أم أنه نفس الإبط؟","title":"\"بياض إبطيه\" هل هو خاص بالنبي ﷺ؟","answer":"الجواب: قال بعضُهم: إنه خاص، وقال بعضُهم: إنه كان يتعاهد أخذ شعر الإبط عليه الصلاة والسلام، والسنةُ تعاهد ذلك.\nس: ما جاء في الحديث العفرة..؟\nج: العفرة بمعنى البياض.","link":"https://binbaz.org.sa/fatwas/24289/بياض-ابطيه-هل-هو-خاص-بالنبي-ﷺ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/بياض إبطيه خاص بالنبي.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":4172,"question":"حلق اللِّحَى هل يدخل في التَّشبه بالنساء؟","title":"هل يدخل حلق اللحية في التشبه بالنساء؟","answer":"الجواب: الحلق الكامل يصير تشبُّهًا، المرأة لا لحيةَ لها، الحلق الكامل الذي يُزيل الشعر كله تشبُّه بالنساء، مع أنه تشبّه بالكفار أيضًا، فيه تشبه بالكفار وفيه تشبه بالنساء، إذا استوفى حلقه يُخشى عليه من اللعنة، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/24428/هل-يدخل-حلق-اللحية-في-التشبه-بالنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل حلق اللحية من التشبه بالنساء.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":4173,"question":"حديث ابن عمر الذي يقول القبضة؟","title":"حكم أخذ قدْر القبضة من اللحية","answer":"الجواب: هذا من عمله، هذا غلط، هذا من فعله واجتهاده، الصواب إعفاؤها، ولا يُؤخذ منها شيء، ولو ما زاد على القبضة، فاجتهاده  مخالف لما ورد، فلا يأخذ ما زاد على القبضة .....، الرسول ﷺ أمر بإعفائها وإرخائها، وأما فعل ابن عمر في الحجِّ فهذا من اجتهاده، والأئمة غلَّطوه في هذا .","link":"https://binbaz.org.sa/fatwas/24429/حكم-اخذ-قدر-القبضة-من-اللحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم أخذ القبضة من اللحية.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":4174,"question":"هو سنة... الخضاب؟","title":"حكم الخضاب وتغيير الشيب","answer":"الجواب: الخضاب سنة مؤكدة...، لكن صرفه عن الوجوب ما ثبت عنه ﷺ أنه رُئِيَ في أوقات كثيرة والشعرات بيض لم تغير، وهكذا ما رُوي عن جماعةٍ من الصحابة أنهم تركوا الشيب، فلا شكَّ أنَّ له مؤونة قد يغفل عنه الإنسان، وقد يتساهل فيه في بعض الأوقات، في المشاغل التي قد تعرض، فالأظهر والأقرب أنه سنة مؤكدة.\nس: الحناء الأسود؟\nج: كل شيء يكون أسود خالصًا لا يصلح؛ لأنه ثبت عن النبي ﷺ من وجوهٍ كثيرةٍ النهي عن تغيير الشيب بالسواد: من حديث جابر، وحديث أنس، وأحاديث أخرى كلها دلَّت على تحريم التغيير بالسواد، ومنها حديث ابن عباس الذي عند النسائي: يكون في آخر الزمان قومٌ يخضبون بالسواد كحواصل الحمام، لا يريحون رائحة الجنة. رواه أحمد، وأبو داود، والنسائي بإسنادٍ جيدٍ عن ابن عباس.\nوقد صنَّف بعضُ إخواننا الآن... جمع الأحاديث الواردة في هذا في جزء لا بأس به، عُرض عليَّ، جيد، جمع الأحاديث الواردة في هذا كلها.","link":"https://binbaz.org.sa/fatwas/24430/حكم-الخضاب-وتغيير-الشيب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/خضاب اللحية وتغيير الشيب فيها.mp3","categories":["اللباس والزينة"]},{"id":4176,"question":"قوله: من ذهب أو فضة؟","title":"هل صح اتخاذ النبي ﷺ خاتمًا من ذهب؟","answer":"الجواب: شكٌّ من الراوي، والصواب: من ذهبٍ، هذا المحفوظ، اتَّخذه من ذهبٍ، ثم طرحه، واتَّخذ خاتمًا من فضَّةٍ.\nوكان رواه مسلم في \"الصحيح\" أنه ربما لبسه في اليمين، وربما لبسه في اليسار عليه الصلاة والسلام، فيدل هذا على أنَّ الأفضل أن يكون فصُّه من الداخل، ويُشبه هذا الساعة؛ فإنها من جنس هذا، لا بأس أن تكون في اليمين، ولا بأس أن تكون في اليسار؛ لأنها لحاجةٍ مثل الخاتم.","link":"https://binbaz.org.sa/fatwas/24432/هل-صح-اتخاذ-النبي-ﷺ-خاتما-من-ذهب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث أن رسول الله اتخذ خاتما من ذهب أو فضّة..mp3","categories":["شروح الحديث","اللباس والزينة"]},{"id":4177,"question":"اتخاذ الخاتم سنة أو مباح؟","title":"حكم اتخاذ الخاتم","answer":"الجواب: الأقرب - والله أعلم - أنه سنة لولاة الأمور، وأما عامَّة الناس فقصاراه أن يكون مباحًا، لكن لولاة الأمور سنة؛ تأسيًا بالنبي ﷺ، والآن يختمون به في الوثائق والأوامر، قد جاء في رواية أبي داود من حديث أبي ريحانة: النَّهي عن اتِّخاذه إلا لذي سلطانٍ، وفي صحَّته نظر، لكنه محمول على هذا المعنى لو صحَّ.","link":"https://binbaz.org.sa/fatwas/24433/حكم-اتخاذ-الخاتم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم اتخاذ الخاتم.mp3","categories":["اللباس والزينة"]},{"id":4269,"question":"الساعة المطلية بالذهب حكم لبسها؟","title":"حكم لبس الساعة المطلية بالذهب","answer":"الجواب: تصلح للنساء، أما الرجال لا.","link":"https://binbaz.org.sa/fatwas/24539/حكم-لبس-الساعة-المطلية-بالذهب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم لبس الساعة المطلية بالذهب.mp3","categories":["اللباس والزينة"]},{"id":4271,"question":"ما حكم وضع الحناء على الرأس الذي فيه شيب؟","title":"حكم تغيير شيب الرأس والشارب بالحناء","answer":"الجواب: السنة أن يغير الرأس واللحية إذا شاب، السنة التغيير لكن بغير السواد، بالصفرة بالحمرة أو بين السواد والحمرة، لما رأى النبي رأس أبي قحافة والد الصديق رأسه ولحيته كالثغامة بياضًا قال: غيروا هذا الشيب، يعني: الرأس واللحية جميعا، واجتنبوا السواد.\nس: والشارب؟\nج: مثله، دربه درب اللحية.","link":"https://binbaz.org.sa/fatwas/24541/حكم-تغيير-شيب-الراس-والشارب-بالحناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تغيير شيب الرأس والشارب بالحناء.mp3","categories":["اللباس والزينة"]},{"id":4318,"question":"في واحد يسأل يقول: زوجته تستخدم السحر عشان تحبه، وهذا يسأل يقول: هل يجوز يطلقها لهذا السبب، وله أربعة أولاد منها؟","title":"هل تُطلَّق الزوجة لعملها سحر جلب المحبة؟","answer":"الجواب: إن كان متأكدًا، ولكن بعض الناس عندهم وساوس. المقصود إذا كان يتهمها بهذا فراقها أسلم له، يطلقها، هذا خير له، إذا كانت تهمتها قوية.  وبعض الناس عنده وساوس، ما هي بتهمة لكن وساوس يظن أنها تفعل، زوجته تحبه كثيرًا يظنها تعمل له شيئًا.  المقصود إذا كان هناك أمارات واضحة فيطلقها ويسلم من شرها، طلقة واحدة.","link":"https://binbaz.org.sa/fatwas/24592/هل-تطلق-الزوجة-لعملها-سحر-جلب-المحبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا استخدمت الزوجة السحر لأجل المحبة، هل يطلقها.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":4438,"question":"تقليم الأظافر يعني خاصّ بالرجال؟","title":"هل تقليم الأظفار خاصّ بالرجال؟","answer":"الجواب: لا، للرجال والنساء جميعًا، سنة قلم الأظفار ونتف الإبط وحلق العانة للجميع، للرجال والنساء.","link":"https://binbaz.org.sa/fatwas/24716/هل-تقليم-الاظفار-خاص-بالرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تقليم الأظافر يعني خاصّ بالرجال فقط.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":4439,"question":"الكالونيا...؟","title":"ما حكم استعمال الكالونيا وأثرها على الوضوء؟","answer":"الجواب: الكالونيا لا ينبغي استعمالها؛ لأنَّ فيها... مُسْكِر.\nس: هل هي نجاسة عينية؟\nج: المقصود أنها ممنوعة؛ لأنَّ فيها مسكر، والجمهور يرونها نجسة، جمهور أهل العلم يقولون: كل مسكر نجس.\nس: يجب غسلها قبل الوضوء؟\nج: إذا غسلها احتياطًا حسن، لكن لا يستعملها أصلًا، لا يجوز استعمالها أصلًا.","link":"https://binbaz.org.sa/fatwas/24717/ما-حكم-استعمال-الكالونيا-واثرها-على-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/استعمال الكالونيا.mp3","categories":["اللباس والزينة"]},{"id":4440,"question":"تزيين المرأة لزوجها فيه صبغ الوجه بالأصباغ المعروفة؟","title":"حكم تزيّن المرأة لزوجها بالأصباغ المعروفة","answer":"الجواب: إذا كان ما يضرّ ما يضرّ، إذا كان صبغًا لا يضرّ، يُلون الوجهَ ولكن لا يضرّ بالوجه.","link":"https://binbaz.org.sa/fatwas/24718/حكم-تزين-المراة-لزوجها-بالاصباغ-المعروفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تزيين المرأة لزوجها بالأصباغ المعروفة.mp3","categories":["اللباس والزينة"]},{"id":4449,"question":"العمامة هل تُعتبر سنة؟","title":"هل لبس العمامة سنة؟","answer":"الجواب: كانت من سنة العرب، كثير من أهل العلم يقولون: اللباس لا يدخل في السنة والبدعة؛ لأنه من العوائد ... فلا بأس، ومَن تركها فلا بأس، من عوائد العرب قبل الشرع.\nس: هل يُطلق عليها سنة الرسول ﷺ؟\nج: الله أعلم.","link":"https://binbaz.org.sa/fatwas/24727/هل-لبس-العمامة-سنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يقال أن لبس العمامة سنة.mp3","categories":["اللباس والزينة"]},{"id":4513,"question":"الفانلة العلاقية...؟","title":"هل الفانلة العلاقية تستر العاتق في الصلاة؟","answer":"الجواب: إذا كانت تستر المنكبين، أو أحد المنكبين. أما الخيط ما أظن أنه يكفي، ما أعتقد أنه يكفي؛ لأنه ليس بساترٍ.","link":"https://binbaz.org.sa/fatwas/24793/هل-الفانلة-العلاقية-تستر-العاتق-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/لا يصل أحدُكم في الثوب الواحد ليس على عاتقه منه شيء، الصلاة بالفانلة العلاقية.mp3","categories":["ستر العورة للمصلي","اللباس والزينة"]},{"id":4514,"question":"يُستحب أن يُعيد إذا صلَّى وعاتقاه مكشوفان مع القُدرة؟","title":"ما حكم من صلى وعاتقاه مكشوفان؟","answer":"الجواب: إذا قلنا بالوجوب وجب أن يُعيد إذا تعمَّد، أما إذا كان جاهلًا قد يُعفى عنه، لكن إذا قلنا بالوجوب -كما هو مذهب أحمد وجماعة- وجوب ستر العاتقين أو أحدهما لحديث أبي هريرة.\nس: ما يأثم...؟\nج: يأثم... إذا قلنا بالوجوب، وهو الأظهر، وهو الأحوط؛ لأن الأصل في الأوامر الوجوب، والأصل في النهي التحريم، هذا هو الأصل؛ ولأن الناس عند سماع الاستحباب وعند اعتقاد الاستحباب يغلب عليهم التَّساهل، وهذه أوامر ونواهٍ ما ينبغي فيها التَّساهل.\nس: الكتف ليس من العورة... عورته مستورة، والكتف ليس منها؟\nج: لكن الرسول ﷺ أمر بسترها عند القُدرة قال: فإن كان واسعًا فالتحف به، وخالف بين طرفيه، و لا يُصلِّ أحدُكم بالثوب الواحد ليس على عاتقه منه شيء –أو: عاتقيه كما في \"الصحيحين\"، فينبغي الجمع بين هذا وهذا.\nس: مَن قال: يأثم ولا يُعيد؛ لأنها ليست عورةً؟\nج: الأقرب -والله أعلم- أنه إذا تعمَّد وتساهل أنه يُعيد، أما إن كان عن جهلٍ وخرج الوقت فالأمر أوسع.","link":"https://binbaz.org.sa/fatwas/24794/ما-حكم-من-صلى-وعاتقاه-مكشوفان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يعيد الصلاة من صلى وعاتقاه مكشوفان.mp3","categories":["ستر العورة للمصلي","اللباس والزينة"]},{"id":4515,"question":"مَن رأى عورته وقت الصلاة هل تبطل صلاته؟","title":"هل تبطل صلاة من رأى عورته وقت الصلاة؟","answer":"الجواب: لا، ما تبطل، لكن ينبغي له أن يعتني بها، يعتني بزر الثوب، أو تصغير الجيب، أو لفّ شيء عليه حتى لا يرى عورته، أو تكون عليه سراويل أو إزار تحت الثوب، يعني ما يُسمَّى: مكشوف العورة.","link":"https://binbaz.org.sa/fatwas/24795/هل-تبطل-صلاة-من-راى-عورته-وقت-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تبطل صلاة من رأى عورته وقت الصلاة.mp3","categories":["ستر العورة للمصلي","اللباس والزينة"]},{"id":4516,"question":"الحرير الصناعي ما حكمه؟","title":"ما حكم الحرير الصناعي؟","answer":"الجواب: المقصود الحرير المعروف المستخرج من دودة القز، المعروف عند الناس. أما الملابس اللينة من الصناعات ومن الخارج عن الأرض فلا تدخل في ذلك، لكن المؤمن على كل حالٍ ينبغي له أن تكون ملابسه بعيدة عن ذلك، وفيها خشونة؛ لأنَّ هذه الملابس أليق بالنساء، وهو أليق به الملابس القوية، والتي فيها بعض الخشونة.","link":"https://binbaz.org.sa/fatwas/24796/ما-حكم-الحرير-الصناعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما حكم الحرير الصناعي.mp3","categories":["اللباس والزينة"]},{"id":4517,"question":"ما الدليل على تحريم جلود السباع والنُّمور؟","title":"ما دليل تحريم جلود السباع والنُّمور؟","answer":"الجواب: الأحاديث الواردة في ذلك في النَّهي عن ركوبها وعن افتراشها.\nس: يعني العلَّة من تحريم الجلود هو الخشية أن يُؤكل لحمها؟\nج: الله أعلم، علينا أن نتبع، ويكفي علينا أن نتبع الرسول ﷺ، قد يكون ذلك أنه وسيلة إلى التَّساهل بأكلها، وقد يكون هناك شيء آخر.","link":"https://binbaz.org.sa/fatwas/24797/ما-دليل-تحريم-جلود-السباع-والنمور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/علة تحريم جلود السباع والنُّمور.mp3","categories":["اللباس والزينة"]},{"id":4518,"question":"أزياء المسلمين كثيرة ..... الكفار، فمتى يكون الإنسان مُتشبِّهًا بالكفار؟ ومتى يكون غير متشبّه؟","title":"متى يكون المسلم مُتشبِّهًا بالكفار في لباسه؟","answer":"الجواب: زيّهم الخاص الذي ما هو من المسلمين، زيهم الخاص الذي ما يفعله المسلمون، فما اشترك فيه المسلمون وهم ما يصير تشبّه، إنما هذا في الزي الخاص بهم، مثل: أعيادهم وأشباهه.","link":"https://binbaz.org.sa/fatwas/24798/متى-يكون-المسلم-متشبها-بالكفار-في-لباسه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مع تنوع الألبسة، متى يكون المسلم مُتشبِّهًا بالكفار في لباسه.mp3","categories":["اللباس والزينة"]},{"id":4519,"question":"هل يجوز لبسُ الحرير في الحرّ؟","title":"هل يجوز لبسُ الحرير في الحرّ؟","answer":"الجواب: لا، للحكَّة فقط، لا، ما هو في الحر.","link":"https://binbaz.org.sa/fatwas/24799/هل-يجوز-لبس-الحرير-في-الحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى يجوز لبس الحرير.mp3","categories":["اللباس والزينة"]},{"id":4521,"question":"لبس الفضَّة؟","title":"حكم لبس الفضَّة","answer":"الجواب: لا حرج في ذلك، لا بأس للرجال والنساء جميعًا.","link":"https://binbaz.org.sa/fatwas/24801/حكم-لبس-الفضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم لبس الفضَّة.mp3","categories":["اللباس والزينة"]},{"id":4534,"question":"لبس البياض للنساء؟","title":"حكم لبس البياض للنساء","answer":"الجواب: أصله مباح إذا كان على غير الطريقة التي يلبسها الرجال، لكن بسبب أنه في الغالب من لبس الرجال فينبغي لها تركه، ولهذا يُستنكر منها ذلك؛ لأنه في الغالب يكون فيه شبه ظاهر للرجال؛ لأنَّ الرجال يغلب عليهم البياض، لكن لو لبسته على طريقةٍ خاصةٍ تخصّ النساء ما صار فيه تشبّه، مثلما تلبس الأحمر، وهو يلبس الأحمر والأخضر والأسود، كلهم يلبسونه.","link":"https://binbaz.org.sa/fatwas/24814/حكم-لبس-البياض-للنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم لبس البياض للنساء.mp3","categories":["اللباس والزينة"]},{"id":4812,"question":"بعض أحاديث النهي عن الإسبال جاءت مطلقة، وبعضها مقيدة بالخيلاء، فهل يحمل المطلق على المقيّد؟","title":"هل تحريم الإسبال مقيَّد بالخيلاء؟ وهل يشمل الأكمام؟","answer":"لا، ما يحمل المطلق على المقيد، محرم مطلقًا في كل شيء.\nس: أكمام القميص يدخل فيها الإسبال؟\nج: لا، لا يدخل، ما هو بداخل، الرسول ﷺ قال: ما أسفل الكعبين، هذا هو الإسبال.","link":"https://binbaz.org.sa/fatwas/25212/هل-تحريم-الاسبال-مقيد-بالخيلاء-وهل-يشمل-الاكمام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أحاديث النهي عن الإسبال مطلقة وبعضها مقيدة بالخيلاء فهل يحمل المطلق على المقيد.mp3","categories":["اللباس والزينة"]},{"id":4870,"question":"بما يزال الشيب وما حكم تغيير الشيب بالكتم أو الحناء؟","title":"ما حكم إزالة الشيب وتغييره بالكتم أو الحناء؟","answer":"الشيب لا يُزال، نهى النبي ﷺ عن نتف الشيب، لكن يغير بالصفرة والحمرة، وكذلك ما بين السواد والحمرة، ولا يغير بالسواد، النبي ﷺ قال: غيروا هذا الشيب واجتنبوا السواد السُّنة يغيَّر بالحناء والكتم أو بغير ذلك من أنواع الصبغ إلا السواد الخالص، لا.","link":"https://binbaz.org.sa/fatwas/25349/ما-حكم-ازالة-الشيب-وتغييره-بالكتم-او-الحناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم تغيير الشيب بالكتم أو الحناء، وبما يزال الشيب.mp3","categories":["اللباس والزينة"]},{"id":4971,"question":"بيع قماش الحرير الخالص للرجال المسلمين؟","title":"حكم بيع قماش الحرير الخالص للرجل المسلم؟","answer":"الجواب: إذا اشتراها لزوجته أو لبناته لا بأس، بس لا يَلْبَسه.","link":"https://binbaz.org.sa/fatwas/27842/حكم-بيع-قماش-الحرير-الخالص-للرجل-المسلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم بيع قماش الحرير الخالص للرجل المسلم؟.mp3","categories":["اللباس والزينة"]},{"id":4988,"question":"السواك هل يفضل عود على عود؟","title":"هل يفضل عود معيّن في السواك؟","answer":"الجواب: الأراك أفضل، أفضله الأراك، طيب، الأراك المناسب الذي لا يتفتت، وإذا تسوك بعود آخر يتشعث ويحصل به النقاء؛ فلا بأس.","link":"https://binbaz.org.sa/fatwas/28500/هل-يفضل-عود-معين-في-السواك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يفضل عود معين في السواك؟.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":4989,"question":"بعض الأطباء صنعوا معجونًا يقولون من نفس المادة حق الأراك، هل يقوم مقام السواك أم لا؟","title":"هل المعجون المصنوع من السواك يقوم مقامه؟","answer":"الجواب: لا، المعجون يكلِّف، المعجون يحتاج كُلْفة، والسواك ما يحتاج كُلْفة، إلا إذا احتاج المعجون في بعض الأحيان من باب غسل الفم في وقت آخر غير وقت الصلاة، هذا لا بأس، أما وقت الصلاة السُّنة له السواك فقط.","link":"https://binbaz.org.sa/fatwas/28501/هل-المعجون-المصنوع-من-السواك-يقوم-مقامه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل المعجون المصنوع من السواك يقوم مقامه؟.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":5075,"question":"ما يلبسه بعضُ اللاعبين من الألبسة القصيرة إلى نصف الفخذ، فما حكم ذلك؟","title":"ما حكم الألبسة القصيرة للرياضيين؟","answer":"الجواب: الواجب ستر الفخذ، للعلماء قولان في الفخذ: هل هما عورة من جهة الرجل أم لا؟ والصواب الذي استقرت عليه السُّنَّةُ أن الفخذ عورة، وأن الواجب ستره، وجاءت في هذا عدةُ أحاديث عن النبي عليه الصلاة والسلام تدل على أنَّ الفخذ عورة، فالواجب على اللاعب وغير اللاعب أن يكون لباسه ساترًا إلى الركبة فما فوق ذلك، حتى لا يُخرج شيئًا من الفخذ إلى الركبة، أقل شيءٍ إلى الركبة، فإن نزل عن الركبة احتياطًا كان ذلك أحسن، فالمقصود أنَّ هذا أقلّ شيءٍ: ما بين السُّرة والركبة، هذا هو العورة.","link":"https://binbaz.org.sa/fatwas/29407/ما-حكم الالبسة-القصيرة-للرياضيين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما حكم الألبسة القصيرة للرياضيين؟.mp3","categories":["اللباس والزينة"]},{"id":5079,"question":"ما حكم لبس القفازين للمرأة؟ وما حكم لبس الضيق أمام النِّساء؟","title":"ما حكم لبس القفازين والضيِّق للمرأة؟","answer":"الجواب: القفازان لا بأس بهما إذا كانت غير مُحرمةٍ، أما المُحرمة فلا تلبسهما بيديها، النبي نهى عن لبس القفازين للمُحرمة في حجٍّ أو عمرةٍ، أما في غير الإحرام فلا بأس أن تلبسهما عند الرجال، تغطي بهما يديها، هذا طيبٌ، أو تُغطي يديها بملابسها الأخرى: كالعباءة، والجلال، وما أشبه ذلك، أما في الإحرام فلا، لا تلبس القفازين في الإحرام في حجٍّ أو عمرةٍ.\nوهكذا الثياب الضَّيقة لا يجوز لبسها، لا للرجل، ولا للمرأة، الضيقة التي تُبدي حجم العورة، وتُسبب الفتنة؛ لا تُلبس، بل تكون وسطًا، تكون صفيقةً ساترةً وسطًا، لا واسعة جدًّا، ولا ضيقة تُبين حجم العورة، لا للرجل، ولا للمرأة، للجميع، والمرأة أشد، ولا سيما إذا كان يراها الرجالُ من محارمها وغير محارمها.","link":"https://binbaz.org.sa/fatwas/29420/ما-حكم-لبس-القفازين-والضيق للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما حكم لبس القفازين والضيَّق للمرأة؟.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":5104,"question":"هنالك أخت أخرى تسأل وتقول: ما حكم تقليد الغرب في أزيائهم وملابسهم عن طريق مجلات الأزياء؟","title":"ما حكم تقليد الكفار في أزيائهم وملابسهم؟","answer":"الجواب: لا يجوز للمسلمات ولا للمسلمين تقليد الغرب ولا الشرق في أزيائهم الخاصة التي ليست من عادة المسلمين؛ لأن الله جل وعلا نهانا عن التخلق والتشبه بأعدائنا قال : وَلَا تَكُونُوا كَالَّذِينَ نَسُوا اللَّهَ فَأَنْسَاهُمْ أَنْفُسَهُمْ أُولَئِكَ هُمُ الْفَاسِقُونَ [الحشر:19] وقال: وَخُضْتُمْ كَالَّذِي خَاضُوا [التوبة:69] ذمًّا لهم وعيبًا لهم في خوضهم كما خاض الأعداء، وقال النبي ﷺ: من تشبه بقوم فهو منهم وقال: قصوا الشوارب وأعفوا اللحى خالفوا المشركين وقال: جزوا الشوارب وأرخوا اللحى خالفوا المجوس في أحاديث كثيرة، فالواجب على رجال الإسلام ونساء الإسلام ألا يتشبهوا بأعداء الله في أزيائهم الخاصة، وأن يبتعدوا عن ذلك في أي مكان كانوا؛ لما تقدم من الأدلة.","link":"https://binbaz.org.sa/fatwas/30012/ما-حكم-تقليد-الكفار-في-ازياىهم-وملابسهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 29.mp3","categories":["اللباس والزينة"]},{"id":5114,"question":"سائلة تقول: هل يجوز لبس البنطلون أمام النساء وأمام الزوج والمحارم علمًا بأن البنطلون فضفاض وواسع؟","title":"حكم لبس المرأة البنطلون أمام النساء والزوج والمحارم","answer":"الجواب: إذا كان من جنس لباس النساء ما فيه تشبه بالكفرة، من جنس اللباس الذي يلبسه نساء بلدها ما فيه تشبه بالكفار؛ فلا بأس، وإلا تعتني بلباس أهل بلدها، لا تشذ عنهم، يكون لباسها لباس أهل بلدها حتى لا يحصل لها شذوذ ولا شهرة.","link":"https://binbaz.org.sa/fatwas/30022/حكم-لبس-المراة-البنطلون-امام-النساء-والزوج-والمحارم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 42.mp3","categories":["اللباس والزينة"]},{"id":5118,"question":"وهذه سائلة تقول: هل يجوز تغطية اليدين في الصلاة أم لا، لأننا سمعنا في هذه الأيام أنه لا يجوز أن تصلي المرأة ويديها كاشفة، بل لا بد من تغطية اليدين بالرغم من قول الرسول ﷺ المرأة كلها عورة في الصلاة ما عدا وجهها وكفيها، أفيدوني جزاكم الله خيرًا؟","title":"حكم تغطية المرأة يديها ووجهها في الصلاة","answer":"الجواب: الكفان سترهما أفضل، ولا يجب سترهما، والوجه كشفه أفضل، السنة كشف الوجه إذا ما كان عندها أجنبي تكشف وجهها ويديها، لا بأس، وإن غطت الكفين هذا أفضل وإلا فلا حرج، أما القدمان فيجب سترهما وجميع البدن، إلا إذا كان عندها أجنبي تستر بدنها كله حتى الوجه، إذا كان عندها أجنبي كأخي زوجها أو غيره.","link":"https://binbaz.org.sa/fatwas/30026/حكم-تغطية-المراة-يديها-ووجهها-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 48.mp3","categories":["ستر العورة للمصلي","اللباس والزينة"]},{"id":5179,"question":"هذا سؤال من أخ، يقول: أختٌ مسلمةٌ تلبس ثوبًا يكسو جميع الجسد، وهو غير شفَّافٍ، وتلبس العباءة، والتي كذلك تُغطي كل الثوب حتى الأرض، وهو مقفولٌ من الأمام، وكذلك غطاء الوجه، فهل يجوز لها أن تخلع العباءة فقط إذا زارت بعض النِّساء المسلمات؟ ما الحكم؟ وما الدليل؟","title":"حكم خلع المرأة حجابها عند النساء","answer":"الجواب: لا شكَّ أن المرأة عورة، وعليها الاحتجاب عن الرجال غير المحارم، أما إذا زارت النساء فلا بأس؛ لأنه لا يجب عليها الاحتجاب عن النساء، وإنما تحتجب عن الرجال، فإذا زارت النساء وطرحت عباءتها فلا بأس ولا حرج في ذلك، والله قال: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]، وقال: وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ إلى أن قال: أَوْ نِسَائِهِنَّ [النور:31]، فإبداء الزينة للنساء ليس فيه شيءٌ، ولا حرج في ذلك.","link":"https://binbaz.org.sa/fatwas/30114/حكم-خلع-المراة-حجابها-عند-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 140.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":5180,"question":"ما حكم استعمال العطور المعروفة بـ\"الكالونيا\"، والتي يوجد فيها كحول؟","title":"ما حكم استعمال العطورالتي فيها كحول؟","answer":"الجواب: العطورات التي يُعرف أنَّ فيها كحولًا مُسكرة، لا تُستعمل، مثل: \"الكالونيا\". وقد حدَّثنا كثيرٌ من الأطباء أنها لا تخلو من الإسبرتو، وأنه متفاوتٌ فيها: بعضه أكثر من بعضٍ، فبعضه فيه 80%، وبعضه 60%، وبعضه 40%، إلى غير ذلك، فهذا ينبغي ألا يُستعمل، وإن كان بعض الناس تساهل فيه واستعملوه، لكن نصيحتي لطالب العلم ألا يستعمل هذا المعروف، وهو \"الكالونيا\" المعروفة التي فيها الإسبرتو، وهو مسكر. أما العطورات الأخرى فلا أعرفها، لكن إذا عرفت أنَّ فيها شيئًا مُسكرًا، وأنَّ كثيره يُسكر؛ فلا تستعملها، واستعمل الطيب المعروف: من دهن الورد، ودهن العنبر، ودهن العود المعروف الذي ليس فيه شيء.","link":"https://binbaz.org.sa/fatwas/30116/ما-حكم-استعمال-العطورالتي-فيها-كحول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 142.mp3","categories":["اللباس والزينة"]},{"id":5196,"question":"يقول: هل حدُّ الإزار مخصص للثياب فقط أم هو شاملٌ للبشوت والبناطيل وغيرها؟","title":"ما حكم الإسبال في البشت والبنطال؟","answer":"الجواب: شاملٌ للجميع، فالإسبال ممنوعٌ في جميع الملابس: القمص، والسراويل، والأُزُر، والبشوت، والبنطلون، وغير ذلك، كل الملابس حدّها الكعب، لا تجوز الزيادة على الكعب. يقول النبيُّ ﷺ: ما أسفل من الكعبين من الإزار فهو في النار رواه البخاري في \"الصحيح\"، فالحد الفاصل من نصف الساق إلى الكعب، هذه هي السنة، والحد الركبة، فالركبة هي الحدّ، ما فوقها عورة، وما تحتها ليس بعورةٍ، لكن كونه يُنزله إلى النصف أفضل، أو إلى الكعب لا بأس، أما تحت الكعب فلا يجوز. أمَّا المرأة فلا بأس؛ لأنها عورة، لا بأس أن تُرخي ثيابها شبرًا أو ذراعًا، كما جاء في الأحاديث الصَّحيحة.","link":"https://binbaz.org.sa/fatwas/30140/ما-حكم-الاسبال-في-البشت-والبنطال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 160.mp3","categories":["اللباس والزينة"]},{"id":5200,"question":"سماحة الشيخ، أفيدونا -جزاكم الله خيرًا- عن حكم حلق اللِّحى والأخذ منها وتسويتها؟","title":"حكم حلق اللحية أو الأخذ منها وتسويتها","answer":"الجواب: الرسول ﷺ قال: قصُّوا الشوارب، وأعفوا اللِّحَى، خالفوا المشركين متفق على صحَّته. ويقول ﷺ: قصُّوا الشوارب، ووفروا اللِّحَى، خالفوا المشركين، جزُّوا الشوارب، وأرخوا اللِّحَى، خالفوا المجوس. فالواجب إعفاؤها وإرخاؤها وتوفيرها وعدم قصِّها وعدم حلقها، يُوفِّرها ويجعلها على حالةٍ وافرةٍ، مُرخاة؛ طاعةً لله ورسوله، وابتعادًا عن مُشابهة الكفرة والنساء. ولا ينبغي أن يغترَّ بالناس اليوم وكثرة مَن يحلق أو يقصّ، لا يغترّ بهذا، فالتأسِّي يكون بأهل الخير، لا بأهل الشر، التأسي بالرسول ﷺ وبالأخيار، أما التأسي بمَن فعل معصيةً لا، يقول الله جلَّ وعلا: لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ [الأحزاب:21]، ويقول جلَّ وعلا: وَالسَّابِقُونَ الْأَوَّلُونَ مِنَ الْمُهَاجِرِينَ وَالْأَنْصَارِ وَالَّذِينَ اتَّبَعُوهُمْ بِإِحْسَانٍ [التوبة:100] اتبعوهم بإحسانٍ: ساروا على نهجهم في القول والعمل. فالمؤمن يقصّ الشارب ويُحفيه، ويُرخي اللحيةَ ويُعفيها، هذا هو الواجب الذي فعله النبيُّ ﷺ وفعله الصحابةُ، وأرشد إليه الأمةَ عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/30144/حكم-حلق-اللحية-او-الاخذ-منها-وتسويتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 173.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":5207,"question":"سماحة الشيخ: ما حكم لبس البرقع، خاصةً وأنَّ بعض النساء توسَّعن في ذلك؟ وهل هو حجاب شرعي؟","title":"هل البرقع من الحجاب؟ وما حكم لبسه؟","answer":"الجواب: إذا كان بقدر العين أو العينين فهو حجابٌ شرعي، وإن جعلت لها خمارًا مع ذلك احتياطًا فحسنٌ، وإلا فالبرقع لا بأس به، إلا المُحرمة فإنها لا تلبس البرقع، المحرمة بالحج أو العمرة ليس لها لبس البرقع، بل تُغطي وجهها بالشيلة ونحوها، أما إن كانت غير محرمةٍ فلها لبس البرقع، وليس لها أن تُخرج إلا العين أو العينين فقط، والبقية مستور.","link":"https://binbaz.org.sa/fatwas/30151/هل-البرقع-من-الحجاب-وما-حكم-لبسه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 183.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":5228,"question":"كذلك يسأل سائلٌ عن لبس الألوان: اللون الأحمر الخالص إن كان قميصًا أو نحو ذلك؟","title":"حكم لبس الأحمر الخالص في قميص أو نحوه","answer":"الجواب: بعض أهل العلم يكرهه؛ لما جاء في بعض الروايات أنَّ النبي نهى عن لبس الأحمر، والجمهور لا يكرهون ذلك؛ لأنه ﷺ كان يلبس الحُلَّة الحمراء، كان في حجَّة الوداع في حديث أبي جُحيفة رأى النبيَّ ﷺ وعليه حُلَّة حمراء، وأجاب مَن كره ذلك بأنها حلَّة فيها خطوط حمر، وليست مُصمتةً؛ جمعًا بين الروايات، وبعضهم حمل ذلك على المعصفر الخالصّ، هو الذي فيه النَّهي، وما سواه لا حرج فيه. فالأمر في هذا واسعٌ إن شاء الله، لكن إذا كان أحمر مفدّم –يعني: خالص الحمرة، شديد الحمرة- فيه معصفر، وليس فيه خطوط بيض ولا سود ولا كذا؛ يكون تركه أوْلى خروجًا من الخلاف، أما إذا كانت فيه خطوط أو نقط سود أو بيض أو شبه ذلك؛ زالت الكراهة.","link":"https://binbaz.org.sa/fatwas/30172/حكم-لبس-الاحمر-الخالص-في-قميص-او-نحوه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 500.mp3","categories":["اللباس والزينة"]},{"id":5243,"question":"ما حكم قصّ الشعر من الأمام أو من الخلف أو بجميعه (للمرأة)؟","title":"ما حكم قصّ المرأة أجزاء من شعرها؟","answer":"الجواب: قصّ الشعر لا ينبغي؛ لأنه جمال للمرأة، الأفضل لها أنها لا تقصّه، فهو جمال، لكن إذا دعت الحاجةُ إلى ذلك أو زوجها أراد ذلك أو لكثرته؛ تُخفف، فلا بأس، قد قصَّر أزواج النبي ﷺ من رؤوسهنَّ لما توفي النبيُّ ﷺ للتَّخفيف، وإذا قصَّت للتخفيف أو لشيءٍ رآه الزوج بينها وبينه من غير قصد التَّشبه بالكافرات فلا حرج في ذلك، ولكن تركه أفضل وأوْلى؛ لأنه زينة وجمال. أما الحلق فيَحْرُم، وهكذا ما يُشبه الحلق يحرُم.","link":"https://binbaz.org.sa/fatwas/30654/ما-حكم-قص-المراة-اجزاء-من-شعرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 558.mp3","categories":["اللباس والزينة"]},{"id":5284,"question":"ما حكم لبس الساعات المطلية بماء الذهب، علمًا بأن نسبته ضئيلة جدًّا وأحيانًا يوجد مكتوبًا أيضًا على الساعات ذات القيمة الرخيصة جدًّا؟","title":"ما حكم لبس الساعات المطلية بماء الذهب؟","answer":"الجواب: الذهب لا يحل للرجال، لا في الملابس ولا في الأواني ولا في الساعات، وإذا تحقق أنها مطلية بالذهب لم تجز للرجال، ويجب الحذر من ذلك، وعدم التساهل، والنبي عليه الصلاة والسلام قال في الذهب والحرير: حل لإناث أمتي حرام على ذكورها فالواجب الحذر من ذلك، وأن لا يلبس إلا شيئًا سليمًا فضة أو حديدًا أو مخلوطًا بالفضة والحديد، أما الذهب فالواجب أن لا يتعرض له، وأن لا يتساهل في هذا الأمر، بل ذلك للنساء.[1]","link":"https://binbaz.org.sa/fatwas/30923/ما-حكم-لبس-الساعات-المطلية-بماء-الذهب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 004.mp3","categories":["اللباس والزينة"]},{"id":5314,"question":"يقول: ما حكم لبس الباروكة لمن به عيب وهو الصلع من النساء والرجال وما حكم بيعها في المحلات؟","title":"حكم \"الباروكة\" لمن به صَلَع من النساء والرجال","answer":"الجواب: لبس الباروكة أشد من الوصل، الوصل يعني وصل الشعر، فكيف بالباروكة التي هي رأس كامل؟! والرسول ﷺ أخذ ذات يوم كُبَّةً من الشعر وقال: إنما هلك نساء بنو إسرائيل لما فعلوا مثل هذا فالتدليس لا يجوز، لكن العلاج لإنبات الشعر لا بأس، أن تعالج ليعود الشعر، أما تلبس كُبَّة من الشعر أو تُوصل الشعر لا.[1]","link":"https://binbaz.org.sa/fatwas/30973/حكم-الباروكة-لمن-به-صلع-من-النساء-والرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 034.mp3","categories":["اللباس والزينة"]},{"id":5331,"question":"ما هو قولكم في ستر العاتق هل هو واجب؟ وهل العاتق من العورة؟ وإن كان من العورة فمن أي أنواعها؟ وهل يجوز كشفها؟","title":"ما حكم ستر العاتق؟ وهل هو من العورة؟","answer":"الجواب: جاء في الحديث الصحيح يقول ﷺ: لا يصلي أحدكم في الثوب وليس على عاتقه منه شيء فالعاتق ليس بعورة، لكن أمر النبي بستره إذا تيسر ذلك، وقال لجابر: إن كان الثوب واسعًا فالتحف به، وإن كان ضيقًا فاتّزر به، فإذا كان عنده رداء وضعه على كتفيه أو قميص، فستر العاتقين أو أحدهما واجب في الصلاة، وإن كان ليس بعورة في غير الصلاة؛ لقوله ﷺ: لا يصلي أحدكم في الثوب الواحد ليس على عاتقه منه شيء متفق عليه.[1]","link":"https://binbaz.org.sa/fatwas/31001/ما-حكم-ستر-العاتق-وهل-هو-من-العورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 052.mp3","categories":["ستر العورة للمصلي","اللباس والزينة"]},{"id":5466,"question":"انتشرت بين النساء ظاهرة لبس البنطلونات الضيفة والتي تصف شكل أرجل المرأة بحيث تظهر هذه البنطلونات من أسفل العبايات القصيرة، وذلك في الأسواق والأماكن العامة؛ مما يسبِّب فتنة للرجال والباعة، فما نصيحتكم؟","title":"ما حكم لبس البنطلون الضيق للنساء؟","answer":"الجواب: لا يجوز للمرأة أن تلبس شيئًا يسبب الفتنة، ولا تلبس شيئًا يخالف لباس أهل بلدها؛ لأن هذا من ثوب الشهرة، ثوب الشهرة ممنوع؛ فليس لها أن تلبس ما تتشبه فيه بالرجال، أو يبدي بعض عورتها، أو يخالف زي بلدها، بل عليها أن تكون مثل أهل بلدها في ملابسهن، مع التستر، والعناية بالحذر من التشبُّه بالرجال، لا في بنطلونات ولا غير بنطلونات، تلبس الملابس العادية التي اعتادها بلدها وأخواتها في الله. والله المستعان.[1]","link":"https://binbaz.org.sa/fatwas/31332/ما-حكم-لبس-البنطلون-الضيق-للنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/reyath_alsalhin 003.mp3","categories":["اللباس والزينة"]},{"id":5631,"question":"بعض الإخوان توسَّع في الأخذ من اللحية، يقول: هذه شوائب وزوائد، ومن قبيل هذا، كأنه مُستأنس برأي أحد العلماء؟","title":"ما حكم الأخذ من اللحية استئناسًا بفعل صحابي؟","answer":"الجواب: يُعلَّم أنَّ هذا غلط، الرسول ﷺ قال: قصوا الشَّوارب، ووفِّروا اللِّحَى، خالفوا المشركين، أخرجه البخاري في الصحيح، وفي اللفظ الآخر: قصوا الشوارب، وأعفوا اللِّحَى، خالفوا المشركين متفق عليه، وفي اللفظ الثالث عند مسلم: جزُّوا الشَّوارب، وأرخوا اللِّحى، خالفوا المجوس، فواجب إعفاؤها وإكرامها وتوفيرها وعدم التَّرخص بأقوال زيدٍ أو عمرٍو. س: وإن استدلَّ على ذلك بفعل بعض الصَّحابة؟ ج: هو معصوم الصَّحابي؟! المعصوم مَن هو فيما يُبلِّغ عن الله؟ عليك بالمعصوم، ودع عنك غير المعصوم؛ فإنه يُخطئ ويُصيب، وقل: اللهم اغفر له، فإذا كان ابن عمر أخطأ، أو زيد، أو عمرو، أو أحمد بن حنبل، أو الشافعي، أو واحد من المعاصرين أو غيرهم تقول: اللهم اغفر له، وعليك بالحقِّ، لا تترك الحقَّ لقول أحدٍ، لا لقول الصديق، ولا عمر، ولا عثمان، ولا ابن حنبل، ولا الشافعي، ولا زيد، ولا عمرو، الحق فوق الجميع متى ظهر وتبين، لكن مع التَّرضِّي عن أهل الخير، والترحم عليهم، وإحسان الظنّ بهم. س: حلق اللحية كبيرة من كبائر الذُّنوب؟ ج: معصية، وأما كونه كبيرةً الله أعلم، هو من المعاصي.[1]","link":"https://binbaz.org.sa/fatwas/31628/ما-حكم-الاخذ-من-اللحية-استىناسا-بفعل-صحابي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alsana albaghawi 006.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":5632,"question":"الترجُّل للرجال والنساء أم خاص بالرجال فقط النهي عنه؟","title":"ما حكم ترجيل الشعر للرجال والنساء؟","answer":"الجواب: القاعدة أن ما يحصل من الأوامر والنواهي يعم الجميع، هذه القاعدة، أمر الرجال أمر للنساء، وأمر النساء أمر للرجال إلا ما دل الدليل على الخصوصية. والترجل غِبًّا أرفق؛ لأن الترجل يوميًّا فيه شيء من المشقة وشيء من زيادة الإرفاه، لكن جاء في الحديث أنه رخص لأبي قتادة لما اشتكى إليه أنه يحتاج إلى ذلك، فالظاهر والله أعلم أن النهي هنا للكراهة، وأنه إذا دعت الحاجة إلى الترجل بسبب عارض من العوارض لا بأس يوميًّا، والترجل هو كونه ينقض الرأس ويمشطه ويعتني به. س: وإذا كان الرجل يريد من زوجته الترجُّل يوميا حتى تتجمل له بشعرها؟ الشيخ: السنة غِبًّا مثل ما قال ﷺ، هذا هو السنة. س: الأحاديث كلها صحيحة في الباب؟ الشيخ: الذي أعرف أنها صحيحة كلها، وحديث عبدالله بن مغفل فيه عنعنة الحسن، والذي يظهر أنه جاء من طرق أخرى غير طريق النسائي هذا، وحديث أبي قتادة كذلك لا بأس به، أما هنا من طريق الحسن مرسلًا ومعنعنًا. س: عند الحاجة تزول الكراهة؟ الشيخ: هو الظاهر -والله أعلم-، إذا وجدت حاجة؛ لحديث أبي قتادة. س: من كان له شعر فليكرمه؟ الشيخ: على الوجه الشرعي، يكرمه على الوجه الشرعي. س: الحديث صحيح؟ الشيخ: ما أعرف حاله. س: وهل يقاس ترجيل اللحية على ترجيل الرأس؟ الشيخ: ما هو بظاهر، اللحية لا يتعرض لها. س: من يقول أن الترجل خاص بالرأس؟ الشيخ: هذا المعروف الترجل للرأس. س: يعني ما يدخل فيه اللحية؟ الشيخ: لا، ما يسمى \"ترجيل\".[1]","link":"https://binbaz.org.sa/fatwas/31629/ما-حكم-ترجيل-الشعر-للرجال-والنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/sunan alnisayiy 001.mp3","categories":["اللباس والزينة"]},{"id":5635,"question":"الشيب في الجسد كله منهي عن نتفه؟","title":"هل النهي عن نتف الشيب يشمل الجسد كله؟","answer":"الجواب: ظاهر الحديث العموم، نعم، شعر اللحية والرأس يغيّر بالصُّفرة والحُمرة لا بالسواد. س: في الأيدي والأرجل كذلك؟ الشيخ: الأيدي ما فيها شعر، الذي فيه شعر يروح يزيله ما فيه شيء، الكلام في شعر الرأس، وفي شعر اللحية، والشارب، والأيدي والرجل ما هي محل شعر، وبعض الناس يُبتلى بالشعر. س: يدل على أنه كبيرة الفعل هذا؟ الشيخ: ظاهره الوعيد نعم يقتضي أنه كبيرة لا يريحون رائحة الجنة وعيد. س: ألا يفرّق بين من خلصت لحيته بياضًا، وبين من فيها بعض شيء من البياض المختلط بالسواد فيقال؟ الشيخ: كلما كثر الشيب؛ تأكد التغيير. س: متكلم فيه، الزيادة هذه \"واجتنبوا السواد\"؟ الشيخ: بعضهم يراها مُدرجة، والصواب أنها من نفس الحديث ما هي مُدرجة.[1]","link":"https://binbaz.org.sa/fatwas/31633/هل-النهي-عن-نتف-الشيب-يشمل-الجسد-كله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/sunan alnisayiy 004.mp3","categories":["شروح الحديث","اللباس والزينة"]},{"id":5661,"question":"امرأة مسلمة تشهد أن لا إله إلا الله، وأنَّ محمدًا رسول الله، ولها أهل كُفَّار: أب وأخ، فهل تحتجب عنهم أم لا؟","title":"هل تحتجب المرأة المسلمة عن أهلها الكُفَّار؟","answer":"الجواب: لا، لا تحتجب عنهم، تدعوهم إلى الله ولا تحتجب، تدعوهم إلى الله وتُرشدهم إلى الخير، والحمد لله الذي هداها للإسلام، تدعو أباها وإخوتها وأقاربها، تنصح لهم، ولا تحتجب عنهم.[1]","link":"https://binbaz.org.sa/fatwas/31698/هل-تحتجب-المراة-المسلمة-عن-اهلها-الكفار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aldurus almuhima 007.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":5681,"question":"يوجد بعض من الشباب الواعي يتعصب لأشياء  قد تكون صدمة لدى الشباب الضعيف الذي في أمس الحاجة إلى موجه، ومن هذه الأشياء أنهم يقصرون ثوبهم تقصيرًا قد يصل إلى التشدد؟","title":"حكم الإسبال بين الغلو والتفريط","answer":"الجواب:\nهذه مسائل طفيفة، ومسائل خفيفة، المهم أن يحذروا من الإسبال، فإذا كان الثوب من نصف الساق إلى الكعب فهذا كله جائز، أعلاه نصف الساق كما جاء في الحديث إزرة المؤمن، والنهاية إلى الكعب لا ينزل عن الكعب.  وما دام الثوب من نصف الساق إلى الكعب فلا إنكار في ذلك، ولا ينبغي الإنكار في ذلك؛ بل هذا محل جواز من النصف إلى الكعب، ولا يجوز أن ينزل عن الكعبين كما قال النبي ﷺ: ما أسفل الكعبين من الإزار فهو في النار وتوعد المسبلين قال: لا يكلمهم الله ولا يزكيهم ولهم عذاب أليم. فلا يجوز الإسبال تحت الكعب، ولا بأس أن يكون فوق الكعبين من نصف الساق هذا محله، ولا ينبغي التشديد في هذا، ولا التزمت في هذا؛ بل ينبغي في هذا التسامح، وعدم الإنكار على من رفع إلى نصف الساق، وعدم الإنكار على من نزله إلى الكعب لا هذا ولا هذا. السؤال: أحسن الله إليك يا شيخ، بالنسبة للحديث أمر الرسول ﷺ الصحابي بإعادة الوضوء؟ الجواب: هذا في الإسبال جاء فيه حديث فيه ضعف، وجاء في حديث آخر ما يدل على صحة المعنى، ولكن المقصود من ذلك التحذير من الإسبال، وليس معناه أنك تعيد الصلاة، النبي أمرهم بإعادة الوضوء من باب التشديد، والتحذير، ولم يأمرهم بقضاء الصلاة، وإعادتها -عليه الصلاة والسلام- وقال أهل العلم: إن المراد من هذا التحذير من الإسبال، وأنه شيء قبيح ينبغي فيه الحذر من تعاطيه، ولاسيما في الصلاة. السؤال: إذا كان هناك إنسان خياط، ثم يأتيه الرجل يشترط عليه أن يجعله تحت الكعبين؟ الجواب: يتعلم الخياط، ينكر على الخياط، لا يزيدهم تحت الكعبين إلا إذا كان القصد أنه يرفعه تحت الكعبين، ثم يرفعه إذا غسله؛ لأنه بعض الخرق إذا غسل يشمر، ويرتفع، فإذا كان فيه إسبال أطلقوه حتى يكون مناسبًا بعد ذلك، إذا كان القصد هكذا فلا بأس،.. ثم يرفع، فإذا احتيج إلى إطلاقه أطلقه؛ بشرط أن لا ينزل عن الكعب.","link":"https://binbaz.org.sa/fatwas/973/حكم-الاسبال-بين-الغلو-والتفريط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_02.mp3","categories":["الآداب والأخلاق","اللباس والزينة"]},{"id":5685,"question":"سؤال آخر: إذا لبست العقال حيث بعض الإخوان قال لي: لا تلبسه فهو حرام؟","title":"حكم لبس العقال","answer":"الجواب:\nليس بشيء العقال ليس بشيء، لو لبس عقالًا، أو  خيطًا، أو عمامة لا بأس، كله لا بأس. أمور اللباس هذه ما فيها بأس إلا على وجه يكون فيه مشابهًا للكفار، فالشيء الذي فيه مشابهة للكفار لا يفعله ما دام ملابسه يلبسها المسلمون فلا بأس.","link":"https://binbaz.org.sa/fatwas/988/حكم-لبس-العقال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_17.mp3","categories":["الآداب والأخلاق","اللباس والزينة"]},{"id":5763,"question":"بعض النساء يلبسن ثيابًا فيها سحّابات من خلفها، فهل هذا جائز؟","title":"حكم وضع النساء سحّابات من خلف ثيابهن","answer":"الجواب:  لا نمنع، لا نعلم شيئًا في هذا، لكن إذا كان فيه قدام أولى، وأحفظ للعورات، المهم حفظ العورة. وهذا الاصطلاح الجديد ليس بجيد، لو كان في المقدم فيكون أولى، وأحوط، يكون أمامها تستطيع حفظه، وصيانته، فهو أولى من الخلف، لكن إذا كان من الخلف لا يظهر العورة، ويصون، وإنما جعل؛ لأنه أسهل في خلع الثياب، أو أسباب أخرى فلا نرى فيه بأسًا.","link":"https://binbaz.org.sa/fatwas/1098/حكم-وضع-النساء-سحابات-من-خلف-ثيابهن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_104.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":5938,"question":"هل يجوز للنساء لبس الثياب البيض؟","title":"حكم لبس النساء الثياب البيض","answer":"الجواب: يجوز لبس الثياب البيض إذا كانت على طريقة سليمة، ليس فيها مشابهة للرجال، إذا كان فيها أشياء خياطات، ووصل تميزها عن الرجال، أما لبس البياض على طريقة الرجال فلا يجوز، تشبه.  والرسول ﷺ لعن المرأة تلبس لبس الرجل، لكن إذا لبست الأبيض، أو الأسود، أو الأحمر على طريقة لا تشبه الرجال، الرجل يلبس الأحمر أيضًا يلبس جبة حمراء، وسوداء، وخضراء، وغير ذلك، فلا بدّ أن تكون لبستها غير لبسة الرجل، ولا بدّ أن تتميز، وإلا فهي ملعونة إذا تشبهت، وهو ملعون إذا تشبه بها كل منهما، ملعون، فعليهما جميعًا أن يتباعدوا عن التشبه، فهي تلبس لباسًا لا يشابهه، وهو يلبس لباسًا لا يشابهها، هذا هو الواجب عليهما.","link":"https://binbaz.org.sa/fatwas/1318/حكم-لبس-النساء-الثياب-البيض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_287.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":5942,"question":"هل الإسلام يأمر بإخفاء البشرة، أو يأمر بإخفاء العضو نفسه؟ فإذا كان يأمر بإخفاء العضو نفسه، فما بال الرجال الذين يلبسون الملابس الأوروبية التي لا تستر من الجسم إلا البشرة، وتترك العضو كما هو هل ذلك مقبول في الإسلام؟","title":"كيفية ستر المسلم والمسلمة لجسديهما","answer":"الجواب:  الستر مطلوب، والرجال، والنساء يختلفون في هذا، فالمرأة عورة كلها، وأمرها خطير، وقد سمعت أيها السائل قول النبي ﷺ: ما تركت بعدي فتنة أضر على الرجال من النساء فالواجب على النساء التستر، والعناية، وعدم إظهار حجم الأعضاء بالملابس الضيقة، أو الملابس الرقيقة. الواجب عليهن أمر كبير، وواضح المعنى، وخطر تفريطها في ذلك واضح كبير، فستر الأعضاء واجب عن غير المحارم، أما المحارم فقد سمعت في الندوة، ما سمعت، وأن المحرم يباح له النظر إلى ما ظهر منها غالبًا من وجه، وكفين، وقدمين، ونحو ذلك، كالقرط، والحلق، ونحو ذلك. وأما الرجل فأمره أوسع إذا ستر ما بين السرة، والركبة بشيء صفيق متين، يستر ما بين السرة، والركبة، فهذا كاف، فإن عورة الرجل ما بين السرة، والركبة، فإذا ستر ذلك سترًا كافيًا؛ يغطي العورة، ولا يبينها، لا عورة الفرج الدبر، ولا الذكر، ولا الخصيتين، يكون ساترًا سترًا كافيًا، فلا بأس بذلك.  وإذا كان في مواضع كما أشار الشيخ عبدالله بن جبرين، إذا كان في مواضع قد يستقبحون ظهور الصدور، أو ظهور الظهر، فستر ذلك عندهم كان ذلك أكمل، فإن العرف يختلف، والبلدان تختلف، والمجامع تختلف، فلا ينبغي للإنسان أن يتساهل في مثل هذه الأمور، بل ينبغي له أن يفعل ما لا يستنكر، ولا يستقبح في عرف الناس، حتى لا يرمى بالتساهل في دينه، أو يرمى بشيء آخر مما يضره. كذلك إذا كان صاحب بدن جميلًا، وشابًا خطيرًا فإنه ينبغي التستر الستر الكامل، فإن بعض الناس قد يعشق المردان أعظم مما يعشق النساء؛ فينبغي في مثل هذا الحذر، ولا يقال في حق الأمرد أنه يبدي صدره، ويبدي أكتافه، ويبدي سيقانه؛ فإنه قد يضر الناس بهذا، وقد يفتن الناس بهذا، وقد يبتلى هو، فينبغي له في مثل هذا أن يتستر، وأن يلبس القمص الساترة، وأن يحذر من بلاء الجمال، وبلاء فتنة الناس في بعض المردان، فهذا شيء خطير. وأقل شيء في حق الشاب، أقل شيء أن يستر ما بين الركبة، والسرة سترًا كافيًا، صفيقًا، عظيمًا؛ لعله ينجو، وإذا أطال الستر حتى ستر أغلب الساق؛ فهو خير، وإذا ستر صدره، وظهره بفانيلة جيدة ساترة؛ فهو أكمل، وأكمل، وهكذا ما يقع في لعب الكرة، ينبغي فيه التستر غاية التستر، وأن تكون الفخذ مستورة سترًا كاملًا؛ فإنها عورة، وإذا ستر مع ذلك الساق، وستر مع ذلك ما فوق السرة بالفانيلة؛ كان أكمل، وأسلم في حقه، وأسلم في حق غيره أيضًا، رزق الله الجميع العافية.","link":"https://binbaz.org.sa/fatwas/1314/كيفية-ستر-المسلم-والمسلمة-لجسديهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_283.mp3","categories":["الآداب والأخلاق","اللباس والزينة"]},{"id":5944,"question":"هل إظهار المرأة لنحرها، وصدرها، وذراعيها في بيتها مع ذي محرم يعتبر من التبرج؟ وكيف يستطيع الرجل أن يقيم زوجته، وبناته على عدم التبرج؟","title":"ما يجوز أن تظهره المرأة أمام محارمها؟","answer":"الجواب:  اختلف العلماء في تحديد ما للمحرم أن ينظر على أقوال: منها ما سمعتم من أنه ينظر ما جرت العادة بكشفه فقط من وجه، وقرط، وقلادة، وذراع، وقدم، وأسفل الساق، وزاد آخرون زيادة على ذلك بالنظر إلى الرأس أيضًا، والعضدين، ونحو ذلك.  ولكن الوقت وقت خطير، نحن في آخر الزمان، وفي غربة الإسلام، وكثير من المحارم فسقة، أو كفرة، لا يؤمنون على محارمهم -والعياذ بالله- فينبغي لها التستر مهما أمكن، وألا تأخذ بالرخص الزائدة؛ بل مهما أمكن ألا يظهر منها إلا ما جرت به العادة من وجه، وكفين، وقدمين فهو أولى بها، وأسلم لها، ولاسيما عند الخلوة بمحرمها كأخيها الفاسق، أو عمها الفاسق، أو خالها الفاسق، فإن هذا فيه خطر عظيم.  وكم سمعنا، وكم بلغنا من شرور في هذه المسائل، فالأولى في هذا المقام للمرأة أن تأخذ حذرها، وألا تقول هذا محرمي، وهذا خالي لا، ولاسيما إذا خلا بها ما عندهما أحد، فإن الأمر فيه خطورة في هذا الوقت، والتقي غير غير التقي، ومسائل النساء خطيرة حتى على الأتقياء، فكيف بغير الأتقياء؟! ولا حول ولا قوة إلا بالله.","link":"https://binbaz.org.sa/fatwas/1315/ما-يجوز-ان-تظهره-المراة-امام-محارمها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_284.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":5950,"question":"هل يجوز للنساء لبس الثياب البيض؟","title":"حكم لبس النساء الثياب البيض","answer":"الجواب: يجوز لبس الثياب البيض إذا كانت على طريقة سليمة، ليس فيها مشابهة للرجال، إذا كان فيها أشياء خياطات، ووصل تميزها عن الرجال، أما لبس البياض على طريقة الرجال فلا يجوز، تشبه.  والرسول ﷺ لعن المرأة تلبس لبس الرجل، لكن إذا لبست الأبيض، أو الأسود، أو الأحمر على طريقة لا تشبه الرجال، الرجل يلبس الأحمر أيضًا يلبس جبة حمراء، وسوداء، وخضراء، وغير ذلك، فلا بدّ أن تكون لبستها غير لبسة الرجل، ولا بدّ أن تتميز، وإلا فهي ملعونة إذا تشبهت، وهو ملعون إذا تشبه بها كل منهما، ملعون، فعليهما جميعًا أن يتباعدوا عن التشبه، فهي تلبس لباسًا لا يشابهه، وهو يلبس لباسًا لا يشابهها، هذا هو الواجب عليهما.","link":"https://binbaz.org.sa/fatwas/1318/حكم-لبس-النساء-الثياب-البيض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_287.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":5963,"question":"المسك، ودهن العود، أو الورد، ونحو ذلك من أنواع الطيب إذا استخدمته المرأة، وكانت رائحتها واضحة، فما حكم استعمالها، خاصة إذا خرجت المرأة من منزلها؟ وهل يعتبر تكريم الزائرات بتبخيرهن، وتعطيرهن في حكم ذلك؟","title":"هل يجوز استخدام المرأة للروائح عند خروجها؟","answer":"الجواب: خروج المرأة بالطيب إلى الأسواق أمر ممنوع، وليس لها أن تخرج بذلك، ولا أن تعين الزائرات، والضيوف بذلك، بل عليها أن تنصح، وأن تقول: نود أن نطيبكم، ولكن خروج المرأة بالطيب إلى الأسواق أمر ممنوع، وبذلك تجمع بين النصيحة، وترك ما حرم الله فعله.","link":"https://binbaz.org.sa/fatwas/1336/هل-يجوز-استخدام-المراة-للرواىح-عند-خروجها","audio":"undefined","categories":["قضايا المرأة","اللباس والزينة"]},{"id":5966,"question":"سؤال من ضمن أسئلة كثيرة سبق أن أجيب على بعضها: ما حكم التي تقص من شعرها من عند ناصيتها حتى تجعله عند الحواجب؟ وهل فيه فرق بين الصغيرة، والكبيرة؟","title":"قص المرأة شعرها جائز أم غير جائز","answer":"الجواب: قص الشعر ما نعلم فيه شيئًا، الذي أعرف الحلق، ليس لها أن تحلق رأسها، لكن تقص من طوله، أو من كثرته، فلا نعلم فيه بأسًا، لكن ينبغي أن يكون ذلك على طريقة حسنة التي ترضاها هي، وزوجها، وتتفق عليها مع زوجها من غير أن يكون لقصد التشبه بالكافرات، بل لقصد شيء يرضيه ما بينهم فلا نعلم فيه شيئًا. وقد قصت أمهات المؤمنين شعورهن لما توفي النبي ﷺ لأن بقائها طويلة فيه كلفة في المشط، والتعب، فإذا كان كثيرًا، وقصت المرأة بعض الشيء لطوله، وكثرته، فلا يضر ذلك، لكن يخشى من ذلك التشبه بالنساء الكافرات، فهذا لا يجوز، لا يجوز أن تقصد المرأة التشبه بطائفة كافرة، أو بامرأة كافرة، أما إذا فعلت ذلك لكثرته، أو لأن في قصه جمالًا يرضاه زوجها، وترضاه هي فلا نعلم فيه شيئًا، أما حلقه بالكلية؛ فلا يجوز إلا من علة، ومرض.","link":"https://binbaz.org.sa/fatwas/1332/قص-المراة-شعرها-جاىز-ام-غير-جاىز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_301.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":6041,"question":"هل هناك دليل، أو شيء يحث على حلق شعر الرأس؟","title":"حكم حلق شعر الرأس والسنة في شعر الإبط","answer":"الجواب: حلق الرأس جائز، النبي ﷺ قال في الرأس: احلقه كله، أو دعه كله لما رأى إنسانًا قد حلق بعض رأسه، وهو القزع، قال: احلقه كله، أو دعه كله والنبي حلق رأسه في الحج -عليه الصلاة والسلام- فالحلق لا بأس به، أو تربيته إذا قوي على تربيته على وجه شرعي؛ للتأسي بالنبي ﷺ لا بأس بذلك، طيب، إذا قوي عليه، واعتنى به، لا لقصد الفساد، والنساء، وأشباه ذلك؛ فلا حرج، وإن حلق؛ فلا بأس.  أما الإبط فالسنة أخذ الإبط، نتفه، هو هذا هو الأفضل، والعانة كذلك تحلق حلقًا، والأظفار تقلم، والشارب يقص، هذا سنة، بل قد يجب إذا طال وجوبًا، النبي ﷺ قال: قصوا الشوارب، وأعفوا اللحى وأمر بنتف الإبط، وحلق العانة، وقلم الأظفار للرجل، والمرأة، هذا عام للرجال، والنساء جميعًا، ومشروع للجميع قلم الأظفار، ونتف الإبط، وحلق العانة، هذا للجميع، وقص الشارب للرجال.","link":"https://binbaz.org.sa/fatwas/1463/حكم-حلق-شعر-الراس-والسنة-في-شعر-الابط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_393.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":6050,"question":"المرأة الشرقية، والغربية تظهر متكشفة على شاشة التلفاز أمام المسلمين من الرجال، والنساء؛ فما رأيكم نحو هذه الشائعة الخبيثة؟","title":"ظهور النساء الكاسيات العاريات على شاشات التلفاز","answer":"الجواب: هذا من البلاء الذي تقدم من التلفاز، وظهور النساء الكاسيات العاريات، ويكون من الأغاني الكثيرة، والتمثيليات الباطلة، هذا من البلاء، ومن أسباب تأخر المسلمين، ومما دسه عليهم أعداؤهم، مما دسها أعداؤهم عليهم؛ حتى يضعفهم، ويضرهم، ويفسد أخلاقهم، فهذا منكر.","link":"https://binbaz.org.sa/fatwas/1456/ظهور-النساء-الكاسيات-العاريات-على-شاشات-التلفاز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_385.mp3","categories":["اللباس والزينة"]},{"id":6067,"question":"هل في دليل على جواز صبغ اللحية بالسواد؟","title":"هل من دليل على جواز صبغ اللحية بالسواد؟","answer":"الجواب: أما صبغ اللحية بالسواد فقد دلت الأدلة على منعه، جاء صحيحًا عن النبي ﷺ أنه قال لما رأى لحية أبي قحافة، والد الصديق -رضي الله تعالى عنهما- ورأسه كالثغامة بياضًا، أمرهم أن يغيروا الشيب، وأن يجنبوه السواد، فهذا يدل على أن الشيب يغير والسنة أن يغير بالصفرة أو الحمرة، ولكن لا يغير بالسواد الخالص، بل يغير بسواد مخلوط بالحمرة، أو بالصفرة خالصة، أو بحمرة خالصة.  وفي السنن عن أبي داود، عن ابن عباس -رضي الله تعالى عنهما- أن النبي -عليه الصلاة والسلام- قال: يأتي في آخر الزمان قوم يخضبون بالسواد، كحواصل الحمام، لا يرحون رائحة الجنة وهذا وعيد عظيم، وسنده لا بأس به، رواه أحمد، وأبو داود، والنسائي بإسناد جيد، فهذا صريح في منع السواد الخالص.  وأما ما يروى عن بعض السلف أنه كان يصبغ بالسواد، فهذا محمول على أنه ما بلغه النص، محمول على أنه لم تبلغه النصوص الدالة على تحريم السواد الخالص، هذا أحسن ما يقال في حق من روي عنه أنه يخضب بالسواد من الصحابة، أو من غيرهم، أحسن شيء يحمل عليه أن يحمل على أنه لم يبلغه النهي.","link":"https://binbaz.org.sa/fatwas/1477/هل-من-دليل-على-جواز-صبغ-اللحية-بالسواد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_407.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":6087,"question":"أرى فيما يراه النائم أنه يمشي عريانًا بدون ملابس مع الناس، فما تفسير ذلك؟","title":"ما ينبغي لمن رأى رؤيا مكروهة","answer":"الجواب: هذه رؤيا قبيحة، وما ينبغي ذكرها الذي يمشي عريانًا، النبي -عليه الصلاة والسلام- قال: الرؤيا الصالحة من الله، والحلم من الشيطان، فإذا رأى أحدكم ما يكره؛ فليتعوذ بالله من الشيطان، ومن شر ما رأى ثلاث مرات، ثم ينقلب على جنبه الآخر، فإنها لا تضره، ولا يخبر به أحدًا. الذي يرى أنه عريانًا، أو يرى أنه يضرب، أو يقتل، أو ما أشبه ذلك، أو يرى أن وجهه أسود، أو يرى أنها قد مزقت ثيابه، أو ما أشبه ذلك من الرؤيا المكروهة، يعلم أنها من الشيطان، فإذا استيقظ يتفل عن يساره ثلاث مرات، ويقول: أعوذ بالله من الشيطان، ومن شر ما رأيت ثلاث مرات، ثم ينقلب على جنبه الآخر، ولا يخبر بها أحدًا؛ فإنها لا تضره.  وقد جاء في السنة ما يدل على أن العري، نقص في الدين، والكسوة كمال في الدين، فينبغي لمن رأى أنه عريان، أن يحاسب نفسه، وأن ينظر في أمره، لعل عنده معاصي وسيئات؛ فليبادر بالتوبة، ويبادر بالرجوع إلى الله . وبكل حال فالرؤيا المكروهة من الشيطان؛ فليحذر، قد رأى النبي ﷺ عرض عليه الناس، وعليهم قمص، منهم من يسحب قميصه، ومنهم من قمصهم مرتفعة، فسأل عن هذا؛ فأولها بالدين، وكمال الدين. المقصود: أن صبوغ الملابس، ورفاء الملابس علامة الخير، وكون الملابس قصيرة في النوم، أو عريان في النوم علامة قبيحة، ولا يمنع أن يكون هذا من الشيطان، إذا كان يعلم من نفسه الخير، وأنه مستقيم؛ فالحمد لله، فليعلم أن هذا من الشيطان، وأن الشيطان يريد أن يؤذيه، ويحزنه، فلا يلتفت إليه، ولا يخبر بهذه الرؤيا أحدًا، ويتفل عن يساره ثلاث مرات، وليتعوذ بالله من الشيطان، ومن شر ما رأى ثلاث مرات، ثم ينقلب على جنبه الآخر.  وإن كان يعلم من نفسه أنه مقصر في  أمر الله، ما يصلي، أو ما يزكي، أو ما يصوم، أو يشرب الخمر، أو يتعاطى الأمور المحرمة؛ فليبادر بالتوبة؛ فإن هذا هو العري، نقص الدين، ووجود المعاصي هذا هو العري، هذا هو النقص في الملابس، فإن الدين لباس، قال الله -جل وعلا-: وَلِبَاسُ التَّقْوَى ذَلِكَ خَيْرٌ [الأعراف:26] فالدين لباس عظيم، وهو أعظم اللباس، وأشرف اللباس، أعظم من لباس الدنيا.","link":"https://binbaz.org.sa/fatwas/1502/ما-ينبغي-لمن-راى-رويا-مكروهة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_432.mp3","categories":["اللباس والزينة"]},{"id":6096,"question":"أرى فيما يراه النائم أنه يمشي عريانًا بدون ملابس مع الناس، فما تفسير ذلك؟","title":"ما ينبغي لمن رأى رؤيا مكروهة","answer":"الجواب: هذه رؤيا قبيحة، وما ينبغي ذكرها الذي يمشي عريانًا، النبي -عليه الصلاة والسلام- قال: الرؤيا الصالحة من الله، والحلم من الشيطان، فإذا رأى أحدكم ما يكره؛ فليتعوذ بالله من الشيطان، ومن شر ما رأى ثلاث مرات، ثم ينقلب على جنبه الآخر، فإنها لا تضره، ولا يخبر به أحدًا. الذي يرى أنه عريانًا، أو يرى أنه يضرب، أو يقتل، أو ما أشبه ذلك، أو يرى أن وجهه أسود، أو يرى أنها قد مزقت ثيابه، أو ما أشبه ذلك من الرؤيا المكروهة، يعلم أنها من الشيطان، فإذا استيقظ يتفل عن يساره ثلاث مرات، ويقول: أعوذ بالله من الشيطان، ومن شر ما رأيت ثلاث مرات، ثم ينقلب على جنبه الآخر، ولا يخبر بها أحدًا؛ فإنها لا تضره.  وقد جاء في السنة ما يدل على أن العري، نقص في الدين، والكسوة كمال في الدين، فينبغي لمن رأى أنه عريان، أن يحاسب نفسه، وأن ينظر في أمره، لعل عنده معاصي وسيئات؛ فليبادر بالتوبة، ويبادر بالرجوع إلى الله . وبكل حال فالرؤيا المكروهة من الشيطان؛ فليحذر، قد رأى النبي ﷺ عرض عليه الناس، وعليهم قمص، منهم من يسحب قميصه، ومنهم من قمصهم مرتفعة، فسأل عن هذا؛ فأولها بالدين، وكمال الدين. المقصود: أن صبوغ الملابس، ورفاء الملابس علامة الخير، وكون الملابس قصيرة في النوم، أو عريان في النوم علامة قبيحة، ولا يمنع أن يكون هذا من الشيطان، إذا كان يعلم من نفسه الخير، وأنه مستقيم؛ فالحمد لله، فليعلم أن هذا من الشيطان، وأن الشيطان يريد أن يؤذيه، ويحزنه، فلا يلتفت إليه، ولا يخبر بهذه الرؤيا أحدًا، ويتفل عن يساره ثلاث مرات، وليتعوذ بالله من الشيطان، ومن شر ما رأى ثلاث مرات، ثم ينقلب على جنبه الآخر.  وإن كان يعلم من نفسه أنه مقصر في  أمر الله، ما يصلي، أو ما يزكي، أو ما يصوم، أو يشرب الخمر، أو يتعاطى الأمور المحرمة؛ فليبادر بالتوبة؛ فإن هذا هو العري، نقص الدين، ووجود المعاصي هذا هو العري، هذا هو النقص في الملابس، فإن الدين لباس، قال الله -جل وعلا-: وَلِبَاسُ التَّقْوَى ذَلِكَ خَيْرٌ [الأعراف:26] فالدين لباس عظيم، وهو أعظم اللباس، وأشرف اللباس، أعظم من لباس الدنيا.","link":"https://binbaz.org.sa/fatwas/1502/ما-ينبغي-لمن-راى-رويا-مكروهة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_432.mp3","categories":["اللباس والزينة"]},{"id":6119,"question":"ما حكم تقصيب بشوت الرجال؟","title":"حكم تقصيب بشوت الرجال","answer":"الجواب: لا نعلم فيه شيئًا، إذا كان من غير الذهب، والفضة من أنواع الصفر اللماع، فلا نعلم فيها شيئًا، أما جعل الذهب فلا يجوز إذا وجد ذلك إذا قدر ذلك. والذي عليه من أهل الخبرة أن هذا الشيء الذي في الزري هذا ليس بذهب، وإنما هي أشياء من أنواع الصفر اللماع الذي يظن أنه ذهب، وليس بذهب، والصفر يسمى شبهه، يعني يشبه الذهب لما فيه من الصفرة، واللمعان في بعض الأحيان ولكن ليس بذهب، والفضة أسهل من الذهب، ولكن لا ينبغي أيضًا استعمالها لو وجد.","link":"https://binbaz.org.sa/fatwas/1529/حكم-تقصيب-بشوت-الرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_459.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":6153,"question":"ما حكم إزالة الشعر من اليدين، والساقين للنساء؟","title":"حكم إزالة الشعر من اليدين والساقين للنساء والرجال","answer":"الجواب: سبق أنه لا نعلم فيه شيئًا، أما النمص، وهو حلق الحاجبين فهذا لا يجوز، أما شعر البدن في اليدين، أو الرجل ما نعلم فيه شيئًا، إنما الحديث جاء بلعن النامصة، والمتنمصة، وذلك أخذ شعر الوجه من ... أو الحاجبين، نص عليه أهل العلم .. فلا يجوز أخذ الحاجبين، ولا نمصهما، ولا شعر الوجه العادي .. أما كونه يأخذ الرجل، أو المرأة شعر اليدين، أو الرجلين؛ فلا بأس، ويشرع للرجل، والمرأة جميعًا أخذ شعر الإبطين، والعانة تحلق، والإبطين تنتف، والشارب يقص، هذا هو السنة، والظفر يقلم، هذا سنة للجميع للنساء والرجال، السنة ألا يتأخر ذلك أكثر من أربعين ليلة، يقول أنس : وقت لنا في قص الشارب، وقلم الظفر، ونتف الإبط، وحلق العانة ألا نترك ذلك أكثر من أربعين ليلة. والمشروع للجميع للرجل، والمرأة قلم الظفر، ونتف الإبط، وحلق العانة في أقل من أربعين ليلة، يعني يتعاهد ذلك، والشارب في حق الرجل كذلك لا يترك أكثر من أربعين ليلة، بل يتعاهد، ويقص قبل ذلك؛ لأنه يطول، ويقبح.","link":"https://binbaz.org.sa/fatwas/1612/حكم-ازالة-الشعر-من-اليدين-والساقين-للنساء-والرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_506.mp3","categories":["الآداب والأخلاق","اللباس والزينة"]},{"id":6197,"question":"هل يجب على الغلام غير البالغ أن يجعل إزاره فوق كعبيه؟","title":"حكم الإسبال لغير البالغ","answer":"الجواب: يجب على الذكر أن يكون إزاره، وسراويله، وقميصه لا يزيد عن الكعب، ولو كان ما بلغ، قال النبي ﷺ: ما أسفل الكعبين من الإزار فهو في النار وقد بين ﷺ أن الإسبال من الكبائر، قال: ثلاثة لا يكلمهم الله، ولا ينظر إليهم يوم القيامة، ولا يزكيهم، ولهم عذاب أليم وذكر المسبل.  فلا يجوز للرجل، ولو كان ما بلغ الحلم، ليس له أن يسبل ثيابه، وليس له أن يلبس الحرير، والذهب؛ لأنه مخاطب بذلك ممنوع، على وليه أن يمنعه من ذلك. والنساء يرخين الثياب حتى يغطين أقدامهن؛ لأنهن فتنة عورة، ومن المصائب أنه الآن وجد العكس، صار الرجل -والعياذ بالله إلا من هداه الله- يرخي ثيابه، ويجرها، وصارت المرأة ترفع ثيابها، فهذا انتكاس، نعوذ بالله من ذلك، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/1648/حكم-الاسبال-لغير-البالغ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_535.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":6201,"question":"هل يجب على الغلام غير البالغ أن يجعل إزاره فوق كعبيه؟","title":"حكم الإسبال لغير البالغ","answer":"الجواب: يجب على الذكر أن يكون إزاره، وسراويله، وقميصه لا يزيد عن الكعب، ولو كان ما بلغ، قال النبي ﷺ: ما أسفل الكعبين من الإزار فهو في النار وقد بين ﷺ أن الإسبال من الكبائر، قال: ثلاثة لا يكلمهم الله، ولا ينظر إليهم يوم القيامة، ولا يزكيهم، ولهم عذاب أليم وذكر المسبل.  فلا يجوز للرجل، ولو كان ما بلغ الحلم، ليس له أن يسبل ثيابه، وليس له أن يلبس الحرير، والذهب؛ لأنه مخاطب بذلك ممنوع، على وليه أن يمنعه من ذلك. والنساء يرخين الثياب حتى يغطين أقدامهن؛ لأنهن فتنة عورة، ومن المصائب أنه الآن وجد العكس، صار الرجل -والعياذ بالله إلا من هداه الله- يرخي ثيابه، ويجرها، وصارت المرأة ترفع ثيابها، فهذا انتكاس، نعوذ بالله من ذلك، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/1648/حكم-الاسبال-لغير-البالغ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_535.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":6204,"question":"الإسبال في الإزار، والثياب؟","title":"الألبسة التي فيها الإسبال","answer":"الجواب:\n\nكله، السراويل، والإزار ،والقميص، والبشت كله يجب أن تكون فوق الكعب، لا تنزل عن الكعب، ولا ينبغي للعاقل أن يغتر بهؤلاء المساكين الذين تساهلوا في هذه الأمور في هذا المنكر.\n\nوإذا كان يفعله تكبرًا، وبطرًا فإثمه أكبر -والعياذ بالله- وصارت المصيبة أعظم، أما إذا فعله تساهلًا، وقلة مبالاة، وهو محرم، ومنكر، ولكن أقل ممن يفعله تكبرًا.\n\nفالغالب أن الذي يجر ثيابه إنما يجرها تكبرًا، وتعاظمًا في نفسه، وفي الحديث الصحيح يقول ﷺ: بينما رجل فيما مضى قبلنا يمشي ببرديه، يختال ببردين، قد أعجبته نفسه؛خسف الله به الأرض، فهو يتجلجل فيها إلى يوم القيامة نعوذ بالله.. إذا لبس الثياب الجميلة، وجعل يسحبها، يبتلى بالكبر، والعجب بنفسه، ويظن أنه ليس فوقه أحد، فصار في عجب، وتكبر، وشر، فالواجب عليه أن يحذر ذلك، وأن يتواضع لله، وأن يحذر هذا المنكر، وتكون ثيابه من نصاف الساق إلى الكعب. \n\nأسئلة...","link":"https://binbaz.org.sa/fatwas/1651/الالبسة-التي-فيها-الاسبال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_536.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":6218,"question":"ما قول سماحتكم فيمن سأل عن الإسبال، فقال: هو الكبر، هل هذا يعتبر تفسير، أو تغيير لكلام رسول الله؟ وما حكمه؟","title":"الإسبال وسيلة للكبر","answer":"الجواب: الإسبال وسيلة إلى الكبر، وليس هو الكبر، لكن في الغالب أنه وسيلة، والغالب أنه يدعو إلى الكبر، وأما أنه هو الكبر بعينه لا، لكنه وسيلة إلى الكبر، وذريعة إليه، ولهذا حرمه الإسلام، ونهى عنه؛ لأنه وسيلة إلى الكبر، وهو وسيلة إلى إفساد الثياب، وتنجيسها، وتوسيخها، وإعدامها، ولما رأى عمر  شابًا يمس ثوبه الأرض، قال له: يا عبدالله، ارفع ثوبك؛ فإنه أتقى لربك، وأنقى لثوبك.","link":"https://binbaz.org.sa/fatwas/1707/الاسبال-وسيلة-للكبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_564.mp3","categories":["الأخلاق المذمومة","اللباس والزينة","الخِطْبَة والاختيار "]},{"id":6250,"question":"ما رأيكم فيمن يقول هذا؟ ولماذا لم تردوا عليه في نفس هذه الأجهزة، جزاكم الله خيرًا؟","title":"أدلة كون وجه المرأة عورة","answer":"الجواب:  هذه مسألة خلاف بين العلماء، منهم من قال: إنه عورة، ويجب ستره عن الناس، وهذا هو الصواب، والصواب والحق أنه عورة، وهو عنوان المرأة، وأبرز ما يدل على محاسنها، أو على قبحها، ويدل على هذا قوله سبحانه: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعاً فَاسْأَلُوهُنَّ مِن وَرَاء حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53].  وقال -جل وعلا-: وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ.. [النور:31] الآية، وقال آخرون: ليس من الزينة، ولا بأس بإخراجه؛ لأنها بحاجة إلى إبرازه، واحتج بعضهم بقوله -جل وعلا-: وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنْهَا [النور:31] قالوا: ما ظهر منها هو الوجه، وهذا يروى عن ابن عباس، وبعض السلف.  والصواب: أن ما ظهر منها هو الملابس، كما قاله ابن مسعود، وجماعة آخرون من أهل العلم، ولهذا قال في الآية الأخرى: وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ.. [النور:31] ولم يقل إلا الوجه، والكفين، بل عمم، وقال في الآية الأخرى: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعاً فَاسْأَلُوهُنَّ مِن وَرَاء حِجَابٍ [الأحزاب:53] ما قال إلا عن الوجه، قال من وراء حجاب، وأطلق، ثم قال: ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] وبين سبحانه أن الحجاب أطهر لقلوب الجميع، الرجال، والنساء. أما الرد فقد كتبنا ردًا، وكتب غيرنا، والمسألة معروفة عند العلماء.\n\nالسؤال: حديث عائشة في إذا بلغت المرأة المحيض..؟ الجواب:  هذا حديث أسماء بنت أبي بكر ضعيف، ليس بصحيح، جاء عن أسماء بنت أبي بكر أنها دخلت على النبي ﷺ وعليها ثياب رقاق، فأعرض عنها النبي ﷺ وقال: يا أسماء، إن المرأة إذا بلغت المحيض؛ لم يحل أن يرى منها إلا هذا وهذا، وأشار إلى وجهه، وكفيه احتج به من قال بكشف الوجه، ولكنه حديث ضعيف، لا يصح عن النبي ﷺ رواه أبو داود بإسناد منقطع، عن عائشة، وفي إسناده أيضًا رجل ضعيف، يقال له: سعيد بن بشير، ضعيف لا يحتج به، والذي رواه عن عائشة لم يسمع منها، وهو خالد بن دريك، لم يسمع منها، ولم يدركها مع علة ثالثة أيضًا، وهي عنعنة قتادة، وتدليسه، هذه ثلاث علل كلها توجب عدم صحته، ولو صح؛ لكان فيصلًا. وحديث عائشة في الركب أنهم كانوا مع النبي ﷺ في حجة الوداع قالت: كنا نكشف وجوهنا، فإذا دنا منا الرجل؛ سدلت إحدانا خمارها على وجهها حتى يبتعد، كذلك حديثها في قصة الإفك، قالت: لما سمعت استرجاع صفوان؛ خمرت وجهي، وكان يعرفني قبل الحجاب؛ فدل ذلك على أنهن بعد الحجاب صاروا يخمرون الوجوه، ويسترونها، وإنما كانت تكشف قبل الحجاب.","link":"https://binbaz.org.sa/fatwas/1788/ادلة-كون-وجه-المراة-عورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_627.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":6288,"question":"الأصل  في المرأة في البيع، والشراء لا بدّ أن تكشف وجهها، أم لا؟","title":"حكم كشف وجه المرأة أثناء البيع والشراء","answer":"الجواب:  لا، ما هو بلازم، تبيع، وتشتري، وهي مستورة، والحمد لله، ما في شيء.\n\nالسؤال: يعني مثلًا اشترت من بائع شيئًا، فالبائع يقول: يعرف وجهها، هل يجب عليه أن يعرف وجهها؟ الجواب: إذا صار مداينة، وهو لا يعرف صوتها، بعضهم رخص أنه يعرف وجهها؛ حتى يحاسبها بعد حين بوجهها، أما إذا كانت معروفة، أو يعرف شهودًا يعرفونها؛ فما في حاجة إلى كشف الوجه.","link":"https://binbaz.org.sa/fatwas/1789/حكم-كشف-وجه-المراة-اثناء-البيع-والشراء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_628.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":6355,"question":"هل الذهب محرم كما يقول الشيخ الألباني في كتابه عنوان آداب الزفاف، وأيضا في الحج يقول: إن مناسك الحج واحد، وهو التمتع؟","title":"الرد على القول بتحريم الذهب للنساء وأن الحج تمتع فقط","answer":"الجواب: لا، هذا غلط، مباح للحديث، مباح للأنثى، حكى عليه الإجماع، جمع من أهل العلم كالبيهقي، والنووي، والجصاص، وجماعة، وما يروى من بعض الأحاديث الموهمة في التحريم؛ فهي منسوخة، فالذهب حل للنساء، كالحرير، ومحرم على الذكور. وكذلك مسألة الحج أنساك الحج ثلاثة: القران، والتمتع، وإفراد الحج، لكن التمتع أفضل، وأما إفراد الحج، والقران فهو جائز، وإنما الرسول ﷺ أمر الصحابة أن يحلوا لحكمة ظاهرة، أن يحلوا، ويجعلوها عمرة؛ لأن أهل الجاهلية كانوا ينكرون العمرة في أشهر الحج، ويرونها من أفجر الفجور، وأمرهم النبي أن يحلوا، ويجعلوها عمرة وقال: لولا أني أهديت لأحللت معكم؛ ليبين للناس فضل العمرة، ولم ينسخ الحج -عليه الصلاة والسلام- فالحج باق، والقران باق، ولهذا فعله الصحابة بعده، وهم أعلم الناس به، أفرد الصديق، وأفرد عمر، وأفرد عثمان -رضي الله عنهم وأرضاهم- وقرن عليّ بين الحج، والعمرة في عهد عثمان، وهكذا فعل الصحابة  لكن التمتع أفضل.  أما القول بأن الحج منسوخ، ولا يصح من النسك إلا التمتع فهذا غلط لا وجه له يخالف إجماع المسلمين، قد أجمع العلماء جميعاً على أن الأنساك ثلاثة: القران، والتمتع، وإفراد الحج عند جميع أهل العلم، فمن زعم أن الحج نسخ، وأنه لم يبق؛ فهذا غلط.","link":"https://binbaz.org.sa/fatwas/1940/الرد-على-القول-بتحريم-الذهب-للنساء-وان-الحج-تمتع-فقط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_726.mp3","categories":["مسائل متفرقة في الحج والعمرة","اللباس والزينة","قضايا المرأة"]},{"id":6363,"question":"فضيلة الشيخ متى تكلف المرأة بالأحكام الشرعية من عمرها؟","title":"وقت تكليف المرأة بالأحكام الشرعية","answer":"الجواب: المرأة مثل الرجل، تكلف المرأة مثل الرجل، تكلف بأمور ثلاثة، وتزيد رابعًا هي، متى بلغت خمسة عشرة سنة، وأكملتها؛ صارت امرأة مكلفة بالصلاة، وغيرها، والصيام، والحج، ونحو ذلك. وكذلك إذا أنبتت الشعر الخشن، تسمى الشعرة العانة على الفرج؛ صارت مكلفة -أيضاً- كالرجل، وهكذا بالإنزال، إذا أنزلت المني بشهوة عن نظر، وعن تفكير، أو عن احتلام؛ فهي تكون بهذا مكلفة كالرجل، هذه الأمور الثلاثة مشتركة بين الرجال، والنساء. أولاً: بلوغ خمسة عشر سنة على الراجح، إذا أكملت خمسة عشر سنة؛ صارت امرأة مكلفة بأحكام الدين كالرجل، سواء. الثاني: إنبات الشعر الخشن حول الفرج، هذا أيضاً من أسباب التكليف من الرجل، والمرأة جميعاً. الثالث: إنزال المني بشهوة، سواء باحتلام، أو عن تفكير، أو نظر، ونحو ذلك، فمتى أنزلت، أو أنزل المني؛ صارا مكلفين. والأمر الرابع: يختص بها وهو الحيض، فمتى حاضت؛ صارت مكلفة بذلك. هذه الأمور هي التي بها التكليف للمرأة، والرجل جميعاً، وهي ثلاثة مشتركة، والرابع للمرأة خاصة، وهو الحيض.","link":"https://binbaz.org.sa/fatwas/1941/وقت-تكليف-المراة-بالاحكام-الشرعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_728.mp3","categories":["قضايا المرأة","أصول الفقه","اللباس والزينة"]},{"id":6377,"question":"ما هو النمص؟ وما حكمه؟ وأين يتم في جسم الإنسان؟ وهل يشمل الرجال، والنساء؟","title":"حكم النمص","answer":"الجواب: النمص هو أخذ شعر الحاجبين، وألحق به بعض أهل العلم شعر الوجه المعتاد، فلا يجوز نمصه، النبي ﷺ لعن النامصة، والمتنمصة، قال أهل العلم: النمص أخذ شعر الحاجبين بالمنماص، وهو المنقاش، تزين شعر حاجبيها بالمناقيش حتى تأخذ بعض الشعرات، فإذا كان بالمنقاش يحرم، فكيف بأكثر من المنقاش؟!  السؤال: كذلك شعر اليدين، والرجلين؟ الجواب: اليدين، والرجلين ما ورد فيها شيء، ما نعلم فيها شيئًا.","link":"https://binbaz.org.sa/fatwas/1955/حكم-النمص","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_742.mp3","categories":["الأخلاق المذمومة","اللباس والزينة","الخِطْبَة والاختيار "]},{"id":6387,"question":"ما هو النمص؟ وما حكمه؟ وأين يتم في جسم الإنسان؟ وهل يشمل الرجال، والنساء؟","title":"حكم النمص","answer":"الجواب: النمص هو أخذ شعر الحاجبين، وألحق به بعض أهل العلم شعر الوجه المعتاد، فلا يجوز نمصه، النبي ﷺ لعن النامصة، والمتنمصة، قال أهل العلم: النمص أخذ شعر الحاجبين بالمنماص، وهو المنقاش، تزين شعر حاجبيها بالمناقيش حتى تأخذ بعض الشعرات، فإذا كان بالمنقاش يحرم، فكيف بأكثر من المنقاش؟!  السؤال: كذلك شعر اليدين، والرجلين؟ الجواب: اليدين، والرجلين ما ورد فيها شيء، ما نعلم فيها شيئًا.","link":"https://binbaz.org.sa/fatwas/1955/حكم-النمص","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_742.mp3","categories":["الأخلاق المذمومة","اللباس والزينة","الخِطْبَة والاختيار "]},{"id":6417,"question":"ما هي نصيحة سماحة الشيخ لكثير من الناس الذين يقول بعضهم: عليك نفسك، ولا دخل لك بالغير؟","title":"حكم قول عليك نفسك ولا دخل لك بالغير","answer":"الجواب: هذا من نواب الشيطان، الذي يقول: عليك بنفسك، ودع عنك الناس من نواب الشيطان، الشيطان له نواب كثيرون في كل مكان، يقول للناس: لا تحركوا ساكنًا، دعوا الناس على ما هم عليه من الباطل، ولا تقولوا لأحد شيئًا، وهذا من نواب الشيطان -نعوذ بالله- فالله يأمرك بأن تأمر بالمعروف، وتنهى عن المنكر، وتدعو إلى الخير، فهل تطيع الشيطان، أو تطيع الرحمن؟ الواجب عليك طاعة الرحمن، والله يقول: وَلْتَكُنْ مِنْكُمْ أُمَّةٌ يَدْعُونَ إِلَى الْخَيْرِ [آل عمران:104]، ويقول سبحانه: وَمَنْ أَحْسَنُ قَوْلًا مِمَّنْ دَعَا إِلَى اللَّهِ وَعَمِلَ صَالِحًا [فصلت:33]، ويقول سبحانه: ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125]. نعم إذا كنت في موضع مثل ما قال فيه النبي ﷺ: رأيت شحًا مطاعًا، وهوى متبعًا، ودنيا مؤثرة، وإعجاب كل ذي رأي برأيه ورأيت أمرًا لا يدان لك فيه بشيء -يعني لا طاقة لك به- فعليك نفسك، وأما ما دمت تستطيع أن تقوم، وتأمر؛ فعليك أن تأمر، وتنهى بلسانك، وعليك أن تأمر وتنهى بالفعل مع القدرة، وأقل ذلك كراهة القلب، ومفارقة المنكر.","link":"https://binbaz.org.sa/fatwas/2135/حكم-قول-عليك-نفسك-ولا-دخل-لك-بالغير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_784.mp3","categories":["اللباس والزينة"]},{"id":6418,"question":"ما حكم صلة زوجة أبي، قد طلقها، وهل تجب علي زيارتها، علمًا بأن والدتي حلفت علي يمينًا ألا أزورها، ماذا أفعل؟","title":"حكم صلة زوجة الأب المطلقة","answer":"الجواب: ليس عليك شيء، إذا طلقها والدك ما هي من الأرحام لك، ولا هي بقريبة، إنما هي زوجة أب مطلقة، فإذا كانت أمك لا ترضى، لا تزورها، هي محرم لك، زوجة أبيك التي طلقها، ومات عنها محرم لك؛ لأن الله قال: وَلَا تَنْكِحُوا مَا نَكَحَ آبَاؤُكُمْ مِنَ النِّسَاءِ [النساء:22] بإجماع المسلمين هي محرم لك، لكن إن زرتها من باب الإحسان، ومن باب تقدير حق والدك؛ هذا حسن، إن زرتها، أو أكرمتها، أو وصلتها بالمال هذا من مكارم الأخلاق، ومن المعروف، لكن ما دام ذلك يغضب أمك، ولا ترضاه أمك؛ فلا تفعل شيئًا مثل هذا يغضب أمك، ولو وصلتها على طريقة سرية لا تعلمها أمك؛ فلا بأس. المقصود: لا تغضب أمك بهذا الطريق، ولا يلزمك أن تزورها، ولا أن تصلها؛ لأنها ليست من الأرحام، ولا من الأقارب، وإنما هي مطلقة أب، أو قد مات عنها، فالإحسان إليها من مكارم الأخلاق، ولكن لا تفعل ذلك إذا كان يضر أمك، وإذا وصلتها خفية من دون علم أمك؛ فلا بأس.","link":"https://binbaz.org.sa/fatwas/2130/حكم-صلة-زوجة-الاب-المطلقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_778.mp3","categories":["اللباس والزينة"]},{"id":6419,"question":"هل الأمر بالمعروف، والنهي عن النكر يعتبر الركن السادس للإسلام؟","title":"حكم اعتبار الأمر بالمعروف والنهي عن المنكر ركناً سادساً للإسلام","answer":"الجواب: ليس الركن السادس، ولكن بعض أهل العلم قال: إنه السادس، ألحقه بالشهادتين والصلاة، والزكاة، والصيام، والحج، وقال: إنه السادس لعظم أمره، ولعظم فائدته، فهو واجب عظيم، وفرض عظيم على المسلمين، ولكنه ليس ركنًا سادسًا؛ لأن الناس لا يشرعون، المشرع هو الله على يد رسوله محمد -عليه الصلاة والسلام- فالرسول ﷺ أخبر أن الإسلام بني على خمس، فليس لأحد أن يزيد ... وليس له التدخل في هذا، هذا إلى الله، وإلى رسوله، عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/2136/حكم-اعتبار-الامر-بالمعروف-والنهي-عن-المنكر-ركنا-سادسا-للاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_785.mp3","categories":["اللباس والزينة"]},{"id":6475,"question":"هل يعد المغني من جنود إبليس؟ وهل تقبل شهادته؟وهل يحاسب المسلم، لو قال لشخص عاصٍ، أو فاسقٍ: أنت أحد جنود إبليس، أو أنت شيطان؟","title":"الدعاة إلى المعاصي من جنود إبليس","answer":"الجواب: كل من دعا إلى الشر هو من جنود إبليس، إبليس له جنود، كل من دعا إلى المعاصي، سواء بالبدع، سواء بالغناء، أو بالكلام غير الغناء، أو بالخطب، أو بغير ذلك، كل من دعا إلى بدعة، أو الشرك، أو المعاصي من المغنيين، والعازفين، وأهل البدع، والدعاة إلى الزنا، والقمار، والمعاصي، كلها كلهم جنود الشيطان.  جنود الشيطان هم دعاة الفساد، وجنود الرحمن هم دعاة الحق، والهدى، فمن دعا إلى الحق بفعله، أو قوله؛ فهو من حزب الله، ومن جنود الله، ومن دعا إلى المعاصي، والبدع، والشرك بالغناء، أو بالكلام الآخر، أو بالخطب، أو بالكتابات، أو بغير هذا؛ فهو من جنود الشيطان.","link":"https://binbaz.org.sa/fatwas/2214/الدعاة-الى-المعاصي-من-جنود-ابليس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_833.mp3","categories":["اللباس والزينة"]},{"id":6480,"question":"من عادات بعض البلاد الإسلامية أن يقدم الرجل لعروسه شبكة عند الزواج منها، ومنها خاتم، أحدهما من الرجل، والثاني للمرأة، وينقش على الخاتم اسمها، فهل هذا تشبه باليهود؟","title":"حكم نقش اسم المرأة على الخاتم الدبلة في الأعراس","answer":"الجواب: لا ينبغي للمؤمن أن يتشبه بأعداء الله، لا ينبغي لأهل الإيمان أن يتشبهوا بأعداء الله، فما كان من عادة أعداء الله لا ينبغي لأهل الإيمان أن يتشبهوا به، لا في الخاتم، ولا في غيره.  ولا يجوز للرجل أن يلبس الخاتم الذي هو يسمونه الدبلة من الذهب؛ لأن الذهب حرام على الرجال، خواتيم الذهب محرمة على الرجال، الرسول ﷺ نهى عن خواتيم الذهب، ولما رأى رجلًا في يده خاتمًا من ذهب؛ نزعه، وطرحه -عليه الصلاة والسلام- وقال: يعمد أحدكم إلى جمرة من نار، فيضعها في يده فهذا يدل على تحريم خواتم الذهب، وأنها من الكبائر؛ لأن فيها الوعيد بالنار، ولا ينبغي التشبه بأعداء الله، لا في الأعراس، ولا في غيرها، ولا ينبغي أن يكتب اسم المرأة في خاتمه، بل يكتب اسمه هو، لا يكتب اسم امرأته في خاتمه، هذا تشبه بأعداء الله، لا يجوز، وهذا نزول، وضعف، وتقصير، لا حول ولا قوة إلا بالله.","link":"https://binbaz.org.sa/fatwas/2237/حكم-نقش-اسم-المراة-على-الخاتم-الدبلة-في-الاعراس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_857.mp3","categories":["اللباس والزينة","الخِطْبَة والاختيار ","البدع والمحدثات"]},{"id":6495,"question":"من عادات بعض البلاد الإسلامية أن يقدم الرجل لعروسه شبكة عند الزواج منها، ومنها خاتم، أحدهما من الرجل، والثاني للمرأة، وينقش على الخاتم اسمها، فهل هذا تشبه باليهود؟","title":"حكم نقش اسم المرأة على الخاتم الدبلة في الأعراس","answer":"الجواب: لا ينبغي للمؤمن أن يتشبه بأعداء الله، لا ينبغي لأهل الإيمان أن يتشبهوا بأعداء الله، فما كان من عادة أعداء الله لا ينبغي لأهل الإيمان أن يتشبهوا به، لا في الخاتم، ولا في غيره.  ولا يجوز للرجل أن يلبس الخاتم الذي هو يسمونه الدبلة من الذهب؛ لأن الذهب حرام على الرجال، خواتيم الذهب محرمة على الرجال، الرسول ﷺ نهى عن خواتيم الذهب، ولما رأى رجلًا في يده خاتمًا من ذهب؛ نزعه، وطرحه -عليه الصلاة والسلام- وقال: يعمد أحدكم إلى جمرة من نار، فيضعها في يده فهذا يدل على تحريم خواتم الذهب، وأنها من الكبائر؛ لأن فيها الوعيد بالنار، ولا ينبغي التشبه بأعداء الله، لا في الأعراس، ولا في غيرها، ولا ينبغي أن يكتب اسم المرأة في خاتمه، بل يكتب اسمه هو، لا يكتب اسم امرأته في خاتمه، هذا تشبه بأعداء الله، لا يجوز، وهذا نزول، وضعف، وتقصير، لا حول ولا قوة إلا بالله.","link":"https://binbaz.org.sa/fatwas/2237/حكم-نقش-اسم-المراة-على-الخاتم-الدبلة-في-الاعراس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_857.mp3","categories":["اللباس والزينة","الخِطْبَة والاختيار ","البدع والمحدثات"]},{"id":6591,"question":"كثير من الناس يعرفون الطريق المستقيم، ولكنهم لا يتمسكون به، ما هي الأسباب التي تمنعهم عن التمسك؟ وما هي طرق العلاج التي تجعلهم يسلكون هذا الطريق المستقيم، جزاكم الله خيرًا؟","title":"أسباب ترك الحق","answer":"الجواب: الأسباب كثيرة، التخلف عن الحق أسبابها كثيرة، تارة يكون جاهلًا، وتارة يكون عنده علم بالحق، ولكن يحمله الهوى؛ لأنه ما وافق هواه، فيحمله الهوى على ترك الحق، وتارة يفعله مجاملة لبعض أقاربه، وأصحابه، يجاملهم ما وده يكدرهم إذا وافق الحق، فيجاملهم، فيشرب معهم الخمر، ويعصي معهم ربه في قطيعة الرحم، في العقوق، في غير ذلك مجاملة لأقاربه، أو أصدقائه، أو ما أشبه ذلك، وتارة يعصي الله من أجل المال الذي يعطى إياه، وتارة من أجل الوظيفة، لها أسباب كثيرة، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/2434/اسباب-ترك-الحق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_961.mp3","categories":["اللباس والزينة"]},{"id":6604,"question":"طيب، وبالمناسبة تطويل شعر الرأس؟","title":"حكم إطالة شعر الرأس","answer":"الجواب: هذا أصله جائز، كان العرب يطولون رؤوسهم، والنبي ﷺ كان يعفي رأسه ﷺ، ربما وصل إلى منكبه، وربما ارتفع على حسب حلقه حين يحلقه في الحج، والعمرة، يحلقه في الحج، ويقصره في العمرة -عليه الصلاة والسلام- فإذا طوله الإنسان لا لمقصد سيئ، لا لأجل النساء، ولا لأجل الفتنة؛ فلا حرج في ذلك، وإن كان تطويله في مكان، في بلد، أو في قرية يتهم فيه بالسوء، أو يظن به السوء؛ فينبغي له تركه؛ حتى لا يتهم بالسوء، وإذا طوله من أجل النساء، والفتنة، ومغازلة النساء؛ كان منكرًا، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/2445/حكم-اطالة-شعر-الراس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_972.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":6610,"question":"طيب، وبالمناسبة تطويل شعر الرأس؟","title":"حكم إطالة شعر الرأس","answer":"الجواب: هذا أصله جائز، كان العرب يطولون رؤوسهم، والنبي ﷺ كان يعفي رأسه ﷺ، ربما وصل إلى منكبه، وربما ارتفع على حسب حلقه حين يحلقه في الحج، والعمرة، يحلقه في الحج، ويقصره في العمرة -عليه الصلاة والسلام- فإذا طوله الإنسان لا لمقصد سيئ، لا لأجل النساء، ولا لأجل الفتنة؛ فلا حرج في ذلك، وإن كان تطويله في مكان، في بلد، أو في قرية يتهم فيه بالسوء، أو يظن به السوء؛ فينبغي له تركه؛ حتى لا يتهم بالسوء، وإذا طوله من أجل النساء، والفتنة، ومغازلة النساء؛ كان منكرًا، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/2445/حكم-اطالة-شعر-الراس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_972.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":6619,"question":"هل يجوز نتف شيب الرأس، ولو كان قليلًا؟","title":"حكم نتف الشيب وصبغ الشعر بالسواد","answer":"الجواب: هذا ورد في المحاضرة، لا ينبغي نتف الشيب، الشيب لا ينتف نور المسلم، وجاء في الحديث الآخر: أنه من شاب شيبة؛ كتب الله بها حسنة فلا ينبغي نتف الشيب، أقل أحواله الكراهة الشديدة، فلا ينبغي نتف الشيب، وإن كان في اللحية؛ صار أشد، فلا يجوز نتفه من اللحية، ويكره نتفه من الرأس؛ فإنه نور المسلم، ولم يثبت عن النبي ﷺ ولا عن أصحابه نتفه، فلا ينبغي نتفه.  ولا ينبغي أيضًا الصبغ بالسواد، سمعت من بعض الناس قد يصبغ بالسواد، وهذا لا يجوز، النبي ﷺ قال: غيروا هذا الشيب، وجنبوه السواد. فالسنة أن يغير بالحمرة، أو بالحناء والكتم، أما دعوى بعض الناس أن قوله: وجنبوه السواد أنه مدرج، هذا غلط ليس بمدرج، بل هو نفس كلام النبي -عليه الصلاة والسلام- غيروا هذا الشيب، وجنبوه السواد رواه مسلم في الصحيح، وجماعة آخرون من أهل العلم، وفي السنن، وفي مسند أحمد عن النبي ﷺ أنه قال: يكون في آخر الزمان قوم يخضبون بالسواد كحواصل الحمام، لا يريحون رائحة الجنة نسأل الله العافية، هذا وعيد شديد يدل على شدة التحريم.  ولما رأى النبي ﷺ رأس أبي قحافة، شيخ كبير، والد الصديق ، رأى رأسه، ولحيته كالثغامة بياضًا، قال ﷺ: غيروا هذا الشيب، وجنبوه السواد لكن إن خالطه بالكتم، بالحناء والكتم، بالحناء وحده؛ لا بأس، أما سواد خالص؛ فلا يجوز، وإن فعله بعض الناس لا يغتر ببعض الناس، قد فعله بعض السلف، ويروى عن بعض الصحابة أنه فعله، لكن يحمل ذلك على أنهم ما بلغهم النهي، من فعله من الصحابة، ومن السلف من أهل العلم الأوائل؛ فهو محمول على أنهم ما بلغهم النهي، لو بلغهم النهي؛ لبادروا إلى الترك، ولم يفعلوا رضي الله عنهم وأرضاهم. السؤال: يجوز للقائد، أو الحاكم؟ الجواب: لا، ليس لأحد.","link":"https://binbaz.org.sa/fatwas/2447/حكم-نتف-الشيب-وصبغ-الشعر-بالسواد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_974.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":6665,"question":"كنت في الشباب ووالدي عندي، وكثيرًا ما أتضايق من تدخلهم في شؤوني، وفيما بيني، وبين أولادي، وأتأفف من ذلك إلى غير ذلك، وقد توفيا، وتندمت غاية الندم مما حدث، فهل لي كفارة لذلك؟","title":"صور الإحسان إلى الوالدين بعد موتهما","answer":"الجواب: نعم نعم، عليك التوبة إلى الله، والندم مما فعلت مع والديك، والمعنى: أن تندم على ماضيك، وأن تقلع من ذلك بعد وفاتهما من الكلام فيما يسؤوهما، أو التحدث فيما يسؤوهما، أو ذكر شيء من عيوبهما بعد ذلك، تحفظ لسانك عنهما إلا بالدعاء لهما، والاستغفار لهما، والترحم عليهما، والإحسان إليهما بما تستطيع من صدقة عنهما، ونحو ذلك، والحذر من العودة إلى ما حرم الله عليك، فالتوبة تجب ما قبلها، والحمد لله.","link":"https://binbaz.org.sa/fatwas/2560/صور-الاحسان-الى-الوالدين-بعد-موتهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1055.mp3","categories":["اللباس والزينة"]},{"id":6685,"question":"بين والدي وعمي خصومة من أجل دنيا، فهل يجوز لي صلة عمي، ولو كان ذلك لا يرضي والدي؟","title":"حكم صلة أحد الأقارب إذا كان بينه وبين الأب خصومة","answer":"الجواب: نعم نعم، إذا كان بين عمك، وأبيك خصومة من أجل دنيا بينهما؛ فلا مانع من النصيحة لهما جميعًا؛ ليحلوا الخصومة، بل يشرع لك ذلك، بل يجب عليك إذا استطعت أن تحل هذا المشكل، وأن تتوسط بينهما بالخير؛ لأنها من صلة الرحم، ومن بر والدك، ومن صلة عمك. فالواجب عليك وعلى إخوتك أن تحلوا المشكلة بما تستطيعون من النصيحة، والمعاونة؛ حتى يزول هذا الإشكال، وحتى تصلح القلوب، وتصفو القلوب، وإذا لم يتيسر ذلك، أو عجزتم عن ذلك؛ فلا مانع من صلة عمك بالطريقة الطيبة، البعيدة عن إغضاب أبيك، بطريقة خفية تصل بها عمك، وتنصح بها لعمك، ولكنها خفية عن أبيك؛ حتى لا يتضايق منك، وحتى لا يسيئ إليك، ولكنها طريقة تجمع المصلحتين، بقاء حال أبيك معك، وصلة رحم عمك فيما ينفعه -إذا كان محتاجًا فقيرًا- بمال، أو بغير هذا من أنواع الصلة التي تنفعه، وتعينه على طاعة الله، وعلى حل المشكل، ولكن بالطريقة التي لا تسيء بها إلى أبيك، ولا يطلع عليها أبوك؛ حتى لا يزداد سوء الحال بينك، وبين أبيك.","link":"https://binbaz.org.sa/fatwas/2561/حكم-صلة-احد-الاقارب-اذا-كان-بينه-وبين-الاب-خصومة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1056.mp3","categories":["اللباس والزينة"]},{"id":6703,"question":"حصل في يوم عرفة، وفي مسجد عرنة أن يقوم أحد الأشخاص بالتلبية بمكبرات الصوت، ثم يلبي الناس جميعهم خلفه، واستمر هذا الفعل عدة مرات، السؤال هل هذا جائز أن يلبي؟ وإذا لم يكن جائزًا، نرجو التنبيه على ذلك مستقبلًا؟","title":"حكم التلبية بمكبرات الصوت","answer":"الجواب: التلبية مشروعة للجميع، كل يلبي على حدته، أما كونه يلبي بالمكبر ليذكر الناس من باب التذكير، والترجيع، لا من باب التكبير الجماعي، ولا التلبية الجماعية، فالتنبيه بالمكبر عند غفلة الناس ليسمعوا لا مانع في هذا، أما يكون تلبية جماعية بأصوات مجتمعة فلا.","link":"https://binbaz.org.sa/fatwas/2576/حكم-التلبية-بمكبرات-الصوت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1071.mp3","categories":["اللباس والزينة","مسائل متفرقة في الحج والعمرة","ردود وتعقيبات"]},{"id":6718,"question":"تكثر في هذه الأيام مباريات كرة القدم، وتنقل عبر التلفزيون، فما حكم مشاهدتها إذا لم تكن بعصبية، ولا تشبيه، وإنما للترويح فقط عن النفس؟","title":"حكم مشاهدة مبارايات كرة القدم","answer":"الجواب:  الذي يظهر لنا من لعب كرة القدم: أنها مشغلة عن الخير، ومشغلة عن الصلوات في الجماعة، والذي ينبغي تركها، لو صينت، وكانت في أوقات قليلة، ومعها ضبط العورات، وصيانة العورات وإقامة الصلوات، لو كان هذا مضبوطًا؛ لكان الأمر أسهلًا، لكن مع ما نشاهده من الناس من الشغل بها، والفتنة بها، وتضييع الصلوات من المشاهدين، واللاعبين، فالذي نعتقده أن هذا العمل محرم، ومنكر، ولا يجوز فعله أبدًا، لا في هذه البلاد، ولا في غيرها من المسلمين؛ لأن فعلهم هذا أفضى بهم إلى شر عظيم، شغلوا الناس في الإذاعات، شغلوهم في التلفاز، شغلوهم في الأوقات، وضيعوا الصلوات، وكثير منهم يلبس لباسًا يبدي عورته، يبدي فخذيه، يفتن الناس به، فكل هذا من المنكرات التي لا مبرر لها. الحاصل: أن كرة القدم التي يفعلها الناس اليوم شرها عظيم، وخيرها معدوم، وإن كان فيها خير؛ فهو قليل جدًا من جهة النشاط، واحتياج القوة، مغمور هذا الخير القليل في جنب الشر الكثير. فالذي نعتقده اليوم: أن فعلها محرم، وأنها منكر، إلا إذا التزم أهلها بالستر، وحفظ الأوقات، وإقامة الصلوات في وقتها، وصار لعبها في وقت خاص محدود، لا يتجاوزه إلى أن يضيعوا به الصلوات، إما المشاهدون، وإما اللاعبون، وإما الجميع، هذا الواقع نسأل الله السلامة.  السؤال: يا شيخ متعرون عريًا شديدًا؟ الجواب: الله يهديهم، الله يردهم إلى الصواب. السؤال: تكتبون لهم يا شيخ أو؟ الجواب: الله المستعان، كم كتب، وكم كتب، الله المستعان، لا تفكر أن الأمر هكذا، قد بذلت فيها الأسباب، ولكن نسأل الله لنا ولهم الهداية.","link":"https://binbaz.org.sa/fatwas/2594/حكم-مشاهدة-مبارايات-كرة-القدم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1090.mp3","categories":["اللباس والزينة"]},{"id":6792,"question":"يقول بعض المشايخ، وطلبة العلم: عندنا في المملكة أن الحجاب للمرأة، وبخاصة ستر الوجه هو من خصوصيات زوجات النبي ﷺ وبناته، أفتونا في هذه المسألة وليس..؟","title":"خطأ من يقول بأن الحجاب خاص بزوجات النبي وبناته","answer":"الجواب: هذا غلط، الذي يقوله غلطان، إذا كان أزواج النبي ﷺ وهن من أتقى النساء، فغيرهن من باب أولى، فيمنعن من السفور، ويأمرن بالحجاب، ثم إن الله  ذكر علة تدل على أن المطلوب نساء النبي، وغير نساء النبي، قال تعالى: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] فالطهارة مطلوبة لنساء النبي، فقط وإلا للجميع؟ الطهارة مطلوبة للجميع، وغير نساء النبي ﷺ أحوج؛ لأن إيمانهن أقل.  فالمقصود: أن العلة التي بينها الرب -جل وعلا- عامة ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] ثم الأصل في الأحكام التعميم، ومن قال بالخصوصية؛ فعليه الدليل، الله ما قال هذا خاص بنساء النبي، ولا قاله الرسول، بل هو عام، وهكذا قال -جل وعلا-: يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلَابِيبِهِنَّ [الأحزاب:59] فعمم الجميع.","link":"https://binbaz.org.sa/fatwas/2675/خطا-من-يقول-بان-الحجاب-خاص-بزوجات-النبي-وبناته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1172.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":6854,"question":"نرجو توضيح القلب الذي أشار إليه فضيلة الشيخ، ومكانه، هل هو القلب المخصوص الذي يضخ الدم، أم هو غيره؟، والله يحفظكم.","title":"مكان القلب في جسم الإنسان","answer":"الجواب: الأول نشكر له شعوره الطيب، ونسأل الله أن يحفظنا، وإخواننا جميعًا من كل سوء، وأن يمن علينا، وعلى جميع إخواننا بالسلامة من كل بلاء، ومن كل..  ونقول لأخينا: أحبك الله الذي أحببتنا له، ونسأله أن يجعلنا جميعًا من المتحابين في الله، الذين جاؤوا في الحديث الصحيح، يقول النبي ﷺ: يقول الله  يوم القيامة: أين المتحابون بجلالي؟ اليوم أظلهم في ظلي يوم لا ظل إلا ظلي. ويقول -عليه الصلاة والسلام-: سبعة يظلهم الله في ظله يوم لا ظل إلا ظله: إمام عادل، وشاب نشأ في عبادة الله، ورجل قلبه معلق بالمساجد، ورجلان تحابا في الله، اجتمعا على ذلك، وتفرقا عليه، ورجل دعته امرأة ذات منصب، وجمال، فقال إني أخاف الله، ورجل تصدق بصدقة، فأخفاها حتى لا تعلم شماله ما تنفق يمينه، ورجل ذكر الله خاليًا؛ ففاضت عيناه نسأل الله -جل وعلا- أن يجعلنا، وإياكم من هؤلاء السبعة .. أما القلب فهو معروف في الصدر، في الجهة اليسرى، وهو معنى القلب المعرف مضغة، كما قال مضغة، لحمة كالشيء الممضوغ، لها شأن عظيم في الإنسان، عليها مدار صلاحه، وفساده، جعلها الله -جل وعلا- في محور الإنسان، ومدار حياته، وصحته، وسلامته، ومتى صلح القلب من جهة الدين؛ صلح الإنسان من جهة الدين، ومتى فسد من جهة الطبيعة؛ فسد الإنسان أيضًا، وربما انتهى إلى الموت بما يصيب هذا القلب من السكتات التي تسكن الحركات، وينتهي به إلى الموت. فالقلب له شأن عظيم من جهة حياة الإنسان الحسية، وحياته المعنوية الحقيقية، فمتى صلح من جهة الدين؛ فهي الحياة السعيدة، وهي الحياة المعنوية الكاملة، ومتى صح من جهة البدن، ومن جهة عدم الآفات؛ صح البدن أيضًا؛ لأنه تبع له. المقصود: أن القلب هو المعروف الذي نعرفه جميعًا، فينبغي للمؤمن أن يسعى كثيرًا، ويجتهد كثيرًا في صلاحه بطاعة الله، وخشية الله، والإخلاص لله، ومراقبة الله، وتعظيم حرمات الله، والبعد عن محارم الله .","link":"https://binbaz.org.sa/fatwas/2739/مكان-القلب-في-جسم-الانسان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1239.mp3","categories":["اللباس والزينة"]},{"id":6864,"question":"أنا معقب جوازات، وهذا العمل يجيز لي الاطلاع على صور النساء في الجوازات عند القيام بتعقيب الإجراءات النظامية، فهل هذا العمل يؤثر على قلبي؟","title":"العمل في أماكن الفتن وأثره على القلب","answer":"الجواب: لا يضرك -إن شاء الله- إذا كان المقصود هو حفظ الأمن، ومساعدة الدولة في صلاح المجتمع، وحفظ الأمن؛ فلا بأس بذلك، لكن تحذر الميل إلى الشهوات، أو الميل إلى ما يجرك إلى الفساد. وإذا كنت لا تأمن، وتعرف من قلبك أن عليك خطرًا؛ لأنك تشاهد وجوها جميلة، وربما جرك ذلك إلى الفتنة؛ تبتعد عن هذه الوظيفة، وانتقل إلى عمل آخر. فالمؤمن يكون طبيب نفسه، ينظر ما هو الأصلح، فإذا كان التعقيب في الجوازات قد يفضي بك إلى ما يضرك؛ فانتقل عن هذا العمل إلى غيره، وإن كان لا يضرك، ولم تر منه إلا خيرًا، وأنت قصدك الخير، ونفع المسلمين، وحفظ الأمن، ومساعدة الدولة على ما ينفع المسلمين؛ فلا حرج عليك.","link":"https://binbaz.org.sa/fatwas/2741/العمل-في-اماكن-الفتن-واثره-على-القلب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1241.mp3","categories":["اللباس والزينة"]},{"id":6912,"question":"توجد لدي خالة لم أصلها حتى الآن، وأنا أبلغ من العمر عشرين عامًا، والسبب في ذلك سوء الحالة المادية، فهل علي إثم في ذلك؟","title":"المشروع فعل المستطاع في صلة الأرحام","answer":"الجواب: ليس عليك إثم إلا إذا قدرت على الصلة، ولم تفعل، أما ما دمت عاجزًا؛ فلا شيء عليك فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] لكن تصلها بالكتاب الكريم، بالرسالة الطيبة والمكالمة الهاتفية، والزيارة إذا قدرت عليها، أما المال  فحسب القدرة.  لكن الصلة قد تكون بالكلام الطيب أعظم من المال، الكلام الطيب، والزيارة بالقدم، أو من طريق السيارات، أو بالكلام الهاتفي، كل هذا نوع من الصلة، فكلها يحصل بها أجر كبير للمؤمن إذا وصل قرابته بالكلام الطيب، والزيارة الحسنة، لا سيما عند المناسبات، كل هذا من الصلة، أما المال فيحتاجه الفقير.","link":"https://binbaz.org.sa/fatwas/2843/المشروع-فعل-المستطاع-في-صلة-الارحام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1291.mp3","categories":["اللباس والزينة"]},{"id":6913,"question":"كيف نشكر الوالدين؟ وهل الشكر بالقول فقط، أم ماذا؟","title":"كيفية شكر الوالدين","answer":"الجواب: الشكر يكون بالقول، والعمل، شكر الله بالقول، والعمل بتوحيده، والإخلاص له، وطاعة أوامره، وترك نواهيه، هذا شكر الله كما قال تعالى: اعْمَلُوا آلَ دَاوُودَ شُكْرًا [سبأ:13]. وهكذا شكر الوالدين ببرهما، بالإنفاق عليهما إذا احتاجهما، بالسمع والطاعة لهما في المعروف، في زيارتهما إذا كانا ليس عندك بالتلطف لهما، وسؤالهما عن حاجتهما، وعن صحتهما، وحسن الكلام معهما، وخفض الجناح لهما، كل هذا من شكرهما، وتذكر إحسانهما القديم، فأنت تعمل من الأعمال التي ترضيهما، ولا تغضب الله، ما فيه خير لهما، ويسمى هذا شكرًا، والقول الطيب شكر.","link":"https://binbaz.org.sa/fatwas/2844/كيفية-شكر-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1292.mp3","categories":["اللباس والزينة"]},{"id":6961,"question":"قال قائل لي: إن الوجه عورة، أما اليدين فليستا عورة لأنه لا يوجد دليل على ذلك، وأخت تقول: إن لبس الكفوف في اليدين بدعة ولم يأت دليل بذلك، وحجتهم في ذلك أنها لا تسبب فتنة، رجاء توضيح ذلك جزاكم الله خيرًا؟","title":"حكم إظهار المرأة للوجه واليدين","answer":"الجواب: الصواب في هذا الذي عليه المحققون من أهل العلم أن المرأة عورة كلها؛ وجهها وقدمها، ويدها كلها عورة؛ لأن الله قال: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ [الأحزاب:53] فلم يستثن شيئًا، وقال: وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ [النور:31] إلى آخره. فلهذا قرر المحققون من أهل العلم أنها عورة، والواجب سترها حتى لا تفتن، ولا تفتن، وأخبرت عائشة -رضي الله عنها- أنهن كن يكشفن قبل الحجاب، فلما أنزل الله آية الحجاب؛ سترن وجوههن، فدل ذلك على أن آية الحجاب لما نزلت أمر النساء بحفظ الوجوه، وجميع الأبدان، وكانوا قبل ذلك يكشفون الوجه والكفين، قبل نزول آية الحجاب، ثم أمروا بالستر.","link":"https://binbaz.org.sa/fatwas/2901/حكم-اظهار-المراة-للوجه-واليدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1349.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":6983,"question":"قال قائل لي: إن الوجه عورة، أما اليدين فليستا عورة لأنه لا يوجد دليل على ذلك، وأخت تقول: إن لبس الكفوف في اليدين بدعة ولم يأت دليل بذلك، وحجتهم في ذلك أنها لا تسبب فتنة، رجاء توضيح ذلك جزاكم الله خيرًا؟","title":"حكم إظهار المرأة للوجه واليدين","answer":"الجواب: الصواب في هذا الذي عليه المحققون من أهل العلم أن المرأة عورة كلها؛ وجهها وقدمها، ويدها كلها عورة؛ لأن الله قال: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ [الأحزاب:53] فلم يستثن شيئًا، وقال: وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ [النور:31] إلى آخره. فلهذا قرر المحققون من أهل العلم أنها عورة، والواجب سترها حتى لا تفتن، ولا تفتن، وأخبرت عائشة -رضي الله عنها- أنهن كن يكشفن قبل الحجاب، فلما أنزل الله آية الحجاب؛ سترن وجوههن، فدل ذلك على أن آية الحجاب لما نزلت أمر النساء بحفظ الوجوه، وجميع الأبدان، وكانوا قبل ذلك يكشفون الوجه والكفين، قبل نزول آية الحجاب، ثم أمروا بالستر.","link":"https://binbaz.org.sa/fatwas/2901/حكم-اظهار-المراة-للوجه-واليدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1349.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":7004,"question":"ما حكم لبس الذهب المحلق بالنسبة للنساء؟ وهل له حكم، أي نوع من أنواع الذهب، أرجو من فضيلتكم الإجابة على هذا السؤال؛ لأن الأمر ملتبس علي؟","title":"حكم لبس الذهب المحلق بالنسبة للنساء","answer":"الجواب:\n\nلبس المحلق من الذهب لا بأس به، ولا حرج فيه عند أهل العلم جميعًا، حكاه غير واحد، إجماع أهل العلم، كما حكى ذلك الجصاص الحنفي -رحمه الله- وحكى ذلك البيهقي، وحكى ذلك أيضًا الحافظ ابن حجر، وكذلك النووي، وآخرون حكوا إجماع أهل العلم على حله للنساء المحلق، كالخاتم، والقلائد، والأسورة، وقد ذهب بعض إخواننا المتأخرين، ويروى عن بعض السلف على تحريم ذلك.. وهو خطأ قول مرجوح، وغلط.\n\nوالصواب: حل ذلك، وما ورد في هذا مما قد يوهم التحريم، فهي أخبار شاذة مخالفة للأحاديث الصحيحة، وقال جمهور أهل العلم: إنها منسوخة للأحاديث الصحيحة. \n\nفالحاصل: أن المحلق كالأسورة، والخاتم حل للنساء من الذهب، حرام على الرجال، وما جاء ما يظن أنه يخالف ذلك؛ فهو عند أهل العلم شاذ، أو منسوخ بالأحاديث الصحيحة عن رسول الله -عليه الصلاة والسلام- وقد حكاه غير واحد إجماع أهل العلم -كما سمعتم الآن-.","link":"https://binbaz.org.sa/fatwas/2946/حكم-لبس-الذهب-المحلق-بالنسبة-للنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1395.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":7014,"question":"ما حكم لبس الذهب المحلق بالنسبة للنساء؟ وهل له حكم، أي نوع من أنواع الذهب، أرجو من فضيلتكم الإجابة على هذا السؤال؛ لأن الأمر ملتبس علي؟","title":"حكم لبس الذهب المحلق بالنسبة للنساء","answer":"الجواب:\n\nلبس المحلق من الذهب لا بأس به، ولا حرج فيه عند أهل العلم جميعًا، حكاه غير واحد، إجماع أهل العلم، كما حكى ذلك الجصاص الحنفي -رحمه الله- وحكى ذلك البيهقي، وحكى ذلك أيضًا الحافظ ابن حجر، وكذلك النووي، وآخرون حكوا إجماع أهل العلم على حله للنساء المحلق، كالخاتم، والقلائد، والأسورة، وقد ذهب بعض إخواننا المتأخرين، ويروى عن بعض السلف على تحريم ذلك.. وهو خطأ قول مرجوح، وغلط.\n\nوالصواب: حل ذلك، وما ورد في هذا مما قد يوهم التحريم، فهي أخبار شاذة مخالفة للأحاديث الصحيحة، وقال جمهور أهل العلم: إنها منسوخة للأحاديث الصحيحة. \n\nفالحاصل: أن المحلق كالأسورة، والخاتم حل للنساء من الذهب، حرام على الرجال، وما جاء ما يظن أنه يخالف ذلك؛ فهو عند أهل العلم شاذ، أو منسوخ بالأحاديث الصحيحة عن رسول الله -عليه الصلاة والسلام- وقد حكاه غير واحد إجماع أهل العلم -كما سمعتم الآن-.","link":"https://binbaz.org.sa/fatwas/2946/حكم-لبس-الذهب-المحلق-بالنسبة-للنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1395.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":7042,"question":"ما معنى مائلات مميلات في حديث الرسول ﷺ: نساء كاسيات عاريات ...  إلى آخره؟","title":"معنى قول النبي: «نساء كاسيات عاريات مائلات مميلات»","answer":"الجواب:\n\nسمعتم الحديث، يقول النبي ﷺ: صنفان من أهل النار لم أرهما بعد: رجال بأيديهم سياط كأذناب البقر يضربون بها الناس يقال عنهم: إنهم الشرطة وأشباههم من الظالمين، الشرطة الظالمة ونساء كاسيات عاريات مائلات مميلات رؤوسهن كأسنمة البخت المائلة لا يدخلن الجنة ولا يجدن ريحها، وإن ريحها ليوجد من مسيرة كذا وكذا.\n\nالمقصود: أن النساء الكاسيات العاريات أصل كما قاله المشايخ في تفسيرها، وأنهن كاسيات من نعم الله، عاريات من شكرها، هذا أحد التفسيرات لها.\n\nوقال آخرون من أهل العلم: معنى كاسيات، يعني: كاسيات ثياب رقيقة، ما تستر البشرة، عاريات في المعنى.\n\nوقال آخرون في تفسير الحديث: معناه كاسيات بثياب قصيرة، لا تستر، كالتي تلبس الثياب التي إلى الركبة، أو إلى بعض الفخذ، أو إلى بعض الساق، وتكشف الرأس، كل هذه كسوة عارية، فلا تكون الكسوة كافية إلا إذا كانت ساترة للمرأة كلها، فالنساء الكاسيات العاريات هن اللاتي يلبسن لباسًا لا يسترهن، إما لقصره، وإما لرقته، وإما لضيقه -والعياذ بالله- حتى تبدو أحجام عورتها، هذه كاسية بالاسم، عارية في الحقيقة.\n\nوأما مائلات مميلات، فهن المائلات عن العفة، مائلات عن الاستقامة إلى الفواحش والمنكرات، يعني مائلات عن الاستقامة والعفة والصبر على ما أوجب الله، إلى ما حرم الله من الزنا، والفواحش، والتهم، مميلات لغيرهن: مميلات للنساء الأخريات، يدعُنَّ إلى الفساد، ويعلمن النساء الفساد، ويشجعن على الفساد -نسأل الله العافية-.","link":"https://binbaz.org.sa/fatwas/3037/معنى-قول-النبي-نساء-كاسيات-عاريات-ماىلات-مميلات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1437.mp3","categories":["شروح الحديث","قضايا المرأة","اللباس والزينة"]},{"id":7051,"question":"هناك مسلمون يجوزون كشف الوجه والكفين، بدليل حديث رسول الله ﷺ دخلت أسماء على رسول الله ﷺ في ثوب شفاف، فأعرض عنها وقال: إن حاضت المرأة فلا يظهر منها إلا هذا وهذا وأشار بيده على الوجه والكفين، أو كما جاء، نرجو أن توضحوا مدى صحة هذا الحديث، وهل يجوز الأخذ به كدليل على كشف الوجه واليدين، جزاكم الله خيرًا.","title":"الرد على دعوى القائلين بجواز كشف المرأة الوجه والكفين","answer":"الجواب:\n\nهذا السائل ذكرني، كنت عازمًا على التنبيه عليه، ولكن نسيته، فجزاه الله خيرًا هذا السائل، هذا الحديث تعلق به بعض المائلين إلى جواز إظهار المرأة كفيها ووجهها، وهذا الحديث بينه أهل العلم: أنه ليس بصحيح، لا يجوز الاعتماد عليه، وأصله أنه رواه أبو داود، عن سعيد بن بشير، عن قتادة، عن خالد بن دريك، عن عائشة -رضي الله عنها- قالت: دخل النبي ﷺ وعندي أسماء بنت أبي بكر -يعني أختها زوجة الزبير- وعليها ثياب رقاق، فأعرض عنها النبي ﷺ وقال: يا أسماء إن المرأة إذا بلغت المحيض فإنه لا يصلح أن يرى منها إلا هذا وهذا وأشار إلى وجهه وكفيه.\n\nقالوا: فهذا يدل على جواز كشف المرأة وجهها وكفيها؛ لأن في الحديث: أن المرأة إذا بلغت المحيض لا يصلح أن يرى منها إلا هذا وهذا، يعني الكفان والوجه.\n\nوالجواب عن هذا مثلما تقدم: أن الحديث لا يصح عن النبي ﷺ لعلل ثلاث فيه: ثلاث علل عند أهل العلم، مع أنه لو صح؛ لكان قبل الحجاب، لا بعد الحجاب؛ لأن الحجاب نزلت به آية بعد ... كانت المرأة في الجاهلية، وفي أول الإسلام تبدي وجهها، وكفيها، وتجالس الرجال، وتتكلم مع الرجال، إظهار الكفين والوجه كان في أول الإسلام، ثم نسخ هذا، ومنع الله ذلك، وهذا الحديث لو صح؛ لكان هذا قبل الحجاب، لكنه غير صحيح، بل هو ضعيف لعلل ثلاثة عند أهل العلم:\n\nالعلة الأولى: أن الراوي سعيد بن بشير ضعيف عند أهل العلم، لا يحتج بروايته؛ لسوء حفظه، وعدم ضبطه.\n\nالعلة الثانية: أن قتادة مدلس، وقد عنعن، ولم يصرح بسماعه من خالد بن دريك.\n\nوالعلة الثالثة: أن خالد الراوي، عن عائشة لم يدرك عائشة، بل هو منقطع، لم يدركها، ولم يسمع منها؛ فصار الحديث ضعيفًا من هذه العلل الثلاث، ولا يستقيم الاحتجاج به، ولا يصح الاحتجاج به في هذا المقام العظيم، ولو صح؛ لكان هذا قبل الحجاب، لا بعد الحجاب، والله المستعان نعم.\n\nوقد بينا هذا في كتاب الحجاب التي توزع، كتبنا في هذا رسالة في الحجاب من مدة طويلة، فهي توزع بين الناس، وتوزع من طريق ... أيضًا، وهي رسالة بحمد الله موجزة، لكنها مفيدة.\n\nوهكذا رسالة شيخ الإسلام ابن تيمية في الحجاب مفيدة، وكذلك رسالة لأخينا وابننا العلامة الشيخ محمد بن عثيمين في الحجاب جيدة، وهكذا رسالة العلامة المودودي في الحجاب جيدة.\n\nوقد ورد في كتاب الحجاب لأخينا العلامة الشيخ محمد ناصر الألباني شيء يدل على ميله إلى جواز كشف المرأة وجهها وكفيها، وإن كان يرى أن الستر أولى وأحوط، لكنه غلط -وفقه الله- في هذا،  وكما يقال زلةُ العالمِ زلةُ العالَم، زلة العالِم مصيبة، فهذه زلة من أخينا الشيخ ناصر الدين الألباني وهو من خيرة العلماء، ومن خيرة الأخيار، نعرفه كثيرًا، ولكنه له زلات كغيره، كل واحد من العلماء له أخطاء، وله غلطات، هذه من غلطاته -عافاه الله وهداه-.\n\nوله من الغلطات أيضًا قوله في صفة الصلاة: إن اليدين بعد الركوع يسدلها المصلي، ولا يرفعها، هذه غلطة أيضًا، والسنة في المصلي أنه يرفع يديه، ويجعلهما على صدره في القيام قبل الركوع وبعده، هذه السنة، ولكنه غلط، وظن أنها بدعة بعد الركوع، وهي غلطة قبيحة -عافاه الله وهداه-.","link":"https://binbaz.org.sa/fatwas/3027/الرد-على-دعوى-القاىلين-بجواز-كشف-المراة-الوجه-والكفين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1432.mp3","categories":["قضايا المرأة","قضايا المرأة","ردود وتعقيبات","اللباس والزينة"]},{"id":7067,"question":"ما معنى مائلات مميلات في حديث الرسول ﷺ: نساء كاسيات عاريات ...  إلى آخره؟","title":"معنى قول النبي: «نساء كاسيات عاريات مائلات مميلات»","answer":"الجواب:\n\nسمعتم الحديث، يقول النبي ﷺ: صنفان من أهل النار لم أرهما بعد: رجال بأيديهم سياط كأذناب البقر يضربون بها الناس يقال عنهم: إنهم الشرطة وأشباههم من الظالمين، الشرطة الظالمة ونساء كاسيات عاريات مائلات مميلات رؤوسهن كأسنمة البخت المائلة لا يدخلن الجنة ولا يجدن ريحها، وإن ريحها ليوجد من مسيرة كذا وكذا.\n\nالمقصود: أن النساء الكاسيات العاريات أصل كما قاله المشايخ في تفسيرها، وأنهن كاسيات من نعم الله، عاريات من شكرها، هذا أحد التفسيرات لها.\n\nوقال آخرون من أهل العلم: معنى كاسيات، يعني: كاسيات ثياب رقيقة، ما تستر البشرة، عاريات في المعنى.\n\nوقال آخرون في تفسير الحديث: معناه كاسيات بثياب قصيرة، لا تستر، كالتي تلبس الثياب التي إلى الركبة، أو إلى بعض الفخذ، أو إلى بعض الساق، وتكشف الرأس، كل هذه كسوة عارية، فلا تكون الكسوة كافية إلا إذا كانت ساترة للمرأة كلها، فالنساء الكاسيات العاريات هن اللاتي يلبسن لباسًا لا يسترهن، إما لقصره، وإما لرقته، وإما لضيقه -والعياذ بالله- حتى تبدو أحجام عورتها، هذه كاسية بالاسم، عارية في الحقيقة.\n\nوأما مائلات مميلات، فهن المائلات عن العفة، مائلات عن الاستقامة إلى الفواحش والمنكرات، يعني مائلات عن الاستقامة والعفة والصبر على ما أوجب الله، إلى ما حرم الله من الزنا، والفواحش، والتهم، مميلات لغيرهن: مميلات للنساء الأخريات، يدعُنَّ إلى الفساد، ويعلمن النساء الفساد، ويشجعن على الفساد -نسأل الله العافية-.","link":"https://binbaz.org.sa/fatwas/3037/معنى-قول-النبي-نساء-كاسيات-عاريات-ماىلات-مميلات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1437.mp3","categories":["شروح الحديث","قضايا المرأة","اللباس والزينة"]},{"id":7072,"question":"ما معنى مائلات مميلات في حديث الرسول ﷺ: نساء كاسيات عاريات ...  إلى آخره؟","title":"معنى قول النبي: «نساء كاسيات عاريات مائلات مميلات»","answer":"الجواب:\n\nسمعتم الحديث، يقول النبي ﷺ: صنفان من أهل النار لم أرهما بعد: رجال بأيديهم سياط كأذناب البقر يضربون بها الناس يقال عنهم: إنهم الشرطة وأشباههم من الظالمين، الشرطة الظالمة ونساء كاسيات عاريات مائلات مميلات رؤوسهن كأسنمة البخت المائلة لا يدخلن الجنة ولا يجدن ريحها، وإن ريحها ليوجد من مسيرة كذا وكذا.\n\nالمقصود: أن النساء الكاسيات العاريات أصل كما قاله المشايخ في تفسيرها، وأنهن كاسيات من نعم الله، عاريات من شكرها، هذا أحد التفسيرات لها.\n\nوقال آخرون من أهل العلم: معنى كاسيات، يعني: كاسيات ثياب رقيقة، ما تستر البشرة، عاريات في المعنى.\n\nوقال آخرون في تفسير الحديث: معناه كاسيات بثياب قصيرة، لا تستر، كالتي تلبس الثياب التي إلى الركبة، أو إلى بعض الفخذ، أو إلى بعض الساق، وتكشف الرأس، كل هذه كسوة عارية، فلا تكون الكسوة كافية إلا إذا كانت ساترة للمرأة كلها، فالنساء الكاسيات العاريات هن اللاتي يلبسن لباسًا لا يسترهن، إما لقصره، وإما لرقته، وإما لضيقه -والعياذ بالله- حتى تبدو أحجام عورتها، هذه كاسية بالاسم، عارية في الحقيقة.\n\nوأما مائلات مميلات، فهن المائلات عن العفة، مائلات عن الاستقامة إلى الفواحش والمنكرات، يعني مائلات عن الاستقامة والعفة والصبر على ما أوجب الله، إلى ما حرم الله من الزنا، والفواحش، والتهم، مميلات لغيرهن: مميلات للنساء الأخريات، يدعُنَّ إلى الفساد، ويعلمن النساء الفساد، ويشجعن على الفساد -نسأل الله العافية-.","link":"https://binbaz.org.sa/fatwas/3037/معنى-قول-النبي-نساء-كاسيات-عاريات-ماىلات-مميلات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1437.mp3","categories":["شروح الحديث","قضايا المرأة","اللباس والزينة"]},{"id":7086,"question":"يقول أحدهم: ساهمت مع أحد المكاتب العقارية في أرض، وصفيت هذه المساهمة، وحققت ربحًا معينًا، ولكن صاحب المكتب ليس لديه ما يدفع للمساهمين حقهم؛ لأن كبار المساهمين لم يدفعوا له، وهم يقبلون الإحالة عليهم على أن يتنازل لهم المساهم عن جزء من ربحه، بعضهم يقول: إن هذا جائز؛ انطلاقًا من قاعدة: ضع وتعجل،  هل يجوز قبول الإحالة على هذا الوضع، أم لا يجوز؟","title":"حكم قبول الحوالة بشرط الوضع","answer":"الجواب:\n\nأما قبولها بشرط أن يضع لا يجوز، أما إذا قبل الإحالة، وحاول أن يعطوه فلم يعطوه، وتسامح لهم بعض الشيء؛ لا بأس أن يتسامح حتى يعطوه.\n\nأما بشرط أنه يتنازل، أو قال: لا أعطيك حتى تتنازل، لا يجوز، لكن إذا هو نفسه قال: أنا أسمح بشيء من هذا الشيء وتعطيني؛ لا بأس، أما حوالة بهذا الشرط ما يجوز، حوالة بأن يتنازل ما يجوز، نعم.","link":"https://binbaz.org.sa/fatwas/3100/حكم-قبول-الحوالة-بشرط-الوضع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1477.mp3","categories":["اللباس والزينة"]},{"id":7115,"question":"ما هي الميزة التي تتميز بها الأشهر الحرم؟ وما الأشياء التي يحل، أو يحرم فعلها فيها؟","title":"ميزة الأشهر الحرم والتحليل والتحريم فيها","answer":"الجواب:\n\nالأشهر الحرم كما سمعتم هي: ذو القعدة وذو الحجة والمحرم عاشوراء، وهي كلها متوالية الثلاثة، والرابع: رجب مضر الذي بين جمادى وشعبان، يقال له: رجب، هذه أربعة حرم، وقد نص الله في كتابه العظيم على تحريم ظلم النفس فيها فَلَا تَظْلِمُوا فِيهِنَّ أَنْفُسَكُمْ [التوبة: 36] هكذا قال جماعة.\n\nوقال آخرون من المفسرين: إن هذا يرجع إلى الشهور كلها الاثني عشر، وإن الله يحذر عباده من ظلم أنفسهم في جميع الشهور، لا في الأشهر الحرم وحدها، بل في جميع الشهور، يجب على المؤمن أن يحذر ظلم نفسه بالمعاصي والسيئات والكفر بالله  وأن يصونها من ذلك هذه الأشهر، وأن يحسن فيها الخير والعمل الصالح الذي أعظمه وأكبره توحيد الله، والإخلاص له، ولا ريب أن المعنى مراد في الأشهر كلها، ولكن في الأشهر حرم مزية وزيادة وتأكيد في هذا المقام. \n\nواختلف العلماء، هل بقي تحريم القتال فيها أم لا؟\n\nفالجمهور على أنه نسخ، وذهب آخرون من أهل العلم إلى أنه لم ينسخ، وأن تحريم القتال باق فيها، وإليه يميل العلامة ابن القيم -رحمه الله- وجماعة، وعلى كل حال فهذا يدل على أن لها بقية مزية لم تنسخ، وأن أمرها العظيم في وجود المعاصي فيها، وأن المعاصي فيها أكثر إثمًا من غيرها.","link":"https://binbaz.org.sa/fatwas/3144/ميزة-الاشهر-الحرم-والتحليل-والتحريم-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1502.mp3","categories":["اللباس والزينة"]},{"id":7124,"question":"ما حكم لبس البرقع؟ وما حكم نظر المرأة إلى الرجل؟ وهل صوت المرأة عورة؟","title":"حكم لبس البرقع","answer":"الجواب:\n\nالبرقع لا بأس به إذا ستر الوجه، ولم يبق إلا العين، أو العينان فقط للحاجة إلى النظر، لا بأس، ولكن الخمار الكامل يكون أولى وأفضل وأبعد عن الريبة.","link":"https://binbaz.org.sa/fatwas/3169/حكم-لبس-البرقع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1527.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":7139,"question":"نرجو منكم إدراج شبهة الغرب في الحجاب، وهي أن المرأة إذا احتجبت؛ كان ذلك أدعى إلى ملاحقة الشباب لهن وزيادة الرغبة فيهن، وإذا لم يكن هناك حجاب أصبح ذلك شيئًا طبيعيًّا، وكل من الشباب والفتيات يحرص على أن يعجب به صاحبه، وتقل الرغبة الجنسية لدى كل منهما، ولكن حصل العكس بكثرة الجرائم، فما رأي سماحتكم؟","title":"رد شبهة الغرب في الحجاب","answer":"الجواب:\n\nهذه شبهة داحضة لا وجه لها، هذه شبهة داحضة إذا وجب عليها الحجاب بين المسلمين؛ فوجوبه بين الكفار من باب أولى؛ لأن الكافر أخبث، وأكثر شرًا، وأقبح في الفساد.\n\nفإذا وجب عليها التحجب عن المسلم الذي يمنعه دينه من الفساد إلا من ضعف عن ذلك، وضعف إيمانه، فكونها تتحجب بين الكفرة أولى وأولى، وإذا عرف الكافر أنها ليست ممن يطمع فيه؛ لم يتعرض لها.\n\nثم هي ليس لها أن تخرج في بلاد الكفرة إلا ومعها محرمها، ومعها من يحميها من الفتنة، ليس لها أن تخرج هكذا وحدها حتى في بلاد المسلمين، إذا كانت في محل فيه خطر؛ لا تخرج وحدها، فكيف ببلاد الكفرة! يكون معها أولياؤها، معها محارمها، معها أصحابها حتى لا تتعرض للفتنة، أما كشفها هناك فهو محرم كما يحرم بين المسلمين، بل أكثر، بل أشد!","link":"https://binbaz.org.sa/fatwas/3172/رد-شبهة-الغرب-في-الحجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1530.mp3","categories":["قضايا المرأة","ردود وتعقيبات","اللباس والزينة"]},{"id":7144,"question":"كشف المرأة عند ضابط الكنتر في الجوازات؟","title":"حكم كشف المرأة وجهها عند ضابط أمن المطار","answer":"الجواب:\n\nهذا إذا كان فيه ضرورة للسفر، قد يعفى عنها، وإذا كان ما هو بضرورة، لا تكشف، وترجع، لا تسافر. \n\nأما إذا كان ضرورة للسفر، ولم يحضر لها سفر إلا بأن تؤخذ صورتها، لا يعلم مانعًا عند ضرورة السفر إلى ذلك، أما إذا كان السفر غير ضروري؛ فلا تسافر، ولا تكشف.","link":"https://binbaz.org.sa/fatwas/3174/حكم-كشف-المراة-وجهها-عند-ضابط-امن-المطار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1532.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":7155,"question":"كشف المرأة عند ضابط الكنتر في الجوازات؟","title":"حكم كشف المرأة وجهها عند ضابط أمن المطار","answer":"الجواب:\n\nهذا إذا كان فيه ضرورة للسفر، قد يعفى عنها، وإذا كان ما هو بضرورة، لا تكشف، وترجع، لا تسافر. \n\nأما إذا كان ضرورة للسفر، ولم يحضر لها سفر إلا بأن تؤخذ صورتها، لا يعلم مانعًا عند ضرورة السفر إلى ذلك، أما إذا كان السفر غير ضروري؛ فلا تسافر، ولا تكشف.","link":"https://binbaz.org.sa/fatwas/3174/حكم-كشف-المراة-وجهها-عند-ضابط-امن-المطار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1532.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":7159,"question":"ما الحكمة في أن المرأة تكشف وجهها وكفيها أثناء أداء مناسك الحج؟","title":"حكم كشف المرأة وجهها وكفيها أثناء الحج","answer":"الجواب:\n\nليس لها ذلك، بل عليها أن تستر وجهها وكفيها حتى في الحج، هي لا تنتقب النقاب المعروف -البرقع الذي يعرفه البادية- ولكن تغطي وجهها بغير ذلك، الرسول ﷺ نهى عن البرقع، ولم ينهها عن تغطية وجهها، بل نهاها عن البرقع، وعن القفازين في الحج.\n\nفالمعنى: أن تستر وجهها بغير ذلك، كالخمار والجلباب، كما قالت عائشة -رضي الله عنها-: كان إذا دنا منهن الرجال؛ سدلت إحدانا خمارها على وجهها، أو قالت: جلبابها على وجهها، وإذا بعدوا كشفنا، وهكذا القفازان، وهما دسان يجعلان على اليدين، غشاء لليدين لا تلبسهما المحرمة، ولكن تغطي يديها بجلبابها، بعباءتها بغير ذلك، كالرجل لا يلبس القميص، ويغطي بدنه بالإزار، وبالرداء، ونحوه، والحمد لله، فالشيء المحرم لا يفعل.\n\nفالرجل لا يلبس القميص ولا يغطي رأسه بالإحرام، ولكن يغطي بدنه بالإزار، ويغطي بدنه بالرداء، ويغطي يديه بالرداء لا بأس، والمرأة كذلك تلبس القميص، وتغطي رأسها، لكن لا تغطي وجهها بالنقاب، ولا تغطي يديها بالقفازين، ولكن تغطي وجهها بالجلباب، بالخمار عند وجود الرجال، وتغطي يديها بخمارها، أو بعباءتها، أو بجلبابها، هذا فرق بين الأمرين.\n\nالسؤال: هذا البرقع يا شيخ، جزاك الله خيرًا؟\n\nالجواب: البرقع هو النقاب، لا يجوز لبسه للمحرمة.\n\nالسؤال: هذا البرقع واسع...؟\n\nالجواب: لا تلبسه المحرمة مطلقًا، المحرمة لا تلبس البرقع، ولكن تغطي وجهها بغير ذلك، أما غير المحرمة إذا لبسته للحاجة؛ فإنه يكون بقدر العينين فقط، أو إحدى العينين فقط، من دون زيادة.","link":"https://binbaz.org.sa/fatwas/3175/حكم-كشف-المراة-وجهها-وكفيها-اثناء-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1533.mp3","categories":["مسائل متفرقة في الحج والعمرة","اللباس والزينة","قضايا المرأة"]},{"id":7160,"question":"جاء في حديث لشيخ الأزهر بإحدى الصحف المصرية كلام معناه: أن الوجه ليس بعورة حسب رأي جمهور علماء المسلمين، فهل هذا صحيح أن رأي جمهور علماء المسلمين يقضي بكشف الوجه؟ ثم هل إذا قضى المسؤول عند السفر في المطار بكشف وجه المرأة المسافرة بدعوى التأكد من شخصيتها، هل يطاع في ذلك، أفتونا بارك الله فيكم؟","title":"الرد على ادعاء أن كشف المرأة وجهها هو قول الجمهور","answer":"الجواب:\n\nقوله قول الجمهور هذا محل نظر، محل عناية، كثيرًا ما يدعى أنه قول الجمهور يكون محل نظر، وكثير من الناس يدعي أن هذا الشيء قول الجمهور، وليس الأمر كذلك، وليس شيخ الأزهر وحده من قال بهذا، بل قال به غيره كثير من الناس من أهل العلم، وغلطوا في هذا. \n\nفلا ينبغي لعاقل أن يغتر بقول فلان، أو فلان كما سمعت، وإنما مسائل الخلاف تعرض على ما قاله الله ورسوله، وعلى الأدلة الشرعية، وقد سمعتم ما دلت عليه الأدلة الشرعية من وجوب الحجاب، ووجوب ستر المرأة بدنها، وبعدها عن أسباب الفتنة، وأنه أطهر لقلوب الرجال، وقلوب النساء. \n\nفما نقل عن شيخ الأزهر، وعن غيره، وما كتبه أخونا العلامة محمد ناصر الدين الألباني في كتابه الحجاب، وما كتبه غيره مثلما كتب الناس الآخرون يعرض على الكتاب والسنة، وقد عرضنا ذلك على الكتاب والسنة؛ فوجدنا أن من قال بكشف الحجاب قد غلط، ومن قال بالحجاب قد أصاب.\n\nوإذا كان الذي قال بكشف الحجاب، وجواز السفور قد أخلص لله، وقصد الحق، ولكن حمله اجتهاده على ذلك من دون تقصير ولا هوى؛ فله أجر الاجتهاد، والله يغفر له، ويفوته أجر الصواب، ومن قصد الهوى والشر؛ لم يحصل له لا هذا ولا هذا، بل يأثم بذلك، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/3173/الرد-على-ادعاء-ان-كشف-المراة-وجهها-هو-قول-الجمهور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1531.mp3","categories":["قضايا المرأة","ردود وتعقيبات","اللباس والزينة"]},{"id":7166,"question":"ما حكم قص جزء من شعر المرأة، نرجو توضيح ذلك حيث كثرت هذه الظاهرة عند نساء المسلمين؟","title":"حكم قص شعر المرأة للزينة","answer":"الجواب:\n\nبقاؤه أولى؛ لأنه جمال لها، وزينة لها، والقص لا نعلم فيه شيئًا إذا كان عن رضا زوجها، إن كان لها زوج، واتفقت هي وإياه على ذلك، أو هي غير ذات زوج وقصت من شعرها؛ للتخفيف، لكثرته، لا للتشبه بالكافرات، ولا للتشبه بالرجال، بل للتخفيف فقط،  فهذا لا بأس به فيما نعلم، ولم يرد فيه ما يمنع.\n\nإنما جاء النهي عن الحلق، المرأة منهية عن حلق رأسها، فأما القص؛ فلا نعلم فيه شيئًا، وقد قص أزواج النبي ﷺ من رؤوسهن لما توفي -عليه الصلاة والسلام- للتخفيف؛ لأنه يتعب إذا كثر، فالتخفيف لا نعلم فيه بأسًا، وإن تركته جمالًا، ولاسيما الشابات فهو أولى وأسلم.","link":"https://binbaz.org.sa/fatwas/3203/حكم-قص-شعر-المراة-للزينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1553.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":7185,"question":"أنا أعمل في الرياض، وزوجتي وأولادي ساكنين مع والدي ووالدتي في منطقة جيزان، وأنا أريد أن أحضر زوجتي وأولادي، لكن والدي ووالدتي يرفضون ذلك، ولا يرغبون فيه، وأنا لا أدري ماذا أفعل؟ أخاف أن تزعل والدتي إذا فعلت وأخذت زوجتي وأولادي إلى الرياض، أرجو أن ترشدونا للعمل الصالح دون غضب الله؟الشيخ: أعد؟الطالب: أنا أعمل في الرياض، وزوجتي وأولادي ساكنين مع والدي ووالدتي بجيزان، وأريد أن أحضر زوجتي وأولادي إلى الرياض، لكن والدي ووالدتي ترفض ذلك، وأنا لا أريد أن أتسبب في غضبهم، فماذا أفعل؟","title":"حكم طاعة الوالدين في إبقاء الزوجة والأولاد عندهم","answer":"الجواب:\n\nعليك أن تجتهد في رضاهما لعلهما يرضيان بنقل زوجتك؛ لأنك في حاجة إلى زوجتك، عليك أن تجتهد لعلهما يرضيان، وسّط الناس الطيبين، إذا كانت الوالدة تستطيع أن تخدم والدك، وتقوم بحاجة والدك، أما إذا كانت لا تستطيع ووالدك محتاج إلى الزوجة، وأمك كذلك؛ فابقها عندهم، واصبر وتحمل.\n\nوإذا كنت تستطيع زوجة ثانية تزوج، تزوج زوجة ثانية، حطها في الرياض عندك، ودع أم العيال عند أبويك إذا كان حاجتهما إلى ذلك، أو لكونهما لا يرضيان، فاجمع بين المصلحتين: أرض والديك، واجعل الزوجة تخدمهما، وتزوج إذا استطعت، ولو بالدين، وسوف يوفي الله عنك، تزوج من تيسر من الطيبات الصالحات في الرياض؛ تقوم بحالك، وإذا سافرت إلى هناك، ورجعت إلى أم أولادك، ولا حرج في ذلك، والحمد لله.\n\nولا تغضب والديك، ولا تشق عليهما، ولاسيما إذا كانا في حاجة إلى زوجتك، تخدمهما لكبر سنهما، أما إذا كانا في غير حاجة؛ فوسط من يتوسط بينك وبينهما إن لم يتيسر لك الزواج ... وإن تيسر الزواج؛ فالحمد لله، تزوج ولك أربع، تزوج والحمد لله، وأم الأولاد تبقى عندهم.","link":"https://binbaz.org.sa/fatwas/3228/حكم-طاعة-الوالدين-في-ابقاء-الزوجة-والاولاد-عندهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1572.mp3","categories":["اللباس والزينة"]},{"id":7195,"question":"ادَّعى أب أنه إذا نادى ابنه وهو يصلي السنة؛ فعلى الابن أن يترك الصلاة، ويجيب الأب؛ محتجًا بأن إجابة الأب واجبة وفرض، والفرض مقدم على السنة، فما الحكم جزيتم خيرًا؟","title":"تقديم طاعة الوالدين على صلاة النافلة","answer":"الجواب:\n\nنعم هذا هو الأصل، الواجب أنه يقدم طاعة والده على النافلة، وهذه قصة جريج الذي سمعتم؛ فإن جريج كان يصلي نافلة، وقدم صلاته على أمه؛ فعوقب بسبب دعائها عليه.\n\nلكن إذا سمح الوالد له حتى يصلي؛ يكون أفضل؛ حتى لا يقطع عليه صلاته، إذا دعاه وسمح له، وعرف أنه يصلي؛ فالأولى أن يقول له: كمل، حتى يسمح له، حتى لا يقطع صلاته، فإن لم يسمح؛ يقطعها إذا كانت نافلة.","link":"https://binbaz.org.sa/fatwas/3276/تقديم-طاعة-الوالدين-على-صلاة-النافلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1601.mp3","categories":["اللباس والزينة"]},{"id":7204,"question":"تشغله رعاية أمه، والعناية بها عن الخروج مع إخوانه الصالحين؛ خصوصًا يوم هذه الندوة لحضورها، وسماعها، ويفوت عليه خير كثير غير هذا، فما رأي سماحتكم؟","title":"انشغال الابن برعاية أمه عن طلب العلم","answer":"الجواب:\n\nطلب العلم واجب إذا كان الإنسان محتاجًا، طلب العلم واجب، فإذا أبى والداه؛ لا بأس أن يعصيهما في ذلك لطلب العلم الواجب؛ لأن العلم العبد في ضرورة إليه، لكن يكون بالأسلوب الحسن، يكون بالكلام الطيب، يطلب منها الرضا والسماح، ويقول: أنا محتاج إلى طلب العلم، فيخرج في طلب العلم مثل حضور الندوة هذه، مثل حضور حلقات العلم، لكن بالأسلوب الحسن بالطريقة الحسنة. \n\nوإذا كانا في حاجة إليه، وأمكنه أن يستنيب تلك الساعة التي يخرج فيها من ينوب عنه في إحضار حاجات لهما، فهذا هو الذي ينبغي، يلزمه أن يفعل ما يستطيع من برهما، مع الحرص على طلب العلم، وهكذا لو منعاه أنه يصلي في الجماعة؛ عليه أن يصلي في الجماعة، ولا يطعهما في ذلك.\n\nوهكذا لو منعاه من أداء الواجب الذي عليه من زكاة، أو من صيام رمضان، لا طاعة لمخلوق في معصية الخالق، إنما الطاعة في المعروف، كما قاله النبي -عليه الصلاة والسلام- لكن يكون بالأسلوب الحسن، لا يكون بالعنف والشدة، يبين لهما، ويسترضيهما، ويتكلم معهما بالكلام الطيب؛ لعل الله أن يهديهما؛ حتى لا يكون هناك بينهما شيء.","link":"https://binbaz.org.sa/fatwas/3278/انشغال-الابن-برعاية-امه-عن-طلب-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1603.mp3","categories":["اللباس والزينة"]},{"id":7207,"question":"بيني وبين أخي خصام حول إحضار القينات المغنيات في زواج لنا، وحجته أن هذا من باب إعلان الزواج، مع العلم أنه بعيد عن السنة، وتعلمون سماحتكم ما يرافق هذه القينات من الغناء الفاحش والاختلاط والتصوير وغيره، نرجو بيان وجه الحق والفصل بيننا، وجزاكم الله خير الجزاء؟","title":"حكم إحضار المغنيات بحجة إعلان النكاح","answer":"الجواب:\n\nالمشروع في الزواج إعلانه وإظهاره، وأن يكون فيه إعلان يجتمع النساء مع النساء والرجال مع الرجال؛ لأن الرسول ﷺ أمر بإعلان النكاح، وكان يفعل في عهد النبي ﷺ يجتمع النساء إلى أهل العروس، ويزفونها إلى زوجها، ويكون بينهم بعض الأغاني العادية، الوطنية، في مدح الزوج، ومدح أهل الزوج، أو مدح الزوجة، وأهلها، وما أشبه ذلك.\n\n\n\t\n\t\t\n\t\t\tأتيناكم أتيناكم \n\t\t\t فحينونا نحييكم\n\t\t\n\t\n\n\nإلى غير ذلك، هذا شيء لا بأس، أما الأغاني المنكرة التي فيها مدح الخمور، أو الدعوة إلى عشق النساء، أو عشق الرجال، أو رفع هذا بمكبرات الصوت، هذا كله منكر، أما الغناء العادي بين النساء وحدهن من دون اختلاط في محلهن، من دون مكبرات ولا اختلاط بين النساء، الغناء العادي لا بأس، هو من إعلان النكاح كما كان في عهد النبي ﷺ كما كان أزواج النبي يحضرنه -عليه الصلاة والسلام-.\n\nالسؤال: والرجال؟\n\nالجواب: وأما الرجال فلا، الرجال لا يجوز لهم أن يختلطوا مع النساء، أما لو كانوا وحدهم في السلاح، بالرمي، بالأشعار العربية التي ما فيها شر، ولا فيها طبول، ولا شيء؛ لا بأس، يكونون وحدهم بعيدين عن النساء كما يفعل بعض الناس، يرمون وقت الزواج لإعلان النكاح بالرمي، ويجتمعون على قصائد جيدة، فيها حماس، والدعوة إلى مكارم الأخلاق، ومحاسن الأعمال، والشجاعة، ويتعلمون الرمي بحمل السلاح، ما نعلم في هذا بأسًا. \n\nفقد فعل هذا الحبشة في مسجد النبي ﷺ كانوا يلعبون بالحراب في المسجد، والنبي ينظر إليهم، فهذا لا بأس به، كما أقره النبي ﷺ، إذا كان من هذا الطريق مما يتعلق بالحماس في تعلم الشؤون الحربية وكيف يحذف الرمح؟ وكيف يحمل الحربة؟ وكيف يرمي بالبندق؟ وكيف يحمل السيف؟ إلى غير ذلك، هذا شيء ينفع الجميع، أما مع اختلاط النساء فلا يجوز، أو مع الطبول كذلك، أو مع أغاني منكرة تتعلق بالنساء، أو شؤون النساء، أو جمال النساء، أو دعوة إلى فسوق وعصيان، أو خمور، أو أشياء هذا ينكر، يمنع.","link":"https://binbaz.org.sa/fatwas/3272/حكم-احضار-المغنيات-بحجة-اعلان-النكاح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1598.mp3","categories":["اللباس والزينة","الزفاف ووليمة العرس","الشعر والأغاني"]},{"id":7216,"question":"هل يجوز صنع حذاء من جلد النمر؟ نرجو الإفادة عن ذلك.","title":"حكم صنع حذاء من جلد النمر","answer":"الجواب: \n\nالرسول ﷺ نهى عن افتراش جلود النمور، هذه سباع، النمور سباع، والأسود سباع، ولا ينبغي استعمال شيء من جلودها، لا النمر، ولا الأسد، ولا الفهد، ولا الذئب، ولا الثعلب.\n\nينبغي تركها، وأن تتخذ من جلد الأنعام: من الإبل، والبقر، والغنم، هذه التي إذا دبغ جلدها -ولو كانت ميتة- لا بأس، وأما جلود النمور وأشباهها من السباع فلا ينبغي استعمالها، لا نعلًا، ولا غيرها.","link":"https://binbaz.org.sa/fatwas/3251/حكم-صنع-حذاء-من-جلد-النمر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1584.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":7226,"question":"إذا سافر إنسان ما لطلب العلم، ومدة سفره طويلة كأربع، أو خمس سنين، أو أكثر، وأبواه يطالبانه بالزيارة، وهو لا يستطيع ذلك، وعليه مشقة أن يسافر كل سنة ليلبي طلبهما، فماذا يفعل؟","title":"زيارة الوالدين لمن كان سفره طويلاً في طلب العلم","answer":"الجواب:\n\nيقول الله  في كتابه العظيم: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، ويقول سبحانه: لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286] فعليك أن تخاطبهما بالتي هي أحسن من طريق الهاتف، من طريق التلفون، والمكاتبة بالرسائل، ويكفي هذا، تستسمحهما وتقول: لا أستطيع حتى أكمل، ويكفي الهاتف، وإذا قدرت عليه، أو الرسالة الخطية، أو البرقية؛ يكفي هذا والحمد لله، وليس عليك حرج فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. \n\nلكن ما ينبغي لك أن تذهب، تسافر إلى الخارج، إلى بلاد الكفرة مهما استطعت أن تتعلم في بلادك -في بلاد إسلامية- لأن السفر إلى بلاد الكفرة فيه خطر عظيم، لا من جهة العقيدة ولا من جهة الأخلاق، فلا ينبغي للمؤمن أن يسافر إلى الخارج للدراسة، ولا غيرها إلا عند الضرورة، بل يجتهد في أن يدرس في بلاده إذا تيسر له ذلك، ويستغني بذلك عن السفر إلى بلاد الكفرة.","link":"https://binbaz.org.sa/fatwas/3282/زيارة-الوالدين-لمن-كان-سفره-طويلا-في-طلب-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1607.mp3","categories":["اللباس والزينة"]},{"id":7231,"question":"علمنا بفتواكم أن الفخذ عورة؛ فلبسنا السروال الطويل الساتر للفخذ، وجاءت بعض الجرائد والمجلات والجهات الأخرى تدعونا إلى لبس السروال القصير؛ لأنه من الحضارة والمدنية، نرجو الرد على الصحف التي حاربت السروال الطويل، وأنه رجعية؟","title":"حكم لبس السراويل القصيرة","answer":"الجواب:\n\nإن شاء الله، لا شك أن الفخذ عورة والواجب ستره، وقد بلغنا عن كثير من الناس أنهم يلبسون سراويل قصيرة، وثيابًا رقيقة، وهذا خطر عظيم فيما يتعلق بالصلاة، وخطر على ظهور العورات.\n\nفالواجب الحذر من هذا، أن تكون السراويل طويلة على الأقل إلى الركبة؛ حتى تستر الفخذ، وإذا كانت قصيرة؛ وجب أن يكون الثوب الذي فوقها، القميص الذي فوقها صفيقًا يستر العورة، نسأل الله للجميع الهداية.","link":"https://binbaz.org.sa/fatwas/3295/حكم-لبس-السراويل-القصيرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1620.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":7237,"question":"ما رأيكم فيمن يربي شعره وهو يلبس غترة، وأحيانًا لا يلبس، ولكن لا يريد تقليد الكفار، كما نعلم أن هناك بعض الصحابة -رضي الله عنهم وأرضاهم- كان بعضهم يربي الرأس ويطوله؟","title":"حكم تربية شعر الرأس","answer":"الجواب:\n\nلا حرج في تربية الرأس، النبي ربى رأسه -عليه الصلاة والسلام- كان رأسه يضرب بعض الأحيان إلى منكبه -عليه الصلاة والسلام- المقصود أن التربية للرأس لا بأس، ولا حرج في ذلك، لكن بشرط ألا يكون قصده من ذلك التعرض للنساء والفواحش، أما إذا كان يتعرض بذلك للنساء، والفتن؛ فيمنع.\n\nولهذا لما بلغ عمر قصة نصر بن الحجاج وما يتعرض له من إغراء النساء؛ أمر بجلده، وحلق رأسه، جلده عن الخمر، وحلق رأسه الذي رباه للفتنة. \n\nفالحاصل: إذا كانت التربية للتأسي بالصحابة، والتأسي بالنبي ﷺ ولا يتعرض للفتن مع النساء، والمغازلات للنساء؛ فلا بأس، ولا حرج، أما إذا كان يظهر من حاله قصده الفتنة، ومغازلة النساء، والتعرض للنساء؛ فهذا يمنع، ويحلق رأسه، يكون عقوبة.","link":"https://binbaz.org.sa/fatwas/3292/حكم-تربية-شعر-الراس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1617.mp3","categories":["الآداب والأخلاق","اللباس والزينة"]},{"id":7244,"question":"لي والدة بحضرموت، ولي مدة طويلة من خدمتها، وأنا هنا جئت لاكتساب الرزق، فأرجو كيف أبرها؟","title":"كيفية بر الوالدة المنقطع عنها ولدها في بلد آخر","answer":"الجواب:\n\nتبرها بإرسال حاجاتها إليها، والكتابة إليها، ووصية الوافدين إليها بأنك طيب، تحملهم السلام، والمساعدة لها إذا كانت في حاجة، أو هدية، ولو كانت ما هي بحاجة، من باب الهدايا، من أجل تطييب القلوب، هذا هو الواجب عليك معها، حتى يسهل الله لك زيارتها بعد ذلك.","link":"https://binbaz.org.sa/fatwas/3317/كيفية-بر-الوالدة-المنقطع-عنها-ولدها-في-بلد-اخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1641.mp3","categories":["اللباس والزينة"]},{"id":7245,"question":"أنا أعلم تمامًا حرمة قطيعة الرحم، ولكن من طبيعتي عدم كثرة الزيارات؛ مما يسبب لي ترك زيارة أقاربي لمدة أكثر من شهر أحيانًا، ولكن لا أقصد بذلك شيئًا، فهل علي إثم بذلك؟","title":"صلة الأرحام بقدر الاستطاعة","answer":"الجواب:\n\nإنما عليك المستطاع، وليس عليك إثم بهذا، إنما عليك المستطاع في الزيارة التي تستطيعها، أو المكالمة الهاتفية، أو الكتابية، أو البرقية، أو الوصية، كل بحسبه.","link":"https://binbaz.org.sa/fatwas/3311/صلة-الارحام-بقدر-الاستطاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1636.mp3","categories":["اللباس والزينة"]},{"id":7246,"question":"حصل خلاف مع أحد أعمامي بسبب لا داعي للزعل فيه، فخرج وتركنا، ولم يعد يسلم علينا جميعنا -أنا ووالدي وإخواني- وقطعنا حتى سافر لبلد أخرى في الغربية، وحصل هذا تقريبًا منذ ثلاث سنوات، فماذا نفعل؟","title":"بذل الجهد في صلة الرحم","answer":"الجواب:\n\nإذا كانت قطيعته بأسباب أمر شرعي فعلتموه معه؛ فلا يضركم، يكون هو القاطع، لكن افعلوا ما تستطيعون من مراسلته، ودعوته إلى الخير، وإرسال بعض الهدايا إليه، والمعونة؛ لعل الله يفتح عليه، ويهدي قلبه حتى يرجع. \n\nالذي قطع الرحم من دون عذر شرعي هو القاطع، لكن أنتم لا تكونوا مثله، صلوه، وأحسنوا إليه ولو بالمراسلة، والمكاتبة، أو بالهاتف، دعوة له إلى الخير ونصيحة له، لماذا فعلت كذا، لماذا يا أخي فعلت كذا، ماذا سبب هذا الشيء؟ اتق الله يا عبدالله، راقب الله، ينصح هكذا من طريق المكاتبة، من طريق الهاتف، من طريق أن يزوره بعضكم في محله.","link":"https://binbaz.org.sa/fatwas/3306/بذل-الجهد-في-صلة-الرحم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1631.mp3","categories":["اللباس والزينة"]},{"id":7249,"question":"هل يكفي التليفون للاتصال بالأقارب، دون الذهاب إليهم؛ لأن عندي عذرًا هو أن أمي تعيش معي، وهي مسنة، ومن الصعوبة أن أتركها في البيت؟","title":"الاتصال بالهاتف من صلة الأرحام","answer":"الجواب:\n\nنعم يكفي، تتصل لهم بالهاتف، وتسأل عن حالهم، وترسل لهم ما يحتاجون إليه، إذا عذرت وكانوا في حاجة؛ يكفي هذا، ليس من اللازم الذهاب بالرجل، إذا لم يتيسر ذلك المكاتبة، أو البرقية، والهاتف تقوم مقام الزيارة بالقدم إذا لم يتيسر ذلك.","link":"https://binbaz.org.sa/fatwas/3307/الاتصال-بالهاتف-من-صلة-الارحام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1632.mp3","categories":["اللباس والزينة"]},{"id":7251,"question":"لي والدة بحضرموت، ولي مدة طويلة من خدمتها، وأنا هنا جئت لاكتساب الرزق، فأرجو كيف أبرها؟","title":"كيفية بر الوالدة المنقطع عنها ولدها في بلد آخر","answer":"الجواب:\n\nتبرها بإرسال حاجاتها إليها، والكتابة إليها، ووصية الوافدين إليها بأنك طيب، تحملهم السلام، والمساعدة لها إذا كانت في حاجة، أو هدية، ولو كانت ما هي بحاجة، من باب الهدايا، من أجل تطييب القلوب، هذا هو الواجب عليك معها، حتى يسهل الله لك زيارتها بعد ذلك.","link":"https://binbaz.org.sa/fatwas/3317/كيفية-بر-الوالدة-المنقطع-عنها-ولدها-في-بلد-اخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1641.mp3","categories":["اللباس والزينة"]},{"id":7252,"question":"أنا أعلم تمامًا حرمة قطيعة الرحم، ولكن من طبيعتي عدم كثرة الزيارات؛ مما يسبب لي ترك زيارة أقاربي لمدة أكثر من شهر أحيانًا، ولكن لا أقصد بذلك شيئًا، فهل علي إثم بذلك؟","title":"صلة الأرحام بقدر الاستطاعة","answer":"الجواب:\n\nإنما عليك المستطاع، وليس عليك إثم بهذا، إنما عليك المستطاع في الزيارة التي تستطيعها، أو المكالمة الهاتفية، أو الكتابية، أو البرقية، أو الوصية، كل بحسبه.","link":"https://binbaz.org.sa/fatwas/3311/صلة-الارحام-بقدر-الاستطاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1636.mp3","categories":["اللباس والزينة"]},{"id":7253,"question":"حصل خلاف مع أحد أعمامي بسبب لا داعي للزعل فيه، فخرج وتركنا، ولم يعد يسلم علينا جميعنا -أنا ووالدي وإخواني- وقطعنا حتى سافر لبلد أخرى في الغربية، وحصل هذا تقريبًا منذ ثلاث سنوات، فماذا نفعل؟","title":"بذل الجهد في صلة الرحم","answer":"الجواب:\n\nإذا كانت قطيعته بأسباب أمر شرعي فعلتموه معه؛ فلا يضركم، يكون هو القاطع، لكن افعلوا ما تستطيعون من مراسلته، ودعوته إلى الخير، وإرسال بعض الهدايا إليه، والمعونة؛ لعل الله يفتح عليه، ويهدي قلبه حتى يرجع. \n\nالذي قطع الرحم من دون عذر شرعي هو القاطع، لكن أنتم لا تكونوا مثله، صلوه، وأحسنوا إليه ولو بالمراسلة، والمكاتبة، أو بالهاتف، دعوة له إلى الخير ونصيحة له، لماذا فعلت كذا، لماذا يا أخي فعلت كذا، ماذا سبب هذا الشيء؟ اتق الله يا عبدالله، راقب الله، ينصح هكذا من طريق المكاتبة، من طريق الهاتف، من طريق أن يزوره بعضكم في محله.","link":"https://binbaz.org.sa/fatwas/3306/بذل-الجهد-في-صلة-الرحم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1631.mp3","categories":["اللباس والزينة"]},{"id":7256,"question":"هل يكفي التليفون للاتصال بالأقارب، دون الذهاب إليهم؛ لأن عندي عذرًا هو أن أمي تعيش معي، وهي مسنة، ومن الصعوبة أن أتركها في البيت؟","title":"الاتصال بالهاتف من صلة الأرحام","answer":"الجواب:\n\nنعم يكفي، تتصل لهم بالهاتف، وتسأل عن حالهم، وترسل لهم ما يحتاجون إليه، إذا عذرت وكانوا في حاجة؛ يكفي هذا، ليس من اللازم الذهاب بالرجل، إذا لم يتيسر ذلك المكاتبة، أو البرقية، والهاتف تقوم مقام الزيارة بالقدم إذا لم يتيسر ذلك.","link":"https://binbaz.org.sa/fatwas/3307/الاتصال-بالهاتف-من-صلة-الارحام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1632.mp3","categories":["اللباس والزينة"]},{"id":7265,"question":"دبلة الخطوبة؟","title":"حكم دبلة الخطوبة","answer":"الجواب:\n\nالدبلة ما لها أصل، غلط، ولا وجه لها، هذه تلقوها عن مشابهة أعداء الله، الشبكة يسمونها الشبكة، هذه ما لها أصل.","link":"https://binbaz.org.sa/fatwas/3330/حكم-دبلة-الخطوبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1651.mp3","categories":["اللباس والزينة","الخِطْبَة والاختيار ","البدع والمحدثات"]},{"id":7303,"question":"هل الحجاب نزل خاصًا بالحرائر المسلمين من النساء، ولم يفرض على الإماء، مع العلم أن الإماء بهن نفس الفتنة، وهل صحيح أن سيدنا عمر بن الخطاب نهى إحدى الإماء عن لبس الحجاب، والتشبه بالحرائر؟","title":"حكم اختصاص الحجاب بالحرائر من المسلمات دون الإماء","answer":"الجواب: الأصل أن الحجاب للحرائر، هذا هو الأصل، الإماء ممتهنات للخدمة، والغالب عليهن لا يكن خطرًا من جهة السفور، من جهة الجمال، فالأحرار يجب عليهن التستر، والحجاب، وذكر كثير من أهل العلم -رحمة الله عليهم-: أن الأمة إذا كان فيها جمال، وفيها خطر؛ كذلك يجب عليها أن تحتجب؛ لأن العلة واحدة، فإذا كانت ذميمة؛ صارت كالعجوز، لا يجب عليها الحجاب، العجوز الكبيرة التي لا تريد النكاح، ولا تتزين، وهي من القواعد، قال الله -جل وعلا-: وَالْقَوَاعِدُ مِنَ النِّسَاءِ اللَّاتِي لَا يَرْجُونَ نِكَاحًا فَلَيْسَ عَلَيْهِنَّ جُنَاحٌ أَنْ يَضَعْنَ ثِيَابَهُنَّ [النور:60]. العجوز الكبيرة التي لا تشتهى، ولا تتزين، ولا تعمل ما يرغب في النكاح، والأمة التي لا خطر فيها لا حجاب عليها.","link":"https://binbaz.org.sa/fatwas/3371/حكم-اختصاص-الحجاب-بالحراىر-من-المسلمات-دون-الاماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1689.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":7313,"question":"ما حكم اقتناء الطيور ووضعها في أقفاص، لا تخرج منها مع توفير المأكل والمشرب لها؟","title":"حكم اقتناء الطيور وحبسها في أقفاص","answer":"الجواب: لا حرج في ذلك، الطيور في الأقفاص مع الإحسان إليها، وعدم إهمالها؛ لا بأس، فقد ثبت عن النبي ﷺ أنه كان إذا مر على ولد لأبي طلحة -أخًا لأنس من أمه- كان عنده طير يمسكه، ويلعب به، فيقول: ما فعل النغير يا أبا عمير فإمساك الطيور ووضعها في البيوت أمر قديم، فإذا كانت الطيور يعتنى بها ولا يقصر في حقها؛ فلا حرج. السؤال: في منها طائر جارح يباع يسمونها طيور الزينة؟ الجواب: ما أعرفها، على كل إذا صيدت ولم تؤذ أحدًا؛ لا بأس.            السؤال: إذا حجر على حريتها وأخيرًا تموت في القفص؛ لأنها تشعر بأنها محرومة من الحرية، وانطلاقها في الجو؟ الجواب: لا ما تموت، نعرف طيورًا الآن من سنوات كثيرة وهي حية.","link":"https://binbaz.org.sa/fatwas/3380/حكم-اقتناء-الطيور-وحبسها-في-اقفاص","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1698.mp3","categories":["اللباس والزينة"]},{"id":7320,"question":"ما الحكم فيما يجري في بعض المباريات التي يكون بعد انتهاء المباراة توزيع سيارات للجمهور، وذلك بحسب أرقام تذاكر الدخول ليفوز بها أحد الحاضرين، فهل هذا من القمار؟","title":"حكم توزيع جوائز لجمهور المباريات عن طريق سحب أرقام التذاكر","answer":"الجواب: نعم قد نبهنا المسئولين أنه من القمار، وسيكتب في هذا -إن شاء الله- أيضًا، هذا من القمار، هذا يقدم تذاكر كثيرة بأرقام كثيرة، ثم ينظر في الأرقام، ثم يعطى هذا حسب رقم، وهذا حسب رقم، هذا غلط، هذا من الربا، من القمار المعروف من الميسر.","link":"https://binbaz.org.sa/fatwas/3394/حكم-توزيع-جواىز-لجمهور-المباريات-عن-طريق-سحب-ارقام-التذاكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1709.mp3","categories":["اللباس والزينة"]},{"id":7385,"question":"في هذه الأيام طلع ثوب للرجال فيه نسبة من الحرير، فما حكم لبسه إذا كانت نسبة هذا الحرير، أو حرير خالص؟","title":"لبس الحرير للرجال، والقدر الجائز في ذلك","answer":"الجواب: ثبت عن النبي ﷺ أنه قال: أحل الذهب والحرير لإناث أمتي، وحرم على ذكورهم فالحرير محرم على الرجال، مباح للنساء إلا موضع أصبعين، أو ثلاث، أو أربع كما قاله النبي ﷺ قال النبي ﷺ: لا تلبسوا الحرير يخاطب الرجال إلا موضع أصبعين، أو ثلاث، أو أربع كما رواه عمر  كما جاء في الصحيح. فإذا كانت القطعة التي في الثوب موضع أصبعين، أو ثلاثة، أو أربعة؛ فلا بأس، مثل رقعة في الثوب من الحرير، ومثل الزرار، ومثل علامة من الحرير، علامة في ثوب، جعلت في ثوب علامة، وما أشبه ذلك، هذه تباح، المقصود: قدر أصبعين أو ثلاث أو أربعة فقط في الثوب، وما زاد على هذا في لباس الرجل يحرم من الحرير. السؤال: الطبيعي، والصناعي؟  الجواب: المقصود الحرير الذي من المادة المعروفة، من دود القز يعني.","link":"https://binbaz.org.sa/fatwas/3475/لبس-الحرير-للرجال-والقدر-الجاىز-في-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1779.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":7399,"question":"ما مقدار الحجاب الوارد في الكتاب والسنة، هل هو أن المرأة عورة إلى وجهها، أو أن المرأة تغطي جميع وجهها إلى آخره؟","title":"بيان الحجاب الواجب على النساء","answer":"الجواب: المرأة كلها عورة، وجهها وقدمها ويدها ورأسها، كلها عورة، الواجب عليها التستر عن جميع الناس ماعدا المحارم في الداخل والخارج، حتى في بلاد الكفرة، بعض الناس يقول: إذا سافرنا إلى أوروبا، وإلى كذا لا بأس، وهذا غلط، الحجاب على الكافر أولى وأعظم من الحجاب على المسلم.  الواجب الحجاب في بلاد الإسلام، وفي بلاد الكفر، وإذا دعت الحاجة، إذا كان مثلًا الستر يمنعها من الرؤية؛ تجعل لعينها فتحة بقدر العين فقط، أو العينين لا بأس، كما روي عن ابن عباس -رضي الله تعالى عنهما- تجعل فتحة قدر عينها؛ حتى ترى طريقها، ما تمنع من الطريق، وإذا كانت ترى الطريق من وراء الحجاب؛ فالحمد لله. تقول عائشة -رضي الله عنها- حين كانوا مع النبي ﷺ قالت: (كنا إذا دنا منا الرجال؛ سدلت إحدانا خمارها على وجهها، وإذا بعدوا عنا؛ كشفنا) فالمرأة إذا كانت وحدها، أو بين النساء؛ تكشف، وإذا كانت بقرب الرجال؛ سدلت جلبابها، وخمارها على وجهها، ولو كانت محرمة؛ حتى يبتعد عنها الرجال.","link":"https://binbaz.org.sa/fatwas/3489/بيان-الحجاب-الواجب-على-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1793.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":7405,"question":"التي تبرز الأعضاء بخفة من خلالها، فهل من كلمة بليغة في قلوب الذين تجاوزوا الناس بالتبرج إن صح التعبير؛ لعلهم يهتدون؟","title":"نصيحة لمن يتهاون في ستر عورته","answer":"الجواب: الواجب على الرجال ستر العورات، فإذا كانت العورة مستورة بالإزار ساترًا ما بين السرة والركبة؛ فالباقي ما يضر، لكن إذا كانت الملابس كلها جيدة على البدن؛ كان أكمل وأجمل، لكن المهم أن يكون ما بين السرة والركبة مستورًا بسراويل أو أزر صفيقة ساترة، ما ترى منها صفات العورة، لا سوادها ولا بياضها، ولا حجمها، هذا هو الواجب. والنساء أشد في ذلك من النساء والرجال، أما بين الرجال؛ فعليهن أن يستر أبدانهن كلها، وبين النساء يسترن العورة.  الحاصل: أن الثوب الشفاف كالعارية، وهذا معنى كاسيات عاريات، ثوب رقيق، أو قصير هذا عارٍ، وهكذا الرجل إذا كان عليه سراويل شفافة، أو إزار شفاف ترى منه عورته؛ يكون ما ستر عورته -نسأل الله السلامة-.","link":"https://binbaz.org.sa/fatwas/3487/نصيحة-لمن-يتهاون-في-ستر-عورته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1791.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":7420,"question":"التي تبرز الأعضاء بخفة من خلالها، فهل من كلمة بليغة في قلوب الذين تجاوزوا الناس بالتبرج إن صح التعبير؛ لعلهم يهتدون؟","title":"نصيحة لمن يتهاون في ستر عورته","answer":"الجواب: الواجب على الرجال ستر العورات، فإذا كانت العورة مستورة بالإزار ساترًا ما بين السرة والركبة؛ فالباقي ما يضر، لكن إذا كانت الملابس كلها جيدة على البدن؛ كان أكمل وأجمل، لكن المهم أن يكون ما بين السرة والركبة مستورًا بسراويل أو أزر صفيقة ساترة، ما ترى منها صفات العورة، لا سوادها ولا بياضها، ولا حجمها، هذا هو الواجب. والنساء أشد في ذلك من النساء والرجال، أما بين الرجال؛ فعليهن أن يستر أبدانهن كلها، وبين النساء يسترن العورة.  الحاصل: أن الثوب الشفاف كالعارية، وهذا معنى كاسيات عاريات، ثوب رقيق، أو قصير هذا عارٍ، وهكذا الرجل إذا كان عليه سراويل شفافة، أو إزار شفاف ترى منه عورته؛ يكون ما ستر عورته -نسأل الله السلامة-.","link":"https://binbaz.org.sa/fatwas/3487/نصيحة-لمن-يتهاون-في-ستر-عورته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1791.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":7443,"question":"ما حكم المشاركة في الأسابيع التي تقام، مثل: أسبوع النظافة، وأسبوع الشجرة، حيث إنه يطلب مني المشاركة في إلقاء كلمة، أو تقديم حفل، أو غير ذلك، فهل في ذلك شيء؟","title":"حكم المشاركة في أسابيع النظافة والشجرة","answer":"الجواب: لا أعلم في هذا شيئًا لما فيه من المصلحة العامة للمسلمين، وليست من جنس الأعياد، بل هذا تعاون على شيء ينفع المسلمين، وليس بعيدٍ، وليس مما حرم الله ، إنما هو تعاون في أوقات معينة، أو بين وقت وآخر لهذه المصالح.","link":"https://binbaz.org.sa/fatwas/3539/حكم-المشاركة-في-اسابيع-النظافة-والشجرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1844.mp3","categories":["اللباس والزينة"]},{"id":7511,"question":"سؤال الأخوات ليلى وريماء القاضي الأخير يقلن فيه: إذا سافرت المرأة إلى الخارج فما حكم الحجاب مع كشف الوجه؟","title":"حكم كشف المرأة لوجهها عند سفرها إلى الخارج","answer":"الجواب: المرأة في الخارج كالداخل ليس لها كشف الوجه، بل عليها أن تحتجب في الداخل والخارج؛ لأن الله جل وعلا قال: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] وقال سبحانه: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ [النور:31] الآية، فالواجب عليهن التستر والتحجب مطلقاً في الداخل والخارج؛ لأن الرجال في الخارج كالداخل يخشى منهم الفتنة ويخشى عليهن الفتنة على النساء أيضاً، فالحاصل: أن الداخل والخارج سواء في وجوب الحجاب.","link":"https://binbaz.org.sa/fatwas/4475/حكم-كشف-المراة-لوجهها-عند-سفرها-الى-الخارج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_008/07945.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":7516,"question":"أيضاً السؤال الآخر: ما حكم إزالة شعر الأيدي والأرجل من أجل الزينة؟","title":"حكم إزالة النساء لشعر الأيدي والأرجل","answer":"الجواب: لا أعلم فيه بأساً، أخذ الشعر من يد المرأة أو رجلها لا حرج فيه، لا نعلم فيه بأساً، أما الوجه فلا؛ لأن الرسول ﷺ لعن النامصة والمتنمصة، وذكر أئمة اللغة أن النامصة: هي التي تأخذ الشعر من الوجه أو من الحاجبين، هذا هو الممنوع، أما لو ظهر لها لحية، أو ظهر لها شارب، أو صار لها شعر في يديها أو في رجليها فلا بأس بأخذه، ولا حرج في ذلك إن شاء الله.","link":"https://binbaz.org.sa/fatwas/4489/حكم-ازالة-النساء-لشعر-الايدي-والارجل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_008/00817.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":7569,"question":"طيب وبالنسبة للملابس الشفافة؟","title":"حكم لبس الملابس الشفافة أمام المحارم","answer":"الجواب: لا ما تجوز الشفافة، الشفافة خطيرة قد تبدي العورة، لكن إذا كان يعني شفافة في الذراع فهذا سهل، إذا كان البدن مستورا، فينبغي أن تكون الملابس ساترة صفيقة، لا تبين ما وراءها من حسن اللحم، وظهور اللحم من حمرة وبياض ونحو ذلك، بل تكون ساترة لهذا الشيء، تكون تحت الثوب الخفيف مثل الفنيلة التي تعين على ذلك وأشباه ذلك، المقصود أن الشفافة كالعارية، الشفافة من جنس العارية، فينبغي التحرز من هذا الشيء وعدم التساهل في هذا الشيء.","link":"https://binbaz.org.sa/fatwas/4575/حكم-لبس-الملابس-الشفافة-امام-المحارم ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_016/01605.mp3","categories":["الأخلاق المذمومة","سنن الفطرة","اللباس والزينة"]},{"id":7605,"question":"هذه الرسالة تتضمن بعض الأسئلة التي بعث بها عبد الوهاب بن عمر المريح ، يقول في رسالته: ما حكم حلق اللحى، وإطالة الإزار، والتكبر على الغير من المسلمين؟","title":"حكم حلق اللحى وإطالة الإزار والتكبر على الغير","answer":"الجواب: حلق اللحى محرم ومنكر ومخالف لسيرة النبي ﷺ وأوامره، وقد صح عن رسول الله عليه الصلاة والسلام أنه نهى عن ذلك فقال: قصوا الشوارب وأعفوا اللحى، خالفوا المشركين، وقال: جزوا الشوارب وأرخوا اللحى، خالفوا المجوس هكذا جاء عنه عليه الصلاة والسلام في الصحيحين من حديث ابن عمر رضي الله تعالى عنهما أن النبي ﷺ أمر بإعفاء اللحى وقص الشوارب فقال: قصوا الشوارب وأعفوا اللحى خالفوا المشركين، وفي صحيح مسلم عن أبي هريرة  عن النبي ﷺ أنه قال: جزوا الشوارب وأرخوا اللحى خالفوا المجوس، فأنت يا أخي مأمور باتباع نبيك عليه الصلاة والسلام وطاعته والسير على منهاجه، كما قال عز وجل: وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا [الحشر:7]، وقال جل وعلا: مَنْ يُطِعِ الرَّسُولَ فَقَدْ أَطَاعَ اللَّهَ [النساء:80]، وقال: أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ [النساء:59]، وقال: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَأَطِيعُوا الرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ [النور:56]، فالخير كله في طاعته؛ لأن طاعته طاعة لله ، وفي صحيح البخاري -رحمه الله- عن النبي ﷺ أنه قال: كل أمتي يدخلون الجنة إلا من أبى، قيل: يا رسول الله! ومن يأبى؟ قال: من أطاعني دخل الجنة، ومن عصاني فقد أبى. \nوهكذا التكبر على الناس وغمطهم من الكبائر، فالواجب التواضع لله والحذر من التكبر، صح عن رسول الله عليه الصلاة والسلام أنه سئل قال له رجل: يا رسول الله! الرجل يجب أن يكون ثوبه حسناً ونعله حسنة، أفذلك من الكبر؟ فقال النبي ﷺ: لا، إن الله جميل يحب الجمال، الكبر بطر الحق وغمط الناس» فبين عليه الصلاة والسلام أن كون الثياب حسنة والنعال حسنة وهكذا البشت وما أشبه ذلك هذا ليس من الكبر، إن الله جميل يحب الجمال، فالجمال طيب ومحبوب إلى الله ، وقد قال في كتابه الكريم: يَا بَنِي آدَمَ خُذُوا زِينَتَكُمْ عِنْدَ كُلِّ مَسْجِدٍ [الأعراف:31]، ثم بين أن الكبر أنه بطر الحق وغمط الناس، فالكبر بطر الحق، يعني: رد الحق واطراحه إذا خالف هواه، ومعنى غمط الناس يعني: احتقار الناس، هذا الكبر احتقار الناس، واستصغارهم، والتكبر عليهم، ورد الحق إذا خالف الهوى، هذا هو الكبر. \nأما الإسبال فهو محرم، جر الثياب أو الأزر أو السراويل أو البشت كله حرام؛ لما فيه من الكبر والخيلاء، ولما فيه أيضاً من إفساد الثياب وتنجيسها وتوسيخها، ولما فيه أيضاً من التشبه بالنساء، فإن المشروع للنساء إرخاء الثياب على الأقدام، فالمسبل قد تشبه بالنساء وخالف أمر الرسول ﷺ حيث نهى عن الإسبال، وقال عليه الصلاة والسلام: إياك والإسبال؛ فإنه من المخيلة، وقال أيضاً عليه الصلاة والسلام: ما أسفل من الكعبين فهو في النار رواه البخاري في الصحيح، وهذا عام سواء أراد تكبر أو لم يتكبر، هذا عام إذا تعمد ذلك، أما إذا غلبه ذلك ارتخى، مرفع وارتخى قليل وتعاهده هذا لا يدخل في ذلك، في قصة الصديق لما قال: يا رسول الله! إن الإزار يرتخي، قال: لست ممن يفعل ذلك خيلاء، أي لست ممن يتعمد إرخاء الإزار تكبراً وتعاظماً، وليس معناه التقييد، بل معناه أن من شأن من جر الأزر من شأنه التكبر، بخلاف الذي يتعاهد إزاره ويعتني به إذا استرخى فهذا ما قصد التكبر وليس ممن توعد بهذا الوعيد، ولهذا جاءت الأحاديث عامة في النهي عن الإسبال من غير تقييد، وجاء التقييد في أحاديث أخرى، فالتقييد لا يدل على تقييد الأحاديث الأخرى، بل هو من باب ذكر أفراد العام، فقوله ﷺ: من جر ثوبه خيلاء لم ينظر الله إليه يوم القيامة، هذا يوحي وعيداً شديداً فيمن قصد الخيلاء، مع عموم الأحاديث الدالة على تحريم الإسبال مطلقاً، مثل قوله ﷺ: ما أسفل من الكعبين من الإزار فهو في النار هذا عام ولأنه في الغالب يكون على الكبر، هذا الغالب، مع ما فيه من التساهل والتشبه بالنساء وتوسيخ الثياب ويعرضها للنجاسة، ومن هذا قوله صلى الله عليه وسلم في حديث أبي ذر عند مسلم: ثلاثة لا يكلمهم الله ولا ينظر إليهم ولا يزكيهم ولهم عذاب أليم: المسبل إزاره، والمنان فيما أعطى، والمنفق سلعته بالحلف الكاذب، هذا وعيد شديد فيما رواه مسلم في الصحيح لم يقيد بالكبر فهو عام، ومن قال: (إنه مع الكبر محرم ومع عدم ذلك مكروه) فقد ضاع.. خالف الأدلة مخالفة ظاهرة، لكن من جره بقصد الخيلاء صار إثمه أعظم وصارت عقوبته أشد، ومن جره تساهلاً وتعمداً فهو قد فعل منكراً وتشبه بالنساء وخالف الرسول ﷺ، وقد تعرض للوعيد: ما أسفل من الكعبين من الإزار فهو في النار، والوعيد في الآخر: ثلاثة لا يكلمهم الله ولا ينظر إليهم ولا يزكيهم ولهم عذاب أليم: المسبل إزاره، والمنان فيما أعطى، والمنفق سلعته بالحلف الكاذب، فالواجب على المسلمين الحذر من هذه الصفة وهذا الخلق الذميم ورفع الثياب فوق الكعب وألا تنزل تحت الكعب، فإن إزرة المؤمن من نصف ساقه إلى كعبه، ولا يجوز له نزول الثوب يعني سواء كان إزاراً أو قميصاً عن الكعب، ولا ينبغي أن يكون فوق نصف الساق؛ لأنه إذا كان فوق نصف الساق قد يتعرض لظهور العورة، والعورة من السرة إلى الركبة، لكن إذا ارتفع عن نصف الساق قد تنكشف العورة، فالأولى أن ينزل عن الركبة إلى نصف الساق، ولكن بين نصف الساق وبين الكعب هذا محل الإزرة الشرعية، وهذا محل أطراف الثياب من نصف الساق إلى الكعب، ولا يجوز النزول عن الكعب، نسأل الله للجميع التوفيق. نعم.","link":"https://binbaz.org.sa/fatwas/4658/حكم-حلق-اللحى-واطالة-الازار-والتكبر-على-الغير ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_021/02105.mp3","categories":["سنن الفطرة","اللباس والزينة"]},{"id":7606,"question":"في الحقيقة ما دمنا نتحدث عن طول الإزار، هذه رسالة من سعد منيف الروقي من الرياض يقول: إن في ساقه قريب من.. يقول: قريب من الكعب بعض الأشياء لا أريد خروجها للناس، فهل يجوز لي أن أطيل إزاري أو ثوبي حتى ينزل تحت الكعب أم لا؟","title":"حكم إطالة الإزار لعذر","answer":"الجواب: هذا قد يعرضه لسوء الظن به، وقد يكون أسوة لغيره في هذا المنكر الظاهر وهو الإسبال، فلا ينبغي له ذلك ولو كان في ساقه شيء، ولكن في إمكانه أن يلبس الجوارب -الشرابات- يلبسها ولا يكون في هذا شيء من المحذور، ولا يعرض الناس لتهمته وسوء الظن به، أما إسباله الثياب لهذا الغرض فالذي ينبغي ترك ذلك وأن يكتفي بلبس الشراريب التي تستر هذا الشيء. نعم. \nالمقدم: نعم أحسنتم.","link":"https://binbaz.org.sa/fatwas/4659/حكم-اطالة-الازار-لعذر ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_021/02106.mp3","categories":["اللباس والزينة"]},{"id":7607,"question":"سماحة الشيخ هذه عدة أسئلة استعرضنا بعض منها في لقائنا الماضي، وبقي منها أيضاً أسئلة وردتنا من عبد الوهاب بن عمر المريح من معهد الجوف العلمي، يقول في رسالته: ما حكم صبغ اللحية من الصبغة السوداء مع الدليل إن أمكن وفقكم الله؟","title":"ما حكم صبغ اللحية بالصبغة السوداء؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: \nفصبغ اللحى والرأس بالسواد لا يجوز في أصح قولي العلماء؛ لأنه ثبت عن رسول الله عليه الصلاة والسلام فيما رواه مسلم وأهل السنن عن جابر  أن النبي ﷺ قال في قصة أبي قحافة والد الصديق  لما رأى لحيته ورأسه كالثغامة بياضاً قال: غيروا هذا الشيب بشيء، واجتنبوا السواد. \nوفي حديث أنس عند أحمد: غيروا هذا الشيب وجنبوه السواد، وروى أحمد وأبو داود وغيرهما بإسناد جيد عن ابن عباس رضي الله عنهما عن النبي ﷺ أنه قال: يكون في آخر الزمان قوم يخضبون بالسواد كحواصل الحمام لا يريحون رائحة الجنة وهذا وعيد شديد. \nفهذه الأحاديث الثلاثة: حديث جابر وحديث أنس وحديث ابن عباس ، كلها دالة على تحريم الصبغ بالسواد، وأنه لا يجوز صبغه، وفي حديث ابن عباس الوعيد في ذلك، وفي حديث جابر الأمر بتغيير الشيب وتجنيب السواد، والأمر للوجوب، هذا هو الأصل في الأوامر، قوله: غيروا هذا الشيب، وجنبوه السواد هذا يدل على وجوب التغيير، لكن جاء ما يدل من فعل النبي ﷺ على أنه مستحب ومتأكد وليس بواجب التغيير؛ لأنه قد ورد بعض الأحيان قد ترك شيبه أبيض عليه الصلاة والسلام، وشيبه قليل عليه الصلاة والسلام، وهكذا فعل بعض الصحابة فدل على أن تغييره مستحب ومتأكد، لكن يكون بغير السواد، أما السواد فلم يأت ما يدل على الجواز، بل جاء ما يدل على التحريم، فتجنيب السواد الذي أمر به النبي ﷺ أمر واجب، يجب أن يجنب السواد، يعضده حديث أنس في الأمر بتجنب السواد، ثم يعضده الحديث الثالث حديث ابن عباس الذي في الوعيد أنه يكون في آخر الزمان قوم يخضبوا بالسواد كحواصل الحمام لا يريحون رائحة الجنة هذا وعيد شديد.\nفدل ذلك على وجوب ترك السواد الخالص، وأن التغيير يكون بالصفرة والحمرة ونحو ذلك، وقد صح عنه عليه السلام أنه قال: إن اليهود والنصارى لا يصبغون فخالفوهم فدل على أن السنة مخالفتهم في صبغ الشيب، وقد صبغ النبي ﷺ بالحناء والكتم وهكذا الصديق وعمر، فالسنة التغيير وعدم تركه أبيض، هذا هو السنة، لكن يكون بالأحمر.. بالأصفر.. بالحناء والكتم لا بأس، لكن لا يكون أسود خالصاً، بل مخلوط أسود معه حمرة.. معه صفرة لا بأس، إنما المحرم أن يكون أسود خالصاً حالكاً.. أسود مرة، هذا هو المنكر، أما إذا كان فيه الحمرة وفيه السواد فلا بأس. نعم.","link":"https://binbaz.org.sa/fatwas/4660/ما-حكم-صبغ-اللحية-بالصبغة-السوداء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_022/02201.mp3","categories":["اللباس والزينة"]},{"id":7608,"question":"في الحقيقة سماحة الشيخ هناك من يقول: إذا كنت أصبغ لحيتي فما الحكمة من تجنبي السواد؟","title":"المقصد الشرعي من تجنب السواد","answer":"الجواب: الله أعلم أن تجنب السواد؛ لأن السواد يحصل به التلبيس والتغرير أكثر، فإنه يريد أن يتشبه بالشباب، وأنه في دور الشباب وسن الشباب، أما الحمرة والصفرة فلا يحصل بها تلبيس، فالحمرة والصفرة يعرف بأنها شيب.. أنه شائب، وقد صبغ لأجل تغيير الشيب، أما السواد فيحصل به اللبس.. يحصل التزوير، يحصل بذلك ما لا ينبغي من التزوير على الناس وكأنه يقول: أنا ما شبت أنا شاب، فهذا نوع من الكذب الفعلي، كذب فعلي، بخلاف الصبغ بالأحمر والأصفر فإنه واضح. نعم.","link":"https://binbaz.org.sa/fatwas/4661/المقصد-الشرعي-من-تجنب-السواد ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_022/02202.mp3","categories":["اللباس والزينة"]},{"id":7612,"question":"سماحة الشيخ! هذه الرسالة وردت من سليمان الصالح من الرياض حي الشفا، يقول: إلى فضيلة الشيخ عبد العزيز بن باز حفظه الله!ما الذي يجوز للمرأة أن تكشفه من جسمها لمحارمها ماعدا زوجها، أرجو بيان ذلك بالتفصيل؛ لأنه الآن في البيوت كثر تكشف النساء لمحارمهن بشكل فاحش، كإخراج الشعر والنحر والصدر والكتفان والساقان ونحوهما، نرجو الإيضاح وفقكم الله؟","title":"ما الذي يجوز للمرأة كشفه من جسمها أمام محارمها؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: \nفقد ذكر أهل العلم ما يجب على المرأة من التستر عند الأجانب، وأن عليها أن تحتجب عن الأجانب في جميع بدنها؛ لأنها عورة، أما المحارم فذكر العلماء أنه لا بأس أن تكشف للمحارم ما جرت العادة بكشفه كالوجه واليدين والقدمين فلا محذور في ذلك. \nوهكذا شعر الرأس والساعد ونحو ذلك، كل هذا لا بأس به، والأولى بها الحرص على التستر إلا فيما جرت العادة بكشفه كالوجه واليدين والقدمين، فإن هذا لا محذور فيه عند المحارم كالأخ والعم ونحو ذلك، والله جل وعلا قال في كتابه الكريم: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ [النور:31] والمراد بذلك الزينة المعتادة المعروفة، والوجه من الزينة، واليد من الزينة، والقدم من الزينة، فهذه كلها لا بأس بها. \nوهكذا الشعر على الصحيح لا بأس أن يراه محرمها كأخيها وعمها ونحو ذلك؛ لأن من العادة أن مثل هذا يظهر بين المحارم، فلا حرج في ذلك، ولكن ينبغي لها أن تكون حريصة على الستر مهما أمكن؛ لأن بعض المحارم لا يرجى خيره ويخشى شره في هذا العصر، فكونها تستتر إلا الوجه واليدين والقدمين هذا هو الأولى والأحسن لها؛ احتياطاً وبعداً عن أسباب الشر. \nوإلا فالمحرم يجوز له أن ينظر الشعر وينظر الساق والساعد كل هذا لا بأس به في حق المحرم على الصحيح، ولكن كونها تحتاط لنفسها ولا تبدي إلا الشيء الذي جرت العادة غالباً بكشفه، كالوجه والكفين والقدمين هذا هو الأحوط لها والأحسن لها؛ بعداً عن الشر وصيانةً لنفسها عن أسباب الخطر. نعم. \nالمقدم: هذه الرسالة بعث بها المواطن (ح. ن. م. ي).\nالشيخ: قبل هذا نحب أن نقول للسائل عما يتعلق بالمرأة مع محارمها: إن لنا عودة في المقام هذا.. لنا عودة في حديث آخر إن شاء الله للتحقيق في الموضوع ونقل كلام العلماء في ذلك، حتى يكون السائل وغير السائل على بينة كاملة في ذلك، بالنسبة للمرأة والكشف لـمحارمها لنا عودة إن شاء الله في هذا للتحقيق في الموضوع وبيان كلام أهل العلم وبيان الصواب في ذلك على وجه أكمل مما تقدم. \nالمقدم: أحسنتم وبارك الله فيكم. نعم.","link":"https://binbaz.org.sa/fatwas/4665/ما-الذي-يجوز-للمراة-كشفه-من-جسمها-امام-محارمها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_023/02301.mp3","categories":["اللباس والزينة"]},{"id":7656,"question":"هذه الرسالة وردت من حمد مسعود فضل من السودان، يقول: عندنا عادة وهي وضع الحناء على أيدي وأرجل العروس والعروسة في آنٍ واحد، فما حكم هذا العمل وفقكم الله؟","title":"حكم وضع الحناء للرجل والمرأة في الأفراح","answer":"الجواب: أما وضع الحناء في رجل العروسة وفي يديها فلا نعلم فيه شيئاً من باب الزينة لزوجها، وأما الرجل فلا يتزين بهذا؛ لأن هذه زينة النساء.. تشبه بالنساء، فلا يليق ولا يجوز، لا يجوز للرجل أن يتشبه بالنساء لا في الحناء ولا في غير ذلك من الملابس؛ لأن الرسول ﷺ منع من ذلك، ولعن الرجل أن يتشبه بالمرأة والمرأة تتشبه بالرجل، هذا لا يجوز. نعم.","link":"https://binbaz.org.sa/fatwas/4817/حكم-وضع-الحناء-للرجل-والمراة-في-الافراح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_037/03705.mp3","categories":["اللباس والزينة"]},{"id":7676,"question":"هذه رسالة من جدة من المرسلة (ج. ص) تقول: إنني معجبة بالبرنامج نور على الدرب ومحبةً له، وتقول: أرجو عرض رسالتي هذه على سماحة الشيخ: عبد العزيز بن عبد الله بن باز أو الشيخ: عبد الله بن محمد: ما حكم التخفيف من شعر الحاجبين للمرأة للزينة، وكذلك إزالة شعر الوجه أرجو الإجابة بالتفصيل؟","title":"حكم الأخذ من شعر الحاجبين لأجل الزينة","answer":"الجواب: ليس للمرأة أن تأخذ من شعر حاجبيها أو وجهها شيئاً؛ لأن أهل العلم باللغة العربية قالوا: إن النمص الذي لعن الرسول ﷺ صاحبه هو الأخذ من الحاجبين أو من شعر الوجه، ونتف ذلك أو أخذه بالمنماص وهو المنقاش فليس لها أن تأخذ من حاجبيها، وليس لها أن تأخذ من شعر وجهها، بل عليها أن تدع ذلك، وتحذر ما جاء عن النبي ﷺ من اللعن؛ لأن الرسول ﷺ لعن النامصة والمتنمصة، قال العلماء: والنمص: أخذ شعر الوجه أو أخذ شعر الحاجبين، فليس لها أن تفعل ذلك، وعليها أن تتقي الله في ذلك، لكن لو نبت لها لحية، أو شارب، أو شعر خلاف العادة يعني يشينها فلا بأس أن تأخذه وتزيله، أما الشيء العادي الذي ما فيه استنكار هذا يترك، وهكذا الحاجبان لا يتعرض لهما. نعم.","link":"https://binbaz.org.sa/fatwas/4875/حكم-الاخذ-من-شعر-الحاجبين-لاجل-الزينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_040/04003.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":7677,"question":"أيضاً تقول: هل يجوز للمرأة أن تذهب إلى الخياطين من الرجال لخياطة ملابس، مع أنه يوجد نساء خياطات، حتى ولو كان معها محرم مع العلم أنه لا يؤخذ لها مقاس بيده، وإنما يعطى له فستان آخر يعمل بموجبه، أرشدونا نحن معشر الحريم وفقكم الله؟","title":"حكم ذهاب المرأة إلى الخياطين","answer":"الجواب: لا حرج في أن كون المرأة تذهب للخياط، أو يذهب وليها فيعطيه ملابس لها بمقاييس يقيس عليها، إما ملابس أو خيوط يقيس عليها لا بأس في ذلك، إنما المحذور كونها تذهب بنفسها يقيس عليها يلمسها أو يخلو بها هذا منكر ما يجوز، كونه يخلو بها أو يقيس عليها بيده يلمسها بيده هذا منكر، أما تعطيه الثوب يقيس عليه أو خيوط يقيس عليها فلا بأس، وإذا تيسر خياطات كافيات فالنساء أولى بكل حال. نعم.","link":"https://binbaz.org.sa/fatwas/4876/حكم-ذهاب-المراة-الى-الخياطين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_040/04004.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":7678,"question":"من سليمان القناص من بريدة بعث هذه الرسالة يسأل فيها عن جلد الثعلب، يقول: السلام عليكم ورحمة الله وبركاته وبعد: هل جلد الثعلب حرام؟ وهل يجوز اقتناؤه للزينة أفيدونا جزاكم الله خير وشكراً؟في الحقيقة أننا اهتمينا من هذا الموضوع؛ لأن كثرة الجلود الآن تباع في الأسواق وهي مختلفة لأنواع من السباع وغيرها.","title":"حكم اقتناء جلود السباع","answer":"الجواب: فيها خلاف كثير بين أهل العلم جلود السباع، جلود الثعلب والذئب والنمر فيها خلاف بين أهل العلم كثيراً، والذي ينبغي ألا يقتنى وألا يستعمل؛ لأنه جاءت أحاديث تدل على النهي عن جلود السباع وعن افتراشها وعن ركوبها وسمى النبي ﷺ الدباغ طهارة ذكاةً، فدل ذلك على أن الدباغ إنما يكون لما يطهر بالذكاة كمأكول اللحم من الإبل والبقر والغنم ونحو ذلك، فهذه جلودها طيبة ولو ميتة إذا دبغت، أما السباع فهي نجسة ولو ذبحت نجسة، فلا يؤثر فيها الدباغ، فالذي ينبغي للمؤمن ألا يستعمل جلود السباع لا للثعلب ولا غيره، وهذا هو أرجح الأقوال لأهل العلم وهو أحوطها للمؤمن. نعم.","link":"https://binbaz.org.sa/fatwas/4880/حكم-اقتناء-جلود-السباع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_040/04008.mp3","categories":["اللباس والزينة"]},{"id":7695,"question":"هذه رسالة وردتنا من المرسل عواض رده الحارثي من ميسام بلاد بني الحارث قرية المخلد، يقول في رسالته: السلام عليكم ورحمة الله وبركاته. وبعد: أفيدكم أنني أحد المستمعين لبرنامجكم الغالي الذي حل كثيراً من المشاكل، وأنار الطريق أمام كثير من الناس، أدامه الله وأدام العاملين عليه، وأمدهم بالخير والثواب، هذا وإني قد كتبت لكم هذه الرسالة وضمنتها بعض الأسئلة، راجياً منكم عرضها على سماحة الشيخ عبد العزيز بن عبد الله بن باز أثابه الله وسدد خطاه، آمين. السؤال الأول: هل يجوز للمرأة المتزوجة أن تلبس اللبس الخفيف مثل الشلحة، أو تكشف عن شعر رأسها وهي جالسة مع أبيها أو إخوانها أو عمها، أفيدونا وفقكم الله؟","title":"حكم كشف المرأة شعرها أمام المحارم","answer":"الجواب: ينبغي للمرأة أن تكون حريصة على صيانة جسمها، وعلى حفظ مفاتنها وصيانتها حتى عن المحارم حذراً من الفتنة، ولكن لا بأس أن يبدو شعرها أو ساعدها أو شيء من ساقها لا بأس لمحرمها كأبيها وأخيها وعمها ونحو ذلك، لكن كونها تتحفظ وتستر شعرها، وساعديها وساقيها عن المحارم من باب الاحتشام، ومن باب الحذر من بعض المحارم الذين قد يخشى منهم الشر؛ لأن المحارم بعضهم فيه فسق وفيه خطر، فإذا احتشمت وسترت نفسها عند محارمها ولم تبدي إلا وجهها وكفيها أو قدميها مثلاً، هذا يكون أحسن وأحوط وأبعد لها عن الخطر؛ لأن بعض المحارم يخشى شرهم لفسقهم وانحرافهم أو كفر بعضهم -لا حول ولا قوة إلا بالله- ولكن يجوز للمحرم أن ينظر شعرها وساقها -مثلاً- وساعدها، كما ينظر وجهها وكفيها، لكن كونها تحتشم وكونها تستر هذه الأمور ولا تبدي إلا الوجه والكفين، أو القدمين مثلاً، هذا يكون أفضل لها وأحوط؛ حذراً من بعض المحارم الذين ليس عندهم من الإيمان والتقوى ما يحجزهم عن الشر، هذا هو الذي ينبغي، ولا سيما إذا خلا بها محرمها كأخيها وعمها؛ فإن الحشمة في هذا المقام أولى وأفضل وأحوط. نعم. \nالمقدم: أيضاً يقول: هل يحل للبنت أن تكشف الحجاب أو تجلس مع ابن عمها أو ابن خالها؟ \nالشيخ: قبل هذا، أما الثياب الرقيقة التي لا تستر العورة فلا تلبس الثياب الرقيقة التي تبين أفخاذها أو تبين عورتها أو ضيقة، هذا لا يجوز لها حتى عند المحارم، ما يجوز، يعني تلبس ملابس ساترة، والشلحة وحدها كذلك ما ينبغي أن تفعلها عند المحارم؛ لأن الشلحة تكشف الكثير من جسمها، فلا ينبغي لها ذلك، ولكن تلبس ثياباً ساترة وتبدي وجهها وكفيها، لا بأس مع محارمها. نعم. \nالمقدم: أحسنتم.","link":"https://binbaz.org.sa/fatwas/4894/حكم-كشف-المراة-شعرها-امام-المحارم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_028/02806.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":7704,"question":"هذه الرسالة وردتنا من المرسلة تقول الأخت (خ. م. ب): هل حرام أن تعمل الفتاة حاجباها؟ فلقد عرضت ذلك السؤال على عدة شيوخ، فمنهم من يقول: حرام، ومنهم من يقول: ليس حرام، ويوردون لي الحديث التالي: بارك الله في المرأة الحلساء الملساء اللا شعور، والرجل الشعور، ولا بارك الله في رجل أملس لا شعور وامرأة شعور أفيدوني وفقكم الله؟","title":"حكم أخذ المرأة من شعر الحاجبين","answer":"الجواب: هذا الحديث لا أصل له: لا بارك الله في الحلساء الملساء إلى آخره، هذا لا نعرف له أصلاً، هذا الحديث لا أصل له، ولا نعرف له أصلاً عن النبي عليه الصلاة والسلام، أما الحاجبان فليس لها أن تأخذ منهما شيئاً؛ لأن النبي ﷺ لعن النامصة والمتنمصة، والنامصة: هي التي تأخذ من الحاجبين أو من شعر وجهها، وقد فسر العلماء النمص بأخذ شعر الحاجبين والوجه.. شعر الوجه، فليس لها أن تأخذ شعر حاجبيها ولا شعر وجهها العادي، ليس لها أن تأخذ ذلك، لا بالمنقاش ولا غيره عملاً بالحديث، وليس لها أن تغير في حاجبيها، بل عليها أن تترك ذلك وتحذر ذلك، أما لو قدر أنه نبت لها لحية أو شارب شيء يعني مستنكر خلاف المعتاد هذا لا بأس أن تزيله؛ لأنه مثلة وفتنة، أما الشعر العادي.. حاجبها العادي.. الحاجب وأشباه ذلك هذا لا يؤخذ منه شيء؛ لأن الرسول ﷺ لعن النامصة والمتنمصة والنمص: هو أخذ شعر الحاجبين، وفسر أيضاً: بأخذ شعر الوجه بالمنماص وهو المنقاش؛ لأنه يسبب تشويهاً وقبحاً في الوجه، ولحكم أخرى الله جل وعلا أعلم بها، والحاصل أن علينا الامتثال والطاعة لله ولرسوله، والحذر مما نهى الله عنه ورسوله. نعم.","link":"https://binbaz.org.sa/fatwas/4903/حكم-اخذ-المراة-من-شعر-الحاجبين ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_029/02906.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":7718,"question":"سؤالها الأخير تقول: أمي في سن الأربعين وقد ابيض شعر رأسها، فهل يجوز لها أن تصبغه بالصبغ الأسود، أم لا يجوز لها ذلك، وفقكم الله؟","title":"حكم تغيير الشيب بالأسود الخالص","answer":"الجواب: السنة أن يغير الشيب من الرجل والمرأة؛ لأن الرسول ﷺ قال: غيروا هذا الشيب وجنبوه السواد في قصة أبي قحافة ، لكن ينبغي أن يكون التغيير بغير السواد مثل الحمرة والصفرة لا بالسواد الخالص، وإذا غير الشيب بشيء ممزوج من أحمر وأسود فلا بأس، كما جاء عنه صلى الله عليه وسلم أنه خضب بالحناء والكتم، وجاء عن الصديق وعمر وغيرهما الخضاب بالحناء والكتم، هذا هو السنة وهو الأفضل.\nوالأفضل أن لا يترك الشعر أبيض، لكن التغيير بالسواد هو الذي لا يجوز، الصواب أنه لا يجوز؛ لأن الرسول ﷺ قال: جنبوه السواد قوله: وجنبوه السواد يدل على أنه لا يجوز الخضاب بالسواد الخالص.\nوفي مسند أحمد وسنن أبي داود بإسناد جيد: عن ابن عباس رضي الله عنهما عن النبي ﷺأنه قال: يكون في آخر الزمان قوم يخضبون بالسواد كحواصل الحمام لا يريحون رائحة الجنة وهذا وعيد عظيم، يدل على تحريم الخضاب بالسواد.\nومن زعم أن قوله في الحديث: وجنبوه السواد مدرج فقد غلط، الحديث ثابت، وقوله ﷺ: وجنبوه السواد متصل، من كلام النبي ﷺ لا من كلام غيره، وهو ثابت في صحيح مسلم وغيره.\nالواجب على المسلم الحذر مما نهى الله عنه، والاكتفاء بما شرع الله وأباح. والله أعلم.\nالمقدم: أحسنتم.","link":"https://binbaz.org.sa/fatwas/4917/حكم-تغيير-الشيب-بالاسود-الخالص","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_031/03104.mp3","categories":["اللباس والزينة"]},{"id":7727,"question":"أيضاً يقول: أنه رأى بعض الشركات لديها مجموعة من الفلبينيين غير المسلمين وهم يعملون لدى بعض هذه الشركات، وقد كتب على الفنيلة الداخلية لدى كل منهم اسم الشركة وكتب على الفنيلة أيضاً بسم الله الرحمن الرحيم، فما حكم ذلك؟","title":"حكم كتابة أسماء الله على الملابس","answer":"الجواب: قد يقال في هذا إن الكتابة على الفنيلة بسم الله الرحمن الرحيم غير جائز؛ لأنها عرضة لأن تلقى في المحلات التي لا يتوقى فيها القذر، وقد تلقى في محلات ليست نظيفة، فالحاصل أنه لا ينبغي أن يكتب على الفنيلة وشبهها أسماء الرب ، ولا بسم الله الرحمن الرحيم، ولا آيات من القرآن؛ لأن هذا قد يمتهن ويداس في بعض الأحيان إذا اخلولق، فالمقصود أن هذا لا يجوز لا في حق النصارى ولا في حق غيرهم. \nوبهذه المناسبة فإنه لا يجوز استقدام الكافرات للعمل في الجزيرة، بل يجب أن يمنع ذلك حتى لا يستقدم إلا المسلمات؛ لأن هذه الجزيرة أمر النبي صلى الله عليه وسلم بإخراج اليهود والنصارى منها، وبإخراج المشركين منها حتى لا يكون فيها إلا دين واحد وهو دين الإسلام، فالذي أوصي به إخواني في هذه البلاد أن يحذروا استيراد الكافرات والكافرين للعمل أو غيره، بل يجب أن يكون الاستيراد من المسلمين خاصة، لأن هذه الجزيرة لا يجوز أن يبقى فيها دينان ولا يجوز أن يبقى فيها يهودي أو نصراني أو وثني، بل يجب أن تطهر من ذلك تنفيذاً لوصية النبي عليه الصلاة والسلام. نعم.","link":"https://binbaz.org.sa/fatwas/4926/حكم-كتابة-اسماء-الله-على-الملابس ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_032/03202.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":7751,"question":"سؤالها الأخير والثاني تقول: هل يمكن أن يتبادل رجل وامرأة الخطابات في أمور الدين كما ورد عن عائشة بنت طلحة أو فيما ورد عن عائشة رضي الله عنها أم المؤمنين حين أرسل لها معاوية؟وهل يمكن أن يحدث تبادل خطابات بين رجل وامرأة لتسهيل أمر الزواج بمعنى إرسال معلومات عنها أو أي شيء آخر يسهل أمر الزواج إذا كان ذلك غير متيسر بأي طريقة أخرى؟ مع اتقاء الله في هذه الرسائل وعدم الخضوع بالقول؟ بارك الله فيكم وجزاكم الله خيراً؟","title":"حكم المراسلات بين الرجل والمرأة في أمور الدين","answer":"الجواب: لا بأس بتبادل الرسائل بين الرجال والنساء في مسائل العلم مسائل الدين مسائل الدنيا أيضاً لا بأس بتبادل الرسائل أن تكتب المرأة للرجل تنصحه أو تسأله عن علم أو عن تجارة وهي تتعاطى التجارة أو عن مسائل أخرى لا تعلق بالفساد وإنما تعلق بصالح الدين والدنيا لا بأس، ولا بأس أن يكتب الرجل للمرأة إذا كانت فقيهة يسألها عن مسائل دين أو عن مسائل نسب أو عن مسائل تتعلق بأمور الدنيا من التجارة أو أراضي أو غير ذلك، المقصود الرسائل التي ليس فيها محذور وليس فيها ما ينم عن ريبة فلا حرج في ذلك، لا مع الكبار ولا مع الصغار لا من الرجال ولا من النساء، وقد كتب معاوية إلى عائشة رضي الله عنها يقول لها: اكتبي لي بنصيحة أو بوصية وأوجزي، فكتبت له رضي الله عنها الحديث المشهور عن النبي ﷺ أنه قال: من التمس رضا الله بسخط الناس رضي الله عنه وأرضى عنه الناس، ومن التمس رضا الناس بسخط الله سخط الله عليه وأسخط عليه الناس هو حديث جيد رواه ابن حبان في الصحيح وغيره.\nوفي لفظ أنها كتبت إليه خبراً آخر بلفظ آخر: «من التمس رضا الله بسخط الناس كفاه الله مئونة الناس، ومن التمس رضا الناس بسخط الله لم يغنوا عنه من الله شيئاً، وعاد حامده له ذاماً».\nفالحاصل أن المكاتبة في هذا الباب لا بأس بها بين الرجال والنساء وهكذا بين الخاطب والمخطوبة كونها تكتب له عن حالها بصدق حتى يكون على بينة ويكتب لها عن حاله بصدق حتى تكون على بينة؛ لا بأس، لكن يجب الحذر من الكذب الذي قد يغر هذا أو هذا، الواجب الصدق في كل شيء، وإذا تيسر اللقاء للخاطب مع المخطوبة فلا بأس لكن بشرط عدم الخلوة إذا طلب أن يقابلها أو طلبت هي أن يقابلها فلا بأس، لكن على شرط ألا يكون هناك خلوة؛ لأن الخلوة محرمة ومن أسباب الشر وقد نهى النبي ﷺ عن الخلوة وقال: لا يخلون رجل بامرأة إلا ومعها ذو محرم وقال: لا يخلون رجل بامرأة؛ فإن الشيطان ثالثهما فلا يجوز أن يخلو بها الخاطب، ولكن إذا حضرت أمها أو أختها الكبيرة أو جدتها أو زوجة أبيها أو حضر شخص آخر من دون ريبة، مجالس محترمة فلا بأس. نعم.","link":"https://binbaz.org.sa/fatwas/4950/حكم-المراسلات-بين-الرجل-والمراة-في-امور-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_043/04302.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":7776,"question":"هذه الرسالة وردتنا من فرنسا: عبد الرحمن محمد العسيري ، يقول فيها: الحمد الله، والصلاة والسلام على رسول الله، وبعد: أخبركم بأنني أحد الطلبة السعوديين المبتعثين إلى فرنسا، ولي عدة أسئلة أرجو من سماحتكم إجابتي عليها، ولكم جزيل الشكر؟يقول من أسئلته هذه: هل يجوز للمرأة المسلمة كشف وجهها، في مثل هذه البلاد أم لا؟","title":"حكم خلع المسلمة الحجاب في بلاد الكفار","answer":"الجواب: لا يجوز للمرأة المسلمة كشف وجهها لا في فرنسا ولا في غيرها من البلدان، بل عليها أن تحافظ على دينها أينما كانت سواءً كانت في السعودية أو في غير السعودية، هذا الواجب؛ لأن هذا دين، واجب. يجب أن يحافظ عليه مطلقاً، فيجب على المسلمة أن تحافظ على ما شرع الله لها من الحجاب في أي مكان كانت؛ لأن الله قال سبحانه وتعالى: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]، وهذا يعم جميع الأماكن وجميع الأزمان، ولأن الله قال سبحانه وتعالى: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ [النور:31] الآية.\nومعلوم أن الوجه هو أعظم الزينة، فليس لها أن تبدي وجهها للأجنبي لا في فرنسا، ولا في أمريكا، ولا في غير ذلك، عليها أن تحافظ على الحجاب، والله يأجرها ويثيبها. نعم.","link":"https://binbaz.org.sa/fatwas/4988/حكم-خلع-المسلمة-الحجاب-في-بلاد-الكفار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_047/04705.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":7779,"question":"هذه رسالة من جدة من المرسلة (ج. ص) تقول: إنني معجبة بالبرنامج نور على الدرب ومحبةً له، وتقول: أرجو عرض رسالتي هذه على سماحة الشيخ: عبد العزيز بن عبد الله بن باز أو الشيخ: عبد الله بن محمد: ما حكم التخفيف من شعر الحاجبين للمرأة للزينة، وكذلك إزالة شعر الوجه أرجو الإجابة بالتفصيل؟","title":"حكم الأخذ من شعر الحاجبين لأجل الزينة","answer":"الجواب: ليس للمرأة أن تأخذ من شعر حاجبيها أو وجهها شيئاً؛ لأن أهل العلم باللغة العربية قالوا: إن النمص الذي لعن الرسول ﷺ صاحبه هو الأخذ من الحاجبين أو من شعر الوجه، ونتف ذلك أو أخذه بالمنماص وهو المنقاش فليس لها أن تأخذ من حاجبيها، وليس لها أن تأخذ من شعر وجهها، بل عليها أن تدع ذلك، وتحذر ما جاء عن النبي ﷺ من اللعن؛ لأن الرسول ﷺ لعن النامصة والمتنمصة، قال العلماء: والنمص: أخذ شعر الوجه أو أخذ شعر الحاجبين، فليس لها أن تفعل ذلك، وعليها أن تتقي الله في ذلك، لكن لو نبت لها لحية، أو شارب، أو شعر خلاف العادة يعني يشينها فلا بأس أن تأخذه وتزيله، أما الشيء العادي الذي ما فيه استنكار هذا يترك، وهكذا الحاجبان لا يتعرض لهما. نعم.","link":"https://binbaz.org.sa/fatwas/5068/حكم-الاخذ-من-شعر-الحاجبين-لاجل-الزينة ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_040/04003.mp3","categories":["اللباس والزينة"]},{"id":7799,"question":"الرسالة الأخيرة التي بين يدينا في هذا اللقاء بعث بها المستمع عبد الله أبو حذيفة يقول: أخوكم من الإمارات العربية المتحدة، الإخوة المشرفين والمجيبين على أسئلة المستمعين السلام عليكم ورحمة الله وبركاته وبعد: ما حكم مصافحة النساء خاصة وأن الإنسان قد يغيب عن وطنه زمناً طويلا فتأتي النساء لتصافحه فلا يجد مهرباً إلا أن يصافحهن وهو كاره لذلك كراهية أن يلقى في النار، فما الحكم في ذلك؟","title":"حكم مصافحة النساء الأجنبيات","answer":"الجواب: مصافحة النساء إذا كن غير محارم لا تجوز، والنبي ﷺ كان يبايع النساء بالكلام ولم يكن يصافح النساء وقال: إني لا أصافح النساء عليه الصلاة والسلام، والله يقول: لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ [الأحزاب:21] ولأن مصافحتها قد تفضي إلى الفتنة، قال بعض أهل العلم: إنها أشد من النظر فلا تجوز المصافحة إلا لمحرمك أختك عمتك خالتك لا بأس، أما غير المحارم مثل جيرانك من النساء، مثل: بنات عمك.. بنات خالك، هؤلاء ليسوا محارم فليس لك أن تصافحهن ولو قدمت من سفر طويل ليس لك أن تصافح بل تسلم عليهن بالكلام، وترد عليهن بالكلام، وتسألهن عن أحوالهن بالكلام، أما المصافحة فلا، هذا هو الواجب عليك وليس في هذا حياء، المؤمن لا يستحي من هذا بل يبين لهن أنها لا تجوز المصافحة، فإذا قدمت يدها يقول لها: يا أخت! لا تجوز المصافحة ويقبض يده ويعلمها ويرشدها حتى لا تعود لمثل ذلك، وليس في هذا بأس بحمد الله، والله لا يستحيي من الحق سبحانه وتعالى.\nفالواجب بيان الحق حتى يتعلم الناس وحتى يستفيد الناس رجالاً ونساءً فإذا سكت هذا وسكت هذا واستحيا هذا واستحيا هذا بقيت الجهالة وبقي الغلط والخطأ فلا يجوز هذا، وفق الله الجميع وصلى الله وسلم على نبينا محمد وعلى آله وأصحابه.","link":"https://binbaz.org.sa/fatwas/5161/حكم-مصافحة-النساء-الاجنبيات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_050/05009.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":7837,"question":"يسأل أخونا سؤالاً آخر فيقول -مثلاً سماحة الشيخ-: ما هو لباس المرأة في الإحرام؟","title":"صفة لباس المرأة المحرمة","answer":"الجواب: ليس لها لباس خاص، فلو أحرمت في ثيابها العادية أجزأ ذلك، ولكن الأفضل أن تكون ملابسها ملابس لا تلفت النظر، ليس فيها شهرة وليس فيها زينة تلفت النظر، بل تكون ملابس عادية ليس فيها جمال يلفت أنظار الرجال، كالأسود السادة والأحمر السادة والأخضر ونحو ذلك الذي ليس فيه جمال يلفت الأنظار، هذا هو الأفضل لها والأحسن لها، ولو أحرمت في ملابسها العادية جاز ذلك وصح ذلك، ولكن الأفضل لها أن تحرم في ملابس لا تلفت النظر ..... ليس فيها ما يسبب فتنة الرجال بها، هذا هو الأفضل لها، مع سترها ما قد يفتن من حلي أو غيرها، نعم.\nالمقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/5222/صفة-لباس-المراة-المحرمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_052/05203.mp3","categories":["محظورات الإحرام","اللباس والزينة"]},{"id":7841,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين آثر عدم ذكر اسمه، فيسأل أربعة أسئلة، في سؤاله الأول يقول: هل يجوز اتخاذ الطيور مثل الببغاء وغيره داخل قفص ووضعها في البيوت لغرض الزينة، أو اتخاذ البلابل داخل قفص أيضاً للاستمتاع بصوتها، وهناك نوع آخر يكون على شكل حوض وفيه ماء توضع فيه الأسماك الملونة، هل يجوز هذا؟","title":"حكم حبس الطائر في قفص للزينة كالببغاء وغيرها","answer":"الجواب: ليس في ذلك حرج إذا أحسن إليها ولم تظلم، فإذا أحسن إليها في طعامها وشرابها فلا حرج في الببغاء ولا غير الببغاء، والحمام، والدجاج وغير ذلك، بشرط الإحسان إليها وعدم ظلمها، وإذا كانت في حوش أو في ماء كالسمك، أو في صناديق لا تضرها تعطى حبوب تعطى الشراب يعني: لا يكون عليها ظلم فلا بأس بهذا. نعم.\nالمقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/5224/حكم-حبس-الطاىر-في-قفص-للزينة-كالببغاء-وغيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_052/05205.mp3","categories":["اللباس والزينة"]},{"id":7844,"question":"شق رسالته الثاني يقول: والدي صالح بعد أن وصل منى ذبح كبشاً وحلق رأسه ولبس ثيابه، فهل فعله هذا صحيح أم يلزمه هدي، وفقكم الله؟","title":"حكم من لبس المخيط قبل رمي الجمرة","answer":"الجواب: المشروع أنه لا يلبس ثيابه حتى يرمي الجمرة يوم العيد، ثم يحلق أو يقصر ويذبح بينهما هذا هو الأفضل، يرمي ثم يذبح ثم يحلق أو يقصر، هذا هو السنة ثم بعد هذا يتطيب ويلبس ثيابه، هذا هو الأفضل، فالذي ذبح وحلق ولبس ولم يرم لا يجوز له ذلك، لكن ليس عليه شيء لأنه جاهل، مادام جاهلاً فلا شيء عليه في اللبس، وإنما عليه إذا انتبه أن يخلع ثيابه يعني المخيطة ويرمي الجمرة هي جمرة العقبة ثم يلبس بعد ذلك، أما تقديمه الذبح على الرمي فلا يضر؛ لأن النبي سئل عليه الصلاة والسلام عمن ذبح قبل أن يرمي فقال: لا حرج عليه الصلاة والسلام، ولكن السنة يوم العيد أنه يرمي أول جمرة العقبة بسبع حصيات كل واحدة لحالها يكبر مع كل حصاة الله أكبر ويرمي، الله أكبر ويرمي، هذه السنة بحجر صغير -يشبه بعر الغنم- الذي ليس بكبير، ثم بعدما يرمي الجمرة ينحر هدياً إن كان تيسر يذبح إذا تيسر ذلك، ثم يحلق رأسه وهو الأفضل وإن قصر فلا بأس، لكن التقصير يكون من جميع الرأس، من عموم رأسه، من أطراف الشعر، بعض الناس قد يأخذ شعرات من جانب أو من جانبين لا، لا ينبغي هذا بل يعم رأسه بالتقصير كما يعمه بالحلق، ثم بعد هذا يكون قد تحلل التحلل الأول، يعني بهذا العمل يكون قد تحلل التحلل الأول، فيلبس المخيط ويغطي رأسه ويتطيب ويفعل ما يفعله الحلال ما عدا النساء، ما عدا زوجته فإنه لا يأتيها حتى يطوف، فالذي مثلاً جهل فرمى ولبس، أو ذبح ولبس، أو حلق ولبس، لا شيء عليه لأجل الجهل لا شيء عليه، لكن يخلع الثياب في وقته إذا نبه يخلع ويلبس إزاره ورداءه ويكمل، يعني يرمي إن كان ما رمى، يحلق إن كان ما حلق فإذا رمى وحلق أو قصر يلبس ثيابه بعد ذلك ويتطيب؛ لأن الرسول صلى الله عليه وسلم لما رمى ونحر وحلق طيبته عائشة عليه الصلاة والسلام وتحلل ثم ركب إلى البيت فطاف طواف الإفاضة عليه الصلاة والسلام، ويروى عنه عليه السلام أنه قال: إذا رميتم وحلقتم فقد حل لكم الطيب وكل شيء إلا النساء، فالحاصل أنه إذا رمى وحلق أو رمى وقصر حل له كل شيء حرم عليه بالإحرام إلا النساء، فإذا رمى وحلق وقصر وطاف طواف الإفاضة طواف الحج وسعى إن كان عليه سعي تم الحل، حينئذ يلبس المخيط، يتطيب، تحل له زوجته، ولو كان ما بعد رمى الرمي الأخير اللي في أيام التشريق. نعم.\nالمقدم: طيب لو رمى وحلق وطاف بالبيت ولكنه لم يذبح، هل يجوز له؟\nالشيخ: نعم يجوز له، إذا رمى وحلق وطاف ولو لم يذبح حل له كل شيء حتى النساء، يلبس المخيط، يغطي رأسه، يتطيب، يأتي زوجته؛ لأن الذبح ما يتعلق بالحل على الصحيح الذبح ما يتعلق به، لكن الأفضل أنه يسردها كما فعلها النبي ﷺ، أولاً يرمي الجمرة هذا أول شيء صباح العيد أو في آخر الليل إن كان من المستضعفين، وإن كان من الأقوياء فالسنة أن يتأخر حتى يرميها الضحى بعد طلوع الشمس الرمي، ثم ينحر الهدي سواء كان غنم أو بقر أو إبل يذبح يأكل منه ويتصدق، ثم يحلق رأسه والحلق أفضل؛ لأن النبي ﷺ دعا للمحلقين بالمغفرة والرحمة ثلاث مرات وللمقصرين واحدة، أو يقصر بدل الحلق من عموم رأسه، وبهذا يتحلل التحلل الأول، يعني يباح له المخيط وتغطية رأسه والطيب ونحو ذلك ويبقى عليه النساء، فإذا طاف طواف الإفاضة طواف الحج يوم العيد أو بعده وسعى السعي الذي عليه إن كان ما سعى مع طواف القدوم يسعى مع طواف الحج، أو كان متمتعاً فطاف وسعى لعمرته وتحلل فيسعى سعياً ثانياً لحجه، فإذا طاف وسعى حل من كل شيء حرم عليه بالإحرام من النساء وغير النساء، وهذا الترتيب هو السنة أن يرمي ثم يذبح ثم يحلق أو يقصر والحلق أفضل، ثم يطوف ويسعى إن كان له سعي هذا الترتيب المشروع، هذا هو الأفضل وهذا هو السنة، لكن لو قدم بعضها على بعض بأن نحر قبل أن يرمي، حلق قبل أن يذبح، طاف قبل أن يذبح، طاف قبل أن يرمي، طاف قبل أن يحلق لا حرج في ذلك، النبي ﷺ لما سئل عن هذا قال له رجل: يا رسول الله! نحرت قبل أن أرمي، قال: لا حرج، وقال آخر:: حلقت قبل أن أذبح، قال: لا حرج، وقال له آخر عليه الصلاة والسلام: أفضت قبل أن أرمي، قال: لا حرج،، قال الرواي -وهو ابن عباس -: فما سئل يومئذ عن شيء قدم أو أخر إلا قال: افعل ولا حرج، وهكذا جاء في حديث عبد الله بن عمرو بن العاص ، وهذا يدل على التوسعة بحمد الله وأن الأمر موسع، وهذا من إحسان الله عز وجل لعباده لأن هذا اليوم يكثر فيه النسيان، يكثر فيه الجهل، فمن رحمة الله أن جعل الأمر واسعاً، من ذبح قبل أن يرمي لا حرج، من حلق قبل أن يذبح لا حرج، من طاف قبل أن يرمي، طاف قبل أن يذبح، طاف قبل أن يحلق لا حرج، هذه كلها ... بحمد الله موسعة، إنما الأفضل والأولى أنه يرمي، ثم يذبح، ثم يحلق أو يقصر والحلق أفضل، ثم الطواف الأخير هذا هو الأفضل، ويلبس ثيابه إذا رمى وحلق، أو رمى وقصر يلبس ثيابه ولو كان ما بعد طاف، يلبس ثيابه ويغطي رأسه ويطوف بثيابه العادية بعد رميه وحلقه أو تقصيره. نعم.","link":"https://binbaz.org.sa/fatwas/5235/حكم-من-لبس-المخيط-قبل-رمي-الجمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_053/05303.mp3","categories":["اللباس والزينة","محظورات الإحرام","قضايا المرأة"]},{"id":7882,"question":"من الرياض بعث بهذه الرسالة (س. م. ش) يقول هو يسأل عن التبرج تبرج النساء يقول: ما حكم تبرج النساء عند الأجنبي في أسواق البيع، وكذلك في البيوت عند أخ الزوج وبعض الأعمام والأخوال... إلى آخره، عند من يأتي في البيت؟","title":"معنى التبرج وحكمه","answer":"الجواب: التبرج هو: إظهار المحاسن والمفاتن، كإظهار شعرها ووجهها وعنقها والسلع التي في أذنها أو حلقها من الحلي كل هذا يسمى تبرج، والله جل وعلا يقول سبحانه وتعالى: وَلا تَبَرَّجْنَ تَبَرُّجَ الْجَاهِلِيَّةِ الأُولَى [الأحزاب:33]، فسر العلماء التبرج بأنه إظهار المحاسن والمفاتن، من صدرها، ومن عنقها، ومن أذنيها وحليها، وشعرها ونحو ذلك، وهكذا الوجه في أصح قولي العلماء هو من المفاتن؛ لأن جمال المرأة وحسنها وزينتها يظهر من وجهها، فهذا كله حرام ولا يجوز وهو من التبرج الذي حرمه الله عز وجل، سواءً كان عند أخ الزوج أو عند زوج الأخت أو عند عم الزوج أو خال الزوج أو ما أشبه ذلك، وعند الأجانب الآخرين كذلك فالذي يفعله بعض النساء في الأسواق -والعياذ بالله- من التبرج والتساهل في إظهار بعض الشعر أو الوجه أو العنق أو الساق أو الرجلين أو ما أشبه ذلك كل هذا منكر وكله حرام، و المرأة عورة فإذا خرجت إلى السوق استشرفها الشيطان، فالواجب عليها الحذر والتستر والحجاب؛ لأن هذا من أسباب السلامة، والله يقول سبحانه في كتابه العظيم: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]، فالتستر والحجاب أطهر لقلوب الجميع، أطهر لقلوب الرجال وقلوب النساء، وإن كانت الآية في نساء النبي ﷺ لكنها عامة في نساء النبي وغير نساء النبي.\nفالواجب على النساء هو البعد عن التبرج وإظهار المحاسن ومن ذلك التكسر والتميع في المشية هذا من التبرج أيضاً، ومن ذلك أيضاً كشف الحجاب عن الرأس أو عن الصدر أو عن الذراع أو عن الساق أو ما أشبه ذلك مما يلبسه.. يفعل بعض الناس من الثياب القصيرة، فإن هذا من الفتن ومن البلاء ومن جملة ما حرم الله عز وجل، فالواجب الحذر من ذلك، والمرأة عورة وخطرها عظيم على نفسها وعلى غيرها، فالواجب عليها أن تكون بعيدة عن أسباب الفتنة بالتحجب ولبس الجلباب الذي يسترها عن أخي زوجها وعن عم زوجها وعن خال زوجها ونحو ذلك، وإنما المحرم ابن زوجها وأبو زوجها وجد زوجها هؤلاء محارم، أبوه وجده وأولاده من غيرها محارم بلا شك مثل أبنائها.\nلكن بعض المحارم أيضاً يخشى من شره، بعض المحارم قد يكون فاسقاً فينبغي لها التحرز من ذلك ولو كان من أبناء زوجها من غيرها وإن كان محرماً، فينبغي أن يكون عندها فطنة وعندها حذر فتكون متحشمة عند محارمها؛ لئلا تقع فتنة من بعضهم بها، قد بلغنا أنها تقع أشياء كثيرة بسبب التساهل، فقد تفتن المرأة ببعض محارمها وقد يفتن بها في هذا الزمان الذي قل فيه العلم وضعف فيه الإيمان، فقد تبتلى بأخيها وتبتلى بعمها وتبتلى بخالها وهم محارم، فينبغي لها الحذر وأن تكون متحشمة تستر كل شيء ما عدا وجهها وكفيها عند محارمها هذا هو الأحوط لها وأقرب للسلامة.\nأما غير المحارم مثل: أخي الزوج، مثل: زوج الأخت، مثل: الناس الأجانب في الأسواق، هؤلاء أجانب يجب التستر منهم في كل شيء حتى الوجه واليدين؛ لأن هذه فتنة فيجب الحذر منها، والله جل وعلا جبل الرجال على الميل للنساء وهكذا النساء، فيجب الحذر حذر الجميع من طاعة الشيطان ولهوه، نعوذ بالله من الشيطان. نعم.\nثم أمر آخر ينبغي أن يلاحظ وهو أن الواجب على الرجل أن يحذر هذه الأشياء، سواءً كان أخا الزوج أو عم الزوج يكون حذراً لا يتساهل بل يغض بصره، وإذا رأى من زوجة أخيه تساهلاً وعظها وذكرها وقال: لست محرماً فعليك أن تتستري وأن تتحجبي لا يكون متساهلاً؛ لأن الشيطان يجري من ابن آدم مجرى الدم، والناس من شره ومكائده على خطر فيجب الحذر، وكذلك إذا رأى في الأسواق من تتبرج، ومن تظهر زينتها أنكر عليها وبين أن هذا محرم ولا يتساهل في هذه الأمور، وهكذا الباعة أهل الدكاكين إذا رأوا من يتبرج ويظهر المحاسن أنكروا عليه ولو ما شرى منه يعوضهم الله خيراً، فينكر على من تساهل، ويذكره بالله وأن هذا حرام، وأن الواجب على المرأة التستر والحجاب في شرائها من الناس وفي دخولها الأسواق عليها أن تتحجب وأن تستر حتى لا يرى منها شيء؛ لأنها فتنة ولاسيما في هذا العصر الذي قل فيه الحياء والعلم وقل فيه الإيمان وضعفت فيه الغيرة.\nفيجب على المرأة أن تكون بعيدة عن أسباب الفتنة، ويجب على الرجل أن يكون بعيداً أيضاً بغضه بصره وبإنكاره على النساء المتبرجات، سواء كان في دكانه أو في الطريق أو في أي محل، هذا شأن المسلمين بينهم، التعاون على البر والتقوى، والحذر من التساهل الذي يضر الجميع، ولا حول ولا قوة إلا بالله. نعم.","link":"https://binbaz.org.sa/fatwas/5351/معنى-التبرج-وحكمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_058/05802.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":7897,"question":"أيضاً يقول: وقد تحدثنا في أول هذه الحلقة، يقول: ما حكم إسبال الثوب إذا كان لم يقصد به الكبر والعلو على الناس؟","title":"حكم إسبال الثوب بدون قصد الكبر","answer":"الشيخ: تقدم، لا يجوز، ولو ما قصد التكبر، لكن إذا قصد التكبر يكون أعظم في الإثم، وإذا ما قصده وتساهل هذا يكون آثم ولا يجوز، لأن الأحاديث الصحيحة تعمه، والرسول أطلق عليه الصلاة والسلام وعمم فوجب على المسلم أن يحذر ما نهى الله عنه ورسوله. نعم","link":"https://binbaz.org.sa/fatwas/5388/حكم-اسبال-الثوب-بدون-قصد-الكبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_061/06106.mp3","categories":["اللباس والزينة"]},{"id":7898,"question":"يقول حمدان نافي العتيبي:مقدم برنامج نور على الدرب! السلام عليكم ورحمة الله وبركاته وبعد:أرجو عرض رسالتي هذه على سماحة الشيخ: عبدالعزيز بن عبدالله بن باز الرئيس العام وفقه الله.يقول: مما لا شك فيه -يا سماحة الشيخ- أن المسلمين في رخاء دنيوي لا مثيل له، ويظهر كثير من المسلمين هذه النعمة بإسبال الملابس من ثياب وبشوت، فهل هذا العمل موافق للصواب؟ وقد يظهر هذا واضحاً في كثير من المصلين، حيث يمتد ثوبه أو ثوب أحدهم خلفه، فما حكم الإسبال في الصلاة خاصة وفي غيرها بصفة عامة؟","title":"حكم الإسبال","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: الإسبال من المحرمات العظيمة، ومن كبائر الذنوب سواء كان في الإزار أو في السراويل، أو في القميص، أو في العمامة، أو في البشت، كل ذلك محرم في حق الرجل.\nأما المرأة فلها أن تسبل، ترخي ثيابها على أقدامها؛ لأنها عورة، لا لكبر بل لستر، وأما الرجل فيلزمه رفع ثيابه فوق الكعب؛ لأنه ﷺ قال: ما أسفل من الكعبين من الإزار فهو في النار رواه البخاري في الصحيح.\nوقال عليه الصلاة والسلام: ثلاثة لا يكلمهم الله، ولا ينظر إليهم يوم القيامة، ولا يزكيهم ولهم عذاب أليم: المسبل إزاره، والمنان فيما أعطى، والمنفق سلعته بالحلف الكاذب فهذا يدل على أن هذا من الكبائر، وأن الواجب على المسلم أن يرفع ثيابه وملابسه كلها من بشت، وسراويل، وإزار يرفعها فوق الكعب، لا تنزل عن الكعب، بل من نص الساق إلى الكعب كما جاء في حديث جابر بن سليم وغيره: إزرة المؤمن من نصف ساقه ولا حرج عليه فيما بين ذلك إلى الكعب، هذا محل الملابس من نصف الساق إلى الكعب.\nأما إنزال الملابس تحت الكعبين فهذا لا يجوز، بل يجب الحذر من ذلك، وإذا كان عن خيلاء وتكبر صار أعظم في الإثم والكبيرة، قال النبي عليه الصلاة والسلام: من جر ثوبه خيلاء لم ينظر الله إليه يوم القيامة وقال عليه الصلاة والسلام: لا ينظر الله إلى من جر ثوبه بطراً .\nفالذي يرخي ثيابه ويسحبها أو يرخيها تحت الكعبين على حالين:\nأحدهما: أن يفعل ذلك تكبراً وتعاظماً وخيلاء فهذا وعيده شديد، وإثمه أكبر.\nالحال الثاني: أن يرخيها تساهلاً من غير قصد كبر، بل يتساهل، فهذا أيضاً محرم ومنكر وتعمه الأحاديث الصحيحة عن رسول الله عليه الصلاة والسلام ولا يستثنى من ذلك شيء، إلا من يغلبه الأمر، بأن كان إزاره يرتخي من غير قصد ثم يلاحظه ويرفعه فهذا معفو عنه كما جاء في قصة أبي بكر قال: يا رسول الله! إن إزاري يرتخي، فقال: لست ممن يفعله خيلاء؛ لأن أبا بكر كان يعتني به ويلاحظه.\nأما هؤلاء الذين يجرون ثيابهم فتعمهم الأحاديث، إذا أرخى قميصه وأرخى سراويله.. إزاره.. بشته يعمهم الأحاديث، وقول من قال: (إن من غير تكبر) يكون مكروهاًَ قول ضعيف، بل باطل مخالف للأحاديث الصحيحة، فإخبار النبي صلى الله عليه وسلم عمن جر ثوبه بطراً أن الله لا ينظر إليه لا يدل على إباحة ما سوى ذلك، بل يدل على أن هذا متوعد بوعيد خاص عظيم إذا جره بطراً، والباقون الذين يسحبون ثيابهم أو بشوتهم لهم وعيد آخر، أن الله لا يكلمهم، ولا ينظر إليهم، ولا يزكيهم ولهم عذاب أليم.\nفيجب على المؤمن أن يحذر ذلك، وألا يتساهل في هذه الأخلاق الذميمة، بل يرفع ثيابه في الصلاة وخارجها لا ينزلها عن الكعب أبداً، بل يجب عليه أن تكون ثيابه مرتفعة لا تنزل عن الكعب أبداً، إلى نصف الساق فأقل.\nوفي حديث جابر بن سليم قال النبي ﷺ: إياك والإسبال فإنه من المخيلة، وإن الله لا يحب المخيلة يعني: الخيلاء،؛ يعني: الكبر، فوجب على المؤمن أن يحذر هذا الخلق الذميم، وألا يتساهل، بل تكون ملابسه تنتهي إلى الكعب ولا تنزل عنه، أي ملبس كان، من ثوب.. من قميص، أو إزار، أو سراويل، أو بشت، هكذا يجب على المسلمين جميعاً، ولا يجوز التساهل في هذا الأمر.\nوإذا كان في الصلاة ففيه وعيد خاص أيضاً، يروى عنه عليه السلام أنه قال لما رأى مسبلاً في الصلاة أمره أن يعيد الوضوء، يتوضأ مرتين أو ثلاثاً ولم يأمره بقضاء الصلاة، فسئل عن ذلك، فقال: إن المسبل في صلاته لا يتقبل الله صلاته أو كما قال عليه الصلاة والسلام.\nوجاء في حديث ابن مسعود  أنه سئل: من أسبل في الصلاة؟ قال: ليس من الله في حل ولا حرمة.\nفالحاصل أن الإسبال في الصلاة يكون أشد وأقبح، فيجب الحذر من الإسبال في الصلاة والإسبال في غيرها، الصلاة صحيحة؛ لأن الرسول ﷺ ما أمره بالإعادة، لكنه قد أتى منكراً وأتى سيئة قبيحة منكرة؛ فوجب على المسلم أن يحذر ذلك، وألا يسبل لا في الصلاة ولا في خارجها، بل تكون ثيابه معتدلة مرتفعة عن الكعبين، يعني: حد الكعبين فأرفع إلى نصف الساق، هذا هو المشروع وهذا هو الواجب، ولا يجوز النزول في الملابس عن الكعبين كما أخبر النبي ﷺ بقوله: ما أسفل من الكعبين من الإزار فهو في النار وهذا وعيد عظيم، أخرجه البخاري في الصحيح رحمه الله، والأحاديث الأخرى في معناه، والله المستعان! ولا حول ولا قوة إلا بالله! ونسأل الله أن يهدي المسلمين، وأن يبصرهم بما يرضي الله عنهم، وأن يعينهم على ذلك، ولا حول ولا قوة إلا بالله.\nالمقدم: بالنسبة -يا سماحة الشيخ- للسراويل أشرتم أنها يشملها ما يشمل الإزار والثياب، لكن هناك من يقول: لا يشملها الإسبال؟ وأيضاً يقول: لا دليل عليه، فما الحكم؟\nالجواب: هذا غلط؛ لأن الرسول ﷺ أطلق قال: المسبل إزاره، والإزار من السراويل الحكم واحد؛ لأن هذا يلبس السراويل وهذا يلبس إزار، كذلك: ما أسفل من الكعبين من الإزار فهو في النار يعم هذا وهذا؛ لأن الإزار كان العرب كان الغالب عليهم الأزر، وليس الغالب عليهم السراويل، والسراويل جائزة يجوز لبسها ولبس الإزار، لكن الغالب على العرب الأزر لأنها أستر، أستر لحجم الأعضاء، وأستر للعورة من جهة الحجم، فكانت الأزر أكثر لبساً من السراويل، والسراويل كذلك إذا أرخى كمه حتى نزل عن الكعب دخل في الحديث، ولا حول ولا قوة إلا بالله. نعم.","link":"https://binbaz.org.sa/fatwas/5379/حكم-الاسبال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_061/06101.mp3","categories":["اللباس والزينة"]},{"id":7902,"question":"لديه سؤال آخر عبادي الهباش يقول: تقبيل الأب والأخ والولد في الفم في المناسبات، هل يجوز أن تفعله المرأة الصغيرة السن والكبيرة، وماذا يستحسن عمله في مثل هذه المناسبات؟","title":"حكم تقبيل المرأة للمحارم في الفم","answer":"الجواب: ما أعلم فيها نقلاً عن الرسول ﷺ، إنما كثير من أهل العلم يستحبون أن يكون التقبيل في غير الفم يقبل ابنته في خدها، وأخته كذلك، أو مع أنفها، أو مع رأسها إذا كانت كبيرة، وهي كذلك تقبل أباها مع رأسه مع أنفه ونحو ذلك.\nأما تقبيل الفم فالأولى أن يكون للزوج خاصة؛ لأن هذا قد يثير الفتنة، فالأولى أن يكون التقبيل في الفم للزوج، والسيد الذي تباح له جاريته ويقبلها هو مع فمها كالزوجة، أما تقبيل الأقارب كخالها وعمها وأبيها وأخيها تقبله مع رأسه مع أنفه يكون أولى من الفم، وهو يقبل بنته وأخته ونحو ذلك مع خدها، وإن كانت كبيرة كأمه وجدته قبلها مع جبهتها، مع أنفها تقديراً لها واحتراماً لها نعم، هذا هو الأولى. نعم.","link":"https://binbaz.org.sa/fatwas/5385/حكم-تقبيل-المراة-للمحارم-في-الفم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_061/06104.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":7918,"question":"من المرسلة منيرة وردتنا هذه الرسالة، تقول فيها: هل يجب على المرأة وضع الحناء في يديها؛ لأن البعض يقول: إن المرأة تتشبه بالرجل إذا لم تضع الحناء في يديها؟ أفتونا مأجورين.","title":"حكم استعمال المرأة للحناء","answer":"الجواب: لا شك أن تغيير يديها بالحناء مُستحبٌّ، وقد جاء في أحاديث لا تخلو من ضعفٍ، فالأولى لها أن تُغيرها بالحناء. أما كون ذلك يجب، أو كونه يحرم بقاء يدها بيضاء، فلا أعلم له أصلًا، ولكن الأفضل والأولى أن تُغيرها بالحناء حتى تكون غير مُشابهةٍ ليدي الرجل، هذا هو الأفضل والأولى؛ لأنه جاءت في هذا أحاديث؛ ولأنه من السنة المعلومة بين النساء والمعروفة في عهد النبي ﷺ وبعده: تغيير اليدين بالحناء، فهو أمرٌ معلومٌ، وهو الأولى في حق المرأة. نعم.","link":"https://binbaz.org.sa/fatwas/5413/حكم-استعمال-المراة-للحناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_063/06302.mp3","categories":["اللباس والزينة"]},{"id":7927,"question":"هذه رسالة -الله يطول عمرك- وردتنا من العراق من بغداد بعثت بها الأختان (ع. ع. ك)، و(ف. ع. ك)، وهما طالبتان في المرحلة الثانوية من الدراسة، تقول: إنها على الأبواب الجامعة، نحن نرتدي الحجاب الإسلامي ونؤدي الفرائض من صلاة وصوم وقراءة قرآن، ونريد الخير لكل الناس، لقد طلبت منا مديرة المدرسة أن نخلع الحجاب الإسلامي وأن نرتدي الزي العادي الذي هو فاضح وغير ساتر لأنوثة المرأة وإظهار الشر والسير على خطر الموديلات الغربية التي اجتاحت بلادنا اليوم، ولكننا قررنا عدم الرضوخ لمطالبها والانقطاع عن الدراسة نهائياً، ما هو رأيكم أفيدونا جزاكم الله خيراً ولكم مزيد الخير والتوفيق، وسؤالنا هو: هل الانقطاع عن مواصلة العلم قد يسبب ارتكاب الآثام عند تركنا الدراسة وشكراً؟","title":"حكم الرضوخ بخلع الحجاب لمواصلة الدراسة","answer":"الجواب: أولاً: أشكر الأختين الطالبتين غيرتهما الإسلامية وحرصهما على سلامة دينهما وعرضهما، وأسأل الله لهما المزيد من الهداية، كما أسأله للمديرة الهداية والتوفيق حتى تكون عوناً للطالبات على الخير لا على الشر، أسأل الله أن يهدي المديرات لمدارس البنات التوفيق والهداية، نسأل الله لهن التوفيق والهداية وأن يكن عوناً للطالبات على كل خير.\nأما نصيحتي للطالبتين فهي الانقطاع عن الدراسة إذا كانت لا تحصل إلا بالملابس الرديئة الفاضحة التي تدعو إليها المديرة ويدعو إليها كل متحلل من الدين وكل إنسان ضعيف الغيرة وقليل المبالاة في أمور الدين، فانقطاعهما عن الدراسة أولى من لبسهما ما لا ينبغي في الشرع وما لا يبيحه الشرع، ولا شك أن الحجاب أمر متحتم وواجب على المرأة؛ لأن الله يقول سبحانه في كتابه العظيم: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ [الأحزاب:53] ثم قال بعدها: ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]، فبين سبحانه وتعالى أن الحجاب أطهر لقلوب الرجال وقلوب النساء جميعاً، فالذي يدعو للحجاب يدعو إلى الطهرة، ويدعو إلى العفة والبعد عن أسباب الفتنة، وأما التي تدعو لخلع الحجاب فإنها تدعو إلى الفساد والنجاسة والفحش والبعد عن الطهرة والقرب من النجاسة والفساد، ولا يستوي هذا وهذا، فالدعاة إلى خلع الحجاب دعاة إلى نبذ الفضيلة.. دعاة إلى الفساد.. دعاة إلى النجاسة والخباثة.. دعاة إلى محاربة الطهرة التي دعا الله إليها سبحانه وتعالى، فنصيحتي ألا تجيبا المديرة إلى طلبها، وأن تبقيا على الحجاب، فإن أمكن إكمال الدراسة بذلك فالحمد لله، وإلا يمكن إلا بخلع الحجاب فلا حاجة إلى إكمال الدراسة في هذه الجامعة، وبالإمكان إن تيسر أن تتيسر الدراسة في مكان آخر أو تكتفيا بما حصلتما من الدراسة، ثم بالمطالعة والمذاكرة فيما بينكما وبين أمثالكما من الطيبات الطاهرات من النساء، فإن الاجتماع على الدراسة والمذاكرة في كتب العلم يفيد كثيراً وينفع كثيراً، ولاسيما من حصلت الأصل ودرست الأصول فإنها تستفيد من المطالعة والمذاكرة الخير الكثير، ولا ينبغي لها أن تجيب إلى ما حرم الله سبحانه وتعالى. نعم.","link":"https://binbaz.org.sa/fatwas/5437/حكم-الرضوخ-بخلع-الحجاب-لمواصلة-الدراسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_065/06502.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":7978,"question":"هذه رسالة وردتنا، تقول: إني الأخت المؤمنة (ح. ع. ص) من العراق، إني أشكر برنامج نور على الدرب، وأشكر سماحة العلماء، أسألكم: هل يجوز أن أرتدي عباتي أمام أبي وأمي وأخي وأزواج شقيقاتي، وأنا لم أرتد الآن عباتي أمامهم، أرجو أن تتفضلوا بالجواب على سؤالي مع جزيل الشكر لكم؟","title":"حكم ارتداء العباءة عند المحارم وغيرهم","answer":"الجواب: الواجب هو الحجاب عن الأجانب كأزواج أخواتك أيها السائلة، أما أبوك وإخوتك فهؤلاء محارم، الوالد محرم، والإخوة محارم، لكن أزواج الأخوات ليسوا محارم، زوج أختك وكذلك عم زوجك، وأخو زوجك، كلهم ليسوا محارم، أما إخوانك وأبوك وجدك وأعمامك وأخوالك فهؤلاء محارم، وهكذا أبو الزوج.. ابن الزوج، هؤلاء محارم، أما أخو الزوج، وعم الزوج، وخاله فليسوا محارم، كذلك زوج الأخت ليس محرماً، فعليك أن تتحجبي عنه بالعباءة أو بغير العباءة، بالجلباب.. بالخمار على وجهك ورأسك والقميص على بدنك، المقصود الحجاب بما تيسر من عباءة أو غيرها، هذا هو المشروع. نعم.","link":"https://binbaz.org.sa/fatwas/5534/حكم-ارتداء-العباءة-عند-المحارم-وغيرهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_072/07207.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":7980,"question":"الرسالة التي بين يدينا وردتنا من المستمعة تقول: السلام عليكم ورحمة الله وبركاته، وبعد: أنا أختكم في الإسلام (ش. ع. ح) من القصيم رياض الخبراء، وأنا متابعة لبرنامجكم اليومي نور على الدرب، وبعد: فإني أشكر فضيلة العلماء والمشايخ الذين يجيبون على الأسئلة الدينية والاجتماعية، وبعد: سمعت من برنامجكم اليومي حديث عن الرسول ﷺ أنه لعن الواشمة والمتوشمة، فسؤالي هذا أعرضه على فضيلة الشيخ عبد العزيز وفقه الله، تقول: عندما كنت في صغري وفي جهلي شاهدت بعض صديقاتي يوشمن أنفسهن فوشمت نفسي، وأنا لا أدري أنه محرم، وأنا محتارة، أرجو من فضيلتكم حل هذا السؤال، وهل علي كفارة أم لا، علماً أن الوشم لا نستطيع إخراجه من الجسم الآن؟","title":"وشمت نفسها وهي صغيرة هل عليها إثم؟","answer":"الجواب: ليس عليك شيء أيها الأخت، ما دام فعلتيه جهلاً وفي الصغر ليس عليك شيء، أما لو فعلته الكبيرة العاقلة المكلفة فعليها التوبة إلى الله سبحانه وتعالى ولا شيء عليها بعد ذلك، أما الصغيرة التي لم تكلف والجاهلة التي لم تعلم فليس عليها شيء، والوشم إذا أمكن أنه يزول بطريقة خاصة يعرفها الأطباء فلا بأس وإلا فلا حرج في ذلك والحمد لله، إنما الذي ينهى عنه أن تعمده وهي كبيرة مكلفة لا يجوز لها؛ لأن الرسول لعن من فعل ذلك عليه الصلاة والسلام، أما الجاهلة التي لم تبلغ الحلم أو لم تعرف الحكم فليس عليها شيء. نعم.\nالمقدم: في الحقيقة بعض الناس لما يرون بعض الأشخاص عليهم الوشم يتقززون منهم، بل يدعون عليهم وهم يجهلون حالة هؤلاء؛ لأنهم قد وشموا وهم صغار؟\nالشيخ: لا. الدعاء عليهم غلط، ثم الإثم على الذي وشمهم في حال صغرهم، الإثم على آبائهم وأمهاتهم إذا كانوا يعلمون أما الصغار ما عليهم شيء. نعم.","link":"https://binbaz.org.sa/fatwas/5536/وشمت-نفسها-وهي-صغيرة-هل-عليها-اثم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_072/07208.mp3","categories":["اللباس والزينة"]},{"id":8008,"question":"الرسالة التي بين يدينا والأولى وردتنا من عبد الرحمن بن سعدي بن علي الحربي من المدينة المنورة من قرية العوينة، يقول: لقد سمعنا من بعض الإخوة طلاب العلم أن لبس الذهب حرام وغير جائز للنساء، فنرجو مدى صحة هذا القول إن كان صحيح مع بيان الأدلة على ذلك؟","title":"حكم لبس النساء للذهب","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فقد ذكر هذا بعض أهل العلم، وأن لبس الذهب للنساء حرام تحريماً فيه تفصيل، ولكن الذي عليه عامة العلماء وحكاه بعضهم إجماعاً: أنه لا حرج فيه للنساء، وأن الذهب حل للنساء حرام على الذكور وهذا هو الصواب، هذا هو الحق أن الذهب حل للنساء محرم على الرجال؛ لقوله عليه الصلاة والسلام: أحل الذهب والحرير لإناث أمتي وحرم على ذكورهم ولأحاديث أخرى جاءت في الباب دالة على حله للنساء وتحريمه على الذكور، وهكذا لبس الحرير يحل للنساء دون الرجال.\nإلا ما جاء في حديث عمر من استثناء موضع أصبعين أو ثلاث أو أربع من الحرير للرجال، وقد صح عنه ﷺ أنه نهى عن خاتم الذهب للرجال، ورأى الرجل بيده خاتماً من ذهب فنزعه، وقال: يعمد أحدكم إلى جمرة من النار فيضعها في يده فالذهب والحرير محرمان على الذكور حل للإناث، هذا هو الحق والصواب، وهو كالإجماع من أهل العلم رحمة الله عليهم، ما عدا ما تقدم من استثناء موضع أصبعين أو ثلاث أو أربع من الحرير للرجال كالزر وأشباه ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/5568/حكم-لبس-النساء-للذهب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_075/07501.mp3","categories":["اللباس والزينة"]},{"id":8009,"question":"أيضاً سؤالها الثاني تقول: هل لبس الحجاب أمام الأقارب حرام لخروج اليدين والوجه كما سمعت في برنامجكم بأن لا فائدة منه إذا خرج الوجه، ولكن ماذا تفعل إذا كان الوضع هكذا عندنا نرجو التوضيح وفقكم الله لنا؟","title":"حكم لبس الحجاب","answer":"الجواب: المرأة عليها أن تحتجب عن غير محارمها كابن عمها وأشباهه وسائر الأجانب منها، عليها أن تحتجب؛ لأن الله سبحانه يقول: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] فالله سبحانه أمر بالحجاب، وأخبر أنه أطهر لقلوب الجميع، والطهارة مطلوبة للرجال والنساء جميعاً، فليس لها أن تكشف وجهها وكفيها عند زوج أختها أو عند ابن عمها أو نحو ذلك، بل تحتجب منه بالحجاب الذي يستر وجهها وكفيها؛ لأن خروج ذلك من أسباب الفتنة، والله سبحانه حين أمر بالحجاب لم يقيد ذلك بما عدا الوجه والكفين بل أطلق فعم الوجه والكفين، وهكذا قوله سبحانه: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ [النور:31] الآية، والوجه من أعظم الزينة، فلهذا وجب ستره في أصح قولي العلماء.\nوذهب بعض أهل العلم إلى أنه لا حرج في كشف الوجه والكفين لغير المحارم، واحتجوا بما قاله ابن عباس وجماعة في قوله تعالى: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنْهَا [النور:31] يروى عن ابن عباس وجماعة أن ما ظهر منها يعني: الوجه والكفين، وقالوا: إن هذا تحتاج المرأة إليه في سائر أعمالها في بيتها وغير ذلك، فإذا كان عندها أجنبي وسترت وجهها فإن هذا يشق عليها كثيراً، وهذه حجج ليست بظاهرة، بل الصواب الأخذ بما دل عليه القرآن العظيم من الحجاب، وأما الآية فهي مجملة إلا ما ظهر منها مجمل تفسره الآيات الأخرى، المجمل لا تعارض به النصوص، والنصوص صريحة في تحريم إبداء الزينة، والوجه من الزينة، فوجب ستره ووجب الحجاب عن كل من ليس بمحرم من ابن عم ومن زوج أخت ومن أخ الزوج وغير ذلك، هذا هو المعتمد وهو أصح قولي العلماء رحمة الله عليهم لما فيه من الحيطة، ولما فيه من العمل بالآيات الكريمة، ولما فيه من البعد عن أسباب الفتنة، نعم..","link":"https://binbaz.org.sa/fatwas/5580/حكم-لبس-الحجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_076/07607.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":8011,"question":"سؤالها الأخير تقول: أنا فتاة متوسطة في ديني ومع ذلك محافظة عليه أشد الحفاظ -يعني: على الحجاب- ولكن شيء واحد يزعجني هو أننا نسافر أو نذهب إلى الخارج ونلبس العباءة ونكون ملفتين للنظر، فجميع الرجال ينظرون إلينا، فهل لو ما لبسنا الحجاب على وجوهنا مع أننا لبسناه على أيدينا وأرجلنا، هل في ذلك شيء ونحن خارج المملكة؟","title":"حكم كشف الحجاب في بلاد الكفار","answer":"الجواب: الخارج والداخل سواء، الواجب الحجاب مطلقا في الخارج والداخل؛ لأنهم هناك رجال كما أن في الداخل رجال، فالواجب التستر والحجاب عن الجميع، ولا تبالون. لا ينبغي أن تبالوا باستنكارهم، فهم يأتون إلى بلادكم إلى بلاد المسلمين بزيهم ولا يبالون، فالمسلم أولى بأن يحافظ على زيه الشرعي، ولا يبالي بأعداء الله ومن كفر بالله ولا باستنكاره. نعم.","link":"https://binbaz.org.sa/fatwas/5581/حكم-كشف-الحجاب-في-بلاد-الكفار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_076/07608.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":8022,"question":"هذه رسالة وردتنا من بغداد من العراق، تقول: أختكم في الإسلام ولم تشر إلى اسمها ولا رموز، وترجو عرض هذه الرسالة على سماحتكم سماحة الشيخ عبد العزيز بن باز ، تقول: هل يجوز في الشرع أن تزيل المرأة الغير متزوجة الشعر الموجود في ساقيها وفوق الشفاه، ونحن نعلم أن مكان هذا الشعر هو تشبه بالرجل، هل يمكن إزالة الشعر الظاهر في هذه المناطق أم لا يجوز؟","title":"حكم إزالة المرأة لشعر الساقين وما فوق الشفاة","answer":"الجواب: أما في السيقان فلا أعلم فيه شيئاً.. لا أعلم فيه حرجاً، وأما الذي على الشفتين فكذلك يزال؛ لأنه شارب والشارب للرجل ففي بقائه نوع من مشابهة الرجل فإذا خرج شعر على الشفة في محل الشارب فالأولى إزالته حتى لا تكون مشابهة للرجل. نعم.","link":"https://binbaz.org.sa/fatwas/5620/حكم-ازالة-المراة-لشعر-الساقين-وما-فوق-الشفاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_078/07801.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":8025,"question":"بقية سؤالها تقول فيه: هل على المرأة أن تعمل كما أمرنا الرسول ﷺ بالعمل أقصد العمل خارج الدار؟","title":"حكم عمل المرأة خارج بيتها","answer":"الجواب: لها أن تعمل بل يجب عليها أن تعمل ما يعيشها ويحفظ عليها حياتها إذا كان ما عندها مال، ولا عندها من ينفق عليها يلزمها أن تعمل خياطة أو غير ذلك من الأعمال أو صناعة تحسنها نساجة غير ذلك، الشيء الذي تستطيعه على وجه لا تختلط به مع الرجال لا تخلو به مع الرجال في بيتها في محل مصون ليس فيه ريبة تعمل الشيء التي تستطيع من نساجة .. من خرازة .. من حدادة .. من غير ذلك من الأشياء التي تستطيعها حتى تعيش نفسها ومن تحت يدها من ذرية، أما إذا كان عندها من يقوم بحالها من أب أو زوج فليس عليها أن تعمل، بل تكتفي بهذا وتعمل في بيتها في طاعة زوجها. نعم.","link":"https://binbaz.org.sa/fatwas/5631/حكم-عمل-المراة-خارج-بيتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_078/07805.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":8038,"question":"هذه رسالة وردتنا من الرياض من العليا بعث بها المستمع عبد العزيز بن مانع الرويشدي يقول: سماحة الشيخ عبد العزيز بن عبد الله بن باز، السلام عليكم ورحمة الله وبركاته وبعد.حجيت في هذه السنة التي مضى حجها ولبست كنادر وأنا محرم، وهذه الكنادر تحت الكعب وهي شراع وفيها خياط، فهل أتيت محذوراً في إحرامي هذا وفقك الله؟","title":"حكم لبس الكنادر في الإحرام","answer":"الجواب: الذي يلبس كنادر تحت الكعبين لا حرج فيها؛ لأنها من جنس النعال في أصح قولي العلماء؛ لأن الرسول ﷺ قال للذي لم يجد النعلين: يلبس الخفين ويقطعهما أسفل من الكعبين فدل ذلك على أن المقطوعين من جنس النعال، وقد صحح كثير من أهل العلم جواز لبس الخفين من دون قطع عند فقد النعلين. فالحاصل: أن المقطوع والشيء الذي صنع تحت الكعب هذا لا بأس.. إذا كان عليه كنادر تحت الكعبين لا ....... عن الكعبين فحكمهما حكم النعال ولا حرج في ذلك. نعم.\nالمقدم: يعني: تستوي مع النعال؟\nالشيخ: نعم مثل النعال. نعم.\nالمقدم: طيب، و بالنسبة للخياطة التي فيها؟\nالشيخ: ما تضر، حتى النعال فيها خياط. نعم، حتى لو لبس إزاراً مخيوط أو رداء مخيوط، لو كان إزاره من ثلاث قطع أو أربع قطع قد خيط بعضها في بعض جاز، أو كان رداء كذلك من قطعتين أو ثلاث وقد خيط بعضها في بعض فلا بأس، الممنوع أن يلبس المخيط الذي على قدر البدن مثل القميص أو على نصف بدن كالفنيلة أو السراويل من دون عذر، وأما كون الثوب الذي هو الرداء ملفق من قطع مخيطة أو كون الإزار ملفق من قطع هذا لا يضر. نعم.\nالمقدم: طيب الفقهاء -يا سماحة الشيخ- يقولون مثلاً: لبس المخيط من محذورات الإحرام ... فيه.\nالشيخ: هذا المخيط المراد المحيط يعني، المحيط بالبدن كله أو بنصفه أو بعضو منه، هذا المراد، أما المخيط الملفق يعني قطعة ملفقة نعم هذا ما هو بداخل في مرادهم، لكن مرادهم: المخيط الذي على قدر البدن كالقميص أو على قدر عضو منه مثل القفازين .. مثل الخفين، أو على قدر النصف الأعلى مثل: الفنيلة وأشباهها، أو النصف الأسفل مثل السراويل وأشباهها. نعم.","link":"https://binbaz.org.sa/fatwas/5656/حكم-لبس-الكنادر-في-الاحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_080/08004.mp3","categories":["اللباس والزينة","محظورات الإحرام","قضايا المرأة"]},{"id":8045,"question":"سؤاله الأخير يقول: ما حكم الإسلام في الذهب للرجال، علماً بأنني أرى بعض الرجال شيوخ وشباب يركبون أسنان ذهب، أو يلبسون دبل من ذهب، علماً أنه حصل لي حادث واضطررت إلى تركيب سن من الذهب، فما حكم ذلك؟","title":"حكم استعمال الرجال للذهب من لبس وسن وساعة وغيرها","answer":"الجواب: أما التختم بالذهب أو جعل السلاسل في الأعناق من الذهب هذا لا يجوز؛ الرسول ﷺ نهى عن التختم بالذهب للرجال، ورأى رجلاً في يده خاتم من ذهب فنزعه وطرحه وقال: يعمد أحدكم إلى جمرة من النار فيضعها في يده، هذا لا يجوز، وهكذا الدبلة من الذهب لأنها كالخاتم فلا تجوز، وإنما هذا للنساء خاصة، وهكذا السلاسل التي قد يضعها بعض الشباب في أعناقهم من الذهب، هذا أيضاً منكر، هكذا الساعة من الذهب للرجال لا يجوز، لا تجوز ساعة الذهب للرجال، أما سن الذهب هذا قد يعفى عنه إذا دعت الحاجة إليه، سن الذهب ورباط الذهب لا حرج فيه.\nوإذا تيسر أسنان من غير الذهب تقوم مقامها تكفي فلا بأس، قد يكون ذلك أحوط، ولكن لا حرج في سن الذهب؛ لأنه يفعله للحاجة لا للزينة، وقد ثبت عنه ﷺ: أنه أذن لشخص أصيب أنفه أن يضع.. أن يتخذ مكانه فضة فأنتنت عليه فاتخذ مكانه ذهباً، بأمره عليه الصلاة والسلام، فدل ذلك على جواز مثل هذا الأنف من الذهب عند الحاجة، سن الذهب، رباط الذهب لا حرج. نعم.","link":"https://binbaz.org.sa/fatwas/5839/حكم-استعمال-الرجال-للذهب-من-لبس-وسن-وساعة-وغيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_081/08105.mp3","categories":["اللباس والزينة"]},{"id":8071,"question":"هذه رسالةٌ وردتنا من المستمع عواض راجي الحربي من القصيم، يقول في رسالته: أسال عن البرقع: ما حكم لبسه إذا كانت المرأة تتستر من ورائه بالغشاء؟ علمًا بأن لبسه وبيعه وشراءه أصبح شائعًا بين الكثير من النساء.","title":"حكم لبس المرأة للبرقع","answer":"الجواب: لا نعلم بأسًا في لبس البرقع، إذا كان الخرق الذي فيه بقدر العين لا بأس بذلك إن شاء الله؛ لأن هذا أمرٌ معلومٌ من قديم الزمان، والنبي ﷺ نهى المرأة المُحرمة أن تلبس النقاب، وهو يُشبه البرقع، يُنقب فيه للعينين نقبان بقدر العينين، فإذا استعملته الأنثى في حاجاتها: في طريقها، أو عند بعض مَن هو ليس محرمًا لها: كأخي زوجها، ونحو ذلك؛ فلا بأس بذلك، وإذا كان فوقه شيءٌ يستر العينين، ويحصل به قضاء حاجتها من دون أن يضرها ذلك، فهذا من باب الكمال. نعم.","link":"https://binbaz.org.sa/fatwas/5867/حكم-لبس-المراة-للبرقع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_084/08402.mp3","categories":["اللباس والزينة"]},{"id":8073,"question":"سؤاله الثاني يقول: ما رأيكم عن بعض الملابس التي يكون تطريزها مشبوهاً، ولكنها لا تضايق الجسم، ولا تبين محاسنه، فما هو رأيكم بذلك وفقنا الله وإياكم؟الشيخ: ما فهمت هذا السؤال ولا أدري......المقدم: يمكن إنه يقصد في التطريز مثلاً أنواع من الحيوانات توضع عليها أو ثقوب .....","title":"حكم الملابس المطرزة","answer":"","link":"https://binbaz.org.sa/fatwas/5868/حكم-الملابس-المطرزة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_084/08403.mp3","categories":["اللباس والزينة"]},{"id":8075,"question":"هذه رسالةٌ وردتنا من المستمع عواض راجي الحربي من القصيم، يقول في رسالته: أسال عن البرقع: ما حكم لبسه إذا كانت المرأة تتستر من ورائه بالغشاء؟ علمًا بأن لبسه وبيعه وشراءه أصبح شائعًا بين الكثير من النساء.","title":"حكم لبس المرأة للبرقع","answer":"الجواب: لا نعلم بأسًا في لبس البرقع، إذا كان الخرق الذي فيه بقدر العين لا بأس بذلك إن شاء الله؛ لأن هذا أمرٌ معلومٌ من قديم الزمان، والنبي ﷺ نهى المرأة المُحرمة أن تلبس النقاب، وهو يُشبه البرقع، يُنقب فيه للعينين نقبان بقدر العينين، فإذا استعملته الأنثى في حاجاتها: في طريقها، أو عند بعض مَن هو ليس محرمًا لها: كأخي زوجها، ونحو ذلك؛ فلا بأس بذلك، وإذا كان فوقه شيءٌ يستر العينين، ويحصل به قضاء حاجتها من دون أن يضرها ذلك، فهذا من باب الكمال. نعم.","link":"https://binbaz.org.sa/fatwas/5867/حكم-لبس-المراة-للبرقع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_084/08402.mp3","categories":["اللباس والزينة"]},{"id":8077,"question":"سؤاله الثاني يقول: ما رأيكم عن بعض الملابس التي يكون تطريزها مشبوهاً، ولكنها لا تضايق الجسم، ولا تبين محاسنه، فما هو رأيكم بذلك وفقنا الله وإياكم؟الشيخ: ما فهمت هذا السؤال ولا أدري......المقدم: يمكن إنه يقصد في التطريز مثلاً أنواع من الحيوانات توضع عليها أو ثقوب .....","title":"حكم الملابس المطرزة","answer":"","link":"https://binbaz.org.sa/fatwas/5868/حكم-الملابس-المطرزة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_084/08403.mp3","categories":["اللباس والزينة"]},{"id":8089,"question":"هذه الرسالة وردتنا من أحد المستمعين، يقول في رسالته: السلام عليكم ورحمة الله وبركاته، أما بعد، فأنا الحائرة، وأرجو أن توضحوا لي ما في رسالتي هذه، فأرجو التكرم التوضيح فيما يلي تقول في رسالتها: أنها دائمًا تستمع إلى البرنامج، وتريد أن تعرف عما يوضع على الأصابع من مناكير وما يوضع في الآونة الأخيرة من سحابات خلف الظهور ما حكمها، وهل هذه كانت مستخدمة في أول الإسلام أم لا؟","title":"حكم مناكير الأظافر للنساء ووضع سحابات الملابس من الخلف","answer":"الجواب: هذه لا نعرف لها أصلاً وإنما هي من الحوادث التي جدت في الناس، المناكير والسحابات هذه أشياء جدت في الناس ما نعلم لها أصلاً، فالمناكير ينبغي تركها؛ لأنها تغطي الأظفار وتمنع الماء فينبغي تركها، لكن إذا استعملتها المرأة وأزالتها عند الوضوء فالأمر في هذا واسع، ولكن لا ينبغي أن تبقى وقت الوضوء؛ لأنها تمنع الماء. وأما مسألة السحابات فأمرها واسع لو كانت من الأمام كان أحسن وأولى كالطريقة السابقة الجيوب تكون أمام هذا المعروف، فإذا كان الجيب من وراء، أو مضبوط لا تظهر معه العورة فلا يضرها إن شاء الله.","link":"https://binbaz.org.sa/fatwas/5888/حكم-مناكير-الاظافر-للنساء-ووضع-سحابات-الملابس-من-الخلف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_086/08604.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":8129,"question":"هذه الرسالة وردتنا من اليمن الجنوبية، من المستمعة الحائرة (ع. س. ن) تقول: إني طالبة ثاني ثانوي ومؤمنة بالله ورسوله واليوم الآخر، وأصلي وأصوم والحمد لله، وأسألكم هذا السؤال الذي يحيرني كثيراً: هو أني أدرس مع طلبة، وكذلك يدرسني مدرسون، وممنوع على الطالبات وضع المناديل على رءوسهن، مما يجعلني أفكر في ترك المدرسة، وإني لي الرغبة في تكميل التعليم، وخاصة وأني في نهاية التعليم، أفيدوني أفادكم الله. ووفقكم لما يحبه ويرضاه؟","title":"حكم تعلم الفتاة في مدرسة فيها اختلاط وتمنع الحجاب","answer":"الجواب: معلوم أن الحجاب أمر لازم، والكشف للرأس والوجه ونحو ذلك أمر ممنوع، والرأس أشد، لأن الذين قالوا: بجواز عدم الحجاب للوجه والكفين، أما الرأس فلا بد من ستره، فأيها الطالبة الواجب عليك ستره، ستر الرأس وستر الوجه وأن يكون لكي من الستر ما يعينك على القراءة، ولا تبالي بهم ولو استهزءوا ولو سخروا لا تبالي، حتى تكملي دراستك، تكونين متحجبة مستترة بما شرع الله حتى تكملي الدراسة، فإن لم تستطيعي فانفصلي والتمسي دراسة ليس فيها اختلاط، في أي مكان، فإن الاختلاط فيه خطر، وإذا كان مع التكشف صار خطره أكبر، فإذا تيسر لك التستر وتكميل الدراسة من غير ملاصقة للأولاد، بل في جانب غير ملاصق للشباب، فإن هذا لا حرج فيه ..... ..... للتكميل مع الحجاب، مع حجاب الوجه وحجاب الرأس، وأن يكون لكي عين واحدة من خلال البرقع أو شبهه، مما تنظري بعين واحدة حتى تكملي الدراسة، أو العينين يكون لها فتحتان حتى تكملي الدراسة، ثم تنتهي من هذه الدراسة، فإن لم يتيسر هذا فانفصلي، والتمسي مكاناً آخر تكملي فيه الدراسة، وأما البقاء على هذه الحالة فلا يجوز، تبقي مكشوفة الرأس مكشوفة الوجه، هذا فيه فتنة كبيرة وخطر عظيم. نعم.","link":"https://binbaz.org.sa/fatwas/5937/حكم-تعلم-الفتاة-في-مدرسة-فيها-اختلاط-وتمنع-الحجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_088/08808.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":8139,"question":"في بداية لقائنا شيخ عبد العزيز نعود إلى رسالة الأخت أم أحمد من مكة المكرمة، أختنا عرضنا جزءاً من أسئلتها في حلقة مضت، وها نحن نعود إليها في هذه الحلقة لتسأل هذا  هناك من يعارض تنظيف الساقين واليدين من الشعر الموجود بها وإذا كان هذا للزوج فهل الحكم واحد؟","title":"حكم إزالة شعر اليدين والساقين للمرأة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فلا أعلم بأساً في أخذ شعر الساقين واليدين؛ لأن هذا من الأمر المسكوت عنه، وقد جاء في الحديث عنه ﷺ أنه قال: ما سكت الله عنه فهو عافية، فاقبلوا من الله عافيته.\nأما أخذ الحاجبين وشعر الوجه فهذا هو الذي نهي عنه في أحاديث لعن النامصة والمتنمصة.\nقال أئمة اللغة النمص: أخذ شعر الحاجبين والوجه، فهذا هو الذي يمنع، إلا إذا ظهر في الوجه ما يسبب المثلة والتشويه كالشارب للمرأة أو اللحية للمرأة فهذا لا بأس بأخذه، وأما الشعر العادي في الوجه وشعر الحاجبين فهذا لا يؤخذ؛ لأن الرسول ﷺ: لعن النامصة وأخذه من النمص. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/5938/حكم-ازالة-شعر-اليدين-والساقين-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_104/10401.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":8143,"question":"سؤاله الأخير يقول فيه: إذا أسلم الكافر هل يلزمه تغيير اسمه، وإذا كان رجل كبير ولم يطهر وهو صغير؛ لأنه كان كافراً، ماذا يفعل به إذا تكرمتم؟","title":"حكم تغيير اسم من أسلم من الكفار وختانه","answer":"الجواب: إذا كان اسمه ليس بحسن شرع له تغيير اسمه بعد الإسلام، ولأن تغييره أيضاً يعطي انطباعاً واضحاً وظاهراً عن انتقاله للإسلام، وأنه قد انتقل إلى الإسلام؛ لأنه يسأل عن أسباب التغيير، فيعرف الناس أنه أسلم، وأيضاً في الغالب أن أسماءهم في الكفر قد لا تكون مناسبة، فيغير بأسماء إسلامية: كصالح وأحمد وعبد الله وعبد الرحمن ومحمد ونحو ذلك، وأما إن كان اسمه معبداً لغير الله كعبد المسيح، أو عبد الزهرة، أو عبد موسى أو عبد عيسى، هذا يجب تغييره، لأنه لا يعبد إلا لله سبحانه وتعالى، فإذا كان اسمه معبداً لغير الله وجب أن يغير، بعبد الله وبعبد الرحمن أو نحو ذلك، أما إذا كان ما عبد لغير الله، ولكن أسماء معروفة عند الكفرة ومن عادة الكفرة، فالأولى تغييرها والأفضل تغييرها إلى أسماء إسلامية.\nوأما الختان فالأفضل أن يختتن ولو كبير، لكن بواسطة الطبيب الحاذق العارف، ينبغي له أن يختتن، وجمع من أهل العلم يقولون: يجب عليه أن يختتن. بعض أهل يرى أنه يجب عليه أن يختتن، إذا كان ما فيه خطر، أما إن قال الطبيب: إن فيه خطر فلا لزوم يسقط، لكن إذا قال الطبيب: إن اختتانه لا بأس به ولا حرج فيه، ولا خطر فيه، فإنه يختتن هذا هو الذي ينبغي له، وهو سنة مؤكدة أو واجب عند جمع من أهل العلم، فإذا تيسر له الاختتان وهو كبير من غير خطر، هذا هو الأولى والأفضل والأحوط، أما إن كان فيه مشقة، أو قال بعض الأطباء: إن فيه خطر، فلا، فلا حاجة إلى ذلك ويسقط، وإن كان ختنه قد يكون سبباً لتنفيره من الإسلام، فلا يذكر ولا يبين له ذلك ويترك؛ لأن دخوله في الإسلام نعمة عظيمة ولو لم يختتن، فلا ينبغي أن يعرض له بشيء ينفره من الإسلام، لكن إذا دخل في الإسلام واستقر في الإسلام، ينظر بعد ذلك، إن تيسر ختانه بدون مشقة وبدون خطر، هذا أولى وأحوط، وإن لم يتيسر ترك. نعم.","link":"https://binbaz.org.sa/fatwas/5947/حكم-تغيير-اسم-من-اسلم-من-الكفار-وختانه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_089/08905.mp3","categories":["مسائل متفرقة في العقيدة","سنن الفطرة","اللباس والزينة"]},{"id":8151,"question":"سؤالها الثالث تقول: هل صبغ الشعر حلال أم حرام؟","title":"حكم صبغ الشعر","answer":"الجواب: صبغ الشعر إن كان بالأسود الخالص فلا يجوز للرجل والمرأة جميعاً، أما إن كان صبغه بالأصفر أو بالأخضر أو بغير ذلك فلا بأس، لكن بالأسود الخالص النبي نهى عن هذا عليه الصلاة والسلام قال: غيروا هذا الشيب وجنبوه السواد.\nفالحاصل أنه لا يجوز بالأسود الخالص لا للمرأة ولا للرجل، أما إذا غير الشيب بغير الأسود بأسود مخلوط بالحناء أو بأحمر أو بأصفر فلا بأس. نعم.","link":"https://binbaz.org.sa/fatwas/5958/حكم-صبغ-الشعر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_090/09009.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":8161,"question":"هذه رسالة وردتنا من المواطن السوري المسلم حسام الدين النشاشيـبي ومقيم في الرياض، يقول: ما هو حكم من يمنع الحجاب في دولة إسلامية؟","title":"حكم منع الحجاب في الدول الإسلامية","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه.\nأما بعد: فلا شك أن الذي يمنع الحجاب قد أخطأ وغلط، وإن كان له شبهة في بعض الناس الذين قالوا: بأن الحجاب إنما يختص بما سوى الوجه والكفين، وأن الرأس هو الذي يحجب وبقية البدن، وأما الوجه والكفان فيرى بعض أهل العلم أنه لا بأس بكشف المرأة لهما، هذا وإن كان قاله جماعة من أهل العلم، لكنه قول مرجوح، والصواب أن الحجاب واجب، وأن الوجه من أعظم الزينة، وبه فتنة كبيرة، فوجب حجبه عن غير المحرم ، ويدخل في قوله جل وعلا: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]، وفي قوله سبحانه: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ [النور:31] الآية، أما إن كان السائل أراد أن بعض الناس يمنع الحجاب، يعني: يريد كشف المرأة رأسها ومحاسنها، هذا قول ما يقوله أحد من أهل العلم، بل هو قول باطل وهو منكر من القول، ولا يجوز السمع والطاعة في هذا الأمر، بل يجب أن تحجب المرأة عن الأجانب، في رأسها وصدرها وساقها وعضدها وساعدها ونحو ذلك، إنما الخلاف في الوجه والكفين.\nومعلوم أن المرأة فتنة، وإذا خرجت استشرفها الشيطان، فإذا كانت متكشفة متبرجة صار الخطر بها أعظم وأكبر، فالواجب على أهل الإسلام هو الأخذ بحكم الإسلام، والتقيد به، ومحاربة ما خالفه. نعم.","link":"https://binbaz.org.sa/fatwas/5963/حكم-منع-الحجاب-في-الدول-الاسلامية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_091/09101.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":8179,"question":"أخونا يقول: ما حكم إطالة الإزار من غير كبر ولا مخيلة؟","title":"حكم إسبال الثياب من غير كبر ولا مخيلة","answer":"الجواب: يجب على المؤمن أن يتأدب بالآداب الشرعية وأن تكون ملابسه إلى الكعب فقط لقول المصطفى عليه الصلاة والسلام: ما أسفل من الكعبين من الإزار فهو في النار رواه البخاري في الصحيح، ولم يقل: إذا كان متكبراً أو إذا كان للخيلاء بل أطلق وعمم، وقال عليه الصلاة والسلام فيما رواه مسلم في الصحيح من حديث أبي ذر  قال: قال رسول الله ﷺ: ثلاثة لا يكلمهم الله ولا ينظر إليهم يوم القيامة ولا يزكيهم ولهم عذاب أليم: المسبل إزاره، والمنان فيما أعطى، والمنفق سلعته بالحلف الكاذب ولم يقل: إذا كان متكبراً بل قال: المسبل إزاره، والقميص والبشت من جنس الإزار وهكذا السراويل يجب أن تكون كلها فوق الكعب لا تنزل عن الكعب وإذا كان إسبالها عن كبر صار الإثم أعظم صار الإثم أعظم لقوله ﷺ: من جر ثوبه خيلاء لم ينظر الله إليه يوم القيامة وهذا لا يقيد بقية النصوص بل بقية النصوص على حالها ومن قيدها فقد غلط، هذا له شأن وهذا له شأن؛ فإذا فعلها كبراً وخيلاء صار إثمه أكبر وإذا فعلها عن تساهل صار إثمه أسهل ولكنه قد فعل محرما، ثم إرخاء الملابس وسيلة للكبر والغالب أن من أرخاها وتعمد ذلك الغالب عليه التكبر والخيلاء والتعاظم، ثم هذا الإرخاء وسيلة إلى إفساد الألبسة بالأوساخ وتعريضها للنجاسات ثم هو أيضاً نوع من الإسراف لا وجه له ولا داعي له فالواجب رفعها والحذر من إرخائها تحت الكعب وقد جاء في حديث جابر بن سليم في عند أهل السنن يقول ﷺ: إياك والإسبال فإنه من المخيلة فجعل الإسبال كله من المخيلة قصد أو لم يقصد جعل الإسبال كله من المخيلة لأنه إن لم يقصد فهو وسيلة إلى القصد ما الذي حمله واستمر على هذا تعمداً لماذا؟ لولا أن في نفسه شيئاً.\nفالحاصل أنه محرم مطلقاً هذا هو الحق والصواب، وإن لم يتكبر لكن إذا قصد التكبر كان الإثم أكبر ولا حول ولا قوة إلا بالله. نعم.\nالمقدم: جزاكم الله خيراً.\nسماحة الشيخ هناك من يبالغ في تقصير الثياب مبالغة لدرجة أنها أصبحت كالممقوتة ماذا يقول الشيخ لمثل هؤلاء؟\nالشيخ: السنة في هذا أن تكون الثياب من نصف الساق إلى الكعب فرفعها فوق النصف تركه أولى لا ينبغي لأنه وسيلة إلى التكشف ولأنه فيه نوع من الشهرة والازدراء وسحبها تحت الكعب لا يجوز ولكن بين ذلك.\nأما العورة فحدها الركبة لكن إذا أنزلها عن الركبة وجعلها إلى نصف الساق يكون أولى وأبعد عن الشهرة وأبعد عن ظهور العورة لأنه إذا كانت حول الركبة قد تظهر العورة بتساهل منه أو غفلة منه أو ريح تهب فتظهر العورة فإذا أنزلها إلى النصف كان هذا أسلم وأبعد عن ظهور العورة فإزرة المؤمن إلى نصف الساق وإذا نزله إلى الكعب فلا بأس، ولا يجوز تحت الكعب ويكره فوق النصف. نعم.","link":"https://binbaz.org.sa/fatwas/5986/حكم-اسبال-الثياب-من-غير-كبر-ولا-مخيلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_105/10507.mp3","categories":["اللباس والزينة"]},{"id":8215,"question":"هنا رسالة باعثها مجموعة من الإخوان من السودان أيضاً من بينهم الأخ: محمد عبد القادر محمد، ومحمد سر الختم إسماعيل من السودان، الإخوة يشتركون في سؤال واحد يقول: هناك من يقول بحرمة مصافحة المرأة الأجنبية، فهل هذا الكلام صحيح، ونرجو الدليل؟","title":"ما حكم مصافحة الرجال للنساء؟","answer":"الجواب: مصافحة النساء الأجنبيات لا تجوز، ولا شك في ذلك، وقد ثبت عن النبي ﷺ أنه قال: إني لا أصافح النساء، لما بايع النساء ومدت بعض النساء يدها قال: إني لا أصافح النساء، فدل ذلك على أنه لا يجوز، والمسلمون يتأسون به ﷺ في ذلك، وقالت عائشة رضي الله عنها فيما ثبت في الصحيح، لما ذكرت البيعة للنساء، قالت: ما مست يده يد امرأة قط، ما كان يبايعهن عليه الصلاة والسلام إلا بالكلام  هذه سنته عليه الصلاة والسلام عدم مصافحة النساء، لا في البيعة ولا في غيرها، والله يقول سبحانه: لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ [الأحزاب:21]، ويقول ﷺ: من رغب عن سنتي فليس مني ولأن مصافحتهن فتنة ووسيلة إلى شر، حتى قال بعض أهل العلم: إنها شر من النظر، لأن مس يدها فتنة، وقد تكون شابة، وقد تكون يدها ناعمة.\nفالحاصل: أن مس اليد فتنة، فهو من جنس النظر أو أشد من النظر وهو محرم، فيكفي المؤمن ما ثبت في السنة ولا يجوز له مخالفتها ولاسيما في مثل هذه المقامات الخطيرة، رزق الله الجميع التوفيق والهداية. نعم.\nالمقدم: الذين يصورون هذا سماحة الشيخ في صورة احتقار للمرأة ماذا يقال لهم؟\nالشيخ: هذا ليس باحتقار، ولكنه إكرام لها وصيانة لها، وصيانة للمؤمن عن أن يقع الإيقاع فيما حرم الله، فيقول لها: يا أختي أو يا فلانة، ليس المقصود احتقارك، وإنما المقصود طاعة الله ورسوله، والبعد عن أسباب الفتن، فليس لها أن تصافح أخ زوجها، ولا زوج أختها، ولا ابن عمها، ولا جارها في البيت .. ولا غيرهم ولكن تسلم عليهم بالكلام، وعليكم السلام، السلام عليك يا فلان، كيف حالك؟ مع الحجاب والتستر وعدم كشف الوجه أو غيره، تكون متسترة ومحتجبة، وتسلم بالكلام الطيب رداً وبدءاً، كيف حال؟، كيف أولادك؟ إلى غير هذا.. كما قال الله عز وجل في كتابه العظيم في سورة الأحزاب: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53].\nبين سبحانه أن هذا هو الطهارة، التحجب والبعد عن الفتنة هي الطهارة لقلوب الجميع، قال : يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلابِيبِهِنَّ ذَلِكَ أَدْنَى أَنْ يُعْرَفْنَ فَلا يُؤْذَيْنَ [الأحزاب:59]، قال سبحانه: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ [النور:31] الآية، واليد من الزينة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/6026/ما-حكم-مصافحة-الرجال-للنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_095/09512.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":8222,"question":"أخونا يثير قضية أخرى ويقول: ما حكم امرأة تعمدت زحف الثلاجة كيما تسقط الحمل من بطنها؟","title":"حكم تعمد المرأة إسقاط الحمل","answer":"الجواب: لا يجوز لها ذلك، المرأة التي بها حمل ليس لها أن تتعاطى ما يسبب سقوط الحمل، لا بحمل الثقيل ولا بالقفز من مكان إلى مكان، ولا بغير هذا من أسباب سقوط الحمل، يجب عليها أن تجتنب ذلك، إلا إذا كان في الأربعين ودعت الحاجة إلى إسقاطه -في الأربعين الأولى- فقد أجاز هذا جمع من أهل العلم بالطرق الخاصة، بطريق الطبيب، الطريق المعتاد الطريق الآمن السليم، مع أن ترك هذا أفضل وأولى؛ لكن عند الحاجة كالتي يشق عليها الحمل لأن معها أطفالاً كثيرين أو مريضة يضرها الحمل، فإذا طرحته في الأربعين بطريق سليمة مأمونة لا خطر فيها فلا بأس عند الحاجة في الأربعين الأولى، وأما بعد ذلك فليس لها أن تعمل ما يسقطه بأي وجه من الوجوه إلا في حالات خاصة إذا رآها الأطباء تضر المرأة وعليها خطر، فهذا يرجع إلى الأطباء الأمناء المختصين عند دعاء الضرورة إليه.","link":"https://binbaz.org.sa/fatwas/6029/حكم-تعمد-المراة-اسقاط-الحمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_096/09602.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":8228,"question":"أخونا يثير قضية أخرى ويقول: ما حكم امرأة تعمدت زحف الثلاجة كيما تسقط الحمل من بطنها؟","title":"حكم تعمد المرأة إسقاط الحمل","answer":"الجواب: لا يجوز لها ذلك، المرأة التي بها حمل ليس لها أن تتعاطى ما يسبب سقوط الحمل، لا بحمل الثقيل ولا بالقفز من مكان إلى مكان، ولا بغير هذا من أسباب سقوط الحمل، يجب عليها أن تجتنب ذلك، إلا إذا كان في الأربعين ودعت الحاجة إلى إسقاطه -في الأربعين الأولى- فقد أجاز هذا جمع من أهل العلم بالطرق الخاصة، بطريق الطبيب، الطريق المعتاد الطريق الآمن السليم، مع أن ترك هذا أفضل وأولى؛ لكن عند الحاجة كالتي يشق عليها الحمل لأن معها أطفالاً كثيرين أو مريضة يضرها الحمل، فإذا طرحته في الأربعين بطريق سليمة مأمونة لا خطر فيها فلا بأس عند الحاجة في الأربعين الأولى، وأما بعد ذلك فليس لها أن تعمل ما يسقطه بأي وجه من الوجوه إلا في حالات خاصة إذا رآها الأطباء تضر المرأة وعليها خطر، فهذا يرجع إلى الأطباء الأمناء المختصين عند دعاء الضرورة إليه.","link":"https://binbaz.org.sa/fatwas/6029/حكم-تعمد-المراة-اسقاط-الحمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_096/09602.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":8232,"question":"لنا مدرسة طيبة في إعداديتنا متزوجة تصوم وتصلي، وتعرف أصول الإسلام، وترتدي ملابس محتشمة، ولكن شعر رأسها ظاهر للعيان، فما قولكم لها لو تكرمتم؟","title":"حكم ستر المرأة لوجهها وشعرها","answer":"الجواب: الواجب عليها الحجاب والتستر لرأسها وجميع بدنها حتى الوجه، الصواب أنه عورة، وأن الواجب ستره عن الأجانب حال التعليم وغيره.\nأما عند النساء فلا حاجة للستر؛ لأنها من جنسهن، لكن عن الرجل الأجنبي ولو أنه أخو زوجها ولو أنه زوج أختها ولو أنه ابن عمها ولو أنه من جيرانها، يجب عليها التستر والحجاب؛ لأن الله سبحانه يقول: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] فهذا يعم جميع الرجال غير المحارم، وإذا كان هذا خطاباً لأزواج النبي ﷺ وهن من أطهر النساء ومن أكرم النساء فكيف بغيرهن؟!\nوهكذا قوله جل وعلا: يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلابِيبِهِنَّ ذَلِكَ أَدْنَى أَنْ يُعْرَفْنَ فَلا يُؤْذَيْنَ [الأحزاب:59] والجلباب: ما يوضع على الرأس يستر به الرأس وبقية البدن ومنه الوجه، فعليها أن تستر نفسها بالجلباب أو بغيره، ومن أهم ذلك شعرها وجميع بدنها؛ لأن هذا كله عورة، وهكذا الوجه فإنه عورة. نعم.","link":"https://binbaz.org.sa/fatwas/6048/حكم-ستر-المراة-لوجهها-وشعرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/46312.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":8236,"question":"تقول: إنها فتاة في التاسعة عشرة من عمرها، وهي متمسكة بأوامر الله سبحانه وتعالى من صوم وصلاة وحجاب يسترها، تربطها علاقة حب صادقة مع إحدى أخواتها، لكنها تلحظ عليها بعض الملاحظات كعدم الاهتمام بالحجاب وما أشبه ذلك، هل تستمر في صداقتها معها أو تنفصل عنها؟","title":"كيفية التعامل مع امرأة لا تهتم بالحجاب","answer":"الجواب: تستمر بالنصيحة والتوجيه، وحثها على الحجاب لعل الله يهديها بها، فإن يئست منها ولم تر فائدة في هذه النصيحة فينبغي لها أن تنفصل عنها حتى لا تنسب إليها، وحتى لا تقر المنكر، لكن مهما استطاعت أن تؤثر عليها بالنصيحة والتوجيه، أو توصي من تعظمهن أن ينصحوها وأن يتكلموا معها فإن هذا من باب التعاون على البر والتقوى كأن توصي أباها أو أخاها أو توصي بعض النساء الجيدات حتى ينصحنها، هذا من باب التعاون على الخير.\nفإذا لم تجد النصائح ولم تجد الأسباب فالانفصال عنها وعدم اتخاذها صاحبة هو الذي ينبغي. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6049/كيفية-التعامل-مع-امراة-لا-تهتم-بالحجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_097/09708.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":8240,"question":"تقول: إنها فتاة في التاسعة عشرة من عمرها، وهي متمسكة بأوامر الله سبحانه وتعالى من صوم وصلاة وحجاب يسترها، تربطها علاقة حب صادقة مع إحدى أخواتها، لكنها تلحظ عليها بعض الملاحظات كعدم الاهتمام بالحجاب وما أشبه ذلك، هل تستمر في صداقتها معها أو تنفصل عنها؟","title":"كيفية التعامل مع امرأة لا تهتم بالحجاب","answer":"الجواب: تستمر بالنصيحة والتوجيه، وحثها على الحجاب لعل الله يهديها بها، فإن يئست منها ولم تر فائدة في هذه النصيحة فينبغي لها أن تنفصل عنها حتى لا تنسب إليها، وحتى لا تقر المنكر، لكن مهما استطاعت أن تؤثر عليها بالنصيحة والتوجيه، أو توصي من تعظمهن أن ينصحوها وأن يتكلموا معها فإن هذا من باب التعاون على البر والتقوى كأن توصي أباها أو أخاها أو توصي بعض النساء الجيدات حتى ينصحنها، هذا من باب التعاون على الخير.\nفإذا لم تجد النصائح ولم تجد الأسباب فالانفصال عنها وعدم اتخاذها صاحبة هو الذي ينبغي. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6049/كيفية-التعامل-مع-امراة-لا-تهتم-بالحجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_097/09708.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":8259,"question":"هنا رسالة باعثتها إحدى الأخوات سمت نفسها تقول: سمية مصطفى من الرياض، أختنا تقول: أريد السؤال عن عمل المرأة وإقامتها بدون محرم في غير بلدها، علماً بأنني أعمل حالياً بالمملكة وفي مكان كله نساء، وأقيم في القسم الداخلي التابع للعمل وأيضاً كله نساء والحمد لله لا يوجد اختلاط أو شيء يغضب الله ، سواء في العمل أو السكن، وقد حاولت استقدام أخي كمحرم شرعي لي ولكن لم أوفق لذلك، فما حكم الشرع في وضعي الحالي وإقامتي هنا بدون محرم، علماً بأنني أولاً استخرت الله عز وجل كثيراً قبل حضوري إلى هنا، وأحسست أن الله يسر لي أموراً كثيرة لهذا الأمر، ثانياً: الوضع في بلدي من حيث الاختلاط وسوء الأخلاق في مجال العمل لا يشجع الإنسان المسلم الملتزم على الاستمرار فيه على ضوء ما ذكرت لكم، أرجو الفتوى الصحيحة وعمدوني بما ترون وفقكم الله، والسلام؟","title":"حكم عمل المرأة وإقامتها في غير بلدها دون محرم","answer":"الجواب: نسأل الله لنا ولك التوفيق وصلاح الحال، أما هذا الذي سألت فلا بأس به، إقامة المرأة في بلد من دون محرم لا ضرر فيه ولا حرج فيه، ولا سيما إذا كان ذلك لا خطر فيه، فإذا كانت بين النساء أو في عمل مصون عن الرجال مما أباح الله ، أو في قسم داخلي للنساء بين النساء، فكل هذا لا حرج فيه، إنما الممنوع السفر، لا تسافري إلا بمحرم ولا تقدمي إلا بمحرم، فإذا كنت قدمت من بلادك بدون محرم فعليك التوبة على الله والاستغفار وعدم العودة إلى مثل هذا، وإذا أردت السفر فلابد من محرم واصبري حتى يأتي المحرم، لقول النبي ﷺ: لا تسافر المرأة إلا مع ذي محرم وإذا تيسر المحرم من جهة الأقارب أو بالزواج يكون لك زوج تزوجيه ويكون زوجك محرماً لك في السفر، الأمر بيد الله، فعليك أن تعملي ما تستطيعين عند السفر حتى يحصل المحرم.\nوأما إقامتك الآن بين النساء في عمل مباح فلا حرج فيه، والحمد لله.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6069/حكم-عمل-المراة-واقامتها-في-غير-بلدها-دون-محرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_098/09809.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":8345,"question":"أختنا تسأل سؤالاً وتقول: البعض من الرجال يصبغون اللحى، وعندما يدور النقاش حول ذلك يعلل البعض بأنه ليس أسود بحتًا، ولكنه يميل إلى البنفسجي أو إلى الأخضر، فما رأيكم في ذلك؟","title":"حكم صبغ شعر الرأس واللحية بالسواد وغيره","answer":"الجواب: صبغ الشيب سنة مأمور به، يقول النبي ﷺ: إن اليهود والنصارى لا يصبغون فخالفوهم فالسنة للرجل إذا شاب والمرأة كذلك تغيير الشيب بالحمرة والصفرة، وهكذا مما بين الحمرة والسواد؛ لقوله ﷺ: غيروا هذا الشيب وجنبوه السواد أما السواد فلا يجوز، السواد الخالص ليس للرجل أن يغير به الشيب وليس للمرأة كذلك أن تغير به الشيب، إذا كان أسود خالصًا، أما إذا كان سواد فيه حمرة ليس بقانٍ فلا حرج في ذلك، فعلى الرجل وعلى المرأة أن يتحريا هذا الأمر وأن يحذرا ما حرم الله ، فقد جاءت الأحاديث الصحيحة عن رسول الله عليه الصلاة والسلام بتحريم الصبغ بالسواد، ومن جملة ذلك ما جاء في حديث ابن عباس عند أبي داود والنسائي بإسناد صحيح عن النبي ﷺ أنه قال: يكون في آخر الزمان قوم يخضبون بالسواد كحواصل الحمام لا يريحون رائحة الجنة هذا وعيد شديد، وفي قصة الصدِّيق لما جيء بأبيه مسلمًا وكان رأسه ولحيته كالثغامة بياضًا قال عليه الصلاة والسلام: غيروا هذا الشيب وجنّبوه السواد فالواجب اجتناب السواد من الرجال والنساء جميعًا، لكن إذا كان السواد ليس بقانٍ بل مخلوط بالحناء حتى صار بين الأحمر والأسود فلا بأس. نعم.","link":"https://binbaz.org.sa/fatwas/6163/حكم-صبغ-شعر-الراس-واللحية-بالسواد-وغيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_113/11302.mp3","categories":["اللباس والزينة"]},{"id":8357,"question":"لدينا جهة تساعدنا على السياحة خارج البلدان في الصيف، وأخواتي والوالدة يودون السفر إلى أوروبا، ولكن ليس معهم محرم، وهم يكونون مجموعة كبيرة مع باقي العائلة، فهل يجوز أن يسافروا ولو كثر عددهم بقولهم، علماً بأني لن أسافر معهم، أفيدونا في ذلك لو تكرمتم؟","title":"حكم سفر مجموعة من النساء بدون محرم إلى الخارج","answer":"الجواب: ليس للمرأة السفر بدون محرم، ولو تعدد وجود النساء، فليس لهن السفر إلا بمحرم ولو كن جماعة؛ لقول النبي ﷺ: لا تسافر امرأة إلا مع ذي محرم فلا يجوز للنساء السفر بدون محرم، حتى ولو لمكة، ولو للحج، ولو للعمرة، فكيف بالسفر إلى بلاد الكفرة؟! السفر إلى بلاد الكفرة محرم لا يجوز لهن السفر إلى بلاد الكفرة، ولو بالمحرم، ليس لهن السفر إلى بلاد الكفار؛ لأن في ذلك خطراً عظيماً، ولا غير النساء أيضاً، كذلك لا يجوز للشباب ولا غير الشباب من الناس أن يسافروا إلى بلاد الكفرة؛ لأن هذا فيه خطراً عظيماً وشراً كثيراً، فالواجب ترك ذلك.\nوقد قرر أهل العلم وأوضحوا رحمة الله عليهم أنه لا يجوز السفر إلى بلاد الكفار إلا لعلة وحاجة، كأن يسافر للعلاج مع كونه ممن لا يخشى عليه الخطر، أما كونه يسافر للنزهة أو للسياحة في بلاد الكفرة فلا يجوز ذلك، إلا لعالم معروف بالعلم والفضل، لا يخشى على دينه، ليدعو إلى الله وليعلم دين الله ويرشد إلى الله، هذا لا بأس به، من باب الدعوة إلى الله.\nأما سفر الجهلة من النساء ومن الشباب إلى بلاد الكفار فهذا فيه خطر عظيم، ولا يجوز، وإذا كان سفر النساء بدون محرم صار أشد في الإثم، فلا يجوز لا سفر بمحرم ولا بغير محرم إلى بلاد الكفرة، ينبغي لأهل الإسلام أن يتباعدوا عن هذا الشيء وأن يحذروه؛ لأن فيه خطراً كثيراً.\nوإن كان الآن قد تساهل الناس في هذا، وكثر منهم السفر إلى بلاد الكفرة، لكن ليس عملهم بحجة، وليس دليلاً على الجواز، بل الواجب على أهل الإسلام أن يتباعدوا عن ذلك وأن يحذروا ذلك، وأن يمنعوا نساءهم وشبابهم من السفر إلى بلاد الكفار، اللهم إلا من ضرورة لا حيلة فيها، حيث يسافر الرجل أو المرأة للعلاج، ويكون معه من يلاحظه ويشرف عليه ويعتني به، حتى لا يقع في شر، وحتى لا يقع فريسة للكفرة ودعاة الكفر.\nأما من كان عنده علم وعنده بصيرة وعنده قوة على هذا الأمر، بحيث يستطيع أن يدعو إلى الله ويرشد إلى الله ويعلم الناس الدين، ويدعو الكفار للدخول في الإسلام، فهذا لا حرج عليه إذا كان عنده علم وعنده بصيرة، ولا يخشى على نفسه الفتنة. نعم.\nالمقدم: هل من كلمة سماحة الشيخ لتلك الجهة التي تعينهم على السفر للخارج، ولاسيما ..... ؟\nالشيخ: نعم نعم ننصح جميع إخواننا أن لا يعينوا على هذا، ننصح الآباء والأمهات والإخوان وجميع الناس، ننصحهم أن لا يعينوا على السفر إلى بلاد الكفرة؛ لأن هذا السفر فيه خطر كثير، وهو معلوم، وكم من مسافرٍ رجع بغير دينه، أو رجع ناقص الدين جداً، فينبغي لجميع المسئولين وللآباء والأمهات والإخوان والأقارب أن لا يساعدوا في سفر الشباب أو النساء إلى الخارج، إلى الكفرة؛ لأن في سفر الجميع إلى بلاد الكفرة خطراً عظيماً وشراً كثيراً، نسأل الله للجميع العافية.\nالمقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/6206/حكم-سفر-مجموعة-من-النساء-بدون-محرم-الى-الخارج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_113/11314.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":8363,"question":"أختنا تثير قضية هامة، سماحة الشيخ، والواقع هي مدار حديث كثيرٍ من الناس، رجالاً ونساء، تقول: ما حكم كشف الوجه للمرأة، إذ أنني عندما سافرت إلى إحدى البلاد المجاورة لم أجد من يغطي وجهه هناك، ومن غطى وجهه يعتبر شيئاً غريباً، وينظر الناس إليه نظرة غريبة، فماذا نفعل في تلك الحالات، هدانا الله وإياكم سبيل الرشاد والهداية؟","title":"حكم كشف المرأة لوجهها في مجتمع يستغرب فيه تغطيته","answer":"الجواب: الواجب على المؤمن والمؤمنة أن يمتثلا أمر الشرع في أي مكان كان، وأن لا يغرهم أو يهولهم أو يمنعهم من تنفيذ الشرع عدم وجود المنفذين للشرع، أو وجود المستغربين والمستنكرين، فالمؤمن ينفذ أمر الله، سواء كان بين المنفذين أو بين المعرضين والغافلين، فعليك أينما كنت الحجاب عن الرجال الأجانب، كفاراً كانوا أو مسلمين، ولو استغربوا ذلك، فأنت مأمورة من جهة الله أن تنفذي أمر الله، فكما لو كنت في بلاد لا يصلون عليك أن تصلي وإن لم يصلوا، وهكذا فيما يتعلق بجميع الأوامر، فالمؤمن ينفذ أمر الله، في صومه وصلاته وغير ذلك، وإن كان من حوله لا يفعلون ذلك، أو يستغربون ذلك، هذا هو الواجب، وإذا أعرض أولئك عما أوجب الله عليهم لم يجز للمؤمن ولا المؤمنة أن يشاركهم في ذلك، أو يتأسى بهم في ذلك.\nوالحجاب أمر أمر الله به كما قال جل وعلا: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ[الأحزاب:53] ويقول سبحانه: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ [النور:31]هذا عام في بلاد المسلمين وفي بلاد الكافرين، في الداخل والخارج، فاتقي الله وعليك بتنفيذ أمر الله، وإن كنت في بلادٍ تستغرب ذلك.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6212/حكم-كشف-المراة-لوجهها-في-مجتمع-يستغرب-فيه-تغطيته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_114/11403.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":8371,"question":"من القصيم العين، وصلت رسالة من إحدى الأخوات المستمعات تقول: (د. م. ع) أختنا لها ما يقرب من ثمانية أسئلة، في سؤلها الأول تقول: ما حكم قص شعر مقدمة الرأس بالنسبة للمرأة؟","title":"حكم قص المرأة لمقدمة شعر رأسها","answer":"الجواب: لا نعلم في ذلك بأساً، وإذا كان لها زوج فعليها أن تستشير الزوج لئلا يكره ذلك منها، التخفيف في الشعر لا بأس به، بشرط أن لا يكون هذا لقصد مشابهة الكافرات، وبشرط أن لا يكون ذلك بمخالفة الزوج إذا كان لها زوج، بل ينبغي لها أن تنصاع للزوج وتستشيره في ذلك. نعم.\nالمقدم: بارك الله فيكم، على أي حال قد تصل إلى هيئة الكافرات، سماحة الشيخ، لكن ما العمدة في هذا؟\nالشيخ: أما الشيء الخفيف الذي لا يكون فيه مشابهة للكافرات، فلا بأس، أما إذا كان القصد مشابهة الكافرات، أو كان العمل يشابه الكافرات، فلا يجوز.\nالمقدم: لكن ألا يختلف ذلك بالنية أو بشيء من هذا، سماحة الشيخ؟\nالشيخ: لا بد، لا بد إذا كان النية هو، أما إذا صادف وهي ما قصدت ذلك، ولكن اعتبرته هي وزوجها من باب الجمال، ومن باب الزينة، فلا حرج في ذلك.\nالمقدم: وإن صادف ........... ؟\nالشيخ: وإن قدر أنه صادف، لكن لا ينبغي تعمد ذلك، تعمد مشابهة الكافرات.\nالمقدم: بارك الله فيكم. نعم.","link":"https://binbaz.org.sa/fatwas/6220/حكم-قص-المراة-لمقدمة-شعر-راسها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_114/11411.mp3","categories":["اللباس والزينة"]},{"id":8372,"question":"تثير سؤال فيه شيء من العجب، سماحة الشيخ، تقول: هل يجوز للمرأة أن تخيط ثيابها على نفس موديل الرجال؟","title":"ما حكم خياطة المرأة لثيابها كثياب الرجل","answer":"الجواب: هذا فيه إجمال وقد حرم الله جل وعلا مشابهة المرأة للرجال، ليس لها التشبه بالرجال، وليس للرجال التشبه بالنساء، فمجرد الخياطة بالسلك أو الأسلاك أو كيفية الخياطة، إذا كانت الكيفية غير كيفية الرجال، ما تشبه الرجال، لا حرج، كون السلك هو السلك، كون الكف هو الكف، يعني: طريقة الكف في الخياطة، لكن لا بد أن يكون هناك شيء يميز ملابس النساء عن ملابس الرجال، لا يكون فيه تشبه بالرجال بوجه من الوجوه، هذا السؤال فيه إجمال.\nفالواجب عليها أن تبتعد عن كل شيء يكون فيه التشبه، من المرأة بالرجل، في ملبسه أو في غيره، كالرجل ليس له أن يتشبه بالمرأة، والرسول عليه السلام قال: لعن الله المتشبهين من الرجال بالنساء، ولعن الله المترجلات من النساء.\nفالواجب على هذا وهذا البعد عن التشبه، الرجل لا يتشبه بها، وهي لا تتشبه به، لا في الخلق، في الكلام يعني، لا في الكلام ولا في المشي ولا في الملابس ونحوها. نعم.\nالمقدم: بارك الله فيكم، يبدو لي سماحة الشيخ، أن أختنا تسأل عن التفصيل، إذا كان تفصيل ثوب المرأة يشبه تفصيل ثوب الرجل، فإنها حينئذ تسأل عن الحكم، والواقع أن هذا موجود في بعض محلات الخياطة؟\nالشيخ: الحكم هو هذا، الحكم هو التشبه، إذا كان التفصيل يجعلها متشبهةً بالرجل، حرم ذلك؛ لأن هذا .......... ما نعرف مقتضاه من جهة التشبه، فإن كان .... هذا التفصيل يجعلها متشبهةً بالرجل ، ويجعل لباسها من جنس لباس الرجل، لم يجز، وإن كان لا يقتضي ذلك، فلا بأس، الحكم يدور مع التشبه. نعم.\nالمقدم: بارك الله فيكم، هو الواقع الفارق في القماش فقط فضيلة الشيخ، يعني: إذا رأيت هذا الثوب المفصل فهو تفصيل ثوب رجلٍ إلا أنه يختلف بأن هذا القماش لا يلبسه إلا النساء، وذلك القماش لا يلبسه إلا الرجال فقط؟\nالشيخ: ما نعلم شيء يعني واضح في هذا.. المهم أنه لا يكون مشبهاً للرجل، لا يكون هذا اللباس مشبهاً للرجل، وإذا قدرنا أن هناك جماعةً في قريةٍ أو في أي مكان، لهم ملابس خاصة للرجال، وللنساء ملابس خاصة، حرم على المرأة أن تلبس لباسهم، وحرم على الرجل أن يلبس لباسهن، هذا هو الواجب للبعد عن التشبه. نعم.","link":"https://binbaz.org.sa/fatwas/6221/ما-حكم-خياطة-المراة-لثيابها-كثياب-الرجل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_114/11412.mp3","categories":["اللباس والزينة"]},{"id":8373,"question":"هل يجوز إزالة الشعر الذي بين الحاجبين؟","title":"حكم إزالة الشعر الذي بين الحاجبين","answer":"الجواب: ليس من الحاجبين، هذا ليس من الحاجبين، إن أزيل فلا بأس، وبعض أهل العلم يكره ذلك. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6222/حكم-ازالة-الشعر-الذي-بين-الحاجبين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_114/11413.mp3","categories":["اللباس والزينة"]},{"id":8375,"question":"هل يصح للمرأة أن تصبغ أظافر أرجلها بالحناء، علماً بأنها عندما تخرج من المنزل تلبس الشراب، فما رأيكم؟","title":"حكم صبغ المرأة أظافر رجليها بالحناء","answer":"الجواب: لا بأس بذلك أن تصبغ رجليها أو أظفارها مادام ذلك في بيتها أو بين نسائها، وإذا كان عند الرجال تلبس الجوارب، لا بأس. نعم.","link":"https://binbaz.org.sa/fatwas/6224/حكم-صبغ-المراة-اظافر-رجليها-بالحناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_114/11415.mp3","categories":["اللباس والزينة"]},{"id":8402,"question":"أختنا تسأل سؤال سبق وأن طرح سماحة الشيخ، تقول: إنه في بعض المستشفيات يقوم بولادة الحريم وكشف عوراتهن دكتور رجل، فهل في ذلك إثم؟ وهل هو حرام في الشريعة؟ وهل يلحق المرأة إثم أفيدونا أفادكم الله؟","title":"حكم توليد الرجال للنساء","answer":"الجواب: الواجب على المسئولين أن يهيئوا لهذا نساء، وقد سبق التفاهم معهم في ذلك، فوعدوا خيراً وأنهم حريصون على تعليم طبيبات، وأنهم سوف يبذلون وقد بذلوا الجهد الكثير في أن يتولى توليد النساء النساء، هذا هو الواجب، فإذا لم يتيسر ذلك، وخيف على المرأة من عدم تولي الرجل توليدها، وأنه يخشى عليها من ذلك فلا حرج: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] إذا دعت الحاجة والضرورة إلى ذلك فلا بأس، وإلا فالواجب أن لا يولدها إلا النساء، فإن لم يوجد النساء فلا حاجة إلى التوليد؛ لأن الناس مضى عليهم دهور طويلة ما يحتاجون إلى توليد الأطباء، تلد المرأة في بيتها والحمد لله، لكن إذا خيف عليها أو خشي عليها، فتوليد الرجال لها لا بأس به عند الحاجة. نعم.","link":"https://binbaz.org.sa/fatwas/6286/حكم-توليد-الرجال-للنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_117/11707.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":8403,"question":"هل في استعمال المرأة للمناكير التي تطلى بها الأظافر، هل في ذلك إثم؟","title":"حكم استعمال المرأة للمناكير التي تطلى بها الأظافر","answer":"الجواب: لا نعلم شيئاً في هذا، لكن تركها أولى؛ لعدم الحاجة إليها؛ ولأنها قد تحول بين المرأة وبين الوضوء الشرعي، لأنها قد تنسى أو تجهل، فالحاصل أن تركها أولى، والاكتفاء بالحناء الذي درج عليه الأوائل أولى، فإن دعت الحاجة إلى ذلك أو استعملت ذلك، فإنها تزيلها عند الوضوء، تجعلها في وقت العادة وقت الحيض أو النفاس، أو تجعلها في غير ذلك، لكن تزيلها عند الوضوء؛ لأنها فيما بلغنا لها جرم، وتحول بين الماء وبين الوصول إلى البشرة؛ لأن لها جسماً، فالواجب على المرأة أن تزيل ذلك عند الوضوء، فإذا جعلته وقت الطهارة فلا بأس. نعم.","link":"https://binbaz.org.sa/fatwas/6287/حكم-استعمال-المراة-للمناكير-التي-تطلى-بها-الاظافر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_117/11709.mp3","categories":["اللباس والزينة"]},{"id":8417,"question":"لي صديقة أحبها جداً وهي مثل أختي، وهي ملتزمة بأمور دينها، تؤدي الصلاة، وتصوم شهر رمضان، وتبتعد عن أمور الشر، وتتحلى بالأخلاق السامية، إلا أنها رغم إصراري عليها لتلبس الحجاب لم تلبسه حتى الآن، كيف تنصحونني وإياها جزاكم الله خيراً؟","title":"الحث على العناية بالحجاب","answer":"الجواب: الواجب على كل مسلمة العناية بالحجاب؛ لأن الله جل وعلا أمر بذلك، يقول سبحانه في كتابه العظيم لأزواج النبي ﷺ: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] فإذا كان أزواج النبي ﷺ يؤمرن بالحجاب وهن خيرة النساء، فغيرهن من باب أولى، والشيطان على غيرهن أجرأ ولهذا قال سبحانه: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] وإذا كان الحجاب أطهر لقلوب المؤمنين في عهد النبي ﷺ، وأطهر لقلوب المؤمنات في عهد النبي صلى الله عليه وسلم، ومنهن أزواجه عليه الصلاة والسلام، فالطهارة لمن بعدهم أشد وأشد، فالحاجة إلى الطهارة في قلوب من بعدهم أشد وأشد؛ لأن أولئك الأخيار أقوى إيماناً وأكمل إيماناً، فإذا كان الحجاب أطهر لقلوبهم فهو أطهر لقلوب من بعدهم أيضاً. نعم.\nوكذلك قوله جل وعلا: يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلابِيبِهِنَّ ذَلِكَ أَدْنَى أَنْ يُعْرَفْنَ فَلا يُؤْذَيْنَ [الأحزاب:59] والجلباب يغطى به البدن كله، الرأس، والوجه، والبدن، وهكذا قوله سبحانه وتعالى في حق النساء: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ أَوْ أَبْنَائِهِنَّ أَوْ أَبْنَاءِ بُعُولَتِهِنَّ... [النور:31] الآية، فدل ذلك على أن الزينة يجب أن تغطى وتحجب عن الأجانب؛ وإنما تبدي المرأة زينتها لمحارمها، كزوجها وأبيه وابنه وأبيها وأخيها وعمها ونحو ذلك. ثم أيضاً أمر آخر وهو أن إظهار الزينة من أسباب الفتنة، فينبغي للمؤمنة أن تبتعد عن أسباب الفتنة. نعم.","link":"https://binbaz.org.sa/fatwas/6301/الحث-على-العناية-بالحجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_118/11808.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":8419,"question":"أسئلتها الأخيرة تقول فيها: هل يصح قص شعر المرأة؟ وما حكم الحناء؟","title":"حكم قص المرأة لشعرها وتزينها بالحناء","answer":"الجواب: قص الشعر إذا كان للتخفيف، لا للتشبه بالكافرات، بل لمجرد التخفيف فلا بأس بذلك، والحناء لا بأس به، هو من زينة المرأة، فالمشروع لها والأفضل لها أن تستعمله حتى تبتعد عن مشابهة أيدي الرجال. نعم.","link":"https://binbaz.org.sa/fatwas/6303/حكم-قص-المراة-لشعرها-وتزينها-بالحناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_118/11810.mp3","categories":["اللباس والزينة"]},{"id":8441,"question":"من جمهورية مصر العربية باعث رسالة أخونا مستور هارون سليمان من قرية النزيلة، أخونا يقول: إننا نسكن في صحراء، والناس كلهم بدو، وهناك النساء تلبس ثياب تغطي العورة ولكنها قصيرة، وبعض الأحيان ضيقة، بم تنصحون هؤلاء؟","title":"حقيقة الملابس الساترة للمرأة عن الأجانب","answer":"الجواب: لا شك أن الواجب على النساء التستر، والبعد من التبرج، وإظهار المحاسن، يقول الله : وَقَرْنَ فِي بُيُوتِكُنَّ وَلا تَبَرَّجْنَ تَبَرُّجَ الْجَاهِلِيَّةِ الأُولَى [الأحزاب:33]، قال علماء التفسير: معنى التبرج: إظهار المحاسن والمفاتن، فالواجب على المرأة أن تكون مستترة متحجبة بعيدة عن الفتنة، كما قال الله : وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ[الأحزاب:53]، فأطهر لقلوب الرجال وقلوب النساء التستر والتحجب من جهة النساء، وعدم التبرج حتى لا تفتن ولا تفتن، وقال : وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ ... [النور:31] الآية، وقال : يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلابِيبِهِنَّ ذَلِكَ أَدْنَى أَنْ يُعْرَفْنَ فَلا يُؤْذَيْنَ [الأحزاب:59]، والجلباب: شيء تضعه المرأة فوق رأسها أو على جميع بدنها فوق ثيابها الخاصة؛ للستر والبعد عن الفتنة، هكذا ينبغي للمرأة سواء كانت بدوية أو حضرية، إفريقية أو غير ذلك، الواجب عليها أن تلتزم بحكم الإسلام، وأن تجتهد في ستر عورتها، وأن تكون ثيابها وسطاً لا ضيقة تبين حجم العورة، ولا واسعة تبين العورة ولكن وسط، خير الأمور أوساطها، تكون وسطاً، وتكون مستورة الوجه والرأس والبدن كله عند الأجناب، عند وجود الأجنبي من الرجال ليس محرماً لها، وهكذا في صلاتها تستر جميع بدنها في صلاتها ما عدا الوجه فلا بأس بكشفه في الصلاة، بل مشروع لها أن تكشفه في الصلاة إذا لم يكن عندها أجنبي، أما الكفان فإن كشفتهما فلا بأس، وإن غطتهما فهو أفضل، وأما القدمان فيستران في الصلاة عند جمهور أهل العلم، تسترهما بإرخاء الثياب إذا كانت طويلة، أو بلبس الجوارب في رجليها حال أداء الصلاة، رزق الله الجميع التوفيق والهداية. نعم.","link":"https://binbaz.org.sa/fatwas/6325/حقيقة-الملابس-الساترة-للمراة-عن-الاجانب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_120/12006.mp3","categories":["اللباس والزينة"]},{"id":8444,"question":"تسأل أختنا سماحة الشيخ: الواجب شرعاً هل هو النقاب أو الخمار أو الحجاب؟","title":"معنى النقاب والخمار والحجاب وما يجزئ المرأة منها","answer":"الجواب: كله معناه واحد، الحجاب يكون بالخمار، ويكون بالنقاب، ويكون بالجلباب، أو يكون بغير .....، أو يكون من وراء الباب، في حجرة وهو في حجرة، أو في خيمة وهو في خيمة، أو من خارج الخيمة، المقصود سترها نفسها عن الأجنبي ولو بالخمار الذي تلقيه على رأسها ووجهها، أو بالجلباب الذي تلقيه على وجهها ورأسها، أو بالنقاب الذي لا تبدو منه إلا العين أو العينان والبقية مستورة الوجه كله مستور ما عدا العين حتى تنظر، أو العينين حتى تنظر. نعم.\nالمقدم: وخطر العين سماحة الشيخ؟\nالشيخ: إيه لكنها أسهل من الكشف ..... روي عن ابن عباس أنه قال: لا مانع من العين ... رواه علي بن أبي طلحة عن ابن عباس قال: تبدي عيناً واحدة فإذا أبدت عيناً واحدة أو العينين لا محظور إن شاء الله. نعم.","link":"https://binbaz.org.sa/fatwas/6328/معنى-النقاب-والخمار-والحجاب-وما-يجزى-المراة-منها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_120/12009.mp3","categories":["اللباس والزينة"]},{"id":8448,"question":"نعود في بداية لقائنا سماحة الشيخ إلى رسالة الأخت: (ن. ع. غ) من الرياض، أختنا تسأل في هذه الحلقة وتقول: توجد لدينا خادمة مسيحية، هل يجب علينا التحجب عنها أم لا؟","title":"حكم احتجاب المرأة المسلمة من الكافرات","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: أولاً: يجب أن نعلم أنه لا يجوز استقدام الكفرة إلى هذه الجزيرة، لا من النصارى ولا من غير النصارى كـالبوذيين وغيرهم، والهندوس ونحو ذلك؛ لأن الرسول ﷺ أمر بإخراج الكفرة من هذه الجزيرة، وأوصى عند موته ﷺ بإخراجهم من هذه الجزيرة وهي: المملكة العربية السعودية واليمن ودول الخليج، كل هذه جزيرة عربية، فالواجب: أن لا يقر فيها الكفرة، من اليهود والنصارى والبوذيين والشيوعيين والوثنيين جميع من يحكم الإسلام بأنه كافر، لا يجوز بقاؤه ولا إقراره في هذه الجزيرة، ولا استقدامه إليها، إلا عند الضرورة القصوى التي يراها ولي الأمر ضرورة لأمر عارض ثم يرجع إلى بلده، كالبريد الذي يأتي من دولة كافرة، وأشباه ذلك مما قد تدعو الضرورة إلى مجيئه إلى هذه المملكة، وشبهها كاليمن ودول الخليج.\nأما استقدامهم ليقيموا هنا، أو ليخدموا هنا، أو ليعملوا هنا، فلا يجوز استقدامهم، بل يجب أن يكتفى بالمسلمين في كل مكان، وأن تكون المادة التي تصرف لهؤلاء الكفار تصرف لغيرهم من المسلمين، وأن ينتقى من المسلمين من يقوم بالأعمال حسب الطاقة والإمكان، على المحتاجين إلى هؤلاء المشركين أن ينظروا في البلاد التي فيها المسلمون، ويستقدموا من المسلمين ما يغنيهم عن هؤلاء الكفرة، وأن يختاروا من المسلمين من كان أبعد عن البدع والشر، حتى لا يستقدم إلا من هو طيب ينفع البلاد ولا يضرها، هذا هو الواجب، لكن من بلي بشيء من هؤلاء الكفرة كـالنصارى ؛ فإنه يحرص على التخلص منهم وردهم إلى بلادهم بأسرع وقت حسب الإمكان، ولا يجب على المرأة أن تحتجب عن النصرانية أو البوذية ونحوها على الصحيح، ذهب بعض أهل العلم إلى أن المسلمة تحتجب عن الكافرات؛ لقوله سبحانه في سورة النور: أَوْ نِسَائِهِنَّ [النور:31] لما ذكر من تمنع من إبداء الزينة له قال: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّاا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ أَوْ أَبْنَائِهِنَّ أَوْ أَبْنَاءِ بُعُولَتِهِنَّ أَوْ إِخْوَانِهِنَّ أَوْ بَنِي إِخْوَانِهِنَّ أَوْ بَنِي أَخَوَاتِهِنَّ أَوْ نِسَائِهِنَّ [النور:31]، قال بعض أهل العلم: نسائهن، يعني: المؤمنات، فإذا كان النساء كافرات فإن المؤمنة لا تبدي زينتها لها، وقال آخرون: المراد بنسائهن يعني: جنس النساء ليس المراد هنا الخاص جنس النساء مؤمنة أو غير مؤمنة، وهذا هو الأرجح أنه ليس على المرأة المؤمنة أن تحتجب من الكافرة.\nوكان اليهوديات في عهد النبي ﷺ في المدينة، وهكذا الوثنيات كن يدخلن على أزواج النبي ﷺ، ولم ينقل: أنهن كن يحتجبن عنهن، ولو كان هذا واقعاً من أزواج النبي صلى الله عليه وسلم أو من غيرهن لنقل، فإن الصحابة لم يتركوا شيئاً إلا نقلوه رضي الله عنهم وأرضاهم، فهذا هو المختار وهو الأرجح: أنه لا يلزم المؤمنة أن تحتجب عن المرأة الكافرة، فلها أن ترى منها وجهها وشعرها كالمرأة المسلمة، هذا هو الصواب وهذا هو الأرجح، والله المستعان. نعم.","link":"https://binbaz.org.sa/fatwas/6332/حكم-احتجاب-المراة-المسلمة-من-الكافرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_121/12101.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":8454,"question":"شيخ عبدالعزيز أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من جدة باعثها أحد الإخوة من هناك يقول: خالد (ي. ع. عيسى ) صندوق بريد ستة عشر ألف وستمائة وخمسة أخونا مع رسالته أرفق صورة من إحدى صفحات بعض المجلات، يقول: إنها مجلة التضامن، هذه المجلة نشرت بعض الكلام عن المرأة، وأيضاً فيها تطاول على الطريقة الصحيحة التي ينبغي أن تكون عليها المرأة، من ذلكم الكلام الذي نشرته المجلة -ما نقله أخونا بالحرف الواحد- يمارس الفكر السلفي -كما في المجلة تحت عنوان (طبيعة المرأة)- مجموعة من الازدواجيات أولها: ازدواجية التحرر والعبودية، فامتدح دور المرأة العائلي ثم وصفها بالجوهرة المصونة، وربة الصون والعفاف، هذه العبارات من الإطراء والتمجيد والتي تقدم للمرأة باعتبار أنها قمة التحرر في أسرة يحتاج إليها المقصد الحقيقي من ورائها عزل المرأة في إطار المنزل فقط، ويرجو من سماحة الشيخ التوجيه فيما ينشر في مثل هذه المجلات؟","title":"الرد على دعاة تحرير المرأة","answer":"الجواب: نعم، بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nهذا الكلام فيه نظر وإجمال يحتاج إلى مراجعة المجلة والنظر فيما كتبه الكاتب، ولا ريب أن المرأة أصلها حرة كسائر النساء وكسائر الرجال، الأصل الحرية في جميع بني آدم، ليس الرق وإنما هم عبيد لله عبوديتهم لله وحده سبحانه وتعالى، وليسوا عبيداً للناس هذا هو الأصل.\nوأما كونها ينبغي أن تصان في بيتها وأن تبتعد عن اختلاطها بالرجال فهذا إذا كان أراده الكاتب المعنى الحق، ينبغي أن تصون نفسها وأن تبتعد عن اختلاطها بالرجال إلا في الحاجة التي أباح الله لها ذلك، كصلاتها في المسجد خلف الرجال، وهي متحجبة مصونة وخروجها للسوق لحاجاتها متحجبة مصونة تقضي حاجتها وترجع، وما أشبه ذلك من الاختلاط الذي لا ريبة فيه ولا شر فيه.\nأما إن كان أراد شيئاً آخر فينظر فيما كتبه وينبه إن شاء الله المسئولون عن الصحيفة عما يجب الحذر منه. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/6431/الرد-على-دعاة-تحرير-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_123/12301.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":8470,"question":"أخونا (ع. س) أيضاً يسأل -سماحة الشيخ- ويقول: ما رأيكم في حجاب كبيرات السن هل هو كغيرهن أو لا؟","title":"حجاب المرأة الكبيرة السن","answer":"الجواب: الكبيرات في السن قد سامحهن الله وعفا عنهن، إذا كن لا يرجون النكاح ولا يتبرجن بالزينة، مثلما قال سبحانه وتعالى: وَالْقَوَاعِدُ مِنَ النِّسَاءِ اللَّاتِي لا يَرْجُونَ نِكَاحًا فَلَيْسَ عَلَيْهِنَّ جُنَاحٌ أَنْ يَضَعْنَ ثِيَابَهُنَّ غَيْرَ مُتَبَرِّجَاتٍ بِزِينَةٍ وَأَنْ يَسْتَعْفِفْنَ خَيْرٌ لَهُنَّ وَاللَّهُ سَمِيعٌ عَلِيمٌ [النور:60] فالقواعد: هن العجائز كبيرات السن اللَّاتِي لا يَرْجُونَ نِكَاحًا ما عندهن رغبة في النكاح لكبر السن وضعف القوة، قال الله: فَلَيْسَ عَلَيْهِنَّ جُنَاحٌ يعني: حرج أَنْ يَضَعْنَ ثِيَابَهُنَّ يعني: أن يكشفن عن وجوههن وأيديهن لأنهن لا رغبة للناس فيهن ولا طمع للرجال فيهن، بشرط أن لا يكن متبرجات بزينة، بشرط أن لا يكن يتبرجن بالزينة، أي: يلبسن الملابس الجميلة، ويعتنين بهذا الأمر كالكحل وتحسين الوجه، ولبس الملابس الجميلة، إذا كن يفعلن ذلك فعليهن جناح ليس لهن الكشف، وعليهن التستر والحجاب.\nأما إذا كن لا يتبرجن بالزينة بل أمرهن عادي، الوجه عادي واللباس عادية، اللباس عادي فلا بأس بالكشف لعدم الرغبة فيهن، ولكن عدم الكشف أفضل حتى ولو كن كبيرات ولو كن غير متبرجات، ولو كن لا يرجون النكاح كونهن يتعففن أولى، ولهذا قال: وَأَنْ يَسْتَعْفِفْنَ خَيْرٌ لَهُنَّ يعني: وأن يستعففن ولا يظهرن شيئاً إلا ما أباح الله إظهاره كالملابس الظاهرة هذا لا بأس به، فهذا أفضل لهن وخير لهن. نعم.","link":"https://binbaz.org.sa/fatwas/6487/حجاب-المراة-الكبيرة-السن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_124/12404.mp3","categories":["اللباس والزينة"]},{"id":8479,"question":"هنا رسالة باعثها أحد الإخوة يقول أبو معاوية من السودان أخونا يسأل سؤالين:في سؤاله الأول يقول: أرجو أن تفيدونا عن مسألة الشلوخ وهي علامة تعمل بالموسى على الوجه تمييزاً عن كل قبيلة من الأخرى، هل هي حلال أم حرام؟","title":"الوشم محرم وتغيير لخلق الله","answer":"","link":"https://binbaz.org.sa/fatwas/6538/الوشم-محرم-وتغيير-لخلق-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_125/12506.mp3","categories":["اللباس والزينة"]},{"id":8491,"question":"تقول: نسمع أن هناك بعض العطور تحتوي على شيء من الكحول كيف تنصحوننا؟","title":"حكم العطور التي يوجد بها نسبة من الكحول","answer":"الجواب: نسمع هذا أيضاً من بعض الناس، والقاعدة حل العطور والأطياب التي بين الناس إلا ما علم أن به ما يمنعه من مسكر أو نجاسة ونحو ذلك، وإلا فالأصل حل العطور التي بين الناس كدهن العود ودهن الورد والعنبر والمسك وغير ذلك، فإذا علم الإنسان أن هناك عطراً فيه ما يمنع استعماله من مسكر أو نجاسة ترك ذلك.\nومن ذلك الكالونيا فإنها ثبت عندنا بشهادة الأطباء أنها لا تخلو من المسكر، أن فيها شيئاً كبيراً من الإسبيرتو وهو مسكر فينبغي تركها، إلا إذا وجدت أنواع سليمة فلا بأس، والذي نعلمه الآن وذكروا لنا الأطباء أن الكالونيا الموجودة لا تخلو من المسكر، وبعضها يكون فيه ثمانون في المائة من المسكر، فينبغي تركها والحذر منها وعدم استعمالها، لا بعد الطعام ولا في غير ذلك، وفيما أوجد الله من الأطياب غنية عنها والحمد لله.\nوهكذا كل عطر أو شراب فيه مسكر يجب تركه، والقاعدة أن ما أسكر كثيره فقليله حرام كما قاله النبي ﷺ، يقول عليه الصلاة والسلام: ما أسكر كثيره فقليله حرام فكل شيء علم أن كثيره يسكر فإن شربه وأكله ممنوع، ولو لم يسكر إذا كان كثيره يسكر، عملاً بهذه القاعدة التي بينها الرسول ﷺ. نعم.","link":"https://binbaz.org.sa/fatwas/6550/حكم-العطور-التي-يوجد-بها-نسبة-من-الكحول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_126/12605.mp3","categories":["اللباس والزينة"]},{"id":8492,"question":"أختنا تسأل سماحة الشيخ وتقول: المسك ودهن العود وغيره إذا استخدمتها المرأة فإن رائحتها واضحة، فما حكم استعمالها خاصة إذا خرجت المرأة من منزلها، وهل يعد تكريم الزائرات بتبخيرهن وتعطيرهن وترجو التوجيه؟","title":"حكم الطيب للمرأة إذا خرجت من البيت","answer":"","link":"https://binbaz.org.sa/fatwas/6551/حكم-الطيب-للمراة-اذا-خرجت-من-البيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_126/12606.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":8499,"question":"أخت لنا من المغرب تقول عائشة تسأل مجموعة من الأسئلة سماحة الشيخ:ففي سؤالها الأول: علام تجب تغطية الوجه؟","title":"ممن تغطي المرأة وجهها؟","answer":"الجواب: يجب أن يغطى الوجه عن الرجال الأجانب في أصح قولي العلماء، سواء كان الأجنبي ابن عم أو ابن خال أو من الجيران أو غيرهم، لقول الله سبحانه يخاطب المسلمين في عهده ﷺ ومن بعدهم: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] وهذا يعم أزواج النبي ﷺ وغيرهن من المؤمنات كما قال سبحانه: يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكََ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلابِيبِهِنَّ ذَلِكَ أَدْنَى أَنْ يُعْرَفْنَ فَلا يُؤْذَيْنَ [الأحزاب:59] (والجلابيب): ما يوضع على الرأس والبدن من الجلباب من اللحاف الذي يغطى به الرأس والوجه والبدن، وما يوضع على الرأس يقال له: الخمار، فهي تغطي وجهها بالجلباب أو بالخمار؛ لأنه معظم زينتها وأهم زينتها ويعرف به جمالها أو دمامتها هذا هو الصواب، وقال جل وعلا: وَقُلْ لِلْمُؤْمِنَاتِ يَغْضُضْنَ مِنْ أَبْصَارِهِنَّ وَيَحْفَظْنَ فُرُوجَهُنَّ وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنْهَا وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَى جُيُوبِهِنَّ وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ [النور:31] الآية.\nفقوله إِلَّا مَا ظَهَرَ مِنْهَا فسره ابن مسعود وجماعة: بالملابس الظاهرة وفسره قوم: بالوجه والكفين، ولكن التفسير الأول أصح؛ لأنه موافق للأدلة الشرعية.\nوحمل بعضهم قول من فسره بالوجه والكفين على أن هذا كان قبل الحجاب، أما بعد الحجاب فيجب ستر الوجه والكفين في جميع الأحوال عن الرجل الأجنبي.\nثم قال سبحانه: وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَى جُيُوبِهِنَّ [النور:31] (والخمر): جمع خمار، وهو ما يستر به الرأس وما حوله، سمي خماراً لأنه يستر ما وراءه كما سميت الخمر خمراً لأنها تستر العقول وتغيرها، فالخمار يستر الوجه؛ ولهذا قال: وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَىى جُيُوبِهِنَّ [النور:31] (والجيب): الشق الذي في الثوب يخرج منه الرأس فإذا ألقت الخمار على وجهها ورأسها فقد سترت الجيب، وإذا كان هناك شيء من الصدر سترته أيضاً ثم قال: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ [النور:31] والزينة: تشمل الوجه تشمل الرأس تشمل بقية البدن، فيجب عليها أن تغطي هذه الزينة حتى لا تفتن وحتى لا تفتن. نعم.","link":"https://binbaz.org.sa/fatwas/6559/ممن-تغطي-المراة-وجهها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_126/12613.mp3","categories":["اللباس والزينة","النظر والخلوة والاختلاط","قضايا المرأة"]},{"id":8583,"question":"هذه رسالة وردتنا من المرسلة (س. م. ع) من المدينة المنورة تقول في رسالتها: أنا فتاة في السابعة عشرة من عمري مؤمنة ومواظبة على أداء الصلاة والحمد لله، ولكن مشكلتي هي الوسواس والشك، فعندما أستيقظ من النوم أجد بللاً في ملابسي وأغتسل لاعتقادي أنه احتلام مع أنني لا أعرف معنى الاحتلام، وما صفة الماء المصاحب له، لقد أصبح تفكيري محصور في هذه المشكلة لدرجة أنني أغتسل في بعض الأيام مرة أو مرتين، وأصبحت في قلق كبير، وأشك دائماً في نظافة ملابسي وكل شيء حولي، وأستبدل ملابسي الداخلية عند كل صلاة، أرجو إفادتي هل كل بلل تجده المرأة في ملابسها يكون احتلام ولو كان قليل لا يصل إحياناً إلى الملابس، أفيدوني أفادكم الله؟","title":"حكم الرطوبة التي تجدها المرأة في فرجها","answer":"الجواب: أولاً: الوساوس من الشيطان، هذه الشكوك التي تعتري الإنسان، والوساوس كلها من الشيطان، فالواجب محاربته والتعوذ بالله من شره، فعليك أن تتعوذي بالله من الشيطان، وأن تحذري وساوسه، وأن تجتهدي في استحضار عظمة الله، وأنه سبحانه وتعالى لا يكلف نفساً إلا وسعها، وأنه رحيم بعباده، وما جعل عليهم في الدين من حرج، ثم عليك أن لا تخضعي لوساوس الشيطان، بل عليك أن تبتعدي عن وساوسه وإذا أحسست بشيء، قولي: أعوذ بالله من الشيطان الرجيم، واستمري في عملك من صلاة ووضوء وغير ذلك، ولا تعيدي شيئاً ولا تكرري شيئاً.\nأما الرطوبة التي تجدها المرأة في فرجها أو في ملابسها فهذه الرطوبة محل نظر، فإن كانت منياً فهذه علامة أنه احتلام، إذا استيقظت ورأت منياً وهو الماء الثخين الغليظ، هذا يكون عن احتلام، إذا استيقظت من نومها ليلاً أو نهاراً فذلك احتلام فعليها أن تغتسل، أما إن كانت رطوبة عادية ليس فيها ما يدل على المني، فإنها قد تكون رطوبة من بول أو من الماء الذي يحصل للمرأة في فرجها، يحصل في الملابس من السراويل أو في القميص شيء من ذلك، والمرأة تبتلى بأشياء من الرطوبات والمياه التي تخرج من فرجها غير المني، فإذا كنت لا تجزمين أنه مني فليس عليك غسل حتى تعلمي وتجزمي وتتيقني أنه المني المعروف الذي هو أصل الإنسان، وهو ماء غليظ تشبه رائحته رائحة طلع الفحال، فينبغي أن تتثبتي في هذا الأمر، وأن تحرصي على أن تعلمي ما هو هذا الشيء.\nوإذا كان شيئاً عادياً لا يشبه المني، بل هو شيء عادي فهو من رطوبة الفرج، فيكفي أن تغسلي ما أصاب ملابسك من ذلك، وتستنجي بالماء ثم توضئي وضوء الصلاة، يكفي هذا ولا حاجة إلى الغسل. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6666/حكم-الرطوبة-التي-تجدها-المراة-في-فرجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_209/20905.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":8586,"question":"هذه رسالة وردتنا من المرسلة (س. م. ع) من المدينة المنورة تقول في رسالتها: أنا فتاة في السابعة عشرة من عمري مؤمنة ومواظبة على أداء الصلاة والحمد لله، ولكن مشكلتي هي الوسواس والشك، فعندما أستيقظ من النوم أجد بللاً في ملابسي وأغتسل لاعتقادي أنه احتلام مع أنني لا أعرف معنى الاحتلام، وما صفة الماء المصاحب له، لقد أصبح تفكيري محصور في هذه المشكلة لدرجة أنني أغتسل في بعض الأيام مرة أو مرتين، وأصبحت في قلق كبير، وأشك دائماً في نظافة ملابسي وكل شيء حولي، وأستبدل ملابسي الداخلية عند كل صلاة، أرجو إفادتي هل كل بلل تجده المرأة في ملابسها يكون احتلام ولو كان قليل لا يصل إحياناً إلى الملابس، أفيدوني أفادكم الله؟","title":"حكم الرطوبة التي تجدها المرأة في فرجها","answer":"الجواب: أولاً: الوساوس من الشيطان، هذه الشكوك التي تعتري الإنسان، والوساوس كلها من الشيطان، فالواجب محاربته والتعوذ بالله من شره، فعليك أن تتعوذي بالله من الشيطان، وأن تحذري وساوسه، وأن تجتهدي في استحضار عظمة الله، وأنه سبحانه وتعالى لا يكلف نفساً إلا وسعها، وأنه رحيم بعباده، وما جعل عليهم في الدين من حرج، ثم عليك أن لا تخضعي لوساوس الشيطان، بل عليك أن تبتعدي عن وساوسه وإذا أحسست بشيء، قولي: أعوذ بالله من الشيطان الرجيم، واستمري في عملك من صلاة ووضوء وغير ذلك، ولا تعيدي شيئاً ولا تكرري شيئاً.\nأما الرطوبة التي تجدها المرأة في فرجها أو في ملابسها فهذه الرطوبة محل نظر، فإن كانت منياً فهذه علامة أنه احتلام، إذا استيقظت ورأت منياً وهو الماء الثخين الغليظ، هذا يكون عن احتلام، إذا استيقظت من نومها ليلاً أو نهاراً فذلك احتلام فعليها أن تغتسل، أما إن كانت رطوبة عادية ليس فيها ما يدل على المني، فإنها قد تكون رطوبة من بول أو من الماء الذي يحصل للمرأة في فرجها، يحصل في الملابس من السراويل أو في القميص شيء من ذلك، والمرأة تبتلى بأشياء من الرطوبات والمياه التي تخرج من فرجها غير المني، فإذا كنت لا تجزمين أنه مني فليس عليك غسل حتى تعلمي وتجزمي وتتيقني أنه المني المعروف الذي هو أصل الإنسان، وهو ماء غليظ تشبه رائحته رائحة طلع الفحال، فينبغي أن تتثبتي في هذا الأمر، وأن تحرصي على أن تعلمي ما هو هذا الشيء.\nوإذا كان شيئاً عادياً لا يشبه المني، بل هو شيء عادي فهو من رطوبة الفرج، فيكفي أن تغسلي ما أصاب ملابسك من ذلك، وتستنجي بالماء ثم توضئي وضوء الصلاة، يكفي هذا ولا حاجة إلى الغسل. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6666/حكم-الرطوبة-التي-تجدها-المراة-في-فرجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_209/20905.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":8594,"question":"أختنا صابرين الصغيرة من ليبيا بعثت برسالة وضمنتها مجموعة من الأسئلة، تسأل أولاً عن فكرة الحجاب، وتقول: هل فكرة الحجاب غلط، وما رأيكم في زوج ينهى زوجته عن الحجاب؟","title":"تفصيل أقوال أهل العلم في الحجاب","answer":"الجواب: الحجاب فيه تفصيل، أما كونها تستر شعرها وبدنها كله إلا الوجه والكفين فهذا لازم عند أهل العلم، وهكذا القدمان عند جمهور أهل العلم، عليها سترهما عن الرجال، هذا محل ليس محل خلاف كونها تستر شعرها وبدنها وصدرها وجميع بدنها حتى القدمين هذا واجب على النساء عن جميع الرجال الأجانب حتى ابن عمها، وحتى ابن خالها الأجنبي، عليها أن تستر جميع بدنها ما عدا الوجه والكفين هذا محل الخلاف، وهكذا القدمان فيهما خلاف يسير والذي عليه جمهور أهل العلم أن الواجب سترهما أيضاً.\nأما الوجه والكفان فقد نازع بعض أهل العلم في ذلك وقال بعض أهل العلم: إنه لا يجب سترهما عن الأجانب إذا كان الوجه ليس فيه محسنات، لا مكياج ولا كحل ولا شيء من أنواع الجمال الذي تأتي به المرأة يعني المستجلب، وهكذا الكفان إذا كان ليس فيهما شيء من الحلي، قال بعض أهل العلم: إنهما ليس بعورة في هذه الحالة إذا كان الوجه ليس فيه ما يدعو إلى الفتنة من كحل أو زينة أخرى، والكفان ليس فيهما زينة أيضاً من حلي أو نحوها، هذا قول بعض أهل العلم.\nوالقول الآخر: أنهما أيضاً يجب سترهما عن الأجانب، وهذا هو القول الراجح، والأدلة على هذا القول كثيرة؛ لأن الوجه زينة المرأة وعنوانها، جمالاً ودمامة، فالواجب ستره إلا عن المحارم أو الخاطب الذي يريد أن ينظر إليها، فالرسول صلى الله عليه وسلم أذن للخاطب أن ينظر، وأما ما سوى ذلك فالواجب ستر الوجه والكفين حذراً من الفتنة.\nومن الأدلة على هذا قوله سبحانه: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] وإن كانت الآية في أزواج النبي ﷺ فالحكم عام إلا بدليل يخصهن؛ ولأن العلة عامة ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] فإذا كان أطهر لقلوب زوجات النبي ﷺ فغيرهن أحوج إلى ذلك؛ لأن أزواج النبي ﷺ أتقى لله وأكمل إيماناً ممن بعدهن، فإذا كان الحجاب أتقى لأزواج النبي ﷺ وأطهر للقلوب فما بعدهن في أشد الحاجة إلى ذلك.\nولأن الرب  لم يستثن لم يقل: إلا الوجه والكفين بل أطلق، وهكذا قوله سبحانه: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِِ بُعُولَتِهِنَّ [النور:31] ولم يقل إلا الوجه والكفين بل أطلق، وأما قوله في أول الآية: إِلَّا مَا ظَهَرَ مِنْهَا [النور:31] فقد فسره ابن مسعود بأن المراد: الملابس التي تلبسها المرأة، وأما ما يروى عن ابن عباس وجماعة أن المراد به: الوجه والكفان فهذا محل نظر؛ لأن بعض أهل العلم قالوا: إن المراد بذلك يعني: قبل الحجاب، مراد ابن عباس ما كان قبل الحجاب.\nوقال آخرون: أن مراده بعد الحجاب، وبكل حال فقول ابن مسعود يعارض قول ابن عباس ، فإذا تعارض القولان وجب تحكيم الأدلة والرجوع إلى الأدلة، والله يقول سبحانه: فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ إِنْ كُنتُمْ تُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الآخِرِ ذَلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا [النساء:59] ويقول سبحانه: وَمَا اخْتَلَفْتُمْ فِيهِ مِنْ شَيْءٍ فَحُكْمُهُ إِلَى اللَّهِ [الشورى:10] فإذا رجعنا إلى كتاب الله وإلى حكمه وجدناه سبحانه يقول: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] ومن استثنى عليه الدليل، وهكذا قوله سبحانه: يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلابِيبِهِنَّ ذَلِكَ أَدْنَى أَنْْ يُعْرَفْنَ فَلا يُؤْذَيْنَ [الأحزاب:59] والجلباب: ثوب تطرحه المرأة على رأسها وبدنها للستر، ولم يستثن من ذلك الوجه.\nثالثاً: قوله سبحانه: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ [النور:31] الآية، ولم يستثن شيئاً، ومعلوم أن الوجه من الزينة بل هو أعظم الزينة، فتقرر بهذا وجوب ستر الوجه والكفين حذراً من الفتنة.\nوقد يحتج بعضهم.. بعض من أجاز الوجه والكفين بحديث ضعيف رواه أبو داود عن عائشة رضي الله عنها قالت: دخلت علي أسماء بنت أبي بكر -أختها رضي الله عنها زوجة الزبير- قالت: وعندي رسول الله ﷺ وعليها ثياب رقاق، فأعرض عنها النبي ﷺ وقال: يا أسماء ! إن المرأة إذا بلغت المحيض لم يصلح أن يرى منها إلا هذا وهذا وأشار إلى الوجه والكفين، قالوا: فهذا يدل على جواز إبداء المرأة وجهها وكفيها، والجواب عن هذا الحديث من وجوه:\nالوجه الأول: أنه ضعيف لعدة علل: العلة الأولى أنه لم يثبت عن عائشة بل هو منقطع، لأنه من رواية خالد بن دريك عن عائشة ولم يسمع منها، والحديث المنقطع لا يحتج به بل هو ضعيف.\nالعلة الثانية: أن في إسناده سعيد بن بشير وهو ضعيف لا يحتج به عند أهل العلم.\nالعلة الثالثة: أنه من رواية قتادة عن خالد بن دريك وهو مدلس ولم يصرح بالسماع من خالد ، والمدلس إذا روى بالعنعنة لا يحتج به، هذه ثلاث علل.\nوهناك علة رابعة: وهي أن الحديث لم يصرح أنه بعد الحجاب، فقد تكون هذه القضية قبل الحجاب، قبل أن ينزل الحجاب، فلهذا لو صح كان تكشف الوجه والكفين؛ لأن النساء كن قبل الحجاب يكشفن عن وجوههن وكفيهن، هكذا كان قبل الحجاب.\nوعلة خامسة عندي أنها أيضاً وجيهة: وهي أنه يستغرب جداً أن تكون أسماء زوج الزبير بن العوام وهي أكبر من عائشة وقد تفقهت في الدين بنت أبي بكر الصديق تدخل على النبي ﷺ في ثياب رقاق ترى منها العورة هذا بعيد على أسماء ، فهو يدل على نكارة في المتن، وأنه منكر وغير صحيح؛ لأن تقواها لله وإيمانها بالله وتقدمها في الإسلام والهجرة، كل ذلك يقتضي أن تكون في غاية من البعد عن هذه الصفة، والله المستعان. نعم.\nالمقدم: نفع الله بعلمكم وجزاكم الله خيراً، إذاً الزوج الذي ينهى زوجته عن الحجاب يعد مخطئاً ولا شك؟\nالشيخ: لا شك أنه غالط نسأل الله أن يهديه، قد يكون جاهلاً فيعلم، ونسأل الله له الهداية، نعم، لكن لا يلزمها طاعته إنما الطاعة في المعروف يقوله النبي ﷺ: إنما الطاعة في المعروف نعم.","link":"https://binbaz.org.sa/fatwas/6705/تفصيل-اقوال-اهل-العلم-في-الحجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_128/12806.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":8602,"question":"ننتقل إلى رسالة وصلت إلى البرنامج بتوقيع (ع. ع. ع) من بريدة هذه الرسالة اشتملت على مجموعة من الأسئلة ملخصها كما يلي: امرأة تصبغ شعرها لزوجها ما هو رأيكم؟","title":"حكم صبغ المرأة لشعرها تزيناً لزوجها","answer":"الجواب: الصبغ إن كان بالحناء أو بالزعفران أو نحو ذلك لا بأس، أما صبغ الشيب بالسواد فلا يجوز؛ لأن الرسول ﷺ أنكر ذلك ولم يفصل لم يقل: (هذا للنساء أو للرجال) بل عمم، قال ﷺ: غيروا هذا الشيب واجتنبوا السواد وقال: يأتي في آخر الزمان قومم يخضبون بالسواد كحواصل الحمام لا يريحون رائحة الجنة رواه الإمام أحمد وأبو داود والنسائي بإسناد صحيح، والأول رواه مسلم في الصحيح في قصة والد الصديق لما جاء به إلى النبي ﷺ يوم الفتح ورأسه ولحيته كالثغامة بياضاً، قال ﷺ: غيروا هذا الشيب وجنبوه السواد وفي لفظ: واجتنبوا السواد فهذا يعم الرجال والنساء، فإذا كانت المرأة فيها شيب تغير بغير السواد. نعم.\nالمقدم: سمعت من بعضهن أن هناك حناء أسود سماحة الشيخ؟\nالشيخ: لا بد أن يكون الخضاب ليس بأسود، الحناء الذي يجعل الخضاب أحمر أو بين الحمرة والسواد، أما إذا وجد شيء يجعله أسود فلا؛ لأن هذا هو المنهي عنه.\nالمقدم: حتى وإن سمي حناء؟\nالشيخ: وإن سمي حناء. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6733/حكم-صبغ-المراة-لشعرها-تزينا-لزوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_129/12907.mp3","categories":["اللباس والزينة"]},{"id":8657,"question":"الرسالة الأولى في هذه الحلقة وردتنا من السائل عيظة محمد الدعبلي لم يذكر عنواناً، يقول في رسالته: ما حكم الرجل الذي يسعف زوجته بالدم، وما حكم لبس الساعة في اليد اليمنى بالنسبة للرجل؟","title":"حكم التبرع بالدم للزوجة، ولبس الساعة في اليمين","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإسعاف الرجل لزوجته بالدم ليس فيه محذور، ولا يؤثر في النكاح، وليس مثل الرضاع، فللرجل أن يسعف زوجته وللمرأة أن تسعف زوجها، ولا حرج في ذلك والحمد لله.\nأما لبس الساعة فيجوز في اليمين وفي اليسار، وقد ثبت عن النبي ﷺ: أنه تختم في يمينه تارة وفي يساره تارة وهذا لبيان التوسعة، فالساعة مثل ذلك إذا لبسها في اليمين أو في اليسار فلا بأس. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6786/حكم-التبرع-بالدم-للزوجة-ولبس-الساعة-في-اليمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_213/21301.mp3","categories":["اللباس والزينة","الطب والتداوي"]},{"id":8661,"question":"هذه رسالة من السائلة (ح. ط) من العراق بغداد قضاء المحمودية، تقول في رسالتها: أنا أبلغ من العمر أربعين عاماً وأنا فلاحة وأعمل في الزراعة ويخرج لي الرجال والنساء الأجانب وأخالطهم ويظهر مني الوجه والكفان، وأنا لا أستطيع الاحتجاب في المحيط الذي أنا فيه، وأنا أخاف من عذاب الله، فهل علي إثم في العمل أم لا؟","title":"الحث على الحجاب، النهي عن الخلوة بالأجانب","answer":"الجواب: عليك -أيها الأخت- في الله أن تحتجبي ولو كان فيه مشقة؛ يقول النبي ﷺ حفت النار بالشهوات وحفت الجنة بالمكاره هكذا يقول النبي ﷺ: حفت الجنة بالمكاره وحفت النار بالشهوات فلابد من كون المؤمن يجاهد نفسه، والمؤمنة كذلك تجاهد نفسها في الحجاب عن الرجال الأجانب، والخلطة التي قد تسبب فتنة عليك أن تجتنبيها، أما كونهم يتصلون بك لحاجة من المزرعة لشراء حاجة في المزرعة، للسؤال عن حاجة في المزرعة ما يضر مع الاحتجاب والحمد لله، لكن ليس لك أن تختلي بالرجل الواحد ليس معكما أحد، لا. أما معكما ثاني أو ثالث أو امرأة أخرى من دون ريبة ولا فتنة فلا حرج في ذلك مع الحجاب والتستر، إذا سأل عن حاجته أو طلب شراء حاجة أو شبه ذلك من الحاجات التي يحتاجها الناس من المزرعة، هذا لا حرج فيه مع البعد عن أسباب التهمة والبعد عن الخلوة والبعد عن التكشف، تكوني مستورة متحجبة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6812/الحث-على-الحجاب-النهي-عن-الخلوة-بالاجانب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_214/21417.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":8682,"question":"تسأل أيضاً وتقول: هل يجوز لي أن أسير في البيت بين إخوتي ورأسي مكشوف، رغم أني أصلي أم لا يجوز، فهل حرام كشف الرأس على الأهل مثل أولاد الخالة وأولاد العم، وبعض الأحيان يدخل ابن خالتي ورأسي مكشوف، أفيدوني أفادكم الله؟","title":"حكم كشف المرأة رأسها عند المحارم والأقارب غير المحارم","answer":"الجواب: الصلاة هي عمود الإسلام والواجب على كل مسلم أن يصلي، قال الرسول ﷺ: رأس الأمر الإسلام، وعموده الصلاة والله يقول في كتابه العظيم: حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى وَقُومُوا لِلَّهِ قَانِتِينَ [البقرة:238] ويقول سبحانه: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَأَطِيعُوا الرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ [النور:56] هذا فرض على الجميع على الرجال والنساء.\nولكن مع ذلك على المرأة أيضاً وعلى الرجل أن يدع ما حرم الله، وأن يؤدي بقية ما أوجب الله من زكاة ومن حج ومن صيام رمضان ومن بر والدين وصلة أرحام وأمر بمعروف ونهي عن منكر وغير ذلك، وعلى المرأة وعلى الرجل أن يتجنبا ما حرم الله مع كونهما يقيمان الصلاة، عليهما أن يتجنبا ما حرم الله من الزنا والسرقة وشرب المسكرات والتدخين وسائر المعاصي.\nكشف الرأس عند النساء لا بأس، عند المحارم كالإخوة والأعمام والأخوال والأب والبنين لا بأس، إلا إذا كانت تخشى لأن بعض المحارم قد يكونون فساقاً ويخشى من شرهم، فإذا كانت تخشى فينبغي أن تستره أيضاً حتى عند بعض المحارم، الذين لا يؤمنون تستر رأسها وبدنها ولا تظهر عندهم إلا الوجه والكفين ونحو ذلك؛ لأن بعض المحارم وإن كانوا أخوالاً أو أعماماً قد لا يؤمنون فالتستر عنهم يكون أبعد عن الشر، ولكن ليس الرأس ممنوع الكشف عند المحرم، فلو رأى أخوها أو عمها رأسها فلا بأس، وإذا رأى أخوك أو عمك أو خالك رأسك فلا بأس، أما ابن الخال وابن العمة وابن العم لا. هؤلاء ليسوا محارم هؤلاء أجناب، في حكم الأجناب وإن كانوا أقارب، لكنهم في حكم الأجناب، ليس لك أن تكشفي لهم رأسك ولا وجهك ولا قدمك ولا، ينبغي أن تتستري عنهم، المرأة عورة تستر نفسها عن ابن خالها وابن عمتها وابن خالتها وابن عمها، لا تكشف لهم لا وجهاً ولا رأساً بل تستر نفسها كالأجنبي، كالجيران وغيرهم من الأجانب، عليك أن تتستري عنهم وتكلميهم بالكلام الطيب لكن مع الستر مع الحجاب؛ لأن الله يقول سبحانه: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ [الأحزاب:53] وقال سبحانه: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ أَوْ أَبْنَائِهِنَّ أَوْ أَبْنَاءِ بُعُولَتِهِنَّ أَوْ إِخْوَانِهِنَّ أَوْ بَنِي إِخْوَانِهِنَّ أَوْ بَنِي أَخَوَاتِهِنَّ [النور:31] الآية. هؤلاء هم المحارم، أما ابن الخال وابن الخالة وابن العم وابن العمة فليسوا محارم، فعليك الحجاب عن هؤلاء، ولكن الكلام لا بأس، السلام عليه ورد السلام مع الحشمة ومع الحجاب هذا كله لا بأس به من غير خلوة. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6819/حكم-كشف-المراة-راسها-عند-المحارم-والاقارب-غير-المحارم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_215/21506.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":8702,"question":"هنا رسالة وصلت إلى البرنامج من أخينا خالد محمد هنيدو أخونا يقول: إذا كان الإنسان محرماً بالحج أو العمرة وتمزق إحرامه بسبب سقوطه على الأرض، فهل يجوز له أن يخيطه أم لا؟","title":"حكم خياطة ثياب الإحرام","answer":"الجواب: له أن يخيطه وله أن يبدله لا بأس إذا انشق إحرامه أو إزاره أو رداؤه وخاطه لا بأس، وكذلك لو أبدله بغيره لا بأس، المخيط المنهي عنه هو المخيط الذي يحيط بالبدن كالقميص والفلينة وأشباه ذلك، أما مخيط قطعة في قطعه مثل الرداء، قطعتين ثلاث يخيط بعضها في بعض يجعلها رداء أو إزار لا بأس، هذا لا يضر ولا يمنع، الممنوع منه إذا قيل: المخيط المراد بالمخيط الذي يحيط باليد بالبدن بالرجل كالخف هذا هو الذي ينهى عنه، أما مخيط لا يحيط بالبدن مخيطاً بل قطعة ثوب لا يكون قميصاً ولا يكون مثل القفاز، ولا يكون مثل الخف ولا يكون مثل الفلينة بل هو قطعة يوصل بعضها ببعض، فهذا لا بأس به ولا حرج فيه.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6849/حكم-خياطة-ثياب-الاحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_131/13109.mp3","categories":["اللباس والزينة","محظورات الإحرام","قضايا المرأة"]},{"id":8709,"question":"في نهاية هذه الحلقة رسالة الأخت المستمعة من المغرب الشقيق التي عرضنا بعضاً من أسئلتها في حلقة مضت وفي هذه الحلقة تسأل عن الشعر الذي ينبت في وجه المرأة ما رأيكم في إزالته؟","title":"حكم إزالة المرأة للشعر النابت على الوجه","answer":"الجواب: هذا فيه تفصيل، إن كان شعراً عادياً فلا يجوز أخذه لحديث لعن النامصة والمتنمصة، فقد ذكر أئمة اللغة أن النمص: أخذ الشعر من الوجه والحاجبين، أما إن كان شيئاً زائداً، يعني: يعتبر مثلة تشويهاً للخلقة كالشارب واللحية فهذا لا بأس بأخذه ولا حرج؛ لأنه يشوه خلقتها ويضرها، أما الشيء العادي اللي ما فيه تشويه بل هو عادي فهذا لا تأخذه كالحاجبين. نعم.","link":"https://binbaz.org.sa/fatwas/6856/حكم-ازالة-المراة-للشعر-النابت-على-الوجه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_132/13205.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":8724,"question":"أحد الإخوة المستمعين يسأل أيضًا سماحة الشيخ عن غسل الإحرام إذا اتسخ، هل يجوز للمحرم أن يفعل ذلك؟","title":"حكم تغسيل الإحرام","answer":"الجواب: نعم، إذا أحب أن يغسل إحرامه ولاسيما إذا اتسخ فلا بأس، لا بأس أن يغسله، ولا بأس أن يبدله بإحرام آخر، الرجل والمرأة، من أراد أن يبدل ملابس الإحرام بملابس أخرى جديدة أو غسيلة فلا بأس من الرجال والنساء، وهكذا لو توسخت يغسلها أو أصابها نجاسة يغسلها ثم يلبسها، الأمر فيه واسع، إن شاء أبدلها وإن شاء غسلها الأمر في هذا واسع. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/6874/حكم-تغسيل-الاحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_160/16005.mp3","categories":["اللباس والزينة","محظورات الإحرام","قضايا المرأة"]},{"id":8846,"question":"أخت لنا من العراق محافظة البصرة تقول المؤمنة: (م. ع. د) أختنا رسالتها مطولة بعض الشيء، ملخصها السؤال عن الرياضة بالنسبة للفتيات؟","title":"حكم ممارسة النساء للرياضة","answer":"الجواب: الرياضة تختلف كلمة مجملة، فالرياضة بين البنات في أشياء لا تخالف الشرع المطهر بمشي كثير في محل خاص بهن لا يخالطهن فيه الرجال، ولا يطلع عليه الرجال، أو بسباحة عندهن في بيتهن أو في مدرستهن خاصة لا يراها الرجال ولا يتصل بها الرجال، لا يضر ذلك.\nأما رياضة يحصل بها الاختلاط بين الرجال والنساء أو يراها الرجال أو تسبب شرًا على المسلمين فلا تجوز، فلابد من التفصيل.\nالرياضة التي تخص النساء ولا يكون فيها محذور شرعًا، وليس فيها اختلاط بالرجال بل في محل مستور ومحل بعيد عن الخلطة فلا بأس بها، سواء كانت بالمشي أو بالسباحة ونحوها، نعم وهكذا بالمسابقة بينهن. نعم.","link":"https://binbaz.org.sa/fatwas/7001/حكم-ممارسة-النساء-للرياضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_166/16604.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":8850,"question":"من الجمهورية الجزائرية رسالة وصلت إلى البرنامج من الأخوين: حماد وخديجة يسألون في السؤال الأول، ويقولون: عندي سلسلة -ولعل السائلة هي البنت عندي سلسلة- من ذهب ومكتوب عليها اسم الله، هل يجوز لي أن أستعملها أم أن ذلك حرام؟","title":"حكم لبس الحلي أو الثياب التي عليها اسم الله","answer":"الجواب: هذه السلسلة من الذهب التي فيها اسم الله أو فيها آية من القرآن ينبغي تركها؛ لأنه قد يدخل بها الخلاء، تركها أولى، وقد توضع في محل يمتهن، فالأولى بك أن تغيري هذه السلسلة بأن يزال منها ما فيها من أسماء الله حتى لا تمتهن؛ لأن أسماء الله عظيمة، والسلسلة قد توضع في بعض المتاع قد تلقى في الغرفة، قد تلقى في الصندوق فلا يبالى بها، قد تلمس بشيء لا يناسب، فالحاصل: أن تركها أولى وأحوط تعظيمًا لأسماء الله عز وجل، فتحك أو تسبك سبكًا جديدًا ليس فيها ذكر الله سبحانه وتعالى، هذا هو الأولى والأحوط احتياطًا لأسماء الله وحماية لها من الامتهان.\nوهكذا الثياب التي يكون فيها أسماء الله أو آيات لا يجوز لبسها؛ لأنها وسيلة إلى أن تمتهن أو يصيبها النجاسة من حيض أو غيره، أو تلقى فيطأ عليها الناس أو يجلس عليها الناس؛ فلهذا حرم لبسها وحرم جعلها وسائد أو بسط؛ لأن هذا يفضي إلى امتهانها بالقعود عليها والوطء عليها ونحو ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/7005/حكم-لبس-الحلي-او-الثياب-التي-عليها-اسم-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_166/16607.mp3","categories":["اللباس والزينة"]},{"id":8870,"question":"ما حكم الشرع في وضع الكحل على حاجب المرأة للزينة؟","title":"حكم وضع الكحل على حاجب المرأة للزينة","answer":"الجواب: لا أعلم في هذا شيئاً لكن إن كانت قد ظهر فيها الشيب فليس لها أن تغير الشيب بالصبغ الأسود؛ لأن الرسول ﷺ نهى عن التغيير بالسواد، قال: غيروا هذا الشيب وجنبوه السواد ، فإذا صبغت شيبها بغير الأسود كالحناء ونحوه فلا بأس، أما أن تغير الشيب في الحاجب أو في الرأس بأسود فلا كالرجل سواء. نعم.","link":"https://binbaz.org.sa/fatwas/7026/حكم-وضع-الكحل-على-حاجب-المراة-للزينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_138/13809.mp3","categories":["اللباس والزينة"]},{"id":8932,"question":"أختنا تقول: هل يجوز للمرأة بعد أن تحرم أن تأخذ شيئاً من الطيب أو تكتحل أو كذا؟","title":"حكم التطيب والاكتحال بعد الإحرام","answer":"الجواب: هذا فيه التفصيل؛ لأن بعض الناس يشتبه عليه الأمر في هذا، إذا كان الرجل حين لبس الإزار والرداء، أو المرأة إذا لبست الثياب المعدة لإحرامها لم تلب ولم تنو الإحرام حتى الآن، يعني: لبس الإزار والرداء الرجل ليحرم، أو لبست المرأة ثيابًا معدة وهي ما يلزمها ثياب معدة، أي ثوب تلبسه يكفيها، لكن لو أعدت شيئًا يعني ثياباً ليس فيها ما يلفت النظر غير جميلة أعدتها للإحرام فإنها لا تكون محرمة ولا يكون الرجل محرم بلبسه الرداء والإزار إلا بالنية، إذا نوى الرجل أو المرأة الدخول في العمرة أو في الحج والشروع فيها فإنه يلبي حينئذ ولا يباح له بعد هذا أن يلمس طيبًا ولا يقص ظفرًا ولا شعرًا بعد ذلك صار محرمًا، بالنية صار محرمًا.\nفإذا استعد للإحرام بلبس الإزار والرداء، أو المرأة استعدت للبس ملابس أعدتها لذلك فإنها لا تكون محرمة إلا بالنية، فله أن يأخذ الطيب، ولها أن تأخذ الطيب قبل ذلك ولو كانت قد لبست الملابس المعدة للإحرام، ولو كان الرجل قد لبس الإزار والرداء له أن يتطيب وله أن يقلم أظفاره، وله أن يأخذ من شاربه أو من إبطه لا بأس حتى ينوي، فإذا نوى الدخول في الحج بقلبه أو نوى الدخول في العمرة بقلبه، وهكذا المرأة نوت الدخول في الحج أو في العمرة بقلبها فإنه في هذه الحال يلبي، فيقول: لبيك عمرة، أو لبيك حجة، وهي تقول كذلك: لبيك عمرة، أو لبيك حجة عند النية، بعد نية الدخول في النسك الذي هو الحج والعمرة، بهذا إذا نوى هذه النية ودخل في النسك بنيته فإنه في هذه الحال لا يأخذ طيبًا ولا يقلم ظفراً ولا يقص شعراً ونحوه مما حرم عليه.\nأما قبل ذلك فلا بأس، والأفضل أنه لا يحرم إلا بعد ركوبه السيارة، كان النبي ﷺ لا يلبي إلا إذا ركب دابته، فيفعل ما يحتاجه وهو في الأرض، يقص شاربه.. يقلم أظفاره.. يتطيب، ولو أن عليه الرداء والإزار، ولو أنها لبست ملابسها المعدة للإحرام، تفعل ما ترى من أمور الإحرام من نتف الإبط.. من قلم الظفر.. من تطيب والرجل كذلك يتطيب، يقلم ظفرًا إلى غير هذا لا بأس، حتى يركب حين ركب نوى الدخول في العمرة أو نوى الدخول في الحج ثم لبى، وعند ذلك لا يأخذ شيء من شعره ولا من أظفاره ولا يتطيب؛ لأنه دخل في النسك.\nوالخلاصة: أنه لا يكون محرمًا ولا تكون المرأة محرمة إلا بنية الدخول في النسك، من حج أو عمرة، ثم يلبي بعد ذلك، أما كونها لبست الملابس المعدة للإحرام أو كونه لبس الإزار والرداء ليحرم فلا يكونان بذلك محرمين حتى ينويا بقلبهما الدخول في الحج أو في العمرة، ثم بعد هذا يلبيان، فينبغي الفرق وينبغي التفصيل، ونسأل الله للجميع التوفيق. نعم.","link":"https://binbaz.org.sa/fatwas/7090/حكم-التطيب-والاكتحال-بعد-الاحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_143/14307.mp3","categories":["اللباس والزينة","محظورات الإحرام","قضايا المرأة"]},{"id":8940,"question":"أختنا تسأل وتقول: ما حكم الركوب مع أحد من الأقارب بالرغم من وجود أمه أو أخته أو إحداهما؟","title":"حكم الركوب مع غير المحرم مع وجود أمه أو أخته","answer":"الجواب: لا مانع إذا كان مع المرأة شخص ثالث يحصل به زوال الخلوة فلا بأس؛ فإذا ركبت مع السائق ومعه أمه أو أخته أو زوجته أو معها أخوها أو زوجها أو أمها أو امرأة أخرى على وجه ليس فيه ريبة فلا بأس بذلك تزول الخلوة، والحمد لله.\nالمقدم: بارك الله فيكم! لكن يفضل سماحة الشيخ أن يكون الراكب من أقاربها أو من أقارب ذلك الرجل؟\nالشيخ: المهم الثقة أنهم ثقات ليس في ركوبهم ريبة.","link":"https://binbaz.org.sa/fatwas/7098/حكم-الركوب-مع-غير-المحرم-مع-وجود-امه-او-اخته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_172/17202.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":8951,"question":"الرسالة التالية باعثتها إحدى الأخوات المستمعات تقول: (أ. أ. ع) من الشرقية، أختنا لها مجموعة من الأسئلة بدأت رسالتها تقول: أولًا أشكر البرنامج على ما يقدمه لنا من فتاوى قيمة، وجزى الله العلماء الأفاضل خير الجزاء على تفضلهم بالإجابة على أسئلتنا وجزاكم الله خيرًا.أرجو عرض أسئلتي الآتية على سماحة الشيخ عبدالعزيز بن باز: هل لبس الدبلة للنساء بدعة نصرانية؛ لأنني قرأت بأن دبلة الخطبة أو الزواج للرجل وإن كانت فضة وأيضًا للمرأة بدعة نصرانية، هل هذا صحيح؟","title":"حكم لبس دبلة الخطبة والزواج","answer":"الجواب: الدبلة التي تسأل عنها السائلة لا نعلم لها أصلًا والذي يظهر لنا من ذلك أن فيها تشبهًا بالكفرة؛ لأنها من عادتهم فيما بلغنا فلا ينبغي اتخاذها، فإن الإشارة إلى الزواج تكون بالخطبة والاتفاق بين الخاطب والمخطوب منهم ويكفي ذلك من غير حاجة إلى الدبلة، ومتى تم الأمر بالعقد الشرعي انتهى كل شيء، أما الدبلة فلا حاجة إليها ولا حاجة إلى التشبه بأعداء الله، لا من النصارى ولا من غيرهم، والواجب البعد عن مشابهة أعداء الله في كل شيء. نعم.","link":"https://binbaz.org.sa/fatwas/7108/حكم-لبس-دبلة-الخطبة-والزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_173/17302.mp3","categories":["اللباس والزينة","الخِطْبَة والاختيار ","البدع والمحدثات"]},{"id":8955,"question":"هل هناك لون معين يجب أن ترتديه المرأة عند خروجها، أي لابد مثلًا أن ترتدي جلبابًا أسود مع تغطية الوجه أم ليس هناك لون معين يجب أن تتقيد به؟","title":"المشروع في لباس المرأة عند الخروج","answer":"الجواب: ليس هناك لون معين يجب أن تتقيد به إلا أنه يكون من الألبسة التي لا تلفت النظر ولا تسبب الفتنة، تكون ملابس عادية ليس فيها ما يلفت النظر ويسبب الفتنة بمن يراهن؛ لأن الله قال جل وعلا: وَقَرْنَ فِي بُيُوتِكُنَّ وَلا تَبَرَّجْنَ تَبَرُّجَ الْجَاهِلِيَّةِ الأُولَى [الأحزاب:33] قال العلماء: التبرج: إظهار المحاسن والمفاتن من المرأة، فاللباس العادي أسود أو غير أسود، أحمر أو أزرق أو أخضر إذا كان لباسًا عاديًا ليس فيه زينة تلفت النظر ولا جمال يلفت النظر فهذا هو الذي ينبغي، وكذلك الملابس الداخلية تكون مستورة بهذا الجلباب وبهذا العباءة، مع ستر الوجه واليدين والقدمين حتى تكون بعيدة عن الفتنة، ولا مانع من أن يكون الخمار يكون معه النظر لابد من تمكنها من النظر حتى تعرف طريقها، أو تكون هناك عين واحدة مفتوحة أو العينان حتى تعرف الطريق مع ستر البقية. نعم.\nالمقدم: بارك الله فيكم. إذا كان جمال المرأة في عينيها سماحة الشيخ؟\nالشيخ: للضرورة إذا تيسر أن يكون الخمار ساترًا للوجه فهذا أكمل وأعظم في الستر وفي الحجاب، ولكن بعض النساء قد يكون بصرها ضعيفًا وقد لا يكفيها أو لا تستطيع النظر من وراء الحجاب فتفعل ما تستطيع. نعم.\nالمقدم: بارك الله فيكم، إذا كان الغطاء يغيير ملامح الوجه أو العينين ألا يكون هذا نوع من الحجاب سماحة الشيخ؟\nالشيخ: المهم أن تكون المفاتن مستورة حتى يكون النظر الذي تدرك به الطريق لا يحصل به الفتنة إنما عين واحدة، أو العينان إن كانت العين الواحدة لا تكفي. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7112/المشروع-في-لباس-المراة-عند-الخروج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_173/17304.mp3","categories":["اللباس والزينة"]},{"id":8956,"question":"ما حكم الإسلام في الذهب المحلق للمرأة مثل الأسورة والحلق المستديرة؛ لأني سمعت حديثًا معناه: من أراد أن يهدي حبيبه سوارًا من نار فليهده سوارًا من ذهب؟","title":"ما حكم الإسلام في الذهب المحلق للمرأة؟","answer":"الجواب: هذا الحديث بالنظر إلى سنده لا بأس به ولكنه منسوخ بالنسبة إلى النساء، أو شاذ مخالف للأحاديث الصحيحة، وأما الرجل فيحرم عليه الذهب، ليس للرجل أن يلبس ذهبًا حلقة ولا غيرها وإنما يلبس الخاتم من الفضة لقوله ﷺ: أحل الذهب والحرير لإناث أمتي وحرم على ذكورهم، وفي بعض الأحاديث أنه ﷺ: أخذ قطعة من ذهب وقطعة من حرير وقال: هذان حل لإناث أمتي حرام على ذكورها، وقد جاء في المعنى أحاديث أخرى تدل على حل الذهب والحرير للإناث، وعلى تحريمه على الذكور حتى ولو صغارًا ولو أطفالًا لا يجوز تلبيسهم الذهب ولا تلبيسهم الحرير وهم ذكور، وأما ما ورد في خلاف ذلك من نهي المرأة عن لبس المحلق والوعيد في ذلك فهي أحاديث عند أهل العلم ما بين ضعيفة أو شاذة منسوخة مخالفة للأحاديث الصحيحة.\nوقد أجمع المسلمون على حل الذهب والحرير للإناث سواء كان الذهب محلقًا كالأسورة أو غير محلق، هذا هو الصواب، ومن قال من إخواننا المتأخرين: إنه يحرم على المرأة المحلق فهو قول ضعيف مرجوح مخالف لما جاءت به الأحاديث الصحيحة عن رسول الله عليه الصلاة والسلام ومخالف الإجماع الذي حكاه غير واحد من أهل العلم، فقد حكى الحافظ ابن حجر و النووي و البيهقي وجماعة حل الذهب والحرير للإناث وتحريمه على الذكور، حكى هؤلاء وغيرهم إجماع الأمة على ذلك فوجب أن تكون الأحاديث التي فيها ما يشعر بتحريم الذهب على النساء إذا كان محلقًا أنه شيء منسوخ وليس بباقي العمل بل منسوخ أو شاذ مخالف للأحاديث الصحيحة؛ لأن القاعدة عند أهل العلم أن الحديث إذا خالف ما هو أصح منه يعتبر شاذًا، وإذا كان منسوخًا بالأحاديث الصحيحة المتأخرة زال حكمه، وقد جاء في الحديث الصحيح: أحل الذهب والحرير لإناث أمتي، فهذا يشعر بأنه أحل بعدما حرم، فالتحليل للإناث دليل على أنه لا فرق بين المحلق وغيره، ومن قال من بعض إخواننا المتأخرين: إن المحلق محرم فهو غلط، والصواب أن المحلق وغيره من الذهب حل للإناث. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7114/ما-حكم-الاسلام-في-الذهب-المحلق-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_173/17305.mp3","categories":["اللباس والزينة"]},{"id":8990,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من السودان الحِّلة الجديدة باعثة الرسالة إحدى الأخوات من هناك تقول: أختكم عائشة علي حسن خليفة أختنا لها مجموعة من الأسئلة، في سؤالها الأول تسأل وتقول: هل يجوز لي السفر مع أختي وزوجها كمحرم لي ولها؟ هذا هو سؤالها الأول لو سمحتم شيخ عبدالعزيز؟","title":"حكم سفر المرأة مع زوج أختها كمحرم لها","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فقد صح عن رسول الله عليه الصلاة والسلام أنه قال: لا تسافر المرأة إلا مع ذي محرم، وزوج الأخت ليس محرمًا وإنما هو محرم لزوجته، أما أختها وعمتها وخالتها فليس محرمًا لها، وإنما يكون محرمًا لزوجته وأمها وبنتها إذا كان قد دخل بأمها لا بأس يكون محرمًا للزوجة، يكون محرمًا للأم للجدة، وهكذا يكون محرمًا للبنت بنت الزوجة إذا كان قد دخل بأمها، أما أخت الزوجة، عمة الزوجة، خالة الزوجة، بنت عم الزوجة فليس محرمًا لهم. نعم.","link":"https://binbaz.org.sa/fatwas/7148/حكم-سفر-المراة-مع-زوج-اختها-كمحرم-لها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_176/17601.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":8991,"question":"سؤالها الثاني: هل يجوز للرجل أن يصافح خالة أو عمة زوجته؟","title":"حكم مصافحة الرجل عمة أو خالة زوجته","answer":"الجواب: ليس له ذلك؛ لأن خالتها ليست محرمًا له، وهكذا عمتها، ولكن له أن يصافح أمها وجدتها، بنتها التي دخل بأمها لا بأس، أما عمتها وخالتها وأختها فليس له أن يصافحهن، يقول النبي ﷺ: إني لا أصافح النساء، قالت عائشة رضي الله عنها: والله ما مست يد رسول الله ﷺ يد امرأة قط، ما كان يبايعهن إلا بالكلام.\nولأن مس المرأة قد يفضي إلى الفتنة، قال بعض أهل العلم: إنه شر من النظر. نعم.","link":"https://binbaz.org.sa/fatwas/7149/حكم-مصافحة-الرجل-عمة-او-خالة-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_176/17602.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":9014,"question":"رسالة وصلت إلى البرنامج من مكة المكرمة باعثتها إحدى الأخوات المستمعات تقول: (ح. م) من قديد، يا أخت (ح. م) من مكة المكرمة البرنامج لا يهتم كثيراً بتفسير الأحلام فمعذرة، تسأل سماحة الشيخ لو تكرمتم عن هذه الأصباغ التي يضعها بعض النساء على وجوههن وشفايفهن، وهل يؤثر ذلك على الوضوء وترجو الإفادة؟","title":"حكم الأصباغ التي توضع على الوجه والشفاه","answer":"الجواب: الأصباغ تختلف إن كانت لها جسم لها جرم يمنع الماء فالواجب إزالتها عند الوضوء، أما إن كانت أصباغاً رقيقة لا تمنع الماء على الشفة أو على الوجه لتنويره فلا يضر ولا بأس ولا يضر بالوضوء.\nأما إذا كان لها جسم لها جرم يعني يمنع الماء فهذا يزال عند الوضوء كالمناكير التي يوضع على الأظفار هذه عند الوضوء تزال؛ لأن لها جرماً يمنع الماء. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7172/حكم-الاصباغ-التي-توضع-على-الوجه-والشفاه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_147/14707.mp3","categories":["اللباس والزينة"]},{"id":9015,"question":"بارك الله فيكم، الأخت السائلة (م. م. س) من الخبر تسأل مجموعة من الأسئلة، في سؤال لها تقول: هل يجوز إنزال الجنين قبل بلوغه أربعين يوماً من بطن أمه وما هو العقاب لمن فعل ذلك؟","title":"حكم إسقاط الجنين قبل بلوغه الأربعين يوماً","answer":"الجواب: إذا كان هناك حاجة شديدة ومصلحة شرعية لإنزاله في الأربعين ومضرة من بقائه فقد أجاز هذا جمع من أهل العلم، أما إذا لم يكن هناك مصلحة شرعية ولا حاجة ضرورية فينبغي بقاؤه؛ لأن إنجاب الأولاد وتكثير الأمة أمر مطلوب شرعاً، ولهذا يقول ﷺ: تزوجوا الولود الودود فإني مكاثر بكم الأمم يوم القيامة، فإذا كانت هناك حاجة شديدة لأن المرأة يضرها الحمل وعندها أطفال كثيرون صغار وتخشى من عدم القيام بواجب التربية الشرعية فلا مانع من إنزاله في الأربعين الأولى.\nأما إذا كان إنزاله من أجل سوء الظن بالله أو أنه قد يعسر عليهم النفقة هذا غلط، أو كان لغير أسباب إنما هو للترفه فلا ينبغي هذا أيضاً كذلك ولا يجوز. نعم.","link":"https://binbaz.org.sa/fatwas/7173/حكم-اسقاط-الجنين-قبل-بلوغه-الاربعين-يوما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_147/14708.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":9016,"question":"هل يجوز للمرأة أخذ ما يمنع الحمل؟","title":"حكم تعاطي الحبوب المانعة للحمل","answer":"الجواب: كذلك هذا محل نظر، إذا كان لحاجة ومصلحة مثل المضرة التي تضر المرأة في متابعة الحمل بقول الأطباء، أو لديها أطفال صغار يشق عليها تربيتهم فلها أن تأخذ الموانع، مثل السنة الأولى من سنة الرضاعة السنتين حتى يحصل لها القوة على تربية الأولاد والسلامة من آثار الولادة المتتابعة.\nفالمقصود أنه إذا كان لأمر شرعي ومصلحة شرعية كتربية الأولاد الصغار والعناية بهم، أو هناك مضرة عليها بقول الأطباء أن حملها هذا على هذا يضرها كثيراً فلا مانع من تعاطي الحبوب المانعة لمدة سنة أو سنتين. نعم.","link":"https://binbaz.org.sa/fatwas/7174/حكم-تعاطي-الحبوب-المانعة-للحمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_147/14709.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":9018,"question":"إذا ظهر على ذراع المرأة الشعر فهل لها إزالته؟","title":"حكم إزالة المرأة للشعر إذا ظهر على ذراعها","answer":"الجواب: لها أن تزيله من ذراعها ومن ساقها لا بأس، لا نعلم شيء يمنع من ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/7176/حكم-ازالة-المراة-للشعر-اذا-ظهر-على-ذراعها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_147/14711.mp3","categories":["اللباس والزينة"]},{"id":9034,"question":"نعود في بداية هذه الحلقة إلى رسالة الأخت (ع. ع) من الأحساء، أختنا عرضنا جزءًا من أسئلتها في حلقة مضت، وفي هذه الحلقة بقي لها عدد من الأسئلة، فتسأل هذا السؤال وتقول: هل يجوز خلع الحجاب بين صديقاتي أثناء زيارتي لهن، علمًا بأن المكان خال من الرجال، وأن رجال البيت على علم بأننا في داخله، أرجو التوضيح جزاكم الله خيرًا؟","title":"حكم خلع المرأة حجابها بين النساء","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:  فلا حرج في خلع المرأة حجابها عند النساء كالخمار الذي على رأسها أو العباءة التي عليها ونحو ذلك لا بأس بذلك؛ لأن المرأة ليس لها ولا عليها أن تتحجب عن المرأة، ولو كانت كافرة على الصحيح، حتى ولو كانت المرأة كافرة كبعض الخادمات، لا يجب على المرأة أن تحتجب عن المرأة، سواءً كانت على دينها أو ليست على دينها في أصح قولي العلماء من جهة الكافرة، وبعض أهل العلم يقول: إنها تحتجب عن الكافرة؛ لأن الله قال: أَوْ نِسَائِهِنَّ [النور:31].\nوالصواب: أنه لا يجب الاحتجاب عن الكافرة بل هي كالمسلمة، ولكن لا يجوز استقدام الكافرات لهذه البلاد السعودية؛ لأنها الجزيرة والرسول ﷺ أمر بإخراج الكفار من الجزيرة.\nفالحاصل أنه لا حرج في خلع المرأة حجابها عند النساء إذا كان المكان ليس فيه أجنبي وليس فيه من تظن أنهم ينظرون إليها ويتحيلون في النظر إليها إذا كان المكان مأمونًا فلا بأس، نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7192/حكم-خلع-المراة-حجابها-بين-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_178/17801.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":9036,"question":"تسأل أختنا وتقول: هل يجوز لبس الفستان الأبيض والطرحة البيضاء ليلة الزواج، علمًا بأن أهل البلد يرتدون هذا النوع من الملابس ويرتدون أنواعًا أخرى؟","title":"حكم لبس المرأة الفستان الأبيض ليلة زواجها","answer":"الجواب: إذا كان ليس على صفة لباس الرجال فلا بأس؛ لأن الألوان كلها مباحة للجميع أخضر وأحمر وأبيض وأسود مباح للجميع للرجال والنساء، لكن ليس للرجل أن يتشبه بالمرأة وليس للمرأة أن تتشبه بالرجل لا في اللباس ولا في غيره، فإذا كان الملبس الأبيض الذي تلبسه بعض النساء في الزواج لا يشابه لباس الرجل بوجه من الوجوه ولا يحصل التشبه فلا حرج، لكن ترك ذلك إلى اللباس المعتاد للنساء أولى وأفضل وأحوط وأبعد عن الشبهة؛ لأن الغالب على الرجال لبس الأبيض فإذا ترك ذلك من النساء كان ذلك أحسن وأكمل وأبعد عن التشبه.\nثم هذا الذي يفعله الناس لا بد أن يكون بين النساء، أما ما يفعله بعض الناس من ..... التي تفعلونها في ليلة العرس ليلة الزفاف ويدخل الرجل على النساء كاشفات هذا لا يجوز هذا منكر، بل إذا كان ولابد يجعلونها في غرفة خاصة ويدخل عليها زوجها في الغرفة الخاصة، أما أن تجعل فوق سرير أو فوق محل مرتفع ويدخل عليها الرجل بين النساء وهن كاشفات، أو يدخل عليها ويقبلها عند الناس هذا كله من قلة الحياء ولا يجوز، بل يجب الحذر من ذلك، نعم.\nالمقدم: جزاكم الله خيرًا ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/7194/حكم-لبس-المراة-الفستان-الابيض-ليلة-زواجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_178/17802.mp3","categories":["اللباس والزينة"]},{"id":9046,"question":"كما تلقى البرنامج رسالة المستمع الأخ: عبده حسن اليماني من الجمهورية العربية اليمنية، يسأل فيها السؤال التالي: ما حكم لبس الكمر من قبل المحرم ليحفظ فيه نقوده، هل يجوز له ذلك أم يعتبر ذلك مخيط لا يجوز لبسه؟ أفيدونا جزاكم الله خيراً.","title":"حكم لبس الكمر للمحرم","answer":"الجواب: لا حرج في ذلك، لبس الكمر ونحوه لا حرج في ذلك، كرباط وسطه بحزام، أو منديل أو غير ذلك؛ كل هذا لا حرج فيه؛ لأنه يربط إزاره، ويعينه على ضبط ردائه أيضاً، ويحفظ له حاجته من النقود وغيرها، فلا حرج في ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/7214/حكم-لبس-الكمر-للمحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_224/22411.mp3","categories":["اللباس والزينة","محظورات الإحرام","قضايا المرأة"]},{"id":9071,"question":"الرسالة التالية وصلت إلى البرنامج من المستمع: محمد بن علي بن عبدالوهاب من عمان، ضمن رسالته قول الله : يَا أَيُّهَا الَّذِينَ آمَنُوا لا تَقْتُلُوا الصَّيْدَ وَأَنْتُمْ حُرُمٌ وَمَنْ قَتَلَهُ مِنْكُمْ مُتَعَمِّدًا فَجَزَاءٌ مِثْلُ مَا قَتَلَ مِنَ النَّعَمِ يَحْكُمُ بِهِ ذَوَا عَدْلٍ مِنْكُمْ هَدْيًا بَالِغَ الْكَعْبَةِ أَوْ كَفَّارَةٌ طَعَامُ مَسَاكِينَ أَوْ عَدْلُ ذَلِكَ صِيَامًا لِيَذُوقَ وَبَالَ أَمْرِهِ [المائدة:95] ويسأل: هل يجوز للمحرم أن يقتل الحيوان الضار ليتفادى شره وأذاه؟ وكيف يتصرف، أفيدونا أفادكم الله؟","title":"حكم قتل الحيوانات الضارة للمحرم","answer":"الجواب: أما الصيد فليس له قتله، كما نص الله على هذا في قوله جل وعلا: لا تَقْتُلُوا الصَّيْدَ وَأَنْتُمْ حُرُمٌ [المائدة:95] فالمحرم لا يقتل الصيد: كالضبي والأرنب والوعل ونحو ذلك والحبارى ونحو ذلك، ممنوع من قتل الصيد حتى يحل من إحرامه.\nأما الحيوان الضار كالذئب والكلب الذي تعدى عليه، أو بعض الطيور الضارة كالغراب والعقاب ونحو ذلك لا بأس أن يقتلها، النبي ﷺ قال: خمس من الدواب كلهن فواسق يقتلن في الحل والحرم: الغراب والحدأة والعقرب والفأرة والكلب العقور ...... في رواية: والحية وفي بعضها: والذئب العادي فالفواسق تقتل هذه الخمس وما جاء في معناها الغراب وشر منه العقاب والحدية وأشباهها، والفأرة تقتل والعقرب والكلب العقور والحية، وما أشبهها مما يؤذي كالذئب، وأشباه ذلك مما يؤذي وكبقية الحشرات المؤذية: كالبعوض والذباب وشبه ذلك، كل هذا جائز للمحرم أن يقتله؛ لأنه من الفواسق، ولا حول ولا قوة إلا بالله. نعم.","link":"https://binbaz.org.sa/fatwas/7232/حكم-قتل-الحيوانات-الضارة-للمحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_225/22504.mp3","categories":["اللباس والزينة","محظورات الإحرام","قضايا المرأة"]},{"id":9078,"question":"السؤال الثاني في رسالة الأخ أحمد الشريف محمد إسماعيل من الأردن عمان يقول فيه: هل يجوز للحاج قتل الذباب والنمل والحشرات المؤذية والحيوانات الضارة مثل: الكلب العقور والأفاعي وما شابه ذلك؛ اتقاء شرها؟ وهل في ذلك إثم أفيدونا أفادكم الله؟","title":"حكم قتل المحرم للحيوانات والحشرات الضارة والمؤذية","answer":"الجواب: ليس هناك حرج في قتل المؤذيات كالذباب والبعوض وأشباه ذلك مما يؤذي الإنسان، وهكذا قتل الكلب العقور والحية والعقرب والفأرة والغراب، فقد صح عن رسول الله عليه الصلاة والسلام أنه قال: خمس من الدواب كلهن فواسق، يقتلن في الحل والحرم: الغراب والحدأة والعقرب والفأرة والكلب العقور زاد في رواية: والحية في بعضها: والذئب العادي كل هذا لا بأس به.\nفالمؤذيات المعروفة من البعوض ..... والذباب والحية والعقرب والكلب العقور والحديا والغراب والفأرة، كل هذه تقتل في الحل والحرم. نعم.","link":"https://binbaz.org.sa/fatwas/7246/حكم-قتل-المحرم-للحيوانات-والحشرات-الضارة-والموذية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_226/22608.mp3","categories":["اللباس والزينة","محظورات الإحرام","قضايا المرأة"]},{"id":9079,"question":"كما بعث المستمع عبد الله أحمد فضل السيد من جمهورية السودان الديمقراطية الخرطوم، برسالة إلى البرنامج يقول في بدايتها:بسم الله الرحمن الرحيم، وصلى الله على سيدنا محمد وآله وصحبه أجمعين، والحمد لله رب العالمين، إنني أنصت إلى برامجكم اليومية وخاصة برنامج نور على الدرب، والتي تجيبون فيه على أسئلة المستمعين الدينية، وبهذه المناسبة أود أن أطرح على حضراتكم بعض الأسئلة أرجو الإجابة عليها لما فيه خير الإسلام والمسلمين، يقول في سؤاله الأول: هل يجوز للمحرم أن يغتسل وأن يغير ملابس إحرامه إذا اتسخت؟ وهل يجوز له أن يستعمل الصابون ذا الرائحة الزكية؟ وأيضاً هل يباح للمحرم نفض شعره وتمشيطه وتغطية وجهه اتقاءً من غبار أو عاصفة أو سموم أفيدونا أفادكم الله؟","title":"حكم اغتسال المحرم واستعماله الصابون وتغيير ملابسه","answer":"الجواب: يجوز للمحرم أن يغتسل، فقد اغتسل النبي ﷺ وهو محرم عليه الصلاة والسلام، فلا بأس أن يغتسل المحرم وهو محرم، لا بأس أن يغتسل المحرم ولا بأس أن يغير ملابسه إذا اتسخت أو لم تتسخ لا بأس أن يغيرها، يلبس إزار بدل إزار ورداء بدل رداء وهكذا المرأة لا بأس أن تغير ملابسها قميص بدل قميص، إزار بدل إزار، سراويل بدل سراويل، خمار بدل خمار، فنيلة بدل فنيلة، كل هذا لا بأس به، كذلك شراب بدل شراب، كله لا بأس به لا من الرجل ولا من المرأة، وهكذا استعمال السدر والصابون والشامبو وأشباه ذلك كل هذا لا بأس به، لكن الصابون إذا كان من النوع الزكي الرائحة كالممسك تركه أحوط؛ لأن فيه رائحة من الطيب، تركه للمحرم يكون أحوط وأولى، كل هذه أمور والحمد لله لا بأس بها. نعم.","link":"https://binbaz.org.sa/fatwas/7241/حكم-اغتسال-المحرم-واستعماله-الصابون-وتغيير-ملابسه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_226/22603.mp3","categories":["اللباس والزينة","محظورات الإحرام","قضايا المرأة"]},{"id":9081,"question":"ويقول: هل يباح للمحرم نفض شعره أو نقض شعره وتمشيطه وتغطية وجهه اتقاءً من غبار أو عاصفة أو سموم؟","title":"حكم نقض الشعر وتمشيطه وتغطية الوجه للمحرم","answer":"الجواب: لا بأس، لا بأس أن ينقض شعره من غير قطع الشعر، لا بأس أن ينقض شعره ويغسله كما أمر النبي ﷺ عائشة أن تنقض شعرها وهي محرمة، وتحرم بالحج وهي كانت أحرمت بالعمرة، لكن لما وصلت إلى قرب مكة جاءها الحيض، قبل أن تؤدي مناسك العمرة، فقال لها النبي ﷺ: انقضي رأسك وامتشطي وافعلي ما يفعله الحجاج غير أن لا تطوفي بالبيت حتى تطهري فأذن لها في نقض شعرها وتمشيطها وهي محرمة، فلا بأس أن ينقض شعره المحرم، ويمتشط بغير الطيب كل هذا لا بأس به، كذلك لا بأس أن يغير ملابسه كما تقدم، كله لا بأس به. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7242/حكم-نقض-الشعر-وتمشيطه-وتغطية-الوجه-للمحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_226/22604.mp3","categories":["اللباس والزينة","محظورات الإحرام","قضايا المرأة"]},{"id":9084,"question":"السؤال الثاني في رسالة الأخ عبد الله أحمد فضل السيد من جمهورية السودان الديمقراطية يقول فيه: هل يجوز للحاج المحرم فقع الدمل والحجامة وربط الجرح وتنظيفه؟ وما حكم نزع الضرس أو السن وأخذ الحقن أفيدونا أفادكم الله؟","title":"حكم فقع الدمامل الحجامة وربط الجرح وقلع السن للمحرم","answer":"الجواب: كل هذا لا بأس به، له أن يحتجم وله أن يفقع الدمل ونحوه لاستخراج أذاه، وله أن يربط الجرح وله أن يقلع السن، كل هذه أمور لا بأس بها في حق المحرم، وقد احتجم النبي وهو محرم عليه الصلاة والسلام، فلا حرج في ذلك. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7243/حكم-فقع-الدمامل-الحجامة-وربط-الجرح-وقلع-السن-للمحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_226/22605.mp3","categories":["اللباس والزينة","محظورات الإحرام","قضايا المرأة"]},{"id":9085,"question":"هذه رسالة وصلت إلى البرنامج من المستمعة فوزية محمد صالح أبو محمود من العراق تقول فيها: هل يجوز للمرأة المحرمة التطيب والاكتحال والخضاب -الحناء-، ووضع طلاء الأظافر وتقليمها قبل الإحرام أو بعده، أفيدونا أفادكم الله، وجزاكم عنا خير الجزاء؟","title":"حكم التطيب والاكتحال والخضاب بالحناء وطلاء الأظافر للمحرمة","answer":"الجواب: أما قبل الإحرام فلا بأس لها أن تكتحل، ولها أن تقلم الأظافر ولها أن تتحنى، ولها أن تضع محل الأظافر من الأشياء التي تضعها من مناكير وغيرها، هذا قبل الإحرام، ولها أن تضع الطيب لكن ... يكون طيباً خفيفاً ليس له رائحة كبيرة، لأنها قد تخالط الناس فالأولى أن يكون طيبها خفيفاً ليس له رائحة ظاهرة، بل يكون رائحة داخلية، لمن اتصل بها من نسائها وقبلها من نسائها واجتمع بها، ولا يكون رائحته كبيرة يحصل به الفتنة، هذا كله يباح قبل الإحرام، والمناكير تركها أولى التي توضع على الأظفار؛ لأنها قد تمنع من ماء الوضوء، لكن إذا كانت تزيلها عند الوضوء وعند الغسل فلا بأس، وإن تركتها بالكلية كان أحسن لها وأحوط؛ لأنها قد تنساها عند الوضوء، وقد تنساها عند الغسل، وهي فيما بلغنا لها جسم ولها جرم تمنع الماء، وأما بعد الإحرام فليس لها أن تتطيب إذا أحرمت إذا لبت بالعمرة أو بالحج ونوت الدخول في الحج أو العمرة بقلبها، فإنها لا تمس الطيب، أما الكحل فلا يضر لو اكتحلت بعد الإحرام لا يضر، لكن ليس لها أن تطيب بعد الإحرام، وليس لها أن تقلم أظفارها، ولا أن تأخذ شيئاً من شعرها بعد الإحرام ما دام تنوي الدخول في الحج أو في العمرة، فإنها حينئذ تلبي وتمتنع من الطيب، وتمتنع من قلم الأظفار ومن قص الشعر ونحو ذلك، أما الحناء فأمره واسع، يجوز قبل الإحرام وبعد الإحرام، وهكذا الكحل قبل الإحرام وبعد الإحرام، لكن تركها غير مكتحلة وغير متحنية بعد الإحرام يكون أحسن لأنها حالة تقشف وحالة إقبال على العبادة وليست حالة تجمل، فترك الكحل بعد الإحرام وترك الحناء بعد الإحرام أولى حتى تنتهي من إحرامها، وهكذا الملابس الجميلة تركها أولى، تحرم في ملابس غير جميلة وغير لافتة للنظر، وإذا حلت من إحرامها اكتحلت وفعلت ما ترى من الطيب أو غير ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/7249/حكم-التطيب-والاكتحال-والخضاب-بالحناء-وطلاء-الاظافر-للمحرمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_226/22611.mp3","categories":["اللباس والزينة","محظورات الإحرام","قضايا المرأة"]},{"id":9086,"question":"السؤال الثالث في رسالة الأخ عبد الله أحمد فضل السيد من جمهورية السودان الديمقراطية يقول فيه: أرجو إفادتي عن إذا لبس المحرم ساعة يد أو لبس خاتماً من ذهب، كما أرجو إفادتي هل يجوز للمحرم الاكتحال أفيدونا أفادكم الله؟","title":"حكم لبس الساعة والخاتم من الذهب للمحرم","answer":"الجواب: أما لبس الخاتم من الذهب فلا يجوز للرجل، لا في الإحرام ولا في غير الإحرام، الذهب من خصائص النساء، تلبس المرأة الذهب من الخواتم والأسورة والقلائد لا بأس، أما الرجل فليس له أن يلبس خاتم الذهب، قد نهى النبي ﷺ عن التختم بالذهب: ولما رأى رجلاً في يده خاتم من ذهب نزعه، وقال: يعمد أحدكم إلى جمرة من نار فيضعها في يده فلا يجوز له أن يلبس الذهب.\nوأما الساعة فتركها أحوط، إذا كانت من غير الذهب، تركها في حال الإحرام أحوط، ولا نعلم مانعاً من لبسها في الإحرام؛ لأنها يحتاج إليها، إذا كانت من غير الذهب ولا من الفضة لا بأس أن يلبسها للحاجة إليها، وإن جعلها في كمره أو في إزاره للرجوع إليها وترك لبسها فهذا حسن إن شاء الله من باب الحيطة؛ لأن المحرم ممنوع من لبس المخيط، وما يشبهه، وهذه قد تشبه القفازين شبه الخفين من بعض الوجوه، فإذا ترك لبسها يكون من باب الاحتياط: دع ما يريبك إلى ما لا يريبك وإن لبسها فنرجو أن لا يكون عليه شيء إذا كانت من غير الذهب والفضة، وهذا في حق الرجل، أما المرأة فلا حرج عليها في ذلك، سواء كانت الساعة من ذهب أو من فضة أو غير ذلك. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7244/حكم-لبس-الساعة-والخاتم-من-الذهب-للمحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_226/22606.mp3","categories":["اللباس والزينة","محظورات الإحرام","قضايا المرأة"]},{"id":9126,"question":"هذه الرسالة التي وردت إلى البرنامج من طالب علم كنا قد وعدنا مرسلها بإتمام أسئلته في هذه الحلقة، السؤال الثاني في رسالة الأخ طالب علم يقول فيه: قال ﷺ: خالفوا المشركين وفروا اللحى وأحفوا الشوارب، وقال في والد أبي بكر: غيروا شعره وجنبوه السواد، ما حكم صبغ الشعر للنساء والرجال إذا صح هذا الحديث أفيدونا أفادكم الله؟","title":"حكم حلق اللحى وصبغ الشعر","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله رب العالمين، والصلاة والسلام على عبده ورسوله وخيرته من خلقه وأمينه على وحيه نبينا وإمامنا وسيدنا محمد بن عبد الله، وعلى آله وأصحابه ومن سلك سبيله واهتدى بهداه إلى يوم الدين.\nأما بعد: فهذان الحديثان صحيحان ثابتان عن النبي عليه الصلاة والسلام، فالأول: من حديث ابن عمر ، يقول النبي ﷺ: أحفوا الشوارب ووفروا اللحى، وفي لفظ آخر: قصوا الشوارب وأعفوا اللحى خالفوا المشركين، متفق على صحته من حديث ابن عمر رضي الله تعالى عنهما، وروى مسلم في الصحيح عن أبي هريرة  أن النبي ﷺ أنه قال: جزوا الشوارب وأرخوا اللحى خالفوا المجوس، فهذا يدل على وجوب إكرام اللحى وتوفيرها وإعفائها وإرخائها وأنه لا يجوز للمسلم قصها ولا حلقها، أما ما وقع فيه الكثير من الناس اليوم فهو مؤلم ومحزن ولا ينبغي للمسلم أن يتأسى بأحد في ذلك، فإن الأسوة هو رسول الله عليه الصلاة والسلام ومن سار على نهجه من أهل الخير، أما من خالف نهج الرسول ﷺ وخالف أمره بحلق اللحية أو قصها فليس بقدوة، بل ينبغي أن ينصح بل يجب أن ينصح وأن ينكر عليه ويوجه إلى الخير ولا يقتدى به.\nأما الشوارب فالواجب قصها وإحفاؤها وعدم إطالتها؛ لأن إطالتها مشابهة للمشركين ولا سيما المجوس ، فإنهم يطيلون شواربهم، فالرسول ﷺ أمر بقصها وأمر بجزها، قال أبو محمد بن حزم -وهو من الكبار المعروفين بمعرفة مقالات العلماء- قال: اتفق العلماء على أن إعفاء اللحى وتوفيرها وقص الشوارب أمر مفترض، فحكى الإجماع على أن قص الشوارب مفترض، وعلى أن إعفاء اللحية وتوفيرها أمر مفترض فلا يجوز للمسلم أن يخالف سنة الرسول ﷺ وإجماع أهل العلم في ذلك.\nأما الحديث الثاني: وهو قوله ﷺ في قصة والد أبي بكر: غيروا هذا الشعر وجنبوه السواد، فليس لفظ الحديث هكذا، لفظ الحديث: غيروا هذا الشيب، يقول النبي ﷺ: غيروا هذا الشيب واجتنبوا السواد رواه مسلم في الصحيح وغيره، ومعنى هذا الحديث الدلالة على أن الشيب يغير وأن السنة تغييره ومن هذا قوله ﷺ: إن اليهود والنصارى لا يصبغون فخالفوهم، فالسنة للمسلم أن يغير شيبه وهكذا المرأة تغير شيبها، لكن بغير السواد، ولهذا قال: اجتنبوا السواد، فيغير الشيب بالحمرة والصفرة والسواد المخلوط بالحمرة لا بأس، كان أبو بكر وعمر يخضبان بالحناء والكتم، وروي عن النبي ﷺ أنه خضب بالحناء والكتم، يعني: بالسواد المخلوط بالكتم يصبغ سواداً والحناء حمرة فإذا اجتمعا صارا سواداً بحمرة فإذا خضب بالسواد المخلوط بالحمرة فلا بأس، أما السواد الخالص فلا يجوز لهذا الحديث ولأحاديث أخرى جاءت في المعنى تدل على تحريم الصبغ بالسواد، ومن هذا ما رواه أبو داود والنسائي وجماعة بإسناد صحيح عن ابن عباس رضي الله عنهما عن النبي ﷺ أنه قال: يكون في آخر الزمان قوم يخضبون بالسواد كحواصل الحمام لا يريحون رائحة الجنة، وهذا وعيد عظيم يوجب الحذر. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7285/حكم-حلق-اللحى-وصبغ-الشعر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_229/22901.mp3","categories":["الأخلاق المذمومة","سنن الفطرة","اللباس والزينة"]},{"id":9131,"question":"السؤال الثالث في رسالة الأخ طالب علم يقول فيه: قال عليه الصلاة والسلام: ما أسفل من الكعبين فهو في النار، وقال: من جر إزاره بطراً لم ينظر الله إليه يوم القيامة أفيدونا أفادكم الله؟","title":"حكم الإسبال للرجال والنساء","answer":"الجواب: نعم هذان الحديثان صحيحان، عن النبي صلى الله عليه وسلم، الأول: يقول ﷺ: ما أسفل من الكعبين من الإزار فهو في النار، خرجه البخاري في الصحيح من حديث أبي هريرة ، وهو يدل على تحريم الإسبال وأنه لا يجوز للمسلم أن يجر ملابسه تحت الكعبين، كالسراويل والإزار والبشت والقميص ونحو ذلك، ومثله الإزار من باب التمثيل ليس من باب التخصيص بل من باب التمثيل، ولهذا جاء في الحديث الآخر يقول عليه الصلاة والسلام: إياك والإسبال فإنه من المخيلة وعمم عليه الصلاة والسلام، وفي الحديث الآخر يقول: من جر ثوبه خيلاء لم ينظر الله إليه يوم القيامة، والثوب يعم القميص ويعم السراويل ويعم الإزار ويعم البشت ويعم كل الملابس، ثوب.. من جره خيلاء لم ينظر الله إليه يوم القيامة، فينبغي للمؤمن بل الواجب عليه أن يحذر هذا الإسبال، وفي الباب حديث آخر عظيم صحيح يقول ﷺ: ثلاثة لا يكلمهم الله، ولا ينظر إليهم يوم القيامة، ولا يزكيهم ولهم عذاب أليم: المسبل إزاره، والمنان فيما أعطى، والمنفق سلعته بالحلف الكاذب، وخرجه مسلم في صحيحه.\nفهذا الحديث العظيم يدل على أن هذه الأمور من الكبائر فالإسبال، من الكبائر، والمن في العطية من الكبائر، والحلف الكاذب من الكبائر، قال تعالى: يَا أَيُّهَا الَّذِينَ آمَنُوا لا تُبْطِلُوا صَدَقَاتِكُمْ بِالْمَنِّ وَالأَذَى [البقرة:264] فالواجب على المؤمن أن يحذر الإسبال، ويحذر المن في العطية، ويحذر تنفيق سلعته بالأيمان الكاذبة، فالتجار الذين يدرجون السلع بالأيمان الكاذبة على خطر عظيم، وهكذا المن بالعطية من الكبائر، فعليك يا عبد الله أن تحذر ما حرم الله عليك من إسبال الملابس سواء كانت أزراً أو قمصاً أو بشوتاً أو أزراً عليك أن تحذر ذلك، وثبت أن عمر  في مرضه بعد طعنه قبل أن يموت رأى شاباً يمس ثوبه الأرض، فقال: ادعوه لي، فدعاه وقال: يا بني! ارفع ثوبك فإنه أتقى لربك وأنقى لثوبك أو كما قال رحمه الله ورضي عنه، فبين  أن رفع الثوب أتقى للرب وأنقى للثوب، فجر الثياب وسيلة لغضب الله ووسيلة للأوساخ تلطيخها بالأوساخ والنجاسات.\nفالواجب على المؤمن أن يحذر ذلك طاعة لله ولرسوله وحذراً من صفات المتكبرين، وإذا جرها عن كبر صار أعظم في الإثم جرها وسحبها وإرخاؤها تحت الكعبين منكر، ولكن إذا كان عن كبر وعن قصد للكبر صار أشد في النكارة وأشد في الإثم، نسأل الله السلامة.\nوهذا خاص بالرجال أما المرأة فلها أن ترخي لكن لا لقصد الكبر لكن لقصد الستر، ترخي ثوبها حتى تستر قدميها هذا مشروع لها لأنها عورة فالرسول ﷺ أذن لها في الإرخاء حتى تستر قدميها عن الرجال، بخلاف الرجل فليس بعورة قدماه فلا يجر ثوبه ولا بشته ولا غيرهما، وفق الله الجميع. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7287/حكم-الاسبال-للرجال-والنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_229/22902.mp3","categories":["اللباس والزينة"]},{"id":9134,"question":"والسؤال الرابع في رسالة الأخ طالب علم يقول فيه: وقال عليه الصلاة والسلام: أيما امرأة خرجت بزينتها لعنتها الملائكة حتى ترجع، إذا صح هذا الحديث فما حكم النساء اللاتي تخرجن إلى الأسواق وإلى الأفراح وليالي الزفاف بكامل زينتهن، علماً أنهن يختلطن بالنساء في الأفراح فقط أما في الأسواق فقد يختلطن بالرجال مثل أصحاب المتاجر أفيدونا أفادكم الله؟","title":"حكم خروج المرأة بزينتها كاملة","answer":"الجواب: لا أعرف هذا الحديث بهذا اللفظ: أيما امرأة خرجت بزينتها لعنتها الملائكة حتى ترجع، لا نعرف هذا الحديث بهذا اللفظ ولكن معناه في الجملة صحيح إذا لم تستتر ولم تحتجب، والله يقول جل وعلا في كتابه العظيم: وَقَرْنَ فِي بُيُوتِكُنَّ وَلا تَبَرَّجْنَ تَبَرُّجَ الْجَاهِلِيَّةِ الأُولَى [الأحزاب:33]، فإذا خرجت في زينتها متبرجة تبدي زينتها للناس للرجال، من العنق والوجه والشعر والقلائد ونحو ذلك أو بالتكسر والتغنج في كلامها مع الرجال هذا خطر عظيم، أما إذا خرجت بزينة لها للأفراح أو لزيارة أهلها أو غيرهم ممن تجوز زيارته مع التستر والحجاب والبعد عن إظهار الزينة للرجال والفتنة فلا حرج في ذلك، وإنما جاء هذا اللفظ فيما يتعلق بإغضاب الزوجة لزوجها، يقول ﷺ: أيما امرأة باتت وزوجها عليها غضبان لعنتها الملائكة حتى تصبح، هكذا جاء الحديث الصحيح عن رسول الله ﷺ: أيما امرأة باتت وزوجها غضبان عليها لعنتها الملائكة حتى تصبح، وفي اللفظ الآخر: كان الذي في السماء ساخطاً عليها حتى يرضى عنها.\nفالواجب على المرأة أن تحذر غضب زوجها وأن تسمع وتطيع له في المعروف، حتى لا تلعنها الملائكة وحتى لا يغضب الله عليها ولا ملائكته، لكن إذا كان إغضابها له في الحق بأن أمرها بمعصية الله فأبت عليه وغضب فلا حق له في هذا، ولا خطأ عليها في ذلك بل هي مأجورة، إذا قال لها مثلاً: اكشفي لأخي أو لزوج أختك أو للأقارب من بني عمها وأخوالها فلا طاعة له في هذا؛ لأن هذا معصية أو قال لها: اشربي الخمر أو اشربي الدخان، هذا منكر ليس لها طاعته في ذلك أو ما أشبهها من المعاصي، فالرسول يقول عليه الصلاة والسلام: إنما الطاعة في المعروف، لا طاعة لمخلوق في معصية الخالق، والله ولي التوفيق.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7289/حكم-خروج-المراة-بزينتها-كاملة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_229/22903.mp3","categories":["اللباس والزينة","الحكم على الأحاديث","قضايا المرأة"]},{"id":9157,"question":"السؤال الثاني في رسالة المستمعة أم عبد الله من الرياض، تقول فيه: إذا لبست المرأة ثوباً يبين معالم جسدها من ظهر وأكتاف وما يلي ذلك، هل هو حرام أم حلال، أفيدونا أفادكم الله؟","title":"حكم لبس المرأة ثوباً ضيقاً يبين مفاتنها","answer":"الجواب: إذا كان الثوب ضيقاً يبدي حجم أعضائها وعورتها لم يجز، أما إذا كان وسطاً، يستر بدنها، ولا يبين حجم أعضائها؛ فلا بأس به، وكذلك لابد أن يكون ساتراً، صفيقاً، ما يكون رقيق؛ لأن الرقيق يبين العورة، يبين نور اللحم من حمرة وبياض ونحو ذلك، فلابد أن يكون صفيقاً ساتراً واسعاً بعض السعة، ليس بضيق يبين حجم آليتها وفرجها ونحو ذلك، بل يكون وسطاً في الأمور، لا واسعاً ولا ضيقاً، ويكون صفيقاً لا رقيقاً، ساتراً للبدن، والله أعلم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7323/حكم-لبس-المراة-ثوبا-ضيقا-يبين-مفاتنها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_232/23205.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":9161,"question":"السؤال الثالث في رسالة الأخت أم عبدالله من الرياض، تقول فيه: هل ظهور الذراعين من وراء العباءة، مع العلم بأنهما عاريتين حلال أم حرام، أفيدونا أفادكم الله؟","title":"حكم إظهار المرأة ذراعيها","answer":"الجواب: لا، عورة، الذراعان عورة، والكفان عورة عند جمع من أهل العلم أيضاً، لكن الذراعان أشد، فالواجب سترهما بغير العباءة، إذا كانت العباءة رقيقة تبين ما وراءها، فلابد من سترها بغير ذلك، كقميص ونحوه. نعم.","link":"https://binbaz.org.sa/fatwas/7324/حكم-اظهار-المراة-ذراعيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_232/23206.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":9165,"question":"السؤال الرابع والأخير في رسالة المستمعة أم عبدالله من الرياض، تقول فيه: هل قص الشعر حرام أم حلال، أفيدونا أفادكم الله؟","title":"هل قص الشعر للنساء حرام؟","answer":"الجواب: قص الشعر إذا كان وافراً للتخفيف، فلا بأس، إذا قصت من شعرها المرأة للتخفيف فلا بأس، فقد ثبت أن أزواج النبي ﷺ قصوا من رءوسهن بعد وفاته عليه الصلاة والسلام للتخفيف، عليه الصلاة والسلام ورضي الله عنهن.\nفالمقصود أن القص إذا كان للتخفيف وليس لقصد التشبه بالرجال، ولا لقصد التشبه بالكافرات؛ وإنما تقص ذلك للتخفيف، فلا بأس بذلك. نعم.","link":"https://binbaz.org.sa/fatwas/7325/هل-قص-الشعر-للنساء-حرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_232/23207.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":9170,"question":"السؤال الرابع والأخير في رسالة المستمعة أم عبدالله من الرياض، تقول فيه: هل قص الشعر حرام أم حلال، أفيدونا أفادكم الله؟","title":"هل قص الشعر للنساء حرام؟","answer":"الجواب: قص الشعر إذا كان وافراً للتخفيف، فلا بأس، إذا قصت من شعرها المرأة للتخفيف فلا بأس، فقد ثبت أن أزواج النبي ﷺ قصوا من رءوسهن بعد وفاته عليه الصلاة والسلام للتخفيف، عليه الصلاة والسلام ورضي الله عنهن.\nفالمقصود أن القص إذا كان للتخفيف وليس لقصد التشبه بالرجال، ولا لقصد التشبه بالكافرات؛ وإنما تقص ذلك للتخفيف، فلا بأس بذلك. نعم.","link":"https://binbaz.org.sa/fatwas/7325/هل-قص-الشعر-للنساء-حرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_232/23207.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":9174,"question":"ما حكم من ألبس جدار مجلسه ستائر تغطي حيطان المجلس الأربعة، علماً بأنه ليس فيه غير نافذة واحدة؟","title":"حكم تلبيس الجدار بالستائر","answer":"الجواب: ترك تلبيس الجدر الستر أولى وأفضل؛ لحديث إنا لم نؤمر أن نغطي الجدر، لكن ليس فيه محذور ليس بمحرم؛ لأنه لم ينه عنه فيما علمنا وإنما ذلك جائز وتركه أفضل، فلا حرج في ذلك إذا جعله إما للزينة وإما لترك الغبار، وإما لأسباب أخرى، لا حرج في ذلك إن شاء الله، لكن تركه أولى. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7334/حكم-تلبيس-الجدار-بالستاىر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_150/15008.mp3","categories":["اللباس والزينة"]},{"id":9200,"question":"أخ لنا من جامعة الملك فيصل بالأحساء عبدالوهاب خالد الحليبي فيما يبدو، أخونا بعث برسالة ضمنها مجموعة من الأسئلة يقول: شخص أراد العمرة فأحرم من الميقات فصادف برداً ومطراً شديداً، هل يجوز أن يلبس شيء على الإحرام ليقيه من البرد والمطر أم لا؟","title":"حكم ارتداء المحرم شيئاً فوق الإحرام عند المطر والبرد","answer":"فإنه لا مانع أن يغطي الرأس وعليه الفدية وهي إطعام ستة مساكين لكل مسكين نصف صاع من التمر أو غيره، أو صوم ثلاثة أيام، أو ذبح شاة أحد الثلاثة، هذا إذا خاف على نفسه من المضرة العظيمة إن لم يغط رأسه، أما كونه يلتحف على بدنه ببطانية أو مطرحة أو عباءة يطرحها عليه، لا يلبسها اللبس العادي بل يطرحها عليه لتوقي البرد والمطر فلا بأس بهذا ولا شيء فيه. نعم.","link":"https://binbaz.org.sa/fatwas/7360/حكم-ارتداء-المحرم-شيىا-فوق-الاحرام-عند-المطر-والبرد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_151/15108.mp3","categories":["اللباس والزينة","محظورات الإحرام","قضايا المرأة"]},{"id":9222,"question":"السؤال الثاني في رسالة المستمع (ش. ل. ي) سوداني مقيم بالعراق، يقول فيه: هل يجوز للرجل أن يتحلى بالذهب في أسنانه، أو في خاتم في إصبعه، أفيدونا أفادكم الله؟","title":"حكم التحلي بالذهب وتركيب أسنان من ذهب","answer":"الجواب: ليس للرجل أن يتحلى بالذهب، لا في خاتمه ولا غير ذلك، النبي ﷺ نهى عن التختم بالذهب، ولما رأى رجلاً في يده خاتم من ذهب نزعه وطرحه، وقال: يعمد أحدكم إلى جمرة من نار فيضعها في يد فلا يجوز للمسلم أن يتختم بالذهب، وإنما هذا من شأن النساء، يقول النبي ﷺ: أحل الذهب والحرير لإناث أمتي وحرم على ذكورهم.\nلكن الأسنان إذا دعت الحاجة إليها لا بأس، إذا دعت الحاجة إلى تركيب أسنان من ذهب فلا حرج للرجال والنساء، أما إذا تيسر أن يركب أسناناً من غير الذهب فهو أولى وأفضل وأحوط، وإن لم يجد ما ينفع واحتاج إلى أسنان من ذهب فلا بأس. نعم.","link":"https://binbaz.org.sa/fatwas/7382/حكم-التحلي-بالذهب-وتركيب-اسنان-من-ذهب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_233/23302.mp3","categories":["اللباس والزينة"]},{"id":9245,"question":"وهذه رسالة وردت إلى البرنامج من الإخوة أحمد عبدالعزيز ورجب وإبراهيم إخوة مصريون يعملون بالأردن يقولون في رسالتهم: شخص يتعلم اللغة الإنجليزية عن طريق الكتاب والشريط، وهذه الأشرطة بعضها مسجل بصوت امرأة، مع العلم أنه لا يمكن أن يستغني عن هذه الأشرطة فهل يجوز سماعها؟","title":"حكم الاستماع إلى صوت امرأة عبر شريط لغرض التعليم","answer":"الجواب: نعم يجوز ذلك إذا كان المقصود الفائدة والعلم، ليس المقصود التلذذ بصوتها، وإنما أراد من ذلك معرفة هذه اللغة الذي حصل له من طريقه التسجيل. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7403/حكم-الاستماع-الى-صوت-امراة-عبر-شريط-لغرض-التعليم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_235/23502.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":9283,"question":"أخت لنا من السودان أيضًا تسأل وتقول: ما حكم تخفيف الحواجب بالنسبة للنساء؟","title":"حكم تخفيف شعر الحواجب","answer":"الجواب: تخفيف الحواجب لا يجوز، الرسول ﷺ: لعن النامصة والمتنمصة فلا يجوز للمؤمن أن يسمح لزوجته أو أخته أو بنته بذلك، وهي في نفسها ليس لها أن تخالف أمر الله وأن تتعدى حدوده، بل يجب على المرأة أن تكف عما نهى الله عنه، ومن ذلك النمص فإنه من الكبائر؛ لأن الرسول ﷺ لعن من فعل ذلك، واللعن يقتضي أنه كبيرة من كبائر الذنوب سواء كان النمص بالمنقاش أو بأي آلة لأخذ شعر الحاجبين. نعم.","link":"https://binbaz.org.sa/fatwas/7446/حكم-تخفيف-شعر-الحواجب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_184/18402.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":9305,"question":"سؤالها الثاني: تقول: زوج خالتي تارك للصلاة رغم أنه حج إلى بيت الله، وقد ذكرت له خالتي ما سمعته من البرنامج من حكم تارك الصلاة تهاونًا من أنه يكون كافرًا كفرًا يخرج من الملة ولكنه ظل تاركًا للصلاة، وهي سكتت عن ذلك، فهل معاشرته لها حرام عليها؟ وهل تاركة الصلاة من النساء يجوز كشف الوجه أمامها باعتبار أنها كافرة بتركها للصلاة وخرجت عن ملة الإسلام، أفيدونا عن هذه القضايا وفقكم الله؟","title":"حكم معاشرة الزوج التارك للصلاة وكشف الوجه أمام الكافرة","answer":"الجواب: لا شك أن الذي يترك الصلاة كافر وإن لم يجحد وجوبها في أصح قولي العلماء؛ لما ثبت عن رسول الله عليه الصلاة والسلام أنه قال: بين الرجل وبين الكفر والشرك ترك الصلاة والمرأة كذلك في الحكم الشرعي؛ لأن القاعدة الشرعية أن الأحكام التي تثبت للرجال تكون للنساء، وهكذا العكس؛ لأن الجميع مكلف، والرسول ﷺ بعث للجميع وهكذا قوله ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر فالذي لا يصلي ليس لزوجته البقاء معه وهي مسلمة، ليس لها أن تبقى معه، بل عليها أن تفارقه وأن تمنعه من الاتصال بها حتى يتوب فيتوب الله عليه.\nوهكذا المرأة التي تترك الصلاة ليس لزوجها المسلم أن يبقى معها، بل يجتنبها حتى تتوب فإن تابت وإلا فارقها وسوف يعوضه الله خيرًا منها؛ لأن الله يقول سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا ۝ وَيَرْزُقْهُ مِنْ حَيْثُ لا يَحْتَسِبُ [الطلاق:2-3] ويقول سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4] وهذه من المصائب العظيمة، ترك الصلاة من المصائب العظيمة.\nفالواجب على المسلمين جميعًا أن يحذروا ذلك وأن يتناصحوا في ذلك، وأن يهجروا من ترك الصلاة، وأن لا يقبلوا دعوته، وأن لا يسلموا عليه، وأن لا يردوا عليه السلام، وأن لا يدعوه إلى وليمة ولا غيرها، بل يجب أن يهجر كالبعير الأجرب، لا يقرب ولا يزار إلا للدعوة إلى الله، إذا كان للدعوة يدعى وينصح فلا بأس.\nوأما طرح الخمار عند الكافرة فلا بأس على الصحيح، سواء كانت تاركة للصلاة أو يهودية أو نصرانية أو وثنية، لا حرج على المسلمة أن تراها الكافرة ولا تحتجب منها، هذا هو الصواب، وهذا هو الصحيح من قولي العلماء أن التحجب إنما يكون عن الرجل الأجنبي أما عن المرأة فلا، أما قول الله سبحانه: أَوْ نِسَائِهِنَّ [النور:31] فالمراد: نساء بني آدم، فالمرأة لا يحتجب عنها على الصحيح وإنما يحتجب عن الرجل الأجنبي الذي ليس بمحرم، وأما المرأة فإنها من جنس المرأة وإن كانت كافرة لا حرج على المسلمة أن لا تحتجب عنها؛ لأن الرسول ﷺ لم يأمر نساءه أن يحتجبن عن اليهوديات اللاتي كن في المدينة ولا عن غيرهن من الوثنيات، ولا نعلم أن امرأة من أزواج النبي ﷺ أو بناته احتجبت عن امرأة كافرة.\nوقد ثبت في الصحيحين عن أسماء بنت أبي بكر رضي الله تعالى عنهما أن أمها وفدت إليها في المدينة في وقت الصلح بين الرسول ﷺ وبين أهل مكة وهي كافرة، جاءت تطلب من بنتها الرفد والمساعدة، فاستأذنت أسماء الرسول ﷺ في أن تصلها فقال النبي ﷺ: صليها ولم يأمرها أن تحتجب عن أمها لأنها كافرة، والقضايا في هذا كثيرة كلها دالة على أنه ليس على المرأة المسلمة أن تحتجب عن المرأة الكافرة، والله ولي التوفيق. نعم.\nالمقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/7459/حكم-معاشرة-الزوج-التارك-للصلاة-وكشف-الوجه-امام-الكافرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_184/18406.mp3","categories":["حكم الصلاة وأهميتها","اللباس والزينة","نكاح الكفار"]},{"id":9313,"question":"الرسالة الثانية في هذه الحلقة وردت من السائل (ش. ع. م) من مصر مقيم بالمملكة، يقول في رسالته: أرجو من فضيلتكم توضيح الأحاديث والآيات التي تنص على تغطية الوجه والكفين مع شرحها وبيان الأدلة بالتفصيل، فقد سمعت من علماء كثيرين بأن جمهور العلماء على كشف الوجه والكفين، واستدلوا بحديث أسماء عندما دخلت على رسول الله ﷺ فقال لها: يا أسماء، إذا بلغت المرأة المحيض لا يظهر منها إلا هذا وهذا، وأشار إلى الوجه والكفين، وثانياً: بتفسير ابن عباس  لقول الله تعالى: إِلَّا مَا ظَهَرَ مِنْهَا [النور:31] بأنه قال: ما ظهر منها يقصد به الكحل والخاتم، فقالوا: إن هذا دليل على كشف الوجه والكفين، أفيدونا أفادكم الله؟","title":"حكم كشف المرأة وجهها وكفيها","answer":"الجواب: هذه المسألة قد تنازع فيها أهل العلم رحمة الله عليهم، والصواب: أن الوجه والكفين من العورة، والوجه أشد؛ لأنه زينة المرأة ومعظم ما يرغب فيها أو ينفر منها، وهو داخل في قوله جل وعلا: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ [النور:31] الآية، والأدلة في هذا كثيرة: منها قوله جل وعلا: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]، وهذا عام والله لم يستثن منه شيئاً لا يداً ولا وجهاً ولا غير ذلك، فدل على العموم، ثم علله سبحانه بما هو في مصلحة الجميع، قال: أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]، فدل على أن الحجاب أطهر لقلوب الجميع، وأبعد عن الفواحش، فالكشف يجر إلى الفاحشة، والحجاب يبعد عنها، ومنها قوله جل وعلا: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ [النور:31].. الآية، والزينة ما يبدو من المرأة من وجه وشعر وغير ذلك، والواجب ستر ذلك، فإنها زينة خلقية يجب سترها حتى لا تفتن غيرها.\nوأما قوله : إِلَّا مَا ظَهَرَ مِنْهَا ففسره العلماء بأنه الملابس، مَا ظَهَرَ مِنْهَا يعني: الملابس الظاهرة العادية، فهذه لا وجه للإلزام بإخفائها وسترها فإنه لابد من ظهورها، وإنما المقصود بالزينة: الوجه وما يرغب في نكاح المرأة من شعر ويد وقدم ونحو ذلك.\nوفي الباب أيضاً حديث عائشة رضي الله عنها في الصحيحين قالت: لما سمعت صوت صفوان بن المعطل وذلك في غزوة الإفك، لما سمعت صوته خمرت وجهي، قالت: وكان قد رآني قبل الحجاب فعرفني، فلما سمعت صوته خمرت وجهي، فدل ذلك على أنهم بعد الحجاب أمروا بتغطية الوجوه وسترها.\nوأما أثر أسماء بنت أبي بكر فهو حديث ضعيف، رواه أبو داود بإسناد ضعيف؛ لأنه من طريق سعيد بن بشير ، عن قتادة عن خالد بن دريك عن عائشة ، وسعيد بن بشير هذا ضعيف عند أهل العلم لا يحتج به، وقتادة بن دعامة مدلس وقد عنعن عن خالد ، والمدلس لا تقبل روايته إذا لم يصرح بالسماع، وخالد بن دريك لم يسمع من عائشة ، فصار هذا الحديث فيه ثلاث علل كلها توجب ضعفه، كل واحدة توجب ضعفه فكيف باجتماع الثلاث! ولفظه: أن أسماء بنت أبي بكر دخلت على النبي ﷺ في بيت عائشة وعليها ثياب رقاق، فأعرض عنها عليه الصلاة والسلام وقال: يا أسماء، إن المرأة إذا بلغت المحيض لم يصلح أن يرى منها إلا هذا وهذا، وأشار إلى وجهه وكفيه، هذا الحديث صريح لكنه غير صحيح، ولو صح لكان محمولاً على ما كان قبل الحجاب، لأن المرأة قبل الحجاب كانت تخرج يديها ووجهها، فلما شرع الله الحجاب أمرت بالستر، فلو صح هذا الخبر لكان محمولاً على حال المرأة قبل الحجاب، ثم أمر الله بالحجاب لحفظهن وحمايتهن من أسباب الفتن، والله المستعان. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7483/حكم-كشف-المراة-وجهها-وكفيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_237/23703.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":9315,"question":"تسأل أيضا وتقول: نسمع أن صبغ المرأة لشعرها بالصبغة حرام، فما صحة ذلك؟","title":"حكم صبغ المرأة شعرها","answer":"الجواب: إذا كان الصبغ أسود خالصا لم يجز أن تصبغ به المرأة ولا الرجل، لا تصبغ المرأة شعرها الأبيض بالصبغ الأسود الخالص، ولكن تصبغه بالحناء أو بالحناء والكتم مخلوطين حتى يكون الصبغ بين السواد والحمرة، أو بالزعفران، أو ما أشبه ذلك مما يجعله أصفر أو أحمر أو أسود مخلوطاً بحمرة أو صفرة لا بأس، أما الأسود الخالص فالنبي نهى عنه عليه الصلاة والسلام.\nوهكذا الرجل لا يصبغ شيبه بالأسود الخالص، ولكن يغيره بالحناء والكتم أو بالحناء فقط، أو بالصفرة فقط، هذا هو المشروع، يقول ﷺ: غيروا هذا الشيب واجتنبوا السواد وفي الحديث الآخر: يكون في آخر الزمان قوم يخضبون بالسواد كحواصل الحمام لا يريحون رائحة الجنة رواه الإمام أحمد وأبو داود والنسائي بإسناد صحيح، والأول رواه مسلم في الصحيح: غيروا هذا الشيب وجنبوه السواد . نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7491/حكم-صبغ-المراة-شعرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_237/23708.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":9377,"question":"المستمع (د. م. م) من السودان بعث برسالة ضمنها مجموعة من الأسئلة:في سؤاله الأول يسأل ويقول: ما هو حكم القرآن والسنة في الرجل يصافح النساء من أقاربه ويضع على يده قطعة من قماش تحجب اليد عن أيدي النساء أو المرأة كذلك تضع حاجبًا على يدها عند المصافحة؟ وهل في حديث الرسول ﷺ شيء من هذا، نرجو الإيضاح؟","title":"هل تجوز المصافحةلغير المحارم؟","answer":"الجواب: الواجب على المؤمن والمؤمنة ترك ذلك، فالمصافحة لا تجوز مع غير المحارم، أما أن يصافح أخته أو عمته أو خالته أو زوجته فلا بأس، أما أن يصافح بنات عمه أو بنات خاله أو بنات خالته أو جيرانه أو ما أشبه ذلك هذا لا يجوز، ولو وضع خرقة، ولو وضعت خرقة؛ لقول النبي ﷺ: إني  لا أصافح النساء لما بايعهن ومدت إليه امرأة يدها قال: إني لا أصافح النساء وهو الأسوة عليه الصلاة والسلام، قال الله : لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ [الأحزاب:21] وقالت عائشة رضي الله عنها: والله ما مست يد رسول الله يد امرأة قط -يعني: في البيعة- ما كان يبايعهن إلا بالكلام عليه الصلاة والسلام، ولأن المصافحة للنساء وسيلة إلى الفتنة كما أن النظر إليهن وسيلة للفتنة فهكذا المصافحة وسيلة للفتنة؛ فلهذا حرمها الله سدًا لباب الفتن. نعم.","link":"https://binbaz.org.sa/fatwas/7541/هل-تجوز-المصافحة-لغير-المحارم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_186/186015.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":9403,"question":"على ذكر الحجاب والنقاب أخت لنا من العراق تعاني معاناة كبيرة بموجب فهمي لرسالتها وتقول: إن أهلها يمانعونها عن الحجاب وتسأل لو تكرمتم -شيخ عبدالعزيز -كيف تتصرف؟","title":"حكم طاعة الوالدين في خلع الحجاب","answer":"الجواب: الواجب عليها طاعة الله ورسوله، ولا يجوز لها طاعة أهلها فيما حرم الله؛ لأن الرسول عليه الصلاة والسلام قال: إنما الطاعة في المعروف، وقال عليه الصلاة والسلام: لا طاعة لمخلوق في معصية الخالق، والله يقول سبحانه في كتابه العظيم في شأن النساء: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] ، فالحجاب طهارة لقلوب الجميع للذكور والإناث ومن أسباب السلامة من الفتنة، ويقول جل وعلا: يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلابِيبِهِنَّ ذَلِكَ أَدْنَى أَنْ يُعْرَفْنَ فَلا يُؤْذَيْنَ [الأحزاب:59] والجلباب ما يلبس فوق الملابس العادية ويغطى بالوجه والرأس، ويقول : وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنْهَا وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَى جُيُوبِهِنَّ وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ [النور:31] الآية.\nوالوجه والشعر من الزينة بل هو أعظم الزينة، وهكذا الصدر وهكذا اليد والقدم ونحو ذلك.\nفالمؤمنة تستر نفسها عن الرجال الأجانب، ولو قال لها أهلها: اكشفي، ولو قال لها زوجها: اكشفي، لا تكشف لإخوانه ولا لأقاربه، ولو قال أبوها ذلك أو عمها أو زوجها أو جدها أو غير ذلك، طاعة الله مقدمة، قالت عائشة رضي الله عنها فيما ثبت في الصحيحين عنها رضي الله عنها قالت في غزوة الإفك قالت لما تأخرت في حاجتها وارتحل القوم، وجاءت إلى مكانهم فلم تجدهم، اضطجعت تنتظر، فإذا بها بصوت صفوان بن المعطل لما رأى السواد قال: إنا لله وإنا إليه راجعون، فسمعت الصوت قالت: فلما سمعت صوته خمرت وجهي وكان قد رآني قبل الحجاب فعرفني فقولها: (فخمرت وجهي وكان قد رآني قبل الحجاب) يبين أن الحجاب الذي شرعه الله لهن ونزل به القرآن من جملته تخمير الوجه؛ ولأن الوجه مجمع الزينة تعرف به المرأة جمالًا ودمامة، ما تعرف بيدها ولا بقدمها، يعرف حسنها وجمالها أو ضده بالوجه، والباقي تبع. نعم.","link":"https://binbaz.org.sa/fatwas/7568/حكم-طاعة-الوالدين-في-خلع-الحجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_188/18809.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":9405,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى برنامج من (م. ع. ن. ز) من جمهورية مصر العربية أخونا يرجو مناقشة كثير من الأمور تتعلق بالحج فيصورها كما يلي: نرى كثيراً من النساء لاسيما القادمات من خارج البلاد يتساهلن بالحجاب ويعلم سماحتكم ما يحصل من الفتنة بسبب ذلك، فما نصيحتكم لهؤلاء النسوة أثابكم الله؟","title":"وجوب الحجاب والبعد عن الفتنة للحاجة وغيرها","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فلاشك أن النساء فتنة للرجال والخطر بتبرجهن وإظهارهن المحاسن عظيم كما قال الله  في كتابه المبين: وَقَرْنَ فِي بُيُوتِكُنَّ وَلاا تَبَرَّجْنَ تَبَرُّجَ الْجَاهِلِيَّةِ الأُولَى [الأحزاب:33] وصح عن رسول الله عليه الصلاة والسلام أنه قال: ما تركت بعدي فتنة أضر على الرجال من النساء فالواجب على الرجال التحرز من ذلك بغض البصر وحفظ الفرج كما قال الله سبحانه: قُلْ لِلْمُؤْمِنِينَ يَغُضُّوا مِنْْ أَبْصَارِهِمْ وَيَحْفَظُوا فُرُوجَهُمْ ذَلِكَ أَزْكَى لَهُمْ إِنَّ اللَّهَ خَبِيرٌ بِمَا يَصْنَعُونَ [النور:30] والواجب على النساء كذلك في قوله سبحانه: وَقُلْْ لِلْمُؤْمِنَاتِ يَغْضُضْنَ مِنْ أَبْصَارِهِنَّ وَيَحْفَظْنَ فُرُوجَهُنَّ [النور:31] وعليهن مع ذلك زيادة العناية بالتستر والحجاب وعدم إبداء الزينة لغير محارمهن لقوله في نفس الآية من سورة النور: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنْهَا وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَى جُيُوبِهِنَّ وَلا يُبْدِينََ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ [النور:31] الآية، وقال سبحانه في سورة الأحزاب: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنََّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53].\nفالواجب على النساء الابتعاد عن كل ما يفتن الرجال من إظهار المحاسن والمفاتن من رأس أو وجه أو صدر أو ساق أو قدم أو غير ذلك، فالواجب عليها -أي: المرأة- أن تعنى بالحجاب في الحج وغيره، والحج مجمع للناس من كل جنس، فالتستر فيه من أهم المهمات والحجاب فيه من أوجب الواجبات حذراً من الفتنة، والنبي ﷺ حين قال: ولا تنتقب المرأة ولا تلبس القفازين ليس معناه الإذن لهن في إظهار محاسنهن وإبداء مفاتنهن، لا، إنما معناه: ترك هذا الشيء ترك النقاب وهو ما خيط على قدر الوجه، وترك القفاز وهو ما خيط على قدر اليدين، فلا تلبس النقاب الذي يلبسه النساء عادة في وقت النبي ﷺ ويكون ساتراً للوجه غير العينين، ولا تلبس القفازين وهما كساءان وإن شئت قلت: غشاءان يجعلان لليدين من الصوف أو من القطن أو من غيرهما، هذا ممنوع في حق المرأة وقت إحرامها بالحج أو بالعمرة، لكن ليس معنى ذلك أن تبدي هذه الزينة بل تغطي ذلك بغير النقاب وبغير القفاز، فتغطي اليدين بجلبابها وبغيره من الملابس العامة، وتغطي وجهها بغير النقاب كالجلباب والخمار ونحو ذلك، ولهذا جاء عن عائشة رضي الله عنها قالت: كنا مع النبي ﷺ في حجة الوداع فإذا دنا منا الرجال سدلت إحدانا جلبابها من رأسها على وجهها، فإذا جاوزونا كشفناه.\nفالمطلوب من هذا كله هو البعد عن الفتنة، فإذا كانت بين الرجال وقرب الرجال احتجبت بالجلباب أو بالخمار بدلاً من النقاب وكذلك ترك ما يجلب الفتنة من وجود أشياء ظاهرة من ملابس جميلة تلفت النظر أو أشياء قد تبدو في اليد من الحلي ونحو ذلك، فينبغي لها أن تلاحظ هذا حتى تستر جميع بدنها وحتى لا تكون سبباً لفتنة أحد من الناس في هذا الموسم العظيم موسم الحج، فتكون ساترة وجهها وكفيها وجميع بدنها حتى لا يرى منها ما يفتن أحداً من الناس عند اجتماعها بالرجال وعند اختلاطها بالرجال في الطواف في السعي في أي مكان في عرفات في مزدلفة في أي مكان تبتعد عن أسباب الفتنة؛ لأن الله جل وعلا أمر النساء بالحجاب: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] فأبان سبحانه أن الحجاب أطهر لقلوب الجميع، يعني: أبعد عن أسباب الفتنة، فإن الفواحش نجاسة، وطاعة الله ورسوله والابتعاد عما حرم الله كله طهارة، ولهذا قال: ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْْ وَقُلُوبِهِنَّ [الأحزاب:53] وقال في غض البصر وحفظ الفرج: ذَلِكَ أَزْكَى لَهُمْ إِنَّ اللَّهَ خَبِيرٌ بِمَا يَصْنَعُونَ [النور:30] فالواجب على الجميع هو الابتعاد عن كل ما حرم الله، الرجل يبتعد عن أسباب الفتنة بغض بصره وحفظ فرجه وعدم الخلوة بالمرأة الأجنبية كما جاءت السنة بذلك فإن الرسول ﷺ قال: لا يخلون رجل بامرأة فإن الشيطان ثالثهما وقال عليه الصلاة والسلام: لا يخلون رجلل بامرأة إلا مع ذي محرم وقال: لا تسافر امرأة إلا مع ذي محرم كل ذلك لصيانة المؤمن من أسباب الفتنة ولصيانة المؤمنة من أسباب الفتنة، وهذا يعم الحج وغيره يعم سفر الحج ويعم غير ذلك ويعم المرأة في الحج وفي غير الحج، فهي فتنة أينما كانت فعليها أن تبتعد عن أسباب الافتتان بها وعلى الرجل أيضاً أن يبتعد عن أسباب الفتنة به وأن لا يكون عرضة لفتنة النساء وأن لا يفتتن هو أيضاً بالنساء، كل واحد منهما يحذر أسباب الفتنة به لعله ينجو ولعله يسلم في موسم الحج وفي غيره. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7574/وجوب-الحجاب-والبعد-عن-الفتنة-للحاجة-وغيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_159/15901.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":9415,"question":"أختنا أيضًا تسأل سماحة الشيخ عن صديقات لها تصفهن بعدم الالتزام، تقول: إذا أردت السفر هل أودعهن وأطلب منهن السماح أو لا؟","title":"مصاحبة المرأة لغير المتدينات","answer":"الجواب: إذا كن صديقات وكن طيبات في دينهن فتوديعهن ووصيتهن بالخير، وهن يوصينك بالخير أيضًا، كل هذا طيب؛ لأن المؤمنين إخوة.. كما قال جل وعلا: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ [التوبة:71].\nفهن أخوات في الله، إذا ودعتيهن وطلبت منهن الدعاء، ودعوت لهن وأوصيتيهن بالخير فكل هذا طيب.\nأما إن كن يتعاطين شيئًا يكفرهن كترك الصلاة أو الاستهزاء بالدين أو سب الدين أو معلنات فجورهن وكفرهن أو اعتناق دين الإلحاد فهؤلاء لا تجوز مصادقتهن ولا توديعهن ولا اعتبارهن صديقات، بل يجب أن تبغضيهن في الله وأن تعاديهن في الله إذا كن كافرات إما باعتناق المذهب الشيوعي أو باعتناق المذهب الوثني كدعوة الأموات والاستغاثة بالأموات كـالعيدروس وغيره، أو بسب الدين والاستهزاء بالدين هؤلاء بهذه الأعمال يكن كافرات.\nأما إن كن مسلمات موحدات ولكن عندهن شيء من المعاصي فالأمر في هذا واسع، إن ودعتيهن فلا بأس، وإن تركتيهن فلا بأس، الأمر في هذا واسع؛ إلا إذا كن معلنات فجورهن كالزنا وشرب المسكر فمثلهن ينبغي ترك توديعهن وترك صحبتهن وإن كن مسلمات؛ لأنهن مظهرات للفجور والمعاصي، فمثلهن يستحقن الهجر وعدم اتخاذهن صديقات حتى لا يضرك القرب منهن والمصادقة لهن، نسأل الله لك التوفيق والهداية، ونسأل الله لهن الصلاح والتوفيق.","link":"https://binbaz.org.sa/fatwas/7580/مصاحبة-المراة-لغير-المتدينات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_190/19002.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":9416,"question":"أولى رسائل هذه الحلقة وردت من الأخت حسناء بنت محمد الحربي من القصيم، تقول في رسالتها: ما حكم صبغ الأظافر باللون الأسود وهو ما يعرف بالدوج أو المانوكير هل هو جائز أم لا، أفيدونا أفادكم الله؟","title":"حكم صبغ النساء أظفارهن بالمناكير","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فصبغ الأظفار بالصبغ الأسود ليس فيه حرج ولا بأس به، سواء كان مناكير أو غير مناكير، ولكن الحناء أفضل من المناكير، والمناكير تركها أولى وأحسن، لكن إذا استعملته المرأة فإنها تزيلها وقت الوضوء؛ لأن لها جسماً فيما بلغنا فينبغي لها أن تزيلها عند الوضوء، حتى لا تمنع الماء عن الظفر، وهكذا لو جعلت على أظفارها شيئًا آخر له جسم فإنه يزال عند الوضوء، حتى يصل الماء إلى نفس الظفر، وأما الصبغ فلا بأس به سواء أسود أو أحمر لا بأس به كالحناء. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7581/حكم-صبغ-النساء-اظفارهن-بالمناكير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_255/25501.mp3","categories":["اللباس والزينة"]},{"id":9428,"question":"إحدى الأخوات المستمعات من المدينة المنورة تسأل مجموعة من الأسئلة من بينها سؤال تقول فيه: هل العين من زينة المرأة أو لا؟","title":"حكم إظهار المرأة عينيها","answer":"الجواب: العين ليست من الزينة؛ لأنها تحتاج إلى إبرازها للنظر في الطرق، فالذي يظهر ونص عليه كثير من أهل العلم أنها غير داخلة في الزينة التي نهى الله عن إبدائها، لكن إذا تيسر سترها وأن تنظر من وراء الخمار وتعرف الطريق من وراء الخمار الساتر يستر وجهها ولكنها تتمكن من رؤية الطريق فهذا أكمل، وإذا لم يتيسر ذلك وأخرجت العين أو العينين فلا حرج كما يفعل بعض البادية وهو النقاب يسمى النقاب، يسمونه البرقع، فإذا جعلت لها برقعًا أو نقابًا يستر وجهها كله إلا إحدى العينين أو إلا العينين فلا حرج في ذلك إن شاء الله؛ لأنها محتاجة إلى أن ترى الطريق، أن ترى ما أمامها. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7593/حكم-اظهار-المراة-عينيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_190/19011.mp3","categories":["اللباس والزينة"]},{"id":9429,"question":"أختنا أيضًا تسأل عن من يسألها من وراء حجاب؟","title":"حكم سؤال المرأة من وراء حجاب","answer":"الجواب: لا بأس، لا بأس أن تكلم الرجال من وراء حجاب وهي متغشية ومتحجبة، ولا بأس أن تكلم من طريق الهاتف من طريق التلفون تكلم من يكلمها، يسألها عن حاجة أو يسألها عن زوجها، أو عن حاجة من الحاجات تجيبه بالصوت المتوسط الذي ليس فيه خضوع وليس فيه نزغ وشدة، ولكن بين ذلك.\nمثل ما قال جل وعلا: فَلا تَخْضَعْنَ بِالْقَوْلِ فَيَطْمَعَ الَّذِي فِي قَلْبِهِ مَرَضٌ وَقُلْنَ قَوْلًا مَعْرُوفًا [الأحزاب:32] يعني: وسط، ليس فيه خضوع وليس فيه سوء أدب وشدة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7594/حكم-سوال-المراة-من-وراء-حجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_190/19012.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":9442,"question":"وهذه رسالة وردت لنا من السائل (ص. ع. أ) من المملكة يقول: إلى أي حد يجوز للمسلم إطالة ثيابه وملابسه؟","title":"حد الإطالة في ثوب المسلم وملبسه","answer":"الجواب: ثبت عن النبي ﷺ أنه حد للناس الكعب، فالسنة ألا يزيد على الكعب، من نصف الساق إلى الكعب، لا يرتفع عن نصف الساق ولا ينزل عن الكعب هذا هو السنة، وقال عليه الصلاة والسلام: ما أسفل من الكعبين من الإزار فهو في النار، فلا يجوز له أن يجر إزاره، أو سراويله أو بشته أو قميصه تحت الكعب بل يجب منع ذلك والقضاء عليه، هذا هو الواجب على كل رجل، والإسبال من المنكرات العظيمة، فيجب الحذر منه وهو في الغالب يقع عن الكبر والخيلاء والتعاظم، ولهذا قال عليه الصلاة والسلام: إياك والإسبال فإنه من المخيلة، يعني: من الخيلاء من الكبر، وقال عليه الصلاة والسلام: من جر ثوبه خيلاء لم ينظر الله إليه يوم القيامة، وقال أيضاً عليه الصلاة والسلام ثلاثة لا يكلمهم الله ولا ينظر إليهم يوم القيامة ولا يزكيهم ولهم عذاب أليم: المسبل إزاره، والمنان فيما أعطى، والمنفق سلعته بالحلف الكاذب، خرجه مسلم في صحيحه.\nفجعل منهم المسبل، فهذا يدل على عظم التحريم وأنه من الكبائر، وهكذا من ينفق سلعته بالحلف الكاذب، أيضاً قد أتى كبيرة عظيمة، أو يمن في العطية، يعطيه ويمن، والله يقول سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا لا تُبْطِلُوا صَدَقَاتِكُمْ بِالْمَنِّ وَالأَذَى [البقرة:264].\nفالإسبال من الكبائر، فيجب الحذر من ذلك، والبعد عنه وهذا في حق الرجال، أما المرأة فلها أن ترخي ثيابها حتى تستر أقدامها. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7601/حد-الاطالة-في-ثوب-المسلم-وملبسه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_239/23903.mp3","categories":["اللباس والزينة"]},{"id":9448,"question":"يسأل أيضاً ويقول: هناك عود الصندل معطر بالكلونيا، ونحرقه فينتج منه دخان طيب الرائحة، هل هذا الدخان يعد نجساً؟ وإذا كان الثوب مبخراً بهذا البخور فهل تجوز الصلاة فيه؟","title":"حكم استعمال عود الصندل المعطر بالكلونيا","answer":"الجواب: ينبغي تجنب ما يتعلق بالكلونيا؛ لأن الكلونيا مخلوطة بنوع من المسكر، فينبغي للمؤمن أن يتباعد عن المسكر كله، والسبيرت هو الذي يوضع في الكلونيا مسكر معروف، والمسكرات عند الجمهور نجسة، عند جمهور أهل العلم نجسة، وذهب بعض التابعين إلى أنها غير نجسة، لكن يجب إتلافها وإزالتها والقضاء عليها، فينبغي لك أن تترك هذا التدخين بما فيه جزء من الكلونيا أحوط لك وأبعد عن الشر، وفي التدخين بالطيبات من العود الطيب والصندل وغيره ما يكفي عن مخالطة الكلونيا. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7613/حكم-استعمال-عود-الصندل-المعطر-بالكلونيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_255/25506.mp3","categories":["اللباس والزينة"]},{"id":9451,"question":"السؤال الثالث والأخير في رسالة الأخت السائلة من العراق تقول: في الأفراح كفرح الزفاف مثلاً هل يجوز الغناء والتزين له؟ وهناك رقصة أحياناً عندنا تسمى: بالدبكة كانت تجري سابقاً للرجال فقط بمعزل عن النساء، لكن في الوقت الحاضر تطور الأمر فأصبحت هذه الرقصة يختلط فيها الرجال والنساء في مناسبات الزواج، فما حكم الشرع في ذلك بارك الله فيكم؟","title":"حكم الغناء للنساء ورقصة الدبكة للرجال مع النساء","answer":"الجواب: أما الغناء المعروف الذي ليس فيه تعد لحرمات الله، بل الغناء في مدح أهل الزوجة أو أهل الزوج مع الدف فلا بأس مثل ما جاء في حديث عائشة لما زاروهم قالوا:\n\n\t\n\t\t\n\t\t\tأتيناكم أتيناكم\n\t\t\tفحيانا وحياكم\n\t\t\n\t\n\n\n\n\t\n\t\t\n\t\t\tولولا الذهب الأحمـر\n\t\t\tما حلت بواديكم\n\t\t\n\t\n\n\n\n\t\n\t\t\n\t\t\tولولا الحنطة الحمـراء\n\t\t\tما سمنت عذاريكم\n\t\t\n\t\n\nوما أشبه ذلك من الأشعار والغناء يتعلق بمدح الزوج مدح الزوجة مدح أهلهم، أهل الزوج أو أهل الزوجة، أو أشياء نحو هذا ليس فيها ظلم لأحد، وليس فيها غيبة لأحد، فهذا لا بأس به مع الدف بين النساء خاصة، هذا مشروع من باب إعلان النكاح، كما أمر النبي بإعلان النكاح عليه الصلاة والسلام، وأمر بضرب الدف فيه؛ لأن إعلانه أمر مطلوب حتى يعرف أن فلانة تزوجت فلاناً، وحتى لا يظن بهم السوء، فإن السفاح والزنا يكون بالسر، أما الزواج الشرعي فيكون بالعلن.\nأما الدبكة التي يفعلها الرجال فلا يجوز، وإذا فعلوها مع النساء كان أشر وأقبح، فلا يجوز فعل ذلك من الرجال مع النساء مختلطين؛ لما فيه من الفتنة والفساد الكبير، أما الرجال فليس لهم دخل في هذا إنما هذا للنساء، وإذا فعل الرجال شيئاً يوافق الشرع مثل التدرب على السلاح، وحمل الأثقال، مثل اللعب بالحراب، والتروس، والرمي هذا هو شأن الرجال وحدهم، في أي مناسبة.\nأما اختلاط الرجال بالنساء في الأعراس أو في غير الأعراس هذا منكر لا يجوز؛ لما فيه من الفتنة، قد قال عليه الصلاة والسلام: ما تركت بعدي فتنة أضر على الرجال من النساء، واختلاط الرجال بالنساء في كل مناسبة ينبني عليه شر كثير، ويفضي إلى فتنة عظيمة، فيجب الحذر من ذلك. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7630/حكم-الغناء-للنساء-ورقصة-الدبكة-للرجال-مع-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_240/24007.mp3","categories":["الأخلاق المذمومة","سنن الفطرة","اللباس والزينة"]},{"id":9471,"question":"تقول أيضاً الأخت (ح. غ) من المملكة: عندما يغيب زوجي فأنا أستأذن منه للخروج من المنزل لبعض الحاجات الهامة، فيذهب بي أخوه مع أمه، أو مع زوجته فهل علي في ذلك وزر؟","title":"حكم خروج المرأة مع أخي زوجها وأمه معهما","answer":"الجواب: لا حرج في ذلك إذا خرجت مع أخي زوجك بإذن زوجك ومعكما ثالث إما أمه وإما زوجته وإما غيرهما ممن يحصل به عدم الخلوة فلا بأس بذلك؛ لأن الرسول ﷺ نهى عن الخلوة قال: لا يخلون رجل بامرأة فإن ثالثهما الشيطان، فإذا كانت معكما أمه أو زوجته زالت الخلوة ولا حرج في ذلك إن شاء الله، إذا كان الخروج للحاجات المعلومة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7639/حكم-خروج-المراة-مع-اخي-زوجها-وامه-معهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_241/24103.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":9488,"question":"وبعث الأخ عبده محمد موسى من جمهورية الصومال برسالة يسأل فيها ويقول: إن في عيني شعرًا لابد من أخذه بالمنقاش، فإذا تركته آذاني وأتعبني، فهل يجوز لي أخذه وأنا محرم أم لا، أفيدونا أفادكم الله؟","title":"حكم أخذ المحرم من شعره إذا كان يؤذيه","answer":"الجواب: لا حرج في ذلك، إذا كان الإنسان محرمًا ووقع في ....... شعرات منكسرة تؤذيه فإنه يأخذها بالمنقاش، مثل لو انكسر ظفره أزاله؛ لأن هذا متعب ومؤذي فلا يضر أخذه، وأيضًا من شرع الله التيسير والتسهيل، يُرِيدُ اللَّهُ بِكُمُ الْيُسْرَ وَلا يُرِيدُ بِكُمُ الْعُسْرَ [البقرة:185] فإذا انكسرت شعرة أو شعرات في عينه جاز أخذها بالمنقاش وهو محرم ولا حرج في ذلك، والحمد لله.\nوهكذا لو انكسر ظفره أزاله. نعم.","link":"https://binbaz.org.sa/fatwas/7648/حكم-اخذ-المحرم-من-شعره-اذا-كان-يوذيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_192/19207.mp3","categories":["اللباس والزينة","محظورات الإحرام","قضايا المرأة"]},{"id":9511,"question":"أخيراً يسأل الأخ سليمان فيقول: روى الشيخان عن أبي هريرة  أن رسول الله ﷺ قال: إن اليهود والنصارى لا يصبغون فخالفوهم، ما حكم الشرع في الصبغة، وهل هي حرام أم مكروهة، علماً بأن الظاهرة الموجودة في الصبغة تأخذ نوعاً من المغالطة والعياذ بالله وخاصة الطاعنين في السن، ومما يتضح من الحديث السابق يأمرنا بالصبغة، علماً من أنه لم يوضح نوع هذه الصبغة، أفيدونا أفادكم الله؟","title":"حكم صبغ الشعر بالسواد وغيره","answer":"الجواب: الحديث يدل على أن السنة الصبغ حتى يخالف اليهود والنصارى فهم يتركون شيبهم أبيض، فالسنة للمؤمن أن يخالفهم ويصبغ شيبه، ولهذا في الحديث الصحيح الآخر حديث أبي قحافة والد الصديق لما رآه النبي ﷺ أبيض الرأس واللحية، قال: غيروا هذا الشيب، واجتنبوا السواد.\nفالسنة أن يغير الشيب بالصفرة والحمرة، بالحناء والكتم، لكن لا يغير بالسواد، وإن كان النبي ﷺ لم يبين هذا في هذا الحديث لكن بينه في أحاديث أخرى، أخبرنا هنا بالصبغ أن نخالف اليهود والنصارى فنصبغ، وبين لنا في الأحاديث الأخرى أن الصبغ يكون بغير السواد، بالحمرة، بالحناء والكتم؛ لأن الحناء مخلوط بالكتم حتى يكون بين السواد والحمرة، أما أن يغيره بالسواد الخالص هذا لا يجوز. نعم.","link":"https://binbaz.org.sa/fatwas/7681/حكم-صبغ-الشعر-بالسواد-وغيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_243/24315.mp3","categories":["اللباس والزينة"]},{"id":9516,"question":"أخيراً يسأل الأخ سليمان فيقول: روى الشيخان عن أبي هريرة  أن رسول الله ﷺ قال: إن اليهود والنصارى لا يصبغون فخالفوهم، ما حكم الشرع في الصبغة، وهل هي حرام أم مكروهة، علماً بأن الظاهرة الموجودة في الصبغة تأخذ نوعاً من المغالطة والعياذ بالله وخاصة الطاعنين في السن، ومما يتضح من الحديث السابق يأمرنا بالصبغة، علماً من أنه لم يوضح نوع هذه الصبغة، أفيدونا أفادكم الله؟","title":"حكم صبغ الشعر بالسواد وغيره","answer":"الجواب: الحديث يدل على أن السنة الصبغ حتى يخالف اليهود والنصارى فهم يتركون شيبهم أبيض، فالسنة للمؤمن أن يخالفهم ويصبغ شيبه، ولهذا في الحديث الصحيح الآخر حديث أبي قحافة والد الصديق لما رآه النبي ﷺ أبيض الرأس واللحية، قال: غيروا هذا الشيب، واجتنبوا السواد.\nفالسنة أن يغير الشيب بالصفرة والحمرة، بالحناء والكتم، لكن لا يغير بالسواد، وإن كان النبي ﷺ لم يبين هذا في هذا الحديث لكن بينه في أحاديث أخرى، أخبرنا هنا بالصبغ أن نخالف اليهود والنصارى فنصبغ، وبين لنا في الأحاديث الأخرى أن الصبغ يكون بغير السواد، بالحمرة، بالحناء والكتم؛ لأن الحناء مخلوط بالكتم حتى يكون بين السواد والحمرة، أما أن يغيره بالسواد الخالص هذا لا يجوز. نعم.","link":"https://binbaz.org.sa/fatwas/7681/حكم-صبغ-الشعر-بالسواد-وغيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_243/24315.mp3","categories":["اللباس والزينة"]},{"id":9585,"question":"هذه رسالة من (ع. أ. ع) من الرياض يسأل عن قضية الخلاف بين أهل الفتوى حول مسألة ستر الوجه وأنه واجب وأنه من الحجاب الشرعي، والكلام حول حديث أسماء رضي الله عنها الذي يستدل به من ذهب إلى كشف الوجه. نرجو القول الفصل بارك الله فيكم؟","title":"حكم ستر المرأة وجهها عن الأجانب","answer":"الجواب: الوجه عورة يجب ستره -أعني: وجه المرأة- إلا عن محارمها كأخيها وأبيها وعمها ونحو ذلك، أما من جهة الأجانب فيجب ستر وجهها؛ لأنه عورة، وهكذا بقية بدنها عورة، تستر رأسها ووجهها وبقية بدنها إلا عن محارمها؛ لقول الله عز وجل في كتابه الكريم: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] فبين سبحانه أن الحجاب أطهر لقلوب الجميع، ومعناه: أن عدم الحجاب يسبب الفتنة والخبث، والواجب على المؤمن والمؤمنة الابتعاد عن أسباب الخبث وأسباب الفتنة، والحرص على أسباب الطهارة والسلامة.\nأما حديث أسماء الذي أشار إليه السائل فهو أن أبا داود رحمه الله في سننه روى عن عائشة رضي الله عنها: أن النبي ﷺ دخل عليها وعندها أسماء أختها بنت أبي بكر زوج الزبير رضي الله تعالى عنه، وعليها ثياب رقاق فأعرض عنها النبي ﷺ وقال: يا أسماء ! إن المرأة إذا بلغت المحيض فإنه لا يصلح أن يرى منها إلا هذا وهذا، وأشار إلى وجهه وكفيه هذا الحديث ليس بصحيح عن رسول الله عليه الصلاة والسلام، ولا يجوز التعلق به، بل هو حديث باطل ضعيف لعلل ثلاث:\nإحداها: أنه من رواية خالد بن دريك عن عائشة ولم يسمع منها، فهو منقطع، والمنقطع ضعيف لا يحتج به.\nوالعلة الثانية: أنه من رواية سعيد بن بشير وهو ضعيف لا يحتج به.\nوالعلة الثالثة: أنه من رواية قتادة عن خالد المذكور، وقتادة مدلس وقد عنعن، والمدلس لا تقبل روايته إذا عنعن حتى يصرح بالسماع.\nوعلى فرض صحته يكون محمولاً على ما قبل الحجاب، وبعد نزول الحجاب أمر النساء أن يسترن وجوههن وأكفهن، هذا لو صح مع أنه غير صحيح للعلل الثلاث التي عرفتها، لكن لو صح كان محمولاً على ما كان قبل الحجاب، كانت المرأة المسلمة تكشف وجهها وكفيها عند الرجال قبل الحجاب، ثم شرع الله الحجاب فأمرن بالستر، قالت عائشة رضي الله عنها كما روى البخاري ومسلم في الصحيحين لما سمعت صوت صفوان المعطل في غزوة الإفك يسترجع قالت: لما سمعت صوته خمرت وجهي وكان قد رآني قبل الحجاب فعلم بذلك أنهن بعد الحجاب قد أمرن بتخمير الوجوه وسترها، فهذا نص ثابت في الصحيحين عن عائشة رضي الله عنها دال على أن النساء بعد نزول آية الحجاب أمرن بتخمير الوجوه والحجاب، فحديث أسماء لو صح محمول على الحالة الأولى، مع أنه كما عرفت حديث غير صحيح، بل معلول بالعلل الثلاث. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7746/حكم-ستر-المراة-وجهها-عن-الاجانب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_248/24803.mp3","categories":["اللباس والزينة"]},{"id":9591,"question":"هذه رسالة من (ع. أ. ع) من الرياض يسأل عن قضية الخلاف بين أهل الفتوى حول مسألة ستر الوجه وأنه واجب وأنه من الحجاب الشرعي، والكلام حول حديث أسماء رضي الله عنها الذي يستدل به من ذهب إلى كشف الوجه. نرجو القول الفصل بارك الله فيكم؟","title":"حكم ستر المرأة وجهها عن الأجانب","answer":"الجواب: الوجه عورة يجب ستره -أعني: وجه المرأة- إلا عن محارمها كأخيها وأبيها وعمها ونحو ذلك، أما من جهة الأجانب فيجب ستر وجهها؛ لأنه عورة، وهكذا بقية بدنها عورة، تستر رأسها ووجهها وبقية بدنها إلا عن محارمها؛ لقول الله عز وجل في كتابه الكريم: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] فبين سبحانه أن الحجاب أطهر لقلوب الجميع، ومعناه: أن عدم الحجاب يسبب الفتنة والخبث، والواجب على المؤمن والمؤمنة الابتعاد عن أسباب الخبث وأسباب الفتنة، والحرص على أسباب الطهارة والسلامة.\nأما حديث أسماء الذي أشار إليه السائل فهو أن أبا داود رحمه الله في سننه روى عن عائشة رضي الله عنها: أن النبي ﷺ دخل عليها وعندها أسماء أختها بنت أبي بكر زوج الزبير رضي الله تعالى عنه، وعليها ثياب رقاق فأعرض عنها النبي ﷺ وقال: يا أسماء ! إن المرأة إذا بلغت المحيض فإنه لا يصلح أن يرى منها إلا هذا وهذا، وأشار إلى وجهه وكفيه هذا الحديث ليس بصحيح عن رسول الله عليه الصلاة والسلام، ولا يجوز التعلق به، بل هو حديث باطل ضعيف لعلل ثلاث:\nإحداها: أنه من رواية خالد بن دريك عن عائشة ولم يسمع منها، فهو منقطع، والمنقطع ضعيف لا يحتج به.\nوالعلة الثانية: أنه من رواية سعيد بن بشير وهو ضعيف لا يحتج به.\nوالعلة الثالثة: أنه من رواية قتادة عن خالد المذكور، وقتادة مدلس وقد عنعن، والمدلس لا تقبل روايته إذا عنعن حتى يصرح بالسماع.\nوعلى فرض صحته يكون محمولاً على ما قبل الحجاب، وبعد نزول الحجاب أمر النساء أن يسترن وجوههن وأكفهن، هذا لو صح مع أنه غير صحيح للعلل الثلاث التي عرفتها، لكن لو صح كان محمولاً على ما كان قبل الحجاب، كانت المرأة المسلمة تكشف وجهها وكفيها عند الرجال قبل الحجاب، ثم شرع الله الحجاب فأمرن بالستر، قالت عائشة رضي الله عنها كما روى البخاري ومسلم في الصحيحين لما سمعت صوت صفوان المعطل في غزوة الإفك يسترجع قالت: لما سمعت صوته خمرت وجهي وكان قد رآني قبل الحجاب فعلم بذلك أنهن بعد الحجاب قد أمرن بتخمير الوجوه وسترها، فهذا نص ثابت في الصحيحين عن عائشة رضي الله عنها دال على أن النساء بعد نزول آية الحجاب أمرن بتخمير الوجوه والحجاب، فحديث أسماء لو صح محمول على الحالة الأولى، مع أنه كما عرفت حديث غير صحيح، بل معلول بالعلل الثلاث. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7746/حكم-ستر-المراة-وجهها-عن-الاجانب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_248/24803.mp3","categories":["اللباس والزينة"]},{"id":9645,"question":"الرسالة التالية وصلت من المستمع (م. ر. عبد الرب ) من جمهورية اليمن الديمقراطية الشعبية عدن، الرسالة تحتوي على العديد من الأسئلة السؤال الأول يقول فيه: كيف تتحجب المرأة وممن؟ هل من جميع بدنها وهل يجب أن تظهر كفيها ووجها لجميع المحارم، نرجو توضيح ذلك أفيدونا أفادكم الله؟","title":"بيان من يجب على المرأة الاحتجاب عنهم","answer":"الجواب: المرأة تتحجب عن غير محارمها عن جيرانها بني عمها أخي زوجها أما محارمها فلا تتحجب عنهم، لا بأس أن يبدو وجهها وكفاها وقدماها لمحارمها كأخيها وعمها وخالها لا بأس، إنما التحجب عن الأجانب كابن عمها فإنه أجنبي ما هو بمحرم وكزوج أختها وأخي زوجها وعم زوجها ونحو ذلك، هؤلاء عليها أن تحتجب عنهم وتستتر في وجهها وبدنها كله، لقول الله سبحانه: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] وقال الله سبحانه في سورة النور: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ [النور:31] إلى آخر الآية، فهي مأمورة بالحجاب عن غير محارمها. نعم.","link":"https://binbaz.org.sa/fatwas/7811/بيان-من-يجب-على-المراة-الاحتجاب-عنهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_194/19408.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":9669,"question":"السؤال الخامس في رسالة الأخت إستبرق من العراق جاء فيه: جاء تحريم لبس الذهب بالنسبة للرجال على لسان الرسول ﷺ، ولكن في هذا الوقت أصبح هنالك تقليداً هو أن يلبس الرجال حلقة من الذهب في الأصبع عندما يخطب المرأة وحتى بعد أن يتم زواجها منه، أرجو إعطاء حكم الشرع في ذلك ولكم الأجر والمثوبة من الله؟","title":"حكم تختم الرجل بالذهب في الخطوبة","answer":"الجواب: هذا لا يجوز لبس الرجل الخاتم من الذهب لا عند الزواج ولا بعده ولا قبله ما يجوز؛ لأن الرسول ﷺ نهى عن التختم بالذهب في الأحاديث الصحيحة ولما رأى في يد رجل خاتماً من ذهب نزعه وطرحه وقال: يعمد أحدكم إلى جمرة من النار فيضعها في يده رواه مسلم في الصحيح.\nفهذا يدلنا على تحريم التختم بالذهب للرجال وأنه لا يجوز مطلقاً ولو كان في وقت الزواج أو قبله أو بعده. نعم.","link":"https://binbaz.org.sa/fatwas/7835/حكم-تختم-الرجل-بالذهب-في-الخطوبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_194/19417.mp3","categories":["اللباس والزينة"]},{"id":9718,"question":"سماحة الشيخ! هذه سائلة من السعودية تقول ابنة السعودية لي سؤال: لقد سمعت بأن صبغ الشعر ما دام فيه ستر للشيب فإنه لا يجوز، وهي الآن تقول: فتاة في العشرين من العمر تقول: وقد اعتدى الشيب شعري، فهل يجوز أن أستعمل الحناء وأنا في هذا السن المبكر، جزاكم الله خيراً؟","title":"حكم صبغ الشعر إذا كان فيه شيب","answer":"الجواب: صبغ الشيب سنة للرجال والنساء؛ لقول النبي ﷺ: غيروا هذا الشيب واجتنبوا السواد فيغير بالحمرة والصفرة والحناء غير السواد هذا هو السنة، أما بالسواد الخالص لا يجوز، السواد الخالص لا يجوز لا للرجل ولا للمرأة، لا يغير الشيب بالسواد الخالص، لكن إذا غيره بالحمرة بالسواد مع الحمرة بين الحمرة والسواد، بالصفرة لا بأس هذا هو السنة، أما تغيير الشيب بسواد خالص فلا يجوز. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7873/حكم-صبغ-الشعر-اذا-كان-فيه-شيب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_272/27211.mp3","categories":["اللباس والزينة"]},{"id":9736,"question":"أخيراً تقول الأخت السائلة من اليمن: هل إزالة الشعر من جسم المرأة حرام خصوصاً الوجه واليدين؟ وإذا كان هذا الشعر يسبب لها حرج في وجهها هل عليها ذنب إذا أزالته من نواصي وجهها أو حواجبها بمقص أو موس حلاقة، وخصوصاً أن اللعنة أتت في الحديث للنامصة والمتنمصة، أفتونا جزاكم الله خيراً ؟","title":"أحكام الشعر الموجود في جسم الإنسان","answer":"الجواب: الشعر في البدن له أقسام ثلاثة، له أحوال ثلاثة في حق الرجل والمرأة:\nشعر لا يجوز أخذه ولا قصه ولا حلقه، كلحية الرجل، وحواجب المرأة، ليس للمرأة أن تأخذ حواجبها لا بقص ولا غيره، وليس لها أن تأخذ شعر وجهها المعتاد؛ لأن الرسول صلى الله عليه وسلم لعن النامصة والمتنمصة، والنمص: أخذ شعر الحاجبين والوجه، الشعر المعتاد.\nأما إن كان غير معتاد كاللحية للمرأة والشارب للمرأة فلا مانع أن تأخذ ذلك لما فيه من التشويه، وهكذا لحية الرجل ليس له أخذها لا يحلقها ولا يقصها؛ لأن الرسول ﷺ أمر بإعفاء اللحى، وإرخائها وتوفيرها، وقص الشوارب وإحفائها.\nالقسم الثاني: شعر مأمور بأخذه في حق المرأة والرجل جميعاً، وسنة أن يؤخذ، وهو شعر الإبط وشعر العانة وشعر الشارب وهذا يؤخذ ينتف الإبط، السنة نتف الإبط للرجل والمرأة، وإن أزاله بغير النتف فلا بأس، هكذا العانة وهي الشعرة التي حول الفرج يشرع أخذها بالحديد بالموسى، أو بالمكينة، هذا هو الأفضل وإن أخذها بغير ذلك بشيء من الأدوية التي تزيل الشعر فلا بأس في حق الرجل والمرأة جميعاً.\nوهناك شعر الشارب للرجل السنة قصه كما أمر به النبي عليه الصلاة والسلام قال: قصوا الشوارب وأعفوا اللحى؛ خالفوا المشركين وكذلك قلم الأظفار يشرع للرجل والمرأة قلم الأظفار، ولا ينبغي أن يترك ذلك أكثر من أربعين ليلة، ما ينبغي للرجل ولا المرأة ترك شعر الإبط ولا العانة ولا الأظفار أكثر من أربعين ليلة، وهكذا الرجل لا يترك الشارب أكثر من أربعين ليلة، بل يشرع للجميع أخذ ذلك قبل أربعين ليلة، قص الشارب.. قلم الظفر.. نتف الإبط.. حلق العانة، قبل تمام أربعين ليلة هذا هو المشروع.\nالقسم الثالث: شعر آخر غير هذا، مثل: شعر السيقان شعر العضد، شعر البطن، شعر الصدر، هذا لم يرد فيه شيء فيما نعلم، فمن تركه فلا بأس، ومن أخذه فلا بأس، من أزاله بشيء فلا بأس، ومن تركه فلا بأس، الأمر فيه واسع إن شاء الله. نعم.\nالمقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/7896/احكام-الشعر-الموجود-في-جسم-الانسان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_254/25405.mp3","categories":["اللباس والزينة"]},{"id":9738,"question":"وأولى رسائل هذه الحلقة من مرسلة تقول: من أختكم في الله (أ. ع. ق) من كينيا، تقول السائلة: يقول الرسول ﷺ: صلوا كما رأيتموني أصلي، والذي يفهم من هذا الحديث أنه لا فرق بين صلاة الرجل وصلاة المرأة لا في القيام ولا في القعود ولا في الركوع ولا في السجود، وعلى هذا أنا أعمل منذ بلوغي سن التكليف ولكن عندنا بعض النساء في كينيا يخاصمنني ويقولون: إن صلاتك غير صحيحة؛ لأنها تشبه صلاة الرجل، ويذكرون أمثلة تختلف فيها في نظرهم صلاة الرجل عن صلاة المرأة من حيث إمساك اليدين على الصدر أو إطلاقهما واستواء الظهر في الركوع وغير ذلك من الأمور التي لم أقتنع بها، فأود أن تبينوا لي هل بين صلاة الرجل وصلاة المرأة في الأداء فرق؟","title":"هل يوجد فرق بين صلاة الرجل وصلاة المرأة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: أيها الأخت في الله السائلة! الصواب أنه ليس بين صلاة المرأة وصلاة الرجل فرق، وما ذكره بعض الفقهاء من الفرق ليس عليه دليل، والحديث الذي ذكرت في السؤال وهو قوله ﷺ: صلوا كما رأيتموني أصلي، يعم الجميع، والتشريعات الإسلامية تعم الرجال والنساء إلا ما قام عليه الدليل بالتخصيص، فالسنة المرأة أن تصلي كما يصلي الرجل في الركوع والسجود والقراءة ووضع اليدين على الصدر هذا هو الأفضل، وهكذا وضعهما على الركبتين عند الركوع، وهكذا وضعهما على الأرض في السجود حيال المنكبين أو حيال الأذنيين، وهكذا استواء الظهر في الركوع وهكذا ما يقال في الركوع والسجود وبعد الرفع من الركوع وبعد الرفع من السجدة الأولى كله كالرجل سواء، عملًا بقوله عليه الصلاة والسلام: صلوا كما رأيتموني أصلي رواه البخاري في الصحيح. نعم.\nالمقدم: لكن يا سماحة الشيخ إذا أذنتم لي بالنسبة للجهر بالقراءة وبالنسبة لوجوب الإقامة ألا تختلف صلاة المرأة عن صلاة الرجل في هذا؟\nالشيخ: هذه إقامة خارجة عن هذا، الإقامة والأذان للرجال خاص جاء به النص، الرجال يقيمون ويؤذنون أما النساء فلا إقامة ولا أذان، أما الجهر فلها أن تجهر في الفجر والمغرب والعشاء؛ في الفجر في الركعتين وفي المغرب في الركعتين الأوليين وفي العشاء في الركعتين الأوليين كما يجهر الرجال. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/7905/هل-يوجد-فرق-بين-صلاة-الرجل-وصلاة-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_196/19601.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":9796,"question":"ولها سؤال رابع وأخير تقول: هل جعل الرأس جديلة واحدة من الخلف مكروه وما حكمه؟","title":"حكم جعل المرأة شعرها جديلة واحدة من الخلف","answer":"الجواب: لا نعلم حرجًا في ذلك سواء جعلت رأسها جديلة واحدة أو ثلاثًا أو ثنتين من الجانبين كله موسع فيه بحمد الله ولا نعلم فيه حرج.\nالمقدم: الحمد لله. بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7963/حكم-جعل-المراة-شعرها-جديلة-واحدة-من-الخلف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_196/19612.mp3","categories":["اللباس والزينة"]},{"id":9837,"question":"هذه الرسالة وردتنا من المرسلة دلال محمد المغربي من ..... تسأل عدة أسئلة تقول: هل قص الشعر من الأمام حرام؟ ووضع السحاب من الخلف ما حكمه؟","title":"حكم قص المرأة شعر رأسها ووضع السحاب من الخلف","answer":"الجواب: لا نعلم في ذلك شيئاً، لكن الأولى بالمرأة توفير شعرها؛ لأنه من زينتها ومن جمالها، لكن تخفيف الشعر وأخذ شيء منه تقصيره لا حرج فيه إن شاء الله، لكن الأولى والأفضل بقاؤه كاملاً؛ لما فيه من الجمال والزينة للمرأة، ولا سيما المتزوجة، فإذا أخذت بعضه وقصت بعضه فلا حرج في ذلك.\nوهكذا السحاب سواء من خلف أو من أمام لا حرج فيه إذا كانت العورة محفوظة، المهم حفظ العورة والعناية بالعورة وسترها، لكن كونه من أمام أفضل وإذا كان من خلف فلا نعلم فيه حرجاً إذا كانت العورة مستورة من أمام ومن خلف.","link":"https://binbaz.org.sa/fatwas/8001/حكم-قص-المراة-شعر-راسها-ووضع-السحاب-من-الخلف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_261/26102.mp3","categories":["اللباس والزينة"]},{"id":9873,"question":"أولى الرسائل وردت من السائلة: لطيفة بنت عبدالله بن شعلان تقول في رسالتها: الأم ذهبت في سابق الزمن إلى مكان الحشيش لجلبه لبهائمها ومواشيها ووضعت بنتها الصغيرة عند أمها، والبنت عمرها سنة فانفلتت من جدتها وذهبت إلى بركة الماء، وسقطت فيها وماتت، وقد جاء أخو الأم التي ذهبت إلى البر ورفع البنت وجدها ميتة، وتسأل هذه الأم عن حكمها وقد كبرت الآن وضعفت فماذا تفعل أفيدونا في ذلك؟","title":"ماذا يلزم الأم إذا ماتت ابنتها غرقاً دون تفريط منها؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فهذه الحادثة لا حرج على الوالدة فيها؛ لأنها لم تفرط ما دام جعلتها عند أمها والصبيان الصغار والبنات الصغار في الغالب لا ينضبطون، فكونها ذهبت إلى البركة وسقطت فيها، هذا أمر لا ينضبط، فلا حرج في ذلك، وليس عليها دية ولا كفارة. نعم.\nالمقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/8032/ماذا-يلزم-الام-اذا-ماتت-ابنتها-غرقا-دون-تفريط-منها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_263/26301.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":9899,"question":"من السودان السائل (م. ع. أ. أ) يقول هذا السائل: كما جاء في السنة فإنه لا يجوز للرجل أن يصافح أجنبية، فإذا وضعت المرأة ثوبها على كفها فهل تجوز المصافحة في مثل هذه الحالة؟","title":"حكم مصافحة بحائل وبدونه","answer":"الجواب: لا تجوز مصافحة النساء، النبي عليه الصلاة والسلام قال: إني لا أصافح النساء قالت عائشة رضي الله عنها: والله! ما مست يد رسول الله يد امرأة قط، ما كان يبايعهن إلا بالكلام فالمشروع للمرأة أن تكلم وتسأل من دون مصافحة ولا يجوز لها أن تصافح لا زيد ولا عمرو إلا محارمها، كأخيها وأبيها أما الأجناب لا ، تكلمهم من دون مصافحة ، ولو جعلت شيئاً على يدها ، سداً للباب لا تصافح ولو من دون حائل ، فالواجب عليها الحذر والبعد عن الشبهة وسد الباب ، فلا تصافح لا مكشوفة اليد ولا من وراء ساتر. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8067/حكم-مصافحة-بحاىل-وبدونه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_273/27311.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":9901,"question":"السائل يقول سماحة الشيخ: كيف يوفق الرجل بين الأحاديث الواردة في إسبال الإزار، فهل فعلًا لا تقبل صلاته، وهو يقول: وهل ما يلي الكعبين في النار ، أم أن ذلك في سبيل النهي على الفعل خيلاء وما حكم الإسبال بالنسبة للبنطال، إذا لم يكن خيلاء -أي: إسبال الرجل لبنطاله إلى ما بعد الكعبين- ولا يقصد الخيلاء؟ جزاكم الله خيراً.","title":"تحريم إسبال الإزار والبنطال وغيرهما","answer":"الجواب: الواجب عدم الإسبال ولو ما قصد الخيلاء، الواجب على المؤمن رفع ثيابه، وأن لا تنزل عن الكعبين هذا الرجل، أما المرأة فلا بأس لقوله ﷺ: ما أسفل من الكعبين من الإزار فهو في النار، وقوله ﷺ: ثلاثة لا يكملهم الله ولا ينظر إليهم يوم القيامة ولا يزكيهم ولهم عذاب أليم: المسبل إزاره، والمنان فيما أعطى، والمنفق سلعته بالحلف الكاذب، ولم يشترط الخيلاء، لكن إذا كان معه الخيلاء يكون أشد إثماً، فالواجب الحذر من الإسبال مطلقاً ولو من دون قصد الخيلاء، لأنه وسيلة للخيلاء، ولأن أمر الخيلاء أمر يتعلق بالقلوب لا يعلمه إلا الله -جل وعلا-، ولأنه فساد يفضي إلى تنجيس الثياب، وتوسيخ الثياب ويفضي إلى التكبر، والله المستعان.","link":"https://binbaz.org.sa/fatwas/8069/تحريم-اسبال-الازار-والبنطال-وغيرهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_273/27313.mp3","categories":["اللباس والزينة"]},{"id":9914,"question":"أيضًا للأخت السائلة من دولة الكويت في رسالتها سؤال تقول فيه: أنا أسلم على ابن خالي وابن عمي بيدي بدون حائل فهل هذا جائز، وإذا لم يكن جائزًا فهل يصح أن أضع على كفي إما عباية أو قفازًا وأسلم عليهم، فما الحكم في ذلك؟","title":"حكم مصافحة المرأة لأبناء عمها وخالها","answer":"الجواب: لا يجوز للمرأة أن تصافح الرجال إذا كانوا ليسوا محارم كابن خالها وابن عمها فإنهما ليسا محرمين، فليس لها أن تصافحهما لا بحائل ولا بغير حائل، وإنما تصافح محارمها كأخيها وعمها وخالها وأبيها أو النساء لا بأس أن تصافح النساء، يقول النبي ﷺ: إني لا أصافح النساء فليس للرجل أن يصافح المرأة وليس للمرأة أن تصافح الرجل الذي ليس محرمًا لها كابن خالها وابن عمها وجيرانها وزوج أختها وأخي زوجها كل هؤلاء أجانب ليس لها أن تصافحهم لا بيدها مكشوفة ولا من رواء حائل. نعم.","link":"https://binbaz.org.sa/fatwas/8089/حكم-مصافحة-المراة-لابناء-عمها-وخالها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_199/19904.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":9976,"question":"هذه رسالة من السائل موسى عبدالحميد سوري الجنسية مقيم في الرياض، الأخ موسى يقول في رسالته: إن زوجتي لا تصلي وقد أمرتها بالصلاة أكثر من مرة لكنها لم تستجب، وكذلك هي لا تتحجب وشعرها ظاهر على كل الناس، أفيدوني ماذا أفعل معها؟","title":"ما يفعل من ابتلي بزوجة تاركة للصلاة والحجاب؟","answer":"الجواب: هذه المرأة قد اجتمع فيها شران عظيمان أحدهما أعظم من الآخر.\nالشر الأول: عدم الصلاة، وهذا كفر أكبر على الصحيح.\nوالشر الثاني: عدم تسترها وحجابها، فالواجب أن تفارقها؛ لأنه ليس للمسلم أن يمسك الكافرة، قال الله تعالى: لا هُنَّ حِلٌّ لَهُمْ وَلا هُمْ يَحِلُّونَ لَهُنَّ [الممتحنة:10] فالواجب عليك فراقها ما دامت لم تستجب للنصيحة فالواجب فراقها وأبشر بأن يعوضك الله خيرًا منها، ونسأل الله لها الهداية.\nفالمقصود أن هذه المرأة فيها شران عظيمان أحدهما أعظم من الآخر وهو ترك الصلاة، هذا أعظم وهذا كفر أكبر، وكونها غير محتجبة لا في شعرها ولا في وجهها هذا أيضًا كبيرة عظيمة وشر عظيم.\nفالواجب عليك فراقها والحذر منها وإعطاؤها طلاقها نسأل الله لنا ولكم العافية، ومن ترك شيئًا لله عوضه الله خيرًا منه وسوف يعوضك الله سبحانه وتعالى فضلًا منه خيرًا منها وأصلح إن شاء الله. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/8133/ما-يفعل-من-ابتلي-بزوجة-تاركة-للصلاة-والحجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_200/20005.mp3","categories":["اللباس والزينة","حكم الصلاة وأهميتها","قضايا المرأة"]},{"id":9980,"question":"لها أيضًا أسئلة يعني متقاربة تقول فيها: ما حكم استعمال السحاب أو السوستة في ملابس النساء؟ ثم هل يجوز أن أغير شعري إلى اللون الأحمر؟ ثم هل يجوز استعمال الأسنان الذهبية للنساء والرجال؟","title":"حكم صبغ الشعر واستعمال الأسنان الذهبية","answer":"الجواب: أما السحاب فأمره سهل، كونه في الأمام أفضل وأولى ولكن إذا كان في الخلف لأسباب تقتضيها المصلحة فلا بأس لكن مع العناية بالستر مع العناية بستر العورة ستر البدن من الأمام و الخلف، تكون حريصة على ستر عورتها من أمامها وخلفها هذا هو الواجب، أما كون السحاب أمام أو خلف فأمره سهل ولكنه في الأمام أولى كالعادة القديمة المعروفة، ولأن ذلك أمكن في ضبط العورة وضبط اللباس على البدن.\nالمقدم: وبالنسبة لصبغ الشعر؟\nالشيخ: وأما صبغ الشعر فلا يجوز إذا كان بالسواد الخالص، أما إذا صبغ بالحمرة أو بالصفرة أو بسواد مخلوط بالحناء فلا بأس بذلك، وقد قال عليه الصلاة والسلام: غيروا هذا الشيب وجنبوه السواد فدل ذلك على أن تغيير الشيب سنة ومستحب لكن بغير السواد الخالص، وإذا غير الشعر بالأحمر أو بالأصفر فلا حرج في ذلك.\nالمقدم: وإذا كان يا شيخ لشابة مثلًا تريد تغيره مثلًا من الأسود؟\nالشيخ: إذا كان للجمال فلا بأس إذا كان للجمال فهو مسكوت عنه ليس فيه نهي. نعم.\nالمقدم: وبالنسبة للأسنان الذهبية للرجال والنساء؟\nالشيخ: جائز للنساء خاصة، أما للرجال فلا إلا للحاجة إذا احتاج الرجل ما هو للزينة احتاج لسقوط أسنانه ولأن الذهب أصبر وأنظف فإذا جعله للحاجة فلا بأس وإن جعل غيره من المعادن الأخرى فهو أولى وأحوط إن شاء الله، وإذا ربطه بأسلاك الذهب ربط أسنانه الأخرى بأسلاك الذهب فلا بأس، قد روي هذا عن جماعة من أصحاب النبي ﷺ.\nوالحاصل أنه إذا كان للحاجة فلا بأس، وقد ثبت عنه ﷺ أنه أمر بعض أصحابه لما قطع أنفه في بعض الحروب أن يجعل فضة فلما تغيرت عليه أمره أن يجعل مكانه ذهبًا، فدل ذلك على أن الذهب للحاجة لا بأس لا لأجل الزينة، وإذا جعل من المعادن الأخرى أسنانًا وربطها بشيء من الذهب فلا حرج في ذلك.\nأما النساء فأمرهن أوسع؛ لأنه أحل لهن الذهب والحرير دون الرجال. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8139/حكم-صبغ-الشعر-واستعمال-الاسنان-الذهبية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_200/20007.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":10000,"question":"رسالة وصلت إلى البرنامج من الأخت المستمعة: (ف. ع. أ) من الرياض، أختنا لها عدد من الأسئلة، تقول في أحدها: امرأة في الواحدة والأربعين من عمرها، يوجد في شعرها بعض شعرات بيضاء، وتريد أن تصبغ هذه الشعرات باللون الأسود لكي تتزين لزوجها، فما الحكم في ذلك؟","title":"حكم صبغ الشيب بالسواد","answer":"الجواب: يقول النبي ﷺ: غيروا هذا الشيب وجنبوه السواد فليس لها أن تصبغ الشعرات البيض بالسواد الخالص، ولكن تصبغ بالحناء غير الأسود، أو بصبغ آخر: أصفر أو أحمر أو بين السواد والحمرة، ولا يكون سوادًا خالصًا بالكلية، ولا حرج في ذلك، أما السواد الخالص فلا، تمنع من ذلك. نعم.\nالمقدم: جزكم الله خيرًا. عند النساء حناء يسمونه الحناء الأسود؟\nالشيخ: إذا كان يصبغ أسود لا يفعل، إذا كان أحمر أو بين الحمرة والسواد لا حرج.\nالمقدم: جزاكم الله خيراً، وإن كان اسمه حناء أسود؟\nالشيخ: وإن كان اسمه حناء نعم، فالعبرة بالحقائق لا بالأسماء. نعم.\nالمقدم: نعم.","link":"https://binbaz.org.sa/fatwas/8163/حكم-صبغ-الشيب-بالسواد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_331/331004.mp3","categories":["اللباس والزينة"]},{"id":10004,"question":"فتاة حجت حجة الفريضة، وكانت ساترة جسمها بالكامل عن الرجال الأجانب، شعرها ووجهها وسائر بدنها ماعدا كفيها، فقد بقيتا دون أن تغطيهما جهلًا منها لذلك، فما الحكم في ذلك، أجيبونا مأجورين؟","title":"حكم كشف المرأة كفيها في الحج","answer":"الجواب: ليس عليها حرج لجهلها، والمستقبل إن شاء الله تغطيهما بالقفازين أو بغيرهما، نعم، لكن في حال الإحرام لا تلبس القفازين ولا النقاب وهو البرقع ونحوه، ولكن تغطي وجهها في الإحرام بغير ذلك: كالخمار والجلباب ونحو ذلك، وهكذا تغطي يديها بالجلباب أو بالخمار أو بالعباءة وغير ذلك، في حال الإحرام لا تلبس القفازين ولا تلبس النقاب؛ لأن الرسول نهى عن ذلك عليه الصلاة والسلام. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8173/حكم-كشف-المراة-كفيها-في-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_331/33109.mp3","categories":["اللباس والزينة","محظورات الإحرام","قضايا المرأة"]},{"id":10019,"question":"مجموعة من الأخوات ونابت عنهن المستمعة ابتسام عبد الله من الرياض يسألن سؤالين، في السؤال الأول يقلن: نحن مجموعة من المعلمات تعاقدنا مع سائق باص لإيصالنا إلى المدرسة يوميًا والعودة بنا إلى المنازل، علمًا بأن السائق تركب معه زوجته، فهل في ذلك شيء؟","title":"حكم ركوب مجموعة من النساء مع سائق اصطحب زوجته","answer":"الجواب: لا حرج في هذا، هذا حسن، هذا عمل طيب لا بأس.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8188/حكم-ركوب-مجموعة-من-النساء-مع-ساىق-اصطحب-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_276/27607.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":10043,"question":"المستمعة فيحاء المطيري من عفيف في المملكة بعثت تسأل وتقول: هل تجوز الصلاة بالثوب الأبيض الذي فيه قليل من ألوان الأخرى والذي تتحجب به المرأة عند صلاتها؟","title":"حكم الصلاة في الثوب الأبيض الملون بغيره","answer":"الجواب: نعم تصح الصلاة في الثوب، لكن إذا كان يشبه ملابس الرجال فالواجب عليها تركه، أما إذا كان من ملابس النساء ومن اللباس اللاتي يعتدنه فلا بأس بذلك صلاتها صحيحة ..... صحيح، أما إذا كان لا، فيه تشبه فالصلاة صحيحة لكن ينبغي لها أن تبتعد عن ذلك وأن تترك الشيء الذي يشبه لباس الرجال؛ لأن الرسول ﷺ قال: لعن الله المرأة تلبس لبسة الرجل ولعن الله الرجل يلبس لبسة المرأة فالتشبه من الرجال بالنساء ممنوع وهكذا النساء بالرجال ممنوع، فالواجب على الجميع تقوى الله وعدم التشبه. نعم.\nالمقدم: جزاكم الله خيرًا، إذا صنع هذا القماش خصيصًا للنساء؟\nالشيخ: إذا كان لا يلبسه الرجال فلا يضر، إن كان على طريقة خاصة للنساء. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8212/حكم-الصلاة-في-الثوب-الابيض-الملون-بغيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_332/33211.mp3","categories":["اللباس والزينة","مسائل متفرقة في الصلاة"]},{"id":10103,"question":"سودانية في المملكة تقول هي: (هـ . ح. أ) تقول: أديت فريضة العمرة والحمد لله إلا أنني أحرمت من جدة أولاً ولبست القفازين، فماذا علي؟","title":"حكم لبس القفازين للمحرمة","answer":"الجواب: إذا كنت قادرة من الذهاب للعمرة فعليك الإحرام من ميقات الزيارة وهي من الوادي وادي القرن ، وادي الطائف، في الجو إن كنت في الطائرة أو في السيارة إن كنت في السيارة، فإذا جاوزت الميقات ولم تحرمي إلا من جدة فعليك دم يذبح في مكة للفقراء، أما إن كنت جئت مكة لغرضٍ من الأغراض ما قصدت العمرة، جئت جدة لغرض من الأغراض ما قصدت عمرة، ثم بدا لك وأنت في جدة أن تعتمري فلا حرج في إحرامك من جدة، لأنك ما نويت العمرة إلا فيها. أما إذا كنت نويتيها في الرياض ولكن لم تحرمي إلا في جدة فعليك دم.\nوأما القفازان فلا يجوز لبسهما للمحرمة، بل يجب أن تترك القفازين والنقاب حال الإحرام، فإذا لبستهما جاهلةً أو ناسيةً فلا شيء عليها. فإن تعمدت ذلك وهي تعلم الحكم فعليها كفارة وهي إطعام ستة مساكين أو ذبح شاة أو صيام ثلاثة أيام، مخيرة، إن شاءت أطعمت ستة مساكين ثلاثة أصواع كل صاع بين اثنين، أو تصوم ثلاثة أيام أو تذبح شاة، وهكذا الرجل، إذا فعل محظوراً كأن غطى رأسه أو لبس المخيط أو تطيب عامداً عالماً عليه كفارة، أما إذا فعل ناسياً أو جاهلا ً فلا شيء عليه. وهكذا المرأة إذا لبست النقاب أو القفازين ناسيةً أو جاهلة فلا شيء عليها في حال الإحرام.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8272/حكم-لبس-القفازين-للمحرمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_333/33314.mp3","categories":["اللباس والزينة","محظورات الإحرام","قضايا المرأة"]},{"id":10142,"question":"هذه رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات، تقول: من الحوطة تقول: هل يجوز للمرأة أن تقص شعرها من الأمام أو الخلف سواء للتجمل أمام زوجها أو لغير ذلك، وهل يجوز أن تقص وهي حائض جزاكم الله خيراً؟","title":"هل يجوز للمرأة أن تقص من شعرها للتجمل أمام زوجها؟","answer":"الجواب: قص الشعر تركه أولى لأن الشعر جمال، الرأس جمال، وطوله جمال، لكن إذا دعت الحاجة أو الزينة إلى قص بعضه فلا بأس، وقد ثبت أن أزواج النبي ﷺ لما توفي ﷺ قصصن بعض رءوسهن للراحة من بعض الكلفة. فإذا قصت للجمال أو للراحة من الكلفة والتعب فلا بأس، أما إذا كان لقصد التشبه بالكافرات لا، أو التشبه بالرجال لا، أما إذا قصت زينة للزوج أو لأنه يؤذيها بطوله فتخفف منه فلا حرج في ذلك. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8314/هل-يجوز-للمراة-ان-تقص-من-شعرها-للتجمل-امام-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_306/30603.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":10144,"question":"هذه رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات، تقول: من الحوطة تقول: هل يجوز للمرأة أن تقص شعرها من الأمام أو الخلف سواء للتجمل أمام زوجها أو لغير ذلك، وهل يجوز أن تقص وهي حائض جزاكم الله خيراً؟","title":"هل يجوز للمرأة أن تقص من شعرها للتجمل أمام زوجها؟","answer":"الجواب: قص الشعر تركه أولى لأن الشعر جمال، الرأس جمال، وطوله جمال، لكن إذا دعت الحاجة أو الزينة إلى قص بعضه فلا بأس، وقد ثبت أن أزواج النبي ﷺ لما توفي ﷺ قصصن بعض رءوسهن للراحة من بعض الكلفة. فإذا قصت للجمال أو للراحة من الكلفة والتعب فلا بأس، أما إذا كان لقصد التشبه بالكافرات لا، أو التشبه بالرجال لا، أما إذا قصت زينة للزوج أو لأنه يؤذيها بطوله فتخفف منه فلا حرج في ذلك. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8314/هل-يجوز-للمراة-ان-تقص-من-شعرها-للتجمل-امام-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_306/30603.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":10147,"question":"أخيراً تسأل وتقول: هل يجوز للمرأة أن تدخل السوق مع محرمها، ولكنه يبقى في السيارة وهي تنزل تقضي حاجتها مع أنها متحجبة وفي بعض الأحيان تخرج كفيها للحاجة فقط؟","title":"خروج المرأة إلى السوق دون محرم","answer":"الجواب: الذهاب إلى السوق ما يحتاج إلى محرم، إذا كان السوق آمن والطريق آمن ما في خطر فلا حاجة إلى محرم، المحرم في السفر أما إذا ذهب معها المحرم لخوف عليها من أذى السفهاء، أو لأن السوق يكون فيه اختلاط يخشى منه أو ما أشبهه من الخطر فلا بأس يكون معها المحرم طيب أو معها نساء أمينات طيبات واحدة أو أكثر إذا كانت تخشى من ذهابها وحدها، تذهب معها امرأة طيبة أو أكثر للتعاون معها على شراء الحاجة والرجوع، على كل حال إذا كان ما هناك خطر فلا ضرورة إلى محرم ولا غيره، أما إذا كان السوق فيه خطر أو تخشى من خطر أو تخشى من أذى بعض السفهاء يكون معها محرم أو يكون معها بعض النساء الطيبات اللاتي يعنها على السلامة من الأذى والحمد لله.\nولا تكشف يديها ولا غير يديها عليها الحجاب، الكف عورة والوجه عورة والقدم عورة، المرأة كلها عورة، يقول الرب : وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]، وفي الحديث يقول ﷺ: المرأة عورة، ولم يقل: إلا وجهها أو إلا يديها، جعلها عورة فعليها أن تستتر، ويقول الرب : وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ [النور:31]، واليد من الزينة والوجه من الزينة، وإذا كان في اليد حلي أو خضاب صار الأمر أعظم. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8317/خروج-المراة-الى-السوق-دون-محرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_306/30606.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":10155,"question":"تسأل -أيضاً- وتقول: بالنسبة لما تستعمله بعض النساء مما يسمى لفافات الشعر أو المطاوي كما يسمينه الذي يعمل على لف الشعر، هل يعتبر هذا تغيير لخلق الله أم يجوز للمرأة أن تستعمله؟","title":"حكم استعمال المرأة لما يلف شعرها من لفافات ونحوها","answer":"الجواب: لا أعلم فيه حرجاً، لف الشعر وربطه لا أعلم فيه شيئاً، قد يشبه أسنمة البخت التي جاءت في الحديث في قوله ﷺ: صنفان من أهل النار لم أرهما: رجال بأيديهم سياط كأذناب البقر يضربون بها الناس -يعني ظلماً- ونساء كاسيات عاريات مائلات مميلات، رءوسهن كأسنمة البخت المائلة لا يدخلن الجنة ولا يجدن ريحها، هؤلاء النساء المذمومات أخبر النبي ﷺ من علاماتهن أن رءوسهن كأسنمة البخت المائلة، قال أهل العلم في البخت المائلة: إن لها شبه السنامين بينهما فجوة، فإذا لبدت على رأسها أشياء تجعلها كالسنامين كره ذلك؛ لأنها تشبهت بهؤلاء النسوان اللاتي هذه علامتهن، أما إذا كان هذا التلبيد قليل ولا يشكل شبه سنامين وليس له ما يقربه من هذا الوصف فلا حرج فيه، إذا كانت قصدها أنه يؤذيها إذا كان عمايل مطروحة تؤذيها بعض الأحيان أو ترى أن هذا أستر لها في خروجها ودخولها بين أحمائها وغير أحمائها فلا حرج في ذلك، لكن عند الصلاة تحلها، تجعل عمايل على حالها وعند مسح الرأس تتركها حتى تمسح رأسها بالوضوء حتى يعم المسح الرأس، يعني من مقدم الرأس إلى آخر منابت الشعر، إلى مؤخر الرأس، تطرح العمايل حتى تمسح على جميع رأسها من مقدمه إلى آخره، وما انحدر من العمايل بعد ذلك لا يجب مسحه، المسح يكون من منابت الشعر المقدم إلى المؤخر، وتطرح العمايل حتى تمسح على مقدم رأسها ومؤخره، ولا تفعل أشياء مما يشبه من قال فيهن النبي ﷺ : كأسنمة البخت المائلة تبتعد عن هذا الوصف مهما أمكن. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8332/حكم-استعمال-المراة-لما-يلف-شعرها-من-لفافات-ونحوها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_307/30714.mp3","categories":["اللباس والزينة"]},{"id":10159,"question":"تسأل -أيضاً- وتقول: بالنسبة لما تستعمله بعض النساء مما يسمى لفافات الشعر أو المطاوي كما يسمينه الذي يعمل على لف الشعر، هل يعتبر هذا تغيير لخلق الله أم يجوز للمرأة أن تستعمله؟","title":"حكم استعمال المرأة لما يلف شعرها من لفافات ونحوها","answer":"الجواب: لا أعلم فيه حرجاً، لف الشعر وربطه لا أعلم فيه شيئاً، قد يشبه أسنمة البخت التي جاءت في الحديث في قوله ﷺ: صنفان من أهل النار لم أرهما: رجال بأيديهم سياط كأذناب البقر يضربون بها الناس -يعني ظلماً- ونساء كاسيات عاريات مائلات مميلات، رءوسهن كأسنمة البخت المائلة لا يدخلن الجنة ولا يجدن ريحها، هؤلاء النساء المذمومات أخبر النبي ﷺ من علاماتهن أن رءوسهن كأسنمة البخت المائلة، قال أهل العلم في البخت المائلة: إن لها شبه السنامين بينهما فجوة، فإذا لبدت على رأسها أشياء تجعلها كالسنامين كره ذلك؛ لأنها تشبهت بهؤلاء النسوان اللاتي هذه علامتهن، أما إذا كان هذا التلبيد قليل ولا يشكل شبه سنامين وليس له ما يقربه من هذا الوصف فلا حرج فيه، إذا كانت قصدها أنه يؤذيها إذا كان عمايل مطروحة تؤذيها بعض الأحيان أو ترى أن هذا أستر لها في خروجها ودخولها بين أحمائها وغير أحمائها فلا حرج في ذلك، لكن عند الصلاة تحلها، تجعل عمايل على حالها وعند مسح الرأس تتركها حتى تمسح رأسها بالوضوء حتى يعم المسح الرأس، يعني من مقدم الرأس إلى آخر منابت الشعر، إلى مؤخر الرأس، تطرح العمايل حتى تمسح على جميع رأسها من مقدمه إلى آخره، وما انحدر من العمايل بعد ذلك لا يجب مسحه، المسح يكون من منابت الشعر المقدم إلى المؤخر، وتطرح العمايل حتى تمسح على مقدم رأسها ومؤخره، ولا تفعل أشياء مما يشبه من قال فيهن النبي ﷺ : كأسنمة البخت المائلة تبتعد عن هذا الوصف مهما أمكن. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8332/حكم-استعمال-المراة-لما-يلف-شعرها-من-لفافات-ونحوها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_307/30714.mp3","categories":["اللباس والزينة"]},{"id":10162,"question":"من المكلا حضرموت إحدى الأخوات المستمعات بعثت تقول: أختكم في الله (خ. ح. العكبري )-فيما يبدو- لها ثلاثة أسئلة تدور حول خروج المرأة من بيتها إما للتعليم في المساجد أو للدعوة إلى الله أو للزيارة وصلة الأرحام، وتسأل: كيف يكون هذا ولا سيما إذا لم يكن لديها من يذهب بها في سيارته، هل تركب مع أجنبي جزاكم الله خيراً؟","title":"الضوابط الشرعية في خروج المرأة من بيتها","answer":"الجواب: هذا عمل طيب، خروجها للتعليم أو النصيحة أو عيادة المريض أو زيارة الأقارب الطيبين كل هذا عمل طيب، لكن عليها أن تتحرى الأمر الشرعي، تكون متسترة، بعيدة عن أسباب الفتنة، لا تبرج ولا تبد شيئاً من زينتها، وتكون متحفظة متسترة بعيدة عن أسباب الفتنة، ولا تخرج بطيب لأن الطيب يفتن الناس أيضاً، فتذهب إلى المسجد أو إلى المستشفى أو إلى جيرانها أو أقاربها لا بأس بذلك ولو وحدها، تمشي على قدميها إذا كان ما في خطر، كان المحل آمن فلا حرج تذهب على رجليها مثلما كان نساء الصحابة يخرجون في المدينة، أما إذا كان هناك خطر فليس لها الخروج إلا مع من تأمن، إما جاراً أمين أو امرأة طيبة تمشي معها في السوق حتى تصل، أما مع السواق في السيارة فلا؛ لأنه خطير، قد يذهب بها السواق إلى ما لا تحمد عقباه وليس باختيارها، فلا تذهب مع السائق وحدها لابد يكون معها آخر إما زوجة السائق أو شخص آخر أو محرمها إذا تيسر أو امرأة أخرى، يعني تكون على طريقة آمنة تذهب معها في طريقة مأمونة، لا تتهم فيها ولا تكون وحدها معه بل يكون معهم ثالث أو ثالث ورابع، لا بد من هذا، أما وحدها لا، لا تذهب معه وحدها، أو مع ثالث لكن متهم تتهم به لأن الثالث ليس بجيد يتهم فلا تكون معهم، لا تكون في السيارة مع السائق إلا في طريقة آمنة طريقة طيبة ليس فيها خلوة. نعم.\nالمقدم: جزاكم الله خيراً، سماحة الشيخ! فاتني أن أذكر أمراً رابعاً ألا وهو إجابة الدعوة ولا سيما في الأفراح؟\nالشيخ: لا بأس أيضاً كذلك هذا خروج شرعي، إجابة الدعوة للعرس أو لوليمة دعاها إليها أقاربها أو جيرانها وهي وليمة ليس فيها فتنة ولا فساد فلا بأس، تجيب الدعوة لعموم الحديث، يقول ﷺ في حق المؤمن: ويجيبه إذا دعاه، وقوله ﷺ: إذا دعي أحدكم فليجب، وهذا يعم الرجال والنساء، وفي الحديث الآخر: من لم يجب الدعوة فقد عصى الله ورسوله رواه مسلم ، إجابة الدعوة في حق الرجال والنساء أمر مطلوب واجب، لكن في حق الزوجة تكون بإذن زوجها، تكون الإجابة بإذن زوجها وتكون على طريقة آمنة ليس فيها خطر في دينها، فإذا كانت الدعوة سليمة والمحل سليم والإذن -والزوج إن كان لها زوج آذن- فلا حرج. نعم.\nالمقدم: جزاكم الله خيراً، إذاً نفس الشروط لطلب العلم وللدعوة إلى الله وللمستشفى تنطبق أيضاً على الذهاب لإجابة الدعوة.\nالشيخ: نعم نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8331/الضوابط-الشرعية-في-خروج-المراة-من-بيتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_307/30713.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":10181,"question":"تقول: أرجو أن تفيدوني مأجورين عن معنى النمص؟ وهل يشمل الوجه كله، أم الحاجب فقط؟ وهل إزالة الشارب بالنسبة للمرأة يعتبر منه؟ جزاكم الله خيراً.","title":"حكم النمص ومعناه","answer":"الجواب: النمص إزالة شعر الحاجبين، وهكذا شعر الوجه يقال له: نمص، والرسول ﷺ لعن النامصة والمتنمصة، لكن إذا كان هناك شعر يشوه الخلقة جاز للمرأة أخذه كالشارب واللحية؛ لأن هذا ليس من خصائصها بل هو للرجل، فإذا نبت فيها شوه خلقتها، فلهذا أجاز أهل العلم أخذ الشارب واللحية من المرأة حتى لا تكون مشوهة في خلقتها لدى زوجها ولدى من نظر إليها من أخواتها ومحارمها، والله المستعان. نعم.\nالمقدم: جزاكم الله خيراً، نقول: النمص أو النمص؟\nالشيخ: النمص نعم. بالتسكين. نعم.\nالمقدم: النمص؛ جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8348/حكم-النمص-ومعناه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_308/30809.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":10197,"question":"إحدى الأخوات المستمعات تسأل عن النقاب في الحج هل يجوز أو لا؟ وإذا كانت منتقبة ثم وضعت من فوق النقاب غطاءً خفيفاً، هل يكون هذا قد أثر على حجها؟","title":"حكم انتقاب المرأة وهي محرمة وتغطية الوجه بغير النقاب","answer":"الجواب: المرأة في الحج لا تنتقب ولا في العمرة كذلك وقت الإحرام، يقول النبي ﷺ فيما رواه البخاري في صحيحه من حديث ابن عمر: ولا تنتقب المرأة ولا تلبس القفازين يعني: في حال الإحرام، لا تلبس النقاب وهو شيء يصنع للوجه يقال له: نقاب، يصنع للوجه تلبسه المرأة في وجهها وفيه نقبان للعينين أو نقب واحد للعين ويسمى: نقاباً، لا تلبسه في حال الإحرام، ولكن تغطي وجهها بغير ذلك، جاء عن عائشة رضي الله عنها أنها قالت: كنا مع النبي ﷺ ونحن محرمات إذا دنا منا الركبان سدلت إحدانا جلبابها على وجهها -أو قالت: خمارها على وجهها- فإذا بعدوا كشفنا فالمرأة كذلك إذا دنا منها الرجال تسدل خماراً أو غيره على وجهها، فإذا بعدوا عنها وليس عندها أحد تكشفه، أما النقاب لا تلبسه المصنوع للوجه الذي يخاط ويصنع لقدر الوجه به نقب للعين أو نقبين للعينين، هذا لا تلبسه في حال الإحرام، كما أن الرجل لا يلبس أيضاً جوربين في الإحرام ولا خفين ومع هذا يغطي رجليه بما شاء من إزاره وغيره، أو مطرحة في البرد، لكن هذا هذا شيء مخصوص وهو المخيط على قدر الوجه، والمخيط على قدر الخفين من الجوربين، لا تلبسه المرأة ولا الرجل جميعاً، ولكن تغطي وجهها بالجلباب بالخمار، تغطي يديها بالجلباب بغيره لا بأس، مثلما أن الرجل لا يلبس القميص ولا العمامة، ولكن يغطي بدنه بالإزار والرداء، يغطيه عند البرد باللحاف طراحة ... يضعها على بدنه للدفء، لا بأس بهذا. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8374/حكم-انتقاب-المراة-وهي-محرمة-وتغطية-الوجه-بغير-النقاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_309/30913.mp3","categories":["اللباس والزينة","محظورات الإحرام","قضايا المرأة"]},{"id":10198,"question":"من جمهورية مصر العربية المستمعة (ع. م. ع) بعثت برسالة ضمنتها جمعاً من الأسئلة في أحدها تقول: هل العطور المنتشرة حالياً والتي يدخل في صناعتها نسبة من الكحول يجوز استعمالها وأداء الصلاة بها، أم لا بد من إزالتها قبل الصلاة، سواء كان على أعضاء الوضوء أو على غير أعضاء الوضوء؟","title":"حكم التطيب بالعطور المخلوطة بالكحول","answer":"الجواب: الأصل في الأطياب وغيرها الطهارة، هذا هو الأصل في الأطياب، الأصل فيها الطهارة، في الملابس الطهارة، في الأرض الطهارة، في المياه الطهارة حتى تعلم أيها المؤمن أو أيها المؤمنة النجاسة، فإذا علم أن هذا الطيب فيه كحول يسكر كثيرها فليس لك استعمال ذلك، كالطيب المسمى: الكالونيا هذه ثبت عندنا بشهادة الأطباء الموثوقين أنه يشتمل على مسكر من السبيرتو فلا ينبغي استعماله بل لا يجوز استعمال الكالونيا لما فيها من الخلط المسكر، أما الأطياب الأخرى فلم يثبت لدي ما يدل على أن فيها مسكراً، أو أن فيها ما يسكر كثيره، فالأصل في ذلك الطهارة والسلامة حتى يعلم المؤمن أو المؤمنة أن هذا الطيب فيه ما يسكر كثيره، فمن علم ذلك فليدع هذا الطيب الذي فيه المسكر، وإذا أصاب ثوبه منه شيء غسله؛ لأن جمهور أهل العلم يقولون: كل مسكر نجس، هذا قول الأكثرين من أهل العلم، يرون أن ما أسكر فهو نجس، فالمؤمن يحتاط لدينه إذا أصابه من ذلك شيء يغسله احتياطاً وخروجاً من خلاف العلماء، أما إذا لم يعلم فالأصل الطهارة، إذا لم تعلم أن هذا الطيب فيه ما يسكر كثيره فالأصل السلامة والحمد لله، تصلي في الثوب الذي أصابه، وما أصاب بدنك كذلك لا يضر حتى تعلم يقيناً أن في هذا الطيب ما يسكر كثيره. والله ولي التوفيق. نعم.\nالمقدم: جزاكم الله خيراً، سماحة الشيخ! تفضلتم وقلتم: إنه إذا أصاب اللباس فعلى المرء أن يغسله إذا علم أن هذا الطيب أو هذه الكلونيا فيها شيء مسكر، ماذا إذا أصاب عضواً من جسم الإنسان، يغسله أيضاً؟\nالشيخ: كذلك يغسله إذا أصابه، ... عند الأكثر. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8358/حكم-التطيب-بالعطور-المخلوطة-بالكحول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_309/30902.mp3","categories":["اللباس والزينة"]},{"id":10228,"question":"هل يجوز كشف وجه المرأة أمام غلام في سن العاشرة؟","title":"حكم كشف المرأة وجهها أمام من لم يبلغ الحلم","answer":"الجواب: لا يجب الحجاب إلا إذا بلغ الرجل، قبل البلوغ.. ولهذا قال تعالى: وَإِذَا بَلَغَ الأَطْفَالُ مِنْكُمُ الْحُلُمَ فَلْيَسْتَأْذِنُوا [النور:59] فدل على أنهم لا يحتجب عنهم إلا بعد البلوغ، وقبل ذلك لا يجب الاستئذان دائمًا؛ لأنهم لا يحتجب عنهم حتى يبلغوا الحلم، وابن عشر في الغالب ليس ممن يحتلم في الغالب، وقد يحتلم إذا كمل العشر ولكن الغالب أنه صغير، فإذا احتجبت عنه احتياطًا لأنه مراهق هذا حسن، وإلا فلا يلزمها إلا إذا علم أنه كمل الخمسة عشر سنة أو احتلم بإنزال المني عن شهوة أو بإنبات الشعر الذي حول الفرج شعر خشن، قال جل وعلا في غير البالغين: يَا أَيُّهَا الَّذِينَ آمَنُوا لِيَسْتَأْذِنْكُمُ الَّذِينَ مَلَكَتْ أَيْمَانُكُمْ وَالَّذِينَ لَمْ يَبْلُغُوا الْحُلُمَ مِنْكُمْ ثَلاثَ مَرَّاتٍ مِنْ قَبْلِ صَلاةِ الْفَجْرِ وَحِينَ تَضَعُونَ ثِيَابَكُمْ مِنَ الظَّهِيرَةِ وَمِنْ بَعْدِ صَلاةِ الْعِشَاءِ ثَلاثُ عَوْرَاتٍ لَكُمْ لَيْسَ عَلَيْكُمْ وَلا عَلَيْهِمْ جُنَاحٌ بَعْدَهُنَّ طَوَّافُونَ عَلَيْكُمْ بَعْضُكُمْ عَلَى بَعْضٍ [النور:58].\nفالمقصود أنهم إذا كانوا دون البلوغ فالاستئذان يكون في هذه الأوقات الثلاثة: قبل صلاة الفجر، وحين الظهيرة، وبعد صلاة العشاء، للآية الكريمة، وهكذا المملوك يستأذن في هذه الأوقات الثلاثة بخلاف من بلغ الحلم غير المماليك فإنه يستأذن في جميع الأوقات لقوله تعالى: وَإِذَا بَلَغَ الأَطْفَالُ مِنْكُمُ الْحُلُمَ فَلْيَسْتَأْذِنُوا كَمَا اسْتَأْذَنَ الَّذِينَ مِنْ قَبْلِهِمْ [النور:59] يعني: حتى يتسنى للمرأة الحجاب عنهم، والتحرز من نظرهم إليها، وإذا كان مراهقًا فالتحجب من باب الاحتياط؛ لأنه قد يكون بلغ وهي لا تعلم، والرسول ﷺ يقول: دع ما يريبك إلى ما لا يريبك اللهم صل وسلم عليه دع ما يريبك إلى ما لا يريبك فإذا احتجبت المرأة عن المراهق في الغطاء كان ذلك أحوط لها وأولى، ولكنه لا يجب حتى يبلغ الحلم. نعم.","link":"https://binbaz.org.sa/fatwas/8387/حكم-كشف-المراة-وجهها-امام-من-لم-يبلغ-الحلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_335/33505.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":10304,"question":"ما حكم لبس البنطلون للنساء وللرجال؟","title":"حكم لبس البنطلون للنساء والرجال","answer":"الجواب: لا أعلم فيه مانعاً إذا كان على هيئة ليس فيها ما يصف العورة، بل يستر العورة وليس فيه تشبه، فالبنطلون الذي يختص بالرجال لا تلبسه المرأة والذي يختص بالمرأة لا يلبسه الرجال، وإذا كان على هيئة يختص بالكفار إذا كان على هيئة تختص الكفار لا يلبسها المسلم أيضاً.\nفالحاصل: أن الرجل والمرأة كل منهما يتوخى ويتحرى أن يكون لباسه لا يشبه لباس الآخر، لا في البنطلون ولا غيره، وأن يكون لا يشبه أيضاً لباساً يختص الكفار، أما المشترك الذي لا يخص الكفار مشترك فلا بأس، نعم. وهكذا المشترك الذي لا يخص النساء ولا الرجال كالخاتم من الفضة لا حرج في ذلك شيء لا يخص الجميع نعم، لا يخص أحداً. نعم.\nالمقدم: الواقع من صفة البنطلون سماحة الشيخ أنه يفصل أعضاء الجسم؟\nالشيخ: إذا كان يفصل العورة وأعضاء الجسم يفتن الناس ينبغي للمرأة ألا تلبسه إلا عند زوجها. نعم.\nالمقدم: جزاكم الله خيرا، أمام محارمها؟\nالجواب: كذلك ينبغي تركه.\nالمقدم: تركه.\nالشيخ: حذراً من الفتنة. نعم.","link":"https://binbaz.org.sa/fatwas/8482/حكم-لبس-البنطلون-للنساء-والرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_313/31308.mp3","categories":["اللباس والزينة"]},{"id":10313,"question":"ما حكم لبس البنطلون للنساء وللرجال؟","title":"حكم لبس البنطلون للنساء والرجال","answer":"الجواب: لا أعلم فيه مانعاً إذا كان على هيئة ليس فيها ما يصف العورة، بل يستر العورة وليس فيه تشبه، فالبنطلون الذي يختص بالرجال لا تلبسه المرأة والذي يختص بالمرأة لا يلبسه الرجال، وإذا كان على هيئة يختص بالكفار إذا كان على هيئة تختص الكفار لا يلبسها المسلم أيضاً.\nفالحاصل: أن الرجل والمرأة كل منهما يتوخى ويتحرى أن يكون لباسه لا يشبه لباس الآخر، لا في البنطلون ولا غيره، وأن يكون لا يشبه أيضاً لباساً يختص الكفار، أما المشترك الذي لا يخص الكفار مشترك فلا بأس، نعم. وهكذا المشترك الذي لا يخص النساء ولا الرجال كالخاتم من الفضة لا حرج في ذلك شيء لا يخص الجميع نعم، لا يخص أحداً. نعم.\nالمقدم: الواقع من صفة البنطلون سماحة الشيخ أنه يفصل أعضاء الجسم؟\nالشيخ: إذا كان يفصل العورة وأعضاء الجسم يفتن الناس ينبغي للمرأة ألا تلبسه إلا عند زوجها. نعم.\nالمقدم: جزاكم الله خيرا، أمام محارمها؟\nالجواب: كذلك ينبغي تركه.\nالمقدم: تركه.\nالشيخ: حذراً من الفتنة. نعم.","link":"https://binbaz.org.sa/fatwas/8482/حكم-لبس-البنطلون-للنساء-والرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_313/31308.mp3","categories":["اللباس والزينة"]},{"id":10343,"question":"من الدوحة قطر رسالة من المستمع (خ. ع. م) أخونا يسأل خمسة أسئلة في أحدها يقول: هل يجوز صبغ شعر الرأس والشارب بالسواد؟","title":"هل يجوز صبغ شعر الرأس والشارب بالسواد؟","answer":"الجواب: الصبغ بالسواد لا يجوز لا للرجل ولا للمرأة لا في الرأس ولا في اللحية، إذا كان سواداً خالصاً، لقول النبي ﷺ: غيروا هذا الشيب واجتنبوا السواد، وجاء هذا المعنى في عدة أحاديث، ومنها قوله ﷺ: يكون في آخر الزمان قوم يخضبون بالسواد كحواصل الحمام لا يريحون رائحة الجنة.\nفالحاصل: أنه لا يجوز الصبغ بالسواد الخالص للحية ولا للرأس، لا للرجل ولا للمرأة، ولكن يستحب التغيير بغير السواد بالحمرة والصفرة أو بالسواد مع الحمرة مخلوط كالحناء والكتم يكون سواد مخلوطاً بحمرة لا بأس بذلك، أما السواد الخالص فلا.\nوالسنة للرجل والمرأة تغيير الشيب لا يبقى أبيض السنة تغييره، لقوله ﷺ: غيروا هذا الشيب، ولقوله ﷺ: إن اليهود والنصارى لا يصبغون فخالفوهم، يعني اصبغوا خلافاً لهم لكن بغير السواد. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8520/هل-يجوز-صبغ-شعر-الراس-والشارب-بالسواد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_316/31605.mp3","categories":["اللباس والزينة"]},{"id":10346,"question":"أخيراً يسأل ويقول: هل يجوز مصافحة المرأة العجوز؟","title":"حكم مصافحة المرأة العجوز","answer":"الجواب: مصافحة النساء لا تجوز، سواء كن عجائز أو شابات، لقول النبي ﷺ: إني لا أصافح النساء، لما تقدمت إليه امرأة في وقت البيعة للمصافحة قال: إني لا أصافح النساء، وقالت عائشة رضي الله عنها : والله ما مست يد رسول الله يد امرأة قط، ما كان يبايعهن إلا بالكلام، ومرادها رضي الله عنها يعني: غير محارم، يعني: ما كان يصافحهن، أما المحارم فلا بأس كان يصافح ابنته فاطمة ويصافح المحارم عليه الصلاة والسلام، ولا حرج أن الإنسان يصافح زوجته وأخته وعمته وأمه وجميع محارمه، وإنما الممنوع أن يصافح امرأة أجنبية كزوجة أخيه أو أخت زوجته أو غيرهما هذا لا يجوز وهو من وسائل الشر ولا يجوز لا مع العجوز ولا مع الشابة، هذا هو الصواب حتى ولو كان من وراء حائل ولو لفت على يدها شيئاً، فالذي ينبغي أن لا يصافحها مطلقاً؛ لأن مصافحتها مع وجود حائل وسيلة إلى المصافحات الأخرى بدون حائل، فالواجب ترك الجميع أخذاً بقوله ﷺ: إني لا أصافح النساء، والله يقول سبحانه: لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ [الأحزاب:21]، قال بعض أهل العلم: إن المصافحة أشد من النظر إلى المرأة بالشهوة لأن المصافحة قد تؤثر في الإنسان أكثر مما يؤثره النظر، نسأل الله للجميع التوفيق والهداية. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8527/حكم-مصافحة-المراة-العجوز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_316/31609.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":10351,"question":"من الأردن المستمعة ياسمين أحمد تسأل عن حكم إزالة الشعر الواقع في الوسط بين الحاجبين، هل يجوز للمرأة إزالته أو لا؟","title":"حكم إزالة الشعر بين الحاجبين","answer":"الجواب: لا أعلم مانعاً من ذلك لأنه ليس من الحاجبين وإن تركته احتياطاً فحسن، وأما زواله فلا أعلم فيه بأساً؛ لأنه ليس من الحاجبين اللذين جاء فيهما النهي عن النمص وإن تركته أخذاً بقول من قال: إن النمص يشمل الشعر بجميع الوجه، فهذا من باب الاحتياط، من باب: دع ما يريبك إلى ما لا يريبكوإلا فالأصل أنه ليس من الحاجبين وإنما هو جزء بينهما، وقد يسبب شيئاً من التشويه أو الكراهة من الزوج.\nفالحاصل: أنه لا حرج فيه إن شاء الله وإن ترك على سبيل الاحتياط فأرجو أن ذلك حسن إن شاء الله عملاً بالعموم والله ولي التوفيق. نعم.\nالمقدم: جزاكم الله خيراً، تسأل إذا كان للمرأة شارب فهل يجوز لها زواله؟\nالشيخ: نعم إذا كان فيها شيء يشوه الخلقة كالشارب واللحية فإنها تزيل ذلك، أو كان شعراً في الوجه يشوه الخلقة زائد على المعتاد فإنها تزيله؛ لأنه ليس من النمص، النمص: هو إزالة الحاجبين أو الشعر الذي في الوجه المعتاد الذي ليس فيه تشويه يترك؛ لأنه ﷺ: لعن النامصة والمتنمصة، وقال جماعة من أئمة اللغة: إن النمص أخذ شعر الحاجبين، وقال آخرون: إنه أخذ شعر الوجه.\nفينبغي ترك ذلك إلا إذا كان فيه تشويه كالشارب واللحية والشعور الزائدة في الوجه المستنكرة، فهذا لا بأس بإزالته.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8529/حكم-ازالة-الشعر-بين-الحاجبين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_316/31610.mp3","categories":["اللباس والزينة"]},{"id":10355,"question":"أخيراً يسأل ويقول: هل يجوز مصافحة المرأة العجوز؟","title":"حكم مصافحة المرأة العجوز","answer":"الجواب: مصافحة النساء لا تجوز، سواء كن عجائز أو شابات، لقول النبي ﷺ: إني لا أصافح النساء، لما تقدمت إليه امرأة في وقت البيعة للمصافحة قال: إني لا أصافح النساء، وقالت عائشة رضي الله عنها : والله ما مست يد رسول الله يد امرأة قط، ما كان يبايعهن إلا بالكلام، ومرادها رضي الله عنها يعني: غير محارم، يعني: ما كان يصافحهن، أما المحارم فلا بأس كان يصافح ابنته فاطمة ويصافح المحارم عليه الصلاة والسلام، ولا حرج أن الإنسان يصافح زوجته وأخته وعمته وأمه وجميع محارمه، وإنما الممنوع أن يصافح امرأة أجنبية كزوجة أخيه أو أخت زوجته أو غيرهما هذا لا يجوز وهو من وسائل الشر ولا يجوز لا مع العجوز ولا مع الشابة، هذا هو الصواب حتى ولو كان من وراء حائل ولو لفت على يدها شيئاً، فالذي ينبغي أن لا يصافحها مطلقاً؛ لأن مصافحتها مع وجود حائل وسيلة إلى المصافحات الأخرى بدون حائل، فالواجب ترك الجميع أخذاً بقوله ﷺ: إني لا أصافح النساء، والله يقول سبحانه: لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ [الأحزاب:21]، قال بعض أهل العلم: إن المصافحة أشد من النظر إلى المرأة بالشهوة لأن المصافحة قد تؤثر في الإنسان أكثر مما يؤثره النظر، نسأل الله للجميع التوفيق والهداية. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8527/حكم-مصافحة-المراة-العجوز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_316/31609.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":10364,"question":"يسأل سماحتكم يحفظكم الله ويقول: ما حكم جلوس الإخوان مع زوجاتهم، سواء في مجلس واحد، حيث تكون النساء متسترات، وما حكم كشف الوجه؟","title":"حكم جلوس الإخوة مع زوجاتهم في مجلس واحد","answer":"","link":"https://binbaz.org.sa/fatwas/8536/حكم-جلوس-الاخوة-مع-زوجاتهم-في-مجلس-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_279/27913.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":10375,"question":"في الحديث الوارد عن ابن عمر رضي الله عنهما قال: قال رسول الله ﷺ: من جر ثوبه خيلاء لم ينظر الله إليه يوم القيامة فقالت أم سلمة رضي الله عنها: فكيف تصنع النساء بذيولهن؟ قال: يرخين شبرا قالت: إذًا تنكشف أقدامهن. قال: فيرخينه ذراعًا ولا يزدن عليه أو كما قال عليه الصلاة والسلام، فكيف إذا كانت الزيادة هل تكون من الكعبين أو من رءوس الأصابع؟","title":"حد الإسبال للمرأة وحرمة الإسبال للرجال","answer":"","link":"https://binbaz.org.sa/fatwas/8547/حد-الاسبال-للمراة-وحرمة-الاسبال-للرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_339/33906.mp3","categories":["اللباس والزينة"]},{"id":10415,"question":"في قريتنا يقوم أهل الحاج إلى بيت الله بالتحضير لاستقباله بأن يرسموا الكعبة والمسجد النبوي على الجدار، ويكتبوا عبارات الترحيب، كما يلونون الحجارة باللون الأبيض، فهل ذلك جائز أم أنه بدعة جزاكم الله خيرًا؟","title":"حكم رسم الكعبة على الجدران ابتهاجاً بعودة الحاج","answer":"الجواب: أما وضع صور الكعبة والمسجد فالأولى ترك ذلك، لأن هذا قد يفضي إلى الغلو في هذه الأشياء، قد يفضي استقبال الكعبة ولو إلى غير القبلة؛ لأنه وضعت في غير القبلة، قد يفضي إلى اعتقاد أن هذا سنة وقربة، فالذي ينبغي ترك ذلك، أما تزيين البيت وتجميل البيت هذا أمره واسع، كنس البيت، تجميل الجدران إذا كانت فيها وساخة هذا شيء لا بأس به، من باب التجمل، أما كونه يرسم الكعبة أو المسجد الحرام أو المسجد النبوي فينبغي ترك ذلك، ولا يجوز رسم الكعبة؛ لأن الناس قد يغلون فيها، وقد يدعونها من دون الله، قد يستقبلونها في الصلاة وهي في جهة غير القبلة، فالحاصل أن هذا لا ينبغي.\nالمقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8588/حكم-رسم-الكعبة-على-الجدران-ابتهاجا-بعودة-الحاج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_280/28016.mp3","categories":["اللباس والزينة"]},{"id":10430,"question":"يقول سؤال آخر يقول فيه: هل تجوز مصافحة النساء كزوجة الخال وزوجة ابن العم وزوجة الأخ أو ما أشبه ذلك؟","title":"حكم مصافحة غير المحارم","answer":"أما زوجة أبيه فلا بأس، زوجة ابنه ابن ابنه، زوجة جده لا بأس فهؤلاء محارم، زوجة يعني: أبنائه أو أبناء أبنائه، أو أبناء بناته محارم، وهكذا زوجات أبيه وأجداده محارم؛ لأن الله يقول سبحانه: وَلا تَنكِحُوا مَا نَكَحَ آبَاؤُكُمْ مِنَ النِّسَاءِ [النساء:22]، ويقول سبحانه في المحرمات: وَحَلائِلُ أَبْنَائِكُمُ الَّذِينَ مِنْ أَصْلابِكُمْ [النساء:23]، يعني: غير الأدعياء تحرز من الأدعياء؛ لأن العرب كانت تتبنى بعض الناس كان العرب يتبنون بعض الرجال وبعض البنات يقول: هذا ولدي ويربيه وينسبه إليه، ويسمونه الولد بالتبني، كما كان النبي ﷺ تبنى زيد بن حارثة وكان يدعى زيد بن محمد فلما أنزل الله: ادْعُوهُمْ لِآبَائِهِمْ [الأحزاب:5]، دعي إلى أبيه زيد بن حارثة ، فهكذا يجب أن لا يتبنى أحد أحدًا، بل كل واحد يدعى إلى أبيه. فقوله: مِنْ أَصْلابِكُمْ [النساء:23] ذكر علماء التفسير: أنه تحرز من الأدعياء، أما ابنه من الرضاعة فهو كالنسب، فزوجة ابنه من الرضاعة محرم كابنه من النسب وهكذا أبوه من الرضاعة زوجته محرم كأبيه من النسب، لقوله ﷺ: يحرم من الرضاعة ما يحرم من النسب. نعم.","link":"https://binbaz.org.sa/fatwas/8601/حكم-مصافحة-غير-المحارم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_341/34106.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":10492,"question":"تقول أيضًا: بعض الأخوات ذوات الشعر الخشن يضعن مادة للشعر تنعمه تنعيمًا شديدًا، وتظل فاعلية هذه المادة ستة أشهر تقريبًا، ثم يبطل مفعولها ويعود الشعر كما كان، وقد قالت لي إحداهن: إنها تلاحظ وكأنه على الشعر شيء ما وتخشى أن يمنع وصول الماء إلى الشعر حال الوضوء لذلك لم تعد تستخدمه، فما هو توجيهكم جزاكم الله خيراً؟","title":"حكم وضع مادة للشعر تنعمه لمدة طويلة","answer":"الجواب: إذا كان فيه مصلحة فلا بأس، إذا كان فيه مصلحة وهو مادة طاهرة فلا بأس كالحناء وأشباهه لا بأس، وتمسح عليه مثل ما تمسح على الرأس الذي عليه آثار الحناء ونحوها. نعم.\nالمقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8667/حكم-وضع-مادة-للشعر-تنعمه-لمدة-طويلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_281/28119.mp3","categories":["اللباس والزينة"]},{"id":10554,"question":"النساء في قريتنا لم يلتزمن بالحجاب الشرعي وأزواجهم وأولياء أمورهم يعلمون أن الحجاب من أوامر الله ، ومن أوامر رسوله ﷺ لكنهم لم يمتثلوا بذلك، نريد من سماحتكم أن تتحدثوا عن الحجاب بالتفصيل، لعل الله  أن ينفع به هؤلاء الناس جزاكم الله خيرا؟","title":"الحث على التزام النساء بالحجاب الشرعي","answer":"الجواب: الواجب على كل مسلمة الحجاب عند الرجل الأجنبي، وعلى أولياء النساء أن يتعاونوا في هذا، وأن يلزموهن بذلك، وعلى هيئات الأمر بالمعروف والنهي عن المنكر الأمر بذلك والإلزام بذلك، حتى يحصل التعاون من الجميع؛ لأن الله سبحانه يقول: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2] ويقول سبحانه: وَالْعَصْرِ ۝ إِنَّ الإِنسَانَ لَفِي خُسْرٍ ۝ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ [العصر:1-3] والله سبحانه يقول: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] ويقول جل وعلا في سورة النور: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ .. [النور:31] الآية، والوجه من الزينة، وهكذا القدمان من الزينة، هكذا الرأس من الزينة، وهكذا ...... من الزينة، وهي من أسباب الفتنة، إبداء هذه الأمور لغير المحرم من الفتنة، ويقول جل وعلا: يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلابِيبِهِنَّ ذَلِكَ أَدْنَى أَنْ يُعْرَفْنَ فَلا يُؤْذَيْنَ [الأحزاب:59].\nفالواجب التعاون في هذا حتى تكون المرأة مستورة في وجهها وكفيها وقدميها وشعرها عند غير محرمها، وزوج أختها ليس محرماً لها، وأخو زوجها وعمه وخاله ليس محرماً لها، أما أبو زوجها وجد زوجها وابن زوجها هؤلاء محارم، وهكذا بنو البنين وبنو البنات محارم، وهذا المقام يحتاج إلى عناية ويحتاج إلى صبر وخوف من الله ، وعلى محاربة للعادات السيئة التي تخالف الشرع، فالمؤمن يحارب العادة المخالفة للشرع، وهكذا المؤمنة تحارب كل عادة تخالف الشرع، فالدين ليس بالعادات الدين متلقى عن الله وعن رسوله ﷺ، والرسل إنما عاداهم الناس بالعادات.\nفالواجب على أهل الإسلام أن يحذروا العادات المخالفة للشرع وأن يتعاونوا على تركها والحذر منها حتى يستقيم الجميع على المنهج الشرعي، في هذا الباب وغيره، نسأل الله للجميع الهداية. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8729/الحث-على-التزام-النساء-بالحجاب-الشرعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_321/32109.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":10589,"question":"المستمع علي محمد سعيد عباس سوداني مقيم في عرعر حين كتب الرسالة، يسأل ويقول: عندنا في السودان عادات وتقاليد، منها: عندما يتزوج أي إنسان لازم يضع على رجليه وأيديه الحناء ويلبسونه الحرير، فما حكم ما يفعلون؟","title":"حكم استعمال الحناء للرجال ولبس الحرير","answer":"الجواب: الحناء من صفات النساء، فينبغي أن لا يفعله الرجل؛ لأنه من التشبه بالنساء؛ لكن إذا كان في بلد يفعله الرجال دون النساء ما يكون تشبه، إذا كان في بلد من عادتهم تعاطي الحناء في رجليه، أو في يديه؛ لأسباب تقتضي ذلك إما علاج مرض، أو أسباب اقتضت الحناء، ليس قصده التشبه بالنساء لعلة فهذا لا يكون من باب التشبه، أو كانت العادة عندهم يفعله الرجال في بعض الأوقات والنساء لا يفعلنه ليس من فعل النساء، صار من فعل الرجال، هذا يكون عادة خاصة عند أهل البلد، أما المعروف عندنا فالحناء من خصائص النساء لا يجوز فعله للرجال؛ لأنه تشبه بالنساء، لكن لو وجد بلد انعكس فيها الأمر صار الحناء للرجل في يده أو في رجله أو في رأسه والنساء لا يتعاطين ذلك؛ فالأظهر أنه لا يكون فيه تشبه؛ لأنه من خصائص الرجال حينئذ في تلك البلد وهكذا لبسات الحرير يجب أن يحذره المؤمن؛ لأنه من خصائص النساء، لا يتشبه بالنساء، الرسول -صلى الله عليه وسلم- نهى عن لبس الحرير للرجال، وقال: من لبسه في الدنيا لم يلبسه في الآخرة، وقوله: فأحل الذهب والحرير لإناث أمتي وحرم على ذكورهم هكذا قال ﷺ، فالمقصود أن أن الحرير من خصائص النساء، أحله الله للنساء للتجمل، أما الرجل فليس له لبس الحرير، إلا الشيء القليل موضع إصبعين، أو ثلاث، أو أربع، فهذا جاء به الحديث، مستثنى، الشيء القليل....، رشق، أو يكف به طرف الثوب أو ما أشبهه الشيء القليل الذي لا يزيد عن أصبعين أو ثلاث أو أربع يعني: عن محل إصبعين أو ثلاث أو أربع. نعم.\nالمقدم: جزاكم الله، إذا وجد في بلدٍ ما أن الحناء مشترك بين النساء والرجال فما الحكم لو تكرمتم؟\nالشيخ: هذا والله أعلم مما يتجنبه الرجل؛ لأنه موجود في بعض البلدان يختص بالنساء، كونه يتجنبه الرجل هذا من باب الحيطة، أما الحكم بالتحريم الله أعلم، فمن صفة الجميع، ومن أعمال الجميع محل نظر، لكن كونه يتجنبه الرجل حتى يمتاز النساء عن الرجال، وهو في الغالب يكون من زينة النساء تتزين به المرأة للرجل وتجعل له الخضاب في يديها أو في رجليها هو الغالب من زينة النساء؛ لأنه يشوق الرجل إليها، فالذي ينبغي والأحوط أن يكون في حق النساء فقط وأن يدعه الرجل، كما أنه موجود في نجد ويمكن بلدان أخرى يختص به المرأة، المرأة في نجد هي التي تتحنى تتزين لزوجها بالحناء والرجل لا يفعله، فإذا كان في بلد يفعله هؤلاء وهؤلاء فالأقرب والله أعلم أن الرجل يتجنبه حتى يبتعد عن الشبهة : دع ما يريبك إلى ما لا يريبك.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8773/حكم-استعمال-الحناء-للرجال-ولبس-الحرير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_325/32511.mp3","categories":["اللباس والزينة"]},{"id":10640,"question":"السائل يقول: سماحة الشيخ! يوجد لدي خالة أسقطت جنينًا يبلغ شهرين وتخشى أن تكون السبب في إسقاطه لأنها أكلت نوعًا من الأكل لا يناسبها وهي تعرف ذلك، فبعدها أحست بآلام وأسقطت هل عليها شيء في ذلك؟","title":"حكم من تسببت في إسقاط جنينها","answer":"","link":"https://binbaz.org.sa/fatwas/8817/حكم-من-تسببت-في-اسقاط-جنينها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_285/28502.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":10654,"question":"هذه السائلة تقول: بالنسبة سماحة الشيخ للبس النقاب حيث أنني سمعت بأن بعض الناس يقولون: بأنه غير جائز فما قول سماحتكم في ذلك مأجورين؟","title":"حكم لبس المرأة النقاب","answer":"الجواب: لبس النقاب لا بأس به للمرأة بحيث إذا كان النقب بقدر العين الواحدة أو بقدر العينين والباقي مستور، إلا إذا كانت محرمة بحج أو عمرة فلا تلبس حتى تحل، الرسول ﷺ نهى المحرمة أن تنتقب، أما إذا كانت حلالًا ما هي بمحرمة فلا بأس أن تنتقب لكن لا يظهر إلا العين فقط أو العينان، وإن سترت بالخمار أو نحوه كان أكمل وأبعد عن الفتنة.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ!","link":"https://binbaz.org.sa/fatwas/8831/حكم-لبس-المراة-النقاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_285/28516.mp3","categories":["اللباس والزينة"]},{"id":10698,"question":"السائلة من الرياض رمزت لاسمها بـ (أ. أ. أ) تقول: ما حكم إزالة الشعر من الجسم عامة بواسطة ما يسمى بالحلاوة المزيلة للشعر أفيدونا سماحة الشيخ؟","title":"حكم إزالة المرأة شعر جسدها","answer":"","link":"https://binbaz.org.sa/fatwas/8875/حكم-ازالة-المراة-شعر-جسدها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_285/28521.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":10720,"question":"من السودان المستمع بهاء الدين بعث برسالة ضمنها سؤالين: يقول في أحدها: هل يجوز استعمال الحناء للرجل في مجال التجمل؛ لأن بعض العلماء عندنا جوزوا هذا الاستعمال في حالتي الزواج والعلاج نرجو الإفادة، جزاكم الله خيراً؟","title":"حكم استعمال الحناء للرجال","answer":"الجواب: إذا كان ذلك من صفات النساء فليس لك أن تفعله، أما إذا كان النساء لا يفعلن ذلك عندكم، وإنما يفعله الرجال دون النساء، فلا حرج في ذلك، قد يفعله الإنسان للزينة أو لعلاج في رجليه أو في يديه، أما أن يفعله وهو مما يفعله النساء، فهذا تشبه بالنساء، والرسول ﷺ منع من التشبه بالنساء، فلا يجوز للرجل أن يتشبه بالمرأة، وليس للمرأة أن تتشبه بالرجل، فإذا كان عندكم في السودان أن هذا يختص بالرجال دون النساء، فليس فيه تشبه، أما إذا كان من خصائص النساء فلا يجوز لك أن تفعله، لا لك ولا لغيرك ليس للرجل أن يتشبه بالمرأة لا في اللباس ولا في الزينة، ولا في الحناء، ولا في الحلي، ولا في غير ذلك من أنواع الزينة التي تتعاطاها النساء، يقول النبي ﷺ: لعن الله الرجل يلبس لبسة المرأة، ولعن الله المرأة تلبس لبسة الرجل: ولعن المخنثين من الرجال والمخنث: المتشبه بالمرأة في كلامها، أو في مشيها أو في لباسها، فعليك وعلى غيرك من الرجال الحذر من التشبه بالنساء فيما يختص بالنساء في السودان وفي غير السودان، نعم.","link":"https://binbaz.org.sa/fatwas/8897/حكم-استعمال-الحناء-للرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_343/34312.mp3","categories":["اللباس والزينة"]},{"id":10744,"question":"تسأل وتقول: هناك مادة تلون الفتيات بها رءوسهن، هل هذا جائز أو لا؟","title":"حكم صبغ النساء الشعر للزينة","answer":"الجواب: إن كانت المادة سوداء تجعل الشيب أسود ما يجوز، لقول النبي ﷺ: غيروا هذا الشيب وجنبوه السواد، أما إذا كانت تجعله أحمر أو أصفر فلا حرج المحرم السواد، تغيير الشيب بالسواد. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8926/حكم-صبغ-النساء-الشعر-للزينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_346/34609.mp3","categories":["اللباس والزينة"]},{"id":10847,"question":"ننتقل إلى رسالة أخرى وصلت إلى البرنامج من الأحساء المنطقة الشرقية، وصاحبة الرسالة إحدى الأخوات من هناك تقول: ابنتكم (ر. غ) أختنا لها جمع من الأسئلة من بينها سؤال تقول فيه: هل يجوز إزالة الشعر الذي بين الحاجبين، أم يدخل في حكم النامصة والمتنمصة؟","title":"حكم إزالة شعر ما بين الحاجبين","answer":"الجواب:  فيه نظر، هذا محل نظر، والأقرب أنه لا يدخل في النمص؛ لأنه قد يشوه وجه المرأة، والمنظر إليها، فالأقرب -والله أعلم- أنه لا يدخل في النمص، النمص ... الحاجبين وما بينهما ليس منهما، وإن تركته احتياطًا وبعدًا عن الشبهة فلا بأس -إن شاء الله- لقول النبي ﷺ ....: دع ما يريبك إلى ما لا يريبك. المقدم: طيب جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9026/حكم-ازالة-شعر-ما-بين-الحاجبين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_356/35607.mp3","categories":["اللباس والزينة"]},{"id":10849,"question":"ننتقل إلى رسالة أخرى وصلت إلى البرنامج من الأحساء المنطقة الشرقية، وصاحبة الرسالة إحدى الأخوات من هناك تقول: ابنتكم (ر. غ) أختنا لها جمع من الأسئلة من بينها سؤال تقول فيه: هل يجوز إزالة الشعر الذي بين الحاجبين، أم يدخل في حكم النامصة والمتنمصة؟","title":"حكم إزالة شعر ما بين الحاجبين","answer":"الجواب:  فيه نظر، هذا محل نظر، والأقرب أنه لا يدخل في النمص؛ لأنه قد يشوه وجه المرأة، والمنظر إليها، فالأقرب -والله أعلم- أنه لا يدخل في النمص، النمص ... الحاجبين وما بينهما ليس منهما، وإن تركته احتياطًا وبعدًا عن الشبهة فلا بأس -إن شاء الله- لقول النبي ﷺ ....: دع ما يريبك إلى ما لا يريبك. المقدم: طيب جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9026/حكم-ازالة-شعر-ما-بين-الحاجبين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_356/35607.mp3","categories":["اللباس والزينة"]},{"id":10852,"question":"ما الحكم في صبغ الشعر بالحناء الأسود، هو كالحناء العادي إلا أنه يعطي بدل الصبغة الحمراء صبغة سوداء، وما الحكم في صبغ الشيب إذا ظهر في وقت مبكر من العمر باللون الأسود، أو بأي لون آخر؟","title":"حكم صبغ الشعر بالحناء الأسود أو غيره","answer":"الجواب:  إذا كان الصبغ من الحناء، أو غيره يجعل الشعر أسود بلا شك فهذا يمنع، أما إذا كان فيه حمرة بين الحمرة والسواد فلا حرج؛ لأن الرسول ﷺ منع من تغيير الشيب بالسواد، وقال: غيروا هذا الشيب، وجنبوه السواد في عدة أحاديث. فلا يجوز أن يغير الشيب بالسواد، ولو كان الشيب حدث من الرجل، أو المرأة في حال الشباب، يغير بغير السواد، بالصفرة والحمرة، وأما السواد فلا لعموم الحديث الذي ثبت عن رسول الله -عليه الصلاة والسلام- بل عدة أحاديث في ذلك عن النبي -عليه الصلاة والسلام- نعم.","link":"https://binbaz.org.sa/fatwas/9027/حكم-صبغ-الشعر-بالحناء-الاسود-او-غيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_356/35608.mp3","categories":["اللباس والزينة"]},{"id":10865,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من العراق، وباعثها مستمع من هناك يقول: أبو نهلة بغداد حي القاهرة، أبو نهلة له جمع من الأسئلة من بينها سؤال يقول: ما رأيكم في القفازين كتكملة للحجاب، هل تنصحون بهذا أو لا؟","title":"حكم ستر المرأة يديها بالقفازين تكملة للحجاب","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فالقفازان ستر لليدين، وذلك مناسب في حق المرأة إذا كان بقربها أجنبي، وإن سترت يديها بغير القفازين كالعباءة والجلال الذي تضعه عليها وما أشبه ذلك فلا بأس يكفي، ولكن القفازين فيهما ستر كامل، إلا أن تكون محرمة فليس لها لبسهما، المحرمة لا تلبس القفازين، سواء كانت محرمة بحج أو بعمرة؛ لأن الرسول نهى عن ذلك -عليه الصلاة والسلام- لا تنتقب، ولا تلبس القفازين في حال الإحرام، بل تغطي وجهها ويديها بغير النقاب، وبغير القفازين، أما في غير الإحرام فإن لها أن تنتقب، ولها أن تغطي وجهها بغير النقاب، ولها أن تلبس القفازين لأجل ستر كفيها عن الرجال الأجانب، ولها أن تسترهما بغير القفازين. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9033/حكم-ستر-المراة-يديها-بالقفازين-تكملة-للحجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_357/35701.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":10877,"question":"يقولان: من العادات الشائعة عندنا: مصافحة النساء الأجنبيات للرجال الأجانب، هل تجوز هذه المصافحة، أم أنها حرام؟","title":"حكم مصافحة المرأة لغير محارمها","answer":"الجواب:  مصافحة المرأة للرجل الأجنبي لا تجوز، حتى قال بعض أهل العلم: إنها أشد من النظر إليها؛ لأن لمسه لها قد يسبب من الشهوة أكثر مما يسببه النظر، ولهذا قال -عليه الصلاة والسلام-: إني لا أصافح النساء، لما مدت إليه امرأة وقت البيعة يدها قال: إني لا أصافح النساء، وقالت عائشة -رضي الله عنها-: والله! ما مست يد رسول الله يد امرأة قط، ما كان يبايعهن إلا بالكلام عليه الصلاة والسلام. فالمصافحة بين النساء والرجال الأجانب أمر منكر لا يجوز، لا مع الأقارب ولا مع غيرهم، إلا إذا كان محرمًا كأخيها وعمها لا بأس، أو مع النساء تصافح النساء لا بأس، أما تصافح رجلًا ليس بمحرم لها كابن عمها، أو ابن خالها، أو زوج أختها، أو أخي زوجها، أو ما أشبه ذلك هذا لا يجوز، وهو من أسباب الفتن. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9050/حكم-مصافحة-المراة-لغير-محارمها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_358/35804.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":10896,"question":"هذا السائل من الجزائر غزوني يقول في هذا  هل يجوز للزوجة قص مقدمة الرأس وذلك من باب قصد التزين للزوج؟ نرجو منكم الإفادة.","title":"حكم قص المرأة مقدم شعر رأسها للزينة","answer":"الجواب:  ترك ذلك أولى؛ لأنه يخشى أن يكون من جنس القزع، يشبه القزع، وهو حلق بعض الرأس، وترك بعضه، تركه أحوط، أما لو أخذت من جميع الرأس من أطراف الرأس كله؛ لأنه يشق عليها بكلفته، وأخذت من أطراف الشعر لا حرج -إن شاء الله- فقد ثبت أن أزواج النبي ﷺ بعد وفاته أخذن من رؤوسهن، قصرنها لأجل الكلفة.  فالحاصل أنه إذا كان من جميع الرأس لأجل الكلفة والمشقة فلا بأس، أما أخذ المقدمة فترك هذا أحوط وأولى؛ لقول النبي ﷺ: دع ما يريبك إلى ما لا يريبك. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/9073/حكم-قص-المراة-مقدم-شعر-راسها-للزينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_286/28610.mp3","categories":["اللباس والزينة"]},{"id":10903,"question":"نعود مع مطلع هذه الحلقة إلى رسالة المستمعة (أ. أ. الزاوي) من ليبيا طرابلس، أختنا عرضنا بعض أسئلة لها في حلقة مضت، وفي هذه الحلقة تسأل وتقول: ما رأي سماحتكم في عمل المرأة كمدرسة، أو طبيبة نساء في حالة وجود الرجال في مكان العمل، فمستشفيات الولادة مكتظة بالأطباء الرجال؟ وجهونا جزاكم الله خيرًا.","title":"حكم عمل المرأة طبيبة أو معلمة","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد. فلا حرج في أن تعمل المرأة طبيبة للنساء مع وجود رجال إذا كان ذلك لا يترتب عليه خلوة بأحد من الرجال، ولا كشف منها لشيء من بدنها، بل تكون متحجبة حافظة لنفسها؛ لأن ذلك قد تدعو له الضرورة، وليس به خطر، أما إن كان ذلك يترتب عليه خلوة، أو ظهور شيء من عورتها فلا يجوز، وعليها أن تسعى جاهدة في أن يكون عملها في محل النساء خاصة ليس فيه رجال؛ لأن ذلك أبعد عن الخطر، وأسلم لدينها وعرضها. أما إذا دعت الضرورة إلى الخلطة على وجه ليس فيه خلوة برجل معين، بل مع عدة، وعلى وجه ليس فيه ظهور لشيء من مفاتنها، كوجهها وصدرها ورأسها، ونحو ذلك، بل تكون مستترة متنقبة، لا يظهر منها إلا العين أو العينان، وتعمل في حقل النساء فقط، فأرجو أن يكون ذلك لا حرج فيه -إن شاء الله- للضرورة التي تدعو إلى ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9074/حكم-عمل-المراة-طبيبة-او-معلمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_360/36001.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":10934,"question":"ما هو رأيكم أيضًا لو تكرمتم في استعمال العروس للثوب الأبيض، الذي أصبح عادةً في أغلب البلدان، خاصةً وأن هذا الثوب غالي الثمن، وتستعمله العروس ليلة الزفاف فقط؟","title":"حكم لبس الثوب الأبيض للعروس ليلة الزفاف","answer":"الجواب:  لا أعلم له أصلًا، وينبغي للناس أن يدخلوا العروس في الثياب المعتادة، التي ليس فيها تكلف ولا إسراف، ولا تأسٍ بأعمال الكفرة، بل ينبغي للمؤمن والمؤمنة ولجميع المؤمنين أن يتحروا الشيء الذي ليس فيه تكلف، وليس فيه مشابهة لأعداء الله، ولا مشابهة للرجال، وهذا الثوب الأبيض إذا كان ليس فيه تشبه بالرجال ولا بالكفرة، ولكنه من لبس النساء على طريقة النساء، وتفصيل النساء، وخياطة النساء فلا حرج فيه، أما إذا كان فيه تكلف وغلا، أو تشبه بأعداء الله، أو تشبه بالرجال فلا يجوز، والله المستعان، نعم. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9109/حكم-لبس-الثوب-الابيض-للعروس-ليلة-الزفاف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_362/36206.mp3","categories":["اللباس والزينة"]},{"id":10967,"question":"تقول في فقرتها الثانية: هل يجوز للعروس أن تستعمل الحناء في يوم الزفاف، وهل هي بدعة، أم مباحة؟","title":"حكم استعمال الحناء للعروس ليلة زفافها","answer":"الجواب:  لا حرج أن تستعمل الحناء أو غيرها من أسباب الزينة، وتلبس الحلي، وتستعمل الحناء والكحل.. كل شيء يرغب في عين الزوج كل هذا لا بأس به. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9145/حكم-استعمال-الحناء-للعروس-ليلة-زفافها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_286/28611.mp3","categories":["اللباس والزينة"]},{"id":10968,"question":"أم رشيد أرسلت بمجموعة من الأسئلة تقول في السؤال الأول: جزاكم الله خيرًا يا فضيلة الشيخ! أسأل وأقول: في المدرسة التي ندرس فيها قالت لنا معلمة: بأننا نحاسب على الدموع، وإن كل دمعة سوف نسأل عنها، فهل هذا يحرم علينا البكاء! أحيانًا المرأة ضعيفة يبكيها الضرب، أو الآلام، أو جرح المشاعر، أو أي شيء، أو أحد ظلمها، فهل معنى ذلك بأن الدموع في هذه الحالة حرام! ولكن نحن نساء ضعيفات -مثلما يقولون- سلاح المرأة الدموع، بل الدموع متنفس ومخرج لبعض الهموم، فهل من المعقول ألا نبكي أبدًا إلا في جنب الله فقط، نرجو من سماحة الشيخ إجابة؟","title":"حكم القول بأن المرأة محاسبة على دموعها","answer":"الجواب:  لا حرج في ذلك، قول المعلمة هذا قول لا أصل له، ولا أساس له، لا حرج في البكاء عند الحاجة، والدمع عند الحاجة لا حرج في ذلك، إذا أصاب المرأة أو غيرها ما يؤذيها، ودمعت عيناها لا بأس، المحرم الصياح والنياحة، ضرب الوجه، شق الثوب، نتف الشعر، أما كونها تبكي.. تدمع عيناها لا يضر هذا عند الحاجة، عندما يحزنها شيء، عندما تضرب إلى غير ذلك لا حرج في هذا، والحمد لله. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/9146/حكم-القول-بان-المراة-محاسبة-على-دموعها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_286/28612.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":11008,"question":"يسأل عن صبغة الشعر، فيقول: هل صبغة الشعر للناس كافة تجوز، أو هي حلال، أم غير حلال، جزاكم الله خيرًا؟","title":"حكم تغيير الشيب للرجال والنساء","answer":"الجواب:  يسن للجميع تغيير الشيب الرجال والنساء، لقول النبي ﷺ: غيروا هذا الشيب، واجتنبوا السواد، وقوله ﷺ: إن اليهود والنصارى لا يصبغون فخالفوهم، ولما أحضر لديه والد الصديق أبو قحافة، وقد اشتعل رأسه ولحيته شيبًا أمر بتغييره، وقال: غيروا هذا الشيب، واجتنبوا السواد، وهذا يعم الرجال والنساء. فالسنة للجميع تغيير الشيب بالحمرة والصفرة، بالحناء ونحو ذلك لا بالسواد، أما السواد الخالص فلا يجوز أن يغير به الشيب لهذا الحديث الصحيح، ولكن يغير بغير السواد، بالحناء والكتم ..... الصبغة بين السواد والحمرة، أو الحمرة الخالصة، أو الصفرة هذا هو السنة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9186/حكم-تغيير-الشيب-للرجال-والنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_366/36602.mp3","categories":["اللباس والزينة"]},{"id":11011,"question":"يقول: عندنا هنا في أحد المساجد خطيب جمعة يلقي دروسًا قبل خطبة الجمعة، وفي إحدى الجمع تحدث وقال: إن إسبال السراويل والثياب جائز، ولا شيء فيه، وإنما التقصير، أو الرفع فوق الكعبين، أو إلى نصف الساقين، هذه بدعة، فبماذا تنصحون هذا الخطيب؟ مأجورين، جزاكم الله خيرًا.","title":"تحريم الإسبال على الرجال","answer":"الجواب:  هذا الخطيب -إن صح ما قلت عنه- قد أخطأ وغلط هداه الله، ورزقه العلم النافع وإيانا والمسلمين، والصواب: أن الإسبال لا يجوز، ما تحت الكعبين في حق الرجال، لا في السراويل، ولا في القمص، ولا في البشت، ولا في الإزار في حق الرجل، لقول النبي ﷺ في الحديث الصحيح الذي خرجه البخاري ما أسفل من الكعبين من الإزار فهو في النار، وقوله ﷺ: ثلاثة لا يكلمهم الله، ولا ينظر إليهم يوم القيامة، ولا يزكيهم، ولهم عذاب أليم، المسبل إزاره، والمنان فيما أعطى، والمنفق سلعته بالحلف الكاذب، رواه الإمام مسلم في صحيحه، وهذان الحديثان نص في تحريم الإسبال، وأنه من الكبائر. فالواجب على كل مسلم أن يحذر ذلك، وإذا كان الإسبال من أجل الكبر صار أكبر وأعظم في الإثم، لقول النبي ﷺ: من جر ثوبه خيلاء لم ينظر الله إليه يوم القيامة، فإذا جره بطرًا وخيلاء صار الإثم أكبر. وأما رفع الثوب فوق الكعب وإلى نصف الساق فهذا هو السنة كما جاءت به النصوص عن النبي -عليه الصلاة والسلام- في حق الرجل.  أما المرأة فالسنة لها الإسبال، حتى تغطي قدميها، إلا أن يكون عليها جوربان، أو مداس فلا بأس، وإلا فالسنة لها أن ترخي ثيابها حتى تستر قدميها، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9187/تحريم-الاسبال-على-الرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_366/36603.mp3","categories":["اللباس والزينة"]},{"id":11015,"question":"يسأل عن صبغة الشعر، فيقول: هل صبغة الشعر للناس كافة تجوز، أو هي حلال، أم غير حلال، جزاكم الله خيرًا؟","title":"حكم تغيير الشيب للرجال والنساء","answer":"الجواب:  يسن للجميع تغيير الشيب الرجال والنساء، لقول النبي ﷺ: غيروا هذا الشيب، واجتنبوا السواد، وقوله ﷺ: إن اليهود والنصارى لا يصبغون فخالفوهم، ولما أحضر لديه والد الصديق أبو قحافة، وقد اشتعل رأسه ولحيته شيبًا أمر بتغييره، وقال: غيروا هذا الشيب، واجتنبوا السواد، وهذا يعم الرجال والنساء. فالسنة للجميع تغيير الشيب بالحمرة والصفرة، بالحناء ونحو ذلك لا بالسواد، أما السواد الخالص فلا يجوز أن يغير به الشيب لهذا الحديث الصحيح، ولكن يغير بغير السواد، بالحناء والكتم ..... الصبغة بين السواد والحمرة، أو الحمرة الخالصة، أو الصفرة هذا هو السنة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9186/حكم-تغيير-الشيب-للرجال-والنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_366/36602.mp3","categories":["اللباس والزينة"]},{"id":11018,"question":"يقول: عندنا هنا في أحد المساجد خطيب جمعة يلقي دروسًا قبل خطبة الجمعة، وفي إحدى الجمع تحدث وقال: إن إسبال السراويل والثياب جائز، ولا شيء فيه، وإنما التقصير، أو الرفع فوق الكعبين، أو إلى نصف الساقين، هذه بدعة، فبماذا تنصحون هذا الخطيب؟ مأجورين، جزاكم الله خيرًا.","title":"تحريم الإسبال على الرجال","answer":"الجواب:  هذا الخطيب -إن صح ما قلت عنه- قد أخطأ وغلط هداه الله، ورزقه العلم النافع وإيانا والمسلمين، والصواب: أن الإسبال لا يجوز، ما تحت الكعبين في حق الرجال، لا في السراويل، ولا في القمص، ولا في البشت، ولا في الإزار في حق الرجل، لقول النبي ﷺ في الحديث الصحيح الذي خرجه البخاري ما أسفل من الكعبين من الإزار فهو في النار، وقوله ﷺ: ثلاثة لا يكلمهم الله، ولا ينظر إليهم يوم القيامة، ولا يزكيهم، ولهم عذاب أليم، المسبل إزاره، والمنان فيما أعطى، والمنفق سلعته بالحلف الكاذب، رواه الإمام مسلم في صحيحه، وهذان الحديثان نص في تحريم الإسبال، وأنه من الكبائر. فالواجب على كل مسلم أن يحذر ذلك، وإذا كان الإسبال من أجل الكبر صار أكبر وأعظم في الإثم، لقول النبي ﷺ: من جر ثوبه خيلاء لم ينظر الله إليه يوم القيامة، فإذا جره بطرًا وخيلاء صار الإثم أكبر. وأما رفع الثوب فوق الكعب وإلى نصف الساق فهذا هو السنة كما جاءت به النصوص عن النبي -عليه الصلاة والسلام- في حق الرجل.  أما المرأة فالسنة لها الإسبال، حتى تغطي قدميها، إلا أن يكون عليها جوربان، أو مداس فلا بأس، وإلا فالسنة لها أن ترخي ثيابها حتى تستر قدميها، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9187/تحريم-الاسبال-على-الرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_366/36603.mp3","categories":["اللباس والزينة"]},{"id":11039,"question":"يقول هذا السائل: ما حكم صبغ شعر اللحية بلون غير الأسود مثل البني الفاتح وغيره؟","title":"حكم صبغ اللحية بغير السواد","answer":"الجواب:  صبغها سنة إذا شاب الإنسان، يقول النبي ﷺ: غيروا هذا الشيب واجتنبوا السواد، فإذا صبغها بالأصفر، أو بالحمرة، أو بالحناء والكتم بين السواد، والحمرة لا بأس، المحرم الأسود الخالص، هذا ممنوع، نعم.","link":"https://binbaz.org.sa/fatwas/9217/حكم-صبغ-اللحية-بغير-السواد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_287/28721.mp3","categories":["اللباس والزينة"]},{"id":11078,"question":"تذكر السائلة يا سماحة الشيخ وتقول: بأنها أثناء القراءة للكتب تجد أنها بشكل تلقائي تضع يدها على حواجبها، وتنتف بعضًا من هذه الشعرات، تقول: وقد علمت بأن ذلك محرم، وتبت إلى ربي، لكنني أعود إلى ذلك دون شعور مني، ثم أنتبه لذلك فأعود للتوبة من جديد، فما حكم توبتي؟","title":"حكم من نتف شعر الحواجب دون قصد","answer":"الجواب:  عليك الجد في هذا الأمر، والحذر من التساهل، ومتى ما كان من غير قصد ولا اختيار فلا يضر -إن شاء الله- لأن أخذ الحواجب لا يجوز وهو النمص الذي لعن الرسول ﷺ من فعله. لكن إذا كان الشيء من غير عمد منك، بل عن ذهول فالله -جل وعلا سبحانه- هو العفو الغفور إذا لم تعمدي هذا الشيء، ولكن عليك المجاهدة للنفس، والحرص على عدم أخذ شيء من الحاجبين، والتوبة مقبولة إذا صدقت توبة نصوح يقبلها الله  كلما أذنب العبد: وهي الندم على الماضي، والإقلاع منه، والعزم أن لا يعود فيه، العزم الصادق، هذه التوبة، فإذا فعلت هذا من مثل هذا تاب الله عليك. نعم.","link":"https://binbaz.org.sa/fatwas/9256/حكم-من-نتف-شعر-الحواجب-دون-قصد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_289/28904.mp3","categories":["اللباس والزينة"]},{"id":11081,"question":"ما حكم السلام على العجائز اللاتي يكن كبيرات في السن، سواءً كان ذلك بالمشافهة، أو المصافحة، أو التقبيل؟ وجزاكم الله خيرًا.","title":"حكم المشافهة بالسلام والمصافحة والتقبيل للعجائز غير المحارم","answer":"الجواب:  السلام عليهن لا بأس به بالكلام فقط، أما المصافحة والتقبيل فلا يجوز، سواء كانت عجوزًا، أو غير عجوز، إلا المحرم يسلم عليها مع خدها، مع رأسها، كأمه وأخته وعمته، كان الصديق  يقبل عائشة بعض الأحيان مع خدها، فلا بأس. أما أجنبية ولو كانت عجوزًا لا. ليس له أن يصافحها، ولا أن يقبل رأسها، ولا أن يمس شيئًا من جسمها، لكن يسلم عليها بالكلام، السلام عليكم، وعليكم السلام، وإذا كانت مكشوفة وهي العجوز ليست ممن يتبرج بالزينة فهي من القواعد لها أن تكشف؛ لقوله -جل وعلا-: وَالْقَوَاعِدُ مِنَ النِّسَاءِ اللَّاتِي لا يَرْجُونَ نِكَاحًا فَلَيْسَ عَلَيْهِنَّ جُنَاحٌ أَنْ يَضَعْنَ ثِيَابَهُنَّ غَيْرَ مُتَبَرِّجَاتٍ بِزِينَةٍ وَأَنْ يَسْتَعْفِفْنَ خَيْرٌ لَهُنَّ [النور:60]، كونهن يتحفظن ويحتجبن أفضل، ولكن لا حرج عليهن في الكشف إذا كن غير متبرجات، ولا يرجون النكاح، لهذه الآية الكريمة لكن استعفافهن وتحجبهن أفضل. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9259/حكم-المشافهة-بالسلام-والمصافحة-والتقبيل-للعجاىز-غير-المحارم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_289/28907.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":11095,"question":"هل المسافة يا سماحة الشيخ بين جدة ومكة مسافة سفر، ولابد لها مع وجود محرم مع المرأة حيث تقول هذه السائلة: بأنني أذهب مع زوج أختي ووالدتي وأختي إلى مكة لأداء العمرة، فما حكم ذلك؟ جزاكم الله خيرًا.","title":"حكم سفر المرأة من جدة لمكة مع زوج أختها وأمها","answer":"الجواب:  ما بين جدة وما بين الطائف ومكة كله سفر، فلا تذهب إلا مع محرم، ولو مع أمها، وزوج أختها، بين مكة وجدة، ومكة والطائف سفر، جدة والطائف سفر. فالواجب الحذر من الإخلال بما أمر به النبي ﷺ والوقوع فيما نهى عنه، يقول ﷺ: لا تسافر امرأة إلا مع ذي محرم فالواجب الامتثال، والحذر مما نهى الله عنه. نعم.","link":"https://binbaz.org.sa/fatwas/9273/حكم-سفر-المراة-من-جدة-لمكة-مع-زوج-اختها-وامها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_290/29003.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":11096,"question":"تقول هذه السائلة يا سماحة الشيخ: ما حكم لبس الأساور السلاسل والخاتم المصنوعة من الحديد؟","title":"حكم لباس المرأة للأساور والسلاسل والخواتم الحديد","answer":"الجواب: لا حرج في ذلك، الصواب لا حرج في ذلك؛ لقوله ﷺ للخاطب: التمس ولو خاتمًا من حديد في الصحيحين: التمس ولو خاتمًا من حديد لكن كونه من الذهب، أو الفضة أفضل وأولى في حق المرأة، ولكن إذا دعت الحاجة إلى خاتم من حديد، أو سوارًا من حديد لا حرج. أما الحديث الذي فيه: أنه رأى رجلًا عليه خاتم من حديد، فقال: مالي أرى عليك حلية أهل النار؟! وكذلك في بعض الرواية: ريح الأصنام هو حديث شاذ مخالف للأحاديث الصحيحة. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/9274/حكم-لباس-المراة-للاساور-والسلاسل-والخواتم-الحديد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_290/29004.mp3","categories":["اللباس والزينة"]},{"id":11131,"question":"هل يجوز للمرأة مصافحة زوج أختها؟","title":"حكم مصافحة المرأة غير محارمها كزوج أختها","answer":"الجواب:  زوج أختها ليس محرمًا لها، فليس لها أن تصافحه، وليس لها أن تكشف له، وليس لها أن تخلو به؛ لأنه أجنبي، زوج أختها، وزوج عمتها، وزوج خالتها كلهم أجانب، ليس لها أن تخلو به ولا أن تسافر معه وحدها، ولا مع زوجته، وليس لها أن تصافحه، وليس لها أن تكشف له، بل عليها أن تحتجب وتسلم بسلام بدون المصافحة، السلام عليكم يا فلان، كيف حالك؟ كيف الأولاد؟ يكفي، أما المصافحة لا، يقول النبي ﷺ: إني لا أصافح النساء، وتقول عائشة رضي الله عنها: والله ما مست يد رسول الله يد امرأة قط، ما كان يبايعهن إلا بالكلام، والله يقول سبحانه: لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ لِمَنْ كَانَ يَرْجُو اللَّهَ وَالْيَوْمَ الآخِرَ وَذَكَرَ اللَّهَ كَثِيرًا [الأحزاب:21]. فالمسلمون يتأسون به -عليه الصلاة والسلام- في عدم المصافحة، فهو سيد الخلق، وأكرمهم على الله، وأبعدهم عن كل ريبة، ومع هذا ..... المصافحة، فغيره من باب أولى أن يحذر، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9317/حكم-مصافحة-المراة-غير-محارمها-كزوج-اختها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_369/36917.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":11139,"question":"يقول: هل تجوز القراءة والنفث على المرأة المصروعة أو الملدوغة بحية، أو عقرب مع وجود جمع من النساء ولا محرم هناك؟","title":"حكم القراءة والنفث على المرأة الأجنبية","answer":"الجواب:  نعم، لا بأس، إذا حصل عدم الخلوة، إذا حصل وجود شخص ثالث كأبيها، أو أخيها أو زوجها أو امرأة أخرى، المقصود لا يخلو، يكون معهم ثالث، أو أكثر فلا حرج. المقدم: وإن كان من النساء؟  الشيخ: وإن كان من النساء، ما هو شرط المحرم، المحرم في السفر بس.  المقدم: بارك الله فيكم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9309/حكم-القراءة-والنفث-على-المراة-الاجنبية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_369/36909.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":11165,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يسأل عدة أسئلة، السائل هو الأخ أحمد علي عبدالله من السودان الخرطوم، يقول: ما حكم مصافحة المرأة؟ وهل تجوز مصافحة المرأة بحائل كالثوب وغيره، جزاكم الله خيرًا؟","title":"حكم مصافحة المرأة من وراء حائل وبدون حائل","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد. فإن مصافحة المرأة الأجنبية لا تجوز؛ لقول النبي ﷺ في الحديث الصحيح: إني لا أصافح النساء وقالت عائشة - الله عنها-: والله ما مست يد رسول الله يد امرأة قط، ما كان يبايعهن إلا بالكلام، ولأن المصافحة وسيلة للفتنة، فلا تجوز ولو بحائل؛ لأن المصافحة بالحائل وسيلة إلى المصافحة بغير حائل، ويكفي السلام بالكلام، يكفي السلام بالكلام والسؤال عن الأحوال، يكفي عن المصافحة، والحمد لله، أما المحارم فلا بأس، لا بأس أن يصافح الرجل أمه وأخته وبنته وعمته، ونحو ذلك، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9334/حكم-مصافحة-المراة-من-وراء-حاىل-وبدون-حاىل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_371/37101.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":11176,"question":"تسأل عن صبغ الشعر بالنسبة للمرأة هل يجوز أو لا؟","title":"حكم صبغ المرأة لشعرها","answer":"الجواب:  يشرع لها تغيير الشيب، إذا شابت المرأة أو الرجل يشرع لهما التغيير، تغيير الشيب بالصفرة أو بالحمرة، لا بالسواد؛ لقول النبي ﷺ: غيروا هذا الشيب واجتنبوا السواد ولقوله ﷺ: إن اليهود والنصارى لا يصبغون فخالفوهم. فالرجل يصبغ والمرأة تصبغ، لكن بغير السواد، بالحمرة والصفرة، أو بالحناء والكتم، بين السواد والحمرة لا يكون سوادًا خالصًا، أما الأصباغ الأخرى التي يصبغ بها الناس، بعض النساء الشعر، للجمال والزينة تركها أحوط، من باب الاحتياط. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9359/حكم-صبغ-المراة-لشعرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_372/37204.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":11183,"question":"تسأل عن صبغ الشعر بالنسبة للمرأة هل يجوز أو لا؟","title":"حكم صبغ المرأة لشعرها","answer":"الجواب:  يشرع لها تغيير الشيب، إذا شابت المرأة أو الرجل يشرع لهما التغيير، تغيير الشيب بالصفرة أو بالحمرة، لا بالسواد؛ لقول النبي ﷺ: غيروا هذا الشيب واجتنبوا السواد ولقوله ﷺ: إن اليهود والنصارى لا يصبغون فخالفوهم. فالرجل يصبغ والمرأة تصبغ، لكن بغير السواد، بالحمرة والصفرة، أو بالحناء والكتم، بين السواد والحمرة لا يكون سوادًا خالصًا، أما الأصباغ الأخرى التي يصبغ بها الناس، بعض النساء الشعر، للجمال والزينة تركها أحوط، من باب الاحتياط. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9359/حكم-صبغ-المراة-لشعرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_372/37204.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":11201,"question":"نبدأ هذه الحلقة بسؤال من السائلة (ع. م. خ) سورية، تقول: السلام عليكم ورحمة الله وبركاته، وأسأل عن امرأة تحب عمل الخير ومؤمنة وصائمة ومصلية وحاجة إلى بيت الله الحرام، وقلبها لله  وتحسن إلى الناس، ولكنها تستقبل الضيوف الرجال أثناء غياب الزوج وتقوم بواجبهم على أكمل وجه، ولكن بقلب سليم ونية صافية، فهل هذا حرام وهل يؤثر هذا على عملها وعلى صلاتها وصيامها أفيدوني مأجورين؟","title":"حكم استقبال المرأة لضيوف رجال أثناء غياب زوجها","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فهذا العمل الذي ذكرته السائلة فيه تفصيل: فإن كانت المستقبلة للضيوف مستورة ومتحجبة وبعيدة عن أسباب الفتنة، ولا تخلو بأحد من الرجال فلا حرج عليها، أما إذا كان يتضمن ذلك خلوة بأحد من الرجال أو إبداء شيء من الزينة وأسباب الفتنة هذا لا يجوز؛ لأن الأحكام تدور مع العلل، والمرأة مأمورة بالحجاب والتستر والبعد عن أسباب الفتنة، ومنهية عن الخلوة بالرجل الأجنبي، فإذا كان استقبالها للضيوف على وجه لا يقدح في دينها ولا يضر دينها فلا، لا خلوة ولا تكشف فلا بأس بذلك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9382/حكم-استقبال-المراة-لضيوف-رجال-اثناء-غياب-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_291/29101.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":11212,"question":"السائلة أم خلود يوجد لديها بعض الأسئلة تقول: هل لبس الملابس الضيقة بعض الشيء، مثلًا: يكون الصدر مفتوحًا ويكون الكم قصيرًا وتلبس بين النساء، هل عليها إثم بهذا اللبس وينطبق عليها قول الرسول ﷺ: كاسيات عاريات مائلات مميلات، وماذا نعمل بالملابس الموجودة لدينا؟ جزاكم الله خيرًا.","title":"حكم كشف المرأة شعرها ويديها وصدرها بين النساء","answer":"الجواب:  الكاسيات عاريات فسر بأنهن يلبسن ثيابًا رقيقة أو قصيرة، ثيابًا رقيقة لا تستر أو قصيرة لا تستر، أما الضيقة فلها شأن آخر؛ لأن الضيقة تبين حجم الأعضاء ولكنها تستر. فالواجب أن تكون الملابس وسطًا لا واسعة تبين الأعضاء ولا ضيقة تبين حجم الأعضاء ولكن وسط هذا هو الواجب وهذا هو السنة، أن تكون الملابس للرجل والمرأة وسطًا بين الضيق والواسع، لكن يجب أن تكون ساترة لعورتها، ساترة يعني: من جهة الصفاقة المتانة، ومن جهة أنها وافية ليست قصيرة تسترها عن الرجال الأجانب.  أما وجودها بين النساء إذا بان منها ساق أو رأس ما يضر بين النساء، لكن يجب أن تتحرى الثياب الساترة البعيدة عن أسباب الفتنة حتى لا يراها خادم أو سائق أو غير ذلك من الأجانب. وبين النساء أسهل، إذا كان ما بين السرة والركبة مستورًا، وإذا كان رأت المرأة من أختها الصدر أو العنق أو الرأس أو الساق لا يضر؛ لأن العورة مع المرأة عورتها ما بين السرة والركبة، وهكذا بين المحارم لكن سترها عند المحارم صدرها ورأسها يكون أكمل وأحوط. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/9393/حكم-كشف-المراة-شعرها-ويديها-وصدرها-بين-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_291/29112.mp3","categories":["اللباس والزينة"]},{"id":11232,"question":"تقول في سؤالها الثاني: هل يجوز للمرأة أن تذهب إلى الخياط الرجالي بقصد خياطة الفساتين وهي مرتدية الحجاب الشرعي الكامل، فهل هي آثمة في ذلك، علمًا بأن الخياط الرجالي أقل تكلفة من الخياط النسائي أفيدوني مأجورين؟","title":"حكم ذهاب المرأة لخياط الرجال","answer":"الجواب: لا حرج إذا سلمته الخياطة مع التستر لا حرج، لا يلمسها ولا ينظر إليها، تعطيه شيئًا مفصل مضبوط لا حرج في ذلك، لكن كونه يلمسها ويقيس عليها اللباس أو تكشف له عن شيء من بدنها هذا لا يجوز. نعم.","link":"https://binbaz.org.sa/fatwas/9397/حكم-ذهاب-المراة-لخياط-الرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_291/29113.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":11251,"question":"تسأل أختنا وتقول: ما حكم تغيير الملابس في قصور الأفراح، هل هو حرام أم جائز؟","title":"حكم تغيير النساء الملابس في قصور الأفراح","answer":"الجواب:  إذا كان المحل مستورًا لا يطلع عليها أجنبي لا بأس، وأما ما جاء من الوعيد فهو محمول على التساهل لفعل الفاحشة، وأما إذا كان تغير في محل مصون أو في بيت أخيها، أو عمها أو أبيها أو نحو ذلك فلا بأس، بشرط أنها في محل مصون، نعم. المقدم: بارك الله فيكم، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9430/حكم-تغيير-النساء-الملابس-في-قصور-الافراح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_374/37403.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":11253,"question":"تقول عن نفسها زوجي مسرف وليس عندنا سكن، فهل يجوز أن أخفي عنه بعض النقود الزائدة عن حاجتنا لإعداد السكن لنا ولأولادنا، وخاصة أن لي مالًا خاصًا أضعه في مصروف المنزل منعًا للمشاكل؟ جزاكم الله خيرًا.","title":"حكم أخذ المرأة من مال زوجها خفية إذا كان مسرفاً","answer":"الجواب:  هذا كلام طيب، ومأجورة ومشكورة، إذا حفظت بعض المال الزائد وأخبرته بذلك حتى يشترى به منزلًا، هذا طيب، لا تقتر على الأهل النفقة، فإذا أنفقت عليهم الشيء اللازم والشيء المناسب، فالإسراف لا خير فيه ولا يجوز فتحفظ الزائد، وتجعل معها ما يتيسر من عندها ولا بأس أن تعلمه بعد ذلك حتى يشترى منزلًا ينفعهم جميعًا. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9441/حكم-اخذ-المراة-من-مال-زوجها-خفية-اذا-كان-مسرفا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_374/37414.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":11263,"question":"تسأل أختنا وتقول: ما حكم تغيير الملابس في قصور الأفراح، هل هو حرام أم جائز؟","title":"حكم تغيير النساء الملابس في قصور الأفراح","answer":"الجواب:  إذا كان المحل مستورًا لا يطلع عليها أجنبي لا بأس، وأما ما جاء من الوعيد فهو محمول على التساهل لفعل الفاحشة، وأما إذا كان تغير في محل مصون أو في بيت أخيها، أو عمها أو أبيها أو نحو ذلك فلا بأس، بشرط أنها في محل مصون، نعم. المقدم: بارك الله فيكم، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9430/حكم-تغيير-النساء-الملابس-في-قصور-الافراح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_374/37403.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":11265,"question":"تقول عن نفسها زوجي مسرف وليس عندنا سكن، فهل يجوز أن أخفي عنه بعض النقود الزائدة عن حاجتنا لإعداد السكن لنا ولأولادنا، وخاصة أن لي مالًا خاصًا أضعه في مصروف المنزل منعًا للمشاكل؟ جزاكم الله خيرًا.","title":"حكم أخذ المرأة من مال زوجها خفية إذا كان مسرفاً","answer":"الجواب:  هذا كلام طيب، ومأجورة ومشكورة، إذا حفظت بعض المال الزائد وأخبرته بذلك حتى يشترى به منزلًا، هذا طيب، لا تقتر على الأهل النفقة، فإذا أنفقت عليهم الشيء اللازم والشيء المناسب، فالإسراف لا خير فيه ولا يجوز فتحفظ الزائد، وتجعل معها ما يتيسر من عندها ولا بأس أن تعلمه بعد ذلك حتى يشترى منزلًا ينفعهم جميعًا. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9441/حكم-اخذ-المراة-من-مال-زوجها-خفية-اذا-كان-مسرفا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_374/37414.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":11266,"question":"مستمع يقول: عمر علي عبدالجبار بعث يسأل ويقول: أرجو إفادتي عن لبس حذاء مصنوع من جلد النمر، هل هو حلال أم حرام وما هي الأدلة؟ جزاكم الله خيرًا.","title":"حكم لبس الحذاء المصنوع من جلود السباع","answer":"الجواب:  تركه أحوط وأولى لأن الرسول ﷺ: نهى عن افتراش جلود النمار وفي لفظ آخر: جلود السباع واتخاذ النعال منها مثل افتراشها، اتخاذ النعال مثل الافتراش، فالأحوط لك ترك ذلك، وعدم استعمال النعل من جلود الأسود أو غيرها من السباع هذا هو الذي ينبغي للمؤمن ألا يتخذ من جلودها فرشًا ولا غيرها. نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9436/حكم-لبس-الحذاء-المصنوع-من-جلود-السباع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_374/37409.mp3","categories":["اللباس والزينة"]},{"id":11298,"question":"هل يجوز تلبيس بعض الأسنان بالذهب أو الفضة بقصد الزينة؟","title":"حكم طلاء الأسنان بذهب أو فضة للزينة","answer":"الجواب:  لا يجوز للرجل، أما المرأة فأمرها أسهل، أما الرجل لا يجوز يربطها بغير الذهب والفضة إلا إذا كان دعت الحاجة إلى ربطها ما هو زينة، ربط الأسنان بسلك الذهب فلا بأس، وإن تيسر غيره فهو أحوط، أما اتخاذ رباط للزينة أو الصبغة حق الذهب للزينة هذا ما يجوز. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9480/حكم-طلاء-الاسنان-بذهب-او-فضة-للزينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_376/37612.mp3","categories":["اللباس والزينة"]},{"id":11303,"question":"هل يجوز تلبيس بعض الأسنان بالذهب أو الفضة بقصد الزينة؟","title":"حكم طلاء الأسنان بذهب أو فضة للزينة","answer":"الجواب:  لا يجوز للرجل، أما المرأة فأمرها أسهل، أما الرجل لا يجوز يربطها بغير الذهب والفضة إلا إذا كان دعت الحاجة إلى ربطها ما هو زينة، ربط الأسنان بسلك الذهب فلا بأس، وإن تيسر غيره فهو أحوط، أما اتخاذ رباط للزينة أو الصبغة حق الذهب للزينة هذا ما يجوز. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9480/حكم-طلاء-الاسنان-بذهب-او-فضة-للزينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_376/37612.mp3","categories":["اللباس والزينة"]},{"id":11330,"question":"من الجزائر وصلتنا رسالة الأخ الكريم لم يذكر الاسم هنا، يقول في هذا السؤال الأول: أفيدونا -جزاكم الله خيرًا- عن حكم لبس المرأة بالنسبة للذهب المحلق الذي على شكل حلق هل هو جائز فقد سمعنا بفتوى بتحريمه فما هو الصحيح في ذلك؟ جزيتم خيرًا.","title":"حكم لبس النساء الذهب المحلق","answer":"الجواب:  الصواب حل الذهب المحلق، وأنه لا بأس به، وقد أحل النبي ﷺ الذهب والحرير لإناث الأمة، قال: أحل الذهب والحرير لإناث أمتي، وحرم على ذكورهم وكان الصحابيات يلبسون المحلق فلا حرج في ذلك، وقد أجمع المسلمون على هذا، كان فيه خلاف شاذ لأحاديث وردت فيها ضعف وبعضها منسوخ، واستقرت الشريعة على إباحة الذهب والحرير للنساء المحلق وغير المحلق. وقول بعض إخواننا من علماء العصر بتحريم المحلق قول ضعيف مرجوح خلاف ما عليه أهل السنة والجماعة ، وهو كالإجماع من أهل العلم أنه لا حرج على المرأة أن تلبس المحلق كالخاتم والأسورة والخلخال وما أشبه ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/9512/حكم-لبس-النساء-الذهب-المحلق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_292/29209.mp3","categories":["اللباس والزينة"]},{"id":11338,"question":"على بركة الله نبدأ هذا اللقاء بسؤال لأحد الإخوة المستمعين رمز لاسمه بـ (أ. أ. أ) يقول: ما حكم الشرع في نظركم -سماحة الشيخ- في ذهاب المرأة إلى السوق؟ نرجو التوضيح بهذا مأجورين.","title":"الضوابط الشرعية لخروج المرأة إلى السوق","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فخروج المرأة إلى السوق لقضاء حاجاتها أمر لا بأس به ولا حرج فيه إذا خرجت متسترة متحفظة والسوق ليس فيه خطر ولا من يتعرض بالسوق للنساء فلا بأس، أما إن كان هناك حاجة لمن يصحبها فإنها تخرج مع أخيها أو مع أبيها أو مع زميلتها إذا كان ذلك أسلم وأبعد عن أن تؤذى بشيء. أما إذا كان المحل آمنًا وليس هناك ما يوجب استصحابها أحد فلا حرج في ذلك، وإذا دعت الحاجة إلى استصحاب من يرافقها فإنها تنظر من يرافقها ممن تزول معه المشقة أو الأذى الذي يخشى منه. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/9520/الضوابط-الشرعية-لخروج-المراة-الى-السوق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_293/29301.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":11339,"question":"من السودان أم أحمد تقول: أسأل وأقول: ما هو حكم كشف الوجه أهو حلال أم حرام، وهل الحجاب هو الجلباب الواسع فقط، وهل له لون معين، فنحن في بلدنا نلبس ما يسمى بالثوب الفضفاض فوق الفستان، وله ألوان متعددة، هل يمكن أن يحل محل الحجاب أم لا يجوز؟ أرجو منكم التوجيه.","title":"حكم تغطية المرأة وجهها واشتراط لونًا معينًا للحجاب","answer":"الجواب:  حجاب الوجه أمر لازم؛ لأن الوجه هو محل زينة المرأة، أو ضدها، هو محل الفتنة، فالواجب ستره، وكان النساء في صدر الإسلام يكشفن وجوههن ثم نسخ ذلك لما نزل قوله تعالى: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]، فأمر سبحانه أن يكون السؤال والكلام مع النساء من وراء حجاب، بأن تكون متسترة من وراء جدار، من وراء باب، من وراء جلباب قد وضعته على وجهها حتى لا تفتن ولا تفتن. والجلباب لا حرج أن يكون أسود أو أحمر أو أخضر أو أبيض، المقصود ستر الوجه بأي شيء من أنواع المتاع، ولا يشترط أن يكون أسود أو أخضر أو أحمر أو أبيض أو غير ذلك، وبين سبحانه أنه أطهر لقلوب الجميع، أن هذا الجلباب وهذا التستر أطهر لقلوب الجميع وأبعد عن الفتنة. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/9521/حكم-تغطية-المراة-وجهها-واشتراط-لونا-معينا-للحجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_293/29302.mp3","categories":["اللباس والزينة"]},{"id":11360,"question":"هل صبغ الشعر باللون الأسود غير جائز، وهل هناك فرق بين من هم شباب، وبين الشيوخ؟ جزاكم الله خيرًا.","title":"حكم صبغ الشعر باللون الأسود","answer":"الجواب:  صبغه باللون الأسود لا يجوز، لا للشيخ لا للمرأة ولا للرجل؛ لقوله ﷺ: غيروا هذا الشيب وجنبوه السواد. أما صبغ الشيب بالحمرة والصفرة أو بالسواد المخلوط فلا بأس في ذلك للرجل والمرأة جميعًا، أما تغيير الشيب بالسواد الخالص فلا يجوز للجميع لا للرجل ولا للمرأة. وأما تغيير الشعر بألوان أخرى أو سليم ما فيه شيء فتركه أحوط وأولى، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9530/حكم-صبغ-الشعر-باللون-الاسود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_378/37807.mp3","categories":["اللباس والزينة"]},{"id":11385,"question":"بعد هذا رسالة وصلت إلى البرنامج من المستمع (ع. ع. م) يسأل ويقول: هل النقاب للمرأة فرض أم سنة؟ وهل النقاب خاص بأمهات المؤمنين فقط أم للنساء جميعًا، وهل يجوز إظهار الوجه والكفين للمرأة؟ جزاكم الله خيرًا.","title":"حكم نقاب المرأة","answer":"الجواب:  النقاب عام لأمهات المؤمنين وغيرهن، كان الأمر في الأول عدم وجوب الحجاب، ثم نسخ ذلك وأنزل الله قوله تعالى: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]، وأنزل سبحانه: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ [النور:31] الآية، فوجب الحجاب على الجميع سواء بالنقاب أو بغيره، سواء النقاب وهو على الوجه ويكون فيه نقب للعين أو نقبان للعينين فقط .... العينين أو بإرخاء الخمار على الوجه كله، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9564/حكم-نقاب-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_379/37913.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":11416,"question":"بعد هذا رسالة بعث بها مستمع يقول: (ر. أ. ح) من البحرين، يسأل ويقول: ماء الذهب الذي تصبغ به بعض الألبسة مثل الساعات للرجال، هل يجوز، أو لا؟ جزاكم الله خيرًا.","title":"حكم لبس الرجل للساعة أو الخاتم المطلي بالذهب","answer":"الجواب:  الرجل ممنوع من الذهب والحرير، فليس له أن يلبس الحرير ولا الذهب، وإذا كانت الساعة مموهة بالذهب أو الخاتم مموه بالذهب لا يجوز له لبسه، هذا للنساء، والنبي ﷺ قال في الذهب والحرير: إنهما حل لإناث أمتي، حرام على ذكورهم ولما رأى في يد رجل خاتمًا من ذهب طرحه، وقال: يعمد أحدكم إلى جمرة من نار فيضعها في يده وقال ﷺ: أحل الذهب والحرير لإناث أمتي، وحرم على ذكورهم فتمويه الخاتم، أو تمويه الساعة بالذهب يعتبر ساعة ذهب، خاتم ذهب؛ لأن العبرة بالظاهر، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9597/حكم-لبس-الرجل-للساعة-او-الخاتم-المطلي-بالذهب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_380/38016.mp3","categories":["اللباس والزينة"]},{"id":11422,"question":"نعود إلى رسالة الأخت (ع. س) من مصر تقول: هل يجوز لي أن أتحدث مع ابن عمي، أو خالي في شؤون الحياة، وأمور الدين، مع وجود أبي وأمي؟","title":"حكم تحدث المرأة مع ابن عمها في أمور الدين وضوابطه","answer":"الجواب:  نعم لا حرج، أما خالك فهو محرم، وابن عمك وابن خالك لا بأس ليس بمحرم، لكن التحدث معهم في أمور تنفع مع الحجاب عن ابن عمك، وابن خالك، وعدم الخلوة، لا بأس، تقولين له: أنا في حاجة إلى كذا، وايش يسوى الشغل الفلاني؟ هل يوجد في السوق؟ كيف حالك؟ كيف أهلك؟ كيف أولادك؟ لا بأس، ومع الخال، ومع العم من باب أولى؛ لأنهما محرم. فالمقصود التحدث مع المحرم، وغير المحرم بما تحتاجه المرأة في شؤونها، أو فيما تريد أن تشتريه، أو ما أشبه ذلك، أو تسألهم عن أهليهم، أو عن صحتهم، كل ذلك لا بأس به، لكن مع الحجاب إذا كان المتحدث إليه غير محرم، مع الحجاب وعدم الخلوة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9604/حكم-تحدث-المراة-مع-ابن-عمها-في-امور-الدين-وضوابطه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_294/29403.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":11423,"question":"إحدى الأخوات المستمعات أيضًا تسأل وتقول: هل يجوز للأم أن تلبس بناتها ثوبًا قصيرًا، أي: يكون فوق الركبة، وتلبسهم تحته السراويل، هل يجوز ذلك، وأعمارهم ما بين السنة، إلى العشر سنوات؟","title":"حكم لبس القصير للبنات الصغيرات","answer":"الجواب:  لا حرج في ذلك إذا كانت السراويل تسترهن، لكن ترك هذا أفضل؛ حتى لا يعتدن هذا القصير الذي يفتن، ينبغي أن تعلمهن الستر، ولو أنهن صغيرات؛ حتى يعتدنه، تلبسهن اللباس الضافي الذي يستر أقدامهن يعتدنه؛ حتى يعتدنه، ولاسيما إذا كانت بنت تسع وما حولها؛ فإنها امرأة. أما الصغيرة بنت سنتين هذه أمرها أسهل، ولكن، لا سيما إذا كان عليها سراويل، وبكل حال فكونها تستعمل الشيء الضافي مع جميع البنات هو السنة، هو الأولى؛ حتى يعتدن ذلك الخير، نعم. المقدم: بارك الله فيكم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9605/حكم-لبس-القصير-للبنات-الصغيرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_380/38021.mp3","categories":["اللباس والزينة"]},{"id":11424,"question":"هل يجوز للمرأة أن تقص شعرها فوق الكتف؟","title":"حكم قص المرأة شعرها فوق الكتف","answer":"الجواب:  تركه أفضل؛ لأنه جمال لها، لكن إذا دعت الحاجة إلى أخذه، إلى الأخذ من طوله؛ فلا حرج في ذلك، فقد ثبت أن أزواج النبي ﷺ لما توفي؛ أخذن من طول أشعارهن، نعم. المقدم: نعم، إذًا: هذا جائز. الشيخ: عند الحاجة، إذا رأت المصلحة في ذلك، وزوجها سمح لها إن كان لها زوج، نعم.","link":"https://binbaz.org.sa/fatwas/9606/حكم-قص-المراة-شعرها-فوق-الكتف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_380/38022.mp3","categories":["اللباس والزينة"]},{"id":11428,"question":"هل يجوز للمرأة أن تلبس القناع وهو عبارة عن قطعة قماش بطول مترين ذات لون أسود، وتظهر عينًا واحدة بدلًا من النقاب؟","title":"حكم لبس المرأة للقناع","answer":"الجواب:  لا حرج، عين واحدة، أو العينين، أو لباس النقاب الساتر للعين، أو للعينين، كل هذا لا حرج فيه، وإذا كانت تلبس الخمار الساتر، وتنظر من ورائه؛ كان أكمل وأكمل، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9610/حكم-لبس-المراة-للقناع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_294/29404.mp3","categories":["اللباس والزينة"]},{"id":11485,"question":"تسأل أختنا ما حكم لبس حزام الذهب للمرأة؛ لأن كثيرًا من الناس يقولون: إنه حرام؟","title":"حكم لبس المرأة حزاماً من الذهب","answer":"الجواب:  لا بأس، لا أعلم فيه شيئًا، أقول: لا أعلم فيه بأسًا، مثلما قال ﷺ: إن الذهب والحرير حل لإناث أمتي، حرام على ذكورهم، فما كان من عادة النساء لبسه من الذهب والحرير؛ فلا بأس به، نعم. والحمد لله، هذا هو الأصل حله، سواءً حزام، وإلا قلادة، وإلا سوار، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9667/حكم-لبس-المراة-حزاما-من-الذهب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_382/38213.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":11508,"question":"تسأل أيضًا عن حكم المرأة المسلمة التي تصوم، وتصلي، ولكنها لا تلبس النقاب، بل ترتدي لبس الطويل الذي يصل إلى الكعبين، وتلبس الطرحة التي تداري بها نصف الوجه، هل يعتبر هذا حجابًا كافيًا؟ جزاكم الله خيرًا.","title":"هل تغطية نصف الوجه يعتبر حجابًا كافيًا؟","answer":"الجواب:  عليها التوبة إلى الله، وأن تحتجب حجابًا كاملًا، تستر الوجه كله عن الأجنبي، وهذا هو الواجب لقوله تعالى: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ [الأحزاب:53]، يقول الله سبحانه في سورة الأحزاب: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]، ويقول سبحانه في سورة النور: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ [النور:31] الآية، والوجه هو أعظم الزينة، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/9688/هل-تغطية-نصف-الوجه-يعتبر-حجابا-كافيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_384/38404.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":11509,"question":"سماحة الشيخ: من النساء من تعمل في مزرعة، وتعمل برعي الغنم، أو رعي الإبل، أو البقر، وما أشبه ذلك، كيف تنصحونها بكيفية الحجاب؟","title":"نصيحة لمن تشتغل بالرعي ونحوه بلزوم الحجاب","answer":"الجواب:  تعمل ولا بأس إذا كان ما فيه اختلاط، ولا خطر، تعمل ويكون لها النقاب، تحط النقاب يظهر فيه العين، أو العينان، والباقي مستور، ولا حرج في ذلك. المقدم: بارك الله فيكم، بالنسبة لحجاب بقية الجسم، كيف يكون ذلكم اللباس؟ الشيخ: بالملابس العادية، تستر الرأس، وتستر البدن كله، نعم. المقدم: ملابس هذا الزمان لها أوصاف، ولها طرق في التفصيل. الشيخ: على كل حال تكون الملابس ما فيها فتنة، إذا رآها الرجال، تكون ملابس ليست فيها أسباب الفتنة، وتكون ساترة لجميع بدنها حتى قدميها، نعم. المقدم: بارك الله فيكم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9689/نصيحة-لمن-تشتغل-بالرعي-ونحوه-بلزوم-الحجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_384/38405.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":11510,"question":"تسأل أختنا هل يجوز للمرأة المسلمة أن تجلس، وتتحدث مع زوج أختها بوجود الأهل، أم لا يجوز ذلك؟","title":"حكم كلام المرأة مع الأجنبي","answer":"الجواب:  لا حرج أن تتحدث المرأة مع الرجال، مع التستر والحجاب، وعدم الفتنة، لا بأس، مع زوج أختها، أو أخي زوجها، أو غيره من دون خلوة، بوجود الزوج، أو الأم، أو غيرهما من دون فتنة، ولا خلوة، يعني: على طريقة ليس فيها فتنة، حديث عادي، ليس فيه فتنة، ولا تساهل، ولا كلمات خبيثة تجر إلى الفساد، بل الحديث العادي الذي ليس فيه فتنة، وليس فيه شر، لا حرج في ذلك من دون خلوة، مع زوج أختها مع أخي زوجها بحضرة زوجها، بحضرة أمه، بحضرة أخيها، بحضرة غيرهم من دون خلوة، لكن حديث ليس فيه، يعني: سفاسف، ليس فيه شر، ودعوة إلى شر، حديث عادي سليم، نعم. المقدم: بارك الله فيكم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9690/حكم-كلام-المراة-مع-الاجنبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_384/38406.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":11511,"question":"تسأل سماحتكم عن حكم وضع المكياج للزوج؟","title":"حكم استعمال المرأة لمساحيق التجميل","answer":"الجواب:  لا حرج في المكياج إذا كان لا يضر الوجه، إذا كان لا يسبب مرضًا للوجه، يعني: إنما هو جمال، ونور؛ فلا بأس، كالصابون ونحوه، نعم. المقدم: الله المستعان.","link":"https://binbaz.org.sa/fatwas/9691/حكم-استعمال-المراة-لمساحيق-التجميل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_384/38407.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":11518,"question":"تسأل أختنا عن حكم خروج الفتاة من بيتها لغير حاجة ضرورية؟","title":"حكم خروج المرأة من بيتها لغير ضرورة","answer":"الجواب:  السنة عدم الخروج، الله يقول: وَقَرْنَ فِي بُيُوتِكُنَّ [الأحزاب:33]، السنة البقاء في البيوت، والمحافظة على العفة، والبعد عن التبرج، والخروج إلا من حاجة، فالبقاء في البيت أسلم إلا من حاجة كالخروج للصلاة مع الناس مع التستر، وعدم الطيب، كالخروج لعيادة المريض، خروج لحاجات السوق مع التستر، الحاجة التي تدعو الحاجة إليها، وما أشبه ذلك. أما خروج من غير حاجة قد يفضي إلى فتنة، تركه هو الأولى، المقصود: الخروج لحاجة، ومصلحة شرعية، هذا هو المطلوب، أما خروج لغير حاجة؛ فقد يفضي إلى شر؛ فتركه أولى وأفضل، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9700/حكم-خروج-المراة-من-بيتها-لغير-ضرورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_384/38416.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":11552,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الجمهورية العربية السورية، باعثتها إحدى الأخوات المستمعات من هناك تقول: حملت وأثناء فترة الحمل تناولت دواءً لم أعلم أنه مضر، ولا يجوز تناوله للحامل، وقد ظهر، وتبين أنه قد سبب تشوهًا للجنين، وعندما راجعنا الطبيب قال لنا ولزوجي: إنه من الأفضل إسقاط الجنين؛ لأنه لا يضمن في حين استمرار الحمل، وبناءً على كلام الدكتور أسقطت الجنين، وكان عمره شهرًا و عشرًا، فما هو الحكم الشرعي الإسلامي في هذه الحالة؟ أفيدونا جزاكم الله خيرًا.","title":"حكم إسقاط الجنين في الأربعين الأولى من الحمل بقرار طبي","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد. فإسقاط الجنين فيه تفصيل: فإذا كان في الأربعين الأولى فالأمر فيه أوسع، ولا ينبغي إسقاطه، لكن إذا اقتضت المصلحة الشرعية بإسقاطه؛ لمضرة على الأم، أو لهذا السبب الذي قرر الأطباء أنه قد يتشوه بأسباب فعلتها الأم؛ فلا حرج في ذلك، أما إذا كان في الطور الثاني، أوفي الطور الثالث؛ فلا يجوز إسقاطه، وقد يخطئ الظن، ولا يقع ما ظنه الطبيب، ولا يحصل التشوه، والأصل حرمة إسقاط الجنين إلا عن مضرة كبرى يخشى منها موت الأم. وهكذا بعد أن تنفخ فيه الروح من باب أولى يحرم إسقاطه؛ لأنه صار إنسانًا، فلا يجوز قتله، ولا يحل، لكن لو وجدت حالة يخشى منها موت الأم، وقد تحقق الأطباء أن بقاءه يسبب موتها فحياتها مقدمة، فيعمل الأطباء ما يستطيعون من الطرق التي يحصل بها خروجه حيًا إذا أمكن ذلك. وأما ما قبل نفخ الروح فيه في الطور الثاني والثالث؛ فالأمر أسهل، لكن لا يجوز إسقاطه إلا على وجه يتحقق الطبيب المختص أن بقاءه يسبب خطرًا على الأم، موت الأم، فينبغي أن يكون في ذلك طبيبان فأكثر، مختصان ثقتان يقرران هذا الشيء، ولا يجوز التساهل في ذلك، لا مع طبيب واحد، ولا مع غير الثقات، بل لابد من طبيبين فأكثر، ثقتين مختصين يقرران أن بقاءه يسبب هلاك أمه، هذا هو وجه السماح بعمل ما يلزم لإسقاطه حيًا إذا أمكن، أو غير حي. وأما في الطور الأول فالأمر فيه أوسع إذا اقتضت المصلحة في إسقاطه في الأربعين الأولى؛ فلا حرج في ذلك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9735/حكم-اسقاط-الجنين-في-الاربعين-الاولى-من-الحمل-بقرار-طبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_297/29701.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":11558,"question":"تقول: إذا قضت المرأة أشهر الحداد، ولم تنزع الملابس السوداء، وهي مستمرة في ارتدائها، فهل هذا يجوز لها؟","title":"حكم لبس السواد بعد انتهاء زمن الإحداد","answer":"الجواب:  إذا كان من عادتها ذلك؛ فلا بأس، أما إذا كانت تريد الزيادة على ما شرع الله من بقاء الحزن، وبقاء الإحداد هذا لا يجوز، ليس لها أن تزيد عما شرع الله، أما إذا كانت عادتها لبس هذه الملابس، وليس قصدها مخالفة الشرع، ولكنها تحب الملابس السوداء، أو الخضراء التي كانت تلبسها، وإلا فلتطيب وتلبس الحلي غيرت الإحداد، لبست الحلي تطيبت؛ لا حرج في ذلك، أن تلبس ما شاءت عن غير قصد الإحداد، الإحداد انتهى. أما أن تبقى على حالها لا تلبس الجميل ولا تطيب ولا تكتحل تزيد على أربعة أشهر وعشرًا؛ هذا لا يجوز، هذه بدعة ومنكر.","link":"https://binbaz.org.sa/fatwas/9741/حكم-لبس-السواد-بعد-انتهاء-زمن-الاحداد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_297/29707.mp3","categories":["العِدَد","اللباس والزينة"]},{"id":11573,"question":"بعد هذا رسالة بعثت بها إحدى الأخوات المستمعات تقول المرسلة أم رواحة ، أم رواحة تقول عن نفسها: أنا امرأة عمري في الخامسة والثلاثين، وفي شعري شيب، وأضع الحناء، ويصبح بعد ذلك لون شعري نصفه أحمر، والنصف الآخر أسود، وزوجي يسخر مني -أيضًا- ويعيرني بالشيب، وحينئذ أسأل سماحتكم: هل يجوز أن أستخدم الكتم حيث لونه يقارب الزيتي الغامق؟ علمًا بأنني لا أريد الزينة، والتزين، بل لزوجي فقط، جزاكم الله خيرًا.","title":"صبغ المرأة شعرها يجوز بغير السواد","answer":"الجواب:  يقول النبي ﷺ: غيروا هذا الشيب، واجتنبوا السواد غيريه بشيء لا يكون سوادًا خالصًا، يكون بين السواد والحمرة أو الصفرة، أما السواد الخالص بالكلية؛ فلا يجوز، ولكن غيريه بشيء أصفر، أو أحمر، أو بين السواد والحمرة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9756/صبغ-المراة-شعرها-يجوز-بغير-السواد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_386/38606.mp3","categories":["اللباس والزينة"]},{"id":11578,"question":"تسأل سماحتكم -جزاكم الله خيرًا- عن وضع المرأة لأدوات التجميل من الأحمر وغيره، هل هو جائز أمام الصديقات؟ بارك الله فيكم.","title":"حكم استعمال المرأة المكياج أمام صديقاتها","answer":"الجواب:  لا حرج، التجميل بين النساء، وعند الزوج والمحارم كالكحل وأشباه ذلك، وما يوضع في الشفه من صبغ أو غيره أو .... أو نحو ذلك كل هذا لا بأس به الحمد لله، لكن يجب الحذر من فعل ذلك عند الأجانب والتبرج، أما بين النساء، أو عند الزوج والمحرم؛ فلا بأس، نعم. المقدم: بارك الله فيكم، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9761/حكم-استعمال-المراة-المكياج-امام-صديقاتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_386/38609.mp3","categories":["اللباس والزينة"]},{"id":11619,"question":"من أم يارا رسالة وضمنتها جمعًا من الأسئلة في أحدها تقول: هل لبس البرقع الذي له رتبة الوسط، هل يجوز لبسه أم لا؟","title":"حكم البرقع للمرأة إذا كان يظهر العينين فقط","answer":"الجواب: لبس البرقع جائز إذا كان ساتر الوجه ما عدا العين أو العينين، وأما إذا كان يبدي شيئًا من الوجه الجبهة، أو الخدين أو.. فلا يجوز عند الرجال عند الرجل الأجنبي، بل يجب ستر الوجه بالخمار، أما إذا كان مجرد العين فقط أو العينين، ولا يخرج سواهما؛ فلا بأس لقوله ﷺ في حق المحرمة لا تنتقب ولم يمنعها من الخمار، إنما منعها من الانتقاب المصنوع الذي يصنع على قدر الوجه، فهذا يدل على أنه يجوز لبسه في غير الإحرام، ولكن لبس الخمار الساتر أفضل وأكمل. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9798/حكم-البرقع-للمراة-اذا-كان-يظهر-العينين-فقط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_388/38809.mp3","categories":["اللباس والزينة"]},{"id":11626,"question":"مجموعة من النساء ذهبن للحج، وعندما وصلن عرفة يقلن: إننا خلعنا الثياب عن رؤوسنا لشدة الحر، ولم يكن يعلمن ما حكم ذلك، فما هو توجيهكم؟","title":"حكم نزع المرأة غطاء رأسها في الحج بعرفات","answer":"الجواب: الوقوف الحمد لله لا بأس به، إذا كان ما عندهم أجانب لا حرج -إن شاء الله- الستر هذا يجب عند وجود الأجنبي، أما إذا خلعنه عن رؤوسهن في الخيمة ليس عندهن إلا النساء؛ فلا حرج في ذلك، مثل الرجل لو طرح الرداء عن كتفيه للحر؛ فلا بأس بذلك، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9811/حكم-نزع-المراة-غطاء-راسها-في-الحج-بعرفات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_388/38822.mp3","categories":["اللباس والزينة","مسائل متفرقة في الحج والعمرة","ردود وتعقيبات"]},{"id":11627,"question":"هل يجوز للمرأة أن تلبس الكم الشفاف، أو الكم الذي يكون أعلى من نصف الذراع؟","title":"حكم لبس المرأة للكم الشفاف والقصير عند مثيلاتها النساء","answer":"الجواب:  عند الحريم لا يضرها ذلك، لكن كونها تلبس الكم الساتر الطيب هذا هو الأفضل؛ لأنها قد تتعرض لغير محرمها كأخي زوجها، قد تتعرض للسائق أو الخادم، فإذا هي قد احتاطت واحتشمت، فالذي ينبغي لها أن تتحرى الثياب الساترة لجميع بدنها حتى لا تتعود الشيء الناقص، والشيء الذي قد يعرضها لرؤية الأجنبي لما حرم الله منها، أما عند النساء فالأمر أسهل؛ لأن المرأة لها أن تنظر إلى ساق المرأة، وإلى ذراعها، وإلى صدرها، ورأسها إنما يحرم على المرأة مع المرأة ما بين السرة والركبة، كالرجل مع الرجل. نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9806/حكم-لبس-المراة-للكم-الشفاف-والقصير-عند-مثيلاتها-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_388/38817.mp3","categories":["اللباس والزينة"]},{"id":11628,"question":"أخت لنا في الله تقول: أختكم في الله ح. السمري، تسأل وتقول: هل إزالة الشعر الزائد من بين الحاجبين هل ذلك جائز، أو لا؟","title":"حكم إزالة الشعر الزائد بين الحاجبين","answer":"الجواب:  لا أعلم به بأسًا؛ لأنه ليس من الحاجبين، ليس من الحاجبين، وإن تركته احتياطًا؛ فحسن، نعم","link":"https://binbaz.org.sa/fatwas/9801/حكم-ازالة-الشعر-الزاىد-بين-الحاجبين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_388/38812.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":11669,"question":"يقول: بعض الناس يقولون: إن كشف الوجه والكفين ليس بعورة، ويستدلون بحديث أسماء، فهل هذا الحديث صحيح، أم هو ضعيف؟ وما هو توجيهكم للناس؟ جزاكم الله خيرًا.","title":"الرد على من يستدل بحديث أسماء على كشف الوجه والكفين","answer":"الجواب:  حديث أسماء ليس بصحيح، وهو حديث أسماء بنت أبي بكر، فيه: أنها دخلت على النبي ﷺ وعليها ثياب رقاق، فأعرض عنها النبي ﷺ وقال: يا أسماء! إن المرأة إذا بلغت المحيض لم يحل أن يرى منها إلا هذا وهذا وأشار إلى وجهه وكفيه هذا الحديث .... رواه أبو داود لكنه ضعيف الإسناد، لعلل منها: أنه من رواية خالد بن دريك عن عائشة، ولم يسمع منها فهو منقطع، وفي سنده سعيد بن بشير وهو ضعيف الرواية. وكذلك في سنده قتادة وقد عنعن، والمعنعن إذا كان مدلسًا لا تقبل روايته حتى يصرح بالسماع. ثم فيه علة رابعة: وهو أن أسماء بنت أبي بكر أخت عائشة، المرأة المعروفة بالاستقامة والخير زوجة الزبير، كيف يليق منها أن تدخل على النبي ﷺ في ثياب رقاق؟! هذا منكر المتن، لا يمكن، ولا يتصور أن أسماء المعروفة بالدين والاستقامة زوجة الزبير أن تدخل على النبي ﷺ في ثياب رقاق!! ثم لو فرضنا صحته وسلامته فهذا يكون قبل النسخ، حين كان الحجاب لم يفرض، أما بعد فرض الحجاب فينهى عن كشف الوجه واليدين للأجنبي، وكانوا قبل ذلك تكشف المرأة وتجلس مع الرجال مكشوفة الوجه، ثم نسخ هذا الأمر ونزلت آية الحجاب، وهي قوله تعالى: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] هذا هو الصواب أن هذا الحديث ضعيف، ولو سلم من العلل؛ لكان محمولًا على أن هذا كان قبل نسخ الكشف، قبل نزول آية الحجاب، والله ولي التوفيق. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9853/الرد-على-من-يستدل-بحديث-اسماء-على-كشف-الوجه-والكفين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_390/39003.mp3","categories":["اللباس والزينة","الحكم على الأحاديث","قضايا المرأة"]},{"id":11676,"question":"رسالة موضوعها في غاية الأهمية -سماحة الشيخ- كتبت بأسلوب عامي بحت صاحبة الرسالة تقول: أختكم في الله التي رمزت إلى اسمها بالحروف (م. ع. س) من المنطقة الجنوبية، سأحاول قراءة الرسالة كما وردت.تقول عن نفسها: إني فتاة أبلغ من العمر السادسة والعشرين، لا أقرأ، ولا أكتب، وطلبت من كان عنده علم كتابة هذه الرسالة: أفيدكم أننا بدو من بوادي أهل الجنوب، وإننا أهل أغنام كثيرة، ولازم نخرج أمام الرجال ونحضر لهم الأكل والشرب ونكلمهم، ولكننا والحمد لله رب العالمين، متقيدين بالإسلام قلوبنا طاهرة، ونحن أمرنا بالحجاب، ونحن متسترون، وقد ذاعت الندوات بالأمر بالحجاب، ولكننا لم نقدر إلا على الغطوة -المراد: غطاء الوجه- ولم نقدر على باقي الحجاب من الجلباب ونحوه، وقد سمعنا أشرطة فيها أحاديث تقول:إن المرأة إذا تغطت، يعني: غطت عيناها، ولم ترتدي الحجاب كاملًا، وتخرج أمام الرجال، وتكلمهم؛ فإنه لا يصح لها أبدًا التحجب؛ لأنها تخرج أمام الرجال وتكلمهم، فنرجو من الله، ثم منكم -جزاكم الله خير الجزاء- أن تفيدونا، هل نمنع الغطوة، أم نخليها؟ لأنها لم توف الحجاب كاملًا بالجلباب؛ لأن هناك أناس كثيرين تركوا الغطوة؛ لأنها ليست من الحجاب الكامل، جزاكم الله خيرًا.","title":"حكم الحجاب وصفته","answer":"الجواب:  الحجاب للمرأة عند غير محارمها أمر لازم؛ لأنها فتنة، والنظر إليها فتنة، فوجب عليها الحجاب ابتعادًا من الفتنة لها ولغيرها، وقد قال الله  في أزواج النبي ﷺ وغيرهن من باب أولى: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]. والحجاب يكون بالجلباب، ويكون بغيره من الملابس التي تغطي البدن، وتستر البدن ومنه الوجه، والوجه هو أعظم الزينة، فستره هو أهم المهمات، هو أعظم الزينة، تستر رأسها، أو وجهها، وسائر بدنها، ولا مانع أن تبدي عينًا، أو عينين للنظر، أو لنظر الطريق، والحاجات التي تريد أخذها وحملها. فالحاصل: أن الحجاب لابد منه في حق المرأة بالنسبة إلى غير محارمها، وقال -جل وعلا-: يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلابِيبِهِنَّ ذَلِكَ أَدْنَى أَنْ يُعْرَفْنَ فَلا يُؤْذَيْنَ [الأحزاب:59] والجلباب ثوب تلقيه المرأة على رأسها وبدنها زيادة في التحجب والستر، فإذا كانت ملابسها ضافية، وغطت وجهها ورأسها؛ كفى ذلك، لكن الجلباب يكون من مزيد التستر، وهكذا قوله -جل وعلا- في سورة النور: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ [النور:31] الآية، فإذا سترت الزينة وهي الوجه، وبقية البدن بالجلباب أوغيره، حصل المقصود.  ليس المقصود الجلباب وحده، المقصود ما يسترها، ويبعد الخطر والفتنة، فإن تيسر الجلباب وهو الثوب الضافي، تضعه على بدنها، وتستر به وجهها، وبدنها؛ فالحمد لله، وإن ما تيسر فالحجاب بما يسمى الشيلة، أو غير الشيلة مما توضع على الرأس والوجه، ويستر ذلك يكفي ذلك، وإذا سترت الرأس وجعلت على وجهها برقعًا ترى منه حاجاتها، تبدي العين الواحدة، أو عينين، والباقي مستور، لا حرج في ذلك، وإن تيسر الستر للجميع كان ذلك أكمل بالنسبة إلى البعد عن الخطر؛ لأن الناس يختلفون، بعضهم يتأثر بالعين أيضًا، ولكن هديه ﷺ وسنته دل على أن النقاب جائز، ولهذا قال النبي ﷺ في حق المحرمة: ولا تنتقب المرأة، ولا تلبس القفازين فدل على أن غير المحرمة تنتقب، ولا حرج، غير المحرمة تنتقب، أما المحرمة لا تلبس النقاب، والنقاب ما يوضع على الوجه، وفيه نقب للعين والعينين، ويسمى: البرقع، فإذا .... جعلته على وجهها ..... أو نقبت فيه نقبًا، أو نقبين للعينين فقط، مع ستر الوجه كله، الجبهة والخدين؛ فلا بأس بذلك، الله -جل وعلا- يقول: يُرِيدُ اللَّهُ بِكُمُ الْيُسْرَ [البقرة:185]، ويقول سبحانه: وَمَا جَعَلَ عَلَيْكُمْ فِي الدِّينِ مِنْ حَرَجٍ [الحج:78]. بعض النساء لو جعلت الحجاب ساترًا لعينيها لم تهتدي الطريق، ولم تعرف أن تسير، فلا بد من شيء يعينها على قضاء حاجاتها، وأن يعينها على سيرها في الأسواق وفي بيتها، وحول غنمها، وحول مزرعتها إلى غير ذلك، وفق الله الجميع. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا، نعم، إذًا ذلك الفهم الذي يقول: إن غطاء الوجه، إما أن يكون كاملًا للبدن كله، أو ليس له أثر فهم خاطئ؟ الشيخ: خاطئ نعم، المهم الستر من جلباب وغيره. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9864/حكم-الحجاب-وصفته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_299/29905.mp3","categories":["حكم الصلاة وأهميتها","اللباس والزينة","فتاوى متنوعة"]},{"id":11687,"question":"هل يوصي سماحة الشيخ حول هذه الملابس التي تصف تقاطيع الجسم، والتي انتشرت حتى في البوادي؟","title":"حكم لبس المرأة للملابس الضيقة","answer":"الجواب:  نعم، الواجب العناية بالستر الضافي الواسع الذي يستر البدن ولا يقطعه، الضيق لا يجوز؛ لأنه يبدي العورة في الحقيقة، الضيق الذي يبدي حجم العورات لا يجوز، لكن تكون الملابس متوسطة، لا واسعة تبدي العورات، ولا ضيقة تبدي العورات، ولكنها وسط، هذا هو المشروع الوسط في الأمور كلها، لا الضيق الذي يبدي حجم الأعضاء، ولا الواسع الذي قد يرى منه الذراع، أو يرى منه الساق، بل تكون ساترة لقدميها وساقيها ويديها، ورأسها ووجهها تكون ساترة سترًا بثوب ساتر، لا رقيق، ولا قصير، يكون من الثياب الساترة الصفيقة الساترة للبدن كله؛ لأنها عورة المرأة عورة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9867/حكم-لبس-المراة-للملابس-الضيقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_299/29906.mp3","categories":["اللباس والزينة"]},{"id":11688,"question":"مستمعة تقول: (ع. س) من مصر تسأل وتقول: لنا حقل مزروع، وبه فاكهة، ويبعد عن منزلنا حوالي مائة وخمسون مترًا، أذهب أنا وحدي لهذا الحقل لقطف الثمار بغير محرم، هل يجوز لي ذلك، أم أكون مرتكبة لإثم، علمًا بأن الطريق والمكان آمن، ولله الحمد؟","title":"حكم خروج المرأة إلى المزرعة القريبة بدون محرم","answer":"الجواب:  ليس هذا بسفر، ولا حرج، لا حرج في الذهاب إلى المزرعة بدون محرم، إذا كانت قريبة مثلما ذكرت السائلة، الممنوع إذا كان سفرًا، ثمانين كيلو، أو حولها، نعم، هذا هو الذي يمنع إلا بمحرم. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9887/حكم-خروج-المراة-الى-المزرعة-القريبة-بدون-محرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_391/39117.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":11690,"question":"مستمعة تقول: (ع. س) من مصر تسأل وتقول: لنا حقل مزروع، وبه فاكهة، ويبعد عن منزلنا حوالي مائة وخمسون مترًا، أذهب أنا وحدي لهذا الحقل لقطف الثمار بغير محرم، هل يجوز لي ذلك، أم أكون مرتكبة لإثم، علمًا بأن الطريق والمكان آمن، ولله الحمد؟","title":"حكم خروج المرأة إلى المزرعة القريبة بدون محرم","answer":"الجواب:  ليس هذا بسفر، ولا حرج، لا حرج في الذهاب إلى المزرعة بدون محرم، إذا كانت قريبة مثلما ذكرت السائلة، الممنوع إذا كان سفرًا، ثمانين كيلو، أو حولها، نعم، هذا هو الذي يمنع إلا بمحرم. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9887/حكم-خروج-المراة-الى-المزرعة-القريبة-بدون-محرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_391/39117.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":11699,"question":"هل على المرأة إثم إذا أرادت الذهاب إلى السوق، حيث أن الزوج لا يمكنه شراء ما تحتاجه المرأة على الوجه الأكمل، بحيث تكون متحجبة تمامًا؟","title":"حكم خروج المرأة إلى السوق","answer":"الجواب:  إذا أذن لها زوجها، أما إذا لم يأذن؛ فليس لها ذهاب، تخبره بما تريد، وهو يشتري، أو غيره من صديقاتها، أو غير ذلك من إخوتها وأقاربها. المقصود: لا بد من إذنه، فإذا سمح لها، وخرجت متسترة، بعيدة عن الفتنة والتبرج؛ فلا بأس، أما إذا لم يأذن زوجها؛ فإنها لا تخرج، ولكن تستطيع أن تطلب منه أن يؤمن حاجاتها، أو شخص آخر يرضونه، يرضاه الزوج والزوجة، يقوم بجميع الحاجات من رجل، أو امرأة. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9880/حكم-خروج-المراة-الى-السوق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_391/39110.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":11702,"question":"امرأة عملت عملية تجميل في وجهها من غير ضرورة، وكان ذلك في لحظة غفلة، وبعد ذلك تابت إلى الله، والآن هي خائفة كثيرًا مما فعلت، فهل تقبل توبتها؟","title":"حكم عملية التجميل للمرأة دون ضرورة","answer":"الجواب:  نعم التوبة مقبولة من جميع الذنوب، إذا صحت إذا كانت توبة نصوحًا؛ تقبل من جميع الذنوب، قال الله تعالى: قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنْفُسِهِمْ لا تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا إِنَّهُ هُوَ الْغَفُورُ الرَّحِيمُ [الزمر:53] أجمع العلماء على أن هذه الآية في التائبين من الشرك وغيره، من تاب توبة صادقة من الشرك، وسائر الذنوب؛ تاب الله عليه، ومن ذلك ما فعلت المرأة؛ لأن التوبة رحمة من الله، وفضل من الله منَّ بها على عباده. والتوبة الصادقة النصوح تشتمل على شروط ثلاثة: الندم على الماضي، والإقلاع من الذنب، والعزم الصادق ألا يعود فيه، هذه هي الشروط الثلاثة من رجل، أو امرأة. الأول: الندم، .. كونه يأسف على الماضي، يندم عليه، يحزن لما فعل. الثاني: يدع المعصية، يتركها، يحذرها؛ خوفًا من الله وتعظيماً لله، وطاعة له.  الثالث: يعزم عزمًا صادقًا أنه لا يعود في الذنب، سواء كان الذنب يختص به، أو يختص بغيره. لكن إذا كان بغيره لابد من شرط رابع: وهو تحلله، أو إعطاؤه حقه، إذا كان ظلم أحدًا يطلب منه أن يسامحه، أو يعطيه حقه، إن كان قصاصًا يقتص منه، إن كان مالًا يعطيه ماله، إن كان غيبة يتحلله، فإن كان لا يستطيع أن يتحلله من الغيبة، فإنه يذكره بالصفات التي يعلمها عنه أنها طيبة، يذكره بها في المجالس التي اغتابه فيها يعني: المجالس التي ذكره فيها بالسوء يذكره فيها بالخير الذي يعلمه، فتكون هذه بهذه، إلا إذا تيسر له أن يستسمحه، ويقول: سامحني قد تكلمت في عرضك، فإذا سامحه؛ حصل المطلوب. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9881/حكم-عملية-التجميل-للمراة-دون-ضرورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_391/39111.mp3","categories":["اللباس والزينة"]},{"id":11722,"question":"له سؤال آخر يقول فيه: ما هو الدليل على وجوب تغطية المرأة وجهها، وهل لبس البرقع والكاب جائز؟ والكاب يعرفه فيقول: إنه لباس أسود كالثوب ليس مفتوحًا من الأمام جزاكم الله خيرًا.","title":"الأدلة على وجوب تغطية المرأة لوجهها","answer":"الجواب:  الدليل على ستر الوجه واليدين والبدن قوله -جل وعلا-: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] وكان في أول الإسلام تكشف المرأة وجهها ويديها، ثم نسخ الله ذلك وأمرهن بالحجاب، وأنزل في ذلك هذه الآية هذه آية الحجاب وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] يعني غير المحارم. أما المحارم فلا بأس كأبيها وأخيها ونحو ذلك، وهكذا قوله -جل وعلا-: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ [النور:31] الآية، فالوجه من الزينة واليدان من الزينة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9905/الادلة-على-وجوب-تغطية-المراة-لوجهها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_421/42103.mp3","categories":["اللباس والزينة"]},{"id":11778,"question":"رسالة بعث بها أحد الإخوة يقول المرسل راشد رشيد، أخونا يسأل ويقول: بعض الناس يقول: إنه لا مانع من أن تسلم على زوجة عمك الكبيرة في السن، وكذلك زوجة خالك، وأنا ممتنع عن ذلك، وعندما أقول: إنه لا يجوز يقولون: أنت فرقت بين العائلة، فما هي الإجابة الصحيحة؟ وفقكم الله.","title":"حكم مصافحة زوجة العم والخال","answer":"الجواب:  السلام على زوجة الأخ، وزوجة العم، وزوجة الخال لا بأس بالكلام، أما إذا كان المراد به المصافحة، أو التقبيل ما يجوز، لا يصافحها، ولا يقبلها، أما بالكلام السلام عليكم، كيف حالك يا فلانة؟ لزوجة العم، كيف أولادك؟ لا بأس بهذا، كان النبي ﷺ يسلم عليه النساء، ويسلم عليهن -عليه الصلاة والسلام- وهكذا الصحابة، فأنت تسلم على زوجة أخيك، وعلى زوجة عمك، وخالك، وجيرانك، لا بأس، لكن مع التستر، مع الحجاب، وعدم الخلوة، وعدم المصافحة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9957/حكم-مصافحة-زوجة-العم-والخال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_394/39419.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":11785,"question":"يسأل سماحتكم فيقول: هل صوت المرأة عورة؟","title":"صفة صوت المرأة الذي لا خضوع فيه","answer":"الجواب:  صوتها ليس بعورة، قد كان النساء يسألن النبي ﷺ ويسألن الصحابة، ولم ينكر عليهن النبي ﷺ ذلك، وإنما العورة خضوعها بالقول، وتغنجها؛ لقوله سبحانه: يَا نِسَاءَ النَّبِيِّ لَسْتُنَّ كَأَحَدٍ مِنَ النِّسَاءِ إِنِ اتَّقَيْتُنَّ فَلا تَخْضَعْنَ بِالْقَوْلِ فَيَطْمَعَ الَّذِي فِي قَلْبِهِ مَرَضٌ [الأحزاب:32]. فالمشروع لها أن يكون صوتها وسطًا، لا خضوع فيه، ولا فحش فيه، ولهذا قال: وَقُلْنَ قَوْلًا مَعْرُوفًا [الأحزاب:32]. فهكذا ينبغي للمرأة أن تكون متوسطة في كلامها، لا مفحشة في القول، ولا خاضعة فَيَطْمَعَ الَّذِي فِي قَلْبِهِ مَرَضٌ [الأحزاب:32]، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9969/صفة-صوت-المراة-الذي-لا-خضوع-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_422/42202.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":11830,"question":"هل الحمرة التي توضع على الشفتين تمنع وصول الماء عند الوضوء إلى الشفتين؟ وهل استعمالها محرم؟","title":"حكم استعمال الحمرة التي توضع على الشفاة","answer":"الجواب:  الحمرة والديرم وأشباهه لا تمنع الماء، ولا حرج في ذلك، أما إذا كان شيء له جرم يمنع الماء؛ يزال عند الوضوء، كالمناكير وأشباهها في الأظفار، أما إذا كان حمرة فقط كحمرة الحناء، ونحوه والديرم؛ فهذا لا يضر، ولا يمنع الماء. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10009/حكم-استعمال-الحمرة-التي-توضع-على-الشفاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_395/39512.mp3","categories":["اللباس والزينة"]},{"id":11838,"question":"من اليمن رسالة بتوقيع أحد الإخوة يقول (أ. ع. ع): يسأل ما حكم طلاء المرأة لأظافرها وهي لا تصلي -أي: عندها العذر الشهري- وبمجرد انتهاء أيام الدورة تزيل هذا الطلاء، هل تكون آثمة؟","title":"حكم طلاء المرأة أظافرها أثناء العادة الشهرية","answer":"الجواب:  لا حرج في ذلك، إذا كان في وقت ما فيه صلاة؛ تجعل شيئًا تحتاجه في مواضع الوضوء، ثم يزال عند وقت الوضوء. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10032/حكم-طلاء-المراة-اظافرها-اثناء-العادة-الشهرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_396/39612.mp3","categories":["اللباس والزينة"]},{"id":11841,"question":"هل يجوز للنساء إزالة الشعر من اليدين، والرجلين، أم يعتبر هذا تغييرًا لخلق الله؟","title":"حكم إزالة شعر اليدين والرجلين للمرأة","answer":"الجواب:  لا حرج في ذلك، ولكن لا تزيل الحاجبين؛ لأن هذا هو النمص، لكن لو كان في اليدين، أو الرجلين شعر، أو لحية لها، أو شارب؛ يزال، ولا حرج في ذلك. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10033/حكم-ازالة-شعر-اليدين-والرجلين-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_396/39613.mp3","categories":["اللباس والزينة"]},{"id":11851,"question":"هل يجوز للرجل أن يتحنى بالحناء، وهل وجد ذلك في عهد النبي ﷺ وصحابته؟","title":"حكم استعمال الحناء للرجل","answer":"الجواب:  الحناء من زي النساء، لا من زي الرجال، لكن إذا دعت له الحاجة من باب الدواء لدواء لرجليه، أو في غيره من باب الدواء على وجه، لا يكون فيه تشبه بالنساء؛ فلا بأس من باب الدواء، وإلا هو من زي النساء، ومن عادة النساء، لكن لو وجد في بلد يستعمله هؤلاء وهؤلاء، ولا يكون فيه تشبه لهؤلاء في صفة، ولهؤلاء في صفة، يعني: من زيهم ..... يستعملونه لم يكن فيه تشبه، مثلما يستعملون .... الملابس المعتادة التي يعتادها النساء والرجال في المصلى، وفي غير ذلك. المقصود: إذا وجد في بلد شيء يعتاده الجميع، ما يكون خاصًا بالرجال، ولا يكون خاصًا بالنساء، مثل الخاتم الفضة، ومثل الشيء الذي .. مثل المصليات السجادات، مثل أشياء اعتادها الجميع ما فيها تشبه. نعم. المقدم: بارك الله فيكم، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10031/حكم-استعمال-الحناء-للرجل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_396/39611.mp3","categories":["اللباس والزينة"]},{"id":11860,"question":"تقول أختنا في سؤال أخير: بعض الشباب هداهم الله يخجلون من لبس الثوب القصير، وغطاء الرأس كما كان يفعله الرسول ﷺ فهل من كلمة توجهونها لشباب الأمة؟","title":"التحذير من الإسبال للرجال وحكم لبس العمامة","answer":"الجواب:  الواجب على كل مسلم من الرجال أن يحذر الخيلاء والإسبال، وأن يكون ثوبه إلى الكعب، لا ينزل عن الكعب، وليس في هذا خجل، بل هذا هو السنة، هذا المشروع، ولكن الشياطين تزين للناس الباطل، ونواب الشياطين كذلك، وإلا فالمشروع أن تكون ثيابه إلى الكعب، وهذا هو المشروع، وهذا هو لبس الرجال، أما الإسبال فهو محرم، ومن التشبه بالنساء أيضًا، المرأة تسبل ثيابها؛ لأنها عورة، وقدمها عورة، فلا يليق بالرجل أن يتشبه بالمرأة، والنبي  يقول: ما أسفل من الكعبين من الإزار؛ فهو في النار ويقول -عليه الصلاة والسلام-: ثلاثة لا يكلمهم الله، ولا ينظر إليهم يوم القيامة، ولا يزكيهم، ولهم عذاب أليم: المسبل إزاره، والمنان فيما أعطى، والمنفق سلعته بالحلف الكاذب خرجه مسلم في صحيحه.  فلا يجوز للمسلم أن يرخي ثيابه تحت الكعبين، بل يجب أن يكون الحد الكعب، وإذا رفعه إلى نصف الساق؛ كان أفضل. أما النساء فالواجب عليهن الإسبال يعني: تغطية الأقدام، سئل النبي ﷺ عن ذلك؟ فقال: ترخي شبرًا فقال له بعض النساء: إذًا تبدو أقدامهن، قال: يرخين ذراعاً ولا يزدن على ذلك. فالمرأة عورة، ترخي ملابسها، ذراعًا، أو أقل، وأما الرجل لا، ليس له أن يرخي تحت الكعب، بل الحد الكعب، وأما الرأس فأمره واسع، ليس بعورة، الرأس بالنسبة للرجل، إن جعل عليه عمامة، أو طاقية الذي يسمونها طاقية، أو الغترة المعروفة، الأمر واسع، أو جعله مكشوفًا؛ فلا بأس، الأمر واسع، مثل ما شرع الله في الإحرام للرجل، يلبس الرداء والإزار، دون شيء على رأسه، وإذا جعل على رأسه ما جرت به العادة من عمامة، أو كوفية، أو غترة، أو غير ذلك مما جرت به العادة؛ لا بأس، يلبس المعتاد بين قومه، لا يشذ عن قومه، يلبس الرجل المعتاد على رأسه، فإذا كان عادة قومه الغترة غترة، وإذا كانت عادتهم العمامة على الرأس المكورة، عمامة، إذا كانت عادتهم شيئًا آخر ليس فيه محذور شرعًا؛ لا بأس، حتى لا يشذ عنهم، ولا يلبس شهرة عنهم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10043/التحذير-من-الاسبال-للرجال-وحكم-لبس-العمامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_397/39706.mp3","categories":["اللباس والزينة"]},{"id":11867,"question":"درج النساء على لبس ما يسمى دبلة الخطوبة، فما هو توجيه سماحتكم؟","title":"حكم لبس دبلة الخطوبة","answer":"الجواب:  لا أعلم لها أصلًا، فإن كانت من عمل الكفار فالذي ينبغي تركها، وإن كانت ليست عملًا للكفار، بل اعتادها الناس؛ فالأمر فيها واسع سهل، لكن تركها أفضل بكل حال. نعم. المقدم: جزاكم الله خيرًا. نعم.","link":"https://binbaz.org.sa/fatwas/10045/حكم-لبس-دبلة-الخطوبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_397/39708.mp3","categories":["الأخلاق المذمومة","اللباس والزينة","الخِطْبَة والاختيار "]},{"id":11869,"question":"تقول أختنا في سؤال أخير: بعض الشباب هداهم الله يخجلون من لبس الثوب القصير، وغطاء الرأس كما كان يفعله الرسول ﷺ فهل من كلمة توجهونها لشباب الأمة؟","title":"التحذير من الإسبال للرجال وحكم لبس العمامة","answer":"الجواب:  الواجب على كل مسلم من الرجال أن يحذر الخيلاء والإسبال، وأن يكون ثوبه إلى الكعب، لا ينزل عن الكعب، وليس في هذا خجل، بل هذا هو السنة، هذا المشروع، ولكن الشياطين تزين للناس الباطل، ونواب الشياطين كذلك، وإلا فالمشروع أن تكون ثيابه إلى الكعب، وهذا هو المشروع، وهذا هو لبس الرجال، أما الإسبال فهو محرم، ومن التشبه بالنساء أيضًا، المرأة تسبل ثيابها؛ لأنها عورة، وقدمها عورة، فلا يليق بالرجل أن يتشبه بالمرأة، والنبي  يقول: ما أسفل من الكعبين من الإزار؛ فهو في النار ويقول -عليه الصلاة والسلام-: ثلاثة لا يكلمهم الله، ولا ينظر إليهم يوم القيامة، ولا يزكيهم، ولهم عذاب أليم: المسبل إزاره، والمنان فيما أعطى، والمنفق سلعته بالحلف الكاذب خرجه مسلم في صحيحه.  فلا يجوز للمسلم أن يرخي ثيابه تحت الكعبين، بل يجب أن يكون الحد الكعب، وإذا رفعه إلى نصف الساق؛ كان أفضل. أما النساء فالواجب عليهن الإسبال يعني: تغطية الأقدام، سئل النبي ﷺ عن ذلك؟ فقال: ترخي شبرًا فقال له بعض النساء: إذًا تبدو أقدامهن، قال: يرخين ذراعاً ولا يزدن على ذلك. فالمرأة عورة، ترخي ملابسها، ذراعًا، أو أقل، وأما الرجل لا، ليس له أن يرخي تحت الكعب، بل الحد الكعب، وأما الرأس فأمره واسع، ليس بعورة، الرأس بالنسبة للرجل، إن جعل عليه عمامة، أو طاقية الذي يسمونها طاقية، أو الغترة المعروفة، الأمر واسع، أو جعله مكشوفًا؛ فلا بأس، الأمر واسع، مثل ما شرع الله في الإحرام للرجل، يلبس الرداء والإزار، دون شيء على رأسه، وإذا جعل على رأسه ما جرت به العادة من عمامة، أو كوفية، أو غترة، أو غير ذلك مما جرت به العادة؛ لا بأس، يلبس المعتاد بين قومه، لا يشذ عن قومه، يلبس الرجل المعتاد على رأسه، فإذا كان عادة قومه الغترة غترة، وإذا كانت عادتهم العمامة على الرأس المكورة، عمامة، إذا كانت عادتهم شيئًا آخر ليس فيه محذور شرعًا؛ لا بأس، حتى لا يشذ عنهم، ولا يلبس شهرة عنهم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10043/التحذير-من-الاسبال-للرجال-وحكم-لبس-العمامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_397/39706.mp3","categories":["اللباس والزينة"]},{"id":11879,"question":"يقول: والدتي امرأة كبيرة في سن الخمسين تقريبًا، أو ربما تزيد، فهل يلزمها الزي الشرعي (النقاب) عند الخروج من المنزل، علمًا بأنها ترتدي زيًا محتشمًا، ولا تظهر إلا الوجه والكفين، فما هو الأفضل؟ وما العمل فيما لو لم تطع أمرنا؟ جزاكم الله خيرًا.","title":"حد القواعد من النساء اللاتي لا يجب عليهن الحجاب","answer":"الجواب:  أم خمسين لا تزال قوية، وليست من القواعد، ولا تزال النفوس تميل إليها؛ فالواجب عليها التستر، وعدم التكشف، الله يقول: وَالْقَوَاعِدُ مِنَ النِّسَاءِ اللَّاتِي لا يَرْجُونَ نِكَاحًا فَلَيْسَ عَلَيْهِنَّ جُنَاحٌ أَنْ يَضَعْنَ ثِيَابَهُنَّ غَيْرَ مُتَبَرِّجَاتٍ بِزِينَةٍ، ثم قال سبحانه: وَأَنْ يَسْتَعْفِفْنََ خَيْرٌ لَهُنَّ [النور:60]، والقواعد: العجائز الائي ما لا يلتفت إليهن، ولا يتزين، أما بنت الخمسين فهي حتى الآن فيها بقية، فالذي ينبغي لها التستر، والواجب عليها التستر، وعدم التزين عند الرجال الأجانب، أما بين النساء فلا بأس، ..... العورات بين النساء، مثل غيرها من النساء، لكن عند الرجال تستر وجهها بالخمار.. بالنقاب، كفيها بثيابها؛ لأن هذا أبعد عن الفتنة، ولعموم قوله سبحانه: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]. أما العجوز التي لا تشتهى، ولا تتعاطى الملابس الجميلة؛ فلا بأس أن تبدي وجهها وكفيها، من غير زينة، من غير اكتحال ولا تزين، ولكن تسترها أفضل. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10063/حد-القواعد-من-النساء-اللاتي-لا-يجب-عليهن-الحجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_424/42408.mp3","categories":["اللباس والزينة"]},{"id":11887,"question":"إحدى الأخوات المستمعات تقول: أم محمد من التويجرة أختنا تسأل عن لبس البرقع، وتقول: إنها سمعت من أكثر من شخص أن لبسه حرام، فهل تتفضلون ببيان البرقع الحلال، أو متى لا يجوز لبسه؟ جزاكم الله خيرًا.","title":"متى يجوز لبس البرقع للنساء؟","answer":"الجواب:  البرقع هو إطار يصنع للوجه، تبدو منه العينان، الرسول ﷺ نهى عن ذلك في حال الإحرام، ليس للمرأة أن تلبس البرقع حال إحرامها للعمرة أو للحج، وليس لها أن تلبس القفازين وهما الغشاءان في اليدين ...... اليدين حال إحرامها، يقول ﷺ: لا تنتقب المرأة المحرمة، ولا تلبس القفازين وهما: غشاءان ...... الجوربان في اليدين يقال لهما: القفازان، لا يجوز لبسهما للمحرمة بالحج والعمرة، وهكذا النقاب الذي يصنع للوجه وهو فيه نقبان للعينين، لا يجوز للمرأة أن تلبسه في الإحرام، لكن تغطي وجهها بالشيلة، أو بغيرها من القطع .......... تستر على الوجه، لما جاء عن عائشة -رضي الله عنها- قالت: \"كنا مع النبي في حجة الوداع مع النبي ﷺ فكنا إذا دنا منا الركبان ونحن محرمات سدلت إحدانا جلبابها من فوق رأسها على وجهها، فإذا بعدوا؛ كشفنا\". أما غير المحرمة فلها لبس البرقع، غير المحرمة لا بأس أن تلبس البرقع، لكن بشرط أن يكون النقب صغيرًا بقدر العينين؛ لأن الرسول ﷺ إنما نهى المحرمة، فدل على أن غير المحرمة لا بأس أن تلبسه مع مراعاة أن يكون النقبان ضيقين، بقدر العينين لأجل تهتدي إلى طريقها؛ فلا بأس بهذا، مع مراعاة عدم التكحل الذي قد يفتن، تكون عيناها على العادة، ليس فيها شيء يلفت النظر، فهذا -إن شاء الله- لا حرج فيه. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10071/متى-يجوز-لبس-البرقع-للنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_425/42508.mp3","categories":["اللباس والزينة"]},{"id":11893,"question":"هل كشف الشعر أمام الإخوة والأخوال والأعمام حرام؟","title":"حكم كشف المرأة شعرها وصدرها أمام محارمها","answer":"الجواب:  لا حرج في ذلك كونه يرى شعر الرأس للأخ أو العم أو الأب أو الابن لا حرج، لكن التستر والحشمة يكون أفضل، كونها تغطي رأسها عند محارمها يكون هذا أحوط وأفضل، ولاسيما في هذا العصر، عصر ضعف الإيمان وقلة الوازع. فالمقصود: أن وجودها بينهم مستورة الشعر والبدن ما عدا الوجه والكفين يكون هذا أبعد عن الفتنة وأسلم، ولكن لو رأوا رأسها أو صدرها أو ساقها لا حرج، لا حرج في ذلك؛ لأنهم محارم، كالنساء إذا رأت المرأة من أختها في الله صدرها، أو رأسها، أو ساقها لا بأس، لكن كونها تتحشم عند محارمها ولاسيما الأخوال والأعمام والإخوة، فإنه أشد خطر، فالتحشم عندهم كون الملابس كاملة إلا الوجه والكفين؛ يكون هذا أحوط وأكمل وأبعد عن الخطر. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10077/حكم-كشف-المراة-شعرها-وصدرها-امام-محارمها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_425/42514.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":11906,"question":"هل تربية أسماك الزينة في حوض في المنزل، أو عصافير الزينة في المنزل جائز شرعًا، أم أنه لا يجوز؟ جزاكم الله خيرًا.","title":"حكم اقتناء الأسماك والطيور في البيوت للزينة","answer":"الجواب:  حفظ الطيور في المنزل لا يهملها، بل أكرمها، وأحسن إليها هذه العصافير، أو غير عصافير إذا أكرمها وأعطاها علفها؛ فلا بأس، وإذا كان سمكًا جعله في بيته، يكون عنده؛ فلا بأس. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10090/حكم-اقتناء-الاسماك-والطيور-في-البيوت-للزينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_426/42607.mp3","categories":["اللباس والزينة"]},{"id":11916,"question":"يسأل ويقول: هل يجوز لبس الذهب للمرأة، سواء قل، أو كثر؟","title":"حكم لبس المرأة للذهب الكثير","answer":"الجواب:  الذهب مباح للنساء، فلها التحلي بالقليل والكثير، ما دام جرت العادة بذلك، وإذا ..... ولم تتحل إلا بالقليل؛ فلا بأس، لكن لها أن تتحلى بما جرت به العادة، وإن كثر، من أسورة وخواتم وأقرطة وغيره وقلائد، كل هذا لا بأس به، وإن كثر، وينفعها في المستقبل، ينفعها، أو ينفع ورثتها بعدها، لا يضر، لكن لا يكون فيه مباهات، أو إسراف .... تتحري الشيء المناسب، تتحرى العادة الذي يلبسوه أمثالها، هذا هو الأولى بها. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10100/حكم-لبس-المراة-للذهب-الكثير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_426/42617.mp3","categories":["اللباس والزينة"]},{"id":11927,"question":"تقول فتاة متزوجة: هل يجوز لزوجة أبيها أن تكشف على زوجها؟","title":"حكم كشف زوجة الأب لزوج بنت الأب","answer":"الجواب:  زوجة أبيها لا تكشف على زوجها؛ لأنها ليست ابنة لها، إنما المحرم أمها وجداتها، أما زوجة أبيها فليست محرمًا لزوجها، بل أجنبية، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10111/حكم-كشف-زوجة-الاب-لزوج-بنت-الاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_427/42704.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":11975,"question":"إحدى الأخوات المستمعات تسأل سماحة الشيخ فتقول: ما حكم وضع الشعر للفتاة بالطريقة المائلة للتجميل، هل يجوز ذلك؟ وما حكم ما يسمونه الكعكة المرتفعة في البيت، وعند المحارم، وهل يدخل هذا العمل في قول الرسول ﷺ عندما وصف النساء اللاتي من الأصناف التي لم يرها، وهن المائلات المميلات، ورؤوسهن كأسنمة البخت المائلة؟","title":"حكم إمالة المرأة لشعر رأسها للتجمل","answer":"الجواب: الأفضل فيما أعلم أن تكون الفرقة في وسط الرأس حذاء الأنف، لا تميل هكذا ولا هكذا، أما ما جاء في الحديث فالمراد به الميل عن الحق، صنفان من أهل النار في الحديث الصحيح، يقول النبي ﷺ: صنفان من أهل النار لم أرهما: رجال بأيديهم سياط يضربون بها الناس، ونساء كاسيات عاريات مائلات مميلات، رؤوسهن كأسنمة البخت المائلة، لا يدخلن الجنة، ولا يجدن ريحها هذا الحديث الصحيح فيه التحذير من ظلم الناس بغير حق، ولهذا ذم هؤلاء الذين بأيديهم سياط يضربون بها الناس، يعني: بغير حق، سواء كانوا شرطة، أو غيرهم، لابد في ضرب الناس من الدليل الموجب لذلك، بحكم الحاكم الشرعي، أو بتأمير ولي الأمر، أما ضرب الناس بغير حق هذا من أعظم الظلم الذي حرمه الله، فلا يجوز ضرب الناس إلا بدليل، لحكم حاكم، أو من ولي الأمر الذي يرى فيه المصلحة للمسلمين، لكون المضروب فعل ما يوجب ذلك. وأما النساء فالواجب عليهن أيضًا التستر، وأن يكن كاسيات كسوة ساترة، فالكسوة التي فيها ظهور العورة لرقتها، أو قصرها هذه عارية، ليست كسوة في الحقيقة، ولهذا قال: نساء كاسيات عاريات يعني: عليهن اسم الكسوة، لكنها كسوة غير ساترة، إما لرقتها، وإما لقصرها، هذا لا يجوز، بل منكر، ولهذا توعدهن بالنار، وهكذا: ( مائلات مميلات ) معناه: مائلات عن الحق والعفاف إلى الفجور والفساد. وهكذا (مميلات) يعني: يملن غيرهن من النساء إلى الباطل والشر، فهن مائلات في أنفسهن عن الحق، مميلات لغيرهن إلى الباطل، فلهذا استحقن النار والعاقبة السيئة، أما قوله: رؤوسهن كأسنمة البخت المائلة فهذه علامة عليهن، قال بعض أهل العلم: معناه: أنه يضخمن رؤوسهن، يعملن عليه اللفائف الشيء الذي يكبرها، هذه من علامتهن. أما الكعكة فلا يظهر بأنها هي المرادة بهذا الحديث؛ لأنها ما فيها تضخيم للرأس، هي قليلة كشعر قليل يجعل في وسط الرأس، أو في أسفل الرأس، لكن كونها تترك الجدائل مطروح مبذول يكون أولى وأفضل وأبعد عن الشبهة، كونها تترك رأسها يعني منجدل على ظهرها، أو بعضه على ظهرها وبعضه على جانبيها هذا يكون أولى، يكون لها جدائل وضفائر القرنان، والماشطة تكون من وراء، يكون هذا أفضل وأحوط وأجمل أيضًا، أما جمعه على الرأس، أو في مؤخر الرأس فيخشى أن يكون من هذا الباب، وإن كان ليس بظاهر، يعني لا يكون له شيء يشبه أسنمة البخت، بل يكون أقل من ذلك، لكن كونها تترك ذلك، وتطرحه على العادة القديمة، يكون على الظهر، وعلى الجانبين، يعني تجعل الضفائر مطروحة على ظهرها، وعلى جانبي رأسها، هذا هو الأولى والأبعد عن الشبهة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10160/حكم-امالة-المراة-لشعر-راسها-للتجمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_429/42916.mp3","categories":["اللباس والزينة"]},{"id":11980,"question":"تقول أختنا: هل يجوز صبغ الشعر بألوان مختلفة غير الأسود، وأيضًا إزالة الشعر الزائد من الحاجبين إذا كان شكله يشوه الوجه؟","title":"حكم صبغ المرأة لشعر رأسها بألوان مختلفة غير السواد","answer":"الجواب:  صبغ الشيب يجوز، سنة صبغ الشيب بالحمرة والصفرة ونحوها، أو السواد مع الحمرة مخلوط، وإنما يحرم السواد الخالص؛ لقول النبي ﷺ: غيروا هذا الشيب، واجتنبوا السواد فإذا غيرت المرأة، أو الرجل الشيب بالحناء، والكتم؛ صار بين السواد والحمرة، أو بالحمرة، أو بالصفرة؛ فلا بأس، بل هذا سنة، أما تغيير الشعر بغير السواد للزينة والجمال؛ فهذا تركه أحوط، ما نعلم فيه شيئًا، لكن تركه من باب الاحتياط؛ لأنه يخشى أن يكون من تغيير خلق الله، لكن الأولى ترك ذلك، والأحوط. وأما التحريم فلا يظهر فيه التحريم، لكن تركه من باب الاحتياط ..... يصبغون الشعر بشيء يلمع، أو شيء أزرق، أو كذا تركه أولى، إلا الشيب فالسنة تغييره، لكن بغير السواد. المقدم: طيب طيب، جزاكم الله خيرًا، الواقع شاع بين النساء سماحة الشيخ أن المرأة تصبغ شعرها بلون ملابسها؟ الشيخ: هذا ما نعرف له أصلًا، والأحوط تركه، الأحوط تركه؛ لأن الرسول ﷺ يقول: دع ما يريبك إلى ما لا يريبك من اتقى الشبهات؛ فقد استبرأ لدينه وعرضه. المقدم: الله المستعان، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10165/حكم-صبغ-المراة-لشعر-راسها-بالوان-مختلفة-غير-السواد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_430/43003.mp3","categories":["اللباس والزينة"]},{"id":11993,"question":"هل لبس البرقع حرام؟","title":"هل لبس البرقع حرام؟","answer":"الجواب:  البرقع إذا كان بقدر العين، لا يظهر إلا العين؛ لا بأس، وإن سترت نفسها بالخمار الكامل، كان أكمل وأطيب، أما العين لا بأس بخروجها إلا في الإحرام. المقدم: إلا في الإحرام. الشيخ: في الإحرام لا تلبس البرقع، نعم. المقدم: جزاكم الله خيرًا، بعض النساء سماحة الشيخ سخرن البرقع أيضًا للموضة، فهل من توجيه؟ الجواب: يجب أن يكون البرقع بقدر العين، يستر الوجه كله إلا مقدار العين، أو عين واحدة لأجل الطريق، وإن سترت بالخمار الذي ترى من ورائه الطريق؛ كفى، والحمد لله، أجمل وأحسن. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10178/هل-لبس-البرقع-حرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_431/43107.mp3","categories":["اللباس والزينة"]},{"id":12047,"question":"حدثونا عن الحجاب الشرعي للمرأة؟ وأيضًا من يجوز لها أن تخرج أمامهم؟ جزاكم الله خيرًا.","title":"صفة الحجاب الشرعي للمرأة","answer":"الجواب:  الحجاب الشرعي تستر بدنها ومنه: الوجه والكفان، يقول الله : وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]، وكان النساء في أول الإسلام يباح لهن كشف الوجه واليدين والجلوس مع الرجال، ثم أنزل الله الحجاب، فمنعوا من ذلك وأمروا بالحجاب. أما حديث أسماء الذي اشتهر عند الناس، لما دخلت على النبي ﷺ في ثياب رقاق، فقال لها النبي ﷺ: يا أسماء إن المرأة إذا بلغت المحيض لم يصلح أن يرى منها إلا هذا وهذا وأشار إلى وجهه وكفيه فهو حديث غير صحيح، ضعيف جدًا ولا يحتج به، وفيه علل متعددة.  وأما حديث: لا تنتقب المرأة فهذا في الحج لا تنتقب، لكن تستتر بغير النقاب، النقاب شيء يصنع للوجه يلبس، تجعل فيه نقبين للعينين أو نقبًا لأحدهما، هذا لا تلبسه المحرمة ولكن تستتر بالخمار، بإلقائه على وجهها أو بالجلال كما قالت عائشة -رضي الله عنها-: كناا مع النبي ﷺ في الحج، وكنا إذا دنا منا الرجال؛ سدلت إحدانا خمارها على وجهها، فإذا بعدوا كشفنا. فالمقصود: المرأة مأمورة بالحجاب، وهو التستر لوجهها وقدميها ورأسها وكفيها؛ لأنها فتنة، والوجه أعظم الزينة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10232/صفة-الحجاب-الشرعي-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_433/43316.mp3","categories":["اللباس والزينة"]},{"id":12062,"question":"تسأل عن أدوات التجميل التي يستعملها النساء، هل تنصحونهن بالاستمرار عليها، أم بالابتعاد عنها، ولاسيما إذا كانت تؤثر على الوضوء؛ لأن بعض أدوات الزينة إذا ثبتت على الأظفار يصعب إزالتها؟ جزاكم الله خيرًا.","title":"حكم استعمال المرأة لأدوات التجميل","answer":"الجواب:  أدوات التجميل فيها تفصيل: إن كانت ملصقة مثل ما يوضع على الأظفار المناكير؛ فهذه ينبغي تركها، ولا يحسن فعلها، فإن فعلت؛ أزيلت عند الوضوء، وجب أن تزال عند الوضوء؛ لأنها تمنع الوضوء. كذلك إذا كانت تؤثر في الوجه بقعًا، أو مرضًا؛ وجب تركها، أما الشيء الذي لا يكلف مثل: الكحل، مثل: وضع الديرق في الشفة، أو الصبغ الأحمر في الشفة، فلا بأس بذلك، المقصود أن التجميل الذي لا يضر وليس بمحرم، وليس فيه حرج كالكحل، وتجميل الشفة بالصبغ، أو بالديرق كما يقولون، أو تزيين اليدين والرجلين بالحناء، كل هذا لا بأس به، أما الشيء الذي يؤثر ضررًا في الوجه، أو يستر البشرة عند الوضوء، هذا يزال، الشيء الذي يحدث به ضرر في الوجه هذا لا ينبغي فعله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10247/حكم-استعمال-المراة-لادوات-التجميل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_434/43411.mp3","categories":["اللباس والزينة"]},{"id":12073,"question":"يسأل سماحتكم عن الصفة الشرعية للحجاب، هل لابد من لبس معين؟ أو أي ستر يستر المرأة، ويستر جسمها يجزئ عن ذلك؟ جزاكم الله خيرًا.","title":"صفة الحجاب الشرعي","answer":"الجواب:  نعم، المقصود الستر، فإذا حصل الستر بخمار أو بغيره فهذا هو المطلوب، تستر بدنها كله بأي طريقة، بالخمار على رأسها ووجهها، بالعباءة على بدنها كله ... تلبسه تعم به بدنها، المقصود الستر، هذا المقصود، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10258/صفة-الحجاب-الشرعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_435/43506.mp3","categories":["اللباس والزينة"]},{"id":12124,"question":"من المستمع سيد محمود أحمد سليمان من مصر رسالة وضمنها هذا السؤال يقول: إنني أعمل في المملكة سائق، وخرجت من الدمام قبل الحج، وعند الميقات أحرمت، ولكن قبل أن أدخل جدة أقهرت، أو أجبرت أن أحل الإحرام ثم ارتديته مرة أخرى واعتمرت، فما حكم ما فعلت؟","title":"حكم من لبس المخيط وغطى رأسه وهو محرم","answer":"الجواب:  عليك إطعام ستة مساكين، أو صيام ثلاثة أيام، أو ذبح شاة عن لبس المخيط، وعن غطاء الرأس، مثل ذلك: إطعام ستة مساكين، كل مسكين له نصف صاع من التمر، أو الأرز، من قوت البلد، أو صيام ثلاثة أيام مجتمعة، أو متفرقة، أو ذبح شاة في مكة للفقراء، أو سبع بدنة، أو سبع بقرة عن لبس المخيط المقطع مثلًا، وعليك مثل ذلك عن غطاء الرأس إن كنت غطيت رأسك؛ لكونك تعمدت ذلك، وأنت تعلم أنه لا يجوز لك، لكن للأسباب التي ذكرتها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10309/حكم-من-لبس-المخيط-وغطى-راسه-وهو-محرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_438/43809.mp3","categories":["اللباس والزينة","محظورات الإحرام","قضايا المرأة"]},{"id":12129,"question":"أخيرًا تسأل أختنا عن الملابس التي عليها بعض الصور كيف تتصرف فيها المرأة؟ جزاكم الله خيرًا.","title":"حكم لبس الملابس التي عليها صور","answer":"الجواب:  الملابس التي فيها صورة صورة الحيوان لا تلبس، صورة إنسان، أو بهيمة ما يلبس، النبي ﷺ لما رأى ثوبًا فيه صور؛ هتكه، وغضب وقال: إن أصحاب هذه الصور يعذبون يوم القيامة ويقال لهم: أحيوا ما خلقتم فلا يجوز لبس الثياب المصورة، ولا تعليقها على الجدران، ولا في المكاتب، ما يجوز هذا. لكن لا بأس أن تكون في فرش، في وسايد، في البسط لا بأس؛ لأنها ممتهنة، النبي ﷺ لما هتك الستر قالت عائشة -رضي الله عنها-: فجعلت منه وسادتين يرتفق بهما النبي، عليه الصلاة والسلام؛ لأنها ممتهنة، وفي حديث أبي هريرة  : أن النبي ﷺ واعد جبرائيل ذات يوم، فجاء جبرائيل ولم يدخل، فسأله النبي عن ذلك عليه الصلاة والسلام،، فقال: إن في البيت تمثالًا وستراً فيه تصاوير وكلبًا، فنظروا فإذا موجود التمثال فأمره بقطع رأس التمثال حتى يكون كهيئة الشجرة، وأمره بالستر أن تتخذ منه وسادتان توطآن منتبذتان، وأمر بالكلب أن يخرج، ففعل النبي ﷺ ما قاله جبرائيل ودخل جبرائيل عليه الصلاة والسلام وصار الكلب وجدوه تحت نضد لهم أدخله الحسن أو الحسين ، جرو أدخله الحسن أو الحسين، ابنا فاطمة، رضي الله عنهما وعنها.  فدل ذلك على أن الصورة إذا كانت في وسادة، أو في بساط يمتهن؛ فلا بأس، وأن الصورة إذا كانت ما لها رأس -جسم بلا رأس- ما تمنع، لا بأس من وجودها في الثوب أو غيره؛ لأنها كالشجرة حينئذٍ، نعم.  المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10314/حكم-لبس-الملابس-التي-عليها-صور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_438/43814.mp3","categories":["اللباس والزينة"]},{"id":12157,"question":"من إحدى الأخوات المستمعات من ليبيا رسالة وضمنتها جمعًا من الأسئلة، وهذه المستمعة رمزت إلى اسمها بالحروف: (ف. ط. أ) تسأل أولًا، هل يجوز حرق الملابس التي هي غير صالحة للبس؟ لأننا سمعنا أن ذلك حرام، أفيدونا جزاكم الله خيرًا.","title":"حكم إحراق الملابس غير الصالحة للاستخدام","answer":"الجواب:  لا يجوز حرقها؛ لأنه إضاعة للمال، ولكن تجعل وسائد، أو فراشًا يستمتع به، يعني: يجلس عليه، أو يتصدق بها على الفقراء، أما الإحراق لا، ولو كان فيه نجاسة؛ تغسل النجاسة، فيه صورة؛ تجعل وسادة، إذا كان في وسادة؛ لا بأس الصورة تمتهن، أما إحراقه هذه إضاعة، فالرسول ﷺ نهى عن إضاعة المال، فإذا كانت الخرق فيها صور، الصورة توضع في وسادة، خرقة في وسادة، أو كرسي يوطأ عليه، يجلس عليه، أو فراش ينام عليه، أو هذه الصورة تجعل في شيء آخر، يعني: يمتهن، لحاف يمتهن، أو ما أشبه ذلك لا تعلق، ولكن تكون في شيء يمتهن، إما فراشًا وإلا وسادة، وإلا يعطاها الفقراء ويقال للفقراء: اجعلوها كذا وكذا، فراشًا، أو وسائد، أو نحو ذلك، ولا تحرق، أما إن كان فيها نجاسة؛ تغسل، ما تحرق، تغسل، ويتصدق بها، أو يستعملها صاحبها، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10342/حكم-احراق-الملابس-غير-الصالحة-للاستخدام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_441/44107.mp3","categories":["اللباس والزينة"]},{"id":12163,"question":"نعود مع مطلع هذه الحلقة إلى رسالة جمعٍ من الأخوات في ليبيا بعثن برسالة ضمنها عددًا من الأسئلة، عرضنا بعضًا منها في حلقات مضت، وفي هذه الحلقة يسألن ويقلن: نرجو الإفادة حول لباس المرأة المسلمة، وما معنى الجلباب؟ إذ أن هناك بعض النساء في مناسبات الأفراح عندما يدخلن المكان الذي تكون فيه المناسبة يقمن بكشف شعرهن، فهل يجوز هذا، مع العلم بأنه لا يوجد رجال في هذه الأماكن؟ وماذا عن الغناء والرقص في الأفراح بين النساء؟","title":"ضابط لباس المرأة وحكم الغناء والرقص للمرأة","answer":"الجواب:  بسم الله، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فإن استعمال الجلباب أمر مطلوب بين الرجال الأجانب، والجلباب يشبه العباءة، وما أشبهه مما تغطي به المرأة بدنها كله، رأسها وبدنها فوق ثيابها، قال الله تعالى:  يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلابِيبِهِنَّ.. [الأحزاب:59] الآية، وفي الصحيح عن أم عطية -رضي الله عنها-: أن النبي ﷺ أمر النساء بحضور العيد، بحضور صلاة العيد، قالت: قال بعض النساء: إن إحدانا ليس لها جلباب، فقال -عليه الصلاة والسلام-: لتلبسها أختها من جلبابها.  فالمقصود: أن الجلباب شيء يستر البدن كله، وهو يشبه العباءة من بعض الوجوه. والواجب على النساء التحجب عن الأجانب، وعدم إظهار شيء من الزينة لهم، كأخي الزوج، وأخي زوج الأخت، وغيرهم ممن ليس محرمًا.  ولا بأس بالغناء المعتاد في العرس بين النساء، وضرب الدف الذي هو الطار، والدف له وجه واحد يضرب في مناسبة العرس لإعلان النكاح وإظهاره، وقد جاءت السنة في ذلك، وكان يستعمل في عهد النبي ﷺ، فلا بأس به لإظهار النكاح وإعلانه في وقت مناسب من الليل من دون سهر. ولا بأس -أيضًا- بالرقص ولا حرج في ذلك بين النساء، ولا بأس بالغناء المعتاد الذي ليس فيه دعوة إلى محرم، ولا تزيين للفواحش، ولكنه مدح للزوج، أو الزوجة، أو أهل الزوج، أو أهل الزوجة، ونحو ذلك مما جرت به العادة. كان النساء يغنين في عهد النبي ﷺ في العرس، ويضربن بالدف، ولا حرج في ذلك، بشرط: أن يكون ذلك ليس فيه اختلاط بين الرجال والنساء، بل يكون خاصًا بالنساء في ليلة العرس لإظهار النكاح وإعلانه، والله ولي التوفيق، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10349/ضابط-لباس-المراة-وحكم-الغناء-والرقص-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_442/44201.mp3","categories":["اللباس والزينة","الزفاف ووليمة العرس","الشعر والأغاني"]},{"id":12165,"question":"أيضًا يقلن هذا  سمعت أنه يجب على المرأة عدم كشف وجهها أمام الأجانب، هل يعتبر هذا فرضًا، أم سنة، وهل على من تركت هذا الأمر إثم، وهل تكون تغطية الوجه في جميع الأماكن، ثم إن هناك كثيرًا من الظروف تستدعي أن تكشف المرأة وجهها، مثلًا عند أخذ صورة خاصة بجواز السفر، والبطاقة الشخصية، وتكون المرأة مغطاة الوجه، ثم تبرز وجهها لأخذ الصورة، وكذلك تبرز جواز السفر، أو البطاقة التي تحمل صورتها للرجال للمطابقة؟","title":"احتجاب المرأة عن الرجال الأجانب ومتى يباح كشف الوجه؟","answer":"الجواب:  الاحتجاب مثلما تقدم، يجب على المرأة أن تحتجب عن الرجل الأجنبي بنص القرآن الكريم، لقول الله سبحانه: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] وهذا عام، ما قال: إلا الوجه، أو الوجه واليدين، بل عمم -جل وعلا- وهذا يعم أزواج النبي ﷺ ويعم غيرهن، والعلة التي بينها الرب -جل وعلا- كلهم في حاجة إليها، كلنا في حاجة إليها ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]. وهكذا قوله سبحانه في سورة النور: ولا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِِ بُعُولَتِهِنَّ [النور:31] والوجه والكفان من أظهر الزينة، ومن أعظم الزينة الخلقية، بالنسبة إلى الخلقة، والكحل والحلي والملابس الجميلة من أعظم الزينة المكتسبة، فالمؤمنة تبتعد عن هذا المنكر، وتستر نفسها وتحتجب، ابتعادًا عن الفتنة، وحذرًا من أن تفتن غيرها، أو تفتن هي في ذلك، نعم. لكن كشف الوجه للضرورة، في المسائل التي ذكرتها السائلة، عند الحاجة إلى أخذ صورة للوجه، وعند إبراز الصورة للتطبيق، إذا دعت الضرورة إلى ذلك؛ فلا حرج في ذلك؛ لأجل الضرورة، نعم. وهكذا إظهار وجهها للخاطب، إذا أراد الخاطب أن ينظر إليها لا بأس أن تكشف وجهها له، حتى ينظر إليها، وينظر إلى وجهها، إلى رأسها، إلى قدمها، إلى يدها لا بأس، النبي ﷺ أذن في هذا، أذن للخاطب أن ينظر، فلا حرج في ذلك؛ لأن هذا من أسباب الوئام بينهما إذا تزوجها بعد النظر، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10351/احتجاب-المراة-عن-الرجال-الاجانب-ومتى-يباح-كشف-الوجه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_442/44203.mp3","categories":["اللباس والزينة"]},{"id":12166,"question":"سؤال قريب من نفس الموضوع، بل هما سؤالان، هل يحق للمرأة التحدث مع أجنبي مثل أقاربها من غير المحارم، أو أقارب الزوج وغيرهم في حضور الأهل، أو غيرهم من الناس، وإلقاء السلام عليهم عند المرور من أمامهم، ثم يقلن في السؤال الأخير، عند السلام على النساء، هل يكتفى بإلقاء السلام فقط، أم يجب المصافحة، خاصة إذا كانت امرأة أكرهها، ولا أحب مصافحتها؟","title":"حكم مصافحة المرأة الرجل الأجنبي والتحدث معه","answer":"الجواب:  التحدث مع الرجال للسلام وغير السلام لا بأس به على وجه ليس فيها خضوع، بل بالكلام العادي من غير خضوع، ومن غير جفاء، وكلام سيء، ولكن بكلام وسط ليس فيه خضوع، قال الله تعالى في كتابه العظيم: يَا نِسَاءَ النَّبِيِّ لَسْتُنَّ كَأَحَدٍ مِنَ النِّسَاءِ إِنِ اتَّقَيْتُنَّ فَلا تَخْضَعْنَ بِالْقَوْلِ فَيَطْمَعَ الَّذِي فِي قَلْبِهِ مَرَضٌ [الأحزاب:32] يعني: مرض الشهوة وَقُلْنَ قَوْلًا مَعْرُوفًا [الأحزاب:32]. فأذن سبحانه في القول المعروف، ونهى عن الخضوع في القول، فالمرأة إذا كلمت الرجل كأخي زوجها، أو أبناء عمها، أو جيرانها، أو أزواج أخواتها، يكون بالكلام المعروف الطيب الذي ليس فيه خضوع، وليس فيه جفاء وخشونة، تبدأ بالسلام، وترد السلام مع البعد عن أسباب الفتنة، مع الاحتجاب، والبعد عن أسباب الفتنة. أما المصافحة فلا، ليس للمرأة أن تصافح الرجل الذي ليس بمحرم لها، يقول ﷺ: إني لا أصافح النساء وتقول عائشة -رضي الله عنها-: والله ما مست يد رسول الله يد امرأة قط ما كان يبايعهن إلا بالكلام هكذا قالت عائشة، رضي الله عنها. فدل ذلك على أن الرجل لا يصافح المرأة، والمرأة لا تصافح الرجل، إذا كان ليس من محارمها، أما محرمها كأخيها وعمها وخالها؛ فلا بأس، أو مع النساء؛ لا بأس أن تصافح النساء. فالواجب على المؤمن والمؤمنة تقوى الله في كل شيء والحذر مما حرم الله من جميع الوجوه، لا من الكلام، ولا من غير الكلام، فالمؤمن يتقد بالشريعة في قوله وفعله، والمؤمنة كذلك، تتقيد بالشريعة في قولها وفعلها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10352/حكم-مصافحة-المراة-الرجل-الاجنبي-والتحدث-معه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_442/44204.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":12179,"question":"يسأل ويقول: عند كثير من النساء عادة، وهي إذا جاء قريب لأبيها، أو قريب لأمها وهو لم يكن محرمًا، تقوم بمصافحته باليد، بدون حاجز، أو بدون أن يكون هناك على اليد شيء، هل هذا جائز؟","title":"حكم مصافحة المرأة للرجل الأجنبي","answer":"الجواب:  لا تجوز مصافحة الرجال من النساء إذا كانوا غير محارم، الواجب أن...  الواجب أن تمتنع من هذا، أما السلام بالكلام فلا بأس، تسلم بالكلام، مشروع السلام بالكلام، أما بالمصافحة فلا، يقول النبي ﷺ: إني لا أصافح النساء وتقول عائشة -رضي الله عنها-: والله ما مست يد رسول الله يد امرأة قط، ما كان يبايعهن إلا بالكلام. فكان -عليه الصلاة والسلام- ما كان يصافح النساء غير المحارم، أما المحرم فلا بأس يصافح أخته عمته أمه لا بأس، أما ابن عمه أو ابن عم أمه أو ابن خاله يعني: ابن خالها، أو ابن عم أمها لا تصافحه، ابن عم أمها، أو ابن خال أمها، أو جارهم لا، ولو كان قريبًا لأمها إذا كان ليس بمحرم، أو قريبًا لأبيها، إنما تسلم عليه بكلام، حياك الله، وعليكم السلام، كيف حالك يا فلان؟ كيف أولادك؟ كيف أهلك؟ طيب؟ أما المصافحة فلا، ولو من دون حائل، لا تصافح أبدًا، ولو من دون حائل، المصافحة لا تجوز مع الرجال الأجناب، إنما تصافح محرمها كأخيها وزوجها وعمها وأبيها ونحو ذلك، أو النساء، تصافح النساء لا بأس، أما أن تصافح رجل أجنبيًا كأخي زوجها، أو عم زوجها، أو زوج أختها، أو جاء أحد جيرانها، كل هذا لا يجوز، وفيه فتنة وشر، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10365/حكم-مصافحة-المراة-للرجل-الاجنبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_443/44306.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":12183,"question":"تسأل سؤالًا آخر وتقول فيه: هل يجوز استعمال الميش، وهو عبارة عن مادة كيماوية توضع على الشعر، فيصبح الشعر ذا لونين، يعطي نوعًا من الجمال للشعر، وهذه المادة لا تزول إلا مع مرور الزمن، أو قص الشعر، ولا يزول بأي مادة منظفة، طبعًا يعمل ذلك للزوج، وليس للتبرج أمام الناس؟","title":"حكم صبغ المرأة شعرها بالميش","answer":"الجواب:  لا نعلم مانعًا من ذلك إذا كان لا يصبغ سوادًا، أما إذا كان يصبغ سوادًا؛ فلا يجوز؛ لأن النبي  قال: غيروا هذا الشيب، وجنبوه السواد فإذا كان هذا الميش يصبغ حمرة، أو صفرة؛ فلا حرج في ذلك، إذا كان طاهرًا ليس فيه نجاسة، وليس من المخدرات، ولا المسكرات؛ فلا بأس في ذلك، إذا كان شيئًا طيبًا طهورًا، لا حرج فيه، ولا محظور فيه، ولا نجاسة فيه؛ فلا بأس. المقدم: ماذا عن الغسل سماحة الشيخ، إذا كان هذا الدهان يبقى إلى الأبد على الشعر .... ؟ الشيخ: هذا مثل المشاط لا يمنع. المقدم: مثل. الشيخ: مثلما يقع في الرأس من المشط، والمشاط والحناء ونحو ذلك، لا يمنع المسح، نعم. المقدم: لا يمنع. الشيخ: ما يوضع على الرأس من ما تحتاجه المرأة من زينة الرأس من حناء أو حاجة أخرى في الرأس وقت فتل الشعر وظفره؛ لا حرج فيه، لا يمنع، كان نساء النبي ﷺ، يمسحن على ما يفعلن في رؤوسهن من أنواع المشاط، نعم. المقدم: لكنه يمنع الماء إلى الشعر الأصلي؟ الشيخ: المقصود مسح الرأس فقط، ما هو المقصود أصول الشعر، المقصود المسح، مسح ظاهر الرأس. المقدم: الشعر نفسه. الشيخ: ظاهر الرأس. المقدم: ظاهر الرأس. الشيخ: وإذا كان عليه شيء مما يحتاجه النساء؛ فلا يمنع، لا يضر. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10369/حكم-صبغ-المراة-شعرها-بالميش","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_443/44310.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":12184,"question":"تسأل في أحد أسئلتها وتقول: هل في لبس المرأة للذهب على شكل أساور أو دائرة مغلقة حرمة، أم أن جميع أشكال الذهب حلال لبسه بالنسبة للمرأة؟","title":"هل يجوز لبس المرأة للذهب على شكل أساور؟","answer":"الجواب:  جميع أنواع الحلي جائزة للمرأة من الذهب والفضة ولو كانت محلقة، ولو كانت أسورة، ولو كانت قلائد، المقصود جميع أنواع الحلي محلقة، وغير محلقة، كالخاتم والسوار والقلادة في العنق ونحو ذلك كله حلال، قد حكى غير واحد من أهل العلم إجماع العلماء على ذلك، وقد ثبت عن النبي ﷺ ما يدل ذلك؛ فلا حرج في ذلك لقوله ﷺ: أحل الذهب والحرير لإناث أمتي، وحرم على ذكورهم قد لبس زوجاته الخواتم من الذهب والفضة، ولا حرج في ذلك، والحمد لله. أما قول من قال من المتأخرين: إن المحلق يحرم هذا قول لا أصل ولا صحة له، بل هو قول مرجوح غير صحيح، بل باطل، الصواب: أن المحلق من الذهب والفضة كل ذلك حلال للنساء، سواء كان أسورة، أو خواتمًا أو غير ذلك، نعم، وما تعلق به بعض الناس من أحاديث وردت في ذلك كلها منسوخة غير صحيحة، بعضها غير صحيح، وبعضها منسوخ، بعضها منسوخ بالأحاديث الصحيحة الدالة على حل الذهب والحرير لإناث الأمة، وبعضها غير صحيح، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/10370/هل-يجوز-لبس-المراة-للذهب-على-شكل-اساور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_443/44311.mp3","categories":["اللباس والزينة"]},{"id":12192,"question":"السائل:ثم يقول: إنه يلاحظ على البعض التقصير الفاحش للثياب؟","title":"صفة ثوب المؤمن","answer":"الجواب:  السنة النصف، نصف الساق إلى الكعب هذه السنة، إزرة المؤمن إلى نصف الساق، وإن نزل إلى الكعب؛ فلا بأس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10378/صفة-ثوب-المومن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_443/44319.mp3","categories":["اللباس والزينة"]},{"id":12213,"question":"نعود مع مطلع هذه الحلقة إلى رسالة وصلت إلى البرنامج من مكة المكرمة بتوقيع إحدى أخواتنا من هناك تقول: أم عبدالله من مكة، أم عبدالله عرضنا سؤالًا لها في حلقة مضت، وفي هذه الحلقة تسأل وتقول: أنا معلمة للصف الأول الابتدائي، وأدرس التلميذات مادة القرآن الكريم من كتاب خاص جمع فيه منهج التوحيد والفقه مع السور المقررة للحفظ، فهل يجوز للطالبات مس السور المكتوبة في ذلك الكتاب قبل تطهرهن؟ وهل يجب علي أن أخرجهن للوضوء كل حصة قبل مس ذلك الكتاب امتثالًا لقوله تعالى: لا يَمَسُّهُ إِلَّا الْمُطَهَّرُونَ [الواقعة:79]؟ وجهوني جزاكم الله خيرًا.","title":"حكم مس كتاب محتوٍ على القرآن دون طهارة","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فهذا الكتاب الذي فيه مقرر التوحيد والفقه وبعض السور التي تقرؤها الطالبات، ليس له حكم المصحف، ولا حرج في مس الطالبات لهذا الكتاب، لأن الآية في المصحف، أما هذا ليس بمصحف، وهكذا كتب التفسير لا بأس أن يمسها المحدث، وهكذا كتب الترجمة، تراجم معاني القرآن؛ لأنها ليست مصاحف، وإن المصحف ما يكون فيه القرآن خاصة، هذا المصحف، أما إذا كان القرآن مجموعًا مع آيات مجموعة، أو سورًا مجموعة مع غيرها، أو القرآن مع التفسير؛ هذا ليس بمصحف، نعم، لا حرج في أن يمسه غير المتطهر، نعم. المقدم: الحمد لله، جزاكم الله خيرًا، إذًا هناك حكمة من جمع أكثر من مقرر مع مقرر القرآن الكريم؟ الشيخ: لا حرج نعم. المقدم: الحمد لله جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10399/حكم-مس-كتاب-محتو-على-القران-دون-طهارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_446/44601.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":12216,"question":"إني المستمعة (ن. م. ع) من العراق محافظة النجف لدي بعض الأسئلة الدينية التي أرجو منكم التفضل بالإجابة عليها، تقول عن نفسها: أنا فتاة محجبة، وأعرف أصول الحجاب، ولكن لدي ابن خالتي وهو أصغر مني بسنة، رضعت من أمه عندما كنت طفلة لمدة خمسة أشهر تقريبًا، وأخته رضعت من أمي أيضًا، فهل يكون لي أخًا بالرضاعة، ويجوز لي ألا أحتجب عنه، وأيضًا لدي ابن عم أمي، وابن عم أبي وهما رجلان بعمر أبي تقريبًا، ومنذ طفولتي، وأنا أناديهم بعمي وخالي، هل علي أن أحتجب عنهما؟","title":"حكم تحجب المرأة من ابن عم أبيها، وأخيها من الرضاعة","answer":"الجواب:  نعم، نعم، عليك أن تحتجبي عن ابن عمك، وابن خالك، ولو كنت عشت معهما طويلًا، عليك أن تحتجبي منهما؛ لأنهما ليسا محرمين. المقدم: هو ابن عم أبيها. الشيخ: ابن عم أبيها، وابن عم أمها ليسا محرمين، وهكذا ابن عمها هي، وابن خالتها خالها كلهم أجناب، أما ابن خالتك التي رضعت من أمه خمسة أشهر؛ فهذا محرم، هذا أخ لك؛ لأنك رضعت من أمه، فهو أخوك، وليس عليك حجاب عنه، بل هو أخوك، قال النبي ﷺ: يحرم من الرضاع ما يحرم من النسب. والمقصود: أن ابن الخالة، أو غير ابن الخالة متى رضع من أمك، أو رضعت من أمه رضاعًا تامًا، خمس رضعات، أو أكثر؛ فإنه يكون أخًا لك من الرضاعة، سواء كان رضع من أمك، أو أنت رضعت من أمه، أو من أخته؛ فإنه يكون محرمًا لكِ إن كان من أمه؛ فهو أخوك، وإن كنت رضعت من أخته؛ فهو خالك؛ لأنك رضعت من أخته؛ فيكون خالًا لك. والحاصل أن الرضاع كالنسب، سواء سواء؛ لقول النبي ﷺ: يحرم من الرضاع ما يحرم من النسب، فليس عليك عنه حجاب، وأما ابن عم أبيك، وابن خال أبيك، وابن خالك، وابن عمك كل هؤلاء إذا كان ما بينك وبينهم رضاع كلهم أجناب؛ فعليك التحجب عنهما. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10402/حكم-تحجب-المراة-من-ابن-عم-ابيها-واخيها-من-الرضاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_446/44604.mp3","categories":["اللباس والزينة"]},{"id":12220,"question":"رسالة وصلت إلى البرنامج من المملكة الأردنية الهاشمية إربد، وباعثتها إحدى الأخوات من هناك، ورمزت إلى اسمها بالحروف (ن. هـ) تقول: هناك أم تجبر بناتها المتزوجات أن يحضرن بالقيام بأعمال منزلها، مع أنها قادرة على العمل، فإذا ما قصرت واحدة أخذت تسبها وتتهمها بأنها مقصرة في حقوقها، وتعلن غضبها عليها، فهل لها الحق في ذلك؟ وهل رفض طلبها يدخل في باب العقوق؟ نرجو الإفادة جزاكم الله خيرًا.","title":"هل رفض مساعدة الأم من العقوق؟","answer":"الجواب:  هذا فيه تفصيل إن كان الزوج لا يرضى؛ فلا حق لها في ذلك، وحق الزوج في هذا مقدم، وليس لهن أن يعصين الزوج، ويأتين إلى أمهن لهذا العمل، أما إن كن قد سمح لهن الزوج بذلك، وهي محتاجة إلى إصلاح شؤون بيتها؛ فينبغي لهن أن يجبن إليها، وكل واحدة تقوم بقسط من ذلك، هذا على فلانة، هذا اليوم على فلانة، وهذا اليوم على فلانة؛ من باب التعاون مع والدتهن، ومن باب جبر الخاطر، ومن باب البر والإحسان، وعدم القطيعة والعقوق؛ فالوالدة لها حق عظيم، يقول النبي ﷺ لما سأله السائل: من أبر؟ قال:: أمك قال: ثم من؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من؟ قال: أباك ثم الأقرب فالأقرب وفي اللفظ الآخر قال: يا رسول الله! من أحق الناس بحسن صحبتي؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من؟ قال: أبوك. فالمشروع لهن أن يجتهدن في إرضائها، وقضاء حاجتها إذا سمح الزوج، ويجعلن ذلك نوبًا كل واحدة تقوم بقسط، يقتسمن الزمان، كل واحدة يكون لها يوم، أو يكون لها ليلة في حاجات والدتهن، ولهن في هذا أجر عظيم، وخير كثير، مع إرضاء والدتهن، وسماح خاطرها، ورضاها عليهن، وعدم سبها بها لهن، نسأل الله للجميع الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10407/هل-رفض-مساعدة-الام-من-العقوق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_446/44608.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":12233,"question":"المستمع (م. أ. م) مصري يعمل في الرياض بعث برسالة ضمنها جمعًا من الأسئلة في أحدها يقول: ذهبت إلى بلد أجنبي في مهمة، وفي غفلة من أمري، اشتريت فراءً تلبسه النساء المتبرجات، وذلك بغرض الاتجار به، وعند عودتي لبلدي فطنت لحرمة ذلك، فتوقفت عن التصرف فيه، وما زال عندي حتى الآن، كيف التصرف بما يرضي الله؟ أفادكم الله.","title":"حكم من اشترى شيئاً لا يلبسه إلا المتبرجات ويريد بيعه","answer":"الجواب:  إذا كان هذا الفرو لا يلبسه إلا المتبرجات؛ فليس لك أن تعينهن على المعصية، ولكن تنظر في أمره بطريقة سليمة، إما ببيعه على من لا يستعمله في المعصية، أو تغيير حاله من حال إلى حال؛ حتى لا يكون على الطريقة التي يلبسها من يتبرج بذلك. المقصود: عليك أن تحاول أن يكون بيعك لها على حالة ليس فيها معصية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10421/حكم-من-اشترى-شيىا-لا-يلبسه-الا-المتبرجات-ويريد-بيعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_447/44709.mp3","categories":["اللباس والزينة"]},{"id":12251,"question":"تسأل أختنا وتقول: زوج أختي من أمي، هل هو محرم لوالدتي، أو لا؟","title":"محرمية زوج البنت لأم زوجته","answer":"الجواب:  نعم، زوج أختك محرم لوالدتك؛ لأنه زوج بنتها، فزوج أختك من أمك هو محرم لأمك؛ لأنها أمكما جميعًا، لكن زوج أختك من أبيك ليس محرمًا لأمك، إذا كانت أختك من أبيك، لأنها زوجة أبيها، وليست أمًا لها، أما أختك من أمك فهو محرم لأمها، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10451/محرمية-زوج-البنت-لام-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_449/44902.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":12252,"question":"هل يجوز الكشف على عم والدي، وخال والدتي، وجدها؟ أرشدونا، جزاكم الله خيرًا.","title":"محرمية عم الوالدين وخالهما وجدهما","answer":"الجواب:  نعم، محرم، الخال، والعم لك ولأمك ولأبيك، عم أبيك عم لك، وعم جدك عم لك، وخال أمك، خال لك، وخال أبيك خال لك، وإن علا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10452/محرمية-عم-الوالدين-وخالهما-وجدهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_449/44903.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":12273,"question":"أيضًا يقول في سؤال آخر: لي بنات خالة، وبنات عم، فهل يجوز لي أن أصافحهن عند السلام؟ وهل يصح أن يكشفن شعرهن بحضوري؟ وهل أكون محرمًا لهن؟ أرجو الإفادة جزاكم الله خيرًا.","title":"حكم مصافحة بنات الخال والخالة والعم والعمة","answer":"الجواب:  لسن محارم لك، بنات عمك وبنات خالك، وبنات عمتك، وبنات خالتك، كلهن لسن محارم، كلهن لسن محارم لك، وليس لهن الكشف لك، ولا أن ترى زينتهن من وجه، أو رأس، أو غير ذلك، الله يقول -جل وعلا- في كتابه العظيم في سورة النور: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ أَوْ أَبْنَائِهِنَّ أَوْ أَبْنَاءِ بُعُولَتِهِنَّ أَوْ إِخْوَانِهِنَّ أَوْ بَنِي إِخْوَانِهِنَّ أَوْ بَنِي أَخَوَاتِهِنَّ أَوْ نِسَائِهِنَّ أَوْ مَا مَلَكَتْ أَيْمَانُهُنَّ [النور:31] ولست من هؤلاء، ويقول -جل وعلا- في سورة الأحزاب: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍٍ [الأحزاب:53]. فالواجب على هؤلاء التحجب عنك، والتستر، والواجب عليك أيضًا أن تمتنع من مصافحتهن، والنظر إليهن، عليهن أن يحتجبن، وعليك أن تغض بصرك لو تساهلن، وليس لك أن تصافحهن، يقول النبي ﷺ: إني لا أصافح النساء يعني: غير المحارم، لكن تسلم عليهن بالكلام، من دون مصافحة، ومن دون تقبيل، وترد عليهن السلام كذلك، أما كشفهن لك؛ هذا منكر، وهكذا المصافحة، لا تجوز لمسلم أن يصافح امرأة ليست محرمًا له، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10473/حكم-مصافحة-بنات-الخال-والخالة-والعم-والعمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_450/45010.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":12279,"question":"من المملكة الأردنية الهاشمية رسالة بعث بها المستمع (ر. ن. ف) يقول: في رمضان الماضي نويت أداء العمرة فسافرت عن طريق البحر، وعند ركوب الباخرة تعطلت ثمانية أيام، وقبل المكان الذي يحرم منه الناس قمت بالإحرام، وكان معي اثنان من زملائي، وبعد نصف ساعة من الإحرام قالوا: إن الباخرة تعطلت مرةً ثانية، فتحللنا من الإحرام خوفًا من أن تتسخ، ونحن لا نعرف شيئًا عن صحة ذلك من عدمه؛ لأنها المرة الأولى التي أعتمر فيها، لكن أحد الإخوان في الرحلة قال: إن هذا لا يصح وأن علينا فدية، ولم يكن معي مال لأشتري فدية، فهل صحيح أن علينا فدية، أم لا؟ وإذا كان علينا فدية لكل منا فأين نفدي وكيف؟ نرجو الإفادة، جزاكم الله خيرًا.","title":"حكم من ارتكب محظوراً من محظورات الإحرام","answer":"الجواب:  الواجب في مثل هذا الصبر، وأن تبقيا على إحرامكما حتى تؤديا العمرة، وإذا كنتما خلعتما ملابس الإحرام، ثم أعدتما ملابس الإحرام لما سارت الباخرة، وأديتم العمرة؛ فليس عليكما شيء؛ لأن خلعكما الملابس، ولبس المخيط صدر عن جهل؛ فيعفى عنكما إذا كنتما أديتما العمرة، ولم تتركاها.  أما إذا كنتما لم تؤديا العمرة، واستمررتم في التحلل فإن عليكما أن تحرما وتتوجها إلى مكة لأداء العمرة التي أحرمتم بها سابقاً ويكفي ذلك والحمد لله، ولا شيء عليكما بسبب الجهل، إلا إذا كنتما جامعتما زوجاتكما؛ فعليكما شاة؛ لأنها تفسد العمرة بالجماع قبل الطواف والسعي تفسد العمرة بالجماع؛ فعليكما شاة تذبح في مكة للفقراء، وعليكما أن تكملا العمرة بالطواف والسعي والتقصير، وعليكما أن تأتيا بعمرة أخرى بدلًا من العمرة الفاسدة؛ لأن الجماع يفسد العمرة، فتكملا العمرة التي أحرمتما بها، وتفديا وعليكما عمرة أخرى بدل تلك العمرة التي أفسدتموها بالجماع. أما لبس المخيط، والطيب الذي فعلتما هذا لا شيء فيه لأجل الجهل، فعليكما أن تتأملا ما وقع منكما، وتسألا أهل العلم عن أمركما، وأنتما على خير -إن شاء الله- والتوبة تجب ما قبلها، وليس للعبد أن يسكت على جهل، بل عندكم -والحمد لله- العلماء عندكم أنصار السنة وعندكم لجنة الفتوى في الأزهر، وعندكم المفتي، تسألون عما أشكل عليكم، والحمد لله، وقد أوضحنا لكم بعض ما يجب، وإذا خفي عليكما شيء من ذلك فراجعا من لديكما من أهل العلم والبصيرة في هذا الباب، نسأل الله للجميع الهداية والتوفيق. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10479/حكم-من-ارتكب-محظورا-من-محظورات-الاحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_451/45104.mp3","categories":["اللباس والزينة","محظورات الإحرام","قضايا المرأة"]},{"id":12282,"question":"تقول في سؤال آخر: امرأة مصابة بحالة نفسية، وفي حالة حملها تضرب أولادها وتصيح، وتترك البيت وتهيم على وجهها وتكشف عورتها أمام الناس، المهم أنها حالة من الجنون، تزيد بها عند الحمل، وهذه المرأة لديها أكثر من ستة من الأولاد والبنات، وعندما رأيت حالتها بهذا الشكل؛ أشرت على زوجها أن تعمل أي وسيلة لمنع الحمل، وفعلًا بعد أن وضعت آخر مولود لها عملت لها عملية بحيث لا تحمل بعد ذلك، وأنا صنعت هذا العمل إشفاقًا بها، وبأطفالها، فهل علي ذنب في ذلك؟ وكيف أكفر عنه إذا كنت مذنبة؟","title":"حكم إجراء عملية لمنع الحمل لامرأة مصابة بمرض الجنون","answer":"الجواب:  إذا كان الواقع هو ما ذكرت في السؤال؛ فقد أحسنت، ولا حرج في ذلك؛ لأن هذه مصيبة عظيمة، فعلاجها بترك الحمل أمر مهم إذا لم يكن هناك علاج آخر، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10482/حكم-اجراء-عملية-لمنع-الحمل-لامراة-مصابة-بمرض-الجنون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_452/45202.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":12287,"question":"هل مصافحة الفتاة لأحد أقاربها مثل ابن عمها، أو ابن خالها، أو ابن عم أبيها، أو ابن عم أمها، أو خطيبها، هل يعتبر ذلك محرمًا؟","title":"حكم مصافحة المرأة لابن عمها وخالها وخطيبها","answer":"الجواب:  نعم لا يجوز للمرأة أن تصافح غير محارمها، وغير النساء، يقول النبي ﷺ: إني لا أصافح النساء وقالت عائشة -رضي الله عنها-: والله ما مست يد رسول الله يد امرأة قط -يعني: غير محارمه- ما كان يبايعهن إلا بالكلام، فليس للمرأة أن تصافح ابن عمها، ولا خطيبها قبل العقد، و ليس لها أن تصافح ابن خالها، ولا ابن خالتها، ولا أحد جيرانها، ولا أخا زوجها، ولا زوج أختها، ليس لها ذلك؛ لأنهم ليسوا محارم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10487/حكم-مصافحة-المراة-لابن-عمها-وخالها-وخطيبها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_452/45207.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":12301,"question":"هل يجوز للمرأة أن تقص شعرها، أم لا؟","title":"حكم قص المرأة شعر رأسها","answer":"الجواب:  إذا كان فيه مصلحة، وإذا كان لها زوج، ورضي الزوج بذلك؛ فلا بأس، وإلا فالأولى تركه؛ لأنه جمال، وقد ثبت أن أزواج النبي ﷺ قصصن شعورهن بعد وفاته؛ لما فيه من الكلفة في مشطه، والعناية به، فإذا كان فيه مشقة، وقصت بعض رأسها للتخفيف، وكان الزوج راضيًا إن كان لها زوج؛ فلا بأس بذلك، أما تركه فهو أفضل؛ لما فيه من الجمال والزينة للمرأة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10501/حكم-قص-المراة-شعر-راسها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_453/45307.mp3","categories":["اللباس والزينة"]},{"id":12307,"question":"إحدى الأخوات المستمعات من جدة تقول: إنها سيدة من جمهورية مصر العربية، ومقيمة في جدة، ولها بعض الأسئلة، وتثني كثيرًا على البرنامج، من أسئلتها سماحة الشيخ تقول: ما الحكمة من عدم تغطية المرأة وجهها وهي محرمة؟ وهل ينطبق ذلك أيضًا على الحج؟ علمًا بأنه في هذا الزمان لا تستطيع المرأة أن تكشف وجهها لكثرة الأجانب، وجهونا حول هذا جزاكم الله خيرًا.","title":"الحكمة من عدم انتقاب المرأة حال إحرامها","answer":"الجواب:  الله سبحانه حكيم عليم -جل وعلا- فيما يشرع لعباده، فقد شرع للرجل إذا أحرم ألا يغطي رأسه، وأن يلبس إزارًا ورداءً، لا قميصًا ولا عمامة، وهو الحكيم العليم -جل وعلا- فالمحرم الرجل يلبس الإزار والرداء، ولا يلبس السراويل ولا القميص ولا العمامة، وله أن يغطي يده بغير الرداء إذا دعت الحاجة، يغطي بدنه باللحاف في البرد لا بأس، لكن لا يغطي رأسه، ولا يلبس القميص إلا إذا اضطر لذلك لمرض، فإنه يغطي رأسه ويفدي الفدية الشرعية: وهي صيام ثلاثة أيام، أو إطعام ستة مساكين، أو ذبح شاة.  فالمقصود: أن الله هو الحكيم العليم فيما يشرعه لعباده، فكما شرع للرجل أن لا يغطي رأسه، وألا يلبس القميص والسراويل، هكذا المرأة شرع لها ألا تنتقب، والنقاب هو ما يخاط على قدر الوجه، ويكون فيه خرقان للعينين نقبان، وشرع لها ألا تلبس القفازين، وهما غشاءان لليدين دسان لليدين، ولكن لها أن تغطي وجهها بغير النقاب، وتغطي يديها بغير القفازين، كما أن الرجل لا يلبس القميص، ولا يلبس السراويل، ويغطي بدنه بالإزار والرداء؛ فهي كذلك لا تغطي وجهها بالنقاب، ولا تغطي يديها بالقفازين، ولكن تغطي ذلك بالخمار ترخيه على وجهها، وتغطي يديها بعباءتها أو بجلالها لا بأس، قالت عائشة -رضي الله عنها-: \"كنا مع النبي ﷺ في حجة الوداع، فكنا نكشف وجوهنا، فإذا دنا منا الرجال؛ سدلت إحدانا خمارها من ... فوق رأسها على وجهها، فإذا جاوزونا؛ كشفنا\".  فدل على أنهن كن يسترن وجوههن عند الرجال، لكن بغير النقاب، وبغير القفازين، هذه الحكمة -والله أعلم- التي شرع من أجلها ألا يغطي الرجل رأسه، وأن لا يغطي بدنه بالقميص والسراويل، هي الحكمة التي شرع للمرأة فيها ألا تغطي وجهها بالنقاب، ولا يديها بالقفازين، هذا شعار للمحرم، يشعر به المحرم أنه محرم، ويتذكر به يوم القيامة حين يقوم الناس لرب العالمين، حفاة عراة غرلًا، هو شعار خاص بالمحرمين، لله فيه الحكمة، فكما أن الرجل لا يغطي رأسه مطلقًا، ولا يغطي بدنه بالقميص والسراويل، فالمرأة كذلك تغطي رأسها؛ لأنها عورة، ولكن لا تغطي وجهها بالنقاب، ولا تغطي يديها بالقفازين، ولها أن تغطي وجهها بالخمار، ويديها بغير القفازين، والله -جل وعلا- أعلم... المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10507/الحكمة-من-عدم-انتقاب-المراة-حال-احرامها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_453/45313.mp3","categories":["اللباس والزينة","محظورات الإحرام","قضايا المرأة"]},{"id":12323,"question":"إذا كانت أختها متزوجة، فهل لها أن تبيت عند أختها؟","title":"حكم مبيت الأخت في بيت أختها المتزوجة","answer":"الجواب:  إذا كانت ما تخشى من زوجها، ما تخشى فتنة؛ فلا حرج، إذا كان ما تخشى فتنة، أما إذا كان تخشى تبتعد، إلا أن يكون معها غيرها كأمها، أو أخت ثانية، أو خادمة، أو شيء حتى يبتعد الخطر، وأما إذا كان ما تخشى؛ فالحمد لله. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10531/حكم-مبيت-الاخت-في-بيت-اختها-المتزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_398/39817.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":12340,"question":"هل يصح إزالة الشعر من الوجه بأي مادة ما عدا الحاجبين؟","title":"حكم إزالة شعر الوجه للمرأة","answer":"الجواب:  إذا كان فيه مثلة كاللحية والشارب، أو الشعر الكثير الذي يعد مشوهًا للخلقة؛ فلا بأس بإزالته، أما الشيء العادي فيترك؛ لأن بعض أهل العلم يرى أن شعر الوجه كله داخل في النمص، إلا إذا كان خلاف المعتاد كاللحية والشارب والشعر الكثيف، هذا لا بأس بإزالته، أما الحاجبان فلا يزالان، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10550/حكم-ازالة-شعر-الوجه-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_399/39909.mp3","categories":["اللباس والزينة"]},{"id":12524,"question":"تسأل أختنا: هل يجوز لبس القفاز في السعي؟","title":"حكم لبس المرأة للقفازين حال السعي","answer":"الجواب:  لا بأس بلبس القفاز في السعي وغيره، يعني ..... لبست القفازين عند خروجها للأسواق، عند وجود غير محرم، كل هذا طيب، وإن غطت يديها بغير القفازين بجلال، أو بعباءة؛ لا بأس. المقصود: أن القفازين؛ لا بأس بلبسهما في جميع الأوقات، إلا في حق المحرم، إذا كانت محرمة فلا تلبس القفازين، لا في السعي، ولا في الطواف؛ لأن المحرم ممنوع النبي ﷺ قال: لا تلبس القفازين يعني: حال إحرامها بالحج، أو بالعمرة إذا كانت لم تحل. أما إذا كان الإنسان قد حج، قد طاف طواف الإفاضة، وسعى.. إذا كان قد رمى الجمرة، وحلق، أو قصر؛ فقد حل، إذا كان قد طافت ..... قد رمت وقصرت؛ تلبس القفازين، يعني قد حلت ..... من جهة اللباس كالرجل، أما إذا كان لا، ما بعد رمت، أو رمت ولا طافت؛ فإنها لا تلبس القفازين حتى تحل في حال الإحرام بالحج، وفي العمرة كذلك لا تلبس القفازين حتى تطوف وتسعى وتقصر حتى تحل؛ لأنها محرمة، لكن تغطي يديها بغير القفازين، بالعباءة، بالجلال، بغير ذلك. المقصود: أن القفازين مباحان للمرأة إلا في حال الإحرام، ما دامت محرمة؛ لم تحل، لا تلبسهما، نعم.","link":"https://binbaz.org.sa/fatwas/10729/حكم-لبس-المراة-للقفازين-حال-السعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_408/40808.mp3","categories":["اللباس والزينة","محظورات الإحرام","قضايا المرأة"]},{"id":12545,"question":"من القصيم بريدة، رسالة بعثت بها إحدى الأخوات من هناك، تقول: (هـ. م. خ) تسأل وتقول: هل قص الشعر ولبس السحاب، وجدل الشعر جديلة واحدة حرام، أم حلال؟","title":"حكم قص المرأة شعرها للزينة","answer":"الجواب:  قص الشعر للتخفيف لا بأس به، وتركه أفضل؛ لأنه زينة وجمال، وإذا كان لها زوج لا تقص إلا برضاه ومشاورته، قد ثبت أن أزواج النبي ﷺ بعد وفاته جززن رؤوسهن وخففنها؛ لأن لها مؤونة ومشقة، فإذا قصت من رأسها، وخففت منه لأنه طويل؛ فلا بأس، ولكن لا تفعل إذا كان لها زوج إلا برضاه، وإذا جعلته جدائل؛ فهذا أجمل وأحسن؛ لأنه من جمال المرأة أن يكون لها جدائل، ويكون رأسها طويلًا، هذا من الجمال، ولكن الناس في العهد الأخير هذا، صاروا يرغبون في تقصير الرأس، وتخفيفه. والسحاب لا حرج فيه، إذا كانت تصون العورة، المهم صون العورة وضبط العورة، فإذا كان من أمام، أو من خلف لا حرج في ذلك، لكن الأفضل أن يكون من الأمام؛ لأنه أمكن في ضبطه، وإذا كان من الخلف ولكنها قد ضبطته وحفظت عورتها، ولا تسحبه إلا عند الحاجة إلى خلع الملابس؛ فلا بأس بذلك، ولا حرج -إن شاء الله- نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10750/حكم-قص-المراة-شعرها-للزينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_456/45613.mp3","categories":["اللباس والزينة"]},{"id":12546,"question":"جدل الشعر جديلة واحدة؟","title":"حكم جعل المرأة شعرها جديلة واحدة","answer":"الجواب:  لا حرج، تجعله كله خلفها، لا بأس بذلك، وإن جعلته ثلاثًا، قرنان وواحدة ناصية وراء خلف كله حسن -إن شاء الله- القرنان يعني: عن يمين وشمال، والناصية تكون خلفها بين كتفيها، هذا كله حسن، نعم، وإن جمعته كله وجعلته خلفها فلا بأس، الأمر في هذا واسع. نعم. المقدم: الحمد لله، جزاكم الله خيرًا، لا أدري من يشوش على الناس بمثل هذه الأفكار -سماحة الشيخ- ؟ الشيخ: ما أعلم، ما أعلم له أصل، لكن إذا كان في الموت، فلأفضل أن يجعل كله خلف.. يجمع كله خلف ظهرها، كما فعلت أم عطية ببنت النبي ﷺ جمعته، وجعلته خلف ظهرها. المقدم: خلف ظهرها؟ الشيخ: نعم.  المقدم: في جديلة واحدة؟ الشيخ: جديلة واحدة، أما في الحياة تفعل ما هو أجمل، الذي تراه أجمل في أهل بلدها، إذا كان أهل بلدها يجعلون جدائل، جعلته جدائل، وإن كانوا يجعلونه خلف ظهورهم؛ فلا بأس، وإن كانوا يجعلونه ثلاثًا ثنتين عن يمين وشمال، وواحدة خلف الظهر فلا بأس؛ لأن المقصود التجمل، فإذا كان أهل بلدها لهم عادة وطريقة في التجمل بهذا الرأس، تفعل مثل أهل بلدها، ولا حرج في ذلك، الأمر في هذا واسع. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10751/حكم-جعل-المراة-شعرها-جديلة-واحدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_456/45614.mp3","categories":["اللباس والزينة"]},{"id":12597,"question":"المستمعة أم موسى من القصيم تقول في رسالة بعثت بها: عندما كنت طفلة صغيرة وضعت على يدي بعض الوشم دون أن أعرف حكمه، وكما تعرفون فإن الوشم لا يمكن إزالته، فهل هو حلال، أم حرام؟ وإذا كان حرامًا هل علي كفارة؟ وما هي؟ نرجو الإفادة، أفادكم الله.","title":"حكم من وشمت قبل البلوغ","answer":"الجواب:  الوشم لا يجوز، الرسول ﷺ: لعن الواشمة، والمستوشمة والوشم كون الإنسان يغرز الإبرة، أو المخيط ونحوه في يده، أو في وجهه، فإذا خرج الدم؛ جعل فيه شيئًا من النيل، أو غيره من الأشياء التي تبقي نقطًا في الوجه، أو في اليد، مخالفة لصفة الوجه أو اليد، هذا الوشم، تغيير لخلق الله؛ فلا يجوز، وما دمت فعلت في حال الطفولة، وقبل البلوغ؛ فليس عليك شيء ؛ لقول النبي ﷺ: رفع القلم عن ثلاثة: عن النائم حتى يستيقظ، وعن الصغير حتى يبلغ، وعن المجنون حتى يفيق وإذا تيسر زوال الوشم بدون مضرة؛ وجبت إزالته، وإلا فلا شيء عليك، والحمد لله.","link":"https://binbaz.org.sa/fatwas/10800/حكم-من-وشمت-قبل-البلوغ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_413/41303.mp3","categories":["اللباس والزينة"]},{"id":12676,"question":"هل تغيير الشيب بغير السواد واجب؟","title":"حكم تغيير الشيب","answer":"الجواب: سنة، تغييره بغير السواد سنة، النبي -عليه الصلاة والسلام- قال: غيروا هذا الشيب، واجتنبوا السواد وقال: إن اليهود والنصارى لا يصبغون؛ فخالفوهم وقد رئي فيه ﷺ في شيبه البياض، والصحابة كذلك، دل على أنه قد يتأخرون عن الصبغ لبعض الوقت. فالمقصود أنه سنة مؤكدة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10886/حكم-تغيير-الشيب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_417/41705.mp3","categories":["اللباس والزينة"]},{"id":12678,"question":"ما حكم اللباس القصير للفتيات الصغيرات اللائي لم تتجاوز أعمارهن الثامنة؟","title":"حكم الملابس القصيرة للفتيات دون الثامنة","answer":"الجواب:  ينبغي أن يعودن على اللباس الكامل الجيد، وإلا فلا يضر إذا كان لباسهن تحت الركبة، وفوق القدم، لا بأس، لكن ينبغي أن يعودن في اللباس الساتر؛ لأنهن إذا كن بنات سبع، وبنات ثمان قد يفتن، قد يكون ... جيدًا.  المقصود: أنه ينبغي لأمهاتهن والقائمين عليهن أن يعودوهن اللباس الكامل الجيد، والتستر حتى يعشن على هذا، ويعتدن على الستر، ولا بأس أن تكون ملابسهن فوق الكعبين، ولا سيما عند الحاجة إلى ذلك، لكن الاعتياد كونها ساترة حتى تتمرن عليه الفتاة، وتعتاده الفتاة، هذا هو الأولى والأحرى والأحوط. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10888/حكم-الملابس-القصيرة-للفتيات-دون-الثامنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_417/41707.mp3","categories":["اللباس والزينة"]},{"id":12689,"question":"هل يجوز استخدام لفافات الشعر لتنعيمه وسهولة تسريحه، أم أن هذا يعتبر من تغيير لخلق الله، وهل يجوز أن تستخدم المرأة دواءً لتنعيم شعرها أم لا؟ جزاكم الله خيرًا.","title":"حكم استخدام ما يجعل الشعر ناعماً","answer":"الجواب:  لا نعلم في هذا بأسًا إذا كان يعين على إصلاحه وإنعامه فلا بأس في ذلك، سواءً كان من ... بعض الأحيان أو غسله ببعض الأدوية أو ما أشبه ذلك إذا كان شيئًا لا يسبب شرًا فلا بأس، أما إذا كان قد يضر وقد يسبب سقوط الشعر فالواجب تركه، أما إذا كان يحسنه ويزينه ولا يضره فالحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10899/حكم-استخدام-ما-يجعل-الشعر-ناعما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_417/41717.mp3","categories":["اللباس والزينة"]},{"id":12715,"question":"رسالة بعث بها المستمع: يحيى عبدالله البصلي من اليمن، يقول في أحد أسئلته ما هو قولكم -حفظكم الله- في بعض نساء هذا الزمان اللائي يعملن بأنفسهن من كشف شعر الرأس، وتقصير الثياب إلى عند الركبة، وغير ذلك؟ وهل من نظر إليهن يكون مرتكبًا للآثام؟ وما هي نصيحتكم للنساء المسلمات في مشارق الأرض ومغاربها؟","title":"تحذير النساء من التبرج والسفور","answer":"الجواب:  وصيتي للمسلمات في كل مكان أن يتقين الله، وأن يلتزمن بالحجاب الشرعي، وأن يسترن رؤوسهن وأبدانهن جميعها، حتى وصيتي لغير المسلمات أن يستترن، وأن لا يفتن الناس، فإن عليهن آثامًا بذلك حتى ولو كن كافرات، عليهن أن يمتنعن من هذا الشيء؛ لأن إبرازهن هذه المفاتن فيه شر عليهن، ومزيد آثام يوم القيامة مع الكفر. فالمؤمنة والمسلمة أولى وأولى بأن تتحفظ، وتستتر لقول الله -جل وعلا- في كتابه العظيم: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ أَوْ أَبْنَائِهِنَّ أَوْ أَبْنَاءِ بُعُولَتِهِنَّ [النور:31] الآية، فإبرازها مفاتنها للناس في الأسواق هذا منكر عظيم، والله يقول سبحانه، يخاطب أمهات المؤمنين: وَقَرْنَ فِي بُيُوتِكُنَّ وَلا تَبَرَّجْنَ تَبَرُّجَ الْجَاهِلِيَّةِ الأُولَى وَأَقِمْنَ الصَّلاةَ وَآتِينَ الزَّكَاةَ وَأَطِعْنَ اللَّهَ وَرَسُولَهُُ [الأحزاب:33] وقال سبحانه: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] فالتستر أطهر لقلوب الجميع، وأبعد عن الشر والفاحشة والفتنة، وقال تعالى: يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْْ جَلابِيبِهِنَّ ذَلِكَ أَدْنَى أَنْ يُعْرَفْنَ فَلا يُؤْذَيْنَ [الأحزاب:59] فكلهن مأمورات بالستر والحجاب، والبعد عن أسباب الفتنة في أي مكان، في الطريق، أو في البيت، أو في المسجد، أو في أي مكان، وفي الطريق أشد فتنة وأعظم. فالواجب على جميع المؤمنات أن يتقين الله في ذلك، ولو كن في بلاد الكفرة في أوروبا أو غيرها، الواجب على جميع المؤمنات أن يتقين الله سبحانه أينما كن، وأن يتسترن سترًا كاملًا؛ حتى الوجه تستره مع الرأس، مع الساقين، مع الأقدام، مع الأيدي حتى لا تكون هناك فتنة بهن، لا من الكفرة، ولا من المسلمين. ولهذا يقول سبحانه: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] فأبان سبحانه أن الحجاب أطهر لقلوب الرجال والنساء، فالطهارة مطلوبة لنساء النبي، ولغيرهن -عليه الصلاة والسلام- ولقوله -جل وعلا- في كتابه العظيم: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ [النور:31] الآية، والوجه من الزينة، والرأس من الزينة، والساق من الزينة. ولم يستثن إلا القواعد العجائز، قال تعالى: وَالْقَوَاعِدُ مِنَ النِّسَاءِ اللَّاتِي لا يَرْجُونَ نِكَاحًا فَلَيْسَ عَلَيْهِنَّ جُنَاحٌ أَنْ يَضَعْنَ ثِيَابَهُنَّ غَيْرَ مُتَبَرِّجَاتٍ بِزِينَةٍ [النور:60] إذا كانت قاعدة العجوز غير متبرجة بالزينة لا ترجو النكاح؛ فلا مانع من إظهار إبراز وجهها أو يديها، لكن تعففها، وتسترها أفضل، حتى ولو كانت عجوزًا، ولهذا قال سبحانه: وَأَنْ يَسْتَعْفِفْنَ خَيْرٌ لَهُنَّ [النور:60] والاستعفاف بالحجاب والبعد عن أسباب الفتنة، ولو كانت عجوزًا لا تشتهي، فكيف بالشابات والمتوسطات، والفتنة بهن عظيمة. فلا يجوز لهن لا في بلادهن، ولا في بلاد الغرب، ولا في بلاد الشرق، ولا في أي مكان أن يبرزن مفاتنهن ومحاسنهن، لا الوجه، ولا الساق، ولا غير ذلك، بل يجب عليهن التستر والحجاب حتى لا يرى منهن شيء طاعة لله وتمسكًا بشرعه، وحذرًا من أسباب الفتنة لهن أو عليهن، لهن أو بهن، هذا هو واجب المسلمات أينما كن. ونصيحتي أيضًا حتى لغير المسلمات أن يتقين الله، وأن يحذرن مزيد الإثم، فإن التبرج يزيدهن إثمًا على إثم، الكفر في الدنيا والآخرة، نسأل الله السلامة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10928/تحذير-النساء-من-التبرج-والسفور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_460/46003.mp3","categories":["اللباس والزينة"]},{"id":12743,"question":"تقول: لم نتعود على غطاء الوجه، فقط نكتفي بغطاء الرأس والجسم، فهل هذا يكفي في الإسلام، وهل الحجاب -وأقصد به غطاء الوجه- نزل لنساء الرسول ﷺ خاصة، أم لكل نساء المسلمين؟","title":"حكم الحجاب للمرأة","answer":"الجواب:  الحجاب للجميع، وإن خوطب به نساء النبي ﷺ فالحكم عام لجميع المسلمين، ليس خاصًا بهن، لقوله : وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] والطهارة مطلوبة لنساء النبي ﷺ ولجميع المؤمنات، والحجاب مطلوب للجميع، لجميع المؤمنين والمؤمنات. فالحجاب مشروع في حق المرأة في زمن النبي وبعده -عليه الصلاة والسلام- لهذه الآية الكريمة، قالت عائشة -رضي الله عنها-: كنا مع النبي ﷺ في حجة الوداع، فكنا إذا دنا منا الرجال؛ سدلت إحدانا خمارها على وجهها، فإذا بعدوا؛ كشفنا. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10957/حكم-الحجاب-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_418/41814.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":12754,"question":"هل يجوز للمرأة أن تسلم على طفل لم يبلغ الثانية عشرة، وتظهر شعرها أمامه؟","title":"حكم مصافحة المرأة لطفل عمره اثنتي عشرة سنة","answer":"الجواب:  الله -جل وعلا- يقول: وَإِذَا بَلَغَ الأَطْفَالُ مِنْكُمُ الْحُلُمَ فَلْيَسْتَأْذِنُوا [النور:59] فدل على أن تحجبها عنهم إذا بلغوا، والبلوغ يكون بخمسة عشر سنة فأكثر، أو بإنبات الشعر الخشن حول الفرج، أو بالاحتلام، بالإنزال عن شهوة في النوم، أو في اليقظة، فإذا كان ابني اثني عشر، أو ثلاثة عشر فهو مقارب، ومراهق، فالتحجب عنه أحوط، وأولى، فلا تكشف الشعر ولا غيره من بدنها، فالتحجب من المراهقين أولى؛ لأنهم من أهل الشهوة والفتنة، فالتحجب عنهم أولى وأحوط. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10968/حكم-مصافحة-المراة-لطفل-عمره-اثنتي-عشرة-سنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_419/41903.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":12757,"question":"إذا نسيت المرأة، وارتدت ثوبًا؛ كان عليه عطر، وقد نسيت ذلك، وخرجت بهذا الثوب، فهل تكون آثمة؟","title":"حكم ارتداء المرأة ثوباً معطراً ولم تعلم","answer":"الجواب:  إذا نسيت ولم تشعر به إلا بعد ذلك؛ ليست آثمة، الله يقول: رَبَّنَا لا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا [البقرة:286] فقال الله: قد فعلت فإذا علمت؛ تزيله، إذا علمت؛ تزيله في المحل الذي تعلم فيه حيث أمكن، فإن لم يمكن؛ فإنها معذورة حينئذٍ حتى تصل إلى بيتها. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10971/حكم-ارتداء-المراة-ثوبا-معطرا-ولم-تعلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_419/41906.mp3","categories":["اللباس والزينة"]},{"id":12783,"question":"بعد هذا رسالة وصلت إلى البرنامج من المستمع السيد إبراهيم الأحمد، يسأل جمعًا من الأسئلة، من بينها سؤال يقول: ما حكم إسبال الملابس لغير الخيلاء؟ جزاكم الله خيرًا.","title":"حكم إسبال الثياب دون قصد الخيلاء","answer":"الجواب:  حكم الإسبال للخيلاء محرم بلا شك عند جميع العلماء إذا كان للخيلاء، لقول النبي ﷺ: من جر ثوبه خيلاء؛ لم ينظر الله إليه يوم القيامة فهو وعيد عظيم، أما إذا كان لغير الخيلاء، بل للعادة، أو تساهل؛ فهذا فسق عند أهل العلم، منهم من يقول: إنه مكروه، ومنهم من يقول: إنه محرم ووسيلة للخيلاء. والصواب أنه محرم، وإن لم يقصد الخيلاء؛ لأنه إسراف وتعريض لملابسه للنجاسة، ولأنه وسيلة للخيلاء، والأحاديث عامة، الأحاديث في النهي عن هذا عامة لقوله ﷺ: ما أسفل من الكعبين من الإزار فهو في النار رواه البخاري في الصحيح هذا عام، وقوله -عليه الصلاة والسلام-: ثلاثة لا يكلمهم الله، ولا ينظر إليهم يوم القيامة، ولا يزكيهم، ولهم عذاب أليم: المسبل إزاره، والمنان فيما أعطى، والمنفق سلعته بالحلف الكاذب رواه مسلم في الصحيح. هذا يفيد الحذر من الإسبال مطلقًا، ولو ما قصد الخيلاء؛ فإن هذا وسيلة للخيلاء، ووسيلة لأن يظن به الخيلاء أيضًا، ووسيلة إلى توسيخ ثيابه، وتنجيسها، ثم فيه نوع من الإسراف والتبذير. فالواجب الحذر من ذلك، وهذا في حق الرجال، أما المرأة فإنها ترخي ثيابها حتى تستر أقدامها؛ لأنها عورة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10997/حكم-اسبال-الثياب-دون-قصد-الخيلاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_420/42010.mp3","categories":["اللباس والزينة"]},{"id":12784,"question":"بعد هذا يسأل سماحتكم فيقول: ما هو الحجاب الشرعي، جزاكم الله خيرًا؟","title":"الحجاب الشرعي للمرأة","answer":"الجواب:  المرأة كلها عورة، فالحجاب الشرعي أن تستر بدنها كله عن الأجنبي، ومن ذلك الوجه واليدان، أما المحرم فلا بأس أن يرى وجهها ويديها ورأسها، لكن إذا احتشمت، ولم ير محرمها إلا الوجه واليدين، كان يكون هذا أحسن وأكمل، أما الأجنبي فالواجب التستر عنه؛ لقول الله : وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] فلم يستثن شيئًا، قال سبحانه: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنْهَا [النور:31] قال ابن مسعود وجماعة: يعني الملابس، ثم قال بعدها: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ [النور:31] والوجه من الزينة واليدان من الزينة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10998/الحجاب-الشرعي-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_420/42011.mp3","categories":["اللباس والزينة"]},{"id":12792,"question":"الأخت (ج. ن. ق) من الرياض بعثت برسالة ضمنتها جمعًا من الأسئلة من بينها سؤال يقول: ما حكم لبس الخاتم في إصبع السبابة أو الوسطى، فقد سمعنا من يقول: إن الرسول ﷺ قد نهى عن ذلك، وما حكم من يكتب ﷺ بحرف واحد، أو بأربعة حروف، وهي (صلعم)؟","title":"حكم التختم في السبابة أو الوسطى، وكتابة (ص) أو (صلعم)","answer":"الجواب:  النبي ﷺ نهى عن التختم في الأصبع الوسطى والسبابة، والظاهر -والله أعلم-: أنه أراد بذلك الرجال، أما النساء فلهن الزينة في كل شيء، الظاهر -والذي يظهر لنا والله أعلم-: أن المراد بذلك الرجال. وأما كتابة ص أو صلعم فلا ينبغي هذا، أقل أحواله الكراهة، بل السنة أن يصلي على النبي يقول: ﷺ يكتبها كاملة، ويكتب الله له بها عشرًا من صلى علي واحدة؛ صلى الله عليه بها عشرًا. فالسنة للمؤمن إذا تكلم أن يقول: ﷺ عند ذكر محمد -عليه الصلاة والسلام- وإذا كتب اسمه يقول عنده: ﷺ في الكتابة، في الكتب والرسائل اللهم صل عليه وسلم. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11006/حكم-التختم-في-السبابة-او-الوسطى-وكتابة-ص-او-صلعم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_461/46112.mp3","categories":["اللباس والزينة"]},{"id":12798,"question":"رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول: سودانية مقيمة بأبو ظبي أم سلمة عبدالرحيم الشريم بركات، الرسالة مكونة من ست صفحات، ملخص ما في هذه الرسالة: أنه نشأ بينها وبين زوجها خلاف على عملها، حيث يرى عدم جواز عملها، وترك البيت، بينما هي محتاجة جدًا إلى العمل لتنفق على بعض أفراد أسرتها وأقاربها، وترجو من سماحة الشيخ التوجيه جزاكم الله خيرًا؟","title":"حكم خروج المرأة للعمل بدون رضا الزوج","answer":"الجواب:  الواجب على الزوجة طاعة زوجها في مثل هذا وترك العمل؛ لأن بقاءها في البيت فيه مصالح كثيرة للزوج والذرية الأولاد، ومصالح أخرى في حفظها وسلامتها من الأخطار، فالواجب طاعة زوجها في هذا، وأن تبقى في بيتها، إلا إذا كانت قد شرطت عليه عند العقد أنها تبقى في عملها من تدريس، أو تمريض، ونحو ذلك، فالمسلمون على شروطهم، إلا أن تسمح هي، وتترك العمل بنفسها، وأما إذا كانت لم تشرط هذا؛ فلا حق لها في العمل إلا بإذنه، والله ولي التوفيق. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11012/حكم-خروج-المراة-للعمل-بدون-رضا-الزوج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_462/46203.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":12811,"question":"الأخوات بدور حجازي، و سمراء السحيباني بعثن برسالة ضمنها عددًا من الأسئلة من بينها سؤال يقول: هل يجوز للمرأة لبس الثوب الأبيض؟","title":"حكم لبس المرأة للثوب الأبيض","answer":"الجواب:  إذا كان على طريقة الرجال ما يجوز؛ لأن الرسول ﷺ لعن المرأة المتشبهة بالرجال، أما إذا كان تفصيله وخياطته وهيئته خاصًا بالنساء؛ فلا بأس، لكن تركه أولى؛ لأن فيه نوع من المشابهة؛ لأن غالب لبس الرجال البيض فكونها تترك ذلك يكون أحوط، وإلا فلا يحرم إذا كان على هيئة تختص بالنساء، مثلما تلبس الأسود والأخضر وإن كان يلبسه الرجال، لكن إذا كان الأسود والأخضر والأصفر على هيئة تختص بالنساء.  وهكذا الرجل يلبس الأسود والأحمر على الهيئة التي تخص الرجال، فالأبيض مثل ذلك؛ لأن الملابس مشتركة بين الرجال والنساء، لكن يجب أن تكون ملابس الرجال تختص بهم، وأن تكون ملابس النساء تختص بهن، ولا يجوز للرجال التشبه بالنساء، ولا النساء التشبه بالرجال. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11025/حكم-لبس-المراة-للثوب-الابيض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_462/46216.mp3","categories":["اللباس والزينة"]},{"id":12850,"question":"تقول: بعض الناس -هداهم الله- يُلبسون بناتهم الصغار ملابس قصيرةً، ويُلبسون الأولاد ملابس طويلةً نوعًا ما، ما نصيحتكم لمثل هؤلاء؟","title":"ضرورة تربية البنات الصغار على الحِشْمة في الملبس وغيره","answer":"الجواب: هذا غلطٌ، وعكس المشروع، هذا عكس المشروع، فالمشروع أن يُلبسوا البنات اللباس الطويل؛ حتى يعتدنه، ويكون سجيةً لهن، وأن يُلبسوا الأولاد اللباس الذي فوق الكعب؛ حتى يعتادوه، هذا هو المشروع. ولا يجوز للمسلم ولا للمسلمة أن يُربي أولاده على خلاف المشروع، فالمؤمن يُربي أولاده على المشروع، والمؤمنة كذلك، فالبنت الصغيرة تُربى على الطويل؛ حتى تعتاده، وتُربى على الستر، وعدم التساهل في الأمور، هذا هو المشروع للجميع. والرجل يُربى على الشرع، على أن تكون ثيابه فوق الكعب، ولا يُربى على الدخان، أو المُسكر، أو العقوق، أو السب، لا، يُزجر عن ذلك؛ حتى لا يعتاد سبَّ والديه، ولا العقوق لهما، ولا التدخين، ولا شرب المُسكر، ولو كان صغيرًا يُربى على الحق؛ حتى يستقيم، ولو بالضرب. وهكذا البنت تُربى على الخير، وعلى الخلق الجميل، وعلى ستر العورة حسب الطاقة بالكلام الطيب، والأسلوب الحسن، ولو بالضرب عند الحاجة إلى ذلك، حتى إذا بلغت، فإذا هي قد استقامت على الخير والهدى والصلاح. الله المستعان، نعم.  المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11065/ضرورة-تربية-البنات-الصغار-على-الحشمة-في-الملبس-وغيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_464/46416.mp3","categories":["اللباس والزينة"]},{"id":12879,"question":"يسأل ويقول: عندما أقوم بزيارة ذوي الأرحام أمتنع عن مصافحة النساء، ويقابل هذا العمل بالسخرية من قبلهم، وأحيانًا يأخذني أخوهن إلى داخل المنزل كي أسلم عليهن غصبًا، وتارةً أخرى يأتين هن أنفسهن، ويسلمن علي بالقوة، وهذا شيء محرم علي في الشرع، وإذا انقطعت عنهم؛ قطعت الرحم، أرجو أن توجهوني كيف أتصرف، جزاكم الله خيرًا؟","title":"حكم مصافحة غير المحارم من النساء","answer":"الجواب: مصافحة النساء لا تجوز إذا كن من غير المحارم، لقول النبي ﷺ: إني لا أصافح النساء وقول عائشة -رضي الله عنها-: والله ما مست يد رسول الله يد امرأة قط، ما كان يبايعهن إلا بالكلام ولأن المصافحة وسيلة إلى الفتنة، قال بعض أهل العلم: إنها أعظم من النظر، وقد نص الله على تحريم النظر، فالمصافحة قد تكون أشد في الفتنة، فلا تجوز، ولو لم يرضين بذلك، عليك أن تمتنع، وأن تخبرهن بالأمر الشرعي، والحمد لله، سواء كن عجائز، أو شابات، تسلم عليهن بالكلام، وتسألهن عن أحوالهن، وتدعو لهن بالخير، أما المصافحة فلا.  وإذا كان حضورك يوجب إلزامهن لك؛ فلا تحضر، تسلم عليهن من بعيد بالتلفون، بالمكاتبة بالوصية توصي، فلان يسلم عليهن، ونحو ذلك، الأمر في هذا واسع والحمد لله، ليس من شرط الصلة أن تحضر، إذا وصلتهن بالدعاء لهن، والتسليم لهن من طريق المكاتبة، أو من طريق الوصية، أو من طريق الهاتف بالتلفون، كله طيب، وإذا كن فقيرات وأرسلت إليهن مساعدة؛ فهذه صلة أيضًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11094/حكم-مصافحة-غير-المحارم-من-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_466/46611.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":12923,"question":"تسأل أيضًا سؤالًا آخر وتقول: لدي بعض العطور التي تحتوي على الكحول، وسمعت أن استعمالها حرام، فماذا أفعل بها، هل يجوز أن أستعملها حتى تنتهي، ثم أستعمل غيرها؟","title":"حكم استعمال العطور التي تحتوي على نسبة من الكحول","answer":"الجواب:  العطور التي يثبت أن فيها مسكرًا لا يجوز استعمالها، بل يجب إتلافها، مثل الكالونيا هذه ثبت أن فيها كحولًا، فيها اسبيرت وتسكر، فلا يجوز استعمالها، وإن فعلها بعض الناس لا يجوز استعمالها أبدًا. وأما العطور الأخرى فلا نعلم أن فيها شيئًا، لكن إذا ثبت بشهادة الثقات العارفين بأن فيها ما يسكر كثيره؛ فإنها لا تستعمل ما أسكر كثيره فقليله حرام هكذا قال النبي ﷺ: ما أسكر كثيره فقليله حرام فإذا ثبت بقول الثقات العارفين اثنين فأكثر أنه مسكر يعني: أن كثيره يسكر؛ لم يجز استعماله لا قليله ولا كثيره، فأما إذا كان كثيره لا يسكر فلا بأس باستعماله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11138/حكم-استعمال-العطور-التي-تحتوي-على-نسبة-من-الكحول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_469/46908.mp3","categories":["اللباس والزينة"]},{"id":12968,"question":"تقول هذه السائلة يا سماحة الشيخ: المرأة التي تصطحب زوجها كمحرم لها وهي تعمل -مثلًا- في بلد وهو معها، وغالبًا هو لا يعمل لعدم وجود فرصة له في العمل، هل يكون في ذلك قلب للقوامة، قوامة الرجال على النساء، وهل يجوز ذلك، أم لا؟","title":"حكم سفر المرأة للعمل مع وجود زوج محرماً لها","answer":"الجواب:  لا حرج في ذلك، أن يذهب معها محرم لها، وهي العاملة، وهو لا يعمل، كالعكس لو ذهبت معه، ويعمل هو، وهي ما تعمل، الله أباح العمل للجميع، فإذا تيسر لها عمل كتدريس، أو طب، وهو لم يتيسر له ذلك؛ فلا بأس أن يسافر معها محرم لها، ومعين لها على هذا العمل، والمصلحة لهما جميعًا، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11185/حكم-سفر-المراة-للعمل-مع-وجود-زوج-محرما-لها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_503/50302.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":13013,"question":"المستمعة (ح. ع. م) من المنطقة الشرقية الأحساء قرية الشعبة، بعثت بسؤال طويل تقول فيه: والدتي في الأربعين من عمرها، وقد نبت الشيب في مفرق شعر رأسها، وهي تريد أن تضع فيه صبغة لونها أسود، وقد منعتها من ذلك مستندة في منعي لها لحديث رواه جابر  حيث قال: \"أتي بأبي قحافة والد أبي بكر الصديق  يوم فتح مكة ورأسه ولحيته كالثغامة بياضًا، فقال رسول الله ﷺ: غيروا هذا، واجتنبوا السواد لكن وللأسف لم تستمع ووضعت الصبغة فما حكم الإسلام في ذلك؟ جزاكم الله خيرًا.","title":"حكم صبغ الشيب بالسواد","answer":"الجواب:  قد أحسنت في نصيحتها، قد أحسنت -بارك الله فيك- في نصيحتها للحديث المذكور، وهو حديث صحيح رواه مسلم وغيره، والنبي  قال: اجتنبوا السواد وفي اللفظ الآخر: وجنبوه السواد وجاء في ذلك أحاديث أخرى كلها تدل على النهي عن الصبغ بالسواد. فالواجب أن تنصحي الوالدة كثيرًا حتى لا تصبغ بالسواد، تصبغ بالحناء، أو بالحناء، والكتم بين السواد، والحمرة، وأما الصبغ بالسواد الخالص؛ فلا يجوز لها، ولا لغيرها، الواجب على كل مسلم أن يمتثل أمر الرسول ﷺ وألا يصبغ بالسواد لا لحية، ولا رأسًا؛ لأن الرسول ﷺ قال: غيروا هذا الشيب، واجتنبوا السواد وفي اللفظ الآخر: وجنبوه السواد. فالواجب على الرجال والنساء عدم الصبغ بالسواد، فالرجل لا يصبغ لحيته بالسواد، ولاسيما طلبة العلم، وأهل العلم؛ فإنهم قدوة، فالواجب عليهم ألا يصبغوا بالسواد؛ حتى لا يتأسى بهم غيرهم، وهكذا غيرهم من الرجال والنساء، الواجب عدم الصبغ بالسواد، نعم، للحديث المذكور، وما جاء في معناه من الأحاديث الصحيحة. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11230/حكم-صبغ-الشيب-بالسواد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_471/47109.mp3","categories":["اللباس والزينة"]},{"id":13034,"question":"تسأل أختنا وتقول: ما حكم لباس المرأة الضيق والشفاف والقصير تحت الركبة في المنزل، وعند اجتماعها بالنساء في مكان بعيد عن مخالطة الرجال؟","title":"حكم لبس المرأة الضيق والشفاف والقصير عند مثيلاتها","answer":"الجواب:  لا ينبغي اعتيادها لهذا؛ لأن هذا يجرها إلى التساهل به عند خادم، وعند أخي زوج، وغير ذلك، فينبغي لها أن تكون الملابس ليست ضيقة تبدي حجم عورتها، وحجم أعضائها، تكون متوسطة، لا واسعة، ولا ضيقة بين ذلك، ولا تكون قصيرة ولا شفافة، وإذا بدت منها العورة ما بين السرة والركبة؛ حرم ذلك حتى عند النساء، إذا كانت شفافة يرى ما تحت السرة، أو يرى فخذها، هذا منكر.  فإذا كانت تستر ما بين السرة والركبة عند النساء؛ فلا بأس، لكن لا ينبغي لها اعتياد ذلك؛ لأن هذا يجر إلى التساهل، حتى عند خادم، أو سواق، أو أخي زوج، أو زوج أخت، فينبغي سد الذريعة، ينبغي البعد عن أسباب الفتنة، ينبغي لها أن تعتاد الملابس الجيدة الساترة الوافية البعيدة عن الفتنة، هذه نصيحتي لكل امرأة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11251/حكم-لبس-المراة-الضيق-والشفاف-والقصير-عند-مثيلاتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_472/47214.mp3","categories":["اللباس والزينة"]},{"id":13064,"question":"ننتقل إلى رسالة السائلة (ر. م. هـ) من القصيم تقول: هل قص شعر المرأة من الخلف، أو من الأمام محرم؟نرجو منكم الإفادة.","title":"حكم قص المرأة بعض شعرها","answer":"الجواب:  القص فيه نظر، أما إذا كان الشعر طويلًا، ويكلف المرأة؛ لا بأس أن تأخذ من أطرافه، تخففه، تقص من أطرافه كما ثبت عن أزواج النبي ﷺ أنهن قصصن من أطراف الشعر بسبب كثرته لما مات النبي ﷺ للتخفيف. فإذا كان فيه مشقة، وأخذت من أطرافه للتخفيف؛ فلا بأس، أما أخذ من بعض فيكره ذلك، كأخذ الناصية، أو من أحد الجانبين، أو من القفاء؛ لأن هذا يشبه القزع، والقزع أخذ بعض الرأس، وترك بعضه، كونه يحلق بعضه، ويخلي بعضًا، هذا منهي عنه، فكون المرأة تقص بعضًا، وتخلي بعضًا، ترك هذا أولى وأحوط؛ لأنه يشبه القزع، نعم.","link":"https://binbaz.org.sa/fatwas/11281/حكم-قص-المراة-بعض-شعرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_505/50524.mp3","categories":["اللباس والزينة"]},{"id":13066,"question":"من جمهورية السودان الشقيقة هذه رسالة بعثتها إحدى الأخوات، تقول: سعدية موسى، الأخت سعدية تسأل ثلاثة أسئلة: في أحد أسئلتها تقول: ما هي شروط الحجاب الشرعي؟","title":"ما هي شروط الحجاب الشرعي؟","answer":"الجواب:  شروط الحجاب الشرعي: أن يكون ساترًا لمحاسن المرأة، يستر وجهها وشعرها وبدنها، ليس رقيقًا ترى منه زينتها، بل يكون ساترًا صفيقًا يستر عورتها، يستر بدنها، ويكون ذلك من اللباس الذي ليس فيه محذور، ليس مغصوبًا ولا نجسًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11283/ما-هي-شروط-الحجاب-الشرعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_473/47303.mp3","categories":["اللباس والزينة"]},{"id":13081,"question":"أيضًا يسأل هذا السائل عن الثوب الطويل الذي يكون أسفل الكعبين، ويلبس بدون خيلاء، ما حكمه؟","title":"حكم إسبال الثوب بدون خيلاء","answer":"الجواب:  لا يجوز، هذا من الإسبال، لكن مع الخيلاء يكون الإثم أكثر، مع الخيلاء يكون الإثم أكثر؛ لقول النبي ﷺ: ما أسفل من الكعبين من الإزار فهو في النار رواه البخاري في الصحيح ما أسفل من الكعبين من الإزار فهو في النار وهكذا البشت، وهكذا القميص، وهكذا السراويل كلها واحدة، إذا نزل عن الكعبين؛ فهو لا يجوز في حق الرجل. ويقول ﷺ: ثلاثة لا يكلمهم الله، ولا ينظر إليهم يوم القيامة، ولا يزكيهم، ولهم عذاب أليم: المسبل إزاره، والمنان فيما أعطى، والمنفق سلعته بالحلف الكاذب رواه مسلم في الصحيح من حديث أبي ذر ، فهذا يبين أنه لا فرق بين من أراد التكبر، أو لم يرد التكبر؛ لأن الرسول ﷺ أطلق في هذه الأحاديث. وقال في حديث آخر: من جر ثوبه خيلاء؛ لم ينظر الله إليه يوم القيامة هذا وعيد آخر، وعيد شديد. فالواجب الحذر من الإسبال مطلقًا، ولو لم يرد التكبر، وهذا شيء في قلبه من يعلم ذلك إلا الله -جل وعلا- فالإسبال ممنوع، وهو وسيلة إلى التكبر مع ما في هذا أيضًا من الإسراف، وتعريض الثياب للأوساخ والنجاسات. يروى عن عمر  وهو مطعون  جاءه شاب يعوده، فلما أدبر رأى ثوبه يمس الأرض، فقال له: «يا شاب! ارفع ثوبك، فإنه أتقى لربك، وأنقى لثوبك». المقصود: أنه لا يجوز أن تنزل الملابس عن الكعبين في حق الرجل ولو لم يرد التكبر؛ لأن الأحاديث عامة. أما المرأة فالسنة لها أن تسبل حتى تستر أقدامها عن الرجال، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11298/حكم-اسبال-الثوب-بدون-خيلاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_507/50713.mp3","categories":["اللباس والزينة"]},{"id":13085,"question":"هذه السائلة دلال من اليمن تقول في هذا  ما حكم لبس الخاتم الذي يوجد عليه ثعبان، وهل تجوز الصلاة فيه، وجهونا بذلك؟","title":"حكم لبس الحلي والثياب التي عليها صور","answer":"الجواب:  لا يجوز لبسه، ولا يجوز الصلاة فيه إلا إذا قطع رأسه، رأس الثعبان، يقطع، يحك رأسه؛ حتى يزول الرأس، وإلا فلا يجوز لبسه، سواء كان خاتمًا، أو حلية، مثل الحلق، أو غيره، كثعبان، أو طير، أو حيوان آخر حتى يقطع الرأس، وإلا فالواجب عدم لبسه. لكن الصلاة صحيحة.. الصلاة صحيحة على الصحيح، لكن لا يجوز استعماله ولو في غير الصلاة، مثل: الخاتم الذي فيه صورة ثعبان أو غيره أو حزام، أو قميص، أو غير ذلك، لا يجوز حتى يقطع الرأس، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11302/حكم-لبس-الحلي-والثياب-التي-عليها-صور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_507/50717.mp3","categories":["اللباس والزينة","مسائل متفرقة في الصلاة"]},{"id":13137,"question":"لها سؤال طويل أيضًا لخصته في العبارات التالية: تسأل سماحة الشيخ -لو تكرمتم- عن حكم سن الذهب، والتفليج البسيط للمرأة؟","title":"حكم اتخاذ السن من الذهب وحكم التفليج","answer":"الجواب:  سن الذهب لا بأس به، أما التفليج فلا يجوز، الرسول ﷺ  نهى عن التفليج للحسن، أما إذا كان لإصلاح الضرس لمرض به، أو لتلبيسه الذهب أو لأشياء أخرى من العلاج فلا بأس. أما للتحسن للحسن والزينة هذا لا يجوز، الرسول ﷺ لعن المتفلجات للحسن أما إذا كان حك الضرس، والعمل في إزالة ما فيه من عوج، أو الزيادة، أو تقدم، أو تأخر؛ فلا بأس، ليس هذا من باب التفليج، إنما هو من باب العلاج لما حصل فيه من الخلل، أو لتلبيسه، أو لإزالة ما فيه من الدود والسوس، لا حرج في ذلك. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11390/حكم-اتخاذ-السن-من-الذهب-وحكم-التفليج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_474/47414.mp3","categories":["اللباس والزينة"]},{"id":13155,"question":"السائل (م. م. أ) من الرياض يقول: والدة زوجتي أحيانًا عندما نذهب أنا وزوجتي للسلام عليها في منزلها تسلم علي، وليس على رأسها غطاء، مع أنها امرأة مسلمة، ومحافظة على الصلوات الخمس، ومحافظة على الشريعة الإسلامية، والآداب الإسلامية، فهل إذا خرجت علي في بعض الأحيان، وليس على رأسها غطاء، هل تأثم بذلك؟","title":"حكم كشف المرأة رأسها أمام زوج ابنتها","answer":"الجواب:  الصواب أنها لا تأثم؛ لأنها محرم لك، أم زوجتك، لكن لو غطت رأسها؛ يكون أحوط، وأحسن؛ خروجًا من الخلاف، خروجًا من خلاف من يرى تحريم إبداء الرأس للمحرم، والأظهر في الأدلة الشرعية أنه لا يحرم، كون المحرم يرى رأس أخته من الرضاعة، أو يرى رأس أم زوجته، أو جدة زوجته، الصواب لا حرج في ذلك، لكن إذا غطته احتشامًا وخروجًا من الخلاف؛ يكون حسن، إن شاء الله. المقدم: طيب جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11409/حكم-كشف-المراة-راسها-امام-زوج-ابنتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_510/51015.mp3","categories":["اللباس والزينة"]},{"id":13166,"question":"تقول السائلة في سؤالها الثاني: هل يجوز إزالة الشعر الناتج عن التقاء الحاجبين، خاصة عندما تكون إزالة ذلك تمنع تشوهًا في الوجه؟","title":"حكم إزالة الشعر الذي بين الحاجبين للمرأة","answer":"الجواب:  لا حرج في إزالة ما بين الحاجبين، وإن تركه احتياطًا؛ فحسن، وإلا فليس من الحاجبين، ما بينهما ليس منهما، من تركه احتياطًا؛ فحسن، ومن أزاله فلا أعلم به بأسًا؛ لأنه ليس من الحاجبين. نعم.","link":"https://binbaz.org.sa/fatwas/11421/حكم-ازالة-الشعر-الذي-بين-الحاجبين-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_511/51102.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":13177,"question":"هذا السائل كتب بأسلوبه الخاص يقول: ذهبت لأداء فريضة الحج العام الماضي، وخرجت من الدمام حتى وصلت الميقات، وأحرمت من الميقات، وعندما وصلت إلى بيت الله الحرام؛ خلعت ملابسي أي: ملابس الإحرام، وكنت نويت الحج متمتعًا، ولكنني جهلت هذا الموضوع، فقال لي أحد الزملاء: أنت آثم؛ لأنك لازم تعمل عمرة قبل أن تخلع ملابسك، أو ملابس الإحرام، وسألت بعض الإخوان قالوا لي: تحرم من مسجد التنعيم، وتعمل عمرة، وفعلت ذلك، وأديت فريضة الحج، فهل عملي صحيح يا سماحة الشيخ؟","title":"حكم المتمتع إذا خلع ملابس الإحرام قبل أداء العمرة","answer":"الجواب:  لا حرج عليك، إذا كنت ناسيًا الحمد لله، ليس عليك إن كنت ناسيًا أو جاهلًا لا حرج عليك، وقد أحسنت لما فعلت العمرة، لكن ما يحتاج التنعيم، إذا وقع مثل هذا جهلًا، أو نسيانًا؛ يعيد ملابس الإحرام، ويذهب إلى الكعبة، ويطوف. إذا أحرم الإنسان من الميقات، ثم دخل مكة، ثم خلع ثيابه جاهلًا، خلع ملابس الإحرام جاهلًا، ثم نبه؛ يلبس ملابس الإحرام في محله في بيته الذي هو فيه، ثم يذهب إلى المسجد الحرام، يطوف، ويسعى، ويقصر، ولا حاجة، يروح التنعيم. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11432/حكم-المتمتع-اذا-خلع-ملابس-الاحرام-قبل-اداء-العمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_511/51113.mp3","categories":["اللباس والزينة","محظورات الإحرام","قضايا المرأة"]},{"id":13181,"question":"تقول هذه السائلة أيضًا: سماحة الشيخ! يوجد لدى بعض النساء -هداهن الله- يقمن بلبس العباءة على الكتف، رغم وجود الرجال، أو قرب السكن الذي يتواجد به رجال، أفتونا في ذلك في حكم ارتداء العباءة على الكتف، جزاكم الله خيرًا؟","title":"حكم لبس النساء العباءة على الكتف أمام الرجال الأجانب","answer":"الجواب:  الواجب ارتداؤها على الرأس كعادة النساء، أما ارتداؤها على الكتفين فهذا لا يجوز؛ لأنه تشبه بالرجال، وإيهام أنها رجل، فلا يجوز هذا العمل، بل الواجب عليها أن ترتدي العباءة فوق الرأس، مع التحفظ والتستر. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11436/حكم-لبس-النساء-العباءة-على-الكتف-امام-الرجال-الاجانب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_511/51117.mp3","categories":["اللباس والزينة"]},{"id":13194,"question":"من الزعفرانية في العراق بغداد المستمع: محمود الطلباني بعث يسأل في هذه الحلقة ويقول: نهى رسول الله ﷺ أن يلبس الرجل الثوب المزعفر فما هو الثوب المزعفر؟","title":"حكم لبس الرجل الثوب المزعفر","answer":"الجواب:  المزعفر هو المصبوغ بالزعفران، والزعفران معروف، فلا يجوز للرجل أن يلبسه، وإنما هو من لبس النساء، ونهى المحرم أيضًا أن يلبس شيئًا من الثياب مسه الزعفران، أو الورس ، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11449/حكم-لبس-الرجل-الثوب-المزعفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_476/47603.mp3","categories":["اللباس والزينة"]},{"id":13204,"question":"هذه السائلة (أم خالد . أ. أ) الرياض تقول: لي مجموعة من الأسئلة تقول: بأنني ألبس العدسات الملونة في المنزل رغبة من زوجي للتجمل له، فما حكم لبس العدسات، وجهونا في ضوء ذلك؟","title":"حكم لبس العدسات اللاصقة","answer":"الجواب:  إن كانت تقوي البصر يستفيد منها البصر؛ فلا بأس كالمراية، كالمناظر، أما إن كان لمجرد الزينة؛ فتركها أولى وأحوط، إذا كان لمجرد الزينة؛ فتركها أولى وأحوط، والاكتفاء ببصرها الذي خلق الله لها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11475/حكم-لبس-العدسات-اللاصقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_512/51209.mp3","categories":["اللباس والزينة"]},{"id":13205,"question":"هل في تخريم الآذان بالنسبة للأطفال شيء، وذلك لوضع ما يسمى بالخماخل، هل في ذلك بأس؟","title":"حكم تخريم آذان البنات","answer":"الجواب:  لا حرج في ذلك إذا كان بنات، إذا كن بنات لا بأس لأجل وضع الأقراط فيها، نعم.","link":"https://binbaz.org.sa/fatwas/11477/حكم-تخريم-اذان-البنات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_512/51210.mp3","categories":["اللباس والزينة"]},{"id":13234,"question":"بعد ذلك ننتقل إلى رسالة السائل: محمود العثمان، وثامر العثمان السائلان يقول هذا السائل: شاب يبلغ من العمر التاسعة عشرة من العمر، وظهر الشيب بشكل واضح جدًا في شعره ورأسه، ماذا تنصحونه أن يفعل بهذا، جزاكم الله خيرًا؟","title":"حكم صبغ الشاب شيب رأسه بالسواد","answer":"الجواب:  يصبغه بغير السواد، والحمد لله، يصبغه بالحمرة.. بالسواد .... مع الحمرة، لا يكون خالص السواد، أما بالسواد فلا؛ لأن الرسول ﷺ قال: غيروا هذا الشيب، واجتنبوا السواد ولم يقل: إلا أن يكون في شاب، قال: غيروا هذا الشيب، واجتنبوا السواد فإنهم يغيروه بما أحب، لكن لا بالسواد الخالص، إذا كان سوادًا ما هو بخالص، مخلوط بالحمرة، بين الحمرة والسواد؛ لا بأس، أو الحمرة الكاملة، أو الصفرة الكاملة، لا بأس، أما سواد خالص لا. ولو كان شابًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11516/حكم-صبغ-الشاب-شيب-راسه-بالسواد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_520/52017.mp3","categories":["اللباس والزينة"]},{"id":13266,"question":"تسأل أختنا آخر سؤال في هذه الحلقة، تقول: هل صبغة الشعر والحمرة التي توضع على الشفاه هل هي حلال، أم حرام؟","title":"حكم صبغ الشعر وحكم وضع الحمرة على الشفتين للنساء","answer":"الجواب:  صبغ الشعر مستحب، إذا كان شيبًا يصبغ، لكن بغير السواد، لقول النبي ﷺ: غيروا هذا الشيب واجتنبوا السواد تصبغ بالحمرة، أو بالصفرة، أو بالحناء، مع الكتم يعني: مخلوط سواد مع حمرة، حتى يكون الصبغ بين السواد، وبين الحمرة، أما السواد الخالص فلا يجوز، لا للرجال، ولا للنساء.  وأما الحمرة على الشفة فلا نعلم فيها شيئًا، مثل الديرم كونها تحمر شفتها بالديرم، أو بالبودرة، أو بشيء آخر من باب الجمال بين النساء، أو عند الزوج، مع التستر عن الأجنبي والحجاب، هذا لا بأس به، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11556/حكم-صبغ-الشعر-وحكم-وضع-الحمرة-على-الشفتين-للنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_476/47607.mp3","categories":["اللباس والزينة"]},{"id":13278,"question":"السائل رمز لاسمه بـ (أ. أ. أ) يقول: ما حكم ارتداء الخمار بالنسبة للمرأة المسلمة، وهل كان معروفًا في زمن الرسول ﷺ؟","title":"حكم الخمار للمرأة","answer":"الجواب:  الخمار مشروع بين النساء، وبين المحارم، وواجب إذا كان يراها أجنبي، يجب أن تختمر لتغطي رأسها، ووجهها، ومعروف في عهد الصحابة، وفي عهد النبي ﷺ وما بعده، قال الله تعالى: وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَى جُيُوبِهِنَّ [النور:31]. فالخمار ما يوضع على الرأس، ويستر به الوجه والرأس، ومقدم البدن، وقد يكون طويلًا يستر البدن كله مع الرأس. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11562/حكم-الخمار-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_514/51410.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":13312,"question":"السائلة (ج. أ. أ) تقول في هذا  نحن معلمات نذهب إلى المدرسة مع سائق أجنبي، ونحن مجموعات من المعلمات، وتقدر هذه المسافة التي نذهب إليها للتدريس من مائة وخمسين إلى مائة وثمانين كيلو مترًا، مع العلم بأنه يوجد مع السائق زوجته، فهل يجوز لنا السفر مع هذا السائق، وذلك للتدريس، ونعود في نفس اليوم يا سماحة الشيخ؟ أفتونا بذلك.","title":"حكم سفر المعلمات بدون محرم","answer":"الجواب: هذا موضوع قد شغل بال الكثير من الناس؛ لأن الرسول ﷺ نهى عن سفر المرأة إلا بمحرم، والحاجة ماسة إلى سفر هؤلاء للقيام بمهمتهم، وليس كل امرأة يتوفر لديها المحرم، فالواجب على المرأة أن تحرص على ألا تسافر إلا بمحرم، ولو كان مع نساء، ولو كانت مع سائق معه زوجته، ما يغني هذا عن المحرم، الرسول ﷺ قال: لا تسافر المرأة إلا مع ذي محرم وهؤلاء النسوة يسافرن من دون محرم مسافات طويلة، وهذا فيه نظر؛ لأنه مخالف للسنة الصحيحة، وبعض أهل العلم أجاز ذلك للحاجة والضرورة إذا كان الطريق آمنًا، وليس هناك خطر، ولكن هذا فيه نظر. فالذي يظهر لي أنه لا يجوز لأي امرأة أن تسافر إلا مع محرم، فليس هذا مقام ضرورة، ففي إمكان المرأة أن تسافر مع زوجها، أو أخيها، أو أبيها، والله المستعان. نعم. المقدم: جزاكم الله خيرًا، اللهم آمين، جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11598/حكم-سفر-المعلمات-بدون-محرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_521/52106.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":13408,"question":"السائلة تقول من بني مالك: هل يجوز للرجل أن يقبل محارمه كأمه وأخته في وجهها، أم لا يجوز له ذلك؟ وإذا كان لا يجوز فنرجو من سماحتكم أن تخبرونا بالكيفية، ونصح الإخوان والأخوات في ذلك الأمر.","title":"حكم تقبيل المحارم في الوجه","answer":"الجواب:  لا حرج أن يقبل محارمه كأمه وأخته بين عينيها، أو مع خدها، لا بأس، أو مع رأسها، كان الصديق  يقبل عائشة مع خدها، فلا بأس به، والحمد لله، من غير شهوة، من غير تلذذ، بل للقرابة والرحم، ولا يجوز أن يفعل هذا عن شهوة، أو تلذذ، ولكن يفعل ذلك عن محبة، وعن رحمة، أو قرابة، لا بأس بذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11699/حكم-تقبيل-المحارم-في-الوجه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_516/51605.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":13412,"question":"السائلة تقول: امرأة ذهبت إلى مكة وهي حائض، وجلست فيها يومًا حتى طهرت من حيضها، ثم اغتسلت، وذهبت لقضاء العمرة من طواف وسعي، لكنها بعد ذلك وجدت بعضًا من آثار الحيض، فما الحكم؟","title":"حكم من وجدت آثار الحيض بعد عمرتها","answer":"الجواب: لا يضرها ذلك إذا كان لا تعلم لا يضرها، طوافها صحيح والحمد لله، إذا وجدت في ثوبها، أو في سراويلها أثرًا من الدم لم تغسله، ولكن لم تعلم إلا بعد الطواف لا يضرها، كمن صلى وفي ثوبه نجاسة لم يعلم إلا بعد الصلاة صلاته صحيحة، والصلاة أعظم من الطواف. فإذا صلى في ثوب، ثم بان بعد الصلاة أن به نجاسة، أو صلى في سراويل، وبان فيه نجاسة، أو طاف في ثوب، أو بشت، أو غير ذلك ثم تبين بعد الطواف أن به نجاسة، ولم يعلم، أو كان عالمًا، ثم نسيها؛ فلا يضره ذلك، والحمد لله، يقول الله -جل وعلا-: رَبَّنَا لا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا [البقرة:286] وروي عنه ﷺ أنه قال: عفي لأمتي عن الخطأ والنسيان، وما استكرهوا عليه والحمد لله. والنبي ﷺ \"صلى في نعليه ذات يوم، ثم جاءه جبرائيل، فأخبره أن بهما أذى؛ فخلعهما، ولم يعد أول الصلاة\" عليه الصلاة والسلام. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11705/حكم-من-وجدت-اثار-الحيض-بعد-عمرتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_526/52607.mp3","categories":["مسائل متفرقة في الحج والعمرة","اللباس والزينة","قضايا المرأة"]},{"id":13466,"question":"هل يجوز للمرأة أن تستعمل الباروكة، وهو الشعر المستعار، وذلك من أجل الزينة؟","title":"حكم استعمال الباروكة","answer":"الجواب: لا يجوز، هذا أعظم من الوصل، الوصل لا يجوز، وصل الشعر بالشعر ما يجوز، فالباروكة أشد وأخطر، وقد ثبت في حديث معاوية في الصحيح، أنه قال: إنما عذبت نساء بني إسرائيل لما فعلن ذلك فعلن كبة من الشعر على رؤوسهن. فالمقصود: أن جعلها رأسًا تامًا، أو وصل شعر، كله لا يجوز، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11769/حكم-استعمال-الباروكة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_517/51714.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":13470,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الرياض، وباعثتها مجموعة من الأخوات هن (ن. م. صالح) الأخوات يسألن هذا السؤال، يقول  متى تحتجب المرأة عن الصبيان، أي: كم هو عمر الصبي الذي يجب على المرأة أن تحتجب منه؟ جزاكم الله خيرًا.","title":"عمر الصبي الذي تحتجب منه المرأة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فقد قال الله -جل وعلا-: وَإِذَا بَلَغَ الأَطْفَالُ مِنْكُمُ الْحُلُمَ فَلْيَسْتَأْذِنُوا كَمَا اسْتَأْذَنَ الَّذِينَ مِنْ قَبْلِهِمْ [النور:59] ويقول النبي ﷺ: إنما جعل الاستئذان من أجل النظر فالاحتجاب يكون بعد البلوغ، متى بلغ الصبي خمسة عشر سنة، أو عرف أنه احتلم، أو أنبت الشعر الذي حول.. الشعر الخشن الذي حول الفرج؛ صار بهذا محتلمًا، ووجب عليه الاستئذان، ووجب التحجب عنه. ولكن ينبغي للمرأة أن تحتاط، فإذا كان مراهقًا قد قارب سن الاحتلام، فلتحتط، ولتحتجب منه، وليس لها الخلوة به؛ بعدًا عن الشبهة، وحذرًا من الفتنة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11775/عمر-الصبي-الذي-تحتجب-منه-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_478/47801.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":13474,"question":"سؤال آخر تقول: ما رأيكم في هذا العمل، وهو أن بعض الناس عندما يتزوج ابنهم يعملون له ما يسمونه بالحناء، ويكون في ليلة قبل الزفاف، ويأتي بعض الرجال والنساء إلى بيت العريس، ويجلسون العريس في الوسط، فيأخذون ويعطونه الفلوس، وبعد هذا العمل تقوم أم العريس، وتعمل له الحناء في يديه، وجهونا ووجهوهم مأجورين، جزاكم الله خيرًا؟","title":"حكم الحناء للرجال والاختلاط في الأعراس","answer":"الجواب: الحناء من خصائص النساء، من زينة النساء، فلا يجوز أن يستعمل مع العريس، ولا مع غيره من الرجال، الحناء من زينة النساء، ومما يعمله النساء، تجملًا لأزواجهن، فلا يجوز أن يعامل الرجل بذلك، ولا أن يستعمله الرجل، بل ينبغي أن يبتعد .. بل يجب أن يبتعد عن مشابهة النساء، وقد صح عن رسول الله -عليه الصلاة والسلام- أنه قال: لعن الله الرجل يلبس لبسة المرأة، ولعن الله المرأة تلبس لبسة الرجل وجاء عنه ﷺ: أنه لعن المتشبهين من الرجال بالنساء، والمتشبهات من النساء بالرجال وهذا يعم أنواع التشبه. فالواجب الحذر من التشبه بالنساء في استعمال العريس الحناء، أو غير ذلك، مما هو من خصائص النساء. أما اجتماعهم بالعريس رجالًا، ونساء يعطونه النقود، فهذا فيه تفصيل: اجتماعهم مختلطين، وليسوا محارم فيما بينهم رجال أجنبيات، هذا ما يجوز، اختلاط الرجال مع النساء إلا على وجه فيه الحشمة، والبعد عن أسباب الفتنة، والتستر، والاحتجاب كما يجتمع الناس في بيوتهم، تجتمع المرأة مع أحماء زوجها، ومع أزواج أخواتها، مع التستر والحشمة للتحدث في بعض الأمور لا بأس. أما اختلاط فيه عدم التحجب، وعدم البعد عن أسباب الفتنة هذا لا يجوز. وهكذا لا يجوز الخلوة بالعريس من امرأة أجنبية تخلو به، فلا يجوز أيضًا. أما إعطاؤه النقود.... يساعدونه في الزواج، من باب المساعدة؛ فلا بأس كون أعطوه فلوسًا، أو غير فلوس، من باب التعاون على الخير. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11777/حكم-الحناء-للرجال-والاختلاط-في-الاعراس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_478/47803.mp3","categories":["قضايا المرأة","النظر والخلوة والاختلاط","اللباس والزينة"]},{"id":13479,"question":"إنما المصافحة كيف يكون وضعها، لو سمحتم؟","title":"حكم مصافحة المرأة الأجنبية","answer":"الجواب: ليس للرجل أن يصافح المرأة الأجنبية، يقول النبي ﷺ: إني لا أصافح النساء وتقول عائشة -رضي الله عنها-: والله ما مست يد رسول الله ﷺ يد امرأة قط، ما كان يبايعهن إلا بالكلام فالرجل لا يصافح المرأة الأجنبية، ويجب عليها التحجب عنه، ولا يخلو بها أيضًا، ولكن يسلم من دون خلوة، ومن دون مصافحة، أما مع المحارم لا بأس يصافح أخته عمته أمه لا بأس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11782/حكم-مصافحة-المراة-الاجنبية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_478/47808.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":13488,"question":"في آخر أسئلته يقول هذا السائل: نسأل عن النقاب بالنسبة للمرأة، وإذا كان واجبًا فبماذا نرد على من يقول بخلاف ذلك سماحة الشيخ؟","title":"حكم النقاب للمرأة","answer":"الجواب: المرأة عورة، والنقاب في حقها واجب، وهو ستر الوجه، وستر جميع بدنها عن الأجنبي -الرجل الأجنبي- وكان في أول الإسلام لها أن تكشف وجهها ويديها عند الرجال، وتخالطهم، ثم نسخ الله ذلك، وأنزل الله آية الحجاب، وهي قوله سبحانه: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ [الأحزاب:53] يعني: من وراء ساتر: ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] وقال تعالى: يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلابِيبِهِنَّ ذَلِكَ أَدْنَى أَنْ يُعْرَفْنَ فَلا يُؤْذَيْنَ [الأحزاب:59] يعرفن بالجلباب الذي يغطي وجهها وبدنها، هذا هو الأخير، وكان في الأمر الأول مرخص للمرأة أن تكشف، وأن تجلس مع الرجال، ثم أنزل الله الحجاب؛ صيانة لهن، وحماية لهن من أسباب الفتنة، وللرجال أيضًا. فالكشف معصية، لا يجوز لها أن تكشف لغير محارمها إلا في الإحرام، تكشف النقاب، تغطي وجهها بغير النقاب .. بالخمار .. بالجلباب، أما النقاب الذي يستر وجهها، ويبقى نقبان لعينيها، أو نقب واحد؛ فهذا يمنع منه في الإحرام، وهو ستر خاص، وحجاب خاص تمنع منه المرأة في الإحرام، أما ستر وجهها بغير ذلك من الخمر، أو ما يسمى الشيلة، أو غير ذلك لا بأس. مثلما روي عن عائشة -رضي الله عنها- قالت: \"كنا مع النبي ﷺ في حجة الوداع محرمات، وكنا إذا دنا منا الركبان؛ سدلت إحدانا خمارها على وجهها من رأسها، فإذا بعدوا؛ كشفنا\" أو قالت \"جلبابها على وجهها\" هذا يدل على أنه إذا ستر الوجه بغير النقاب في حق المحرمة لا بأس، فتصير مصلحتان: الستر مع عدم النقاب، وذلك بجعل الجلباب، أو الخمار الذي تلبسه على رأسها على وجهها عند الأجنبي، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11791/حكم-النقاب-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_518/51802.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":13509,"question":"السائلة التي أرسلت بمجموعة من الأسئلة لم تذكر الاسم في هذه الرسالة تقول: ما حكم لبس الذهب المحلق بالنسبة للنساء؟","title":"حكم لبس النساء الذهب المحلق","answer":"الجواب: لا بأس بلبس المحلق، النبي ﷺ أقر ذلك، ولا حرج في ذلك، أما ما يروى من النهي عن ذلك فهي أحاديث منسوخة .. ما بين أحاديث ضعيفة، وما بين أحاديث منسوخة، هذا هو الصواب، ولا بأس أن تلبس المحلق كالخواتم، والأسورة لا بأس بذلك، ولا حرج فيه، وقد صحت السنة بذلك، وقد حكى بعض أهل العلم إجماع العلماء على هذا، وأنه لا حرج فيه، والحمد لله. الصواب: أنه لا حرج في ذلك، وأن الخواتم والمحلق من الذهب والفضة لا حرج فيه. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11830/حكم-لبس-النساء-الذهب-المحلق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_531/53110.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":13518,"question":"تقول في آخر أسئلتها: سمعت من إحدى الأخوات في المصلى أن وضع العباءة على الكتفين حرام في الصلاة، ما صحة هذا القول؟","title":"حكم وضع العباءة على الكتفين في الصلاة","answer":"الجواب: الذي يظهر أنه لا يجوز؛ لأن فيه تشبه بالرجال، فإما أن تلبس جلبابًا وتصلي فيه، وإلا تصلي في العباءة وهي على رأسها، وإلا تدع العباءة، ويكون عليها جلباب يسترها، والحمد لله. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11836/حكم-وضع-العباءة-على-الكتفين-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_531/53112.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":13521,"question":"تقول في آخر أسئلتها: سمعت من إحدى الأخوات في المصلى أن وضع العباءة على الكتفين حرام في الصلاة، ما صحة هذا القول؟","title":"حكم وضع العباءة على الكتفين في الصلاة","answer":"الجواب: الذي يظهر أنه لا يجوز؛ لأن فيه تشبه بالرجال، فإما أن تلبس جلبابًا وتصلي فيه، وإلا تصلي في العباءة وهي على رأسها، وإلا تدع العباءة، ويكون عليها جلباب يسترها، والحمد لله. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11836/حكم-وضع-العباءة-على-الكتفين-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_531/53112.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":13523,"question":"هذا السائل مصري، ومقيم بالدمام يقول: ما هو الإزار؟ وهل يجب أن يكون السروال إلى نصف الساق؟","title":"ما هو الإزار؟","answer":"الجواب: الإزار قطعة من القماش يلفها على نصفه الأسفل يقال له: إزار، إذا لف على نصفه الأسفل، أو ربط على نصفه الأسفل يقال له: إزار، فأما إن كان مخيطًا له كمان، على النصف الأسفل هذا يسمى سراويل، إذا كان مخيطًا له كمان، كل رجل لها كم، هذا يسمى سراويل، أما إذا كان لا، إنما هو قطعة من القماش يلفها على نصفه الأسفل ويربطها، أو يلف بعضها على البعض حتى تستر نصفه الأسفل هذا يسمى الإزار. وهذا هو المشروع للمحرم، إذا أحرم بالحج، أو العمرة يلبس هذا الإزار دون السراويل، ويلبس معه الرداء على كتفيه، هذا هو السنة، وكانت هذه ملابس للعرب قديمًا، يغلب عليهم لبس الإزار والرداء، وربما لبسوا السراويل مع الرداء، وربما لبسوا القميص، لكن يغلب عليهم الرداء، فوق المنكبين مع الإزار، وهذا هو المشروع للمحرم، إذا أحرم بعمرة، أو حج يكون عليه إزار ورداء فوق منكبيه، فإن عدم الإزار ولم يتيسر الإزار؛ لبس السراويل، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11835/ما-هو-الازار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_518/51817.mp3","categories":["اللباس والزينة"]},{"id":13533,"question":"يقول في سؤاله: هل الذي يطيل الثوب يعتبر في النار وإن صلى وصام وعمل الصالحات مع العلم بأن ليس في نيته التبختر أو التكبر؟","title":"حكم الإسبال لغير قصد الخيلاء","answer":"الجواب: الإسبال لا يجوز مطلقًا، ولو كان ما عنده نية التكبر، أو التبختر، ليس له أن يسبل ثيابه تحت الكعبين، وهو متوعد بالنار؛ لقوله ﷺ: ما أسفل من الكعبين من الإزار فهو في النار أخرجه البخاري في الصحيح، وهذا في حق الرجال، ومثل الإزار: القميص، والبشت والسراويل، ويقول ﷺ: ثلاثة لا يكلمهم الله يوم القيامة، ولا يزكيهم، ولهم عذاب أليم: المسبل إزاره، والمنان فيما أعطى، والمنفق سلعته بالحلف الكاذب رواه مسلم. وإذا كان ينوي التكبر قصده التكبر؛ صار عذابه أشد؛ لقوله ﷺ: من جر ثوبه خيلاء؛ لم ينظر الله إليه يوم القيامة هذا من باب الوعيد يكون الوعيد في حقه أشد، نسأل الله العافية. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11869/حكم-الاسبال-لغير-قصد-الخيلاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_532/53208.mp3","categories":["اللباس والزينة"]},{"id":13573,"question":"ما هو لباس الشهرة يا سماحة الشيخ؟","title":"المقصود بلباس الشهرة","answer":"الجواب: الذي يخالف ما عليه الناس، هذا لباس الشهرة، يقول الناس: لماذا؟ نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11906/المقصود-بلباس-الشهرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_532/53221.mp3","categories":["اللباس والزينة"]},{"id":13615,"question":"السائل الذي رمز لاسمه بـ (م. ب. ع)، يقول: ما حكم لبس الساعة التي في بعضها ذهب -أي في الأطراف- والقلم الذي يستخدم أيضًا فيه ذهب، ما حكم استخدام مثل هذه الأشياء؟","title":"حكم استعمال الساعة والقلم اللذان فيهما ذهب","answer":"الجواب: الساعة المذهبة لا تصلح للرجال، للنساء خاصة، الساعة المذهبة لا تصلح للرجال؛ لقول النبي ﷺ: أحل الذهب والحرير لإناث أمتي، وحرم على ذكورهم ولما رأى رجلًا في يده خاتم من ذهب؛ طرحه، وقال -عليه الصلاة والسلام-: يعمد أحدكم إلى جمرة من نار، فيضعها في يده فليس للرجل أن يلبس الذهب، لا خاتمًا، ولا غيره، ولا ساعة، ولا غيرها، وهكذا قلم الذهب ينبغي تركه، ويستعمل قلمًا ليس فيه ذهب ولا فضة، المؤمن يحتاط لدينه، ويبتعد عن الشبهة. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11955/حكم-استعمال-الساعة-والقلم-اللذان-فيهما-ذهب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_528/52809.mp3","categories":["اللباس والزينة"]},{"id":13616,"question":"السائلة من جمهورية مصر العربية تقول في هذا  ما حكم عمل المرأة خارج البيت، علمًا بأنها تبلغ من العمر الحادية والثلاثين، تقول: تذكر في رسالتها بأنها ملتزمة بالحجاب الشرعي، وتتنقل بالباص في الذهاب إلى العمل، والعودة، وهي تقول: محتاجة إلى هذه النقود التي تأخذها مقابل هذا العمل؟ فما حكم عمل المرأة خارج البيت؟","title":"حكم عمل المرأة خارج البيت","answer":"الجواب: لا حرج في ذلك؛ إذا كان العمل مباحًا، كونها ممرضة، كونها خادمة، كونها مدرسة، لا بأس بهذا، أن تذهب وتأتي، وإن كان لها زوج فلابد من إذن الزوج، وليس لها أن تخلو بالسائق، لابد يكون معهم ثالث حتى لا يكون خلوة، وإذا كان العمل مباحًا تذهب للمستشفى للتمريض، تذهب مدرسة، تذهب لتعليم امرأة، أو تعليم بنات صغار في بيوتهم، أو ما أشبه ذلك. المقصود: إذا كان العمل مباحًا، وكانت تذهب بطريقة شرعية، مع محرم، أو مع ناس كثير، يعني: ثلاثة فأكثر حتى ما تصير خلوة مع السواق، إن كان لها زوج فبإذنه؛ فلا بأس بذلك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11965/حكم-عمل-المراة-خارج-البيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_534/53403.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":13633,"question":"من الدمام المستمعة (ع. ف. ع) بعثت بقضية تقول فيها: أفيدكم بأنني معلمة في إحدى مدارس مدينة بقيق، ومقيمة في مدينة الدمام، ونذهب يوميًا مع مجموعة من المعلمات في حافلة دون محرم، فهل هذا جائز، أم لابد من محرم؟ أفتونا مأجورين، جزاكم الله خيرًا.","title":"حكم سفر المعلمات خارج مدينتهن بدون محرم","answer":"الجواب: الواجب على المرأة ألا تسافر إلا مع ذي محرم؛ لقول النبي ﷺ: لا تسافر امرأة إلا مع ذي محرم وليس وجود النساء محرمًا لها، محرمها زوجها، وأبوها، وأخوها، ونحوهم، فإذا كان بين بقيق، وبين الدمام مسافة سفر ثمانين كيلو، أو سبعين كيلو، أو ما يقارب ذلك؛ فليس لك السفر بدون محرم، هذا هو الصحيح الذي عليه جمهور أهل العلم. وبعض أهل العلم رخص في السفر إذا كانت في جملة نساء ثقات عند الحاجة، ولكن ينبغي ترك ذلك خروجًا من الخلاف، وعملًا بالحديث الصحيح، وهو قوله ﷺ: لا تسافر امرأة إلا مع ذي محرم هذا نص صريح لا يحتمل التأويل، فلا يليق، ولا ينبغي للمرأة أن تتساهل في هذا. والواجب على الرئاسة العامة لتعليم البنات أن تتحرى في هذا، وأن تجعل المدرسات في البلدان التي هن فيهن، كل مدرسة تسكن في البلد التي تعلم فيه حسب الطاقة والإمكان، فإن لم تسكن فيه؛ يكون معها زوجها، أو أخوها، أو عمها يوصلها، ويردها. نعم. المقدم: جزاكم الله خيرًا، إذا كان الموضوع لمدارس خاصة مثلًا مدارس أهلية؟ الشيخ: كذلك لابد من مراعاة مدرسات يكن من البلد، أو يكون معهن محارم حتى لا تقع المدرسة في المحظور. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11962/حكم-سفر-المعلمات-خارج-مدينتهن-بدون-محرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_480/48018.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":13680,"question":"في آخر أسئلته يقول هذا السائل: هل يجوز مصافحة المرأة الأجنبية الكبيرة في السن، والتي لا ترجو نكاحًا؟","title":"حكم مصافحة المرأة الكبيرة في السن","answer":"الجواب: لا تجوز مصافحة النساء، النبي ﷺ قال: إني لا أصافح النساء وقالت عائشة -رضي الله عنها-: \"ما مست يد رسول الله يد امرأة قط، ما كان يبايعهن إلا بالكلام\" -عليه الصلاة والسلام- فلا تجوز مصافحة النساء، ولو عجائز، حسمًا لمادة الفتنة، وحذرًا من الشر، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12029/حكم-مصافحة-المراة-الكبيرة-في-السن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_519/51909.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":13696,"question":"من منطقة جيزان المستمع (ح. ع. ح. محمد) بعث برسالة ضمنها بعضًا من الأسئلة في أحدها يقول: امرأة تخرج بغير إذن زوجها إلى أهلها، أو إلى مكان فيه مناسبة نسائية، هل تأثم؟ وإذا خاصمها زوجها قالت: أنا كنت في واجب؟ أفيدونا جزاكم الله خيرًا.","title":"هل تخرج المرأة من بيت زوجها بغير إذنه؟","answer":"الجواب: ليس لها الخروج إلا بإذن زوجها، يحرم عليها أن تخرج إلا بإذن زوجها، ولو كانت في تعزية لأهل ميت، أو عيادة المريض، أو لأهلها ليس لها الخروج إلا بإذنه، عليها السمع والطاعة.. عليها السمع والطاعة لزوجها إلا في المعصية، أما في المعروف فعليها السمع والطاعة، وليس لها الخروج إلا بإذنه، سواء كان ذلك لأهلها، أو لغير أهلها. وعلى الزوج أن يراعي حقها، وأن يتلطف بها، وأن يحسن عشرتها، فيأذن لها في الخروج المناسب الذي ليس فيه منكر، وليس فيه إعانة على منكر من باب المعاشرة بالمعروف، ومن باب جمع الشمل، فلا ينبغي له أن يشدد، ولا يجوز لها أن تعصيه في المعروف، أما إن أمرها بمعصية؛ فلا، ليس لها طاعته في ذلك. لو أمرها أن تسب والديها، أو تشرب الخمر، أو تترك الصلاة لم يجز لها طاعته في ذلك، حرم عليها طاعته في ذلك؛ لأن الرسول  يقول: إنما الطاعة في المعروف ويقول -عليه الصلاة والسلام-: لا طاعة لمخلوق في معصية الخالق. لكن إذا أمرها بشيء مباح من عدم الخروج للجيران، أو لأهلها، أو عدم صنع الطعام المعين، أو أشياء أخرى مما أباح الله؛ فليس لها أن تعصيه، بل عليها السمع والطاعة. نعم.. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12067/هل-تخرج-المراة-من-بيت-زوجها-بغير-اذنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_481/48104.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":13701,"question":"تقول السائلة: هل وضع المكياج بقصد التجمل للرجل بالنسبة للمرأة في بيتها محرم؟ أم لا؟ علمًا بأنه لا أحد يراها إلا الزوج فقط؟","title":"حكم استعمال المكياج للتجمل للزوج","answer":"الجواب: لا بأس، لا حرج في أخذ المكياج وغيره مما يحسن وجهها إذا لم يكن فيه مضرة، إذا كان المكياج أو غيره كالصابون وغيره إذا كان للتجمل، فلا بأس إلا إذا كان ذلك الشيء يضر الوجه يجعل فيه رقعًا سوداء، أو يسبب مرضًا؛ فلا. لكن إذا كان لا، ينظف الوجه، وينوره، ولا يضر الوجه، والقصد التجمل لزوجها، فلا بأس بهذا، والحمد لله. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12085/حكم-استعمال-المكياج-للتجمل-للزوج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_535/53510.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":13709,"question":"هذه رسالة وصلت من مستمعة للبرنامج تقول في هذا  هل يجوز للمرأة أن تتزين لزوجها كأن تستعمل الأحمر والأبيض والأسود في شعرها، وإذا استعملت ذلك فهل تكون مغيرة لخلق الله تعالى؟","title":"حكم تزين المرأة لزوجها وصبغ شعرها","answer":"الجواب: يستحب للمرأة التزين لزوجها؛ لأن هذا من أسباب محبته لها، ومن أسباب ميله إليها، فتزينها له داخل في قوله: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19] وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ [البقرة:228] عليها أن تتصنع لزوجها، وأن تتجمل لزوجها، وأن تستعمل الطيب، وكل شيء يرغبه فيها، هذا سنة في حقها، إلا ما حرم الله، فعليها أن تستعمل ما أباح الله من الطيب، واللباس، ونحو ذلك، أما ما حرم الله كالنمص لا يجوز نمص الحاجبين ولو طلبه الزوج، أو تغيير الشيب بالسواد، إذا كانت كبيرة فيها شيب؛ ليس لها أن تغيره بالسواد، لقول النبي ﷺ: غيروا هذا الشيب، واجتنبوا السواد. أما كونها تصبغ شيبها بحمرة، أو صفرة، أو بين السواد والحمرة؛ فلا بأس، تلبس ثيابًا جميلة صفراء، أو حمراء، أو خضراء، أو بيضاء، لكن على وجه ليس فيه تشبه بالرجال، لباس ما فيه تشبه، أما التشبه بالرجال فلا يجوز، ففي الحديث الصحيح: لعن الله المرأة تلبس لبسة الرجل فليس لها أن تتشبه بالرجال، لا في الملبس، ولا في غيره. أما كون اللون أبيض، أو أحمر، أو أصفر لا يضر، لكن على الهيئة التي يلبسها النساء، لا على هيئة الرجال. نعم.","link":"https://binbaz.org.sa/fatwas/12074/حكم-تزين-المراة-لزوجها-وصبغ-شعرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_545/54505.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":13732,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول أحمد محمد عطية، مصري الجنسية، الأخ أحمد يسأل عن حجاب المرأة، هل هو تغطية الوجه فقط؟ وهل هو فرض، أم سنة؟","title":"هل الحجاب تغطية الوجه فقط؟","answer":"الجواب: الحجاب معناه: أن تغطي وجهها، وبدنها كله، هذا الحجاب عن الرجال الأجانب، كأخي زوجها، وعم زوجها، وزوج أختها، أو زوج عمتها، وابن عمها، وابن خالها، وجيرانها تحتجب عنهم، تغطي وجهها، وشعرها، وبدنها كله، لكن تسلم عليهم، ترد عليهم السلام، لا بأس، لكن لا تصافحهم، ولا تكشف لهم عن شيء من بدنها، قال الله -عز وجل- في حق نساء النبي ﷺ: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53].  بين سبحانه أن الكلام يكون من وراء حجاب، وهو التغطي، أو من وراء باب، أو من وراء اللباس الذي تحجبت به، وذكر أنه أطهر لقلوب الجميع، أن هذا العمل أطهر لقلوب هؤلاء وهؤلاء؛ لأن النظر قد يفتن، وقد يدعو إلى الشهوة، فكان الحجاب من أسباب السلامة، وقال -جل وعلا- في سورة النور: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ [النور:31] إلى آخره. فنهى النساء أن يبدين زينتهن إلا لأزواجهن، ومن ذكر مع الأزواج، وما ذاك إلا لأن إظهار الزينة من الفتنة، فقد يفتن بها رائيها، وربما جر هذا إلى فساد، سواء كان زوج أختها، أو كان أخ زوجها، أو عم زوجها، أو ابن عمها، أو ابن خالها، أو أحد جيرانها من غير المحارم، كلهم ليس لها أن تبدي لهم الزينة من وجه، أو غيره. نعم.. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12103/هل-الحجاب-تغطية-الوجه-فقط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_481/48115.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":13740,"question":"من أسئلة هذه السائلة من سوريا تقول: هل الخروج بغير الجلباب باللون الأسود مثلًا محرم مثل: اللون البنفسجي، والأخضر، والرمادي؟ وجهونا في ذلك.","title":"حكم لبس المرأة الجلباب غير الأسود","answer":"الجواب: الخروج إلى السوق بجلباب يستر عورتها، ويسترها، سواء أسود، أو أحمر، أو أخضر ما يلفت النظر، ما يكون بسبب الفتنة، لا حرج في ذلك، وتكون مستورة البدن، لا حرج، مستورة الوجه والقدمين، يعني: لا يرى منها شيء، لا حرج في ذلك. المقصود: البعد عن أسباب الفتنة، وليس من شرط ذلك العباءة، لكن العباءة أكمل، العباءة التي ليس فيها فتنة تكون أكمل في التستر، ويكون الوجه مستورًا بالخمار، أو بالنقاب الذي لا يبدو منه إلا العين، أو العينان، أو بالخمار، فلا حرج في ذلك؛ لقوله -جل وعلا-: وَقَرْنَ فِي بُيُوتِكُنَّ وَلا تَبَرَّجْنَ تَبَرُّجَ الْجَاهِلِيَّةِ الأُولَى [الأحزاب:33] فنهى عن التبرج، فإذا خرجت بدون تبرج؛ فلا بأس. ولقوله -جل وعلا-: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]، ولقوله سبحانه: يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلابِيبِهِنَّ ذَلِكَ أَدْنَى أَنْ يُعْرَفْنَ فَلا يُؤْذَيْنَ [الأحزاب:59] والجلباب: اللباس الذي يستر البدن. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12109/حكم-لبس-المراة-الجلباب-غير-الاسود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_535/53511.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":13741,"question":"السائل الذي رمز لاسمه بـ (أ. أ) يقول في هذا  هل الصلاة تقبل من الذي ثوبه مسبل؟","title":"حكم صلاة المسبل إزاره","answer":"الجواب: على خطر، على خطر من ذلك، لكن تصح .. تجزئه؛ لأن الرسول ﷺ ما أمره بالإعادة، الذي صلى وهو مسبل لم يأمره بالإعادة، فصلاته ناقصة، لا يؤمر بالإعادة، لكن لا يجوز له الإسبال مطلقًا، لا في الصلاة، ولا في خارجها. نعم.","link":"https://binbaz.org.sa/fatwas/12126/حكم-صلاة-المسبل-ازاره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_535/53519.mp3","categories":["اللباس والزينة","مسائل متفرقة في الصلاة"]},{"id":13745,"question":"من أسئلة هذه السائلة من سوريا تقول: هل الخروج بغير الجلباب باللون الأسود مثلًا محرم مثل: اللون البنفسجي، والأخضر، والرمادي؟ وجهونا في ذلك.","title":"حكم لبس المرأة الجلباب غير الأسود","answer":"الجواب: الخروج إلى السوق بجلباب يستر عورتها، ويسترها، سواء أسود، أو أحمر، أو أخضر ما يلفت النظر، ما يكون بسبب الفتنة، لا حرج في ذلك، وتكون مستورة البدن، لا حرج، مستورة الوجه والقدمين، يعني: لا يرى منها شيء، لا حرج في ذلك. المقصود: البعد عن أسباب الفتنة، وليس من شرط ذلك العباءة، لكن العباءة أكمل، العباءة التي ليس فيها فتنة تكون أكمل في التستر، ويكون الوجه مستورًا بالخمار، أو بالنقاب الذي لا يبدو منه إلا العين، أو العينان، أو بالخمار، فلا حرج في ذلك؛ لقوله -جل وعلا-: وَقَرْنَ فِي بُيُوتِكُنَّ وَلا تَبَرَّجْنَ تَبَرُّجَ الْجَاهِلِيَّةِ الأُولَى [الأحزاب:33] فنهى عن التبرج، فإذا خرجت بدون تبرج؛ فلا بأس. ولقوله -جل وعلا-: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]، ولقوله سبحانه: يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلابِيبِهِنَّ ذَلِكَ أَدْنَى أَنْ يُعْرَفْنَ فَلا يُؤْذَيْنَ [الأحزاب:59] والجلباب: اللباس الذي يستر البدن. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12109/حكم-لبس-المراة-الجلباب-غير-الاسود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_535/53511.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":13746,"question":"السائل الذي رمز لاسمه بـ (أ. أ) يقول في هذا  هل الصلاة تقبل من الذي ثوبه مسبل؟","title":"حكم صلاة المسبل إزاره","answer":"الجواب: على خطر، على خطر من ذلك، لكن تصح .. تجزئه؛ لأن الرسول ﷺ ما أمره بالإعادة، الذي صلى وهو مسبل لم يأمره بالإعادة، فصلاته ناقصة، لا يؤمر بالإعادة، لكن لا يجوز له الإسبال مطلقًا، لا في الصلاة، ولا في خارجها. نعم.","link":"https://binbaz.org.sa/fatwas/12126/حكم-صلاة-المسبل-ازاره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_535/53519.mp3","categories":["اللباس والزينة","مسائل متفرقة في الصلاة"]},{"id":13755,"question":"إحدى الأخوات المستمعات رمزت إلى اسمها بالحروف (ف. أ. ع) من الرياض، تسأل جمعًا من الأسئلة في أحدها تقول: إذا صافحت على المحارم من الرجال بيدي وأنا صائمة، هل يؤثر ذلك على الصيام؟ وأيضًا هل يؤثر على الوضوء، والصلاة؟","title":"هل تؤثر مصافحة المرأة لمحارمها على الصيام والوضوء؟","answer":"الجواب: لا، لا يؤثر. المقدم: لا يؤثر. الشيخ: نعم، إذا صافحت. المقدم: نعم. الشيخ: لا يؤثر ذلك.. لكن لا تصافح إلا المحارم بس فقط، مثل زوجها، أخاها، عمها، خالها، أما الأجنبي، أو زوج أختها، أو أخا زوجها لا تصافحه، النبي ﷺ قال: لا أصافح النساء فهي تصافح من يكون لها مصافحته من المحارم، ولا ينتقض الوضوء بذلك. نعم.. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12119/هل-توثر-مصافحة-المراة-لمحارمها-على-الصيام-والوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_481/48120.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":13768,"question":"رسالة وصلت إلى البرنامج من جدة أيضًا وباعثها مستمع من هناك يقول المرسل (س. س. س) أخونا له عدد من الأسئلة من بينها سؤال عن حكم سكن المرأة الأرملة أو المطلقة في البيت لوحدها دون محرم، هل يجوز لها ذلك أو لا؟","title":"حكم سكن المعتدة في بيت بمفردها","answer":"الجواب: نعم، يجوز لها السكن وحدها سواء كانت أرملة أو مطلقة لا بأس أن تسكن وحدها إذا كانت في محل آمن لا خطر عليها، أما إذا كان المحل ليس بآمن فإنها لا تسكن وحدها بل تسكن مع غيرها من أهلها أو من النساء الثقات اللاتي لا خطر في السكنى معهن، وهذا معروف من قواعد الشرع المطهر، فإذا كانت في محل آمن فلا بأس أن تسكنه وحدها، وإذا كان المحل ليس بآمن فإنها تلتمس سكنًا آمنًا لا خطر فيه لا على عرضها ولا على بدنها.\nالمقصود أن هذا يختلف بحسب اختلاف البلدان، فإذا كان البلد آمنًا والحي الذي هي فيه آمن ليس عليها خطر فلا حرج في ذلك، أما إذا كانت هناك خطورة في سكنها وحدها فإنها يجب عليها أن تلتمس محل الأمن، ولاسيما الخطر على عرضها، وقد يكون خطر على غير عرضها على نفسها أيضًا.\nفالمقصود أنها في المحل الآمن الذي لا خطر فيه فلا بأس، وفي المحل غير الآمن ليس لها ذلك بل تلتمس المحل الآمن بالطرق التي تستطيعها.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12162/حكم-سكن-المعتدة-في-بيت-بمفردها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_601/60109.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":13783,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع العوني أبو عونية أخونا عرضنا بعض أسئلته في حلقة مضت وفي هذه الحلقة يسأل ويقول: ما حكم الصلاة بالملابس الضيقة للرجال؟ وهل يصلي بالناس من يرتديها؟","title":"حكم الصلاة بالملابس الضيقة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فالملابس الضيقة يكره لبسها للرجال والنساء جميعًا، والمشروع أن تكون الملابس متوسطة، لا ضيقة تبين حجم العورة ولا واسعة ولكن بين ذلك، أما الصلاة فهي صحيحة إذا كانت ساترة فالصلاة صحيحة، ولكن يكره للمؤمن تعاطي مثل هذه الألبسة الضيقة، وهكذا المؤمنة يكون اللباس متوسطًا بين الضيق والسعة، هذا هو الذي ينبغي. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12138/حكم-الصلاة-بالملابس-الضيقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_601/60101.mp3","categories":["اللباس والزينة","ستر العورة للمصلي"]},{"id":13896,"question":"ما حكم لبس الثياب الضيقة التي تظهر أجزاء المرأة؟ وهل يجوز لها أن تصلي فيها أو لا؟","title":"حكم لبس المرأة الملابس الضيقة والصلاة فيها","answer":"الجواب: أقل أحوالها الكراهة، أقل أحوالها الكراهة، ما ينبغي أن تصلي في ثياب ضيقة، بل تكون وسط لا ضيقة ولا واسعة جدًا وسط، هذا السنة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12260/حكم-لبس-المراة-الملابس-الضيقة-والصلاة-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_482/48201.mp3","categories":["ستر العورة للمصلي","اللباس والزينة","قضايا المرأة"]},{"id":13912,"question":"السائلة من الأردن التي رمزت لاسمها بـ (ر. ح) تقول في هذا  قرأت في سنن النسائي حديثًا عن الرسول ﷺ يبين كراهية إظهار الذهب للنساء، وأسمع كثيرًا من الفتاوى تفيد على أن إظهار الخاتم أو الأسورة بالنسبة للمرأة ليس حرامًا؛ لأنه من الزينة الظاهرة التي أجازها الله ، فأرشدونا حول هذا الأمر للأهمية مأجورين؟","title":"حكم إظهار المرأة للخاتم والأسورة أمام الأجانب","answer":"الجواب: الله جل وعلا يقول: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ [النور:31] الآية، فإظهار الزينة من الحلي في اليدين أو في الحلق أو في الأذن كل هذا من المحرمات، لا يجوز لها إبداء الزينة بل يجب عليها التستر والحجاب، قال الله جل وعلا: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]. فالواجب على المرأة أن تستر وجهها وجميع بدنها عند غير المحارم، ومن ذلك ستر يديها وما فيها من الأسورة والخواتم وستر حلقها وما فيه، وستر وجهها وما في أذنيها كل هذا واجب، وقال الله جل وعلا: وَلا تَبَرَّجْنَ تَبَرُّجَ الْجَاهِلِيَّةِ الأُولَى [الأحزاب:33] قال العلماء: معنى ذلك إظهار المحاسن، معنى التبرج: إظهار المحاسن والمفاتن. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12324/حكم-اظهار-المراة-للخاتم-والاسورة-امام-الاجانب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_544/54411.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":13932,"question":"تسأل أيضًا وتقول: هل يجوز للمرأة غير المتزوجة أن تكشف رأسها؟ جزاكم الله خيرًا.","title":"حكم كشف الرأس للمرأة غير المتزوجة","answer":"الجواب: لا حرج أن تكشف رأسها إذا كان ما عندها أحد، تكشف .. رأسها عند أمها وعند أخواتها وعند النساء لا حرج، أما إذا كان عندها أجنبي لا تكشف رأسها ولا وجهها ولا بدنها، سواءٌ كان الأجنبي ابن عم أو ابن خال أو زوج أخت أو كان أخا زوج أو ما أشبه ذلك، عليها التستر عن جميع الأجانب وهم غير المحارم، أما عند النساء لا بأس أن تكشف رأسها عند أمها وأخواتها جاراتها في البيت لا حرج، وهكذا عند الزوج عند المحرم لا بأس. نعم..\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12321/حكم-كشف-الراس-للمراة-غير-المتزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_482/48207.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":13941,"question":"تسأل أختنا وتقول: بالنسبة لطلاء الأظافر سمعت أن المرأة إذا وضعته على أظافرها وهي طاهر جاز لها أن تصلي وإن انتقض الوضوء بعد ذلك فنريد الجواب الصحيح؟ بارك الله فيكم.","title":"حكم طلاء الأظافر للنساء","answer":"الجواب: إذا كان الموضوع على الأظافر لا جرم له، لا جسم له فلا يضر، مثل الحناء الذي لا جسم له مثل إذا غمست أصابعها في الحناء من غير أن يكون له جسم أو ما أشبه ذلك من الدهونات التي لا جسم لها فإنه لا يضر، إذا توضأت ثم انتقضت الطهارة وأعادت الوضوء وذلك عليها لا يضر. أما إذا كان له جسم كالذي يسمونه مناكير أو غير ذلك مما يكون له جسم على الظفر هذا لابد من إزالته، إذا أرادت الوضوء تزيله عن أظفارها؛ لأنه يمنع وصول الماء إلى الظفر فيزال، ولابد من إزالته، كما لو كان على ذراعيها عجين أو طين يزال، وهكذا على رجلها أو وجهها يزال، فهكذا مكان الأظافر إذا شيء له جسم من عجين أو مناكير أو قطعة من الحناء لها جرم أو ما أشبه ذلك يزال، أما مجرد الصبغ صبغ الحناء في أظفارها صار له أثر صفرة حمرة أو غير ذلك من الأصباغ لا يضر هذا؛ لأنه لا جسم له. نعم.","link":"https://binbaz.org.sa/fatwas/12360/حكم-طلاء-الاظافر-للنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_604/60408.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":13948,"question":"من اليمن الشمالي هذه رسالة وصلت إلى البرنامج من الأخت (م. ع. س) أختنا لها جمع من الأسئلة تسأل في سؤاله الأول وتقول: هل يجوز للمرأة أن تلبس ثوبًا قصيرًا أو خفيفًا أمام محارمها؟","title":"حكم لبس المرأة للقصير والخفيف أمام المحارم","answer":"الجواب: لا ينبغي لها ذلك، ينبغي أن تكون بعيدة عن أسباب الفتنة، تلبس ثوبًا ساترًا طويلًا حتى لا تقع في فتنة ولا توقع غيرها في فتنة؛ لأن المحارم قد يفتن بعضهم بذلك، قد يكون فيهم الفاسق، فلا يجوز لها التساهل في هذا الأمر، ينبغي لها أن تكون محتشمة بين محارمها من إخوة وأعمام وأخوال وأبناء تكون محتشمة تلبس الملابس الجيدة الحسنة الساترة غير القصيرة ابتعادًا عن أسباب الفتنة، ولا مانع من أن يروا شيئًا من رأسها تكشف وجهها ويديها وقدميها لا بأس لكن مع التستر في بقية البدن بعدًا عن الخطر والفتنة ولاسيما في هذا العصر الذي قل فيه العلم وضعف فيه الإيمان إلا من شاء الله، وكثرت فيه أسباب الفتنة. فينبغي للمؤمنة أن تكون حريصة على التستر والحشمة حتى مع محارمها لئلا تقع في فتنة أو توقعهم في فتنة، رزق الله الجميع التوفيق والسلامة. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12359/حكم-لبس-المراة-للقصير-والخفيف-امام-المحارم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_604/60407.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":13953,"question":"هل للفتاة غير المتزوجة أن تتزين وتضع على وجهها المكياج إذا كانت لا تخرج ولا تقابل الرجال الأجانب؟","title":"حكم تزين المرأة غير المتزوجة في بيتها","answer":"الجواب: نعم، لها أن تتزين في بيتها عند أهلها لا بأس تضع الزينة المعتادة من ملابس وتنظيف وجه وغير ذلك وربما جاء من يخطبها فيراها على حالة حسنة، ربما تأتي امرأة تخطبها لغيرها تخطبها لابنها أو لأخيها أو كذا فتراها في حالة حسنة.\nالمقصود أنه لا بأس بالتزين بالملابس وغير الملابس في بيتها بين أهلها وبين نسائها من دون أن تظهر ذلك لغير محارمها لا بأس بهذا ولا حرج. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12363/حكم-تزين-المراة-غير-المتزوجة-في-بيتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_604/60411.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":13962,"question":"تسأل أختنا مع الذين يسألون عن صبغ الشيب بالصبغ الأسود بالنسبة للمرأة التي تتجمل بها عند زوجها، مع العلم بأنه لا يراها الرجال الأجانب؟","title":"حكم صبغ المرأة شعرها بالسواد","answer":"الجواب: تقدم الجواب عن هذا في السؤال السابق، وأنه لا يجوز للرجل ولا للمرأة الصبغ بالسواد الخالص، ولو للتجمل عند الزوج، بل يجب أن يكون الصبغ مخلوطًا، ليس بالسواد الخالص، بل يكون فيه خلط بين السواد والحمرة، أما السواد الخالص الذي ليس فيه خلط؛ هذا لا يجوز، لعموم قوله ﷺ: غيروا هذا الشيب واجتنبوا السواد. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12383/حكم-صبغ-المراة-شعرها-بالسواد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_605/60507.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":13964,"question":"يسأل أخونا ويقول: رأينا كثيرًا من الناس يستعملون النيل الأسود للحى والشوارب، فهل هذا محرم أم مباح؟","title":"حكم صبغ اللحية والشارب بالنيل الأسود","answer":"الجواب: يستحب للمؤمن وللمؤمنة تغيير الشيب بالحمرة والصفرة أو بالحناء والكتم؛ لقول النبي عليه الصلاة والسلام: غيروا هذا الشيب وجنبوه السواد، فالسنة تغيير الشيب وعدم تركه أبيض، لقوله عليه الصلاة والسلام: إن اليهود والنصارى لا يصبغون فخالفوهم، فيستحب لنا المسلمين جميعًا رجالًا ونساء أن يغيروا الشيب، بالصفرة والحمرة، أو بالسواد المخلوط بالحمرة كالحناء والكتم؛ عملًا بالسنة ومخالفة لليهود و النصارى في ذلك.\nلكن لا يغير بالسواد الخالص، لقول النبي ﷺ: غيروا هذا الشيب وجنبوه السواد، في اللفظ الآخر: واجتنبوا السواد، رواه مسلم في صحيحه، وخرج الإمام أحمد و النسائي و أبو داود بإسناد صحيح عن ابن عباس رضي الله عنهما، عن النبي عليه الصلاة والسلام أنه قال: يأتي قوم في آخر الزمان يخضبون بالسواد، كحواصل الحمام لا يريحون رائحة الجنة، وهذا وعيد شديد، هذا وعيد يدل على تحريم الخضاب بالسواد الخالص، ولكن يستحب للمؤمن والمؤمنة تغيير الشيب بالحناء الخالص.. بالصفرة.. بالحناء والكتم، يعني: سواد مخلوط بحمرة حتى لا يكون سوادًا خالصًا، يكون بين السواد والحمرة؛ لا بأس، وفق الله الجميع.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12378/حكم-صبغ-اللحية-والشارب-بالنيل-الاسود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_605/60503.mp3","categories":["اللباس والزينة"]},{"id":13977,"question":"مستمع من الدمام هو الأخ فهد إبراهيم، يذكر رقم صندوق البريد والرمز البريدي، وله جمع من الأسئلة.في سؤاله الأول يقول: الرسول ﷺ حرم علينا لبس الثوب الطويل، وأن يكون فوق الكعبين، هل لبس البنطلون ينطبق عليه الحكم، وهل هناك حديث يفيد بتقصير الثوب حتى نصف الساق؟ جزاكم الله خيرًا.","title":"حكم إرخاء البنطال تحت الكعبين والثياب إلى نصف الساق","answer":"الجواب: نعم، صح عن النبي ﷺ أن أزرة المؤمن إلى نصف ساقه، ولا حرج عليه أن ينزل إلى الكعب، وصح عنه عليه الصلاة والسلام أنه قال: ما أسفل من الكعبين من الإزار فهو في النار، وهذا يعم جميع الملابس، يعم البنطلون ويعم الإزار ويعم السراويل ويعم القميص ويعم البشت، ويعم غير ذلك من الملابس، الواجب على المؤمن الرجل أن تكون ملابسه إلى حد الكعب، لا تنزل عن الكعب. أما المرأة فالسنة لها أن ترخي ثيابها حتى تستر قدميها، إلا أن يكون عليها جرابان في رجليها فلا بأس، لا بأس أن تظهر الرجل إذا كان عليها الجوارب.\nالمقصود أن الرجل ليس له أن يرخي تحت الكعب، الحد الكعب، من أي ملبس كان: إزارًا أو قميصًا أو سراويل أو بشتًا أو غير ذلك؛ لأن الرسول ﷺ نهى عن الإسبال، وشدد فيه عليه الصلاة والسلام، وإذا كان عن تكبر؛ صار الإثم أعظم، إذا كان الإرخاء للتكبر والتعاظم والخيلاء؛ صار الذنب أعظم، كما قال عليه الصلاة والسلام: من جر ثوبه خيلاء؛ لم ينظر الله إليه يوم القيامة.\nفالواجب على المؤمن أن يتحرى السنة في ذلك، وأن يحذر ملابس المتكبرين، وأن يبتعد عن أن يظن به هذا الشر، فيرفع ثيابه إلى نصف الساق فأقل، النصف فأقل إلى الكعب، هذا هو المشروع، وإذا كان في بيئة تعيبه بذلك، ويتأذى بذلك؛ فلا حاجة إلى أن يرفع إلى نصف الساق، الحمد لله عنده رخصة، يرخي إلى الكعب والحمد لله، ويستريح من الأذى ولا بأس؛ لأنها سنة فقط مستحب، المحرم أن ينزل عن الكعب، هذا هو المحرم، أما من الكعب إلى النصف، هذا كله موسع فيه والحمد لله. نعم.\nالمقدم: جزاكم الله خيرًا ونفع بكم.","link":"https://binbaz.org.sa/fatwas/12409/حكم-ارخاء-البنطال-تحت-الكعبين-والثياب-الى-نصف-الساق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_606/60605.mp3","categories":["اللباس والزينة"]},{"id":13979,"question":"أخونا فهد إبراهيم من الدمام يقول: هل هناك دليل شرعي يحرم وضع الكحل على العين والحناء (الخضاب) على الأيدي والأرجل بالنسبة للرجل، علمًا بأن وضعها ليس القصد منه التشبه بالنساء، إنما عادة.","title":"حكم الكحل والحناء للرجل","answer":"الجواب: ليس للمؤمن أن يتشبه بالنساء لا في الحناء ولا في غيرها، ولو كان عادة، ليس له أن يفعل ما يكون فيه متشبهًا بالنساء؛ لأن الرسول ﷺ لعن المتشبهين من الرجال بالنساء، ولعن المتشبهات من النساء بالرجال. أما الكحل: فلا بأس مشروع للجميع للرجال والنساء، كونه يكحل عينيه لا بأس، الكحل طيب ونافع، وقد كان النبي يكتحل عليه الصلاة والسلام فلا بأس بذلك. نعم.","link":"https://binbaz.org.sa/fatwas/12411/حكم-الكحل-والحناء-للرجل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_606/60606.mp3","categories":["اللباس والزينة"]},{"id":13983,"question":"هذا سائل للبرنامج السائل (أ. س. ص) يقول في هذا  نويت العمرة فطفت ثم سعيت والحمد لله، وبعد ذلك وضعت الإحرام على رأسي جهلًا مني وليس نسيانًا أو تعمدًا، ثم حلقت رأسي، فماذا علي؟","title":"ما يلزم المحرم إذا غطى رأسه جاهلًا أو ناسيًا؟","answer":"الجواب: وضع الإحرام على الرأس جهلًا أو نسيانًا لا شيء فيه والحمد لله، فلو أن الإنسان غطى رأسه وهو محرم جاهلًا أو ناسيًا أو تطيب جاهلًا أو ناسيًا أو قص شعره أو ظفره جاهلًا أو ناسيًا فلا شيء عليه، ثبت عن النبي ﷺ: \"أن إنسانًا أحرم وعليه جبة وتضمخ بالطيب، فأمره النبي ﷺ أن ينزع الجبة وأن يغسل أثر الخلوق ولم يأمره بفدية\"؛ لأنه جاهل. نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12392/ما-يلزم-المحرم-اذا-غطى-راسه-جاهلا-او-ناسيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_539/53906.mp3","categories":["اللباس والزينة","محظورات الإحرام","قضايا المرأة"]},{"id":13986,"question":"هذا سائل للبرنامج السائل (أ. س. ص) يقول في هذا  نويت العمرة فطفت ثم سعيت والحمد لله، وبعد ذلك وضعت الإحرام على رأسي جهلًا مني وليس نسيانًا أو تعمدًا، ثم حلقت رأسي، فماذا علي؟","title":"ما يلزم المحرم إذا غطى رأسه جاهلًا أو ناسيًا؟","answer":"الجواب: وضع الإحرام على الرأس جهلًا أو نسيانًا لا شيء فيه والحمد لله، فلو أن الإنسان غطى رأسه وهو محرم جاهلًا أو ناسيًا أو تطيب جاهلًا أو ناسيًا أو قص شعره أو ظفره جاهلًا أو ناسيًا فلا شيء عليه، ثبت عن النبي ﷺ: \"أن إنسانًا أحرم وعليه جبة وتضمخ بالطيب، فأمره النبي ﷺ أن ينزع الجبة وأن يغسل أثر الخلوق ولم يأمره بفدية\"؛ لأنه جاهل. نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12392/ما-يلزم-المحرم-اذا-غطى-راسه-جاهلا-او-ناسيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_539/53906.mp3","categories":["اللباس والزينة","محظورات الإحرام","قضايا المرأة"]},{"id":13994,"question":"أيضًا نعود إلى رسالة الأخت (ن. هـ. أ. د) حيث عرضنا بعض أسئلة لها في حلقة مضت، ولها في هذا الحلقة مجموعة من الأسئلة، تقول في أحدها: يقول ﷺ في شأن خروج النساء: أذن لكن بالخروج لحاجتكن ما المقياس الذي تقدر فيه الحاجة المسموح للمرأة بالخروج من أجلها؟ وإن كان محرمها من الرجال يستطيع أن يكفيها حاجتها، فهل يباح لها الخروج، وخاصةً إذا كانت حاجتها شراء الملابس؟ وإن لم يكن لها محرم، وجدت قريبًا غير محرم، يكفيها حاجتها، فهل يباح لها الخروج؟ أم يكفيها قريبها غير المحرم؟ نرجو التوجيه، جزاكم الله خيرًا.","title":"ما الحاجة التي يجوز للمرأة الخروج لأجلها؟","answer":"الجواب: كل امرأة أعلم بحاجتها هذا شيء لا يتحدد، كل امرأة أعلم بحاجتها، فإذا رأت أن محرمها أو غيره لا يكفي، ولا يحصل به المقصود فلها الخروج، أما إذا كانت تعلم أن زوجها، أو أخاها يحصل به المقصود وليس هناك حاجة إلى خروجها فالأولى بها ألا تخرج، وأن تكتفي بمحرمها؛ من أخٍ أو زوجٍ أو غيرهما، أو بغيرهما ممن تطمئن إليه وتثق به من الرجال أو النساء، يكفونها المئونة؛ لأن خروجها عرضة لشر كثير، فلا ينبغي لها أن تتساهل في ذلك. فالخروج عند الحاجة مع التستر والتحفظ والبعد عن أسباب الفتنة والريبة هذا أمر مطلوب، ولهذا قال جل وعلا: وَقَرْنَ فِي بُيُوتِكُنَّ [الأحزاب:33] فأمر بلزوم البيوت، يعني: إلا عند الحاجة، وقد كان أزواج النبي ﷺ يخرجن للحاجة، وهكذا نساء المؤمنين يخرجن للحاجة، فإذا خرجت لحاجتها من زيارة قريب أو عيادة مريض أو صلة رحم أو شراء حاجة من السوق، ترى أن شراءها لها أولى لأنها أعلم بحاجتها، وأعلم بالصفة التي تريد فلا حرج في ذلك، وإذا تيسر لها أن يكفيها غيرها، فذلك خير لها وأفضل.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12400/ما-الحاجة-التي-يجوز-للمراة-الخروج-لاجلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_483/48302.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":13995,"question":"ما هي المسافة التي سمح بها الشرع لخروج المرأة وحدها دون محرم؟ وكيف التوفيق بين الروايات التي جاءت تحدد المسافة بثلاثة أيامٍ في إحدى الروايات، ويومين في روايةٍ أخرى، ويومٍ واحد في رواية ثالثة، وما مقدار مسيرة اليوم بالكيلو متر؟","title":"المسافة التي يحرم على المرأة الخروج دون محرم","answer":"الجواب: القاعدة في هذا هو أن ما يسمى سفرًا؛ ليس لها الخروج إليه إلا بمحرم، كل ما يسمى سفر ليس لها أن تسافر إلا بمحرم، لقوله ﷺ: لا تسافر امرأة إلا مع ذي محرم وفي رواية: مسيرة يوم وليلة وفي رواية: مسيرة يوم وفي بعضها: مسيرة ليلة وفي بعضها: مسيرة ثلاثة أيام وفي بعضها: مسيرة بريد والبريد: نصف يوم. قال العلماء رحمة الله عليهم في هذا: أن هذا اختلف بحسب أسئلة السائلين، فبعض السائلين يقول: إذا أرادت المرأة أن تسافر مسيرة يوم، هل لها الخروج؟ فيقول النبي ﷺ: لا تسافر مسيرة يوم، وسائل آخر يقول: ليلة، وسائل آخر يقول: ثلاثة أيام، فأجابه النبي ﷺ على حسب الأسئلة.\nويحتمل أنه ﷺ أجاب بذلك على حسب ما نزل من الوحي، ثم خفف الله جل وعلا في ذلك، فأذن في السفر فيما كان لا يسمى سفرًا، ومنع ما كان يسمى سفرًا.\nفالحاصل: أن التحديد قد يكون للأسئلة، وقد يكون أن الله جل وعلا منع من مسيرة بريد، ثم منع مسيرة يوم وليلة، ثم مسيرة ثلاثة أيام، لحكمةٍ بالغة، ولكن حمل ذلك على أن المقصود هو ما يسمى سفرًا، هو مطابق للأدلة الشرعية، ولهذا في الروايات الأخرى الصحيحة في الصحيحين لم يقيد، بل قال: لا تسافر امرأة إلا مع ذي محرم وأطلق، كما في الصحيح من حديث ابن عباس ، وهذا يجمع الروايات كلها، فكل شيءٍ يسمى سفر، وأقله نصف يوم، وهو البريد، فلا تسافر إليه؛ لأنها عرضة ٌللشر والفساد والخيانة.\nفلا ينبغي لها أن تخاطر بسفرها من دون محرم، والمحرم زوجها وهكذا من تحرم عليه على التأبيد في نسب، كأخيها وأبيها، أو لرضاع كأخيها من الرضاعة وعمها من الرضاعة ونحو ذلك.\nواليوم والليلة بالكيلو ثمانين كيلو تقريبًا، خمسة وسبعين كيلو تقريباً، ونصف اليوم بالكيلو، أربعين كيلو تقريبًا، يعني: يوم وليلة؛ لأنه أربعة وعشرين ساعة، نصفها اثنا عشر ساعة بالكيلو أربعين كيلو تقريبًا.\nفينبغي لها أن تبتعد عما يقارب هذا المعنى، وهو نصف يوم، يعني: أربعين كيلو تقريبًا.\nوأما الشيء العادي في البلد وأطراف البلد فلا يحتاج إلى محرم، إذا كانت مع من تطمئن إليه من النساء، أو كانت في محلٍ آمن، وقرية آمنة لا تخشى شيئًا، فلا بأس أن تخرج في أطراف البلد، وحاجات البلد، ومن بيت إلى بيت، ولو كان كيلو كيلوين ثلاثة أربعة كل هذا لا يضر، إذا كان الأمن متوفراً ولا خطر في ذلك، وليس هناك ريبة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12405/المسافة-التي-يحرم-على-المراة-الخروج-دون-محرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_483/48303.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":14010,"question":"يقول: بعد تمام الأسبوع الأول من الولادة يخرج به شخص معروف لديهم بالشجاعة والحذاقة وكتمان السر، ووالدة المولود تبقى أربعين يومًا في الحجبة لا تطلع من بيتها بل تبقى بداخل غرفة وحدها في إغلاق حتى تنتهي هذه الأربعين اليوم، ويرجو أيضًا التوجيه حول هذا الأمر.الشيخ: أعد أعد. يقول: إن من العادات الباقية لديهم فيما يتعلق بولادة المولود أن يأخذ المولود شخص معروف بالشجاعة والحذاقة وكتمان السر، ووالدة المولود تبقى أربعين يومًا في الحجبة لا تطلع من بيتها بل تبقى بداخل غرفة وحدها في إغلاق لمدة أربعين يومًا، هل هذه الأفعال كما يقول أخونا: هل هذه الأفعال في نظركم فيها شيء من الدين؟ نرجو التوجيه، جزاكم الله خيرًا.","title":"ما حكم عادة حجب النفساء وحدها أربعين يومًا دون ولدها؟","answer":"الجواب: هذا كالذي قبله كله باطل، كله لا أساس له، لا حمل الولد من جهة إنسان معروف بالشجاعة إلى شيء معين يحمله إلى كذا أو إلى كذا أو يذهب به إلى كذا كله هذا لا أساس له، بل المولود يبقى عند والدته لإرضاعه والعناية به من أول ولادته أو يدفع إلى من تحضنه وتربيه وترضعه إذا كانت أمه لا تستطيع ذلك وليس فيها لبن، وأمه كذلك ليس لها أن تحبس نفسها في غرفة ولا في غيرها بل كسائر النساء يخرجن من محل الوالدة وتذهب إلى حاجاتها ولا تغلق عليها غرفة ولا غيرها بل هذا كله باطل وكله تشديد لا وجه له بل هو من الشيطان. نسأل الله السلامة. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12432/ما-حكم-عادة-حجب-النفساء-وحدها-اربعين-يوما-دون-ولدها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_611/61102.mp3","categories":["قضايا المرأة","البدع والمحدثات","اللباس والزينة"]},{"id":14024,"question":"رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول: المرسلة (ج. ع. أ. س) أختنا لها عدد من الأسئلة من بينها سؤال يقول: إذا منعني زوجي من صلة الأرحام هل أطيعه في ذلك، ومن هم الأرحام الذين تجب صلتهم علي؟ جزاكم الله خيرًا.","title":"هل يُطاع الزوج في عدم صلة الرحم؟","answer":"الجواب: إذا منعك الزوج من الصلة لم يلزمك طاعته؛ لأن الرسول  يقول: إنما الطاعة في المعروف، فإذا أمرك بقطيعة الرحم فلا سمع ولا طاعة، لا مانع أن تصلي أرحامك بالمال والدعاء لهم بالتوفيق والهداية ولاسيما إذا كانوا فقراء تحسنين إليهم من الزكاة أو غيرها من مالك لا من ماله هو، لا مانع أن تعطي أرحامك وتصلي أرحامك من مالك أنت لا من ماله هو، أما ماله فلا بد من إذنه، أما مالك أنت إذا وصلت أمك أو أخواتك أو عماتك أو خالاتك بشيء من المال لفقرهن فلا بأس ولا حرج عليك، وإذا كنت تخشين من شره فصليهن سرًا من طريقة خفية لا يعلمها، جمعًا بين المصلحتين؛ حتى تتقي شره وحتى تفعلي المعروف في أقاربك المحاويج من طريق السر ومن طريق الخفية حتى لا يسيء إليك وحتى لا يضرك وحتى لا يتسبب طلاق، نسأل الله للجميع الهداية. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12442/هل-يطاع-الزوج-في-عدم-صلة-الرحم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_611/61112.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":14053,"question":"رسالة وصلت إلى البرنامج من الإمارات العربية المتحدة باعثتها إحدى الأخوات من هناك تقول: أم مجاهد سودانية، أختنا لها جمع من الأسئلة، في أحد أسئلتها تقول: سمعت في البرنامج بتاريخ خمسة عشر ربيع الثاني ألف وأربعمائة وتسعة أحد العلماء أفتى في أن الصبغة للشعر بالسواد إذا كانت للزينة للمرأة المتزوجة لا مانع من ذلك، ولكن هنالك أحاديث تأمرنا باجتناب السواد، ولم تخصص المتزوجات أم غيرهن، والشيء الذي أعلمه أن هنالك أحاديث كثيرة فيها نهي عن أشياء تفعلها المرأة بقصد الزينة، ولم تذكر المتزوجة أو غير المتزوجة، فلماذا تصبغ المتزوجة فقط بالسواد، ولا تفعل الأشياء الأخرى من الزينة؟ وهل صحيح أن المتزوجة مباح لها الزينة المحرمة على غيرها من غير المتزوجات؛ كالصبغة بالسواد مثلاً؟ أفيدونا مأجورين جزاكم الله خيرًا.","title":"حكم صبغ المرأة شعرها بالسواد للزينة","answer":"الجواب: الصواب: أن الصبغ بالسواد محرم مطلقًا، على المتزوجة وغير المتزوجة، وعلى الرجال والنساء؛ لقول النبي ﷺ في الحديث الصحيح: غيروا هذا الشيب وجنبوه السواد، خرجه الإمام مسلم في صحيحه، ولو كان يباح في التغيير، بالسواد لأحد؛ لأباحه النبي ﷺ للصحابة ولوالد الصديق رضي الله تعالى عنهما، بل لما جيء إليه بوالد الصديق فرأى بياض لحيته ورأسه، قال: غيروا هذا الشيب وجنبوه السواد، فالذي أفتى بإباحة السواد للمتزوجة لا أرى وجهًا لفتواه، ولا محل لها.\nوالواجب اجتناب السواد في حق المرأة والرجل، والمتزوجة وغير المتزوجة؛ عملًا بعموم الأحاديث الدالة على ذلك، ومن ذلك: ما رواه أبو داود والنسائي بإسناد صحيح عن ابن عباس رضي الله تعالى عنهما، عن النبي عليه الصلاة والسلام أنه قال: يأتي في آخر الزمان قوم يخضبون بالسواد، كحواصل الحمام، لا يريحون رائحة الجنة، وفي الباب أحاديث عديدة كلها تنهى عن الصبغ بالسواد؛ لما فيه من التدليس، والتلبيس، والخداع.\nفالذي أوصي به جميع الرجال والنساء: الحذر من تغيير الشيب بالسواد، وأما تغييره بالحناء والكتم، أو بالسواد المخلوط بشيء آخر؛ حتى لا يكون أسود، يكون بين السواد والحمرة، أو أحمر خالص، أو أصفر، هذا كله مشروع، والنبي عليه السلام قال: إن اليهود والنصارى لا يصبغون؛ فخالفوهم، فالسنة أن نخالفهم في الصبغ، لكن لا نصبغ بالسواد الخالص.\nونصيحتي لكل مسلم ولكل مسلمة: أن يعتني بسماع هذا البرنامج (نور على الدرب) في أوقاته؛ لما فيه من الفائدة العظيمة، وقد يشتبه عليه فتوى من بعض المشايخ، فيجد حلها في فتوى العالم الثاني في هذا البرنامج، وتزول عنه الشبهة، فهو برنامج عظيم الفائدة، يسره الله عز وجل على يد جماعة من أهل العلم.\nفأنصح جميع إخواني في كل مكان، وجميع أخواتي في كل مكان بالسماع، بالسماع لهذا البرنامج والاستفادة منه، فهو درس عظيم كثير الفائدة، يسره الله لك أيها الأخ ولك أيها الأخت في الله وأنت في بيتك، وفي مجلسك، وعلى سريرك، وفي سيارتك، وهكذا كل أخت في الله يسر الله لها هذا البرنامج، وهي في بيتها وعلى فراشها، في غاية من الراحة، فينبغي حمد الله على ذلك وشكره على ذلك، والدعاء لمن قام بهذا البرنامج بالتوفيق والإعانة على كل خير، وأن يوفقوا للصواب في إصابة الحق، هكذا ينبغي للمؤمن مع إخوانه الذين تحصل له منهم فائدة، يدعو لهم بالتوفيق والسداد وعظيم الأجر.  نسأل الله أن يوفق القائمين على هذا البرنامج لكل ما فيه صلاح المسلمين وسعادتهم، ونسأله سبحانه أيضًا أن يوفق الجميع لإصابة الحق الموافق لما قاله الله ورسوله. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12488/حكم-صبغ-المراة-شعرها-بالسواد-للزينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_608/60807.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":14081,"question":"يقول: سمعت من بعض الناس أن التسليم على المرأة بدون عازل على يدها يعتبر شيئًا محرمًا، فهل هذا صحيح؟","title":"هل يحرم مصافحة الأجنبية؟","answer":"الجواب: لا يجوز للمؤمن أن يصافح النساء إلا إذا كان محرمًا كأخيها وعمها ونحو ذلك، يقول النبي ﷺ: إني لا أصافح النساء لما بايعهن وأرادت مرأة أن تصافحه قال: إني لا أصافح النساء، وقالت عائشة رضي الله عنها: ما مست يد رسول الله ﷺ يد امرأة قط، ما كان يبايعهن إلا بالكلام، فالواجب عدم المصافحة للمرأة الأجنبية ولو من وراء حائل، يسلم عليها بالكلام ويكفي ولا حاجة إلى المصافحة؛ لأن في المصافحة فتنة كالنظر، فالواجب أن يكون السلام بدون مصافحة، يسلم كيف حالك يا فلانة، كيف أولادك؟ كيف زوجك؟ كيف أبوك؟ إلى غير ذلك من دون مصافحة، وليس له الخلوة بالمرأة أيضًا الأجنبية، ليس له مصافحتها ولا الخلوة بها بل يسلم عليها من دون خلوة إلا إذا كانت محرمًا له كأخته وعمته وأمه وبنته ونحو ذلك فلا بأس بذلك، ولا ينبغي التساهل في هذه الأمور؛ لأنها قد تفضي إلى ما لا تحمد عقباه، نسأل الله للجميع الهداية والعافية. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12522/هل-يحرم-مصافحة-الاجنبية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_614/61405.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":14115,"question":"المستمع (ن. هـ. أ. د) بعث برسالة ضمنها جمعًا من الأسئلة في أحدها يقول: قرأت في كتاب فقه المرأة المسلمة أن ما تضع المرأة على وجهها من أدوات التجميل من أحمر الشفاه والمساحيق، والبودرة يعتبر حرامًا، حيث أن صاحب الكتاب أدخل هذا العمل تحت قول رسول الله ﷺ: المغيرات خلق الله، حيث جاء في أول الحديث: اللعن للواشمة والمستوشمة والواشرة والمستوشرة، والمتفلجة للحسن، فهل إدخال صاحب الكتاب لهذه الأمور التي تفعلها المرأة يعتبر صحيحًا وحرامًا؟","title":"حكم استعمال المرأة أدوات التجميل في وجهها","answer":"الجواب: ليس بصحيح وهذا غلط، وليس هذا من تغيير خلق الله، هذا من جنس الكحل، ومن جنس الحناء لا حرج فيه، إذا تحنت أو تكحلت أو غسلت وجهها بشيء .... بالصابون أو غيره مما ينظف الوجه، فكل هذا لا حرج فيه، وهكذا البودرة وتحمير الشفاه، كل هذا لا حرج فيه إن شاء الله، ليس هذا من جنس تغيير خلق الله، تغيير خلق الله من جنس الوشم من جنس الوصل، وأما هذا الممنوع من جنس كبة الشعر .. يسمونها الباروكة، هذا هو الذي فيه المنكر.\nأما كونها تجعل في شفتيها شيء من الحمرة أو من الديرم، أو كحل في عينيها أو ما أشبه ذلك مما يغسل به الوجه كل هذا لا حرج فيه.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12555/حكم-استعمال-المراة-ادوات-التجميل-في-وجهها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_484/48418.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":14123,"question":"ما هو المقياس الشرعي لكون لباس المرأة صفيقًا، وهل ما نعرفه من الألبسة الدارجة يعتبر من لباس المرأة الشرعي؟ وأنا أقصد ما نسميه بالفستان أو الدشداشة، وهل للجلباب الوارد في كتاب الله تعالى مفهوم خاص؟ نرجو أن توضحوا لنا هذه المسألة جزاكم الله خيرًا.","title":"اللباس الشرعي للمرأة","answer":"الجواب: الملابس يختلف فيها الناس وعرفهم، فلكل أحد عرفه في الملابس، والمرأة الواجب عليها ستر العورة باللباس المعتاد في بلادها، تستر عورتها وتستر شعرها عن الأجنبي ووجهها عن الأجنبي بأي طريق، بالجلباب بغير ذلك، المقصود أنها تستر وجهها بما جرت به العادة في بلادهم، فلا تكلف المرأة المغربية بملابس المرأة المشرقية وهكذا، على كل واحدة أن تلبس ما اعتاده أهل بلادها وتجتهد في ستر عورتها بأي نوع من الملابس، حتى لا يراها الأجنبي، وليس هناك مشاحة في أنواع الملابس؛ لأنها عرفية لكل قوم عرفهم في الملابس، وإنما تعتني بستر العورة، وإذا كان عندها أجنبي تستر بدنها تستر وجهها تستر شعرها، بأي نوع من أنواع الملابس، نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12560/اللباس-الشرعي-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_484/48419.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":14155,"question":"السائلة في هذا السؤال أم محمد من القنفذة تقول: حديث الرسول ﷺ الذي فيما معناه: بأن المرأة التي تخرج متطيبة فيجد الرجال ريحها فهي كذا وكذا، تسأل السائلة تقول: بأنها امرأة لا تتطيب عند الخروج وتقول: أتحاشى الخروج بثياب الزينة أو في ثياب فيها أثر للطيب، ولكنني ولشدة الحر في بلدي أجد لنفسي رائحة كريهة من العرق حتى أنني أخرج أحيانًا وأتحرج من مقابلة الناس، وجهوني بعلمكم سماحة الشيخ؟","title":"حكم استعمال المرأة للطيب عند خروجها","answer":"الجواب: ليس للمرأة أن تتطيب عند الخروج طيبًا يحسه الرجال؛ لأن هذا يسبب الفتنة، ولهذا يقول ﷺ: أيما امرأة أصابت بخورًا فلا تشهد معنا العشاء فالمرأة عورة وفتنة، فإذا تطيبت طيبًا يجده الرجال في الطريق صار هذا من أسباب الفتنة.\nأما طيب لا يحسه الرجال ولكنه يكون بين النساء فيما بين النساء تحسه المرأة التي تقبلها أو تصافحها وتقوم منها ولكن لا يحسه الرجال في الطرق فهذا لا يضر، فعليها أن تتحرى الطيب الذي لا تصل رائحته للرجال عند الخروج.\nأما في البيت فلا بأس، تتطيب بما شاءت في الطيب بين النساء وبين محارمها وعند زوجها تتطيب بما يسر الله لها، لكن عند الخروج تجتنب الطيب الذي له رائحة يحس بها الرجال في الطرق. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12596/حكم-استعمال-المراة-للطيب-عند-خروجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_546/54619.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":14181,"question":"ما حكم لبس العمامة في الإسلام، وما حكم تغطية الرأس للرجل؟","title":"حكم لبس العمامة","answer":"الجواب: لا بأس بها، العمامة من الأمور العادية من لبسها فلا بأس ومن تركها فلا بأس؛ لأنها أمور عادية من عادة العرب. نعم.","link":"https://binbaz.org.sa/fatwas/12624/حكم-لبس-العمامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_547/54716.mp3","categories":["اللباس والزينة"]},{"id":14206,"question":"يقول السائل في هذا السؤال الأخير: المرأة هل لها أن تنوع في اللباس أم عليها أن تلبس فقط الجلباب، يقول: وفي مجتمعنا الكثير من البنات إذا كن متحجبات يلبسن السروال وعليه مئزر وأيضًا عليه الجلباب هل هذا حلال أم حرام؟","title":"كيفية لباس المرأة عند النساء وبين الأجانب","answer":"الجواب: المرأة تلبس ما يسر الله لها من الزينة بين نسائها وعند زوجها مع التستر عن الأجنبي، أما عند نسائها وعند محارمها تلبس اللباس المعتاد، لا حرج من لبس الزينة التي يلبسها أمثالها، ولا بأس بإظهار وجهها ويديها وقدميها عند نسائها ومحارمها هذا لا حرج فيه، وإنما الحجاب عن الأجنبي عليها أن تحتجب وتستتر عمن ليس محرمًا لها في وجهها وجميع بدنها، وليس لها أن تلبس شيئًا يكون فيه مشابهة للكفار؛ لقوله ﷺ: من تشبه بقوم فهو منهم ولا تلبس أشياء يكون فيها شهرة تخالف أهل بلدها تترك الشهرة تلبس لباس أهل بلدها وما اعتاده أهل بلدها حتى لا يكون ثوب شهرة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12654/كيفية-لباس-المراة-عند-النساء-وبين-الاجانب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_548/54807.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":14256,"question":"بلغني أن لبس الساعة اليدوية محرم، وذلك قياسًا على الخاتم الحديد المنهي عن لبسه وهي مصنوعة من الحديد، فهل هذا صحيح؟ وما رأيكم هل نلبس الساعة أم لا؟ صاحب هذا السؤال من صبيا هو المستمع: عبد اللطيف علي ناصر خواجي.","title":"حكم لبس الساعة اليدوية","answer":"الجواب: الصواب أنه لا حرج في ذلك، لا حرج في لبس الساعة ولا في لبس الخاتم من الحديد، وإنما المحرم لبس الخاتم من الذهب على الرجل، أما لبس الخاتم من الفضة أو من الحديد أو الساعة كل ذلك لا بأس به، وقد ثبت عنه ﷺ أنه قال لرجل خطب امرأة: التمس ولو خاتمًا من حديد رواه الشيخان في الصحيحين.\nفلو كان الخاتم من حديد ممنوعًا لما قال له: التمس ولو خاتمًا من حديد، وما جاز للرجل جاز للمرأة إلا ما حرمه الشرع أو خص به المرأة أو الرجل، والذي خص به المرأة هو خاتم الذهب، فهذا هو الذي لا يجوز للرجل ويجوز للمرأة، أما خاتم الفضة وخاتم الحديد فمشترك.\nأما حديث أنه ﷺ لما رأى على إنسان خاتمًا من حديد قال: مالي أرى عليك حلية أهل النار!، ولما رأى خاتم من صفر قال: مالي أرى عليك ريح الأصنام، فهما حديثان شاذان مخالفان للأحاديث الصحيحة، والشاذ عند أهل العلم يعتبر ضعيفًا لمخالفته الأدلة الشرعية.\nوالساعة إذا كانت على الطريقة التي يلبسها الرجال ليس فيها تشبه بالنساء فلا بأس بها ولا تكن من الذهب ولا تكن من الفضة بل تكون من غير ذلك يلبسها الرجل، والمرأة تلبس ما يناسبها، فلا يلبس الرجل ما كان من خصائص المرأة، ولا المرأة ما كان من خصائص الرجل، كل منهما يلبس ما يليق به سواء كان لبسها في اليمنى أو في اليسرى كالخاتم، الرسول عليه السلام لبسه تارة في اليمنى وتارة في اليسرى وهو من الفضة، والساعة تشبه الخاتم فإذا لبسها في اليمين أو في اليسار فلا حرج في ذلك، لكن لا تكن من الفضة هذا هو الذي ينبغي اقتصارًا على ما ورد في الخاتم فقط في حق الرجل.\nأما الذهب فلا يجوز للرجل لا خاتم ذهب ولا ساعة الذهب كلاهما، نعم، وفق الله الجميع.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12812/حكم-لبس-الساعة-اليدوية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_622/62214.mp3","categories":["الحكم على الأحاديث","اللباس والزينة"]},{"id":14258,"question":"تقول أختنا: عندما قدمت لأداء فريضة الحج أتيت برفقة أمي وشقيقتي وزوج شقيقتي، هل أمي وشقيقتي وزوجها محرم لي؟","title":"هل الأم والأخت وزوجها من المحارم؟","answer":"الجواب: المحرم إنما يكون ذكرًا لا أنثى، والمحارم هم من تحرم عليهم المرأة على التأبيد بنسب كأبيها وأخيها، أو سبب كالرضاعة، والمصاهرة كزوج بنتها، وزوج أمها، فإنهم محارم، زوج أمها بالمصاهرة وزوج بنتها بالمصاهرة وأخيها من الرضاع أو عمها من الرضاع بسبب الرضاع، وأخيها من النسب وأبيها من النسب بسبب القرابة. أما المرأة فلا تكون محرمًا أم المرأة وأختها وعمتها لسن محارم، يقول ﷺ: لا تسافر امرأة إلا مع ذي محرم، ثم ذكر في بعض الروايات الزوج، ذكر الزوج وذكر الأخ ونحو ذلك.\nالمقصود أن المحرم إنما يكون رجلًا لا أنثى، وهو من تحرم عليه على التأبيد بنسب أو صهر مباح كأبيها وأخيها وعمها وخالها من نسب أو رضاع، وهكذا زوج أمها وزوج بنتها وزوج ابنة ابنها وبنت بنتها كلهم محارم. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12764/هل-الام-والاخت-وزوجها-من-المحارم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_621/62110.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":14284,"question":"رسالة وصلت إلى البرنامج من السودان لكن لم أجد داخل الرسالة اسم المرسل ولا على الظرف، على أي حال الأسئلة تقول: هل حجاب المرأة له لون وشكل محدد لا يجوز مخالفته؟ أم أن أي لبس ساتر لجميع جسم المرأة وغير ضيق يعتبر حجاب حتى تستطيع كل امرأة لا تلبس الحجاب بحجة أنه ملفت للنظر في بلدتهم ستر جميع بدنها بزيها الشعبي وسد النظرات عنها، ويرجو التوجيه شيخ عبد العزيز، جزاكم الله خيرًا.","title":"هل يشترط في الحجاب لونًا وشكلًا معينًا؟","answer":"الجواب: ليس للحجاب فيما نعلم لون مخصوص ولا صفة مخصوصة، بل الواجب على المرأة أن تحتجب بما تيسر لها من الملابس التي تعتادها في بلادها وبين قومها، وليس هناك شيء مخصوص إلا أنها تجتنب ما يلفت النظر وما يسبب الفتنة من الملابس الجميلة التي تلفت الأنظار إليها وربما جرت إلى شر، فتحرص على حجاب لا يلفت النظر ولا يكون فيه دعوة إلى الفتنة، ولا تشبه بالرجال، تكون ملابس نسائية ليس فيها ما يجر إلى الشر، هذا هو المشروع لها، ونسأل الله للجميع التوفيق. نعم.\nالمقدم: جزاكم الله خيرًا، لا يشترط أن يكون عباءة أو كاب أو نوع ..؟\nالشيخ: ما في شرط، نعم. ما يسر الله تفعله.\nالمقدم: المهم أن يكون حجاب فقط.\nالشيخ: ساترًا، أن يكون حجابًا ساترًا، نعم. ليس فيه ما يلفت النظر ويسبب الفتنة، وليس فيه مشابهة لملابس الرجال. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12774/هل-يشترط-في-الحجاب-لونا-وشكلا-معينا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_618/61805.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":14289,"question":"تسأل وتقول: هل يجوز للمرأة أن تقص شعرها؟","title":"هل يجوز للمرأة أن تقص شعرها؟","answer":"الجواب: لا بأس أن تخفف شعرها وإذا كان لها زوج فلا بد من مشاورته؛ لأنه زينة الرأس زينة وجمال وإذا اتفقت مع زوجها على قص بعضه للتخفيف لأنه طويل أو يشق عليها، فقد ثبت عن أزواج النبي ﷺ بعد وفاته أنهن قصصن من رءوسهن للتخفيف. نعم.\nالمقدم: الله المستعان.","link":"https://binbaz.org.sa/fatwas/12747/هل-يجوز-للمراة-ان-تقص-شعرها ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_486/48614.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":14290,"question":"المستمعة التي رمزت لاسمها ب: (أ. م. س) من الرياض تقول: هل يجوز لي يا سماحة الشيخ أن أسافر مع زوج أختي ومعه أختي وأولادها وليس معي محرم سواه؟","title":"حكم سفر المرأة مع أختها وزوجها وأولادهما","answer":"الجواب: ليس لك السفر مع زوج أختك؛ لأنه ليس محرمًا لك، فالواجب ترك ذلك لقول النبي ﷺ: لا تسافر المرأة إلا مع ذي محرم، وزوج أختك أو زوج عمتك ليس محرمًا لك، محرمك أخوك أو أبوك أو ابنك أو نحو ذلك أو زوج بنتك محرمًا لك أو زوج أمك كذلك محرم، أما زوج أختك فلا. نعم.\nالمقدم: إذا كانت داخل المدينة سماحة الشيخ؟\nالشيخ: لا بأس داخل المدينة ما هو بسفر، تروح مع أختها ........، هذا ليس بسفر، التنقل في المدينة أو الذهاب إلى المستشفى أو المحكمة من غير خلوة لا بأس.","link":"https://binbaz.org.sa/fatwas/12749/حكم-سفر-المراة-مع-اختها-وزوجها-واولادهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_549/54920.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":14291,"question":"تقول السائلة: هل عدم الجواز في لبس النقاب هو النقاب بحد ذاته، أم طريقة اللبس؟ مع العلم بأنني ألبس النقاب ولكنني لا أكشف عن عيوني أبدًا إلا للضرورة.","title":"حكم لبس النقاب","answer":"الجواب: النقاب محرم على المحرمة، إذا كانت المرأة محرمة بحج أو عمرة ليس لها أن تلبس النقاب، أما غير المحرمة فلها أن تلبس النقاب؛ لأنها محتاجة إلى أن ترى طريقها، فإذا فتحت لعينيها أو لإحدى العينين شيء فلا بأس، بقدر العينين أو العين الواحدة. نعم.","link":"https://binbaz.org.sa/fatwas/12751/حكم-لبس-النقاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_549/54921.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":14292,"question":"تسأل سؤالها الأخير وتقول: هل يجوز للمرأة أن تصلي ولو لم تكن لابسة لعباءة أو أي غطاء آخر؟","title":"صفة اللباس الشرعي للمرأة في الصلاة","answer":"الجواب: لا بد من ستر عورتها بملابس ساترة تستر بدنها كله مع الرأس ما عدا الوجه، تستر الرأس والبدن كله الرجلين والبدن كله بجلال أو عباءة أو غيرهما تستر بدنها كله، بثوبها أو بجلال عليها ما عدا الوجه وهكذا الكفان لو ظهرا لا يضر ظهورهما لكن سترهما أفضل، أما القدمان فلا بد من سترهما مع القدرة؛ لأن المرأة عورة ولا بد من هذا في حقها، لقوله ﷺ: لا يقبل الله صلاة حائض إلا بخمار، الحائض: يعني: البالغة إلا بخمار هو الثوب الذي يوضع على الرأس ويقال لها: الشيلة تستر بها الرأس.\nأما الوجه فالسنة إبرازه في الصلاة تصلي المرأة ووجهها بارز ظاهر غير مستور إلا إذا كان عندها أجنبي فإنها تستر وجهها كأخي زوجها أو عم زوجها أو غيرهما من الأجانب الذين ليسوا محارم، وأما إذا كان ما عندها إلا نساء أو زوجها فإنها لا تستر وجهها بل تكشف وجهها، والأفضل ستر الكفين أيضًا وإن كشفتهما فلا حرج على الصحيح، أما الرجلان فالواجب سترهما. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12752/صفة-اللباس-الشرعي-للمراة-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_486/48615.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":14296,"question":"تقول في آخر أسئلتها: ما أقصى حد للبس الكم القصير بالنسبة للمرأة؟","title":"حكم لبس المرأة لقصير الكم من الملابس","answer":"الجواب: لا بأس أن تلبس الكم القصير بين النساء، لكن الأفضل أن تكون أكمامها تامة حتى يتعلم غيرها منها الحشمة عند النساء وعند المحارم، هذا هو الأولى في حقها، تكون محتشمة وكمها إلى مفصل الكف إلى نهاية الذراع، هذا هو الأولى والأفضل والأحوط حتى لا يتأسى بها غيرها، وحتى لا يدخل عليها من ليس بمحرم.\nفالمقصود أن كونها تلبس أكمام وافية إلى الرسغ إلى مفصل الذراع من الكف يكون هذا أكمل بين النساء وعند المحارم وإلا فالذراع ليس بعورة عند النساء والمحارم، لكن كونها تستكمل الكم يكون أكمل وأفضل وأبعد عن الريبة.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12760/حكم-لبس-المراة-لقصير-الكم-من-الملابس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_549/54924.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":14326,"question":"السائلة تقول في هذا السؤال سماحة الشيخ: هل وضع العباءة على الكتف أثناء الصلاة فيه شيء؟ علمًا بأن وضعها على الرأس يكون أثناء خروجنا من المنزل وجهونا بذلك؟","title":"حكم وضع المرأة العباءة على الكتف أثناء الصلاة","answer":"الجواب: وضعها على الكتفين لا يجوز؛ لأنها تشبه بالرجال، ولكن تلبس شيء من رداء جلال وقت الصلاة مقطعًا إضافي يغطي رجليها فيكفي والحمد لله، مع تغطية الرأس.\nفالحاصل أن لبس المشلح كالهيئة التي يلبسها الرجال لا يجوز، لا في الصلاة ولا في غيرها؛ لأن الرسول ﷺ نهى عن التشبه بالرجال، وقال: لعن الله المرأة تلبس لبسة الرجل، ولعن الله الرجل يلبس لبسة المرأة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12798/حكم-وضع-المراة-العباءة-على-الكتف-اثناء-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_550/55010.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":14372,"question":"تقول السائلة: هل يجب الحجاب على المرأة من الصبي الذي بلغ الحادية عشرة أو الثانية عشرة أم لا يجب؟ وما هو الضابط في حجاب المرأة عن الصبي؟","title":"ما ضابط احتجاب المرأة من الأطفال؟","answer":"الجواب: الضابط أنها تحتجب عمن بلغ، ومن كان مراهقًا؛ لأنه قد يكون بلغ و لا تدري عنه، إذا كان مراهقًا يحتجب عنه، أو علمت أنه قد بلغ خمسة عشر سنة، أو احتلم، أو أنبت تحتجب عنه؛ لقوله -جل وعلا-: وَإِذَا بَلَغَ الأَطْفَالُ مِنْكُمُ الْحُلُمَ فَلْيَسْتَأْذِنُوا [النور:59] دل على أنهم قبل الحلم ما عنهم غطاء، ما يلزمهم الاستئذان، فإذا بلغوا الحلم استأذنوا، والمراهق قد بلغ الوقت الذي يناسب فيه الاستئذان، فإذا استأذن لئلا يغشهم فلا بأس. المقصود: أنه يلزمه إذا بلغ الحلم، يلزمه، وإذا كان مراهقًا واستأذن للحيطة وحماية نفسه مما قد يضره، فهذا حسن.\nالمقدم: جزاكم الله خيرًا، إذًا إحدى عشر سنة أو اثنا عشر سنة يا شيخ ما في شيء؟\nالشيخ: ما هو بالظاهر، هؤلاء ما قاربوا، ما قاربوا، نعم. المقدم: بارك الله فيكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12853/ما-ضابط-احتجاب-المراة-من-الاطفال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_551/55115.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":14377,"question":"الفقرة الأخيرة في سؤال السائل يقول: ما حكم لبس الملابس ذات الأكمام القصيرة بالنسبة للمرأة عند المرفقين أمام الأب والإخوة؟جزاكم الله خيرًا.","title":"حكم لبس المرأة لقصير الأكمام أمام المحارم","answer":"الجواب: الأفضل لها التستر؛ لأن هذا قد يفضي إلى شر، فالأفضل لها ألا تبدي ذراعيها عند أبيها وإخوتها، تكون أكمامها كاملة، هذا هو الأفضل والأحوط، ذراعها ليس بعورة بالنسبة إلى أبيها، لكن كونها تستره أولى وأحوط، وأبعد عن الشر.","link":"https://binbaz.org.sa/fatwas/12858/حكم-لبس-المراة-لقصير-الاكمام-امام-المحارم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_551/55120.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":14410,"question":"ما حكم تركيب الأظافر؟ تقول: علمًا بأنني أجتهد أن لا يراها الرجال أبدًا، وهل ذلك داخل في حكم الواصلة الواردة في الحديث؟","title":"ما حكم تركيب المرأة للأظافر؟","answer":"الجواب: تركيب الأظفار لا أصل له، ولا يجوز تركيب الأظفار، بل الواجب والسنة قصها وقلمها في أقل من أربعين، يقول أنس : «وقت لنا في قص الشارب، وقلم الظفر، ونتف الإبط، وحلق العانة أن لا ندع هذا أكثر من أربعين ليلة» وفي اللفظ الآخر: «وقّت لنا رسول الله ﷺ»، فالرجل والمرأة مأموران بقلم الأظفار في أقل من أربعين ليلة، فكيف تجعل لها أظفار هذا منكر لا وجه له، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12892/ما-حكم-تركيب-المراة-للاظافر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_553/55307.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":14413,"question":"في آخر أسئلة هذا السائل من الرياض يقول: هل يجوز لبس الماس بالنسبة للرجال سماحة الشيخ؟","title":"حكم لبس الرجال للماس","answer":"الجواب: ما أعلم فيه بأسًا، الماس من جنس الفضة، فالمحرم الذهب، يحرم على الرجال الذهب، ويباح للنساء، أما الماس فلا أعلم فيه شيئًا، والأصل الإباحة، كما يباح لبس خاتم الفضة، أما إذا كان الماس يعني: أغلى من الذهب، وأحب يتورع لا بأس الأصل الجواز؛ لأن التحليل بيد الشرع ليس بيد الناس، والشرع حرم الذهب، ولم يحرم الفضة، ولم يحرم الحديد، فإذا قال النبي ﷺ: التمس ولو خاتمًا من حديد لو لبس خاتم من حديد أو من فضة أو من صفر لا بأس، المحرم على الرجل خاتم الذهب، والماس ليس من الذهب لا يسمى ذهبًا وإن كان غاليًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12895/حكم-لبس-الرجال-للماس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_553/55310.mp3","categories":["اللباس والزينة"]},{"id":14437,"question":"يسأل أيضًا أخونا ويقول: ما هو نوع صلة القرابة بين شخص ما وبين ابنة زوج أخته، ولكن البنت من امرأة أخرى ليست من أخت الشخص المذكور؟","title":"هل بنت زوج الأخت من غيرها من الأرحام؟","answer":"الجواب: هذه ليست قريبة له، هذه ليست من أرحامه، ولا قريبة له، وإذا أحسن إليها؛ لأنها بنت زوج أخته، فلا بأس بذلك، لكن ليست قريبة له، إنما تكون قريبة لو كانت بنت أخته يكون هو خالها، فيحسن إليها كما يحسن إلى بقية الأرحام، أما بنت لزوج أخته ليست منها فلا تعتبر من أقاربه، نعم.\nالمقدم: ما هي صلة القربى أيضًا بين الشخص نفسه وبين زوج البنت نفسها لو تزوجت مثلًا، وهل يعتبر زوج البنت التي ليست من شقيقته من ذوي الأرحام الذين لا يجوز مقاطعتهم؟\nالشيخ: زوج البنت يسمى صهرًا، وليس رحمًا، فإذا أحسن إليه من أجل المصاهرة فهذا مما ينبغي أن يفعل؛ لأن المصاهرة لها صلة بالناس كصلة الرحم من جهة التقارب والاجتماع والتعاون، فإذا وصل زوج أخته أو زوج بنت أخته أو زوج بنت عمه من باب الإكرام لقرابته، ومن باب الإحسان فهذا حسن، ولكن ليس قريبًا، إنما هي قرابة المصاهرة، ومن عادة المسلمين إكرام الأصهار والإحسان إليهم وتقديرهم؛ لأن ذلك في ضمن الإحسان إلى الأقارب الذين هم بنات عمه أو خالاته أو أخواته وهن زوجات هؤلاء الأصهار. فالحاصل: أنّ الصهر ليس من الأقارب، ولكنه قريب إلى الأقارب بالمصاهرة، فيحسن إليهم من أجل المصاهرة فقط، ويكرم من أجل المصاهرة إكرامًا للقرابات كبنت أخيه وبنت أخته وأخته وعمته وخالته، فأزواجهن لهم حق المصاهرة من باب الإحسان إلى قراباته وبنات عمه ونحوهن، لا أن الأزواج يعتبرون من الأرحام لا، ولكنهم يعتبرون أصهارًا يحسن إليهم، ويكرمون إكرامًا للقرابات، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12937/هل-بنت-زوج-الاخت-من-غيرها-من-الارحام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_624/62408.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":14458,"question":"هذه السائلة أم وليد من الدمام، تقول: سماحة الشيخ، سمعت حديثًا عن رسول الله ﷺ فيما معناه بأنه: \"من صلى الفجر في جماعة، ثم جلس في مصلاه، أو في عبادة الله حتى تطلع الشمس بمقدار رمح في السماء، كان له أجر حجة وعمرة تامة تامة\" وأنا يا سماحة الشيخ لا أستطيع تقدير هذا الوقت، وأرجو من سماحتكم بيان مقدار هذا الوقت بالدقائق، مأجورين.","title":"فضل الانتظار بعد الفجر إلى طلوع الشمس","answer":"الجواب: هذا حديث لا بأس به، جاء له من طرق لا بأس به: من صلى الفجر وجلس في مصلاه حتى تطلع الشمس، وترتفع هذا فيه فضل عظيم، ثم صلى ركعتين، كان النبي ﷺ يجلس في مصلاه الفجر في الغالب حتى تطلع الشمس طلوعًا حسنًا. فإذا جلس الإنسان الرجل في مصلاه، أو المرأة في مصلاها، فإذا ارتفعت الشمس صلى ركعتين هذا كله طيب وحسن، وهو بعد الربع الساعة تقريبًا من طلوع الشمس، فإن طلوع الفجر إلى طلوع الشمس نحو ساعة ونصف، ثم بعد نحو ربع ساعة يعني: بعد طلوع الفجر بنحو ساعتين إلا ربع أو ساعتين إلا عشر يكون في ذلك قد ارتفعت الشمس، فهذا الوقت إذا صلى فيه ركعتين فيه خير عظيم، أو أكثر من ذلك، نعم. المقدم: جزاكم الله خيرًا، سماحة الشيخ تقول السائلة: هل ينطبق أيضًا هذا على النساء؟\nالشيخ: عام الحديث للنساء والرجال جميعًا، الحكم عام.","link":"https://binbaz.org.sa/fatwas/12935/فضل-الانتظار-بعد-الفجر-الى-طلوع-الشمس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_554/55414.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":14461,"question":"من اليمن السائل (أ. ع. م) يقول في هذا  ما حكم التطيب ببعض العطور؟علمًا بأن بعضها يحتوي على تسعين بالمائة من الكحولات، وهل هي تنجس المؤمن أو ثياب المؤمن أم ماذا؟","title":"حكم استعمال العطور المحتوية على كحول","answer":"الجواب: إذا كان الطيب فيه مسكر، فيه نوع من المسكرات حرم استعماله؛ لقول النبي ﷺ: ما أسكر كثيره فقليله حرام وقال: كل مسكر حرام هكذا قال ﷺ، فإذا علم أنّ هذا الطيب، أو هذا الشراب، أو هذا الطعام كثيره يسكر حرم، وأكثر أهل العلم على أن ما أسكر فهو نجس، فينبغي توخي ذلك، إذا أصابه شيء من الخمر أصاب ثوبه فإذا غسله يكون حسن إن شاء الله من باب الاحتياط. المقصود: أن ما أسكر كثيره من طعام أو شراب فهو نجس عند الجمهور، وهو محرم عند الجميع؛ عند جميع العلماء ما أسكر كثيره فقليله حرام فإذا كان إذا شرب منه مثلاً كأس سكر، وإذا كان شرب نصف كأس ما يسكر فهو حرام كله قليله وكثيره، نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12942/حكم-استعمال-العطور-المحتوية-على-كحول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_554/55416.mp3","categories":["اللباس والزينة"]},{"id":14470,"question":"في آخر أسئلة هذه السائلة من اليمن تقول: سماحة الشيخ نحن نعلم بأن الحجاب واجب على المرأة، ولكن بعض النساء لا يتحجبن، ويقلن: نعلم أنه واجب، ولكن لا نستطيع على ذلك، ونخاف أن يتكلم الناس علينا بأقوال غير مستحبة، ونستحي منهم، ويقلن أيضًا: بأننا واثقات من الله ، وأملنا بالله كبير، والله غفور رحيم، فما هي نصيحتكم لمثل هؤلاء النسوة سماحة الشيخ؟","title":"حكم ترك المرأة للحجاب بحجة انتقاد الناس","answer":"الجواب: الواجب على النسوة التحجب، والأخذ بتعاليم الشرع، والاستقامة على ذلك، ولا يجوز لأحد أن يخالف الشرع بمعنى أنه يحسن الظن بالله، أو من أجل مجاملة فلان أو فلان، أو لئلا ينتقدها فلان، هذا غلط ومنكر، يجب الأخذ بالشرع والتمسك بالشرع ولو قال فلان كذا أو كذا، ولو انتقدها الناس وقالوا: إنها كذا، وإنها متحجرة، أو إنها غالية، أو إنها مشددة، هذا لا يهمها، الله يقول سبحانه: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] جعلها طهارة لقلوب الجميع، وقال سبحانه في سورة النور: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ [النور:31] الآية. فالواجب على المرأة التحجب والتستر عن الأجنبي، أما عن زوجها ومحارمها فلا بأس أن يروا وجهها ويديها لا بأس، أما أن تكشف للأجناب؛ لأخي زوجها، أو لابن عمها، أو لجيرانها، أو لجلسائها لا يجوز، بل يجب التستر والبعد عن الريبة والخطر، ولا تجوز الخلوة أيضًا بالرجل الأجنبي، وليس لأحد أن يترخص بمجاملة، أو بأن الله عفو غفور، أو ما أشبه ذلك، فهو سبحانه عفو غفور وهو شديد العقاب أيضًا ، كما قال : نَبِّئْ عِبَادِي أَنِّي أَنَا الْغَفُورُ الرَّحِيمُ  ۝ وَأَنَّ عَذَابِي هُوَ الْعَذَابُ الأَلِيمُ [الحجر:49-50] وقال سبحانه: غَافِرِ الذَّنْبِ وَقَابِلِ التَّوْبِ شَدِيدِ الْعِقَابِ [غافر:3]. فالواجب على جميع المؤمنين والمؤمنات الأخذ بتعاليم الشرع، والتمسك بتعاليم الشرع، وأداء فرائض الله، والحذر من محارم الله، ولو كره الناس، ولو انتقدهم الناس، فالله أحق أن يستحيا منه، وأحق أن يؤخذ بأمره، وأن ينتهى عما نهى عنه ، نعم.","link":"https://binbaz.org.sa/fatwas/12955/حكم-ترك-المراة-للحجاب-بحجة-انتقاد-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_554/55420.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":14491,"question":"المستمعة (م. ع) من الرياض، بعثت تسأل عن قص الشعر بالنسبة للمرأة، ولا سيما مما هو تحت الأذن، هل يجوز ذلك أو لا يجوز؟","title":"هل يجوز قص الشعر بالنسبة للمرأة؟","answer":"الجواب: الشعر من الجمال، كلما طال فهو من جمال المرأة، والمرأة تمدح بطول الشعر، ووفرة الشعر، فإذا تركته فهو أولى لها، لما فيه من الجمال، وإذا دعت الحاجة إلى تخفيفه، أو قص من طوله فلا بأس به، لا حرج في ذلك، ليس في الأدلة ما يمنع ذلك، وإذا كان لها زوج فتستشيره؛ لأن هذا يتعلق بالجمال، فإذا وافق على تخفيفه فلا بأس بذلك، وأما إذا لم يوافق فلا تعصه؛ لأن له مصلحة في طوله وجمالها به. قد ثبت أنّ أزواج النبي ﷺ بعد وفاته جززن من رؤوسهن من أجل الكلفة والمئونة، فإذا جزت المرأة من رأسها للكلفة والتعب فلا بأس، أو لأنه أجمل عند زوجها وأكمل، ويحب زوجها ذلك فلا بأس، أما إن كان لأجل مشابهة الكافرات فلا يجوز، التشبه بالكافرات، لا يجوز، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12961/هل-يجوز-قص-الشعر-بالنسبة-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_488/48811.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":14492,"question":"في سؤال ثانٍ لهذه السائلة أم عبدالله تقول: لبس الرجل للثوب الطويل من غير قصد الخيلاء ولا رغبة في الطويل، وإنما لأسباب قد يكون منها عدم توفر القصير في يوم من الأيام أو الاتساخ لهذا الثوب القصير، وما أشبه ذلك، هل هذا من الإسبال المحرم؟","title":"حكم لبس الرجل للطويل من الثياب","answer":"الجواب: نعم، لا يجوز لبس الطويل مطلقًا، ولو قال: إنه لا يتكبر، الله حرم ذلك، يقول النبي ﷺ: ما أسفل من الكعبين من الإزار فهو في النار ويقول ﷺ: ثلاثة لا يكلمهم الله، ولا ينظر إليهم يوم القيامة، ولا يزكيهم، ولهم عذاب أليم: المسبل إزاره، والمنان فيما أعطى، والمنفق سلعته بالحلف الكاذب أخرجه مسلم في الصحيح، ولم يشترط أن يكون أراد الخيلاء، لكن إذا أراد الخيلاء يكون الذنب أعظم، كما قال ﷺ: من جر ثوبه خيلاء لم ينظر الله إليه يوم القيامة هذا يكون ذنبه أعظم، ويكون الإثم أكثر.  ثم الغالب أنّ من جر ثوبه في الغالب أنه خيلاء، وإذا زعم أنه ليس بخيلاء فلا ينبغي تصديقه. وإنما يقال له: اترك هذا، احذر هذا، فالرسول ﷺ نهاك عن هذا، وإذا كان طويلًا يقصه، وإلا يخبنه حتى يرتفع، حتى لا ينزل عن الكعبين، نعم.","link":"https://binbaz.org.sa/fatwas/12960/حكم-لبس-الرجل-للطويل-من-الثياب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_554/55422.mp3","categories":["اللباس والزينة"]},{"id":14498,"question":"الجواب:ما رأي الشرع إذا رفضت المرأة الحجاب؟علمًا بأنّ النساء عندنا لا يحتجبن، فما هو توجيهكم؟جزاكم الله خيرًا.","title":"كيفية التعامل مع من ترفض الحجاب","answer":"الجواب: تعالج الأمور بالحكمة، المؤمن يعالجها بالحكمة، يدعوها إلى الحجاب، ويبيّن لها حكم الحجاب، وأنه واجب، وأن الله شرع لها الحجاب، وأنها عورة وفتنة إذا لم تحتجب، يعالج الأمور بالحكمة، والكلام الطيب، يقول الله سبحانه: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] فيتلو عليها هذه الآية، ويبيّن لها حكم الحجاب، وهكذا قوله سبحانه: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ [النور:31] الآية، وهكذا قوله سبحانه: يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلابِيبِهِنَّ ذَلِكَ أَدْنَى أَنْ يُعْرَفْنَ فَلا يُؤْذَيْنَ [الأحزاب:59]. وفي الصحيحين عن عائشة -رضي الله عنها- أنها قالت: لما سمعت استرجاع صفوان في الغزوة التي جرى فيها كلام أهل الإفك، قالت: لما سمعت صوته تخمرت، وعرفني؛ لأنه كان قد رآني قبل الحجاب، يعني: قبل أن نؤمر بتخمير الوجه؛ لأنه قد رآني قبل الحجاب، فعرفني، فلما سمعت صوته خمرت وجهي. دل على أنه قد استقر عندهم بعد نزول آية الحجاب أنّ الوجه يخمر ويستر، وهذا أطهر للقلوب، وأنفع وأبعد عن الشبهة، وأبعد عن الشر، فأنت يا عبدالله تعالج الزوجة بالكلام الطيب، والأسلوب الحسن، حتى تستقيم -إن شاء الله-، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12973/كيفية-التعامل-مع-من-ترفض-الحجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_488/48815.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":14500,"question":"رسالة من المستمع عبدالقادر بلال يقول: هل يوجد دليل واضح من كتاب الله يحرم مصافحة المرأة الأجنبية؟علمًا بأنني ملتزم بعدم المصافحة، جزاكم الله خيرًا.","title":"أدلة تحريم مصافحة المرأة","answer":"الجواب: نعم، مصافحة النساء الأجنبيات لا تجوز؛ لأن الرسول ﷺ قال: إني لا أصافح النساء وقالت عائشة -رضي الله عنها-: «والله ما مست يدي رسول الله ﷺ يد امرأة قط، ما كان يبايعهن إلا بالكلام» والقرآن يقول الله فيه: لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ لِمَنْ كَانَ يَرْجُو اللَّهَ وَالْيَوْمَ الآخِرَ [الأحزاب:21] ويقول الله سبحانه في القرآن: وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا [الحشر:7] ويقول سبحانه: قُلْ أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ فَإِنْ تَوَلَّوا فَإِنَّمَا عَلَيْهِ مَا حُمِّلَ وَعَلَيْكُمْ مَا حُمِّلْتُمْ وَإِنْ تُطِيعُوهُ تَهْتَدُوا [النور:54] فطاعة الرسول ﷺ واجبة علينا وفيها الهداية، وكان لا يصافح النساء لما في هذا من الفتنة، لمس يد المرأة فيه فتنة، قال بعض أهل العلم: إنه أشد من النظر. والحمد لله الذي منّ عليك بعدم المصافحة، فاثبت على هذا، ولا تصافح النساء إلا إذا كن من محارمك أختك وعمتك لا بأس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12986/ادلة-تحريم-مصافحة-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_488/48817.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":14508,"question":"رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات وقعت في نهاية رسالتها بقولها: أم معاذ تسأل وتقول: هل يجوز أن ترتدي المرأة الذهب فوق الحجاب، فهناك العديد من الفتيات يفعلن ذلك، وقد قلت: إنه حرام، وإنه زينة، قالوا: لا، إنها زينة ظاهرة وغير مقصودة، فما هو الحكم في هذا؟ وما معنى الزينة الظاهرة وهي حسب علمي: أنّ الزينة الظاهرة هي الثياب، والله أعلم. أرجو إفادتي، وإفادة الأخوات حول هذه القضية. جزاكم الله خيرًا.","title":"حكم إظهار المرأة الحلي ونحوها فوق الحجاب","answer":"الجواب: إبداء الذهب، وسائر الحلي من ماس وغير ماس إبداؤه من الزينة التي حرم الله إبداءها للرجال الأجانب، كما يحرم عليها إبداء شعرها، وسائر بدنها كوجهها وحلقها وصدرها، ونحو ذلك، كذلك إبداء الذهب، وإبداء الأسورة والقلائد كل ذلك لا يجوز؛ لقوله سبحانه: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ [النور:31] فوجهها وما يكون في صدرها من القلائد، وما يكون في حلقها، وما يكون في رأسها كل ذلك من الزينة التي يحرم إبداؤها، والذهب من أحسن الزينة، فلا يجوز لها إبداء ما يفتن الرجال، ويسبب الميل إلى المرأة، ولكن تجتهد في ستر ذلك بالملابس والأجلة، ونحو ذلك، حتى لا يبدو منها شيء، إلا عينها، إلا العين أو العينين، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13007/حكم-اظهار-المراة-الحلي-ونحوها-فوق-الحجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_626/nour_62605.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":14515,"question":"رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات وقعت في نهاية رسالتها بقولها: أم معاذ تسأل وتقول: هل يجوز أن ترتدي المرأة الذهب فوق الحجاب، فهناك العديد من الفتيات يفعلن ذلك، وقد قلت: إنه حرام، وإنه زينة، قالوا: لا، إنها زينة ظاهرة وغير مقصودة، فما هو الحكم في هذا؟ وما معنى الزينة الظاهرة وهي حسب علمي: أنّ الزينة الظاهرة هي الثياب، والله أعلم. أرجو إفادتي، وإفادة الأخوات حول هذه القضية. جزاكم الله خيرًا.","title":"حكم إظهار المرأة الحلي ونحوها فوق الحجاب","answer":"الجواب: إبداء الذهب، وسائر الحلي من ماس وغير ماس إبداؤه من الزينة التي حرم الله إبداءها للرجال الأجانب، كما يحرم عليها إبداء شعرها، وسائر بدنها كوجهها وحلقها وصدرها، ونحو ذلك، كذلك إبداء الذهب، وإبداء الأسورة والقلائد كل ذلك لا يجوز؛ لقوله سبحانه: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ [النور:31] فوجهها وما يكون في صدرها من القلائد، وما يكون في حلقها، وما يكون في رأسها كل ذلك من الزينة التي يحرم إبداؤها، والذهب من أحسن الزينة، فلا يجوز لها إبداء ما يفتن الرجال، ويسبب الميل إلى المرأة، ولكن تجتهد في ستر ذلك بالملابس والأجلة، ونحو ذلك، حتى لا يبدو منها شيء، إلا عينها، إلا العين أو العينين، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13007/حكم-اظهار-المراة-الحلي-ونحوها-فوق-الحجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_626/nour_62605.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":14535,"question":"رسالة وصلت إلى البرنامج من العراق، باعثتها إحدى الأخوات المستمعات تقول: (م. ن) في بداية رسالتها تقول: إني مواطنة مسلمة من القطر العراقي الشقيق، لا أزال غير محجبة، ولكن ملابسي محتشمة، وإني موظفة في إحدى المؤسسات، وأختلط بالرجال، زملاء لي في العمل ومواطنين لديهم مصالح تقتضي مقابلتهم في مؤسستنا.وإنني -والحمد لله- أؤدي فريضة الصلاة، وأصوم شهر رمضان منذ حوالي سبعة أشهر فقط، لم أكن في السابق من المصلين. أرجو إفادتي -حفظكم الله-: هل يصح عملي -أي الصلاة والصوم- بدون حجاب؟علمًا أني أنوي ارتداء الحجاب الإسلامي خلال فترة قريبة.","title":"حكم صلاة وصوم من لا ترتدي الحجاب","answer":"الجواب: الحمد لله الذي منَّ عليك بالتوبة، وقمت بالصلاة، هذه أعظم النعم؛ لأن ترك الصلاة كفر أكبر نسأل الله العافية، فنوصيك بالثبات على الحق، ولزوم ما أوجب الله عليك، وترك ما حرم الله عليك، ومن ذلك الحجاب، فإنه يجب على المرأة أن تحتجب عن الرجال، قال الله تعالى: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ[الأحزاب:53] فالحجاب أطهر لقلبك وقلب الرجال، فنوصيك بلزوم الحجاب، والحذر من مخالطة الرجال، وأن يكون عملك مع النساء، أو في محل مستقل وحدك دون الرجال، ولا تختلطي بالرجال؛ فإن ذلك من أسباب الفتنة، وعليك التوبة مما مضى، ومن تاب تاب الله عليه، والتوبة الندم على الماضي، والإقلاع من الذنب، والعزم على عدم العود إليه عزمًا صادقًا، بنية الإخلاص لله، ومحبته وتعظيمه. وما فعلت من الأعمال الطيبة فهو صحيح من صلاة وصوم لا يبطله عدم الحجاب، عدم الحجاب لا يبطل الأعمال لكنه معصية، فعليك التوبة إلى الله من ذلك، والاستقامة على الحجاب في الطريق، وعند الرجال أينما كنت؛ ولهذا يقول : يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلابِيبِهِنَّ ذَلِكَ أَدْنَى أَنْ يُعْرَفْنَ فَلا يُؤْذَيْنَ وَكَانَ اللَّهُ غَفُورًا رَحِيمًا[الأحزاب:59] ويقول سبحانه: وَقُلْ لِلْمُؤْمِنَاتِ يَغْضُضْنَ مِنْ أَبْصَارِهِنَّ وَيَحْفَظْنَ فُرُوجَهُنَّ وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنْهَا[النور:31] وما ظهر منها هي الملابس الظاهرة كالعباءة والجلباب ونحو ذلك. وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَى جُيُوبِهِنَّ[النور:31] والجيب مخرج الرأس، والمعنى: تضرب بالجلباب على رأسها ووجهها وصدرها حتى لا يبين منها شيء عند الرجال، ثم قال مؤكدًا سبحانه: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ[النور:31] والبعولة: الأزواج: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ أَوْ أَبْنَائِهِنَّ أَوْ أَبْنَاءِ بُعُولَتِهِنَّ أَوْ إِخْوَانِهِنَّ أَوْ بَنِي إِخْوَانِهِنَّ أَوْ بَنِي أَخَوَاتِهِنَّ أَوْ نِسَائِهِنَّ ..[النور:31] الآية. فعليك أن تتقي الله في هذا الأمر، وأن تحذري التساهل في أمر الحجاب، رزقنا الله وإياك الاستقامة والهداية. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13030/حكم-صلاة-وصوم-من-لا-ترتدي-الحجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_634/nour_63412.mp3","categories":["حكم الصلاة وأهميتها","اللباس والزينة","نكاح الكفار"]},{"id":14588,"question":"الأخت المستمعة فاطمة عبدالله من السودان، بعثت برسالة ضمنتها بعض الأسئلة، تقول في أحد أسئلتها: إنها فتاة محتجبة، ولكن يوجد عندهم فتيات يقلن: إن الوجه ليس بعورة، هل هذا صحيح؟","title":"حكم كشف المرأة لوجهها","answer":"الجواب: هذا ليس بصحيح، هذا قاله بعض أهل العلم، ولكنه ليس بصحيح، والصواب: أنه عورة، هذا الصواب من قولي العلماء: أنه عورة؛ لأنه أعظم الزينة، والله يقول سبحانه: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ ..[النور:31] الآية، فالوجه أعظم الزينة، وبه تعرف المرأة هل هي جميلة أو دميمة، وهو داخل في قوله تعالى: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ[الأحزاب:53]. فالواجب على النساء التحجب، وعدم إبداء الوجه لغير المحارم؛ لأنه أعظم الزينة؛ ولأنه فتنة، وربما سبب شرًا كثيرًا لمن كشفت وجهها عند غير محارمها، ولا حول ولا قوة إلا بالله، نعم، وكان هذا جائزًا في أول الإسلام، جائز في أول الإسلام، ثم نهى الله عن ذلك بعدما أنزل آية الحجاب، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13085/حكم-كشف-المراة-لوجهها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_635/nour_63508.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":14625,"question":"هل يجوز استعمال العطور المشهورة في الأسواق، فقد سمعت بعدم جوازها؛ لأنها تحتوي على كمية من الكحول الأثيلي في مكوناتها الأساسية؟أرجو بيان رأي الشرع في هذا؟جزاكم الله خيرًا.","title":"حكم استعمال العطور المحتوية على الكحول","answer":"الجواب: العطور لا بأس بها؛ لأن الطيب مطلوب، النبي ﷺ حث على التطيب، والطيب من سنن المرسلين، وقال: من عرض عليه طيب فلا يرده فالطيب مطلوب، لكن إذا عرف المؤمن أن شيئًا من العطور فيه كحول يسكر كثيرها لم يستعمل ذلك الطيب، إذا عرف أن فيه كحولًا يسكر كثيرها، فإنه لا يستعمله؛ لقول النبي ﷺ: ما أسكر كثيره فقليله حرام. وقد بلغنا أن الكالونيا فيها مسكر....، مسكر، فإذا عرف أنه هذه الكالونيا من النوع الذي فيه المسكر، فإنه لا يشتريها.  المقصود: أن كل طيب عرف أن فيه مسكرًا فإنه لا يستعمل، لا للرجال ولا للنساء إذا كان كثيره يسكر، أما إذا كان لا يعرف ذلك، فالأصل هو السلامة، فالأصل هو السلامة والإباحة إلا إذا عرفت أن هذا الطيب كالكالونيا فيه ما يسكر، أو فيه ما كثيره يسكر، فإنك تجتنب ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13127/حكم-استعمال-العطور-المحتوية-على-الكحول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_626/nour_62614.mp3","categories":["اللباس والزينة"]},{"id":14683,"question":"إزالة شعر الوجه بالنسبة للمرأة هل هو من النمص؟","title":"حكم إزالة المرأة لشعر وجهها","answer":"الجواب: الشعر العادي لا يجوز، أما إذا كان شيء مشوه فلا بأس من اللحية من الشارب شيء يشوه الخلقة يزال، أما الشيء العادي لا، لا تأخذ شيئًا من وجهها، ولا من حاجبيها، نعم.","link":"https://binbaz.org.sa/fatwas/13168/حكم-ازالة-المراة-لشعر-وجهها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_560/56010.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":14703,"question":"تريد زوجتي يوم زفافنا -إن شاء الله- لبس فستان الفرح الأبيض، وعليه خمار يستر وجهها وجيدها، علمًا بأنها وهي في طريقها إلى التاكسي الذي سيقلنا إلى شقتنا سيراها الرجال الأجانب، ناهيك عن سائق التاكسي الذي سيراها أيضًا، وأنا جالس بجوارها، أرجو إفادتي، وكيفية التصرف؟علمًا بأن زوجتي أخبرتني أنها سمعت الشيخ عبدالعزيز بن باز يقول في أحد الشرائط: إنه يجوز للعروس وهي تزف إلى زوجها لبس هذا الفستان.","title":"حكم لبس فستان الفرح والخروج به أمام الأجانب","answer":"الجواب: هذا الفستان إذا كان من ملابس النساء وليس من ملابس الرجال، وليس فيه تشبه بالرجال، بل هو من لبس النساء، وليس فيه تشبه بالكافرات فلا بأس به.  لكن ينبغي أن يكون فوقها شيء يسترها عن الرجال حال ذهابها إلى محل الزواج، كالعباءة ونحوها مما يستر زينتها وجمالها، وليس لها أن تكشف نفسها من حلي، ومن ملابس جميلة؛ لأن ذلك فيه فتنة، فعليها أن تستر نفسها بالعباءة والجلال، ونحو ذلك مما يستر زينتها عن الرجال؛ لقوله سبحانه: وَلا يُبْدِينَ زِينَتَهُنَّ [النور:31] الآية. أما هذا الأبيض إذا كان من لبس النساء، وليس من لبس الرجال في كيفيته وحالته، فإنه لا يكون فيه تشبهًا حينئذٍ بالرجال، إلا إذا كان فيه تشبه بالكافرات فلا، لا يجوز؛ لأن المرأة منهية عن التشبه بالرجال، ومنهية عن التشبه بالكافرات، وهكذا الرجل منهي عن التشبه بالنساء، ومنهي عن التشبه بالكفار.\nوالستر مطلوب للنساء عن الأجناب في الطريق وفي غيره، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13220/حكم-لبس-فستان-الفرح-والخروج-به-امام-الاجانب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_629/nour_62909.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":14709,"question":"تريد زوجتي يوم زفافنا -إن شاء الله- لبس فستان الفرح الأبيض، وعليه خمار يستر وجهها وجيدها، علمًا بأنها وهي في طريقها إلى التاكسي الذي سيقلنا إلى شقتنا سيراها الرجال الأجانب، ناهيك عن سائق التاكسي الذي سيراها أيضًا، وأنا جالس بجوارها، أرجو إفادتي، وكيفية التصرف؟علمًا بأن زوجتي أخبرتني أنها سمعت الشيخ عبدالعزيز بن باز يقول في أحد الشرائط: إنه يجوز للعروس وهي تزف إلى زوجها لبس هذا الفستان.","title":"حكم لبس فستان الفرح والخروج به أمام الأجانب","answer":"الجواب: هذا الفستان إذا كان من ملابس النساء وليس من ملابس الرجال، وليس فيه تشبه بالرجال، بل هو من لبس النساء، وليس فيه تشبه بالكافرات فلا بأس به.  لكن ينبغي أن يكون فوقها شيء يسترها عن الرجال حال ذهابها إلى محل الزواج، كالعباءة ونحوها مما يستر زينتها وجمالها، وليس لها أن تكشف نفسها من حلي، ومن ملابس جميلة؛ لأن ذلك فيه فتنة، فعليها أن تستر نفسها بالعباءة والجلال، ونحو ذلك مما يستر زينتها عن الرجال؛ لقوله سبحانه: وَلا يُبْدِينَ زِينَتَهُنَّ [النور:31] الآية. أما هذا الأبيض إذا كان من لبس النساء، وليس من لبس الرجال في كيفيته وحالته، فإنه لا يكون فيه تشبهًا حينئذٍ بالرجال، إلا إذا كان فيه تشبه بالكافرات فلا، لا يجوز؛ لأن المرأة منهية عن التشبه بالرجال، ومنهية عن التشبه بالكافرات، وهكذا الرجل منهي عن التشبه بالنساء، ومنهي عن التشبه بالكفار.\nوالستر مطلوب للنساء عن الأجناب في الطريق وفي غيره، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13220/حكم-لبس-فستان-الفرح-والخروج-به-امام-الاجانب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_629/nour_62909.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":14725,"question":"المستمع (ع. س) الجنيدي الشمري من رفحا، بعث يسأل ويقول: هل يجوز تركيب ناب من الذهب؛ وذلك للزينة للرجال؟","title":"حكم تركيب الرجل سنًا من الذهب للزينة","answer":"الجواب: لا للزينة لا يجوز، أما للحاجة إذا ما وجد غيره لا بأس إذا وجد غيره من الأضراس الأخرى من المعادن الأخرى فضة أو غيرها يركب، لكن إذا ما تيسر ضرس مناسب يركب الذهب؛ لأن الذهب جيد، والفضة قد تتغير. فالحاصل: أنه إذا دعت الحاجة إلى ضرس الذهب لا بأس، وإن تيسر معدن يقوم مقام الذهب فهو أولى وأحوط، وأما للزينة فلا.\nالمقدم: جزاكم الله خيرًا، من فعل ذلك وركب هل يخلعه؟\nالشيخ: نعم. المقدم: يخلعه؟\nالشيخ: يخلعه ويبدله، نعم.\nالمقدم: جزاكم الله خيرًا بالنسبة للنساء إذا ركبت المرأة نابًا ذهبًا للزينة فقط؟ الجواب: النساء أسهل.\nالمقدم: أسهل؟\nالشيخ: النساء أسهل، نعم.\nالمقدم: إذًا جائز في حقهن؟ الشيخ: لا حرج -إن شاء الله- فيما نعلم، لكن إذا دعت الحاجة، أما تقلعه وتحط بداله لا تقلعه، لكن إذا سقط الضرس حطت مكانه ضرس ذهب لا حرج -إن شاء الله-، النساء أسهل؛ لأن لهم الذهب، محلًا لهم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13218/حكم-تركيب-الرجل-سنا-من-الذهب-للزينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_490/49005.mp3","categories":["اللباس والزينة"]},{"id":14730,"question":"هل لبس الذهب للفتاة في العمل أو المدرسة حرام؟","title":"حكم لبس المرأة للذهب في مكان عملها","answer":"الجواب: لبس الذهب لا حرج فيه للمرأة إذا كانت بين النساء، أما بين الرجال غير المحارم تستره حتى لا تفتن أحدًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13232/حكم-لبس-المراة-للذهب-في-مكان-عملها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_637/nour_63715.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":14760,"question":"من السائلة سناء علي، من بني غازي في ليبيا، بعثت برسالة وضمنتها سؤالين، تقول في سؤالها الأول:أسأل عن تغطية الوجه والكفين، هل هي واجبة؟ وإذا كان الجواب: بنعم، فهل من الضروري كما يقول البعض أن تكون سوداء؛ لأن الألوان الأخرى تلفت النظر؟","title":"حكم تغطية المرأة وجهها وكفيها بغير السواد","answer":"الجواب: الصواب: أن الكفين والوجه عورة بالنسبة إلى الأجنبي، كأخ الزوج وعم الزوج وابن العم، وسائر الأجناب؛ لقول الله : وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ[الأحزاب:53] وهذا عام، وهكذا قوله سبحانه: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ[النور:31] الآية من سورة النور، ولا شك أن الوجه والكفين من الزينة، وإذا سترت ذلك بجلبابها، أو بأي قطعة من الثياب، سواء كانت سوداء، أو غير سوداء فلا بأس لا يشترط سوداء ولا حمراء، المقصود سترهما بأي حجاب، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13265/حكم-تغطية-المراة-وجهها-وكفيها-بغير-السواد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_638/nour_63804.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":14764,"question":"من ينبع فتيات يسألن هذه الأسئلة، الحقيقة هذه المجموعة يقلن في هذا السؤال الأول:بالنسبة -سماحة الشيخ- للبس القفازات بالنسبة للفتيات أثناء خروجهن، ما حكم ذلك؟مأجورين.","title":"حكم لبس المرأة للقفازين خارج البيت","answer":"الجواب: لا بأس، إذا غطين أكفهن بقفازات أو بالملابس أو بالعباءة كله طيب، الحمد لله، إلا المحرمة لا، التي هي بإحرام بحج أو عمرة ليس لها أن تلبس القفازين، ولا أن تلبس النقاب في وجهها، وهي محرمة بحج أو عمرة.  أما إذا كانت غير محرمة فلا بأس أن تغطي يديها بقفازين، أو بعباءتها، أو بجلال، أو بغير ذلك، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/13253/حكم-لبس-المراة-للقفازين-خارج-البيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_561/56105.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":14768,"question":"السائلة -يا سماحة الشيخ- تذكر وتقول: والدتي أدت فريضة الحج، ولكنها قطعت أوراقًا من شجرة في جبل بمنى وهي محرمة، ماذا يجب عليها الآن؟","title":"ما يجب على من قطعت أوراق شجرة في منى؟","answer":"الجواب: التوبة والاستغفار، والحمد لله، عليها التوبة والاستغفار، ويكفي. المقدم: جزاكم الله عنا كل خير سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13257/ما-يجب-على-من-قطعت-اوراق-شجرة-في-منى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_561/56107.mp3","categories":["اللباس والزينة","محظورات الإحرام","قضايا المرأة"]},{"id":14773,"question":"رسالة وصلت إلى البرنامج من ليبيا، وباعثها مستمعٌ من هناك يقول: (ش. ق. ع) يسأل بعضًا من الأسئلة، في أحد أسئلته يقول:يوجد في منطقتنا عادةٌ قديمة، وهي أن جميع النساء يلبسن اللباس الأسود، هل هذا مستحب أم مكروه؟","title":"حكم لبس المرأة للسواد من الثياب","answer":"الجواب: النساء مخيراتٌ في اللباس، أسود أو أخضر أو أحمر، أو غير ذلك، اللباس بابه واسع.  أما إن كن يتقيدن بذلك عن اعتقاد، وأنه قربة؛ فيكون بدعة، وأما إذا كن يرين أنه يناسبهن السواد؛ لأنه أستر لهن عند الرجال؛ فلا بأس بذلك، أو لأسبابٍ أخرى؛ لأنه أرخص، أو لأسباب أخرى، لا لاعتقاد أنه قربة، وطاعة، فلا حرج.  أما اعتقاد أن الأسود له مزية وقربة وطاعة عند الله، فهذا بدعة، لا يصلح.\nالمقدم: جزاكم الله خيرًا، إذا كان هناك فرقة من المتصوفة يلبسون هذا اللباس؟ الشيخ: إذا كان القصد التشبه بهم، كذلك لا يجوز، التشبه بأهل البدع، ولا بالكفار، إذا كان المقصود من الأسود التشبه بطائفةٍ من الصوفية، أو طائفة من الكفرة؛ فلا يجوز؛ لقول النبي ﷺ: من تشبه بقوم فهو منهم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13291/حكم-لبس-المراة-للسواد-من-الثياب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_641/nour_64106.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":14823,"question":"سؤاله الثاني يقول: ما حكم لبس النساء للذهب المحلق بأنواعه وأشكاله، من سوار وقرط وسلاسل وغيرها، حتى أنني قرأت حديثًا في كتاب عنوانه تحفة العروس أو الزواج الإسلامي السعيد تأليف محمود مهدي الاستانبولي من مصر، والحديث هو : من أحب أن يحلق حبيبته بحلقة من نار فليحلقها حلقة من ذهب، ومن أحب أن يطوق حبيبته طوقًا من نار فليطوقها طوقًا من ذهب، ومن أحب أن يسور حبيبته سوارًا من نار فليطوقها طوقًا وفي رواية: فليسورها سوارًا من ذهب، ولكن عليكم بالفضة فالعبوا بها رواه أبو داود ومسلم، وهو حديث صحيح، هذا بالنص من الكتاب المذكور للمؤلف، فما مدى صحة الحديث؟ وهل يجوز لبس المحلقات للنساء؟أفتونا في ذلك، جزاكم الله خيرًا.","title":"حكم لبس الذهب المحلق","answer":"الجواب: الحديث في صحته نظر، وفي متنه غرابة، وليس في مسلم، ولكنه في أبي داود، وفي صحته نظر، ولو صح فهو محمول على ما كان قبل النسخ، فإنه كان الذهب محرم على النساء، ثم أبيح للنساء، وأبيح لهن الحرير، وحرم على الرجال، فقال ﷺ: أحل الذهب والحرير لإناث أمتي، وحرم على ذكورها. فالصواب: أن جميع أنواع الذهب من المحلق وغير المحلق كالأسورة والخواتم وأشباه ذلك مباحة كالقلائد وغيرها، هذا هو الصواب، وهو الذي عليه عامة العلماء، وحكاه جمع من أهل العلم إجماع أهل العلم، أن الذهب بأنواعه من محلق وغيره كله حل للنساء، وهذا هو الصواب، ومن قال بتحريمه فقد غلط، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13315/حكم-لبس-الذهب-المحلق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_643/nour_64303.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":14893,"question":"من السودان مستمع، بعث برسالة ضمنها بعض الأسئلة، وهذا المستمع هو علي الصديق علي، في أحدها يقول:أرجو أن تتفضلوا بتبيين حكم المصافحة بالنسبة للرجال للنساء، مع بيان من تجوز للرجل مصافحته منهن؛ لأن البعض يقول: ما دام القلب لا يخالجه شيء من إثارة شهوة، وما إلى ذلك فالسلام لا إثم فيه، أريد منكم أن تردوا على هؤلاء. جزاكم الله خيرًا.","title":"حكم مصافحة الرجال للنساء غير المحارم","answer":"الجواب: المصافحة للنساء لا تجوز، إذا كان النساء لسن محارم للمصافح، سواء كن بنات عم، أو زوجات إخوة، أو زوجات أعمام، أو من الجيران كل ذلك لا يجوز؛ لأن المصافحة خطرها عظيم، وربما سببت ما لا تحمد عقباه؛ ولهذا ثبت عنه ﷺ أنه قال: إني لا أصافح النساء لما أرادت امرأة أن يصافحها، قال: إني لا أصافح النساء وقت البيعة. وقالت عائشة -رضي الله عنها-: \"والله ما مست يد رسول الله يد امرأة قط، ما كان يبايعهن إلا بالكلام\" فلا تجوز المصافحة للنساء غير المحارم أبدًا، ولو من وراء حائل، إنما يسلم عليهن بالكلام، كان النبي ﷺ يسلم عليهن بالكلام، ويرد عليهن بالكلام، وهكذا الصحابة لا مانع من السلام على النساء، ورد السلام عليهن، من دون مصافحة ومن دون كشف، بل مع الستر والحجاب، وعدم الخلوة. وقد كان النساء يسلمن على النبي ﷺ ويسألنه عن حاجتهن، ويسلم عليهن ويكلمهن، وهكذا مع الصحابة -رضي الله عن الجميع-، نعم. المقدم: جزاكم الله خيرًا، بعض النساء إذا أرادت مصافحة الرجال تضع على يدها جزءًا من لباسها، رأيكم شيخ؟ الشيخ: لا، ما يصلح؛ لأن هذا وسيلة للتساهل، لا يصافحها لا من وراء حائل، ولا مكشوفة اليد سدًا للباب، وأخذًا بالعموم إني لا أصافح النساء هكذا قال -عليه الصلاة والسلام-، وهو القدوة يقول الله سبحانه: لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ [الأحزاب:21] ولأن المصافحة وسيلة للتلذذ والفتنة، حتى قال بعض أهل العلم: إنها أعظم من النظر، أخطر من النظر، والله -جل وعلا- يقول: قُلْ لِلْمُؤْمِنِينَ يَغُضُّوا مِنْ أَبْصَارِهِمْ [النور:30] نقول: لمس اليد قد يكون أخطر من النظر، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13391/حكم-مصافحة-الرجال-للنساء-غير-المحارم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_492/49202.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":14985,"question":"ونبدأ برسالة المرسلة (س. م) من ضواحي المدينة المنورة، تقول فيها: إني ولدت بنتًا فيها بعض التشويه الخلقي، وبقيت أنا بعد الولادة ثلاثة أيام فاقدة الوعي، ثم خفت بعد ذلك، وتوفيت البنت في اليوم السابع من عمرها، وأنا الآن متندمة لأنني لم أرضعها في هذه المدة، ولم أحسن إليها، وكانت موضوعة في غرفة بعيدة عني ومظلمة، وإنني الآن متندمة كثيرًا. أرجو إفادتي في موضوعي هذا، وفقكم الله.","title":"حكم من ولدت بنتًا مشوهة فعزلتها حتى ماتت","answer":"الجواب: هذه فيها إشكال، ولا أدري عنها الآن تحتاج إلى، أقول: هذه المسألة تحتاج إلى تأمل يكون في حلقة أخرى -إن شاء الله- نتأملها؛ لأنها هذه فيها إشكال الآن في الحكم، نعم.","link":"https://binbaz.org.sa/fatwas/13475/حكم-من-ولدت-بنتا-مشوهة-فعزلتها-حتى-ماتت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_651/nour_65101.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":14988,"question":"سؤاله الأخير والأخير أيضًا في لقائنا هذا، يقول فيه: لماذا حرم الذهب والحرير على الرجال، وحل على النساء؟ وما الفرق؟أفيدونا، جزيتم عنا خيرًا وعن المستمعين أيضًا.","title":"لماذا حرم الذهب على الرجال دون النساء؟","answer":"الجواب: أولًا: يقول النبي ﷺ: لا تشربوا في آنية الذهب والفضة، ولا تأكلوا في صحافها؛ فإنها لهم في الدنيا، ولكم في الآخرة يعني: الكفرة، فالكفرة زينتهم الدنيا، وهمهم الدنيا، فهم أولى بهذا الشيء.  أما المؤمن فشأنه أن يعد للآخرة، وأن يعمل للآخرة، وليس من شأنه المباهات في الدنيا، ولبس الذهب والفضة والحرير ليس من شأنه هذا، بل هو حريص على إعداد نفسه للآخرة، والقيام بما أوجب الله عليه، وترك ما حرم الله عليه، وتعاطيه الذهب والفضة لبسًا أو أكلًا وشربًا في أوانيها قد يجره إلى الكبر والخيلاء، فيكون ذلك من أسباب دخوله النار، وقد يجره إلى التشبه بأعداء الله في أخلاقهم وصفاتهم ورغبتهم في الدنيا وبعدهم عن الآخرة، فيجره ذلك إلى الهلاك. أما النساء من جهة الحلي فلأنهن مطلوب منهن الزينة لأزواجهن، حتى يتحببن إلى أزواجهن، والذهب زينة والفضة زينة، فلهذا أباحه الله للنساء حتى يتجملن به للرجال.  وأما الرجل فليس في حاجة إلى هذا الشيء، ليس في حاجة أن يتجمل به، بل يكفيه اللباس الحسن والخاتم من الفضة فقط، ولا حاجة به إلى التجمل لزوجته بالذهب والفضة، وهذا من حكمة الله -جل وعلا- ورحمته وإحسانه إلى عباده ، نعم. المقدم: شكرًا، أثابكم الله.","link":"https://binbaz.org.sa/fatwas/13492/لماذا-حرم-الذهب-على-الرجال-دون-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_661/nour_66105.mp3","categories":["اللباس والزينة"]},{"id":15000,"question":"من حجر رابغ المستمع (د. س) بعث برسالة ضمنها جمعًا من الأسئلة، في أحدها يقول:قرأت في كتاب آداب الزفاف في السنة المطهرة، من تأليف الشيخ محمد ناصر الدين الألباني ووجدت أدلة تحرم الذهب على النساء، فما حكم ذلكم القول؟ وهل هو صحيح؟جزاكم الله خيرًا.","title":"حكم الذهب المحلق للنساء","answer":"الجواب: ليس ذلك بصحيح، الذهب حل للإناث، وهكذا الحرير كلها حل للإناث، والأدلة التي ذكرها الشيخ ناصر ما بين منسوخ، وما بين ضعيف شاذ، مخالف للأحاديث الصحيحة، قد حكى جماعة من العلماء، إجماع أهل العلم على حل الذهب والحرير للإناث محلق وغير محلق، وجاءت بذلك الأحاديث الصحيحة تدل على حل الذهب والحرير لإناث الأمة، سواء كان محلقًا أو غير محلق، والشيخ وفقه الله غلط في هذا، وشذ عن الأمة. والصواب: أن الذهب والحرير حل للإناث، حرام على الذكور، سواء كان الذهب محلقًا أو غير محلق، والأدلة التي ذكرها خفي عليه أمرها، فإنها ما بين إما شاذ، وإما منسوخ بالأدلة الصحيحة.  والقاعدة: أن الحديث المخالف للأحاديث الصحيحة يكون شاذًا، ويعتبر الشاذ ضعيفًا، لا يعول عليه، وقال جماعة من أهل العلم: إنها منسوخة بالأدلة الأخيرة الدالة على حل الذهب والحرير لإناث الأمة؛ ولهذا أجمع العلماء، أجمع أهل العلم على حل الذهب والحرير لإناث الأمة، وحكاه غير واحد، وما يوجد من الخلاف فهو خلاف شاذ لا يعول عليه عند أهل العلم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13500/حكم-الذهب-المحلق-للنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_493/49303.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":15016,"question":"السائل: عدنان من سوريا، ومقيم بالأردن، يقول في هذا  سماحة الشيخ، هل يجوز أن تعمل زوجتي داخل بيت لتجميل السيدات؟","title":"حكم تجميل المرأة للنساء في بيتها","answer":"الجواب: ما في مانع، التجميل الجائز، تمشط رؤوسهم، تعلمهم كيف يمشطون، كيف يغتسلون، لا بأس، تعلمهم الأشياء المباحة الطيبة لا بأس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13510/حكم-تجميل-المراة-للنساء-في-بيتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_563/56303.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":15017,"question":"ما حكم تطويل الثوب من غير قصد الكبرياء؟","title":"حكم إسبال الثياب","answer":"الجواب: يحرم تطويله مطلقًا، لكن إذا كان على سبيل التكبر صار الإثم أعظم، والجريمة أشد، وإلا فالإسبال محرم مطلقًا؛ لأن النبي ﷺ نهى عن ذلك، وزجر عنه مطلقًا، قال ﷺ: ما أسفل من الكعبين من الإزار فهو في النار ولم يقل: بشرط التكبر، وقال ﷺ: ثلاث لا يكلمهم الله، ولا ينظر إليهم يوم القيامة، ولا يزكيهم، ولهم عذاب أليم: المسبل إزاره، والمنان فيما أعطى، والمنفق سلعته بالحلف الكاذب فتوعدهم بهذا الوعيد العظيم، ولم يقل: إذا كان متكبرًا. أما ما جاء في الحديث الصديق  أنه قال: يا رسول الله، لما سمع منه حديث إن إزاري يتفلت علي إلا أن أتعاهده، فقال ﷺ: إنك لست ممن يفعله تكبرًا فهذا معناه: أن هذا التفلت الذي يقع من الإنسان من غير قصد الكبر لا يضره، ولكن عليه أن يتعاهده حتى لا ينفلت، وأما إنسان يتعمد ترك ثيابه تحت كعبيه فهذا متعمد، مظنة الكبر، وإذا كان ما أراد الكبر فعمله سيئ، وهو وسيلة للكبر أيضًا، وفيه إسراف وتعريض للملابس للأوساخ والنجاسات. فالحاصل: أن الإسبال محرم مطلقًا؛ لأن الأحاديث العامة تدل على ذلك، وإذا كان عن تكبر صار الإثم أعظم وأشد، وفي الحديث الصحيح يقول ﷺ: إياك والإسبال، فإنه من المخيلة سمى الإسبال كله مخيلة؛ لأنه مظنة الكبر، لماذا يسبل؟ الغالب على الناس هو التكبر والتعاظم، وإذا كان ما أراد هذا فهو وسيلة له، مع ما فيه أيضًا من الإسراف، وتعريض الملابس للأوساخ والنجاسات؛ ولهذا جاء عن عمر  أنه رأى شابًا قد أرخى ثوبه فقال: \"يا عبدالله، ارفع ثوبك، فإنه أتقى لربك، وأنقى لثوبك\"، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13511/حكم-اسبال-الثياب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_493/49305.mp3","categories":["اللباس والزينة"]},{"id":15028,"question":"سؤاله الأخير، سؤال صالح يقول: ما حكم من مرض بعد نية العمرة والحج متمتعًا؟ ومرض بعد وصوله مكة، ولبس ثيابه لمرضه؟","title":"ما حكم من مرض وهو محرم ولبس ثيابه؟","answer":"الجواب: حكمه أنه لا يزال في إحرامه، ما دام أحرم بالعمرة والحج أو بالعمرة، قاصدًا التمتع بها إلى الحج، ثم مرض بعد دخوله مكة، حكمه أنه لا يزال في إحرامه، وعليه إذا شفاه الله أن يطوف ويسعى، وعليه أن يزيل الملابس المخيط، ويبقى في الإزار والرداء، إلا إذا قال الطبيب: إنه يحتاج إلى التدفئة، ويغطي رأسه، ويلبس لباسًا، يعني: مخيطًا، فلا بأس، وعليه الفدية، وهي إطعام ستة مساكين، أو ذبح شاة، أو صوم ثلاثة أيام كما تقدم، عن اللبس، وهكذا عن تغطية الرأس إذا غطاه لحاجته، للمرض.  هذا كله إذا كان لم يستثن، أما إذا كان استثنى، قال: فإن حبسني حابس؛ فمحلي حيث حبستني؛ فإنه يحل، ولا شيء عليه، أصابه مرض يمنعه من أداء النسك، فإنه يتحلل، ولا شيء عليه؛ لأنه اشترط. والنبي  قال لـضباعة بنت الزبير، بنت عمه الزبير بن عبدالمطلب؛ لما دخل عليها وهي شاكية، وقالت: يا رسول الله، إني أريد الحج؟ قال: حجي واشترطي: أن محلي حيث حبستني قال العلماء: معناه: أنه إذا اشترطت المرأة، أو اشترط الرجل في إحرامه أن محله حيث يحبس، أو فإن حبسني حابس؛ فمحلي حيث حبستني، أو قال: فإن حبسني حابس؛ فأنا حلال، أو فأنا في حل، أو ما أشبهها من العبارات، فإنه إذا حبسه حابس من مرض، أو ضياع نفقة، أو ما أشبه ذلك مما يمنعه من الحج، فإنه يحل، نعم.","link":"https://binbaz.org.sa/fatwas/13526/ما-حكم-من-مرض-وهو-محرم-ولبس-ثيابه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_653/nour_65303.mp3","categories":["اللباس والزينة","محظورات الإحرام","قضايا المرأة"]},{"id":15085,"question":"عن الكلونيا، والتطيب بها، وردتنا هذه الرسالة، من مكة المكرمة، من مقدمها حسام محمود منير ، يقول فيها: أرجو من فضيلتكم التكرم بإفادتي عن حكم استعمال العطور المخلوطة بالكحول، الكلونيا، بقصد التطيب بها، وشكرًا.","title":"حكم استخدام الكالونيا لقصد التطيب بها","answer":"الجواب: هذا الموضوع قد جرى فيه بحث كثير، وعلمنا من الأطباء أن هذا الطيب لا يخلو من الكحول، وقد يكون كثيرًا، وقد يكون قليلًا، قد يكون ما فيه يبلغ ثمانين في المائة، وقد يكون عشرين في المائة، وقد يكون ذلك بين ذلك، والذي نرى أنه لا ينبغي استعمال هذا الطيب؛ لما فيه من إسبيرتو، ومعروف مسكر، وقد ذهب أكثر أهل العلم إلى أن كل مسكر خمر، ونجس، فينبغي للمؤمن أن يتطهر من هذا، وأن يبتعد عنه، وألا يستعمله، ولو كان فيه طيب، هذا هو الذي نرى، وقد كتبنا في هذا سابقًا منذ سنوات، في بعض الصحف المحلية.  نصيحةً للناس في عدم استعماله، لما فيه من المسكر المعروف: اسبيرتو، ولو أن الذي يقتنيه لا يريد السكر، وإنما يريد الطيب؛ لكن بكل حال، فهو غير جائز بالنسبة إلى استعماله، وإن كان صاحبه لا يشرب ذلك الطيب، وإنما يتطيب به فقط، وقد جرى من هذا الطيب شر كثير، وقد كان بعض الشباب يشربه، ويسكر منه. فالحاصل: أنه لا ينبغي استعماله أبدًا؛ لأن فيه هذا المسكر؛ ولأن بعض الناس قد يستعمله شرابًا، فيسكر، ويحصل منه من الضرر العظيم ما لا يحصى، فينبغي لأهل الإسلام أن يجتنبوه، وألا يستعملوه مطلقًا؛ لما فيه من المادة الخبيثة المسكرة، نعم.","link":"https://binbaz.org.sa/fatwas/13588/حكم-استخدام-الكالونيا-لقصد-التطيب-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_655/nour_65506.mp3","categories":["اللباس والزينة"]},{"id":15122,"question":"أخيرًا تسأل أختنا عن القصة للمرأة هل هي جائزة أو لا؟","title":"حكم تقصير الشعر للمرأة","answer":"الجواب: إذا دعت الحاجة إلى ذلك لا بأس بتقصيرها، وإن تركتها زينة وجمالًا وأزالتها وراء ظهرها، وراء الرأس كفى، وإن دعت الحاجة إلى تقصيرها وقصها، أو قص بعض الرأس حتى يخف فلا حرج في ذلك، ولا سيما إذا كان زوجها موافقًا عليها، إن كان عندها زوج ووافق فلا حرج.  أما إن كان ما عندها زوج، فالترك أحسن؛ لأن الرأس جمال، جمال لها، فإذا دعت الحاجة إلى قص شيء منه تخفيفًا، وليس القصد مشابهة الكفار، ولكن قصدها التخفيف، فلا بأس بذلك على الصحيح، لا حرج في ذلك، وقد ثبت عن أزواج النبي ﷺ لما توفي ﷺ قصصن من رؤوسهن تخفيفًا. فالحاصل: أن المرأة لها أن تقص من الطويل، سواء من القصة، أو من أطراف العمايل للتخفيف والتيسير، وإن تركت ذلك فهو أجمل وأفضل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13622/حكم-تقصير-الشعر-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_495/49506.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":15123,"question":"الأخت المستمعة فاطمة محمد الناغي، من منطقة مستورة، في طريق المدينة المنورة، بعثت برسالة ضمنتها جمعًا من الأسئلة، في أحدها تقول: هل صحيح أن الحناء لا يجوز في شهر صفر؟","title":"حكم الحناء للمرأة في شهر صفر","answer":"الجواب: هذا باطل، لا أصل له، الحناء يجوز في صفر وفي غير صفر، في كل الشهور، للمرأة تتحنى في صفر، وفي رمضان، وفي شعبان، وفي رجب، وفي كل شهر، وفي كل يوم، سواء طاهرة أو حائض، حتى ولو كانت حائضًا، أو نفساء، لها أن تتحنى، ولو في حال النفاس أو حال الحيض لا حرج في ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13623/حكم-الحناء-للمراة-في-شهر-صفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_495/49507.mp3","categories":["قضايا المرأة","البدع والمحدثات","اللباس والزينة"]},{"id":15124,"question":"هل صحيح إذا تحنت المرأة أربعين ربوعًا تدخل الجنة؟","title":"هل المرأة إذا تحنت أربعين أربعاءً تدخل الجنة؟","answer":"الجواب: لا، هذا باطل، لا أصل له، الحناء ما له تعلق بالجنة ولا بالنار، الحناء من الأمور المباحة، من زينة المرأة، من الزينة، فإذا حنت يديها للجمال والزينة فهذا طيب، حتى لا تكون مثل الرجل، وإلا ليس بواجب، إنما هو مستحب لها جمال لها، ولا تعلق له بالجنة ولا بالنار، ولم يرد فيه حديث في هذا المعنى، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13624/هل-المراة-اذا-تحنت-اربعين-اربعاء-تدخل-الجنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_495/49508.mp3","categories":["قضايا المرأة","البدع والمحدثات","اللباس والزينة"]},{"id":15125,"question":"هل صحيح أن الكحل والحناء لا يجوزان ليلة الإثنين؟","title":"حكم الكحل والحناء ليلة الإثنين","answer":"الجواب: كل هذا باطل، كل هذه من خرافات العامة، تكتحل ليلة الإثنين، وإلا غير ليلة الإثنين، وتتحنى ليلة الإثنين، وإلا غيره، كله واحد، في جميع الليالي الحناء والكحل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13625/حكم-الكحل-والحناء-ليلة-الاثنين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_495/49509.mp3","categories":["قضايا المرأة","البدع والمحدثات","اللباس والزينة"]},{"id":15153,"question":"ونبدأ برسالة المستمع (ب. ف. م) يقول في رسالته: هل وضع الشعر من اتجاه واحد كأن يكون على اتجاه الظهر هل فيه شيء أم لا؟","title":"حكم جعل المرأة شعر رأسها في جانب واحد","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد رب العالمين، والصلاة والسلام على عبده ورسوله وخليله وأمينه على وحيه، نبينا وإمامنا محمد بن عبد الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: تقدم أنه لا نعلم في هذا شيئًا إذا جعلت المرأة شعرها وراء ظهرها، أو على جانب رأسها، لا بأس بذلك هذا شيء إلى النساء، لا نعلم فيه سنة خاصة، لكن الميت السنة أن يجعل رأسه ثلاثة قرون، إذا مات الميت وعليه شعر يجعل ثلاثة قرون.  أما الحي يتصرف كيف شاء، يجعله قرنًا واحدًا خلفه، أو قرنين عن يمينه وشماله، لا بأس المرأة والرجل سواء، نعم.","link":"https://binbaz.org.sa/fatwas/13642/حكم-جعل-المراة-شعر-راسها-في-جانب-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_658/nour_65801.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":15160,"question":"الأخ علي عبدالحي القحطاني له ستة اقتراحات بالنسبة للبرنامج هي: تكرار عنوان المراسلة، وتسجيل الحلقات على كاسيت وتوزيعها، وتدوين الأسئلة، ثم نشرها، وإعادة بعض الأسئلة المفيدة، وزيادة مدة البرنامج، والإجابة على أسئلته المرفقة في رسالته هذه.ونقول للأخ علي اقتراحاتك موضع الاهتمام، وبعضها ينفذ الآن.وسؤال الأخ علي عبدالحي القحطاني من خميس مشيط الأول يقول: تنتشر في الجنوب من بلادنا عادة سيئة، وأقول: (تنتشر) لأن تسعة وتسعين من سكان هذه البلاد يفعلونها، ألا وهي عدم تغطية المرأة لوجهها أمام الرجال الأجانب، وخصوصًا الأقارب.أرجو بيان ذلك بيانًا شافيًا وكافيًا، وتخويف من يفعل ذلك من عقاب الله.وفقكم الله.","title":"حكم كشف المرأة وجهها أمام الأجانب","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، والصلاة والسلام على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد:\nفإن هذه العادة التي ذكرها السائل وهي تساهل النساء في الجنوب بكشف الوجه عند غير المحارم لا شك أنها عادة سيئة، وأن الواجب على المرأة التحجب عن غير محارمها، وعدم كشف الوجه عند أخي الزوج، أو عم الزوج، أو زوج الأخت، أو أبناء العم، ونحو ذلك، كل هذا لا يجوز؛ لأن الله سبحانه يقول في محكم التنزيل: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ[الأحزاب:53] فأخبر سبحانه أن الحجاب أطهر لقلوب الجميع، وأمر به سبحانه.  فالواجب على الرجال والنساء الأخذ بذلك، والتعاون في ذلك، وعلى المرأة أن تخاف الله وتراقبه، وأن تحذر ما حرم عليها . وقال  في سورة النور: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ[النور:31] الآية، والزينة تشمل كشف الوجه، وغير ذلك، فالوجه من أعظم زينتها، وهكذا حليها في حلقها، وفي يديها، وفي أذنيها، كل هذه من الزينة التي يجب سترها، وهكذا ما يكون في رجليها من الخلاخل كله زينة يجب سترها، وعلى المرأة وعلى وليها وزوجها أن يخافوا الله جميعًا، وأن يتعاونوا على البر والتقوى، وأن يحذروا ما حرم الله عليهم. ومن المعلوم: أن إظهار الزينة والمحاسن من المرأة من أسباب الفتنة بها، ومن أسباب وقوع الفواحش، فعلى الجميع تقوى الله في ذلك والحذر من غضبه ، نعم.","link":"https://binbaz.org.sa/fatwas/13653/حكم-كشف-المراة-وجهها-امام-الاجانب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_665/nour_66506.mp3","categories":["قضايا المرأة","نصائح وتوجيهات","اللباس والزينة"]},{"id":15171,"question":"سؤاله الآخر يقول: ما حكم كشف المرأة لشعر رأسها أمام الأجانب؟ وهل يعتبر عورة؟ وإذا رفضت المرأة ستر شعرها، فماذا يجب على زوجها اتخاذه؟وفقكم الله.","title":"حكم كشف المرأة لشعر رأسها أمام الأجانب","answer":"الجواب: لا شك أن إظهارها شعرها للأجانب منكر، وهو من أحسن زينتها، ومن أعظم زينتها، وهو عورة، فالواجب أن تستره عن جميع الأجانب ما عدا محارمها، فهي تستره عن أخي زوجها، وعن زوج أختها، وعن عم زوجها، وعن خال زوجها، وعن بني عمها، وعن جيرانها، وهكذا بقية الأجانب تستره. كما أن الواجب أيضًا ستر الوجه على الصحيح؛ لأنه عورة. فالحاصل: أن الشعر عورة بالإجماع فيما نعلم، ليس فيه خلاف بين أهل العلم أن الواجب ستره، وإنما الخلاف في الوجه والكفين، هل يجب سترهما أم لا؟ على قولين، والأرجح وجوب الستر؛ لأن الوجه أعظم الزينة، وأظهر الزينة، نعم.","link":"https://binbaz.org.sa/fatwas/13672/حكم-كشف-المراة-لشعر-راسها-امام-الاجانب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_659/nour_65904.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":15176,"question":"أيضًا يقول: ما حكم القصة التي يتخذنها بعض النساء، وهو إظهار بعض الشعر إلى فوق جبينها داخل في حكم التحريم أو لا؟جزاكم الله عنا خير الجزاء.","title":"حكم قصة الشعر التي يتخذنها بعض النساء","answer":"الجواب: ما أعلم في القصة شيئًا، هذه القصة التي هي إظهار الشعر الذي قدام، أو توفيرها بالنسبة إلى بقية الشعر، ما أعلم فيه شيئًا، إلا أنه يلاحظ أن لا تستر شيء من الجبهة وقت الوضوء، فإنها تغسل الجبهة، ولا يسترها شيء من الشعر، بل تغسله وقت الوضوء ووقت الجنابة حتى لا تستر شيئًا من المفروض. أما كيفية القصة التي يفعلونها فلا أعلم تفصيلها، لكن لا أعلم شيئًا في هذا يعني يمنع من التصرف بها في شعرها في كيفية فتله ونقضه وغير ذلك، كل هذا إليها التصرف فيه، إلا أنها تنهى عن عمل يشابه أعمال الكافرات التشبه بالكفرة، أما كونها تجعل رأسها ضفيرة واحدة أو ضفيرتين أو ثلاث ضفائر، كونها تزيد في شعر القصة، وتقص من أطراف العمايل، أو من بعض الشعر من جهة أخرى، ما أعلم شيئًا في هذا إلا أن الأولى والأفضل أن يكون رأسها معتدلًا، وأن تكون شعورها معتدلة، ليس فيها تمثيل، وليس فيها شيء يلفت النظر، بل تكون حالتها معتدلة في شعرها، وفي تصرفاتها، مع الحذر من تعاطيها شيئًا يشابه عمل الكافرات، فإن الرسول ﷺ قال: من تشبه بقوم فهو منهم فلا يجوز لها أن تتشبه بأعداء الله الكافرات، نعم.","link":"https://binbaz.org.sa/fatwas/13674/حكم-قصة-الشعر-التي-يتخذنها-بعض-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_659/nour_65905.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":15181,"question":"ما حكم الزوج الذي يأمر الزوجة بعدم ارتداء الحجاب؟","title":"حكم طاعة الزوج في ترك الحجاب","answer":"الجواب: عليها أن لا تطيعه، عليها أن ترتدي أن تحتجب؛ لأن الرسول ﷺ يقول: إنما الطاعة في المعروف ويقول ﷺ: لا طاعة لمخلوق في معصية الخالق فعليها أن تحتجب عن الأجنبي، ولو قال لها الزوج: لا تحتجبي، نعم.","link":"https://binbaz.org.sa/fatwas/13684/حكم-طاعة-الزوج-في-ترك-الحجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_564/56421.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":15198,"question":"سؤال آخر من المستمع (ع. خ) من المدينة المنورة يقول: هل يجوز للمرأة أن تلون شفتيها وأظافرها؟ أفيدونا، جزاكم الله عنا خيرًا.","title":"ما حكم تلوين المرأة شفتيها وأظافرها؟","answer":"الجواب: لا نعلم بأسًا في ذلك، أن تجعل في شفتيها شيء من الصبغ المناسب كالديرم، وأشباه ذلك، مما يفعلون للجمال، لكن فيما يتعلق بزوجها والنساء فقط، وليس لها أن تبدي ذلك للرجال الأجانب، بل هذا حرام؛ لأن الواجب عليها ستر وجهها، وستر زينتها، فإذا كان هذا مع النساء ومع الزوج، فلا نعلم شيئًا في ذلك، مثلما تتخذ الحناء في يديها، أو في رجليها، وتتخذ أنواع الطيب لزوجها، كل هذا لا بأس به، ومع النساء لا يضر، إذا كانت في محل ليس فيه إلا النساء، وليس فيه اختلاط بالرجال، فهذا لا حرج فيه.  والواجب عليها البعد عن أسباب الفتنة مع الرجال، نعم.","link":"https://binbaz.org.sa/fatwas/13698/ما-حكم-تلوين-المراة-شفتيها-واظافرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_667/nour_66702.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":15291,"question":"هذه التي رمزت لاسمها بـ (أ. م. ع) تقيم بجدة مؤقتًا، تقول: أنا مدرسة أعمل بمدرسة مشتركة بين البنين والبنات في إحدى البلاد العربية، وأنا أعلم حكم الشرع في ستر وجه المرأة، ومع حاجتي إلى العمل، فهل يجوز أن أكشف وجهي إذا اضطررت لذلك بسبب ظروف العمل سماحة الشيخ؟","title":"حكم كشف المدرسة وجهها من أجل العمل","answer":"الجواب: لا أرى لك ذلك، الواجب عليك أن تلتمسي مدرسة ليس فيها رجال، درسي البنات، أما مع الرجال فلا، إلا مع الحجاب لا بأس، تحتجبين وتدرسين البنات لا بأس، أو البنين معهم مع الحجاب لا بأس، ولكن مع الكشف لا، الواجب عليك تقوى الله، والله يقول سبحانه: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13777/حكم-كشف-المدرسة-وجهها-من-اجل-العمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_565/56519.mp3","categories":["اللباس والزينة"]},{"id":15394,"question":"سؤاله الآخر يقول: ما حكم الاكتحال؟ وهل علم عن النبي ﷺ أنه كان يضع الكحل في عينيه؟","title":"ما حكم الاكتحال للرجال؟","answer":"الجواب: الاكتحال سنة، وقد ثبت عن النبي أنه كان يكتحل -عليه الصلاة والسلام- في كل عين ثلاثة أميال -عليه الصلاة والسلام-، السنة الاكتحال، سنة -نعم- بالإثمد أفضل ما يكون الإثمد، نعم، وكان النبي يكتحل -عليه الصلاة والسلام-، نعم.","link":"https://binbaz.org.sa/fatwas/13908/ما-حكم-الاكتحال-للرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_684/nour_68406.mp3","categories":["اللباس والزينة"]},{"id":15397,"question":"هذه ثلاثة أسئلة، بعثت بها الأخت المستمعة (س. م) من مكة المكرمة، سؤالها الأول تقول: أحيانًا وأنا محرمة كنت أزيل قشورًا جلدية من جسمي، وبعضها يسيل منه دم، فهل يؤثر ذلك على صحة إحرامي، أم يلزمه صيام أو ذبح؟أفيدونا، جزاكم الله خيرًا.","title":"حكم من أزال قشورًا جلديه فسال منه دم وهو محرم","answer":"الجواب: لا يؤثر هذا؛ لأن خروج الدم من المحرم لا يؤثر، حتى لو احتجم لا يضره، النبي ﷺ احتجم وهو محرم -عليه الصلاة والسلام-، وخروج بعض الدم من جلد المرأة، أو الرجل المحرم لا حرج، ولا يضر إحرامه، نعم.","link":"https://binbaz.org.sa/fatwas/13916/حكم-من-ازال-قشورا-جلديه-فسال-منه-دم-وهو-محرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_684/nour_68410.mp3","categories":["اللباس والزينة","محظورات الإحرام","قضايا المرأة"]},{"id":15476,"question":"هل يعتبر عم الزوج محرم للزوجة؟ وهل يجوز السلام عليه باليد بحضور الزوج؟","title":"هل عم الزوج من المحارم؟","answer":"الجواب: عم الزوج ليس محرمًا للزوجة ولا أخوه، وإنما المحرم أبوه وجده وابنه، أما عمه وأخوه فليسا محرمين للزوجة، نعم.","link":"https://binbaz.org.sa/fatwas/14001/هل-عم-الزوج-من-المحارم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_569/56902.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":15485,"question":"في وقتنا هذا سماحة الشيخ -نحمد الله- توفرت سبل التعليم: الأشرطة .. الإذاعات المباركة التي تبث، ما الواجب على المرأة تجاه دينه في التعلم؟","title":"ما الواجب على المرأة تجاه دينها؟","answer":"الجواب: الواجب عليها تعلم ما يلزمها، ما يجب عليها، أما المستحبات يستحب لها تعلمها، يستحب لها أن تتعلم كثيرًا من القرآن، وإذا تيسر لها تعلمه كله أو حفظه كله، فهذا أحسن وأطيب.  وأما الواجب فلا يجب عليها إلا تعلم الفاتحة هي الواجبة في الصلاة، وما زاد على الفاتحة فهو سنة في الصلاة، لكن إذا تيسر لها أن تتعلم سورًا قصيرة حتى تقرأ مع الفاتحة في الفجر، وفي الأولى والثانية من الظهر والعصر والمغرب والعشاء كان هذا أفضل وأطيب وأحسن. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14015/ما-الواجب-على-المراة-تجاه-دينها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_569/56906.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":15519,"question":"تقول يا سماحة الشيخ: تلبس المرأة عندنا التنورة، ما يسمى بالتنورة، وهي عبارة عن ثوب مقسم إلى جزئين، مثلًا: فنيلة وبلوزة، هل يجوز لها ذلك؟","title":"هل يجوز لبس ما يسمى بالتنورة؟","answer":"الجواب: ليس لها أن تلبس لباسًا يظهر شيئًا من عورتها، أو تشابه فيه الكفار أو الرجال، وإذا كان لباس لا يشبه الرجال، ولا يشبه الكفار، ولا يبدي شيئًا من العورة فلا بأس، لا بد أن يكون ساترًا، وبدنها كله عورة إلا وجهها وكفيها عند النساء، والعورة المغلظة ما بين السرة والركبة، وهي كلها عورة عند الرجال جميعًا، جميعها عورة عند الرجال، لكن في الصلاة كلها عورة إلا وجهها وكفيها، إذا كان ما عندها رجال أجناب، نعم. المقصود: لا تلبس لباسًا يكشف شيئًا من العورة، أو لباسًا يشبه الرجال أو لباسًا يشبه الكفار، نعم.","link":"https://binbaz.org.sa/fatwas/14056/هل-يجوز-لبس-ما-يسمى-بالتنورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_691/nour_69109.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":15543,"question":"هل يجوز أخذ هذه الآية الكريمة في قوله تعالى: الرِّجَالُ قَوَّامُونَ عَلَى النِّسَاءِ [النساء:34] من دون تكملتها؟وما هو نوع القوامة بالنسبة للرجل على المرأة يا سماحة الشيخ؟","title":"توضيح حول قوامة الرجل على المرأة","answer":"الجواب: مثل ما بين الله -سبحانه وتعالى-: الرِّجَالُ قَوَّامُونَ عَلَى النِّسَاءِ بِمَا فَضَّلَ اللَّهُ [النساء:34]، وَبِمَا أَنفَقُوا مِنْ أَمْوَالِهِمْ [النساء:34] لفضل الرجل على المرأة، وبما أنفق من ماله، وأنفق عليها، أعطاها المال، وأعطاها النفقة، فهو القوام عليها، وليس لها الخروج من بيته إلا بإذنه، وليس لها معصيته فيما أباح الله، عليها السمع والطاعة في المعروف، وهو القائم عليها في توجيهها وإرشادها، والإذن لها بالخروج، أو عدمه، إلا في المعصية، فليس لها أن تطيعه في المعصية؛ لأن الرسول قال -عليه الصلاة والسلام-: إنما الطاعة في المعروف لا طاعة لمخلوق في معصية الخالق نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14079/توضيح-حول-قوامة-الرجل-على-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_569/56928.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":15566,"question":"ما الحكم الشرعي لغطاء الوجه، هل هو فرض واجب؟ وما حكم من ترك غطاء الوجه؟","title":"ما حكم غطاء الوجه للمرأة؟","answer":"الجواب: على المرأة غطاء الوجه عن الأجنبي؛ لقول الله -جل وعلا-: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ[الأحزاب:53] وقوله -جل وعلا-: يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلابِيبِهِنَّ[الأحزاب:59]. وقوله -جل وعلا-: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ[النور:31] الآية، والوجه من الزينة، من أعظم الزينة، فالواجب الحجاب عن الرجال الأجانب، نعم.","link":"https://binbaz.org.sa/fatwas/14102/ما-حكم-غطاء-الوجه-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_691/nour_69132.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":15574,"question":"يقولون: إن الإسلام قد ظلم المرأة في إعطائها حقوقها، والإسلام يفضل الرجل على المرأة، كقوله تعالى: الرِّجَالُ قَوَّامُونَ عَلَى النِّسَاءِ [النساء:34] فهل معنى هذه الآية تفضيل الرجال على النساء؟وأرجو أن توضحوا قضية المرأة وحقوقها ومكانتها في الإسلام.","title":"ما حقوق المرأة ومكانتها في الإسلام؟","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فالقائلون بأن الإسلام ظلم المرأة؛ قد أخطئوا كثيرًا، وغلطوا غلطًا كبيرًا، فإن الإسلام هو الذي أنصفها، ورفع مكانتها، وكانت مظلومة في الجاهلية بين العرب، وفي اليهودية والنصرانية وغير ذلك من سائر الأديان الباطلة، والإسلام هو الذي رفعها، وعظم شأنها، وأنصفها وأعطاها حقوقها، فجعلها أمًا كريمة، وزوجة كريمة، وبنتًا مرحومة معطوفًا عليها، ينفق عليها، ويحسن إليها، حتى تستقل بنفسها، أو تتزوج، وأمر بالإنفاق عليها، وألزم والدها بالإنفاق عليها، وزوجها بالإنفاق عليها، وإحسان عشرتها، وأمر الدولة الإسلامية أن تنصفها، وأن تعطيها حقوقها، وأن تمنع من العدوان عليها، وجعل لها قيمة متى قتلت قتل بها الرجل، ومتى أصيب منها شيء أعطيت حقها في ذلك، سواء كان المصاب عضوًا، أو غير ذلك. أما قوله سبحانه: الرِّجَالُ قَوَّامُونَ عَلَى النِّسَاءِ بِمَا فَضَّلَ اللَّهُ بَعْضَهُمْ عَلَى بَعْضٍ وَبِمَا أَنفَقُوا مِنْ أَمْوَالِهِمْ [النساء:34] فالأمر فيها واضح، الله سبحانه فضل الرجال على النساء؛ لأن جنس الرجال أقوى في الجملة على أداء الحقوق، وعلى جهاد الأعداء، وعلى رفع الظلم، وعلى الإحسان إلى الأولاد والنساء وحمايتهم من الأذى والظلم، إلى غير هذا مما هو معروف شرعًا وفطرة وحسًا، أن الرجال أقوى وأقدر على ما ينفع المجتمع من النساء في الجملة. ثم الرجال ينفقون أموالهم في الزواج بإعطاء المهور، وفي الإنفاق على الزوجات، وفي حمايتهن مما يؤذيهن، والعطف عليهن، فالرجال لهم حق كبير من الجهتين؛ من جهة تفضيل الله لهم على النساء لما هو معلوم من كون الرجال أكمل وأقدر على كل شيء في الجملة، وأكمل عقولًا، وأتم نظرًا في العواقب والمصالح في الجملة؛ ولأنهم أنفقوا أموالهم في تحصيل الزوجات من مهر وغيره؛ ولهذا قال سبحانه: الرِّجَالُ قَوَّامُونَ عَلَى النِّسَاءِ بِمَا فَضَّلَ اللَّهُ بَعْضَهُمْ عَلَى بَعْضٍ وَبِمَا أَنفَقُوا مِنْ أَمْوَالِهِمْ [النساء:34]. ولا يلزم من هذا أن يكون كل رجل أفضل من كل امرأة، وإنما هذا تفضيل في الجملة، أما بالتفصيل: فقد تكون امرأة أفضل من رجل، هذا أمر واقع ومعلوم، ولكن في الجملة جنس الرجال مفضل على جنس النساء، وهذا يعرف بالشرع وبالعقل وبالفطر وبمعرفة الواقع والتجارب، ولكن كم لله من امرأة أفضل من رجل بسبب علمها ودينها واستقامتها وبصيرتها، ومن نظر في صفات الصحابيات والتابعيات، وعلماء هذه الأمة من النساء؛ عرف أن هناك نساءً طيبات يفضلن على كثير من الرجال، وقال -عليه الصلاة والسلام-: كمل من الرجال كثير، ولم يكمل من النساء إلا: آسية ابنة مزاحم -زوجة فرعون-، ومريم ابنة عمران وجاء في فضل فاطمة بنت النبي ﷺ وفضل خديجة -رضي الله عنها- وعائشة -رضي الله عنها-، ما يدل على اختصاصهن بالفضل أيضًا، فهؤلاء الخمس هن أفضل النساء: خديجة وعائشة من أمهات المؤمنين، وفاطمة ابنة النبي ﷺ، ومريم بنت عمران أم المسيح عيسى -عليه الصلاة والسلام-، وآسية ابنة مزاحم زوج فرعون، هؤلاء النسوة الخمس هن خير النساء، وهناك نساءٌ كثيرات لهن فضل، ولهن علم، ولهن تفضيل على كثير من الرجال. لكن حكمة الله اقتضت تفضيل الرجل على المرأة في أشياء معينة أيضًا: كالإرث، فإن البنت تعطى نصف ما يعطى الذكر من الأولاد، والأخت من الأبوين أو الأب تعطى نصف ما يعطاه الأخ الشقيق، أو الأخ لأب، والزوجة تعطى النصف مما يأخذه الزوج، فإذا أخذ الزوج النصف صار لها الربع، وإذا أخذ الزوج الربع صار لها الثمن، وهذه لحكمة بالغة، ومعانٍ إذا تدبرها ذو البصيرة عرف وجاهتها، وحكمة الله فيها، وأنه سبحانه هو الحكيم العليم، فكل موضع فضل فيه الرجل على المرأة فله وجاهته، وله أسبابه، وله حكمته لمن تدبر وتعقل، والله المستعان، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14114/ما-حقوق-المراة-ومكانتها-في-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_704/nour_70401.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":15581,"question":"هذه رسالة من الأخت (ي. م . ب) من العراق، تقول: هل يجوز للمرأة أن ترفع الشعر الموجود في الوجه وتعدل الحواجب؛ وذلك برفع الشعر الزائد عن الحاجب؟","title":"حكم أخذ المرأة من شعر الحاجبين والوجه","answer":"الجواب: ليس لها ذلك، ليس لها أن تغير شعر الحاجبين، ولا الشعر العادي في الوجه، بل تدع ذلك؛ لأن الرسول ﷺ لعن النامصة والمتنمصة وذكر أئمة اللغة: أن النمص أخذ شعر الحاجبين، وشعر الوجه.  فالواجب ترك ذلك، إلا إذا كان في شعر الوجه شيء يخالف المعتاد، ويشوه الخلقة كالشارب أو اللحية، فإن هذا يزال عند أهل العلم، ولا حرج في ذلك.  أما الشعر العادي اليسير الذي قد يكون في الوجه هذا يترك.\nوهكذا الحاجبان لا يجوز أخذهما، ولا تخفيفهما؛ لأن الرسول ﷺ لعن النامصة والمتنمصة والنمص فسره أهل العلم باللغة بأنه أخذ الحاجبين، وشعر الوجه، نعم.","link":"https://binbaz.org.sa/fatwas/14121/حكم-اخذ-المراة-من-شعر-الحاجبين-والوجه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_692/nour_69206.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":15655,"question":"سؤالها الثالث تقول: ما حكم المساحيق التي يضعها النساء على وجوههن للزينة؟ هل هن يعتبرن من المغيرات لخلق الله بذلك حتى إذا وضعت بقصد الزينة للزوج فقط؟ وهل صحيح أن عطر النساء في صدر الإسلام كان له لون، وليس له رائحة؟","title":"ما حكم مساحيق التجميل للنساء؟","answer":"الجواب: المساحيق فيها تفصيل:\nإن كانت يحصل بها جمال والنور، ولكن لا تضر الوجه، ولا تسبب شينًا فيه، فلا بأس بها، ولا حرج، أما إن كانت تسبب شينًا فيه، بقع مثلًا سوداء أو ضررًا في الوجه، فإنها تمنع من أجل الضرر. وأما الطيب فهو قديمًا وحديثًا قد يكون له لون مع الريح، وقد لا يكون له لون، ويكون له ريح، فإذا تعاطت المرأة الطيب، فالأولى والأفضل بها أن تتحرى الذي ليس له رائحة جيدة قوية، وإلا فالنساء يتعاطين في عهد النبي ﷺ ما له ريح، وله لون، كالمسك، قالت عائشة: \"كنا نضمد جباهنا بالمسك مع النبي ﷺ في الإحرام\". فالأولى بها أن تتحرى الشيء الذي ليس له الرائحة القوية؛ لئلا تفتن الرجال، وتبتعد عن المرور على الرجال، أو المخالطة للرجال، مع وجود الطيب الذي له رائحة، وقد يكون له لون، ولكن ليس له رائحة شديدة، مثل بعض الأطياب التي لها لون أصفر، أو نحوه، لكن ليس له الرائحة القوية، هذا نوع من الأطياب، ولا يكون طيب إلا وله رائحة، لكن قد تكون قوية، وقد تكون ضعيفة، لكن إذا تحرت الطيب الذي ليس له رائحة قوية، إذا كان قد تبتلى بالرجال من أحمائها وغير أحمائها، فيكون هذا أولى، وإذا فعلته وكانت مع النساء وفي حقل نساء لا في حقل رجال فلا حرج، نعم.","link":"https://binbaz.org.sa/fatwas/14199/ما-حكم-مساحيق-التجميل-للنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_699/nour_69905.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":15659,"question":"هذا سؤال من المستمع: علي عبده مشهور، من جيزان صامطة، يقول: كنت أقرأ في كتاب آداب الزفاف تأليف: محمد ناصر الدين الألباني، فوجدت في هذا الكتاب حديثًا لا أعلم مدى صحته، وهو قول الرسول ﷺ: من أحب أن يحلق حبيبه بحلقة من نار، فليحلقه حلقة من ذهب، ومن أحب أن يطوق حبيبه طوقًا من نار، فليطوقه طوقًا من ذهب، ومن أحب أن يسور حبيبه سوارًا من نار فليطوقه طوقًا -وفي رواية: فليسوره سوارًا من ذهب، ولكن عليكم بالفضة، فالعبوا بها، العبوا بها، العبوا بها أخرجه أبو داود، وهذا سند جيد، فهل هذا الحديث صحيح؟ فإن كان كذلك فإن معناه: تحريم الذهب على النساء، فإن محمد ناصر الدين الألباني قد حرمه، أفيدونا عن ذلك جزاكم الله خيرًا.","title":"ما صحة حديث: «من أحب أن يحلق حبيبه بحلقة من نار»؟","answer":"الجواب: هذا الخبر في صحته نظر، وقد صححه جماعة، والصواب أنه شاذ، وليس بصحيح، ولو فرضنا صحته فهو منسوخ بإجماع أهل العلم، فإن أهل العلم أجمعوا على أن الذهب حل للنساء، محرم على الرجال، وهذا الخبر بين أمرين:\nإما أن يكون شاذًا قد خالف الأحاديث الصحيحة، والشاذ حكمه حكم الأحاديث الضعيفة، ولو صح سنده فإنه متى خالف الأحاديث الصحيحة يكون شاذًا، حكمه حكم الأحاديث الضعيفة؛ لأن من شرط الصحيح ألا يكون شاذًا، وما شذ من الأحاديث بأن خالف الأحاديث الصحيحة التي هي أصح منه، فإن حكمه حكم الأحاديث الضعيفة، فيحكم عليه بأنه ضعيف، وهذا من هذا الباب. ثم هو مع هذا منسوخ، لو صح سنده وسلم من الشذوذ فإنه منسوخ بإجماع أهل العلم، الدال على أن الذهب محلل للنساء، محرم على الرجال، وأن ما جاء فيه من النهي كان قبل ذلك ثم نسخ، وقد كتبنا في هذا مقالًا نشرناه قريبًا، وجوابًا أرسلناه إلى مجلة الدعوة وغيرها من النشر في بيان هذا الحكم، وأن الحديث هذا وأشباهه مما جاء في تحريم الذهب على النساء كلها على افتراض صحتها منسوخة، بالإجماع الذي حكاه أهل العلم، فإنه حكى الإمام الجصاص والبيهقي والنووي وجماعة بإجماع أهل العلم على حل الذهب للنساء،وعلى تحريمه للرجال. وأما هذه الأخبار التي فيها ما يدل على تحريمه على النساء فهي أخبار إما شاذة، وإما منسوخة كما بيَّنا في الكلمة.  وأخونا العلامة الشيخ محمد ناصر الدين الألباني وَهِمَ في هذا، غفر الله له، ورأى أن يكون المحلق محرمًا على النساء دون غير المحلق، وهذا ليس بصحيح.  والصواب: أن جميع أنواع الذهب سواءً محلق أو غير محلق حل للنساء، وقد ثبت عنه ﷺ أنه أذن للنساء في لبس الأسورة، وفي لبس الخاتم من الذهب وهو محلق والأسوار محلقة. المقصود: أن الصواب في هذا أن الحديث هذا بين أمرين: بين ضعفه لشذوذه، وبين نسخه لو فرضنا صحته بإجماع أهل العلم، وبالأحاديث الصحيحة الدالة على حله للنساء، وما ذكره أخونا الشيخ العلامة محمد ناصر الدين الألباني في آداب الزفاف من الجمع بين الأحاديث الواردة في هذا الباب، بحمل الأحاديث التي فيها النهي على المحلق، والأحاديث الدالة على الإباحة على غير المحلق ليس بصحيح، وقد بيَّنا ذلك في الكلمة التي كتبناها من باب النصيحة، وبيان الصواب في هذا الباب.  وهو لا شك مجتهد -جزاه الله خيرًا، وبارك فيه-، ولكن كل واحد يخطئ ويصيب، وكل عالم له أغلاط وله أخطاء، ونسأل الله أن يوفق الجميع لما فيه صلاح النية والعمل، نعم. المقدم: حفظكم الله وأثابكم.","link":"https://binbaz.org.sa/fatwas/14204/ما-صحة-حديث-من-احب-ان-يحلق-حبيبه-بحلقة-من-نار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_699/nour_69910.mp3","categories":["الحكم على الأحاديث","اللباس والزينة"]},{"id":15675,"question":"من إرتيريا، رسالة بعث بها المستمع إسماعيل علي سليمان، يسأل عدة أسئلة، في أحدها يقول: عندنا عادات كثيرة، منها: مصافحة الرجال للنساء اللاتي لا يجمعنا بهن صلة قرابة أو محرم، نرجو منكم بيان حكم ذلك؟ جزاكم الله خيرًا.","title":"حرمة مصافحة المرأة الأجنبية","answer":"الجواب: لا تجوز مصافحة الرجل الأجنبي للمرأة؛ لقول النبي ﷺ: إني لا أصافح النساء وتقول عائشة -رضي الله عنها-: \"والله ما مست يد رسول الله ﷺ يد امرأة قط، ما كان يبايعهن إلا بالكلام\" فهذا يدل على أنه ﷺ ما كان يصافح النساء، فلا تجوز مصافحتهن؛ لأنها فتنة، المصافحة قد تجر إلى فتنة، فلا تجوز إلا إذا كانت محرم: كأخته وعمته وزوجته لا بأس.  أما الأجنبية ولو بنت عمه أو زوجة أخيه أو زوجة عمه، أجنبية، ليس له أن يصافحها، إنما يسلم: كيف حالكم؟ كيف أنتم؟ السلام عليكم، وعليكم السلام، كيف أولادكم؟ كلام طيب من دون مصافحة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14219/حرمة-مصافحة-المراة-الاجنبية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_706/nour_70606.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":15682,"question":"سؤال آخر تقول: ما رأيكم في هذا العمل وهو: أن بعض الناس عندما يتزوج ابنهم يعملون له ما يسمونه بالحناء، ويكون في ليلة قبل الزفاف، ويأتي بعض الرجال والنساء إلى بيت العريس، ويجلسون العريس في الوسط، فيأخذون ويعطونه الفلوس، وبعد هذا العمل تقوم أم العريس وتعمل له الحناء في يديه، وجهونا ووجهوهم، مأجورين. جزاكم الله خيرًا.","title":"حكم استعمال الحناء للرجل في العرس","answer":"الجواب: الحناء من خصائص النساء، من زينة النساء، فلا يجوز أن يستعمل مع العريس، ولا مع غيره من الرجال، الحناء من زينة النساء، ومما يعمله النساء؛ تجملًا لأزواجهن. فلا يجوز أن يعامل الرجل بذلك، ولا أن يستعمله الرجل، بل ينبغي أن يبتعد، بل يجب أن يبتعد عن مشابهة النساء.\nوقد صح عن رسول الله -عليه الصلاة والسلام- أنه قال: لعن الله الرجل يلبس لبسة المرأة، ولعن الله المرأة تلبس لبسة الرجل.\nوجاء عنه ﷺ: أنه لعن المتشبهين من الرجال بالنساء والمتشبهات من النساء بالرجال وهذا يعم أنواع التشبه.\nفالواجب الحذر من التشبه بالنساء في استعمال العريس للحناء، أو غير ذلك مما هو من خصائص النساء. أما اجتماعهم بالعريس رجالًا ونساءً يعطونه النقود، فهذا فيه تفصيل، اجتماعهم مختلطين وليسوا محارم فيما بينهم نساء أجنبيات هذا ما يجوز، اختلاط الرجال مع النساء إلا على وجه فيه حشمة، والبعد عن أسباب الفتنة، والتستر والاحتجاب، كما يجتمع الناس في بيوتهم، تجتمع المرأة مع أحماء زوجها، ومع أزواج أخواتها، مع التستر والحشمة للتحدث في بعض الأمور لا بأس.  أما اختلاط فيه عدم التحجب، وعدم البعد عن أسباب الفتنة هذا لا يجوز.\nوهكذا لا يجوز الخلوة بالعريس من امرأة أجنبية تخلو به فلا يجوز أيضًا. أما إعطاؤه النقود إذا كان على سبيل المساعدة يساعدونه في الزواج من باب المساعدة فلا بأس، سواء أعطوه فلوسًا أو غير فلوس، من باب التعاون على الخير، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14233/حكم-استعمال-الحناء-للرجل-في-العرس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_572/57203.mp3","categories":["اللباس والزينة"]},{"id":15707,"question":"هل يجوز لبس العدسات اللاصقة الملونة بغرض التجمل للزوج؟","title":"حكم لبس المرأة للعدسات اللاصقة للتجمل","answer":"الجواب: تركه أحوط، إذا كان لمجرد التجمل تركه أحوط، أما إذا كان لمصلحة العين؛ لقوة النظر فلا بأس.......، تُلبس، نعم.","link":"https://binbaz.org.sa/fatwas/14265/حكم-لبس-المراة-للعدسات-اللاصقة-للتجمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_573/57316.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":15787,"question":"تقول: إذا لبست المرأة المسلمة الخمار، فهل يجب عليها ألا يرى الرجال وجهها، مثل أخي الزوج، وزوج الأخت، وزوج العمة، وزوج الخالة؟","title":"حكم تغطية المرأة وجهها عن الأجانب","answer":"الجواب: نعم، لها أن تستر وجهها بالخمار، أو بالنقاب، ولا بأس أن ترى عيناها، أو إحدى عينينها من النقاب، ولا تكشف لهؤلاء، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14377/حكم-تغطية-المراة-وجهها-عن-الاجانب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_742/nour_74214.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":15830,"question":"في ثاني أسئلة هذه السائلة من جدة أم محمود تقول: سماحة الشيخ لقد قلت في النية: بأنني سوف أعمل عمرة لجدي المتوفى، وفي نيتي أنها ستكون أول عمرة أعملها بعد أن قلت ذلك، ولكنني بعد ذلك أديت عمرة لنفسي، مع العلم بأنني اعتمرت قبل ذلك، ثم نويت الحج متمتعة، فأديت عمرة أخرى وحج، والحمد لله، ولم تكن عندي فرصة لأداء عمرة لجدي قبل الحج، ولم أؤديها إلى الآن، فهل حجي صحيح؟ وماذا يلزمني؟","title":"حكم من نوت أن تعتمر عن جدها ثم لم تف","answer":"الجواب: نعم، حجك صحيح، والعمرة صحيحة، والحمد لله؛ لأن هذا ليس بنذر، هذا نية، فليس عليك شيء متى تيسرت العمرة لجدك فلا بأس، وإلا العمرة التي فعلت صحيحة، والحج صحيح، والحمد لله؛ لأن هذا ليس بنذر، نية، مجرد نية، نعم. المقدم: أحسن الله إليكم يا شيخ.","link":"https://binbaz.org.sa/fatwas/14419/حكم-من-نوت-ان-تعتمر-عن-جدها-ثم-لم-تف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_575/57522.mp3","categories":["مسائل متفرقة في الحج والعمرة","اللباس والزينة","قضايا المرأة"]},{"id":15896,"question":"ما حكم من صافح ابنة عمه، واستمر على ذلك فترة طويلة، هل يعد آثمًا؟جزاكم الله خيرًا.","title":"ما حكم من صافح ابنة عمه؟","answer":"الجواب: مصافحة المرأة الأجنبية لا تجوز، سواءٌ كانت ابنة عمه، أو ابنة خاله، أو بعيدة من ذلك؛ لأن ابنة العم أجنبية، يجوز له تزوجها، فلا يجوز للمؤمن أن يصافح النساء الأجنبيات؛ لقول النبي ﷺ: إني لا أصافح النساء وتقول عائشة -رضي الله عنها-: \"والله ما مست يد رسول الله ﷺ يد امرأة قط، ما كان يبايعهن إلا بالكلام\" -عليه الصلاة والسلام-. فالمقصود: أن المصافحة للنساء الأجنبيات لا تجوز، وفاعلها يأثم، وعليه التوبة إلى الله من ذلك، إلا إذا كان جاهلًا لم يعرف الأحكام الشرعية، فنرجو له من الله العفو، وعليه الحذر في المستقبل بعدما علم الحكم، ومن تاب تاب الله عليه، والله -جل وعلا- لطيف بعباده رحيم، فالذي لم يعرف الحكم الشرعي، ولم يتساهل، فلما عرف الحكم الشرعي تاب وأناب الله يتوب على التائب . فالمقصود: أن التوبة تجب ما قبلها مطلقًا، من تاب من الذنب تاب الله عليه، وعليك الحذر في المستقبل من مصافحة غير المحارم، أما أختك وعمتك وخالتك ونحو ذلك من المحارم لا بأس، أما الأجنبيات فالواجب الحذر من مصافحتهن؛ لأن ذلك وسيلة إلى شر، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14484/ما-حكم-من-صافح-ابنة-عمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_745/nour_74511.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":15945,"question":"المستمع حمدان أحمد خضيض رشيدي يقول: أسال سماحتكم عن مصافحة الرجل لابنة عمه، أو بنت خاله، أو ما يشبه ذلك من النساء؟جزاكم الله خيرًا.","title":"هل يجوز مصافحة الرجل لابنة عمه، أو بنت خاله؟","answer":"الجواب: لا تجوز له مصافحة المرأة الأجنبية، ولو كانت بنت عمك، أو بنت خالك، أو زوجة أخيك، يقول النبي ﷺ: إني لا أصافح النساء يعني: غير المحارم، أما المرأة المحرم: كعمتك، وخالتك وزوجتك وأمك وجدتك فلا بأس بذلك، أما الأجنبية وإن كانت بنت عم وبنت خال، أو زوجة أخ، أو زوجة عم، أو زوجة خال لا، لا تصافحها السلام من دون مصافحة، السلام عليكم، وعليكم السلام، كيف حالك؟ كيف حالك يا فلانة؟ كيف حالك يا أم فلان؟ كيف الأولاد؟ كيف الوالدان؟ أو كيف أبوك؟ أو كيف حال أمك؟ أو ما أشبه هذا من الكلام الطيب، أما المصافحة فلا، فالكلام الطيب بدأ الكلام، ورد الكلام، مع الكلام الطيب، مع السؤال المناسب؛ هذا كله لا بأس به، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14551/هل-يجوز-مصافحة-الرجل-لابنة-عمه-او-بنت-خاله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_710/nour_71006.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":15963,"question":"من جمهورية جيبوتي المستمعة (ف. أ. ح) تسأل جمعًا من الأسئلة من بينها سؤال عن طلاء الأظافر، هل لا يجوز أو لا؟جزاكم الله خيرًا.","title":"حكم طلاء الأظافر بالمناكير والحناء","answer":"الجواب: طلاء الأظافر بالحناء أو غيره مما يحسنها لا بأس إذا كان طاهرًا ليس بنجس، وكان رقيقًا لا يمنع الوضوء والغسل، أما إن كان له جسم فلا بد من إزالته عند الوضوء والغسل؛ لئلا يمنع وصول الماء إلى حقيقة الظفر.  فالمقصود: أن استعمال ما يغير الظفر من الحناء أو غيره، أو ما يسمونه المناكير، لا بأس به إذا أزيل هذا الذي له جسم عند الوضوء والغسل إن كان له جسم، أما إذا كان ليس له جسم مثل الحناء يجعل الظفر أحمر أو أسود ولكن لا يبقى له جسم، هذا لا يضر، أما إذا كان له جسم يمنع الماء؛ فلا بد من إزالته، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14571/حكم-طلاء-الاظافر-بالمناكير-والحناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_710/nour_71013.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":15987,"question":"هذه رسالة من السائلة (م. س. الهاجري) من الخرج، تقول: امرأة قامت بأخذ عمرة في بيت الله الحرام، وكان المحرم الذي يرافقها هو زوج ابنتها، فهل تصح عمرتها ويعتبر لها محرمًا أم لا؟ وماذا تفعل لو كان غير محرم لها؟ هل عليها أن تعيد عمرتها، أم تصح حتى لو كانت الواجبة؟","title":"حكم سفر المرأة للعمرة مع زوج البنت","answer":"الجواب:  زوج البنت محرم، زوج البنت وزوج بنت البنت وبنت الابن محارم، وزوج الأم محرم، وزوج الجدة محرم، كلهم محارم، ولا حرج في ذلك، وعمرتها إذا أدت حقها وكملتها صحيحة، حتى لو كان معها غير محرم، لو كان الذي معها غير محرم، مثل ابن عمها، أو زوج أختها ليس بمحرم، عمرتها صحيحة، وحجها صحيح، لكنها آثمة إذا سافرت بدون محرم، يكون عليها التوبة إلى الله، وأما العمرة فصحيحة، والحج صحيح، ولو كان ما معها محرم، لكنها قد أخطأت غلطت ما يجوز لها أن تسافر بدون محرم لا للحج ولا لغيره، لكن لو فعلت بأن ظنت أنه يجوز أو أفتاها بعض الناس أنه يجوز وحجت بدون محرم، أو اعتمرت بدون محرم عمرتها صحيحة، وحجها صحيح، لكن عليها التوبة إلى الله، والندم، وعدم العود إلى مثل هذا، ليس لها أن تسافر بعد ذلك إلا بمحرم؛ لأن الرسول ﷺ قال: لا تسافر امرأة إلا مع ذي محرم هكذا قال -عليه الصلاة والسلام-، نعم.","link":"https://binbaz.org.sa/fatwas/14608/حكم-سفر-المراة-للعمرة-مع-زوج-البنت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_680/nour_68004.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":16012,"question":"هل يجوز صبغ الحواجب بدون نتفها بالنسبة للمرأة فتظهر بلون البشرة؟","title":"حكم صبغ المرأة شعر الحاجبين بلون البشرة","answer":"الجواب: لا بأس بصبغ الحواجب، المنهي عنه النمص، أما كونها تصبغها بالصبغة التي تجعلها حسنة جميلة فلا بأس، ما يضر كمثل الكحل، مثلما تكتحل، مثلما تستعمل..... في شفتها لا حرج في ذلك، كون تصبغها بشيء. أما إن كانها شايبة -يعني: عجوز- وقد شاب -يعني: شعرها- فلا تغيره بالسواد؛ الرسول ﷺ نهى عن تغيير الشيب بالسواد، أما كونها تحط شيء يجملها وهي سوداء.. ما هو بتغير الشيب، إنما تختار بعض الأصباغ الحسنة لشفتها، أو لكحلها، أو لعينها لا حرج، نعم، أو حواجبها، نعم. المقدم: حفظكم الله يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14641/حكم-صبغ-المراة-شعر-الحاجبين-بلون-البشرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_579/57902.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":16016,"question":"ما حكم استخدام الرجال للكريمات المرطبة والمنعمة للجلد، هل هذا من التشبه بالنساء يا سماحة الشيخ؟!","title":"حكم استخدام الرجال للكريمات المنعمة للجلد","answer":"الجواب: إذا دعت الحاجة إلى هذا ليس فيه تشبه، دهن أو كريم أو سمن أو زبدة.. المقصود إذا دعت الحاجة إلى شيء من هذا فلا حرج، الحمد لله. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14650/حكم-استخدام-الرجال-للكريمات-المنعمة-للجلد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_579/57906.mp3","categories":["اللباس والزينة"]},{"id":16022,"question":"تسأل أختنا من ليبيا تقول: ما حكم مصافحة زوج الأخت؟ وهل يجوز أن أضع قفازًا إذا أردت السلام عليه، أو على أي رجل أجنبي؛ ليكون حائلًا بين يدي وأيديهم؟","title":"حكم مصافحة المرأة للأجانب مع لبس القفازين","answer":"الجواب: لا تجوز المصافحة للرجال الأجانب، ولو كان زوج الأخت، أو زوج العمة؛ لأنه أجنبي ليس بمحرم، ولو مع القفاز، يقول النبي ﷺ: إني لا أصافح النساء وتقول عائشة -رضي الله عنها-: والله ما مست يد رسول الله ﷺ يد امرأة قط، ما كان يبايعهن إلا بالكلام ولما مدت امرأة يدها في البيعة قال: إني لا أصافح النساء.  فالواجب على المرأة أن تحذر هذا الشيء، لا مع زوج أختها، ولا مع زوج عمتها، ولا مع أخي زوجها، ولا غيرهم من الأجانب؛ لأنه وسيلة للشر والفتنة أعظم من النظر. أما زوج أمها فهو محرم، زوج أمها، أو زوج جدتها هذا محرم من النسب والرضاع، هكذا زوج ابنتها، وزوج بنت ابنها، وزوج بنت بنتها محرم من النسب والرضاع. أما زوج الأخت، زوج العمة، زوج الخالة هذا أجنبي، وهكذا أخو الزوجة، وأخو الزوج، أخو الزوج ليس بمحرم، أجنبي، عمه خاله أجنبي، أما أبو الزوج، وجد الزوج، وابن الزوج، وابن بنت الزوج وابن ابنه، هؤلاء محارم، زوج البنت، زوج بنت البنت، زوج بنت الابن كلهم محارم من النسب والرضاع، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14671/حكم-مصافحة-المراة-للاجانب-مع-لبس-القفازين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_801/nour_80111.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":16033,"question":"تسأل وتقول: هل غطاء الوجه فرض لازم على المرأة، مع العلم أنني ألتزم باللباس الشرعي، والحمد لله، ومتدينة، ولكني لا أغطي وجهي، فهل علي إثم في ذلك؟","title":"هل غطاء الوجه واجب على المرأة؟","answer":"الجواب: هذا الموضوع فيه خلاف بين أهل العلم، والصواب أن ستر الوجه واجب عند الأجنبي، إذا كان في المكان الأجنبي ليس محرمًا لك؛ فالواجب غطاء الوجه، هذا هو الواجب؛ لأن المرأة عورة، فيجب عليها الستر في جميع بدنها عند الأجنبي، يعني: غير المحرم، كأخي زوجك، وابن عمك، وغيرهم من الجيران، أو غيرهم ممن ليس بمحرم، والحجة في هذا قوله : وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] ولم يقل: إلا الوجه والكفين. بل أطلق  وأخبر أن هذا أطهر لقلوب الجميع، والفتنة بالوجه أشد من غيره؛ لأنه مظهر الزينة، وبه يعلم جمال المرأة، وعدم ذلك، وقال في سورة النور: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ [النور:31] والزينة تشمل الوجه، واليد، والقدم، والساق، والرأس، وغير ذلك، وأعظم الزينة الوجه؛ لأنه مظهر الجمال وضده، وإذا كان فيه تجميل من الكحل، وتخضيب الشفاه، وغير ذلك؛ كان أشد وأشد في الفتنة. فالمقصود: أن الأصح من قولي العلماء: وجوب ستر الوجه عن الأجنبي، نعم. ولو بالبرقع التي تظهر منه العين، أو العينان، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14665/هل-غطاء-الوجه-واجب-على-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_748/nour_74803.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":16073,"question":"تقول في سؤالها الثاني: هل يجوز للمرأة أن تزيل بعض الشعر الذي ينبت على الوجه، علمًا بأنه يضايقها، مثل الذي ينبت على الشوارب، وجوانب الخد؟","title":"حكم إزالة المرأة الشعر النابت على وجهها","answer":"الجواب: إذا نبت شعر يشوه الخلقة؛ فلا بأس بإزالته، مثل الشارب، واللحية، وإذا كان من الشعر الذي يشوه الخلقة، أما الشعر العادي الذي في الوجه، الشعر العادي فلا يتعرض له، وشعر الحاجبين لا يجوز التعرض له، أما لو نبت شيء يكون فيه تشويه، أو فيه بشاعة؛ فهذا يزال، ولا حرج في ذلك مثل الشارب واللحية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14709/حكم-ازالة-المراة-الشعر-النابت-على-وجهها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_803/nour_80303.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":16074,"question":"من سلطنة عمان رسالة بعثت بها إحدى الأخوات من هناك تقول المرسلة (م. م)، لها سؤالان.في سؤالها الأول تقول: سمعت بعض الناس يقولون: إنه عند الانتهاء من قص الأظافر لابد من أخذها، ودفنها في مكان، وقراءة بعض السور عليها مثل الإخلاص، والمعوذتين، وعدم رميها، فما حكم ذلك؟ جزاكم الله خيرًا.","title":"حكم دفن الأظافر بعد قراءة القرآن عليها","answer":"الجواب: هذا شيء لا أصل له، إذا قص الإنسان أظفاره يرميها، ولا بأس، ولا حاجة إلى دفنها، ولا قراءة قرآن عليها، كل هذا خرافة لا أصل لها، ولا أساس لها، متى قص الإنسان أظفاره رجل، أو امرأة؛ فلا حرج في إلقائها في أي مكان، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14707/حكم-دفن-الاظافر-بعد-قراءة-القران-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_803/nour_80302.mp3","categories":["الأخلاق المذمومة","سنن الفطرة","اللباس والزينة"]},{"id":16111,"question":"من المستمعة زهرة سيد أحمد محمد محمود من السودان رسالة تقول فيها: سمعنا من خلال برنامجكم هذا تحريم المصافحة، وعملت على تطبيقه، الناس يطالبونني بالأدلة، أرجو أن تتفضلوا بإعطائي دليلًا قاطعًا أوقف به ألسنة الناس؟ جزاكم الله خيرًا.","title":"أدلة تحريم مصافحة الرجل للمرأة الأجنبية","answer":"الجواب: المصافحة بين الرجال سنة، كان النبي ﷺ يصافح أصحابه، وكان الصحابة إذا تلاقوا تصافحوا  وهكذا النساء المصافحة بينهن سنة، بينهن، أو مع محارمهن لا بأس. أما المرأة مع الأجنبي، كابن عمها، أو زوج أختها، أو أخي زوجها لا تصافحه، ولا يجوز لها أن تصافح الرجل الأجنبي، ولو كان زوج أختها، ولو كان أخا زوجها، ولو كان ابن عمها، وابن خالها؛ لقول النبي ﷺ: إني لا أصافح النساء لما قدمت امرأة يدها إليه؛ امتنع -عليه الصلاة والسلام- وقال: إني لا أصافح النساء. وقالت عائشة -رضي الله عنها-: \"والله ما مست يد رسول الله ﷺ يد امرأة قط، ما كان يبايعهن إلا بالكلام\" وهو ﷺ معروف بعصمته فيما يبلغه عن الله، وهو معروف أيضًا ببعده عما حرم الله -عليه الصلاة والسلام- وهو معصوم عند جمهور أهل العلم، عن كبائر الذنوب. فلو كانت المصافحة لا حرج فيها؛ لصافح -عليه الصلاة والسلام- فلما امتنع منها، وهو أتقى الناس، وأخشاهم لله؛ دل ذلك على أن الواجب تركها؛ ولأن الفتنة قد تقع بالمصافحة، الفتنة كما تقع بالنظر قد تقع بالمصافحة، إذا مس يدها؛ قد يفتن بها، ولهذا قال بعض العلماء: إن المصافحة أخطر من النظر، فإذا كان النظر محرمًا، فالمصافحة مثل ذلك، أو أشد، نعم.  المقدم: جزاكم الله خيرًا، إذًا الدليل الذي تفضلتم به سماحتكم هو فعل الرسول ﷺ. الشيخ: نعم. المقدم: وتلك من سنته، اللهم صل عليه. الشيخ: نعم نعم. المقدم: جزاكم الله خيرًا.  الشيخ: وهو فعل ذلك خشية الفتنة. المقدم: الله أكبر الله أكبر، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14778/ادلة-تحريم-مصافحة-الرجل-للمراة-الاجنبية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_803/nour_80308.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":16117,"question":"أسأل سماحتكم -جزاكم الله خيرًا- عن حكم النقاب، إذ أني لاحظت أن بعض الناس يفتي بتحريمه، فما هو القول الصحيح في هذه المسألة؟ جزاكم الله خيرًا.","title":"ما حكم لبس المرأة النقاب","answer":"الجواب: القول الصحيح أنه لا بأس بالنقاب بقدر العينين فقط؛ لأن الرسول ﷺ لما نهى عنه للمحرمة؛ دل على حله لغير المحرمة، وإذا سترت وجهها بغير النقاب سترًا كاملًا؛ كان أفضل، وأكمل، وأبعد عن الشبهة، وإلا فالنقاب المضبوط بقدر العين فقط، لا بأس به بنص الرسول -عليه الصلاة والسلام-نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14767/ما-حكم-لبس-المراة-النقاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_712/nour_71203.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":16129,"question":"أحد الإخوة المستمعين رمز إلى اسمه بالحروف (ع. م. ص) أخونا يسأل سماحتكم عن مصافحة النساء، وزيارتهن في المستشفيات، ولا سيما إذا كن من غير المحارم إنما هن من القرابة، ما حكم ذلك؟ جزاكم الله خيرًا.","title":"حكم مصافحة النساء وزيارتهن في المستشفيات","answer":"الجواب: أما زيارتهن في المستشفى، أو في غير المستشفى على وجه صلة الرحم، من غير خلوة، ولا تهمة، ولا ريبة؛ فلا بأس، مع محرمها، أو بحضرة نساء، كأمها، وأخواتها. المقصود: على وجه ليس فيه ريبة، ولا خلوة، فلا بأس أما المصافحة فلا، ليس للرجل أن يصافح المرأة، إلا إذا كانت من ذوات المحارم، كالأخت، والخالة، والأم.. ونحو ذلك. أما الأجنبية -ولو كانت بنت عمه أو بنت خاله أو خالته- ليس له أن يصافحها؛ لأن بنت العم أجنبية، بنت الخال أجنبية، بنت الخالة أجنبية، يجوز له أن يتزوجها. فالمقصود: أن المصافحة لغير المحرم لا تجوز، لقول النبي ﷺ: إني لا أصافح النساء وقالت عائشة -رضي الله عنها-: \"والله ما مست يد رسول الله ﷺ يد امرأة قط، ما كان يبايعهن إلا بالكلام\" ولأن المصافحة قد تفضي إلى الفتنة، والريبة، والتلذذ. المقصود: أنها لا تجوز المصافحة لغير المحارم، أما المحرم كالأخت، والعمة فلا بأس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14785/حكم-مصافحة-النساء-وزيارتهن-في-المستشفيات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_713/nour_71303.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":16187,"question":"تقول: إذا كان في ذراعي المرأة شعر، فهل يجوز إزالته بالموس؟","title":"حكم إزالة المرأة شعر الذراعين","answer":"الجواب: لا حرج في ذلك، بالموس، أو غيره من الأدوية، .. الذراع، أو الساق، أو الفخذ.. كما تزال العانة بالدواء، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14944/حكم-ازالة-المراة-شعر-الذراعين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_807/nour_80713.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":16203,"question":"تقول: أنا مقيمة في المملكة حاليًا، وملتزمة بالحجاب الشرعي، وعندما أرجع؛ أترك الحجاب، وأكشف الوجه والكفين؛ لأن البلد كله على ذلك الحال، فهل صلاتي وزكاتي وحجي وجميع أعمالي تكون باطلة لتصرفي هذا؟ جزاكم الله خيرًا.","title":"حكم أعمال من تساهلت في الحجاب","answer":"الجواب: ليست أعمالك باطلة، هذه معصية، ولكن أعمالك -إن شاء الله- صحيحة، وليست باطلة، ولكنك أخطأت في التساهل، ولو أن أهل البلد تساهلوا لا تتساهلي أنت، فلو أن أهل البلد شربوا الخمر لا تشربي الخمر، وإذا تركوا الحجاب لا تتركي الحجاب، وإذا صاروا يغتابون الناس لا تغتابين الناس أنت، وإذا صاروا يسبون الناس لا تسبين الناس، ليسوا بقدوة، المؤمن يخالف الباطل ولو كان وحده، الجماعة من وافق الحق وإن كان وحده، فعليك بالحق، الزميه، وإن كنت وحدك، لا في الحجاب، ولا في غيره، وفق الله الجميع. المقدم: آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14873/حكم-اعمال-من-تساهلت-في-الحجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_751/nour_75104.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":16225,"question":"المستمعة هديل من تبوك بعثت برسالة وضمنتها جمعًا من الأسئلة، في أحدها تقول: هل يجوز أن يلبس الأطفال الذكور الذهب، أم لا؟ وإذا كانت أعمارهم تقل عن السنتين؟ جزاكم الله خيرًا.","title":"حكم تلبيس الأطفال الذكور الذهب","answer":"الجواب: لا يجوز تلبيس الذكور الذهب مطلقًا، ولو كان في أقل من سنتين، الذهب حل للإناث، حرام على الذكور، سواء كان خواتيم، أو ساعات، أو غير ذلك، لا يجوز إلباس الطفل الذكر الذهب، كما لا يجوز إلباس الرجل الكبير، وإنما الذهب للنساء، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14901/حكم-تلبيس-الاطفال-الذكور-الذهب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_751/nour_75114.mp3","categories":["اللباس والزينة"]},{"id":16236,"question":"من إحدى الأخوات المستمعات من ليلى بالأفلاج رسالة تقول أم العنود، لها أكثر من سؤال في أحد أسئلتها تقول: ما حكم خرق الأنف للنساء؟ وهل هو صحيح، أم بدعة؟ وهل التي لم تفعل هذا تكون آثمة؟ نرجو أن توضحوا لنا الحكم، جزاكم الله خيرًا.","title":"حكم خرق الأنف للمرأة من أجل الحلي","answer":"الجواب: لا نعلم فيه بأسًا، بل هذا من الحلي التي يستعملها النساء، خرق الأنف، والأذن هذا مما يفعله النساء لاتخاذ الحلي، فلا حرج فيه -إن شاء الله- وليس بواجب، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14927/حكم-خرق-الانف-للمراة-من-اجل-الحلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_807/nour_80702.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":16249,"question":"رسالة من أحد الإخوة المستمعين يقول: محمد علي الأخ محمد له جمع من الأسئلة في أحدها يقول: هل يجوز للمسلم أن يلبس أي لبس، سواء كان بنطلونًا، أو جلابية، وهي أسفل من الكعبين، وما حكم من لبس جزاكم الله خيرًا، وهل يعد مرتكبًا لكبيرة من الكبائر؟","title":"الملابس التي يجوز لبسها وحكم الإسبال فيها","answer":"الجواب: الملابس من الأمور العادية، يجوز للإنسان أن يلبس ما شاء مما أباح الله من القطن، والصوف، والكتان، والحرير إذا كانت امرأة تلبس الحرير أيضًا، بخلاف الرجل، لكن ليس له أن يتشبه بأعداء الله في لباسه، وليس للمرأة أن تتشبه بالرجل، وليس للرجل أن يتشبه بالمرأة في اللباس، ولا في غيره، فالتشبه بأعداء الله في اللباس، وغيره لا يجوز، وتشبه المرأة بالرجل، والرجل بالمرأة أيضًا لا يجوز، لا في الكلام، ولا في المشي، ولا في اللباس. وليس للرجل أن يلبس لباسًا محرمًا كالحرير، أو الإسبال، بحيث ينزل بشته، أو بنطلونه، أو سراويله، أو إزاره عن الكعب، هذا لا يجوز للرجل؛ لقول النبي ﷺ في الحديث الصحيح: ما أسفل من الكعبين من الإزار فهو في النار وقوله -عليه الصلاة والسلام-: ثلاثة لا يكلمهم الله، ولا ينظر إليهم يوم القيامة، ولا يزكيهم، ولهم عذاب أليم: المسبل إزاره، والمنان فيما أعطى، والمنفق سلعته بالحلف الكاذب خرجه مسلم في الصحيح. فجعل المسبل إزاره من هؤلاء الثلاثة المتوعدين؛ فيجب الحذر، أما المرأة فلها أن ترخي ثيابها حتى تستر قدميها شبرًا إلى ذراع، وأما الرجل لا، عليه أن تكون ثيابه إلى الكعب، لا تنزل عن الكعبين، سواء كانت الثياب قمصًا، أو سراويلات، أو إزرًا، أو بشتًا، أو غير ذلك، عليه أن يتقي الله، وأن يحذر الإسبال، وإذا كان عن تكبر؛ صار الإثم أعظم، إذا كان عن تكبر؛ صار الإثم أكبر لقوله ﷺ: من جر ثوبه خيلاء؛ لم ينظر الله إليه يوم القيامة نسأل الله السلامة والعافية، نعم. المقدم: جزاكم الله خيرًا، متى يكون الإسبال -سماحة الشيخ - من الكبائر كما يسأل صاحب هذه الرسالة؟ الشيخ: هو من الكبائر مطلقًا لهذا الحديث الصحيح: ما أسفل من الكعبين من الإزار؛ فهو في النار توعده بالنار، وأخبر أنه: لا يكلمهم، ولا ينظر إليهم، ولا يزكيهم، ولهم عذاب أليم ذكر منهم المسبل، هذا من الكبائر، وإذا كان عن كبر؛ صار أشد، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14940/الملابس-التي-يجوز-لبسها-وحكم-الاسبال-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_752/nour_75203.mp3","categories":["اللباس والزينة"]},{"id":16299,"question":"تسأل وتقول: ما حكم لبس المرأة للملابس الضيقة أمام النساء، وما حكم الخروج بها مع ارتداء الجلباب، أو العباءة خارج المنزل مثل المدرسة التي للبنات فقط؟","title":"حكم لبس المرأة للملابس الضيقة أمام النساء","answer":"الجواب: لبس الملابس الضيقة ما يجوز مطلقًا، لا عند النساء، ولا عند الرجال؛ لأنها تبين حجم العورة، وتفتن الناس، فالواجب الحذر منها، وأن تكون الملابس وسطًا ليس فيها ضيق، وليس فيها اتساع يبين العورة، ولكن متوسطة، هذا هو الواجب على المرأة، والرجل جميعًا، أن تكون الملابس وسطًا لا ضيقة تبين حجم العورة، ولا واسعة قد يبين منها بعض العورة، ولكن بين ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14990/حكم-لبس-المراة-للملابس-الضيقة-امام-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_753/nour_753006.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":16309,"question":"تقول في سؤالها الأخير، قالت لي إحدى الأخوات: إنها تريد تغطية الوجه، وعدم المصافحة لإخوان زوجها، وأزواج أخوات زوجها، إلا أن زوجها لم يرض لها وهي تجد إحراجًا كبيرًا منهم لو قامت بذلك، مع العلم أنها امرأة صالحة، ومحتشمة في ملابسها، وهي تلبس العباية، وتغطي شعرها في حضرتهم، فهل عليها شيء؟","title":"حكم مصافحة المرأة وكشف وجهها لغير المحارم","answer":"الجواب: نعم، الواجب عليها أن تحتجب عن إخوان زوجها، وعن أزواج أخواتها؛ لأنهم ليسوا محارم، ليسوا محارم لها، وليس للزوج أن يمنعها من ذلك، الواجب عليه طاعة الله ورسوله، وعدم منعها من الاحتجاب، والله يقول سبحانه في كتابه العظيم: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] وهم أزواج النبي ﷺ ومع هذا أمرن بالحجاب، وقيل في حقهن: أطهر لقلوبهم وقلوب الرجال، لقلوبهن ولقلوب الرجال، والطهارة مطلوبة لأزواج النبي ولغيرهن. وقال -جل وعلا- في نساء المؤمنين: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ [النور:31] البعولة: الزوج، إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ أَوْ أَبْنَائِهِنَّ أَوْ أَبْنَاءِ بُعُولَتِهِنَّ أَوْ إِخْوَانِهِنَّ أَوْ بَنِي إِخْوَانِهِنَّ أَوْ بَنِي أَخَوَاتِهِنَّ [النور:31] إلى آخره. فالمقصود: أن الواجب على المرأة التحجب عن الأجنبي، ولو كان الأجنبي زوج أخت، أو زوج عمة، أو زوج خالة، أو أخًا للزوج، أو عمًا للزوج؛ لأنهم ليسوا محارم، ولا تصافح واحدًا منهم، يقول النبي ﷺ إني لا أصافح النساء وتقول عائشة -رضي الله عنها-: \"والله ما مست يد رسول الله يد امرأة قط، ما كان يبايعهن إلا بالكلام\".  فليس لها أن تصافح غير محارمها، ولو كانوا إخوة لزوجها، أو أزواجًا لأخواتها. أما زوج أمها محرم لها، زوج أمها، زوج بنتها محرم، جد الزوج كذلك محرم، الأب أبو الزوج سواء من النسب، أو من الرضاعة، أبو الزوج من النسب، أو الرضاعة، جده من النسب، أو الرضاعة، ابنه من النسب، أو الرضاعة.. محارم، زوج البنت كذلك، سواء كان البنت من النسب، أو الرضاعة محرم. فالمصافحة للمحرم لا بأس به، وكونها تكشف له -أيضًا- وجهها لا بأس، أما غير المحارم فلا تكشف لهم، ولا تصافحهم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15009/حكم-مصافحة-المراة-وكشف-وجهها-لغير-المحارم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_810/nour_81010.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":16325,"question":"من سلطنة عمان المرسلة (م. م) تقول في سؤال لها: هل يجوز للمرأة أن تزيل بعض الشعر الذي ينبت على الوجه، علمًا بأنه يضايقها مثل الذي ينبت على الشوارب، وجوانب الخد؟","title":"هل يجوز للمرأة أن تزيل الشعر الذي ينبت على الوجه؟","answer":"الجواب: المرأة لا تتعرض للوجه، ولا للحاجبين إذا كانت الشعور الموجودة عادية، أما إذا نبت لها شيء يؤذيها، يشوهها كاللحية، أو الشارب فإنها تزيل ذلك، أما الشعر العادي الذي ليس فيه أذى، ولا مثلة، هذا لا يتعرض له. وهكذا الحاجبان لا تأخذهما، ولا تأخذ منهما شيئًا، لأن الرسول ﷺ لعن النامصة والمتنمصة وعلماء اللغة قالوا: النمص أخذ شعر الحاجبين، وأخذ شعر الوجه، لكن إذا كان في الوجه شيء يشوه الخلقة... كاللحية، والشارب؛ فإنها تزيل ذلك، ولا حرج عليها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15021/هل-يجوز-للمراة-ان-تزيل-الشعر-الذي-ينبت-على-الوجه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_810/nour_81017.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":16336,"question":"من اليمن المستمع (ف. ع. ج) يقول: أسأل سماحتكم عن حكم من تحلق رأسها تشبهًا بالرجال، هل هذا جائز، أو لا؟","title":"حكم حلق المرأة شعر رأسها","answer":"الجواب: لا يجوز حلق الرأس للمرأة، بل يجب أن تبقي الرأس؛ لأنه جمال لها، وزينة لها، وفرق بينها وبين الرجال، فليس لها حلقه حتى في الحج، إنما هي تقصر في الحج، وفي العمرة كذلك، لقول النبي ﷺ: ليس على النساء حلق، وإنما يقصرن. فالرأس لهن جمال، فليس لهن حلقه، إلا إذا كان علة مرض، رأى الأطباء أن يزال، للمرض هذا شيء آخر للعلة، وإلا فليس لهن حلقه تساهلًا، أو تقليدًا للكفرة، أو لغيرهم، لا، بل الواجب تربيته، والعناية به، لما فيه من الجمال، لكن إذا خففت منه -قصرت منه- فلا بأس لطوله، أو لكثافته، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15030/حكم-حلق-المراة-شعر-راسها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_713/nour_71312.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":16371,"question":"يسأل ويقول: ما هو توجيه سماحتكم لمن أراد أن يتخذ خاتمًا من فضة، أو يضع سنًا من فضة؟ جزاكم الله خيرًا، وهل هذا حلال، أم حرام؟","title":"حكم اتخاذ الخاتم أو السن من الفضة","answer":"الجواب: الخاتم من الفضة لا بأس به، وضعه النبي ﷺ والصحابة، فخاتم الفضة لا بأس به للرجال والنساء، أما وضع السن من الفضة، أو من الذهب إذا دعت إليه الحاجة؛ فلا بأس، وإلا فالأولى أن يتخذ من غير الذهب والفضة من المعادن الأخرى، والجواهر الأخرى، والمواد الأخرى، وهناك مواد يتخذ منها أسنانًا غير الذهب والفضة، تكفي عن الذهب والفضة، لكن إذا دعت الحاجة إلى ذلك، إلى الذهب والفضة؛ فلا حرج، في حق الرجل، وأما المرأة؛ فلا بأس بذلك، من باب أولى إذا دعت الحاجة إلى ذلك؛ فلا بأس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15077/حكم-اتخاذ-الخاتم-او-السن-من-الفضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_754/nour_75408.mp3","categories":["اللباس والزينة"]},{"id":16377,"question":"من أحد الإخوة المستمعين وقع في نهاية رسالته صابر محمد علي من الجوف، الأخ صابر له رسالة وضمنها جمعًا من الأسئلة، في أحد أسئلته يقول: هل صبغ شعر الرأس واللحية حلال، أم حرام؟","title":"حكم صبغ شعر الرأس واللحية","answer":"الجواب: السنة صبغ شعر الرأس واللحية إذا خطه الشيب، السنة أن يصبغ بغير السواد لقول النبي ﷺ: غيروا هذا الشيب، واجتنبوا السواد وكان ﷺ يصبغ والصحابة كذلك، فالسنة تغيير الشيب بالصفرة والحمرة، أو بالسواد المخلوط بغيره. أما السواد الخالص فهذا ممنوع؛ لأن الرسول نهى عنه -عليه الصلاة والسلام- وهذا للمرأة والرجل، يستحب تغيير الشيب من المرأة والرجل، في الرأس للرجل والمرأة، وفي اللحية أيضًا للرجل بهذا الحديث الصحيح: غيروا هذا الشيب، واجتنبوا السواد اللهم صل عليه وسلم، نعم.","link":"https://binbaz.org.sa/fatwas/15076/حكم-صبغ-شعر-الراس-واللحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_752/nour_75207.mp3","categories":["اللباس والزينة"]},{"id":16382,"question":"رجل أمر زوجته بارتداء الحجاب الشرعي فأبت، ماذا يفعل؟","title":"توجيه للزوج الذي ترفض زوجته الحجاب","answer":"الجواب: يستمر في نصيحتها، ويتعاون مع أهلها في ذلك؛ لعل الله يهديها بأسبابه؛ لأن هذه معصية، فعليه أن يستمر في النصيحة، ولا مانع من تأديبه لها على ذلك تأديبًا لا يضرها، بضرب غير مبرح من باب إنكار المنكر، إذا كانت لا تبالي بذلك عند الأجناب، عند الرجل الأجنبي، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15089/توجيه-للزوج-الذي-ترفض-زوجته-الحجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_754/nour_75412.mp3","categories":["الدعوة والدعاة","الآداب والأخلاق المحمودة","اللباس والزينة"]},{"id":16391,"question":"يسأل أخيرًا عن المعرس، وعن حكم الحناء له، ووضع الورد على الحناء؟","title":"حكم استعمال الحناء للرجال عند الأعراس","answer":"الجواب: لا نعلم لهذا أصلًا، والحناء من أعمال النساء، ومن صفات النساء، ليس من أعمال الرجال، كونها تجعل الحناء في يديها، أو في رجليها، هذا من صفات النساء، ومن تزينهن لأزواجهن، أما إذا كان في بلد من عادتهم وضع الحناء للرجل في يد، أو في رأس، أو في غيره، عادة له ليس للتشبه، ليس من التشبه بل هو عادة لهم... الرجال فهذا لا يكون فيه تشبه، إذا كان من عادتهم أن الرجال يفعلونه، ليس من خصائص النساء، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15097/حكم-استعمال-الحناء-للرجال-عند-الاعراس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_754/nour_75417.mp3","categories":["اللباس والزينة"]},{"id":16398,"question":"لها سؤال آخر تقول فيه، هل يجوز الذهاب لزيارة أختي في مدينة أخرى، والإقامة عندها لمدة أسبوع مثلًا، أو أكثر، مع غير محرم، ما حكم ذلك؟ جزاكم الله خيرًا.","title":"هل يجوز للمرأة الذهاب إلى مدينة أخرى من غير محرم؟","answer":"الجواب: السفر بغير محرم ما يجوز، سواء لأختك، أو لأبيك، أو غيره، لا بد من المحرم إذا كانت المسافة سفرًا، مثل ثمانين كيلو، أو ما يقاربها، أو أكثر من ذلك، هذا يعد سفرًا، يوم وليلة للمطية، ويعد سفرًا عرفًا، فليس لك السفر إلا بمحرم، لا لزيارة أختك، ولا لغير هذا، لقول النبي ﷺ: لا تسافر امرأة إلا مع ذي محرم رواه الشيخان: البخاري ومسلم في الصحيحين، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15111/هل-يجوز-للمراة-الذهاب-الى-مدينة-اخرى-من-غير-محرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_811/nour_81111.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":16413,"question":"من القصيم بريدة المستمع: عبد الله الصالح رسالة وضمنها جمعًا من الأسئلة، في أحدها يقول: هل يجوز للمرأة أن تكلم الأجانب عن طريق الهاتف؟ جزاكم الله خيرًا، وهل هناك من شروط معينة تودون بيانها؟ جزاكم الله خيرًا.","title":"ما حكم محادثة المرأة للأجانب في الهاتف؟","answer":"الجواب: لا حرج في تكليم المرأة للرجل من طريق الهاتف إذا كان في مصلحة شرعية، أو أمر مباح كالسؤال عن العلم، أو سؤاله عن مريض، أو سؤاله عن صحته، أو عن شيء مهم، لا بأس بذلك. أما إذا كانت المكالمة لمغازلة كما يقولون، ولأسباب الفتنة، والدعوة إلى الفاحشة، أو ما يجر إلى الفاحشة، هذا لا يجوز، الواجب على المرأة أن تحذر ذلك، وعلى الرجل أن يحذر ذلك، ليس للرجل أن يكلم النساء لهذا الغرض، وليس للمرأة أن تكلم الرجال لهذا الغرض، بل هذا يجر إلى شر كثير، وفساد عظيم، أما كونها تكلم زوج أختها، أو ابن عمها تسأله عن صحته، أو صحة أولاده، أو صحة والدته، أو أبيه، أو عن حاجة تسألها عنه لشراء حاجة، أو بيع حاجة، أو ما أشبهه من الأمور التي ليس فيها شبهة، ولا ريبة ولا شر، فلا حرج في ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15167/ما-حكم-محادثة-المراة-للاجانب-في-الهاتف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_812/nour_81211.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":16414,"question":"رسالة وصلت إلى البرنامج من الرياض، وباعثها مستمع رمز إلى اسمه بالحروف: (ع. ب. ز) يسأل جمعًا من الأسئلة في أحدها يقول: ما حكم حلق بعض الشعر، وترك بعضه؟ وما حكم تخفيف الشعر قليلًا؟ جزاكم الله خيرًا.","title":"حرمة حلق بعض شعر الرأس وترك بعضه","answer":"الجواب: أما حلق البعض، وترك البعض هذا لا يجوز، بعض أهل العلم جزم بالكراهة، وظاهر الحديث التحريم؛ لأن النبي ﷺ قال: احلقه كله، أو دعه كله فلا يحلق بعض رأسه، ويترك البعض لا، إما أن يحلقه كله، أو يدعه كله، وإذا خفف بمكينة؛ فلا بأس، إذا عمم بالمكينة، ولم يحلقه، فلا بأس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15148/حرمة-حلق-بعض-شعر-الراس-وترك-بعضه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_812/nour_81205.mp3","categories":["اللباس والزينة"]},{"id":16422,"question":"من القصيم بريدة المستمع: عبد الله الصالح رسالة وضمنها جمعًا من الأسئلة، في أحدها يقول: هل يجوز للمرأة أن تكلم الأجانب عن طريق الهاتف؟ جزاكم الله خيرًا، وهل هناك من شروط معينة تودون بيانها؟ جزاكم الله خيرًا.","title":"ما حكم محادثة المرأة للأجانب في الهاتف؟","answer":"الجواب: لا حرج في تكليم المرأة للرجل من طريق الهاتف إذا كان في مصلحة شرعية، أو أمر مباح كالسؤال عن العلم، أو سؤاله عن مريض، أو سؤاله عن صحته، أو عن شيء مهم، لا بأس بذلك. أما إذا كانت المكالمة لمغازلة كما يقولون، ولأسباب الفتنة، والدعوة إلى الفاحشة، أو ما يجر إلى الفاحشة، هذا لا يجوز، الواجب على المرأة أن تحذر ذلك، وعلى الرجل أن يحذر ذلك، ليس للرجل أن يكلم النساء لهذا الغرض، وليس للمرأة أن تكلم الرجال لهذا الغرض، بل هذا يجر إلى شر كثير، وفساد عظيم، أما كونها تكلم زوج أختها، أو ابن عمها تسأله عن صحته، أو صحة أولاده، أو صحة والدته، أو أبيه، أو عن حاجة تسألها عنه لشراء حاجة، أو بيع حاجة، أو ما أشبهه من الأمور التي ليس فيها شبهة، ولا ريبة ولا شر، فلا حرج في ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15167/ما-حكم-محادثة-المراة-للاجانب-في-الهاتف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_812/nour_81211.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":16433,"question":"مصافحة البنت التي لم تبلغ؟","title":"حكم مصافحة البنت التي لم تبلغ","answer":"الجواب: إذا كانت صغيرة لا يضر دون التسع؛ لأنها ليست محلًا للشهوة، أما إذا كانت بنت التسع، فأكثر، فالذي ينبغي ترك مصافحتها؛ لأنها حينئذ محلًا للشهوة، وتعتبر امرأة؛ فلا ينبغي أن تصافح الرجل الأجنبي، هذا هو الذي ينبغي للمؤمن التحرز من الشر، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15129/حكم-مصافحة-البنت-التي-لم-تبلغ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_755/nour_75507.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":16438,"question":"هذه أختكم من سوريا دمشق (ج. أ) رمزت لاسمها، تقول: سماحة الشيخ! ما الحكم في إزالة الشعر الموجود بين الحاجبين، أي: عند ملتقى الحاجبين إذا كان منظره غير محبب؟","title":"حكم إزالة الشعر النابت بين الحاجبين","answer":"الجواب: لا حرج -إن شاء الله- لأنه ليس من الحاجبين، هذا ليس من الحاجبين، ما بينهما ليس من الحاجبين، أما الحاجبان فلا لا يؤخذ منهما شيء، أما ما بينهما فلا حرج، نعم.","link":"https://binbaz.org.sa/fatwas/15136/حكم-ازالة-الشعر-النابت-بين-الحاجبين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_581/58130.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":16445,"question":"في آخر أسئلة السائلة أختكم (ج. أ) من سوريا دمشق، تقول: المكياج؛ ما حكمه في الإسلام -حفظكم الله- هل نستطيع أن نقيس المكياج على الحناء، والكحل اللذين أمر بهما الرسول ﷺ زوجاته؟","title":"حكم استعمال المرأة المكياج","answer":"الجواب: المكياج إذا كان لا يضر الوجه؛ فلا حرج، من باب الزينة، إذا كان لا يضر الوجه، ولا يسبب ضررًا؛ فلا حرج في ذلك، أما إذا كان يسبب ضررًا؛ فلا يفعل، أما إذا كان لا إنما هو ينور الوجه، ولكن لا يحصل به ضرر؛ فلا حرج، نعم. المقدم: خصوصًا سماحة الشيخ بأن المرأة تتزين بهذا لزوجها؟ الجواب: المقصود إذا كان لا ضرر فيه، لا حرج الحمد لله، الرسول ﷺ قال: لا ضرر ولا ضرار مثل الكحل، ومثل الديرمة، وأشباهها. نعم.","link":"https://binbaz.org.sa/fatwas/15141/حكم-استعمال-المراة-المكياج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_581/58132.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":16449,"question":"هذا السائل الأخ مقرن المحبوب كتب سؤالين، يقول: نويت العمرة يا سماحة الشيخ، وأحرمت من مطار الرياض، ولبيت بالعمرة عند قربي من الميقات، وعند نزولنا في مطار جدة ذهبت لأتوضأ للصلاة، فوجدت أنني لم أخلع السروال ناسيًا، فخلعته، فهل علي شيء في ذلك؟","title":"ما حكم من نسي خلع السراويل عند الإحرام؟","answer":"الجواب: ليس عليك شيء، يقول الله -جل وعلا-: رَبَّنَا لا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا [البقرة:286] فالمحرم إذا نسي؛ غطى رأسه، أو لبس القميص، أو السراويل ناسيًا؛ فلا حرج عليه، أو أحرم والسروال عليه ناسيًا؛ فلا حرج عليه، والحمد لله، نعم.","link":"https://binbaz.org.sa/fatwas/15157/ما-حكم-من-نسي-خلع-السراويل-عند-الاحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_582/58204.mp3","categories":["اللباس والزينة","محظورات الإحرام","قضايا المرأة"]},{"id":16477,"question":"سماحة الشيخ! هذه السائلة أم أحمد تقول: أختي تكثر الخروج إلى الأسواق، والمجمعات، وإذا نصحناها عن ذلك؛ قالت بأن ذلك ليس بحرام؟","title":"حكم إكثار المرأة من الخروج إلى الأسواق","answer":"الجواب: نصيحتها مناسبة، الخروج وسيلة إلى شر إذا كان ما له حاجة، الخروج إلى الأسواق قد تفضي إلى التبرج، قد تفضي إلى عدم التستر. المقصود: أن الخروج إلى الأسواق، والمجمعات بغير عذر شرعي تركه أولى، وأحوط، الله يقول سبحانه لأزواج نبيه ﷺ: وَقَرْنَ فِي بُيُوتِكُنَّ [الأحزاب:33] فالجلوس في البيت أولى إلا من حاجة، كونها تخرج بغير حاجة الأولى لها ترك ذلك، والمحافظة على بقائها في البيت؛ حذرًا من تبرج، أو تساهل في التستر، أو غير هذا من الأسباب التي قد تجر إلى الشر، فعدم الخروج أولى، إلا من حاجة، وعليكم النصيحة، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15179/حكم-اكثار-المراة-من-الخروج-الى-الاسواق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_582/58209.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":16498,"question":"تقول عن نفسها: أنا فتاة أبلغ من العمر السادسة عشر، وأريد أن أرتدي النقاب، ولكن أهلي لا يوافقون ويقولون لي: إني ما زلت...الشيخ: أعد.المقدم: تقول: أنا فتاة أبلغ من العمر السادسة عشرة، وأريد أن أرتدي النقاب، ولكن أهلي لا يوافقون، ويقولون لي: إني ما زلت صغيرة على ذلك، فما رأيكم؟ جزاكم الله خيرًا. ب","title":"حكم طاعة البنت أهلها في عدم ارتداء الحجاب","answer":"الجواب: الواجب عليك ارتداء النقاب، والتحجب عن الرجال الأجانب، ولو أبى أهلك في ذلك، ليس لهم طاعة في هذا، يقول النبي ﷺ: إنما الطاعة في المعروف والمعروف هو ما شرعه الله -جل وعلا- وأباحه، ويقول ﷺ: لا طاعة لمخلوق في معصية الخالق. فالواجب عليك التستر، والحجاب عن الأجنبي، كأخي الزوج، أو عمه، وكالجيران الذين ليسوا بمحارم، وغيرهم، كل رجل ليس محرمًا لك؛ عليك التحجب عنه، ولو أبى أهلك ذلك، لا، ليس لك أن تطيعيهم في ذلك. والواجب عليهم أن يساعدوك على الخير، والحجاب، هذا هو الواجب عليهم؛ لأن الله يقول سبحانه: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2] ويقول سبحانه: وَالْعَصْرِ ۝ إِنَّ الإِنسَانَ لَفِي خُسْرٍ ۝ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ [العصر:1-3] فالواجب التواصي بالحق، والتواصي بالحجاب من التواصي بالحق، ويقول سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71]، والأمر بالحجاب أمر بالمعروف، والنهي عن الحجاب أمر بالمنكر. فنوصيك بالتستر والحجاب، ومخالفة أهلك في ذلك، حتى ولو كنت أقل من ست عشر، إذا حاضت المرأة، ولو بنت عشر، أو تسع؛ صارت امرأة تحتجب، ولو أنها بنت تسع، أو عشر، أو إحدى عشرة، أو ما أشبه ذلك، أما بنت ست عشرة فهي امرأة كبيرة، قد بلغت بالسن، وقد يكون جاءها الحيض قبل ذلك. فالحاصل: أن بنت ست عشر سنة امرأة كبيرة، عليها أن تحتجب، وعليها أن تغض بصرها، وعليها أن تبتعد عن أسباب الفتنة، نسأل الله لنا ولك ولأهلك التوفيق والهداية.  المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/15262/حكم-طاعة-البنت-اهلها-في-عدم-ارتداء-الحجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_814/nour_81409.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":16514,"question":"لها سؤال آخر تقول فيه: هل يجوز للمرأة أن تقص من بعض شعرها من الأمام بقصد التجمل لزوجها، وأمام النساء؟","title":"ما حكم قص المرأة مقدمة رأسها بقصد التجمل؟","answer":"الجواب: لا أعلم في هذا بأسًا، إذا كان المقصود هو التجمل، أو التخفيف، وليس المقصود التشبه بالرجال، ولا التشبه بالكافرات؛ فلا حرج في ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15225/ما-حكم-قص-المراة-مقدمة-راسها-بقصد-التجمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_756/nour_75610.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":16534,"question":"سماحة الشيخ، هذه سائلة للبرنامج تقول: امرأة أصيبت بعين لجمال شعرها، وأصبح الشعر الطويل يؤذيها، ففي كل شهر تضطر أن تقصه إلى بداية رقبتها تحت الأذن، ما حكم هذا القص؟ وماذا تفعل حفظكم الله؟","title":"ما حكم قص المرأة شعرها للضرورة؟","answer":"الجواب: إذا دعت الحاجة إلى هذا لا بأس؛ لقص أمهات المؤمنين، زوجات النبي ﷺ لما توفي ﷺ قصصن من رؤوسهن، خففن منها لكلفة التعب في مشطها، وشدها، ونحو ذلك، فإذا قصت منه لمصلحة أنه يؤذيها، ويضرها؛ فلا حرج، لكن لا تقصه للتشبه بالرجال، أو التشبه بالكافرات، لا، إذا قصت من رأسها للمشقة، للتعب فلا بأس. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15256/ما-حكم-قص-المراة-شعرها-للضرورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_583/58310.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":16536,"question":"سماحة الشيخ من أسئلة هذه السائلة حفظكم الله تسأل، وتقول: ما حكم لبس القصير بالنسبة للمرأة أثناء وجود المحارم من أب، وعم إلى غيرهم، ويكون هذا القصر بمقدار شبر من فوق الكعب؟","title":"حكم لبس المرأة للقصير بين المحارم","answer":"الجواب: الأفضل أن تكون محتشمة، هذا هو الأفضل لها، وإلا ساقها ما هو بعورة بالنسبة إلى محرمها، أخيها، وأبيها، وهكذا رأسها ليس بعورة، لكن كونها تحتشم، وتستر ساقها، ورأسها، ولا تبدي إلا الوجه، والكفين يكون هذا أفضل، وأبعد عن الخطر؛ لأن بعض المحارم قد يكون لا خير فيه، فإذا تسترت، واحتشمت في ساقيها وستر رأسها وذراعيها؛ كان ذلك أكمل، وأحوط، أبعد عن الشبهة،  نعم. المقدم: جزاكم الله خيرًا يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15263/حكم-لبس-المراة-للقصير-بين-المحارم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_583/58312.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":16583,"question":"يسأل أخونا فيقول: ما حكم الإسلام في المرأة المتحجبة بكاملها، باستثناء أسفل عقبيها، هل يجوز لها ذلك؟","title":"ما حكم ستر المرأة لعقبيها؟","answer":"الجواب: الواجب عليها ستر العقبين، ستر رجليها؛ لأنها عورة، فعليها أن تستر رجليها بإرخاء الثياب، أو بالجوارب، والحمد لله، نعم. المقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/15312/ما-حكم-ستر-المراة-لعقبيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_758/nour_75806.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":16598,"question":"سوداني يعمل بالإمارات بعث برسالة يقول فيها: محمد عبدالقادر سليمان: هل يجوز للمسلم أن يلبس نعلين من جلد النمر، أو أن يجلِّد سكينه بجلد التمساح، علمًا بأنني قرأت في رياض الصالحين: أنه لا يحل للمسلم أن يفترش فراشًا من جلد النمر، أو الحيوانات المفترسة؟","title":"حكم افتراش جلود السباع","answer":"الجواب:  النبي ﷺ \"نهى عن افتراش جلود السباع\" فينبغي لك أن تبتعد عن هذا النمر، وغير النمر، وتكتفي بالجلود الطيبة من المذكاة من الإبل، والبقر، والغنم، وفيها كفاية، والحمد لله. أما جلود السباع فابتعد عنها: النمر، والذئب، والأسد، وغير ذلك، رزق الله الجميع العافية والسلامة، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15322/حكم-افتراش-جلود-السباع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_817/nour_81705.mp3","categories":["اللباس والزينة"]},{"id":16614,"question":"سماحة الشيخ، كثر الكلام في هذه الآونة عن البرقع، إذ أنه أصبح يأخذ شكلًا ما يسمى بالموضة، فما هو رأي سماحتكم في البرقع من حيث هو؟ وما توجيه سماحتكم للنساء إذا أردن لبس هذا النوع من الملابس؟","title":"ما حكم لبس البرقع للنساء؟","answer":"الجواب: كان لبس البرقع من عادة العرب، يلبسون البراقع، ويقال له: النقاب، يفتح فيه للعين، أو العينين نقب، وتستر به وجهها، ولهذا نهى النبي ﷺ عن لبسه في حال الإحرام للمرأة، قال: لا تنتقب المرأة، ولا تلبس القفازين في حالة الإحرام بالعمرة، أو بالحج معناه: أنه في غير ذلك، لا بأس أن تلبس البرقع، والقفازين في الأوقات الأخرى؛ للتستر، والحجاب. فلا حرج في لبس القفازين، والنقاب للمرأة في غير الإحرام للتستر عن الرجال، وإذا سترت وجهها بغير النقاب؛ بالخمار كله، أو بغيره من الألبسة: كالجلال، والجلباب، ونحو ذلك، كله طيب، والنقاب يكون بقدر العينين، أو عين واحدة ما يكون مكشوف الوجنتين، ولا الجبهة، بقدر العينين فقط، هذا هو الجائز. وأما منعه، وتحريمه فلا دليل عليه، بل السنة ظاهرة بالجواز لغير المحرمة، لكن يكون بقدر العينين، أو إحداهما، وإذا لبست خمارًا، أو جلالًا يسترها، فلا بأس، تقول عائشة -رضي الله عنها-: \"كنا مع النبي ﷺ في حجة الوداع محرمات، فإذا دنا منا الرجال؛ سدلت إحدانا جلبابها -أوقالت: خمارها- على وجهها من رأسها، فإذا بعدوا؛ كشفنا\" فمعنى هذا: أنهم ما لبسوا النقاب، نعم، فهذا يدل على أن هذا جائز، وهذا جائز، نعم. فإذا سدلت الخمار، أو الجلباب على وجهها بالكلية، على وجه ترى معه الطريق؛ فلا بأس، وإذا رأت أن إظهار عينيها فيه فتنة، وأنها تخشى الفتنة؛ فلتخمر وجهها بغير ذلك، من الخمار، والشيلة المعروفة، أو بغير ذلك، إذا كانت ترى أن إظهار عينيها قد يحصل به فتنة، فهي أعلم بنفسها.","link":"https://binbaz.org.sa/fatwas/15349/ما-حكم-لبس-البرقع-للنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_758/nour_75819.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":16615,"question":"يسأل أخونا أيضًا ويقول: توجهون الناس أيضًا حول الحجاب الشرعي، أحسن الله إليكم؟","title":"توجيه حول الحجاب الشرعي","answer":"الشيخ: نعم، سبق المرأة كلها عورة، كلها عورة، لكن عليها أن تجتهد في التستر، والبعد عن فتنة الرجال بالحجاب الساتر الكافي، لوجهها، وبدنها جميعًا؛ لأنها كلها عورة كما قال الله : وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] ولم يستثن شيئًا، إلا ما حصل... النقاب... حديث ابن عمر في الصحيحين... بل في صحيح البخاري. وهكذا قوله -جل وعلا- في سورة النور: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ [النور:31].. الآية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15350/توجيه-حول-الحجاب-الشرعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_758/nour_75820.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":16648,"question":"تقول: قرأت في كتاب عن أسماء بنت يزيد أن رسول الله ﷺ قال: أيما امرأة تقلدت قلادة من ذهب؛ قلدت في عنقها مثلها من النار يوم القيامة، وأيما امرأة جعلت في أذنها خرصًا من ذهب؛ جعل الله في أذنها مثله من النار يوم القيامة رواه أبو داود، والنسائي، وعن أخت لحذيفة أن رسول الله ﷺ قال: يا معشر النساء، أما لكن في الفضة ما تحلينن به، أما إنه ليس منكن امرأة تحلي ذهبًا تظهره إلا عذبت به رواه أبو داود، والنسائي، وإسناده ضعيف، فما قول سماحتكم في هذه الأحاديث، وما هو توجيهكم لنا؟ جزاكم الله خيرًا.","title":"توجيه حول الأحاديث الدالة على حرمة الذهب على النساء","answer":"الجواب: هذه الأحاديث التي فيها النهي عن لبس الذهب بعضها ضعيف، وبعضها منسوخ. وقد أجمع المسلمون على حل الذهب للنساء، وتحريمه على الرجال، فلا حرج في ذلك، والحمد لله. كونها تلبس قلادة من الذهب، أو أسورة من الذهب، أو خاتمًا من الذهب، كل هذا لا حرج فيه في حق النساء؛ لقوله ﷺ في الحديث الصحيح: أحل الذهب، والحرير لإناث أمتي، وحرم على ذكورهم فالذهب، والحرير مباحان للنساء، ومحرمان على الذكور، وقد جاءت إليه امرأة قالت: يا رسول الله، جاءت امرأة وعليها مسكتان من ذهب، فقال النبي ﷺ: أتعطين زكاة هذا؟ قالت: لا. قال: أيسرك أن يسورك الله بهما يوم القيامة سوارين من نار؟ فألقتهما وقالت: هما لله ولرسوله\" فلم ينكر عليها اللبس، وإنما أمرها بالزكاة. فالمقصود: أن الأسورة من الذهب، وهكذا القلائد، وهكذا الخواتم، وهكذا الأقرطة كلها مباحة للنساء عند أهل العلم، وهو إجماع منهم ليس في ذلك إلا خلاف شاذ، لا يعول عليه. فلا ينبغي لأحد أن يشك في هذا الأمر، فالذهب، والحرير حل للإناث، حرام على الذكور، وما جاء في بعض الأحاديث من تحريم الذهب على النساء فهو ضعيف، أو منسوخ بالأحاديث الصحيحة الأدلة الواضحة الدالة على حله للنساء، وأن الله أباح الذهب والحرير للنساء، دون الرجال، هذا هو المعتمد الذي عليه أهل العلم، وهو الحق، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15381/توجيه-حول-الاحاديث-الدالة-على-حرمة-الذهب-على-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_717/nour_71711.mp3","categories":["اللباس والزينة","الحكم على الأحاديث"]},{"id":16659,"question":"أخيرًا تقول السائلة يا سماحة الشيخ: أسأل عن حكم استخدام أدوات التجميل الكثيرة التي توضع لكل جزئية من أجزاء الوجه؟","title":"ما حكم استخدام أدوات التجميل؟","answer":"الجواب: التجميل لا بأس به إذا كان شيئًا ما يغير خلقة الله، مثل الحناء، مثل الكحل في العين، مثل الديرمة في الشفة، وما أشبه ذلك، الشيء المستعمل المعتاد الذي لا حرج فيه، ولا نجاسة فيه؛ لا بأس، التجمل بين النساء، وبين زوجها لا بأس بذلك إذا كان ليس فيه محذور. أما إذا كان فيه محذور، مثل الوشم، الوشم منهي عنه، الرسول ﷺ لعن الواشمة، والمستوشمة، أو مثل قص الحواجب، أو نتف الحواجب، هذا منكر، أو استعمال شيء نجس لا يجوز استعماله، أو ما أشبهه، أما إذا كان التجمل بشيء مباح، مثل الكحل، ومثل صبغ الشفة بالديرمة، أو أشباه ذلك شيء مباح، لا حرج فيه، نعم.","link":"https://binbaz.org.sa/fatwas/15392/ما-حكم-استخدام-ادوات-التجميل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_583/58316.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":16670,"question":"سماحة الشيخ كثيرة هي الأسئلة التي تتوارد على الخاطر، وأنا أنصت إلى ما تتفضلون به حول ما اهتم به ديننا تجاه المرأة، وتجاه تكاليفها، وتجاه خطابها كخطاب الرجل سواء بسواء، لعل لسماحتكم من كلمة حول حجاب المرأة، وصلة الأرحام؛ لأن البعض يعتقد أن الحجاب يحول دون صلة الرحم، فما هو تعليق سماحتكم؟","title":"توجيه حول الحجاب وصلة الرحم","answer":"الجواب: الحجاب لا يحول بين المرأة، وصلة الرحم، الحجاب ومنع الخلوة، هذا من كمال الدين، ومن باب البعد عن الشر، والفساد؛ لأنه إذا وصلت أرحامها من بني عم، أو بني عمة، أو بني خال، وهي متبرجة، أو سافرة؛ فهذا من أسباب الفساد، وكذا إذا خلت بواحد من بني عمها، أو بني خالها، هذا من أسباب الفساد. فمن رحمة الله، ومن إحسانه العظيم، ومن كمال الشريعة: أنه حرم على المرأة، وعلى الرجل الخلوة، على الرجل الخلوة بغير محرمه، وعلى المرأة الخلوة بغير محرمها، حرام على هذا وهذا، فعلى الرجل أن يتقي الله، ولا يخلو بمرأة أجنبية، وعلى المرأة أن تتقي الله أيضًا، ولا تخلو برجل أجنبي، لا السائق، ولا غيره، لا السائق، ولا خادم، ولا غيرهما، لا تخلو بالرجل أبدًا. يقول النبي ﷺ في الحديث الصحيح: لا يخلون رجل بامرأة؛ فإن الشيطان ثالثهما ويقول ﷺ: إياكم والدخول على النساء وفي لفظ: المغيبات اللاتي ما عندهن أحد قيل: يا رسول الله! أفرأيت الحمو؟ قال: الحمو الموت الحمو.  يعني: الأخ، والعم، وابن العم، وابن الخال، والخال، وأشباهه؛ سماه موتًا؛ لأنه خطر، يدخل، ولا يستنكر ..، قد يخلو بزوجة أخيه، أو يخلو بزوجة خاله، أو بزوجة ابن أخيه؛ فتقع المصيبة، وتقع الفاحشة... والواجب الحذر من الخلوة: لا بزوجة الأخ، ولا بأخت الزوجة، ولا بزوجة الخال، ولا بزوجة العم، ولا ابن العم، ولا ابن الخال. أما زوجة الأب محرم، زوجة الجد محرم، زوجة ابنك محرم؛ من النسب والرضاعة، ابن البنت زوجته محرم، وهكذا... محارم بالنسب، أو بالرضاع، بالنسب، والمصاهرة: كأم الزوجة... بنت الزوجة المدخول بها، جدة الزوجة محرم؛ من أجل المصاهرة، سواء كانت من النسب، أو من الرضاع، يقول النبي ﷺ: يحرم من الرضاع ما يحرم من النسب. أما الخلوة فخطرها عظيم، لكن إذا كان معهما ثالث في السيارة، أو في البيت مثلًا: جلس مع امرأة أخيه، وهي مستورة متحجبة، ولكن بحضرة أمه، أو بحضرة أخته، أو بحضرة شخص آخر، لا شبهة فيه، ولا ريبة فيه؛ زالت الخلوة، وهكذا لو ركبت مع السائق ومعها شخص آخر، أو امرأة أخرى بدون ريبة؛ زالت الخلوة، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15433/توجيه-حول-الحجاب-وصلة-الرحم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_760/nour_76007.mp3","categories":["قضايا المرأة","نصائح وتوجيهات","اللباس والزينة"]},{"id":16722,"question":"يقول السائل سماحة الشيخ: أنا مقيم بالرياض، وأريد أن أحضر والدتي لحج هذا العام -إن شاء الله- وهي كبيرة في السن، حوالي سبعين سنة، واستطاعتي أن أحضرها، وأقابلها في جدة، وهي ستحضر -إن شاء الله- مع نساء كبيرات في السن، ورفقة مأمونة..الشيخ: أعد.المقدم: يقول السائل: سماحة الشيخ! أنا مقيم بالرياض، وأريد أن أحضر والدتي لحج هذا العام -إن شاء الله- ووالدتي كبيرة في السن حوالي سبعين سنة، وباستطاعتي أن أحضر إلى المطار، وأن أقابلها في جدة، وهي ستحضر مع نساء كبيرات في السن، ورفقة مأمونة، أرجو أن تفتوني في ذلك مأجورين.","title":"حكم سفر المرأة كبيرة السن بغير محرم","answer":"الجواب: ليس لها أن تسافر إلا بالمحرم، تسافر إليها، وتنقلها من البلد التي هي فيها، وأنت محرمها، والا أخ لك، والا عم، والا أخ لك ثاني، والا ابن أخيها، والا ابن بنتها، لابد من محرم، يقول النبي ﷺ: لا تسافر امرأة إلا مع ذي محرم اللهم صل عليه وسلم، نعم. المقدم: اللهم صل وسلم على نبينا محمد.","link":"https://binbaz.org.sa/fatwas/15463/حكم-سفر-المراة-كبيرة-السن-بغير-محرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_584/58426.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":16780,"question":"يسأل ويقول: ما حكم قص الشعر للفتيات بقصد الزينة لا بقصد التشبه بالرجال؟ جزاكم الله خيرًا.","title":"ما حكم قص شعر الفتيات بقصد الزينة؟","answer":"الجواب: لا حرج في ذلك، إذا كان بقصد الزينة، والتجمل، ليس بقصد التشبه بالرجال، ولا التشبه بالكافرات، وإذا كان لها زوج؛ فلا بد من إذنه، نعم.","link":"https://binbaz.org.sa/fatwas/15528/ما-حكم-قص-شعر-الفتيات-بقصد-الزينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_762/nour_76212.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":16795,"question":"سماحة الشيخ! هذه السائلة من سوريا دمشق تقول: سماحة الشيخ! سؤالي عن النقاب -غطاء الوجه- ما حكمه في الشرع؟ هل هو من الواجبات المفروضة على المرأة؟ أم هو من الأفضل، والأولى؟ وهل هناك خلاف بين العلماء في هذه المسألة؟ أرجو أن توضحوا لنا ذلك بالتفصيل، وجزاكم الله خيرًا.","title":"حكم تغطية المرأة لوجهها","answer":"الجواب: النقاب وهو الحجاب واجب على الصحيح، فيه خلاف بين العلماء، لكن الصحيح أنه واجب على المرأة أن تختمر، أن تغطي وجهها عند الأجنبي، عند الرجال الأجانب؛ لأنها فتنة، كشف الوجه فتنة، فالواجب ستره؛ لقول الله : وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53].  قالت عائشة -رضي الله عنها- لما تخلفت عن النبي ﷺ في بعض الأسفار، وهي قد ذهبت تقضي حاجتها، فارتحلوا، ورحلوا هودجها، يظنون أنها فيه، فلما جاءت؛ لم تجدهم، فاضطجعت، ونامت، ترجو أن يرجعوا إليها، فجاء.. مر عليها صفوان المعطل، فلما رآها؛ عرفها، فقال: إنا لله وإنا إليه راجعون، قالت: \"فلما سمعت كلامه؛ انتبهت، وكان قد رآني قبل الحجاب\" فدل ذلك على أنها بعد الحجاب وجب عليهم ستر الوجوه، وإنما كان الكشف قبل الحجاب؛ ولأن كشفه وسيلة إلى شر كبير، نعم. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/15546/حكم-تغطية-المراة-لوجهها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_585/58509.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":16801,"question":"تقول: كيف تكفر المرأة عن ذلكم الذنب إذا وقع منها فعلًا؟ جزاكم الله خيرًا.","title":"كيفية توبة من تشبهت بالرجال","answer":"الجواب: الكفارة التوبة في كل ذنب، التوبة إلى الله، والندم على الماضي، والعزم ألا يعود، الرجل يعزم ألا يعود، ويندم على ما مضى، ويقلع من الذنب، والمرأة كذلك، في كل المعاصي، فالذي تشبه بالنساء؛ عليه الندم على ما مضى، والإقلاع، والعزم ألا يعود. والمرأة كذلك، لو تشبهت بالرجال؛ فعليها الندم على ما مضى منها، والحزن على ذلك، والعزم الصادق ألا تعود في ذلك، والإقلاع من ذلك، والحذر منه، وهكذا المعاصي الأخرى: كالزنا، وشرب المسكر، والعقوق للوالدين، أو أحدهما، وما أشبه ذلك، التوبة من ذلك تكفي بالندم على الماضي، والإقلاع من الذنب، والعزم الصادق ألا يعود فيها الرجل، والمرأة جميعًا.  الله يقول سبحانه: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31] هذا يعم الرجال والنساء، ويقول سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا تُوبُوا إِلَى اللَّهِ تَوْبَةً نَصُوحًا [التحريم:8] ويقول سبحانه في كتابه العظيم: وَإِنِّي لَغَفَّارٌ لِمَنْ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى [طه:82] ويقول النبي ﷺ: التوبة تهدم ما كان قبلها ويقول أيضًا -عليه الصلاة والسلام-: التائب من الذنب كمن لا ذنب له والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15560/كيفية-توبة-من-تشبهت-بالرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_823/nour_82303.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":16809,"question":"تقول: كيف تكفر المرأة عن ذلكم الذنب إذا وقع منها فعلًا؟ جزاكم الله خيرًا.","title":"كيفية توبة من تشبهت بالرجال","answer":"الجواب: الكفارة التوبة في كل ذنب، التوبة إلى الله، والندم على الماضي، والعزم ألا يعود، الرجل يعزم ألا يعود، ويندم على ما مضى، ويقلع من الذنب، والمرأة كذلك، في كل المعاصي، فالذي تشبه بالنساء؛ عليه الندم على ما مضى، والإقلاع، والعزم ألا يعود. والمرأة كذلك، لو تشبهت بالرجال؛ فعليها الندم على ما مضى منها، والحزن على ذلك، والعزم الصادق ألا تعود في ذلك، والإقلاع من ذلك، والحذر منه، وهكذا المعاصي الأخرى: كالزنا، وشرب المسكر، والعقوق للوالدين، أو أحدهما، وما أشبه ذلك، التوبة من ذلك تكفي بالندم على الماضي، والإقلاع من الذنب، والعزم الصادق ألا يعود فيها الرجل، والمرأة جميعًا.  الله يقول سبحانه: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31] هذا يعم الرجال والنساء، ويقول سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا تُوبُوا إِلَى اللَّهِ تَوْبَةً نَصُوحًا [التحريم:8] ويقول سبحانه في كتابه العظيم: وَإِنِّي لَغَفَّارٌ لِمَنْ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى [طه:82] ويقول النبي ﷺ: التوبة تهدم ما كان قبلها ويقول أيضًا -عليه الصلاة والسلام-: التائب من الذنب كمن لا ذنب له والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15560/كيفية-توبة-من-تشبهت-بالرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_823/nour_82303.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":16845,"question":"هل يجوز وضع السن الذهب؛ لأني سمعت من بعض زميلاتي: أن وضع السن الذهب محرم؛ لأن الماء لا يصل إلى السن أثناء الوضوء، فهل هذا صحيح؟","title":"ما حكم تركيب المرأة سنًا من ذهب؟","answer":"الجواب: لا حرج في ذلك للنساء من الذهب، وغير الذهب، لكن للرجل الأولى له أن يتخذ سنًا من غير الذهب؛ إذا تيسر ذلك، نعم. المقدم: وهذا السن للمرأة، سواء كان للتجمل، أو للضرورة؟ الجواب: لا حرج للتجمل، أو للضرورة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15614/ما-حكم-تركيب-المراة-سنا-من-ذهب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_824/nour_82411.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":16875,"question":"من جمهورية مصر العربية المستمعة (م. م. ع) تقول: هل تهذيب شكل الحاجب بأخذ قليل من الشعر منه حرام؟ وماذا عن باقي الوجه، وأخذ الشعر منه؟ وما هي النامصة؟ نريد توضيح ذلك جزاكم الله خيرًا.","title":"حرمة تهذيب شعر الحاجب","answer":"الجواب: الرسول ﷺ لعن النامصة، والمتنمصة، والنامصة التي تأخذ شعر الحاجبين، والمتنمصة التي تفعل ذلك بها، فالمقصود أن النمص أخذ شعر الحاجبين، ولو قليلًا، لا يجوز تهذيبه، ولا أخذ شيء من الحاجبين، ولا شعر الوجه العادي؛ لأن هذا هو النمص، لكن إذا كان هناك شعر يشوه الخلقة، كالشارب، أو اللحية، فإن هذا يؤخذ ولا حرج، أما أن تأخذ شعر الحاجبين، أو تهذب شعر الحاجبين، هذا لا يجوز، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15632/حرمة-تهذيب-شعر-الحاجب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_824/nour_82424.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":16881,"question":"أخيرًا تسأل أختنا، وتقول: لماذا حرم على الرجال لبس الذهب؟","title":"الحكمة من تحريم الذهب على الرجال","answer":"الجواب: الله أعلم؛ لأن الله -جل وعلا- هو الحكيم العليم  فالعباد عليهم أن يخضعوا لحكم الله، وأن يمتثلوه، سواءً عرفوا الحكمة، أم لم يعرفوها؛ لأن الله سبحانه حكيم عليم، يشرع لعباده ما هو أصلح لهم، وأنفع لهم، فحرم على الرجال لبس الذهب، وأباحه للنساء، قال جماعة من أهل العلم: إن الحكمة في ذلك أن الذهب من الزينة، والمرأة في حاجة للزينة لزوجها؛ حتى يرغب فيها، وحتى يميل إليها، وهكذا الحرير، أبيح للنساء دون الرجال؛ لأنه زينة طيبة، فكان ذلك من شأن النساء بحكمة الله  حتى يتزين بالذهب، والفضة، والحرير للأزواج، والرجل ليس بحاجة إلى ذلك. وأيضًا فيه علة أخرى وهي أنه من زي الكفرة، فأباحه الله للنساء لحاجتهن، ومنعه الرجال، وجعله لهم في الآخرة، قال ﷺ: لا تلبسوا الحرير، ولا الديباج، ولا تشربوا في آنية الذهب، والفضة؛ فإنها لهم في الدنيا يعني: للكفرة ولكم في الآخرة فجعلها للكفرة في الدنيا، لا يبالون، يتمتعون بها، لا يبالون، وجعلها للمؤمنين في الجنة، الرجال والنساء جميعًا، وأباح للنساء، أباح التحلي بالذهب، والفضة لحاجة النساء إلى الزينة، وحرم على الجميع أواني الذهب والفضة، على الجميع، الرجال والنساء جميعًا، كالصحن وإناء الشرب، وأكواب الشاي، أكواب القهوة كلها حرام من الذهب، والفضة لا تجوز، هذه من الحكم، التي ذكرها بعض أهل العلم.  والواجب علينا تلقي حكم الله بكل صدر منشرح، بالبساطة والمحبة والرضا، وإن لم نعرف الحكمة، لكن إذا عرفناها، فذلك نور على نور، وخير إلى خير، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15641/الحكمة-من-تحريم-الذهب-على-الرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_825/nour_82506.mp3","categories":["اللباس والزينة"]},{"id":16937,"question":"السائلة (ع. أ. ع) من الدمام تقول: متى يجب على الفتاة أن تلتزم بالحجاب الشرعي؟  تقول: أي: في أي سنٍّ تبدأ؟","title":"وجوب الحجاب على المرأة بالبلوغ","answer":"الجواب:  يلزمها إذا بلغت، إذا حاضت، أو أنزلت المني -احتلمت- أو بلغت خمس عشرة سنةً، مثل الرجل، فالرجل يكون رجلًا إذا بلغ الحلم؛ لقوله تعالى: وَإِذَا بَلَغَ الأَطْفَالُ مِنْكُمُ الْحُلُمَ فَلْيَسْتَأْذِنُوا [النور:59] فإذا احتلم أنه يأتي المرأة، وأنزل؛ بلغ، أو أنبت الشعر الخشن حول القُبل؛ صار مُكلَّفًا، والمرأة كذلك، أو كمل خمس عشرة سنةً؛ صار رجلًا، والمرأة كذلك، وتزيد المرأة أمرًا رابعًا وهو الحيض، إذا حاضت تكون مُكلَّفةً.","link":"https://binbaz.org.sa/fatwas/15708/وجوب-الحجاب-على-المراة-بالبلوغ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_586/58610.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":16999,"question":"الأخت من الباحة يا شيخ تقول: ما حكم دهن الرموش بالزيت بقصد التجمل، بمعنى: تطويل رموش العينين بواسطة هذا الزيت بالنسبة للمرأة؟","title":"حكم دهن المرأة رموشها بقصد تطويلها","answer":"الجواب: إذا كان ينفع العين لا بأس، إذا كان دهنها ينفع العين، كالكحل الذي ينفع العين لا بأس به، ولا حرج فيه. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15770/حكم-دهن-المراة-رموشها-بقصد-تطويلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_587/58703.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":17004,"question":"هل يجوز لبس الجوارب الشفافة، والخروج بها للشارع؟ أفيدونا أثابكم الله.","title":"حكم الخروج بالجوارب الشفافة","answer":"الجواب: للرجل لا بأس، لكن لا يمسح عليها حتى تكون ساترة، أما المرأة لا؛ لأنها تبدي عورتها، تبدي الرِّجْل، فلا يجوز، لا بد من جوارب ساترة للمرأة تسترها عن الفتنة، وتمسح عليها إذا لبستها على طهارة، أما الرجل لو لبسها؛ لأنها تنفع بعض الشيء، لكن لا يمسح عليها حتى تكون ساترة، نسأل الله العافية. نعم. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/15796/حكم-الخروج-بالجوارب-الشفافة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_767/nour_76704.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":17005,"question":"ما رأي سماحتكم في صبغ اليدين، والرجلين بالحناء الأسود؟","title":"حكم صبغ المرأة يديها ورجليها بالحناء الأسود","answer":"الجواب: للمرأة لا بأس بذلك، الحناء من الزينة لزوجها، لا حرج في ذلك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15792/حكم-صبغ-المراة-يديها-ورجليها-بالحناء-الاسود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_767/nour_76703.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":17008,"question":"الأخت السائلة يا سماحة الشيخ تقول: بالنسبة للبس الكم القصير إلى المرفق، أو أقل منه أمام النساء فقط ما حكمه؟","title":"حكم لبس المرأة الكم الصغير أمام النساء","answer":"الجواب: لا حرج فيه -إن شاء الله- لكن كونها تحتشم يكون لباسها إلى المرفق، يكون هذا أكمل، وأحسن حتى يتأسى بها؛ لأنها قد يعرض لها من ينظر إليها من خادم، أو سائق، أو غير ذلك، فاحتشامها، وتحرزها، واحتياطها أفضل، وأولى، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15781/حكم-لبس-المراة-الكم-الصغير-امام-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_587/58705.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":17010,"question":"السائلة يا سماحة الشيخ تقول: إذا ذهبت إلى المدرسة، أو إلى الأقارب، أو الجيران فإني أحضر معي العطر، وأتعطر هناك عندهم في البيت، فهل في ذلك شيء؟","title":"حكم تعطر المرأة في منزل أقاربها وجيرانها","answer":"الجواب: إذا كان لا يحصل منه رائحة في الطرق؛ فلا بأس، إذا كان في البيت فقط، أما إذا كان تخشى منه الفتنة في الطرق فلا، لا تخرج بطيب يشمه الناس في الطرقات الرجال في الطرقات، أما إذا كان خفيفًا لا يشم في الطرقات؛ فلا حرج.","link":"https://binbaz.org.sa/fatwas/15786/حكم-تعطر-المراة-في-منزل-اقاربها-وجيرانها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_587/58706.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":17016,"question":"الزائر للحرمين الشريفين خاصة -سماحة الشيخ- يتأذى كثيرًا من أولئك السافرات عن وجوههن، حتى لو فقد محرمًا له كأمه، أو زوجته، أو أخته، وبدأ يبحث عنها لا يستطيع البحث؛ لأن بصره يقع على ما لا يريد، ما هو توجيه سماحتكم لأخواتنا المسلمات إذا ما كن في الحرمين خاصة، وفي جميع المناطق عامة؟ جزاكم الله خيرًا.","title":"نصيحة حول ظاهرة السفور والتبرج في الحرمين","answer":"الجواب: وصيتي لجميع أخواتي في الله في الحرم الشريف، وفي المطار، وفي السعي، وفي المسجد النبوي، في أي مكان، الوصية للجميع تقوى الله، والاستقامة على أمره، والمحافظة على حدوده التي حدها سبحانه، والحرص على الستر، والحجاب، ولا ينبغي أن تغتر بقول بعض الناس: أنه لا حرج عليها في كشف وجهها، ويديها، هذا قول مرجوح يخالف الأدلة الشرعية، إلا إذا كانت محرمة بحج، أو عمرة؛ فإنها لا تلبس النقاب المصنوع للوجه، لكن تحتجب بالخمار، ونحوه مما يوضع على الوجه. وأما النقاب الذي هو مصنوع على قدر الوجه، ونقب العينين هذا تتركه في حال الإحرام، وفي العمرة والحج، لكن تستر وجهها بالخمار بجلباب فوق رأسها كما قالت عائشة -رضي الله عنها-: \"كنا مع النبي ﷺ في حجة الوداع، فإذا دنا منا الرجال سدلت إحدانا جلبابها على وجهها، أو قالت: خمارها على وجهها، فإذا بعدوا كشفنا\" وهن محرمات. فالوصية للجميع تقوى الله، والحرص على التستر، والحجاب لجميع البدن، في الطواف، وفي السعي، وفي كل مكان عن الأجانب، وأن تحذر أسباب الفتنة من التبرج بالملابس الجميلة، أو إظهار بعض المحاسن التي تفتن الناس، والله يقول -جل وعلا-: وَلا تَبَرَّجْنَ تَبَرُّجَ الْجَاهِلِيَّةِ الأُولَى [الأحزاب:33] ويقول: فَلا تَخْضَعْنَ بِالْقَوْلِ فَيَطْمَعَ الَّذِي فِي قَلْبِهِ مَرَضٌ [الأحزاب:32] يكون القول قولًا عاديًا، كلامًا، العادي ما فيه خضوع، ولا تغنج مع التستر والحجاب، كل هذا لإبعادها عن الفتنة، وأن يفتن بها غيرها أيضًا. نعم. المقدم: جزاكم الله خيرًا، إذًا لا يجوز للمرأة المسلمة أن تكشف وجهها، سواءً كانت في المشاعر المقدسة، أو في غيرها. الشيخ: عند الأجنبي. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15814/نصيحة-حول-ظاهرة-السفور-والتبرج-في-الحرمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_767/nour_76709.mp3","categories":["قضايا المرأة","نصائح وتوجيهات","اللباس والزينة"]},{"id":17019,"question":"رسالة وصلت إلى البرنامج من المستمع عبدالرحيم عبدالله من الخرطوم السودان، يسأل جمعًا من الأسئلة في أحدها يقول: ما هو الزي الإسلامي الصحيح بالنسبة للمرأة؟ وهل يجب عليها أن تغطي وجهها وكفيها؟ مع رجاء بيان الأدلة في هذا المقام، والبسط في الموضوع، جزاكم الله خيرًا.","title":"وجوب تغطية المرأة جميع بدنها عند الأجانب","answer":"الجواب: المرأة كلها عورة -كما قاله النبي ﷺ- فالواجب عليها عند الرجال الأجانب أن تستر جميع بدنها، والمراد بالأجانب غير المحارم، ولو كانوا من بني عمها، كل من كان غير محرم يقال له: أجنبي: كابن عمها، وأخي زوجها، وزوج أختها، وغيرهم، تستر جميع بدنها، الوجه، واليد، والقدم، وغير ذلك لقوله ﷺ: المرأة عورة.  والأصل في هذا قوله سبحانه: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنّ [الأحزاب:53] فلم يستثن سبحانه شيئًا قال: من وراء حجاب ثم بيَّن العلة والحكمة فقال: ذلكم أطهر لقلوبكم وقلوبهن يعني: التستر، والحجاب أطهر لقلوب الجميع، وأبعد عن الفتنة، وقال في سورة النور : وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ [النور:31].. إلى آخره، والوجه، واليد من الزينة، والقدم من الزينة، والشعر من الزينة، وإذا كان في الوجه شيء من التحسينات؛ صار أعظم في الزينة: كالكحل، وأشباهه مما ينور الوجه، كان أعظم في الزينة والفتنة، وهكذا في اليد من الحلي.  المقصود: أنها عورة كلها، ولو لم يكن في يدها شيء، ولا في وجهها شيء، فهي عورة، فالواجب على المرأة أن تحتجب عن الأجنبي، وأن تكلمه من وراء حجاب يكون عليها جلبابها، أو يكون عليها خمارها، تكلمه وتقول له: وعليكم السلام، السلام عليكم، كيف حالك؟  تسأل عن حاجتها مثلما كن في عهد النبي ﷺ يفعلن، كان الحجاب أولًا مرفوعًا، كانت المرأة تكلم وهي مكشوفة، كاشفة الوجه. ثم أنزل الله آية الحجاب، فأمرن بالستر، بعدما نزلت آية الحجاب في سورة الأحزاب: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]، وهكذا آية النور: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ أَوْ أَبْنَائِهِنَّ أَوْ أَبْنَاءِ بُعُولَتِهِنَّ [النور:31] الآية، والبعولة هم الأزواج، حتى قال في آخرها: وَلا يَضْرِبْنَ بِأَرْجُلِهِنَّ لِيُعْلَمَ مَا يُخْفِينَ مِنْ زِينَتِهِنَّ [النور:31] نهيت أن تضرب برجلها حتى يسمع صوت الخلخال الذي في رجلها؛ لأنه قد يفتن الناس، فإذا كانت تنهى عن الضرب بالرجل حتى لا يسمع الخلخال، فكيف بمن تكشف الوجه، أو الرأس، أو الذراع، أو الساق، أو ما أشبه ذلك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15811/وجوب-تغطية-المراة-جميع-بدنها-عند-الاجانب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_767/nour_76708.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":17036,"question":"يسأل ويقول: ما حكم صلاة المسبل إزاره؟ مع الدليل؟ جزاكم الله خيرًا.","title":"حكم صلاة المسبل إزاره","answer":"الجواب: الإسبال محرم، لا يجوز الإسبال، وهو كون الملابس تنزل عن الكعب، سواء كان اللباس سراويل، أو إزارًا، أو قميصًا، أو بشتًا، وهو العباءة، أو غير ذلك، هذا في حق الرجل، لقول النبي ﷺ في الحديث الصحيح: ما أسفل من الكعبين من الإزار فهو في النار أخرجه البخاري في صحيحه، ولقول النبي ﷺ: ثلاثة لا يكلمهم الله، ولا ينظر إليهم يوم القيامة، ولا يزكيهم، ولهم عذاب أليم: المسبل إزاره، والمنان فيما أعطى، والمنفق سلعته بالحلف الكاذب خرجه مسلم في الصحيح، وإذا كان مع الكبر؛ صار الإثم أكبر لقوله ﷺ: من جر ثوبه خيلاء لم ينظر الله إليه يوم القيامة. فمع الكبر يكون الإثم أكبر، ومن دون كبر، بل تساهل يكون آثمًا، ولا يجوز على الصحيح، ولكن لا يكون مثل من جره خيلاء، يكون إثمه أقل، والغالب أنه يجره خيلاء حتى ولو ما نوى الخيلاء، فالغالب أنه يجره لذلك، إذا تساهل به جره ذلك إلى التكبر والتعاظم، ثم هو أيضًا إسراف في الملابس، وتعريض لها للنجاسات، والأوساخ، كذلك لا يجوز مطلقًا. أما المرأة فلا حرج أن ترخي ثوبها شبرًا، أو ذراعًا؛ لأنها بهذا تستر قدميها. والصلاة صحيحة مع الإثم، هو آثم، لكن الصلاة صحيحة؛ لأن الرسول ﷺ ما أمر المسبل أن يعيد، بل الصلاة صحيحة، وهكذا كلما يتعلق بالمعاصي التي يفعلها الإنسان في ثوب، أو غيره، أن يكون هناك ثوبًا من حرام، أو مغصوبًا، أو فيه إسبال؛ فالصلاة صحيحة، لكن مع الإثم، أو الصلاة في أرض مغصوبة، هذا الصواب من أقوال العلماء، بعض أهل العلم يرى أن الصلاة غير صحيحة. المقدم: في الأرض المغصوبة خاصة، أو في كل هذا؟ الشيخ: في الكل: الثوب المغصوب، والمسبل، ولكن الصواب أنه لا تعاد الصلاة، الصلاة صحيحة، الصواب أنها صحيحة؛ لأن هذا النهي ليس خاصًا بالصلاة، بل هو عام ليس له أن يسبل لا في الصلاة، ولا في خارجها، وليس له أن يغصب لا في الصلاة، ولا في غيرها، وليس له أن يدخل الأرض المغصوبة، ولا يصلي فيها، ولا يجلس فيها، فالنهي عام، ما هو بخاص بالصلاة، والصلاة تبطل بالشيء الذي يخصها، مثل الثوب النجس يبطل الصلاة؛ لأنه خاص بالصلاة، مثل كشف العورة، وما أشبه ذلك، الشيء الخاص بالصلاة يبطلها إذا كشف عورته تعمدًا، أو صلى في ثوب نجس؛ لأن هذا يخص الصلاة يبطلها، مثل تكلم فيها، مثل انحرف عن القبلة، وما أشبهه. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ، هذا الحديث الذي تفضلتم بذكره يتضمن ما يتضمن من الوعيد الشديد، وهذا الوعيد قد لا يذكر في معاصٍ أكبر مما ذكر هنا، ما هو توجيه سماحتكم للمستمعين الكرام تجاه هذا الوعيد الشديد في هذا الحديث، وما ماثله في الأحاديث، أو الآيات؟ جزاكم الله خيرًا. الشيخ: لا شك أن هذا الوعيد يوجب النفرة من هذه المسائل، والحذر منها، ولعل الحكمة في ذلك -والله أعلم- أن الدوافع قوية، الدوافع للإسبال، والمن في العطية، والأيمان الكاذبة لأجل ... السلع، الدوافع قوية، فكان من حكمة الله أن جعل الوعيد الشديد حتى يردع عن هذه المعاصي، ويكون ذلك أقوى في الردع؛ لأن كثيرًا من الناس قد يحمله حب المال على الأيمان الكاذبة، وتنفيق السلعة بأيمان كاذبة، فمن رحمة الله أن جعل زجره الشديد عن ذلك؛ حتى لا يضر العالم بأيمانه الكاذبة. وكذلك الإنسان قد يكون عنده تساهل في المن بالعطية، يعطي ويمن على الناس، وهذا من قلة المروءة، ومن صغار النفس، فمن رحمة الله أن جعل الوعيد؛ حتى يحذر المؤمن من هذا الخلق الذميم، وهو كونه يمنُّ على من أعطى: فعلت بك، وأعطيتك، وأحسنت إليك، يمنُّ عليه، وكذلك الدوافع للإسبال كثيرة: للتكبر، والتساهل، ولهذا جاء الوعيد الشديد للتحذير من هذا الخلق الذميم، وهو الإسبال. نعم. المقدم: جزاكم الله خيرًا إذًا هذا الوعيد على ظاهره أو له وجهة أخرى؟ الشيخ: على ظاهره، لكن لا يلزم من ذلك الكفر، بل الوعيد، قد يعفو الله، ولا ينفذ الوعيد، نعم، مثلما توعد كثيرًا من العصاة: توعد القاتل بالنار، توعد الزاني، توعد السارق، ولكن قد يعفو سبحانه، نعم، وهذا ما لم يتب، ومن تاب تاب الله عليه. المقدم: الحمد لله، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15831/حكم-صلاة-المسبل-ازاره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_767/nour_76711.mp3","categories":["اللباس والزينة","مسائل متفرقة في الصلاة"]},{"id":17039,"question":"أبو عبدالكريم يقول في هذا  إذا شرب المحرم شيئًا من الزعفران قبل تحلله هل في ذلك شيء؟","title":"حكم شرب المحرم للزعفران","answer":"الجواب: إذا كان ناسيًا، أو جاهلًا لا شيء عليه، أما التعمد لا يجوز؛ لأن الزعفران طِيب فلا يتعمده، لكن إذا كان جاهلًا، أو ناسيًا فلا شيء عليه رَبَّنَا لا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا [البقرة:286]. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15827/حكم-شرب-المحرم-للزعفران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_587/58716.mp3","categories":["اللباس والزينة","محظورات الإحرام","قضايا المرأة"]},{"id":17040,"question":"ما حكم الشرع في ثقب إذن البنت يا شيخ؟","title":"ما حكم ثقب أذن البنت الصغيرة؟","answer":"الجواب: لا بأس، كان النساء في عهد النبي ﷺ تثقب آذانهن، ويجعل فيها الأقراط، لا بأس بهذا. نعم.","link":"https://binbaz.org.sa/fatwas/15828/ما-حكم-ثقب-اذن-البنت-الصغيرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_587/58717.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":17046,"question":"بعد هذا ننتقل إلى رسالة من المنطقة الشمالية في المملكة باعثتها إحدى الأخوات المستمعات، تقول المرسلة: (م. خ) العتيبي، أختنا تسأل سماحتكم وتقول: ما حكم أخذ شيء من شعر الذراعين والساقين، وذلك إذا كان مؤثرًا على صفة المرأة؟ وجهوها جزاكم الله خيرًا.","title":"حكم أخذ المرأة من شعر الذراعين والساقين","answer":"الجواب: لا نعلم بأسًا في ذلك، لا نعلم حرجًا في أخذ شعر الساقين واليدين، لا حرج في ذلك، ولا نعلم في الشرع ما يمنع ذلك، وهو من الزينة، والتجمل للزوج، ولا حرج في ذلك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15835/حكم-اخذ-المراة-من-شعر-الذراعين-والساقين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_721/nour_72103.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":17066,"question":"يقول السائل: بعض النساء عندما يجمعن شعر رؤوسهن إلى الخلف، هل هذا هو المنهي في حديث الرسول ﷺ؟","title":"حكم جمع المرأة رأسها إلى الخلف","answer":"الجواب: جاء في حديث الرسول ﷺ: رؤوسهن كأسنمة البخت المائلة يجمعون عليها أشياء حتى تعظم وتكبر، أما هذا يجمعون الشعر ما هو من جنس ما قاله الرسول ﷺ، لكن هذا عليهن أن يمسحنه كله... مسح الصلاة عليهن أن ينقضنه ويمسحنه، يوخرنه إن كان عليه خرقة وإلا شيء، يزلنها ويمسحن الرأس كله. أما الذي جاء في الحديث: رؤوسهن كأسنمة البخت المائلة هذا يجمعن عليها أشياء من لفائف حتى تكون كأسنمة البخت المائلة، وأسنمة البخت كأنها سنامان بينهما شيء. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15870/حكم-جمع-المراة-راسها-الى-الخلف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_588/58806.mp3","categories":["شروح الحديث","قضايا المرأة","اللباس والزينة"]},{"id":17085,"question":"نعود مع مطلع هذه الحلقة إلى رسالة وصلت إلى البرنامج من الجمهورية العربية السورية باعثتها إحدى الأخوات من حلب، تقول: أختكم في الإسلام -أختنا عرضنا لها قضية في حلقة مضت- وفي هذه الحلقة تسأل وتقول: هل للمرأة أن تخرج بثياب عادية تستر جسمها دون جلباب أسود طويل؟ وجهونا جزاكم الله خيرًا.","title":"ما حكم خروج المرأة بثياب ساترة دون لبس الجلباب؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فلا حرج على المرأة أن تخرج في ملابس ساترة، ليس فيها فتنة، وإن كان ليس فوقها جلباب، وإن كانت ليس فوقها جلباب، لكن وجود الجلباب والعباءة أكمل؛ لأن الملابس الأخرى قد تبين بعض حجم الأعضاء، فإذا كانت ملابس وافرة كافية ساترة للرأس والوجه والبدن، فلا بأس، لكن وجود الجلباب يكون أكمل، قال تعالى: يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلابِيبِهِنَّ [الأحزاب:59] في خروجها بالجلباب يكون أكمل، وأبعد عن الفتنة، وأستر للمرأة، وهكذا العباءة. فالمقصود: أن وجود العباءة، والجلباب يكون أستر لها، وأبعد، لكن لو وُجِدَ ثيابٌ ضافية ساترة، وطرحتها على الرأس، ساترة مع ستر جميع البدن؛ حصل المقصود، إذ المقصود التستر، والبعد عن أسباب الفتنة مهما أمكن، فالجلباب والعباءة، ونحوهما فوق الثياب يكون أكمل في الستر. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15896/ما-حكم-خروج-المراة-بثياب-ساترة-دون-لبس-الجلباب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_722/nour_72201.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":17108,"question":"تشترك أختنا من حلب في سؤال مع مستمعة من الأردن هي (ع. م) يشتركن في هذا السؤال عن إزالة الشعر من وجه المرأة، ولا سيما الحاجبين، وأيضًا عن الشعر، وإزالته من بقية جسم المرأة، كالذراعين، والساقين، وما أشبه ذلك، ما هو توجيهكم للنساء في هذا الموضوع؟ سماحة الشيخ، جزاكم الله خيرًا.","title":"حكم إزالة المرأة لشعر الوجه والذراعين والساقين","answer":"الجواب: ليس للمرأة أن تأخذ الحاجبين، ولا من شعر الوجه ما ليس فيه تشويه، بل هو عادي؛ لأن هذا من النمص، أما لو نبت في الوجه شيء يشوه الخلقة كالشارب، واللحية، فلا بأس أن تأخذه، أما الحاجبان، والشعر العادي في الوجه فإنها لا تأخذ شيئًا منه؛ لأن \"الرسول ﷺ لعن النامصة والمتنمصة\" أما شعر الذراعين، والرجلين فلا بأس به. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15905/حكم-ازالة-المراة-لشعر-الوجه-والذراعين-والساقين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_722/nour_72202.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":17109,"question":"تقول عن نفسها سماحة الشيخ: أنا طالبة، ويجب علي في كل ستة أشهر أن أسافر إلى أهلي، ولكني أذهب إليهم من غير محرم، وأنا -عفا الله عني وعنكم- أعرف حكم ذلك، لكن أهلي يجبرونني، ويصرون على سفري، فماذا أفعل -يرحمكم الله- وجهوني -جزاكم الله خيرًا- وما الحكم إذا كنت مع مجموعة من البنات؟ وجهوني، جزاكم الله خيرًا.","title":"حكم سفر المرأة من غير محرم","answer":"الجواب: ليس للمرأة أن تسافر إلا مع محرم، ولا طاعة لمخلوق في معصية الخالق، من أمرك بالسفر بدون محرم فلا طاعة له، من أب، أو أم، أو أخ، أو غير ذلك، يقول النبي ﷺ: إنما الطاعة في المعروف لا طاعة لمخلوق في معصية الخالق سبحانه، ويقول ﷺ: لا تسافر امرأة إلا مع ذي محرم متفق على صحته. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15908/حكم-سفر-المراة-من-غير-محرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_722/nour_72204.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":17120,"question":"المستمعة (س. ع. م) من الأردن تسأل أيضًا سماحتكم عن حكم لبس الخاتم، والقلادة، وغير ذلك من الذهب بالنسبة للمرأة إذ تقول: لقد قرأت عن الرسول ﷺ أنه لم يقر ذلك حتى للمرأة، وأوصاها بلبس الفضة، ما هو توجيهكم؟","title":"حكم لبس المرأة المحلق من الذهب","answer":"الجواب: الصواب: أنه لا حرج في ذلك، لا بأس أن تلبس ما يتيسر من الذهب، والفضة، والجواهر، وأن تكون مستورة عن الأجانب، لكن عند زوجها، وعند النساء لا بأس، وقد ثبت هذا في أحاديث صحيحة، أما الأحاديث التي فيها ذكر النهي عن لبس المحلق، أو بعض الفضة هذه أحاديث ما بين ضعيف، وبين منسوخ، ليس عليها عمل، وقد أجمع العلماء على جواز الذهب، والفضة للنساء، ولا حرج في ذلك، وقد دلت عليه الأحاديث الصحيحة عن النبي ﷺ. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15933/حكم-لبس-المراة-المحلق-من-الذهب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_722/nour_72203.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":17165,"question":"هل كحل العينين سنة؟ أم ماذا؟","title":"ما حكم الاكتحال؟","answer":"الجواب: نعم، كان النبي ﷺ يكتحل، الكحل سنة. نعم، والأحسن أن يكون بالإثمد. نعم. المقدم: جزاكم الله خيرًا، سماحة الشيخ بعض الأطباء في هذه الأيام يقولون: إن هذا الكحل -وإن كان من الإثمد- يضر بالعينين، وكأنهم يتجاهلون ما جاء عن الرسول ﷺ في أمر الكحل، ما هو توجيهكم لإخواننا المتخصصين في طب العيون، وفيما يخص الكحل، بارك الله فيكم؟ الشيخ: هذا الذي قال هذا القول غلط، ولو كان طبيبًا، الكحل لا يضر إذا كان بالإثمد السليم النظيف يقول النبي ﷺ: عليكم بالإثمد؛ فإنه يجلو البصر، وينبت الشعر فهو طيب، يزيد البصر شدة وقوة، وينبت الشعر أيضًا، فالذي يقول: إنه يضر البصر قوله ضعيف ومردود، الصواب أنه ينبت الشعر ويجلو البصر، ينفع، الإثمد المعروف. أما إذا كان أنواع أخرى قد تضر يعرفها الأطباء هذا شيء آخر، أما الإثمد المعروف فهو ينبت الشعر، ويجلو البصر كما قاله النبي ﷺ. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15984/ما-حكم-الاكتحال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_767/nour_76714.mp3","categories":["اللباس والزينة"]},{"id":17166,"question":"يسأل: هل يجوز إزالة شعر الذراعين والساقين، علمًا بأن الإزالة تتم بواسطة طبخ الليمون والسكر؟","title":"حكم إزالة شعر الذراعين والساقين","answer":"الجواب: لا حرج في ذلك، لا نعلم فيه بأسًا، حلق شعر اليدين، والساقين لا حرج في ذلك بالسكر، ولا بغيره، لا حرج. نعم. المقدم: الحمد لله، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15985/حكم-ازالة-شعر-الذراعين-والساقين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_767/nour_76715.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":17190,"question":"تقول السائلة: يوجد اعوجاج في أسناني الأمامية، وطويلة أيضًا بعض الشيء، فما الحكم إذا قمت بإصلاحها؟ وهل أدخل من ضمن المغيرات لخلق الله؟","title":"ما حكم تعديل الأسنان للتجمل؟","answer":"الجواب: لا حرج في ذلك، الذي يعالجها للحسن هذا يسمى تفلج ... للحسن، أما إذا حصل فيها اعوجاج، أو سواد، أو طول فلا بأس بعلاجها. نعم.","link":"https://binbaz.org.sa/fatwas/16009/ما-حكم-تعديل-الاسنان-للتجمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_590/59018.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":17198,"question":"ما حكم وضع الكحل على الحاجبين بالنسبة للزينة للمرأة؟","title":"حكم وضع المرأة الكحل على الحاجبين للزينة","answer":"الجواب: لا أعلم فيه بأسًا، جعل الكحل في الحاجبين، أو في جفني العين كله لا بأس به، الممنوع النمص، وقص الحاجبين، هذا هو الذي ما يجوز، هذا النمص، هذا لا يجوز، أما كون تضع فيها كحلًا لا بأس. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16018/حكم-وضع-المراة-الكحل-على-الحاجبين-للزينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_590/59026.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":17200,"question":"تقول السائلة: ما حكم الإسبال في الصلاة؟ حيث إنه يوجد كثير من الناس يسبلون، ويقولون: بأن الرسول ﷺ قد سبل في الصلاة، فما صحة هذا القول؟","title":"ما حكم الإسبال في الصلاة؟","answer":"الجواب: الإسبال إذا كان يعنى به إرخاء اليدين فهذا خلاف السنة، السنة أن يضع اليدين على صدره، هذا السنة، هذا المحفوظ عن النبي ﷺ يضع اليمنى على اليسرى على صدره، ولا يرخيها، يرسلها، يسمى إرسالًا ما يسمى إسبالًا، يسمى إرسالًا. أما الإسبال: فهو إرخاء الثياب تحت الكعبين، الملابس، والإزار، والبشت، هذا يسمى إسبالًا، ما يجوز إرخاء الملابس تحت الكعبين للرجل، أما المرأة؛ لا بأس، أما إسبال الثياب للرجل تحت الكعب؛ إزار، أو سراويل، أو قميص، أو بشت كل هذا لا يجوز. أما إرسال اليدين وهو يصلي هذا ما يسمى إسبالًا يسمى: إرسالًا، إرسال اليدين، والأفضل أن يضمهما، يضمهما على صدره وقت الصلاة، قبل الركوع وبعده، هذا هو السنة. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16022/ما-حكم-الاسبال-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_590/59028.mp3","categories":["اللباس والزينة","مسائل متفرقة في الصلاة"]},{"id":17205,"question":"أخيرًا من أسئلة هذه السائلة من الأردن، تقول سماحة الشيخ: وضع الخواتم في السبابة والإبهام، وكذلك سائر الأصابع بالنسبة للمرأة؟","title":"حكم وضع الخواتم في جميع أصابع اليدين","answer":"الجواب: لا حرج في ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/16027/حكم-وضع-الخواتم-في-جميع-اصابع-اليدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_590/59033.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":17207,"question":"من الدوحة قطر الأخت المستمعة (أ. غ. ع) رسالتها ضمنتها أربعة أسئلة، في أحد أسئلتها تقول: ما حكم ذهاب النساء إلى محل تصفيف الشعر، أو الكوافيرة -كما يسمونه- علمًا بأن هذه المحلات لا يدخلها غير النساء؟ جزاكم الله خيرًا.","title":"نصيحة لمن يردن الذهاب إلى محلات الكوافير","answer":"الجواب: نصيحتي أن لا يذهبن إلى ذلك، وأن تعطل هذه المحلات؛ لأنه يخشى فيها الشر والفتنة، ودعوى ....... عمل أشياء لا حاجة إليها، فالمرأة -والحمد لله- تستطيع تعلم نفسها في بيتها مع أمها، أو أخواتها، أو صديقاتها كل ما يحتاج إليه، ولا ينبغي التكلف .... الشعر معروف، وكذلك فتل العمائم معروف، ولا حاجة إلى هذه المحلات التي أحدثها الناس، فربما يكون فيها فتنة، أو شر، نعم، فينبغي تركها. المقدم: وهذا مؤكد سماحة الشيخ، جزاكم الله خيرًا.  الشيخ: هذا الذي بلغنا، بلغنا أنها لا خير فيها، وينبغي تركها. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16033/نصيحة-لمن-يردن-الذهاب-الى-محلات-الكوافير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_723/nour_72303.mp3","categories":["اللباس والزينة","المساجد ومواضع السجود","قضايا المرأة","نصائح وتوجيهات"]},{"id":17208,"question":"ما حكم صبغ الشعر بالحناء، أو بغيره بحجة التزين للزوج؟","title":"ما حكم صبغ المرأة شعرها للتزين للزوج؟","answer":"الجواب: لا حرج في ذلك صبغه بالحناء، ونحوه لا بأس، المنهي عنه صبغ الشيب بالسواد، هذا لا يجوز، لقوله -عليه الصلاة والسلام-: غيروا هذا الشيب، واجتنبوا السواد فإذا غيرت المرأة، أو الرجل الشيب بالحناء، أو بغيره من الألوان الأخرى فلا بأس، إلا السواد الخالص فلا. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16034/ما-حكم-صبغ-المراة-شعرها-للتزين-للزوج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_723/nour_72304.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":17209,"question":"ما حكم إزالة شعر الوجه، والشعر الزائد الموجود على أطراف الحاجبين؟","title":"حكم إزالة المرأة شعر الوجه وزوائد الحاجبين","answer":"الجواب: إذا كان في الوجه شعر زائد يشوه الخلقة كاللحية للمرأة والشارب للمرأة يزال، أما الشعر العادي فلا يزال، الذي يسمى نمصًا، وهكذا الحاجبان لا يتعرض لهما؛ لأن هذا هو النمص الذي لعن النبي من فعله ﷺ: لعن النامصات والمتنمصات، وهو أخذ شعر الحاجبين أو شعر الوجه الذي ليس فيه تشويه، بل شعر عادي.","link":"https://binbaz.org.sa/fatwas/16035/حكم-ازالة-المراة-شعر-الوجه-وزواىد-الحاجبين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_723/nour_72305.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":17236,"question":"سماحة الشيخ! هذه السائلة أم أمل، تقول في هذا  ما حكم تسريح الشعر إلى الخلف، وضفره ضفيرة واحدة؟","title":"حكم تسريح الشعر إلى الخلف","answer":"الجواب: لا أعلم في هذا علة، أقول: لا أعلم في هذا بأسًا، لكن الأفضل أن يكون ثلاثًا، ثنتان أمام، وواحدة خلف، كما أمر النبي ﷺ أم عطية لما غسلن ابنته أن يجعلن قرونها ثلاثًا، قرنين، وذؤابة وراءها، الأفضل يكون ثلاثًا، قرنين، والناصية من خلفها، هذا هو الأفضل، وإلا لو جعل كله وراء، ما أعلم فيه شيئًا، لكن الأفضل هو هذا، الأفضل أن تكون القرون ثلاثة، قرن عن اليمين، وقرن عن الشمال، وقرن خلف. المقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16065/حكم-تسريح-الشعر-الى-الخلف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_591/59113.mp3","categories":["اللباس والزينة"]},{"id":17249,"question":"هذه السائلة أم عاصم من أسئلتها تقول يا سماحة الشيخ: «لعن رسول الله ﷺ النامصات، والمتنمصات» هل النمص هو نتف الشعر من الحاجبين فقط؟ أم من بقية الوجه فقط؟","title":"حكم نتف الشعر من الوجه للمرأة","answer":"الجواب: النامصات من الحاجبين، وهكذا الوجه عند بعض أهل العلم إذا كان فيه شيء تنمصه، هذا من النمص، إلا إذا كان شيء يسبب المثلة والتشويه، مثل شارب لها أو لحية، لا بأس أن تأخذه؛ لأنه يشوه عليها ويضرها، أما أخذ الحاجبين، أو الشعر العادي الذي ما يضر لا تأخذ شيئًا. نعم. المقدم: أحسن الله إليك.","link":"https://binbaz.org.sa/fatwas/16081/حكم-نتف-الشعر-من-الوجه-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_592/59203.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":17290,"question":"من أسئلة إحداهن تقول يا سماحة الشيخ: ما حكم تسريح الشعر إلى الخلف، وظفره ظفيرة واحدة، هل تكن آثمة من تفعل ذلك؟","title":"حكم تسريح الشعر إلى الخلف وجعله ظفيرة واحدة","answer":"الجواب: لا حرج فيه، سواء جعلته ظفيرة، أو ظفائر، لا حرج في ذلك، والحمد لله. نعم. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/16134/حكم-تسريح-الشعر-الى-الخلف-وجعله-ظفيرة-واحدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_593/59308.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":17316,"question":"ما حكم الإسبال في الكم؟ هل هو حرام، أم مكروه؟ وإذا كان مكروهًا وأسبل هل يكون آثمًا؟","title":"ما حكم الإسبال في الكم؟","answer":"الجواب: لا أعلم في ذلك حرجًا إلا أن الأفضل أن يكون إلى الرسغ.. الأفضل أن يكون إلى الرسغ، كما روي عن النبي ﷺ \"أنه كان قميصه إلى الرسغ\" ولو زاد على ذلك لا يضر، لا أعلم به بأسًا، ولا نهيًا عن النبي -عليه الصلاة والسلام- نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16182/ما-حكم-الاسبال-في-الكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_833/nour_83313.mp3","categories":["اللباس والزينة"]},{"id":17339,"question":"بعد هذا ننتقل إلى جمهورية مصر العربية عبر رسالة بعث بها المستمع: محمد مرعي علي من المنيا، أخونا له جمع من القضايا يسأل فيها ويقول:ما رأي سماحتكم في الزوجة التي ترفض النقاب رغم التزامها، وطاعتها لزوجها في سائر الأمور، فهل يعد رفضها للنقاب شذوذًا يوجب طلاقها بعد النصح، والهجر، والضرب؟ أم أن زوجها يصبر عليها كما أشرت سماحتكم في كتابكم الفتاوى، والنصائح؟","title":"كيفية التعامل مع الزوجة التي ترفض لبس النقاب","answer":"الجواب: نعم، الواجب الاستمرار في النصيحة، والتوجيه، وذكر الأدلة لها، ولا يجب الطلاق؛ لأنها قد يكون عندها شبهة من فتاوى بعض العلماء في جواز ترك النقاب، قد يكون عندها اقتناع برأيها، ورأي من أفتاها. فالحاصل: أن مثل هذا لا يوجب الطلاق، لكن النصيحة والاستمرار، وأن تدع رأيها، وأن تعمل بقول زوجها، وتطيعه في طاعة الله، وهذا شيء ينفعها، ويبعدها عن التهمة، وعن الشر، والخطر، فالنقاب فيه مصالح كثيرة، فتوصي بذلك، وأنت تجتهد معها بالكلام الطيب، ولا حاجة إلى الضرب، ولكن توصيها بتقوى الله، توصيها بالحجاب، وألا تغتر بفتاوى بعض المفتين، وهذا -إن شاء الله يكفي- نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16178/كيفية-التعامل-مع-الزوجة-التي-ترفض-لبس-النقاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_724/nour_72411.mp3","categories":["اللباس والزينة"]},{"id":17430,"question":"ما حكم الحناء للرجال، سواء كان أسود، أو على لونه الطبيعي الأحمر؟","title":"حكم الحناء للرجال","answer":"الجواب: الحناء من زينة النساء، تتزين به النساء في أيديهن وأقدامهن، وليس من خلق الرجال، فلا يجوز له أن يتعاطى الحناء الذي يتشبه فيه بالنساء، أما إذا تعاطاه من أجل الدواء، كأن يكون في يده، أو رجله شيء؛ يداويه بالحناء، ولم يتيسر له دواء آخر حتى لا يتشبه بالنساء.  فنرجو أن لا حرج عليه إذا كان من باب الدواء على وجه لا يكون فيه تشبه بالنساء، وإذا تيسر دواء آخر يقوم مقامه، ويغني عنه؛ فهو أولى من التداوي به، وقد بلغني أن كثيرًا من الناس يتداوون به في الجنوب وغيره، فإذا كان من باب الدواء على وجه ليس فيه تشبه بالنساء في صفة تعاطيهن للحناء؛ فنرجو أن لا حرج في ذلك، إن شاء الله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16302/حكم-الحناء-للرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_836/nour_83605.mp3","categories":["اللباس والزينة"]},{"id":17438,"question":"رسالة من مجموعة من الفتيات من ليبيا، يقلن: إن والدهن منعهن من الدراسة، وهن الآن لا يعرفن قراءة حتى قصار السور، فما الحكم، وبماذا توجهونهن جزاكم الله خيرًا؟","title":"حكم منع الوالد بناته من الالتحاق بالمدارس","answer":"الجواب: إذا كانت الدراسة ممكنة في مدرسة نسائية ليس فيها اختلاط، والطريق إليها ميسر بدون فتنة؛ فليس لوالدكن المنع، أما إذا كانت الدراسة في مدرسة مختلطة، أو في الطريق إليها ما يمنع من ذهابكن إليها؛ لوجود من يغازلكن، ويفتنكن؛ فله الحق في منعكن، وفي إمكانكن أن تتعلمن من طريق إذاعة القرآن السعودية، ففيها تعليم القرآن، وفيها علوم كثيرة، وفيها برنامج نور على الدرب، فيها علم كثير. فعليكن بالتماس وقتها، والاستماع لها، ففيها خير عظيم، وعلم كبير، وإذا تيسر معلمة تأتيكن في البيت، أو والدكن يعلمكن في البيت، فهذا طيب، وخير كبير، فالتمسن معلمة طيبة تعلمكن في البيت، أو يقوم بذلك أحد محارمكن من إخوة، من أخ، أو عم، أو خال، أو أب، أو جد يحصل به المطلوب -إن شاء الله- نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16303/حكم-منع-الوالد-بناته-من-الالتحاق-بالمدارس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_836/nour_83606.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":17464,"question":"هل لبس المرأة للسواد جائز من أجل الحداد؟","title":"حكم لبس المرأة للسواد في أيام الحداد","answer":"الجواب: المرأة تلبس لباسًا لا جمال فيه، ولا يتعين أسود، أسود، أو أحمر، أو أصفر، أو أخضر، لكن ما يكون فيه زينة، لباس عادي، هذا هو السنة في حقها: أن تلبس لباسًا عاديًا ليس فيه زينة، نعم.","link":"https://binbaz.org.sa/fatwas/16332/حكم-لبس-المراة-للسواد-في-ايام-الحداد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_773/nour_77303.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":17478,"question":"هذه سائلة للبرنامج تستفسر عن صحة الحديث سماحة الشيخ، تقول: لا تسافر المرأة إلا مع ذي محرم مسيرة يوم وليلة\" هل يمكن للمرأة أن تسافر لوحدها، طالما أنه لم يبدأ عليها الليل لشرط الحديث، أم أن سفرها ممنوع لوحدها مطلقًا؟ وما الحكم إذا كنا نسافر لأحد أقاربنا في محافظة أخرى، حيث لا يستغرق السفر إلا ساعات، ولا نبيت في الطريق، نرجو التوجيه سماحة الشيخ؟","title":"هل يجوز سفر المرأة دون محرم إذا كان السفر لبضع ساعات؟","answer":"الجواب: ليس للمرأة أن تسافر إلا مع ذي محرم مطلقًا؛ لقوله ﷺ: لا تسافر امرأة إلا مع ذي محرم متفق عليه من حديث ابن عباس -رضي الله عنهما- ولم يحدد يومًا، ولا ليلة، أما الأحاديث التي فيها التحديد بيوم وليلة، أو بيومين، أو بثلاثة أيام هذه حملها العلماء على أنها على حسب الأسئلة، يسأل عن ثلاثة أيام، فيجيب -عليه الصلاة والسلام- وعن يومين فيجيب، وعن يوم وليلة فيجيب، والجامع في هذا هو السفر، فكل سفر ليس للمرأة أن تسافره إلا بمحرم، وهو مسيرة ثمانين كيلو تقريبًا، يوم وليلة للمطية سابقًا، فإذا كان السفر يبلغ ثمانين كيلو تقريبًا، فهو سفر، ليس لها أن تسافر إلا مع ذي محرم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16379/هل-يجوز-سفر-المراة-دون-محرم-اذا-كان-السفر-لبضع-ساعات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_773/nour_77310.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":17482,"question":"هذا سائل للبرنامج يقول: سماحة الشيخ! العطور التي يوجد بها كحولات ما حكم استعمالها بالنسبة للرجال والصلاة فيها، وما حكم استعمال المرأة لهذه العطورات تزينًا لزوجها، مع العلم بأنها حريصة على عدم الخروج بها، الزوج يرغب في استعمالها، وهذه المرأة لا تصلي في الملابس التي تصيبها هذه العطور، وتقوم بغسل ما أصاب الجسم منها قبل الصلاة، هل تجوز الصلاة في ملابس بها هذه العطور؟","title":"حكم صلاة المرأة بالملابس المعطرة","answer":"الجواب: إذا كانت العطور فيها مادة مسكرة لا يجوز استعمالها، إذا كان العطر فيه مادة مسكرة ليس للمرأة، ولا الرجل استعماله، بل يحرم استعمال ذلك، وأما إذا كان العطر سليمًا من المسكر؛ فلا بأس، لكن لا تخرج به المرأة في الأسواق، بل في بيتها عند زوجها، وإذا خرجت تبتعد عن الطيب. أما إذا كانت فيها مسكر، إذا كانت المادة مسكرة، فيها مسكر؛ فإنه لا يجوز استعمالها، ولا يحل للمؤمن استعمال ما فيه مسكر؛ لأن الله -جل وعلا- قال في كتابه العظيم: إِنَّمَا الْخَمْرُ وَالْمَيْسِرُ وَالأَنصَابُ وَالأَزْلامُ رِجْسٌ مِنْ عَمَلِ الشَّيْطَانِ فَاجْتَنِبُوهُ لَعَلَّكُمْ تُفْلِحُونَ[المائدة:90] فالواجب على كل مسلم، وكل مسلمة الابتعاد عن كل ما يسكر، نعم. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16382/حكم-صلاة-المراة-بالملابس-المعطرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_773/nour_77312.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":17518,"question":"من المستمع (ع. ح. ع) رسالة ضمنها جمعًا من الأسئلة يقول: عندنا يلبس العريس في يوم العقد الذهب والحرير والحناء للرجل، هل هذا حرام؟","title":"حكم الذهب والحرير والحناء للرجل يوم زواجه","answer":"الجواب: لا يجوز هذا، لا يتحنى ولا يلبس الذهب والحرير هذا لا يجوز، هذا من فعل النساء، الذهب للنساء والحرير للنساء والحناء للنساء، لا يتشبه بالنساء. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16460/حكم-الذهب-والحرير-والحناء-للرجل-يوم-زواجه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_837/nour_83714.mp3","categories":["اللباس والزينة"]},{"id":17585,"question":"هل أخذ ما بين الحاجبين بالنسبة للمرأة والرجل جائز أو لا؟","title":"حكم أخذ شعر ما بين الحاجبين للرجل والمرأة","answer":"الجواب:  ما أعلم فيه شيئًا؛ لأنه ليس من الحاجب، ما بين الحاجبين ليس من الحاجب، فالأقرب والله أعلم أنه لا حرج فيه؛ لأنه ليس من الحاجبين. نعم، وهو فاصل بينهما. نعم.","link":"https://binbaz.org.sa/fatwas/16521/حكم-اخذ-شعر-ما-بين-الحاجبين-للرجل-والمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_841/nour_84108.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":17619,"question":"تقول: كثير من النساء يسمين تغطية الرأس وكشف الوجه حجابًا فأرجو من سماحتكم توضيح هذا اللبس وبيان معنى كلمة الحجاب، والفائدة التي تعود على المرأة إذا غطت وجهها عن الرجال الأجانب؟ وجزاكم الله خير الجزاء.","title":"ما هو الحجاب الشرعي للمرأة؟","answer":"الجواب: الحجاب حجابان: حجاب واجب عند الجميع؛ عند جميع أهل العلم، وهذا هو غطاء الرأس وغطاء البدن، ماعدا الوجه والكفين، أما غطاء الوجه والكفين عن الرجال فهذه مسألة خلاف بين العلماء، والصواب أنه يجب عليها أن تحجب وجهها وكفيها عن الرجال؛ لأن الوجه عورة وزينة واليدان كذلك، والله جل وعلا يقول: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ [النور:31] فالوجه من الزينة العظيمة، واليدان كذلك، فهي تمنع من إبداء زينتها للأجانب في الأسواق أو عند إخوة زوجها وأعمام زوجها، أو عند الخدم.. ونحو ذلك، حذرًا من الفتنة عليها وبها. ويقول جل وعلا في آية أخرى: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] الآية من سورة الأحزاب، فأبان سبحانه أن الحجاب أطهر لقلوب الجميع، الرجال والنساء، وهذا يعم الوجه وغيره في قوله: من وراء حجاب يعم الوجه وغيره، وقد قالت عائشة رضي الله عنها في حجة الوداع: \"كنا مع النبي ﷺ في حجة الوداع فإذا دنا منا الرجال سدلت إحدانا جلبابها على وجهها فإذا بعدوا كشفنا\" وفي الصحيحين عنها رضي الله عنها أنها قالت لما سمعت صوت صفوان بن المعطل تسترجع لما رآها قد تركها الجيش قالت: \"فسمعت صوته وكان قد رآني قبل الحجاب فلما سمعت صوته خمرت وجهي\" فدل على أن النساء قبل الحجاب كن لا يخمرن وجوههن، فلما نزلت آية الحجاب خمرن وجوههن عن الرجال. وآية الحجاب قوله تعالى: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] فالحجاب لجميع البدن أما الرأس والقدمان؛ الرأس يجب ستره، والقدمان يجب سترهما وهكذا الصدر والنحر ونحو ذلك، الخلاف في الوجه والكفين، بعض أهل العلم يرى أنهما ليستا عورة إذا كان الوجه ليس فيه زينة لا كحل ولا جمال، والكفان ليس فيهما حلي ولا جمال، والصواب أنهما زينة، وأنهما عورة يستران مطلقًا حتى ولو كان ليس فيهما كحل ولا زينة، وليس في اليدين حلي، والصواب أنهما عورة، لأنهما من الزينة المذكورة في قوله تعالى: وَلا يُبْدِينَ زِينَتَهُنَّ [النور:31] حتى الرجل الخلخال اللي فيها من العورة، قال سبحانه: وَلا يَضْرِبْنَ بِأَرْجُلِهِنَّ لِيُعْلَمَ مَا يُخْفِينَ مِنْ زِينَتِهِنَّ [النور:31] فنهى عن الضرب بالرجل؛ لأن ذلك يفضي إلى أن يعلم الخلخال فكيف بإبداء الوجه وإبداء النحر وإبداء اليد. وقد يتعلل بعض من أجاز كشف الوجه إذا لم يكن فيه فتنة واليدين قد يتعلل بعضهم بحديث رواه أبو داود عن عائشة رضي الله عنها: أن أسماء بنت أبي بكر رضي الله تعالى عنهما دخلت على النبي ﷺ في بيت عائشة وعليها ثياب رقاق -وعلى أسماء ثياب رقاق- فأعرض عنها النبي ﷺ وقال:  يا أسماء ! إن المرأة إذا بلغت المحيض لم يصلح أن يرى منها إلا هذا وهذا وأشار إلى وجهه وكفيه. قالوا: فهذا يدل على أن الوجه والكفين ليسا عورة، لقوله ﷺ: إن المرأة إذا بلغت المحيض لم يصلح أن يرى منها إلا هذا وهذا. والجواب نعم، هذا صريح، لو صح لكان صريحًا في أنهما ليسا بعورة إذا كان هذا الحديث بعد الحجاب بعد نزول الحجاب ولكن الحديث غير صحيح والوقت غير معلوم، هل هو بعد الحجاب أو قبل الحجاب؟ والحديث فيه علل:\nأولاً: أنه منقطع بين الراوي عن عائشة و عائشة كما قاله أبو داود رحمه الله لما رواه قال: هو مرسل، يعني: منقطع؛ لأنه من رواية خالد بن دريك عن عائشة ولم يدركها ولم يسمع منها والمنقطع ضعيف لا يحتج به.\nالعلة الثانية: أن في رواته شخصًا يقال له: سعيد بن بشير ، ضعيف لا يحتج بروايته.\nالعلة الثالثة: أنه من رواية قتادة عن خالد بالعنعنة وهو مدلس، والمدلس إذا عنعن لا تقبل روايته حتى يصرح بالسند.\nوالعلة الرابعة: أنه منكر المتن؛ لأنه لا يليق بـأسماء أن تدخل على النبي ﷺ وهي امرأة كبيرة؛ امرأة الزبير من خيرة أصحاب النبي ﷺ، ومن العشرة المشهود لهم بالجنة، لا يليق بها أبدًا ولا يظن بها أن تدخل على النبي ﷺ في ثياب رقاق ترى عورتها منها، هذا لا يظن بها رضي الله عنها ولا يليق بها أبدًا، وهي أكبر من عائشة وأسن من عائشة، فلا يظن ظان ولا ينبغي أن يظن ظان أنها تدخل على النبي ﷺ في ثياب رقاق ترى عورتها منها، يعرض عنها النبي ﷺ، يرى منها شعرها وصدرها وبدنها، هذا لا يظن بها أبدًا، فهو باطل المتن منكر المتن.\nالعلة الخامسة: أنه لم يحفظ أن هذا بعد الحجاب، بعد نزول آية الحجاب، وكانوا قبل الحجاب تكشف المرأة وجهها ويديها وتجلس مع الناس ثم أنزل الله الحجاب ومنعن من ذلك، فلو صح سنده واستقام متنه لكان يجب أن يطالب المدعي بإثبات أنه بعد الحجاب حتى تقوم به الحجة، أما قبل الحجاب فكان النساء يفتشن وجوههن وأيديهن وأقدامهن قبل الحجاب ثم أنزل الله آية الحجاب فمنعن من ذلك وأمرن بالتستر والحجاب، كما في قوله سبحانه: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ [الأحزاب:53] قوله : وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ [النور:31]إلى آخره، قوله : يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلابِيبِهِنَّ [الأحزاب:59] والجلباب: ما تضعه فوق رأسها وبدنها، وفق الله الجميع. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16551/ما-هو-الحجاب-الشرعي-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_843/nour_84304.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":17626,"question":"الرسالة التالية رسالة وصلت إلى البرنامج من الأردن وباعثتها إحدى الأخوات المصريات المقيمة هناك رمزت إلى اسمها بالحروف (ن. أ. م) لها سؤال تقول فيه: إنها امرأة موظفة وهي في حاجة إلى الوظيفة والعمل وتسأل سماحتكم عن شروط الحجاب حتى تعمل وهي في إطار إسلامي، جزاكم الله خيرًا.","title":"شروط عمل المرأة","answer":"الجواب: الواجب عليها أن تلتزم بالحجاب الإسلامي في عملها فتلتزم عدم التبرج وعدم إظهار مفاتنها لا رأسها ولا وجهها ولا شيء من بدنها حتى لا تفتن ولا تفتن لا في الأسواق ولا في العمل إذا كان عندها رجال، إذا رأت الرجال تحتجب عنهم ،ويكون عملها مع النساء لا مع الرجال سواء كانت مدرسة أو غير مدرسة، تكون في تدريس النساء وفي عمل النساء حتى تسلم من الفتنة، وعليها أن تحتجب حتى الوجه الصحيح أنه عورة، فإذا لبست الحجاب -البرقع- وجعلت لعينيها نقبين أو لعين واحدة للنظر فلا بأس، وتستر بقية الوجه وهكذا قدماها ويداها على الصحيح؛ لأن المرأة عورة كلها عورة، والله يقول جل وعلا في كتابه الكريم: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]، ويقول جل وعلا: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنّ [النور:31] الآية.\nوالوجه من أعظم الزينة هكذا اليدان وهكذا القدمان، هكذا الشعور، هكذا الصدر، كلها زينة فلتحتجب عن الرجال الأجانب احتجابًا كاملًا، أما السلام والكلام لا بأس السلام الذي ليس فيه خضوع ليس فيه تغنج فلا بأس، يقول الله جل وعلا: فَلا تَخْضَعْنَ بِالْقَوْلِ فَيَطْمَعَ الَّذِي فِي قَلْبِهِ مَرَضٌ [الأحزاب:32]، يكون كلامًا عاديًا ليس فيه خشونة وليس فيه خضوع بل عادي.  قولاً معروفًا هذا هو المشروع للمرأة مع الرجال الأجانب تخاطبه مع الحجاب الشرعي ومع عدم الخلوة لا تخلو بالرجل الأجنبي لا ابن عمها ولا غيره، لا تخلو بزوج أختها ولا بأخي زوجها ولا بغيرهم، لقول النبي ﷺ: لا يخلون رجل بامرأة فإن الشيطان ثالثهما، لكن تبدأ بالسلام ترد السلام لا بأس تسأله عن حاله وعن عياله تخاطبه في حاجاتها مع عدم الخلوة ومع عدم الخضوع بالقول، ومع عدم التكشف وإبداء الزينة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16561/شروط-عمل-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_844/nour_84405.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":17726,"question":"السائل (ع. ط. ح) من الرياض يقول: ما حكم صبغ بعض الحاجبين باللون الذهبي وذلك عوضًا عن نتفهما؟","title":"حكم صبغ الحاجبين","answer":"الجواب: الصبغ لا بأس، النتف هو المحرم، النمص هو المحرم، أما صبغهما بأسود أو بغيره فلا بأس، إذا كان ما هو بشيب، أما إذا كانا شائبين لا يصبغ بالسواد، إذا كان قد حصل الشيب لا يصبغ بالسواد. نعم، بالحمرة أو بالصفرة لا بأس.\nالمقدم: جزاكم الله خيرًا يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16685/حكم-صبغ-الحاجبين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_595/59532.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":17741,"question":"هذا سائل للبرنامج يقول: ما معنى قول الرسول ﷺ: صنفان من أهل النار لم أرهما.. وذكر منهم: نساء كاسيات عاريات مائلات مميلات، رؤوسهن كأسنمة البخت المائلة؟","title":"معنى قول النبي ﷺ: \"صنفان من أهل النار...\"","answer":"الجواب: فسر العلماء هذا بأنهن كاسيات من نعم الله، عاريات من شكرها، وفسره آخرون بأنهن كاسيات ثياب رقيقة أو قصيرة عاريات؛ لأن الثوب القصير والرقيق ما هو كسوة. مائلات عن الحق عن العفة، مميلات لغيرهن إلى الفساد والزنا، هؤلاء متوعدون بالنار هؤلاء النسوة متوعدات بالنار؛ لهذا العمل السيئ، كونهن كاسيات عاريات كاسيات ثيابًا رقيقة أو قصيرة، عاريات في الحقيقة، أو كاسيات من النعم، عاريات من شكر الله بالمعاصي، يعني: عريهن؛ فعلهن المعاصي، مائلات عن الحق وعن العفة، مميلات لغيرهن نسأل الله العافية. نعم.\nرؤوسهن مثل أسنمة البخت المائلة يعني: يعظمن رؤوسهن، يجعلن على رؤوسهن أشياء كبيرة تعظمها. نعم.","link":"https://binbaz.org.sa/fatwas/16697/معنى-قول-النبي-ﷺ-صنفان-من-اهل-النار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_209/nour_20912.mp3","categories":["شروح الحديث","قضايا المرأة","اللباس والزينة"]},{"id":17768,"question":"هذه السائلة (ج. ص. ع. ع) تقول: ما حكم إزالة الشعر الواقع فوق الأنف مباشرة للضرورة كحفل زفاف أو التزين للزوج، وما حكم تخفيف شعر الحواجب وتسويتها إذا كانت تؤثر في شكل وجه المرأة، مع العلم - تقول - مع العلم بأنني لا أزيلها مطلقًا بل أقوم بتخفيفها فقط؟ جزاكم الله خيرًا.","title":"حكم إزالة الشعر الذي على الأنف وتخفيف الحاجبين","answer":"الجواب: شعر الحاجبين لا يجوز التعرض له، الرسول ﷺ لعن النامصة والمتنمصة وقد أخبر أهل اللغة أن النمص: أخذ شعر الوجه، وأخذ الحاجبين، فلا يجوز أخذ ذلك، أما ما بين الحاجبين فهذا محل نظر ليس من الحاجبين إن تركه فهو أحوط، وإن أخذه فلا أعلم به شيئًا؛ لأنه ليس من الحاجبين، وهو ما يحاذي الأنف بين الحاجبين؛ تركه أحوط كالحمى. نعم.","link":"https://binbaz.org.sa/fatwas/16751/حكم-ازالة-الشعر-الذي-على-الانف-وتخفيف-الحاجبين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_778/nour_77802.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":17776,"question":"يقول السائل: يتهاون كثير من النساء في كشف الوجه، فما حكم ذلك يا سماحة الشيخ؟ وما الأدلة الشرعية والتي تبين تغطية الوجه في هذا الأمر؟","title":"حكم كشف المرأة وجهها أمام الأجانب","answer":"الجواب: تعلم المرأة أن الواجب عليها التستر والبعد عن السفور؛ لأن ذلك فتنة، والدليل على ذلك قوله جل وعلا: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنّ [الأحزاب:53] هذا يعم أزواج النبي وغيرهن عليه الصلاة والسلام، وقوله جل وعلا في النساء: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنّ [النور:31] الآية، والوجه من أعظم الزينة، فالواجب عليها ستر بدنها إلا ممن ذكر: من أبيها وزوجها وأخيها وعمها وخالها. نعم.","link":"https://binbaz.org.sa/fatwas/16760/حكم-كشف-المراة-وجهها-امام-الاجانب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_596/59628.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":17788,"question":"في آخر أسئلته يقول سماحة الشيخ: عند الميقات قمت بالاغتسال والتطيب ولبست ملابس الإحرام ورشيت بعض الطيب على ملابس الإحرام وذلك قبل أن أعقد النية بالإحرام وذلك لجهل مني، فما الحكم؟","title":"حكم تطييب ملابس الإحرام","answer":"الجواب: في المستقبل لا تفعل، وما دام جاهل ما عليك لكن في المستقبل لا تطيب الإحرام تتطيب أنت فقط أما الإزار والرداء لا تطيبهم ولاسيما بما له لون كالزعفران والورس أما غيرهما فالأمر أسهل لكن تركه أولى وأحوط، النبي ﷺ قال: لا تلبسوا شيئًا مسه الزعفران أو الورس لأنهما طيب له لون وله صفة، أما الأطياب اللي ما لها لون فتركها أحوط أيضًا لا يجعلها في الإزار ولا في الرداء إنما الطيب يكون في رأسه وبدنه. نعم.\nالمقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16772/حكم-تطييب-ملابس-الاحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_778/nour_77810.mp3","categories":["اللباس والزينة","محظورات الإحرام","قضايا المرأة"]},{"id":17851,"question":"هل يجوز للمرأة أن تلبس بعض الأقمشة المزخرفة، على صدرها؟ ولاسيما أمام زوجها، وأمام المحارم؟","title":"حكم لبس الأقمشة المزخرفة أمام الزوج والمحارم","answer":"الجواب: لا حرج في ذلك، ولو كان فيها زخرفة.نعم.\nالمقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16844/حكم-لبس-الاقمشة-المزخرفة-امام-الزوج-والمحارم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_728/nour_72805.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":17852,"question":"تسأل سماحتكم عن حكم قص الشعر من الأمام، مع تركه من الخلف دون قص، للتجمل، والزينة، مع عدم التشبه في ذلك بالكافرات؟","title":"حكم قص المرأة شعرها من الأمام","answer":"الجواب: ترك قصه أفضل، إلا إذا رأى الزوج، أو المرأة، أو كلاهما رأى الزوج والمرأة، أو المرأة التي ليس لها زوج إذا رأت المصلحة في ذلك، من دون قصد التشبه بالكافرات، فلا نعلم بأسًا في ذلك، الممنوع الحلق، أما قصه بعض الشيء، فلا يسمى قزعًا، ولكن لا حرج في ذلك، إذا رأت المرأة المصلحة في ذلك، وليس لها زوج، أو اتفقت مع زوجها على ذلك، أو بتخفيف الشعر. نعم.\nالمقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16845/حكم-قص-المراة-شعرها-من-الامام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_727/nour_72706.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":17853,"question":"تسأل سماحتكم عن حكم تعليق الآيات القرآنية على الجدران، أو ما كتب على الساعات، أو التحف، وغير ذلك؟","title":"حكم تعليق الآيات على الجدران وكتابتها على التحف","answer":"الجواب: أما تعليق الآيات في المكاتب، والمجالس، فلا حرج فيه، إذا كان لقصد القراءة والانتفاع بها، والفائدة، فلا بأس بها، أو تعليق أحاديث، أو كلماتٍ طيبة، أو أشعار طيبة، لا بأس بذلك.\nأما جعلها في الساعة، فهذا خطأ؛ لأنه قد تمتهن، قد تطرح في محل ما هو مناسب، فلا ينبغي أن يكون لا في الساعة، ولا في الحلي، لا ذكر الله، ولا آيات، لأنها قد تطرح على وجهٍ يحصل فيه امتهان، ولكن ....... معلق على الجدار، في المكتب، أو في المجلس، وقد يتعظ به من أحاديث، أو آيات، أو أشعارٍ طيبة، فلا بأس بها.\nالمقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16846/حكم-تعليق-الايات-على-الجدران-وكتابتها-على-التحف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_728/nour_72807.mp3","categories":["اللباس والزينة","القرآن وعلومه"]},{"id":17871,"question":"من إحدى الأخوات المستمعات من أبها رمزت إلى اسمها بالحرف (ف)، تسأل عن حكم الزمام بالنسبة للمرأة، هل يجوز لها لبسه أو لًا؟","title":"حكم لبس المرأة للزمام","answer":"الجواب: لا نعلم في ذلك شيئًا، نعم الحمد لله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16884/حكم-لبس-المراة-للزمام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_845/nour_84506.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":17941,"question":"المستمع أحمد محمود مصري الجنسية ومقيم في جدة يقول: لي زوجة وأربعة أطفال في مصر وأريد استقدامهم إلا أنني بعيد عنهم ولا أستطيع الذهاب والعودة، فهل لي أن أترك بعض الأجار واستقدام زوجتي بدون محرم؟","title":"هل يجوز طلب سفر المرأة دون محرم؟","answer":"الجواب: لا. ليس لك استقدامها إلا بمحرم، نعم. لقول النبي ﷺ: لا تسافر امرأة إلا مع ذي محرم فاستقدام النساء بغير محارم فيه خطر كثير ومخالفة للنص عن النبي ﷺ. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16986/هل-يجوز-طلب-سفر-المراة-دون-محرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_847/nour_84721.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":17951,"question":"تقول هذه الأخت السائلة يا فضيلة الشيخ من أسئلتها: اعتمرنا في رمضان في العام الماضي مع الزوج والأولاد، وكانوا صغارًا، وأكبرهم كان في الرابعة من عمره، وأحرمنا، وأحرم ولبى عندما لقنه الوالد، ولكن كان الوقت حار جدًا، وأخرنا الطواف إلى بعد المغرب، وخلعت إحرام الصبي وألبسته ثياب، ثم طفنا وسعينا جميعًا، أرجو من سماحتكم بيان الحكم في ذلك، هل يلزمنا قضاء العمرة لذلك الطفل؟ أم ماذا نفعل مأجورين؟","title":"حكم من ألبست طفلها المخيط وهو محرم","answer":"الجواب: إذا كان فعلت هذا جهلًا؛ فليس عليك شيء والحمد لله، إذا كان عن جهل أو نسيان فليس عليك شيء، وإن كنت تعمدت وتعرفين الحكم الشرعي؛ عليك إطعام ستة مساكين، كل مسكين له نصف الصاع عن تلبيسه المخيط وهو محرم، وأنت تعرفي الحكم الشرعي، إطعام ستة مساكين لكل مسكين نصف صاع من قوت البلد، من تمر أو رز أو حنطة، والحمد لله. نعم.\nالمقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16960/حكم-من-البست-طفلها-المخيط-وهو-محرم","audio":"","categories":["اللباس والزينة","محظورات الإحرام","قضايا المرأة"]},{"id":17994,"question":"هل يجوز للمرأة أن تتزين بالمساحيق التجميلية لزوجها؟","title":"حكم تجمل المرأة لزوجها بالمساحيق","answer":"الجواب: لا نعلم في هذا بأسًا، إذا كان مساحيق لا تضرها بل تجملها ولا تضرها لا بأس. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17020/حكم-تجمل-المراة-لزوجها-بالمساحيق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_849/nour_84907.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":18011,"question":"يسأل ويقول: هل يجوز للمرأة المسلمة أن تحف الحواجب؟","title":"حكم حف المرأة حاجبيها","answer":"الجواب: لا يجوز هذا لا يجوز، النبي ﷺ لعن النامصة والمتنمصة والنمص: أخذ الحواجب وأخذ شعر الوجه، لكن لو كان في الوجه شعر زائد كاللحية أو الشارب فلا حرج في أخذ ذلك؛ لأن هذا يشوه الخلقة ويضر المرأة، أما الشيء المعتاد في الوجه أو الحاجبين فليس لها أخذ ذلك بل هذا من النمص المحرم. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17019/حكم-حف-المراة-حاجبيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_849/nour_84906.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":18020,"question":"تسأل عن لبس البنطلون للمرأة أمام زوجها وأبنائها الصغار؟","title":"حكم لبس المرأة البنطال أمام زوجها وأبنائها","answer":"الجواب: لا حرج في ذلك، لكن عند الأجنبي لا إذا كان يفصل الأعضاء، إذا كان ضيقًا أو يظهر منه شيء من العورة صدر أو رجل، الأجنبي لا. وأما إذا كان عند أولادها الصغار أو عند زوجها فهي مباحة لزوجها، وأولادها الصغار ليسوا ممن يخشى منه، وليسوا ممن يجب التستر عنه إلا إذا كانوا قد بلغوا الحلم فلا يرون منها إلا ما فوق السرة وتحت الركبة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17044/حكم-لبس-المراة-البنطال-امام-زوجها-وابناىها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_850/nour_85001.mp3","categories":["اللباس والزينة"]},{"id":18026,"question":"تسأل: ما حكم قص الشعر بالنسبة للمرأة؟","title":"حكم قص شعر المرأة","answer":"الجواب: ما نعلم فيه بأسًا إذا كان لمصلحة وإلا فتركه أولى؛ لأنه جمال للمرأة، لكن إذا كان طويل ويتعبها وقصت منه، أو أمرها زوجها بالقص منه؛ لأن طوله يتعبهم جميعًا، أو لأسباب أخرى فيها منفعة لهم أو جمال فلا حرج في ذلك، فقد ثبت أن أزواج النبي ﷺ بعد وفاته قصوا من شعورهن لأجل الكلفة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17068/حكم-قص-شعر-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_850/nour_85013.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":18060,"question":"هذا سؤال من المستمعة نورة من الخرج، تقول: أفيدونا جزاكم الله خيرًا عن حكم لبس الذهب الذي يوجد به صور حيوانات أو إنسان، هل يجوز لبسه أم لا؟","title":"حكم لبس الذهب الذي عليه صور","answer":"الجواب: الذهب الذي فيه صورة الحيوان لا يجوز لبسه بل يجب حك ذلك وإزالته، فإذا كان في قلادة أو في أسورة أو نحو ذلك، فإنه يزال بالطريقة التي تزيله أو يطمس بشيء ولا يجوز لبسه. وهكذا الثياب وهكذا الخمر وهكذا القمص، كلها لا يجوز لبسها إذا كان فيها صور، بل يجب أن تزال رءوس الصور إذا حك الرأس زال المحذور، المهم زوال الرأس، فإذا حك الرأس أو طمس بشيء لا يبين معه، بل يخفى زال المحذور سواء في ذهب أو فضة أو في قميص، أو في غير ذلك مما يلبسه المؤمن والمؤمنة. نعم. والحجة في هذا قول النبي ﷺ: لا تدع صورة إلا طمستها هكذا جاء الحديث عن رسول الله عليه الصلاة والسلام، وهكذا الحديث الثاني: أن الرسول عليه السلام «نهى عن الصورة في البيت، وأن يصنع ذلك». نعم.","link":"https://binbaz.org.sa/fatwas/17094/حكم-لبس-الذهب-الذي-عليه-صور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_901/nour_90103.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":18070,"question":"أختنا من البحرين تسأل أيضًا وتقول: سماحة الشيخ! ما قولكم في أن وجه المرأة صورة أي: أنني امرأة متحجبة، ولكن لا أضع على وجهي غطاء؛ نظرًا لأن بصري ضعيف وألبس نظارة، وفي حاجة إلى عدم وضع الغطاء، هل تبيح لي تلك الأمور عدم الغطاء أو لا؟","title":"حكم كشف المرأة وجهها بسبب ضعف بصرها","answer":"الجواب: المشروع للمرأة الحجاب، وهو واجب كما قال الله سبحانه في كتابه الكريم: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] وقال سبحانه: وَلا يُبْدِينَ زِينَتَهُنَّ إِلاَّ لِبُعُولَتِهِنَّ [النور:31] الآية. والوجه من الزينة لكن إذا كان البصر ضعيفًا، وتحتاج المرأة إلى إبداء عينيها فلا بأس، تبدي عينيها من طريق وضع النقاب أو البرقع تلبسه على وجهها وتبدي عينيها، أو تضع النظارتين على عينيها للاستفادة من ذلك لا حرج في ذلك والحمد لله: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ[التغابن:16] وتستر بقية الوجه. نعم.","link":"https://binbaz.org.sa/fatwas/17105/حكم-كشف-المراة-وجهها-بسبب-ضعف-بصرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_902/nour_90205.mp3","categories":["اللباس والزينة"]},{"id":18090,"question":"هل يجوز لرجلٍ أن يسافر بامرأةٍ من غير محارمه؟ ثم إذا نوقش في ذلك يقول: إنني مطمئنٌ من نفسي؟","title":"حكم سفر الرجل بامرأة من غير محارمه","answer":"الجواب: ليس له ذلك، لا يجوز للرجل أن يسافر بامرأة وهي غير محرم له، ولو قال: إنه مطمئن، ولو كان من الصحابة، لا يجوز له أن يسافر مع امرأة وحده، الرسول ﷺ قال: لا تسافر امرأة إلا مع ذي محرم، الإنسان لا يأمن على نفسه، ولا يثق بنفسه، ولا يطمئن إليها، إِنَّ النَّفْسَ لَأَمَّارَةٌ بِالسُّوءِ إِلَّا مَا رَحِمَ رَبِّي [يوسف:53]. والله جل وعلا أمر باتباع الرسول ﷺ والتمسك بهديه، فلا يجوز للمؤمن أن يخالف ذلك، يقول سبحانه: وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا [الحشر:7]، ويقول سبحانه: فَلْيَحْذَرِ الَّذِينَ يُخَالِفُونَ عَنْ أَمْرِهِ أَنْ تُصِيبَهُمْ فِتْنَةٌ أَوْ يُصِيبَهُمْ عَذَابٌ أَلِيمٌ [النور:63]، فليس له أن يسافر بمرأةٍ ليس لها محرم، بل يجب أن يدع ذلك، ويحذر ذلك، وهو متهم بهذا، وهي متهمةٌ أيضاً، فلا يجوز. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17125/حكم-سفر-الرجل-بامراة-من-غير-محارمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_730/nour_73014.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":18100,"question":"أخونا يسأل عن استخدام بعض العطور التي يشك في احتوائها على الكحول، هل ينقض الوضوء؟","title":"حكم استخدام العطور التي قد يكون فيها كحول","answer":"الجواب:","link":"https://binbaz.org.sa/fatwas/17135/حكم-استخدام-العطور-التي-قد-يكون-فيها-كحول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_903/nour_90307.mp3","categories":["اللباس والزينة"]},{"id":18177,"question":"متى نأمر بناتنا بالحجاب؟","title":"متى تؤمر البنات بالحجاب؟","answer":"الجواب: يجب أمرهن بالحجاب إذا بلغن الحلم، إذا بلغت الجارية خمسة عشر سنة أو احتلمت -يعني: أنزلت، في النوم أو غير النوم المني- أو أنبتت الشعر الخشن حول القبل -وهو الشعرة-. ولكن ينبغي أن يدربن على هذا قبل ذلك إذا بدأ بلوغ التسع السنين؛ لأنها حينئذٍ تشتهى، قد قالت عائشة رضي الله عنها: \"إذا بلغت الجارية تسعًا فهي امرأة\" فينبغي أن تدرب على الحجاب وتوصى بالحجاب، لكن من غير تشديد حتى إذا بلغت؛ فإذا هي قد اعتادت الحجاب وتمرنت عليه. وقد قال عليه الصلاة والسلام: لا يقبل الله صلاة حائض إلا بخمار فالخمار يلزمها في الصلاة عند بلوغها الحلم، أما فيما يتعلق بالرجال؛ فإن كونها تستتر قبل البلوغ، وتعتاد هذا، وتؤمر بهذا هذا أولى وأفضل إبعادًا لها عن الخطر، فإذا بلغت الحلم وجب عليها ذلك ووجب إلزامها بذلك. الله المستعان. نعم.","link":"https://binbaz.org.sa/fatwas/17222/متى-تومر-البنات-بالحجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_854/nour_85406.mp3","categories":["اللباس والزينة"]},{"id":18187,"question":"ورد عن الرسول ﷺ بأنه قال: من صلى الصبح في جماعة، ثم قعد يذكر الله حتى تطلع الشمس، ثم صلى ركعتين كانت له كأجر حجة أو حجة وعمرة تامة تامة تذكر بأنها امرأة وتريد أن تحظى بهذا الأجر فكيف يمكنها ذلك؟","title":"كيف تنال المرأة فضل الجلوس بعد الفجر حتى الإشراق؟","answer":"الجواب: تبقى في مصلاها حتى طلوع الشمس وتفعل هذا، تشتغل بذكر الله، أو بقراءة القرآن، أو التسبيح والتهليل، فإذا ارتفعت الشمس صلت ركعتين، يعمها الحديث والحمد لله، فالمرأة إذا بقيت في مصلاها الفجر تذكر الله، وتقرأ القرآن، ثم إذا شاء طلعت الشمس وارتفعت صلت ركعتين يحصل لها هذا الأجر إن شاء الله، والحديث لا بأس به، حسن. نعم. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17246/كيف-تنال-المراة-فضل-الجلوس-بعد-الفجر-حتى-الاشراق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_782/nour_78203.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":18203,"question":"تسأل سماحة الشيخ عن حكم تدريس البنات من قبل الرجال مكفوفي البصر؟","title":"حكم دراسة البنات عند رجل مكفوف البصر","answer":"الجواب: لا حرج في ذلك، أن يدرس مكفوف البصر للنساء، أو من طريق الآلة التي تسمعهم، ولا يرى من وراءها من النساء لا بأس بذلك ولو كان بصيرًا، فإذا درسهم بطريقة لا يراهم أو من طريق المكفوف فلا بأس بذلك، قد قال عليه الصلاة والسلام: إنما جعل الاستئذان من أجل النظر وقال عليه الصلاة والسلام لفاطمة بنت قيس لما طلقت: اعتدي عند ابن أم مكتوم فإنه رجل أعمى تضعين ثيابك فلا يراك خرجه مسلم في صحيحه. أما حديث أن النبي ﷺ قال.. عن النبهان عن أم سلمة أن الرسول ﷺ: «قال لـابن أم مكتوم لما دخل عليه ذات يوم وعنده اثنتان من زوجاته، قال: احتجبا منه، فقالتا: إنه لا يبصرنا، فقال: ألستما تبصرانه؟! فهو حديث ضعيف؛ لأن من رواية نبهان ، و نبهان ليس بذاك، وليس ممن يعتمد عليه، ثم هو شاذ مخالف للأحاديث الصحيحة، مخالف لحديث فاطمة بنت قيس ، ومخالف لحديث سهل: إنما جعل الاستئذان من أجل النظر وهو في الصحيحين. فالصواب: أنه لا حرج في ذلك، وأن الكفيف لا بأس أن يراه النساء ولا يلزمهن الحجاب، ولا مانع من تدريسه لهن، لكن ليس له أن يخلو بامرأة، الخلوة ممنوعة ليس له أن يخلو سواءً كفيفًا أو بصيرًا، ليس له أن يخلو بامرأة ليست محرمًا له؛ لقول النبي ﷺ: لا يخلون رجل بامرأة فإن الشيطان ثالثهما. فإذا كان التدريس لاثنتين أو ثلاث، أو أكثر فلا حرج في ذلك، أو كان معه شخص آخر من محارم المرأة، أو غير محارمها ممن لا يكون فيه تهمة؛ فإن الخلوة تزول. والحاصل: أنه لا يجوز التعليم الذي معه الخلوة، أما تعليم لا خلوة فيه فلا بأس به. نعم. المقدم: بارك الله فيكم شيخ عبد العزيز ! لو تكرمتم هل هذا الحكم لكل كفيف أم لنوع خاص من الأكفاء؟ الشيخ: لمن لديه علم، ولا يخشى منه الشر، أما من لا علم لديه، أو معروف بأسباب الفتنة والشر، أو يفتن به النساء، فلا ينبغي أن يكون معلمًا لهن، ينبغي لولي الأمر أو لولي المرأة أن يراعي هذه الأمور، وألا يتولى ذلك إلا من لا تخشى منه فتنة. نعم. المقدم: إذًا رغم أن الحكم كما تفضلتم بالجواز لكن له شروط معينة؟ الشيخ: لابد من مراعاة ما قد يخشى منه. نعم. المقدم: تتفضلون بإعادتها لأهمية الموضوع يا شيخ عبد العزيز ؟! الشيخ: كون المكفوف يعلم المرأة هذا لا بأس به، بشرط عدم الخلوة، وبشرط آخر وهو أن يكون ممن يعرف بالعلم والفضل والسيرة الحميدة، وعدم تعاطيه أسباب الفتنة، أما إذا كان يخشى من شره لضعف إيمانه، أو لجهله أو لأسباب أخرى فينبغي أن لا يولى ذلك. نعم. المقدم: جزاكم الله خيرًا، ونفع بكم.","link":"https://binbaz.org.sa/fatwas/17242/حكم-دراسة-البنات-عند-رجل-مكفوف-البصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_908/nour_90802.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":18223,"question":"هذا سائل للبرنامج يقول سماحة الشيخ: قال رسول الله ﷺ: حبب لي من دنياكم ثلاث: الطيب، والنساء، وجعلت قرة عيني في الصلاة وسؤالي يا سماحة الشيخ عن الطيب: هل هذا الطيب هو المعروف في وقتنا الحاضر دهن العود أو البخور؟","title":"معنى قوله ﷺ: \"حبب إلي من دنياكم الطيب... \"","answer":"الجواب: الحديث ما فيه ثلاث: حبب إلي من دنياكم النساء، والطيب، وجعلت قرة عيني في الصلاة لأن الصلاة ما هي من الدنيا، زيادة ثلاث غلط من بعض الرواة، الصواب: أن الحديث يقول ﷺ: حبب إلي من دنياكم النساء، والطيب، وجعلت قرة عيني في الصلاة والصلاة من الدين لا من الدنيا. والطيب كل ما له شم طيب دهن العود، دهن الورد، العنبر إلى غير ذلك، البخور، الطيب، لا يتقيد بشيء، ما كان له رائحة طيبة يسمى طيب. نعم. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17270/معنى-قوله-ﷺ-حبب-الي-من-دنياكم-الطيب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_782/nour_78212.mp3","categories":["شروح الحديث","قضايا المرأة","اللباس والزينة"]},{"id":18252,"question":"تقول السائلة: ما حكم الحجاب عن المدرس الأعمى؟","title":"حكم حجاب الطالبة عن المدرس الأعمى","answer":"الجواب: الحجاب إنما يكون عن البصير؛ لقوله ﷺ: إنما جعل الاستئذان من أجل البصر؛ ولأنه ﷺ أمر فاطمة بنت قيس لما طلقت أن تعتد عند ابن أم مكتوم وكان رجلا أعمى، قال: تضعين ثيابك عنده فلا يراك. نعم. أما حديث: أنه قال لزوجتين من زوجاته لما دخل ابن أم مكتوم أمرهما أن يحتجبا عنه، وقالتا: إنه أعمى، قال: ألستما تبصرانه؟ فهو حديث ضعيف، والصواب أن الحجاب إنما يكون عن البصير، أما الأعمى فلا يحتجب عنه. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17301/حكم-حجاب-الطالبة-عن-المدرس-الاعمى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_783/nour_78308.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":18260,"question":"هذه السائلة (م. د) تقول: ما حكم لبس الخاتم في السبابة اليمنى واليسرى بالنسبة للرجل والمرأة؟","title":"حكم لبس الخاتم في السبابة اليمنى واليسرى للرجل والمرأة","answer":"الجواب: لا أعلم في هذا شيئًا، لا أعلم في هذا شيئًا، أقول: لا أعلم في هذا بأسًا، المرأة تلبس الخواتم في جميع أصابعها، والرجل يلبس في الخنصر والبنصر كما كان النبي ﷺ الخنصر أو البنصر. المقدم: أحسن الله إليكم سماحة الشيخ، السائل من سوريا ... الشيخ: لأن المرأة . المقدم: نعم. الشيخ: التختم من زينتها ومن حليها، وأما الرجل لا بأس أن يلبس الخاتم في خنصره أو بنصره. نعم. المقدم: أحسن الله إليكم. الشيخ: لما جاء من الأدلة في ذلك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17309/حكم-لبس-الخاتم-في-السبابة-اليمنى-واليسرى-للرجل-والمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_783/nour_78316.mp3","categories":["اللباس والزينة"]},{"id":18282,"question":"أولى رسائل هذه الحلقة رسالة مطولة وباعثتها إحدى الأخوات المستمعات تقول المرسلة:(هـ. ع. أ) أختنا أرفقت برسالتها قصاصة من إحدى الصحف المصرية تتحدث عن تاريخ النقاب وتقول في رسالتها:إلى سماحة الشيخ: عبد العزيز بن عبد الله بن باز ، السلام عليكم ورحمة الله وبركاته.أنا امرأة مصرية مقيمة في المملكة العربية السعودية أرتدي الحجاب الكامل ولله الحمد، وكذلك عندما أعود إلى بلدي وأقصد الحجاب الكامل -النقاب- والذي يتحدث فيه عن النقاب بهذا الأسلوب الذي يتميز بالجهل كما تقول، يتميز بالجهل بتعاليم الدين الإسلامي الحنيف.كما أحزنني أيضًا تصور الكثيرين في بلدي عن مكروهية لبس النقاب حتى أنه منع ارتداؤه في الجامعات، وحرم دخول الجامعات المصرية على أي طالبة ترتدي النقاب، واعتباره من الأمور الداخلة على الإسلام ومن البدع.ولأنني مقتنعة بوجوب غطاء الوجه على نساء المسلمين، ولخوفي من أن يختلط الحق بالباطل، فإنني أتوجه لسماحتكم بالسؤال عن فائدة المؤتمرات الإسلامية، التي تنعقد كل آونة من الزمن، لماذا لم تناقش مثل هذه الأمور التي سيكون نقاشها مفيدًا للناس.وتستمر على هذا المنوال سماحة الشيخ، وترفق المقالة التي قرأتها في تلكم الصحيفة، والمقالة تتحدث عن تاريخ النقاب، وتاريخ النقاب كما سردته هذه القصاصة يبعده عن الإسلام، فما هو رأي سماحة الشيخ؟!","title":"تاريخ الحجاب الإسلامي وصفته الشرعية","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله رب العالمين، والصلاة والسلام على عبده ورسوله، وصفوته من خلقه، وأمينه على وحيه نبينا وإمامنا وسيدنا محمد بن عبد الله وعلى آله وأصحابه ومن سلك سبيله واهتدى بهداه إلى يوم الدين، أما بعد: فإني أشكر للسائلة اهتمامها بأمر الحجاب وأمر الإسلام بصفة عامة، وحرصها على تحجبها، وعلى معرفة ما شرع الله في الحجاب، وأن تقف على الحقيقة هي وأخواتها في الله، فأقول: الحجاب شرعه الله  لنبيه ﷺ وللمسلمين بعد الهجرة والناس في المدينة، بعدما هاجر عليه الصلاة والسلام كانت المرأة أولًا: تجلس مع الرجال غير متحجبة، غير متنقبة، ثم أنزل الله جل وعلا آية الحجاب في قوله  في سورة الأحزاب: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]. فبين سبحانه أن الحجاب أطهر لقلوب الرجال والنساء، وأبعد عن الإثم والشر والفساد، فلو لم يكن في الحجاب إلا هذه الآية لكانت كافية، لما فيها من الدلالة على وجوب الحجاب وبيان الحكمة في ذلك، وأن الحكمة أنه طهارة لقلوب الجميع من الفواحش وأسبابها وما يدعو إليها. وقال سبحانه أيضًا في نفس السورة: يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلابِيبِهِنَّ ذَلِكَ أَدْنَى أَنْ يُعْرَفْنَ فَلا يُؤْذَيْنَ وَكَانَ اللَّهُ غَفُورًا رَحِيمًا [الأحزاب:59]، فبين  أن الواجب على جميع المسلمين إدناء الحجاب، ولا فرق.. بين نساء النبي ﷺ وبين غيرهن، قال: يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ [الأحزاب:59]، فالآية عامة، تعم أزواج النبي ﷺ وبنات النبي ﷺ، ونساء المؤمنين، وأن الواجب أن يدنين عليهن من جلابيبهن، والجلباب ما يلبس على الثياب من الملاحف التي تكون على الرأس، وعلى بقية البدن، ويستر منها الوجه واليدان، هذا هو الجلباب، وقد تخص المرأة الوجه بنقاب خاص، تجعله عليه، لا يظهر منه إلا العين أو العينان، والبقية مستور، ولهذا قيل له: نقاب، لما فيه من النقب للعين أو العينين، هذا هو أصل الحجاب في منتصف الهجرة، بعدما مضى من الهجرة أربع سنوات أو خمس سنوات شرع الله الحجاب، الذي به ستر المرأة وبه بعدها عن أسباب الفتنة، وبعد الرجل عن الفتنة أيضًا. فمن أنكر الحجاب وزعم أنه بدعة في الإسلام فهو جاهل في الإسلام وهو في الحقيقة داعية إلى أسباب الشر. فنسأل الله لنا ولجميع المسلمين الهداية، وأن لا نقول على الله بغير علم، كما أسأله لجميع علماء المسلمين التوفيق والهداية، حتى يبصروا الناس وحتى يرشدوهم إلى ما يجب عليهم في أمر الحجاب وغيره، وقد قال الله سبحانه في سورة النور: وَقُلْ لِلْمُؤْمِنَاتِ يَغْضُضْنَ مِنْ أَبْصَارِهِنَّ وَيَحْفَظْنَ فُرُوجَهُنَّ وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنْهَا وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَى جُيُوبِهِنَّ وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ [النور:31] الآية، إلى أن قال في آخرها: وَلا يَضْرِبْنَ بِأَرْجُلِهِنَّ لِيُعْلَمَ مَا يُخْفِينَ مِنْ زِينَتِهِنَّ [النور:31] ثم قال سبحانه: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31]. فأرشد المؤمنين لغض الأبصار، وحفظ الفروج في أول الآيات، في قوله سبحانه: قُلْ لِلْمُؤْمِنِينَ يَغُضُّوا مِنْ أَبْصَارِهِمْ وَيَحْفَظُوا فُرُوجَهُمْ ذَلِكَ أَزْكَى لَهُمْ إِنَّ اللَّهَ خَبِيرٌ بِمَا يَصْنَعُونَ [النور:30]، ثم أرشد المؤمنات إلى عدم إبداء الزينة وإلى عدم الضرب بأرجلهن ليعلم الرجال ما يخفين من زينتهن، ثم حث الجميع على التوبة إلى الله سبحانه مما قد يقع من التقصير في أمر الله، والارتكاب لمحارم الله ، وقوله : إِلَّا مَا ظَهَرَ مِنْهَا [النور:31]، فسره جماعة بأن المراد بذلك: الملابس الظاهرة، كما قاله الإمام الكبير والعلامة الشهير من أصحاب النبي ﷺ ومن كبارهم: عبد الله بن مسعود ، وقال آخرون: إنه الوجه والكفان كما جاء عن ابن عباس وجماعة، ولكن قال جماعة من أهل العلم مراد ابن عباس يعني: قبل الحجاب، قبل وجوب الحجاب، كانت المرأة تبدي وجهها وكفيها قبل الحجاب. ومراده (ما ظهر منها) يعني: قبل النسخ، قبل أن ينسخ الحجاب، وأما بعد الحجاب، فالواجب كما قال ابن مسعود هو ستر الوجه وغيره، وبكل حال فالآيات واضحة في أن الحجاب يعم الوجه وغيره. والوجه هو عنوان المرأة ودليل جمالها، أو دمامتها وهو من أولى البدن بالستر، وهو أعظم الزينة وأظهر الزينة، وقد قال الله في الآية: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ [النور:31]، فالرأس والوجه والكفان والقدمان كلها من الزينة، فوجب على المرأة أن تسترها حتى لا تقع في فتنة ولا توقع غيرها في فتنة. وفي الصحيحين عن عائشة رضي الله عنها أنها قالت: لما كانت غزوة الإفك وجرى فيها ما جرى من فرية بعض الناس عليها رضي الله عنها؛ بسبب تخلفها عن الجيش لما ذهبت لقضاء حاجتها، وظن الذين يحملون هودجها أنها فيه؛ لأنها كانت خفيفة، وظنوا أنها فيه ورحلوا هودجها وجاءت من قضاء حاجتها، فلم تجد الجيش فلزمت مكانها، لزمت مكانها حتى مر عليها صفوان بن معطل فلما رآها استرجع وأناخ مطيته، وأركبها إياها وجعل يقود بها حتى أوصلها الجيش، قالت: «فسمعته يقول: إنا لله وإنا إليه راجعون فخمرت وجهي، وكان قد رآني قبل الحجاب»، فعلم بذلك من أم المؤمنين عائشة رضي الله عنها أن الحجاب كان بعد نزول آية الحجاب للوجه وغيره، قالت: «فخمرت وجهي، وكان قد رآني قبل الحجاب»، فعلم أنه بعد الحجاب لا يكشف الوجه ولا يرى، وإنما كان هذا قبل الحجاب، وهذا واضح في الرد على من أنكر الحجاب وزعم أنه بدعة أو زعم أنه لا يجب فعله. هذا الحديث مع عموم الآيات التي سبق ذكرها، كل ذلك دال على وجوب الحجاب، وأن هذا بعد نزول آية الحجاب وبعدما شرع الله للمسلمين الحجاب الكامل، فلا ينبغي لأحد أن يغتر بما يقوله بعض الناس في هذا الباب، وينبغي له أن يلزم ما هو الحق، وما هو الصواب، وما هو الأبعد عن الفتنة. رزق الله الجميع التوفيق والهداية. أما ما يتعلق بالمؤتمرات فأسباب عدم عنايتها بأمر الحجاب أمران: الأمر الأول: وضوح الأمر وأنه ليس بحاجة إلى أن يبحث في المؤتمرات؛ لأنها مسألة جزئية معلومة من الدين ظاهرة يعرفها العلماء ويعرفها الناس. والأمر الثاني: قلة من يطلبون المؤتمر ذلك، ولعل أي مؤتمر لم يطلب منه ذلك حتى يدرج هذا الموضوع في جدوله، والمؤتمرات تعقد لأشياء يطلب منها بحثها، وأن توضع في جداولها، فلعل أحدًا لم يتقدم إلى تلك المؤتمرات الإسلامية لبحث موضوع الحجاب، فلهذا لم يوضع في جدولها، وللأمر السابق وهو أنه أمر واضح وأمر ليس بالخفي حتى يوضع في المؤتمرات. نسأل الله للجميع التوفيق والهداية. المقدم: اللهم آمين، جزاكم الله خيرًا، سماحة الشيخ! أختنا تدافع عن النقاب وتتحمس له، وكأن الحجاب لا يصلح إلا بالنقاب، رأيكم؟ الجواب: الحجاب نوعان: نوع: بإسدال الخمار على الوجه، كما في وقت الإحرام، يسدل الخمار من على الرأس، الخمار ونحوه من الملابس التي توضع على الرأس ويسدل على الوجه حتى يغطي الوجه غطاءً لا يمنع أن تعرف طريقها، غطاء يستر الوجه ولكنه لا يمنع الرؤية التي تهديها الطريق، هذا نوع، وهذا الذي فعله أزواج النبي ﷺ في الحج، لما منعت المرأة من الانتقاب حال الإحرام، شرع لها أمر آخر وهو أن تسدل الحجاب على وجهها حتى لا يراها الناس، وحتى لا تفتن أحدًا ولا تفتن. والنوع الثاني: هو النقاب الذي يخاط على الوجه ويصلح لقدر الوجه يقال له: النقاب، وبعض الناس الآن في عهدنا يسميه البرقع، وبعضهم يسميه اللثام، فالحاصل أنه شيء يخاط على قدر الوجه، ويكون فيه نقب واحد أو نقبان، إما لعين واحدة وإما للعينين، تنظر به الطريق ويكون ساترًا للوجه كله، هذا هو النقاب، فالنقاب ممنوع في حق المحرمة، ولكن في حق غير المحرمة ليس بممنوع، إن شاءت وضعت الحجاب الذي هو الخمار، وإن شاءت وضعت النقاب، والخمار أكمل في الستر، إذا تيسر هو أكمل كما يفعل في وقت الحج، والعمرة وقت الإحرام، ومن دعتها الحاجة إلى النقاب، وكان عرف بلدها، ولا تستطيع غيره، أو ترى أنه كافي، ليس هناك ما يوجب عليها الحجاب فلا بأس؛ لأنه إذا كان الظاهر مجرد العين فقط، أو العينين كما يروى عن ابن عباس رضي الله عنهما فلا بأس بهذا. نعم. المقدم: بارك الله فيكم، إذًا: علاقة النقاب بالتاريخ الإسلامي أو بالتشريع الإسلامي، شيخ عبد العزيز ؟ الشيخ: علاقته في المدينة، الحجاب الكامل كان في المدينة، أما أصل الحجاب فهو جاءت به الشرائع كلها، أصل الحجاب جاءت به الشرائع كلها، أما أصل الحجاب فهو في المدينة، بعد مضى سنوات من الهجرة، والنقاب داخل في ذلك، هو من الحجاب، نوع من الحجاب. المقدم: هل وجد قبل الإسلام؟ الشيخ: ما أعرف..، لا أعلم شيء. المقدم: نعم نعم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17331/تاريخ-الحجاب-الاسلامي-وصفته-الشرعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_911/nour_91101.mp3","categories":["اللباس والزينة"]},{"id":18292,"question":"هل قص الشعر وتقصيره كشعر الرجل، ولكن ليس بنية التشبه بالرجال، هل يعتبر ذلك محرم؟","title":"حكم تقصير المرأة شعرها دون تشبه","answer":"الجواب: ترك المرأة شعرها أفضل؛ لأنه جمال لها، فالأفضل لها والأولى بها تركه، وعدم قصه، بل يبقى جمالًا لها وزينة لها، لكن لو أخذت منه، خففت منه لا لقصد التشبه بالكافرات، ولا بالرجال، ولكن لأنه طويل، فتخفف منه، فلا حرج في ذلك، وقد ثبت أن أزواج النبي ﷺ بعدما توفي أخذن من رءوس.. قصصن رءوسهن للتخفيف. فالحاصل: أن التخفيف لا بأس به، ولكن تركه للجمال والزينة يكون أفضل وأولى، وإذا قصت منه شيئًا فليكن ذلك على غير قصد التشبه بالكافرات، أو التشبه بالرجال بل لقصد التخفيف أو الزينة لزوجها إذا كان يرضى بذلك، أما هي إذا كان يمنعها فليس لها أن تعصي زوجها. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17343/حكم-تقصير-المراة-شعرها-دون-تشبه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_912/nour_91207.mp3","categories":["اللباس والزينة"]},{"id":18312,"question":"هذه سائلة للبرنامج تقول: سماحة الشيخ! هل تعتبر المسافة من جدة إلى مكة المكرمة سفرًا؟ ويشترط للمرأة أن تصطحب محرمًا؟","title":"هل المسافة بين مكة وجدة تعتبر سفرًا؟","answer":"الجواب: المعروف أنها سفر، المسافة ما بين جدة ومكة وما بين الطائف ومكة سفر، فلا تروح إلا بمحرم بينهم مسافة. نعم... يقارب نحو ثمانين كيلو أو تقاربها. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17363/هل-المسافة-بين-مكة-وجدة-تعتبر-سفرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_913/nour_91305.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":18325,"question":"هل الشعر الموجود بين الحاجبين ضمن الحاجب؟ وما حكم إزالته عند المرأة؟ جزاكم الله خيرًا؟","title":"حكم إزالة الشعر الذي بين الحاجبين","answer":"الجواب: الأظهر أنه ليس من الحاجبين، ولكنه فاصل بينهما، ولكن إذا تركته احتياطًا؛ حسن، وإلا فليس من الحاجبين، هذا القرن، تسمى: المقرونة، ويسمى الرجل إذا تركه: المقرون؛ فلا بأس في ذلك، إذا تركه احتياطًا؛ فهذا حسن، وإلا فالأصل إنه ليس من الحاجبين. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17379/حكم-ازالة-الشعر-الذي-بين-الحاجبين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_732/nour_73209.mp3","categories":["اللباس والزينة"]},{"id":18343,"question":"رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول: مديرة مدرسة البنات الابتدائية في مساح المزاحمية، أختنا لها مجموعة كبيرة من الأسئلة تسأل وتقول:هل قص الشعر من الأمام حرام وهي للزينة فقط، فأنا لي غرة من الأمام وشعري من الخلف طويل، وأنا أحبها كثيرًا، وهي تزين وتجمل الوجه كثيرًا، مع العلم بأنه لا يراها قريب غير محرم، فجميعهم محارمي مثل والدي وأعمامي وأخوالي وإخواني وأخواتي؟","title":"حكم قص المرأة شعرها من الأمام","answer":"الجواب: لا حرج في ذلك، الحمد لله، المهم صيانة ذلك عن الأجنبي، فإذا كان عندما يظهر الزوج والنساء والمحارم، فلا حرج في ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/17416/حكم-قص-المراة-شعرها-من-الامام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_861/nour_86106.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":18346,"question":"لقد قرأت في أحد الكتب بأن الروج -حمرة الشفايف- هي زينة الجن والشياطين، هل يجب علينا عدم استعمالها لزينة وهل المكياج حرام؟ مع أننا لا نضعها إلا في المناسبات مثل الأعياد والزواجات ولا يرانا الرجال؟","title":"ما حكم استعمال المرأة المكياج؟","answer":"الجواب: وضع ما يعتاده النساء في الشفة من الحمرة هذا لا بأس به، والقول بأنه زي الجن أو الشياطين، هذا لا أصل له. فالمقصود: أن المرأة لها أن تتزين وتتجمل بما تراه مناسبًا في وجهها وكفيها، في رجليها، في فمها، كل هذا لا بأس به عند الزوج، لا للرجال الأجانب. أو بين النساء لا بأس. أما عند الرجل الأجنبي هذا لا يجوز، عليها أن تتستر وأن تحتجب عمن حرم الله عليها أن يراها، كما قال الله سبحانه: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]، الآية من سورة الأحزاب، وقال تعالى في سورة النور: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ أَوْ أَبْنَائِهِنَّ أَوْ أَبْنَاءِ بُعُولَتِهِنَّ أَوْ إِخْوَانِهِنَّ أَوْ بَنِي إِخْوَانِهِنَّ [النور:31]، الآية. فالواجب على المؤمنة أن تتقي الله، وأن تحذر إبداء الزينة لغير الزوج والمحارم، والمكياج كذلك إن كان فيه مضرة يمنع، أما إن كان مجرد زينة ولكن لا يضر الوجه فلا حرج فيه كالصابون والسدر وغير ذلك، لكن بلغني من بعض الخبيرات أن بعض المكياج قد يضر الوجه، وقد يحصل بسببه نقط سوداء أو أشياء شبه ذلك، فإذا عرف أنه يضر بعض أنواع المكياج فيمنع، أما إذا كان مجرد أنه ينور الوجه، ولكن لا يكسب الوجه مضرة فلا حرج في ذلك. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/17405/ما-حكم-استعمال-المراة-المكياج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_861/nour_86103.mp3","categories":["اللباس والزينة"]},{"id":18376,"question":"هذه أخت سائلة أرسلت بهذا السؤال تقول سماحة الشيخ: ما حكم ما يسمى بتسريحة الشعر بالنسبة للمرأة؟ علمًا بأن شعر المرأة يجمع في مؤخرة الرأس، ويرفع قليلًا دون أن يصل إلى قمة الرأس،  يدخل في حديث: صنفان من أهل النار؟","title":"حكم تسريحة الشعر للنساء","answer":"الجواب: الظاهر -والله أعلم- أنه لا يدخل؛ لأن في الحديث الصحيح: صنفان من أهل النار لم أرهما بعد: رجال بأيديهم سياط يضربون بها الناس، ونساء كاسيات عاريات مائلات مميلات رءوسهن مثل أسنمة البخت، لا يدخلن الجنة ولا يجدن ريحها وأسنمة البخت.. البختية: الناقة البختية لها سنامان بينهما فجوة، بينهما منخفض، وهذا الذي يربط في مؤخر الرأس لضم بعض الشعر في مؤخر الرأس لا يتفق مع أسنمة البخت المذكورة، ولكن تركه أحسن، تركه أفضل وأبعد عن الشبهة، كونه يترك جدائل هذا أولى وأحوط وأبعد عن الشبهة في التشبه بهؤلاء النسوة. المقدم: شكر الله لكم يا سماحة الشيخ وبارك الله فيكم وفي علمكم ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/17437/حكم-تسريحة-الشعر-للنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_784/nour_78401.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":18382,"question":"هل إزالة شعر الوجه بالنسبة للمرأة حلال؟ أم حرام؟ وإزالة بعض الشعر من الحاجبين بحيث تساويه فقط، وهو مقدار صغير من الشعيرات، ليست كثيرة؟ هل هو حلال، أم حرام؟","title":"حكم إزالة المرأة شعر الوجه وشيئًا من الحاجبين","answer":"الجواب: أما الحاجبان فليس لها أن تزيل منهما شيئًا، الرسول ﷺ \"لعن النامصة والمتنمصة\"، والنمص: أخذ شعر الحاجبين، فليس للمرأة أن تأخذ من الحاجبين شيئًا، ولا أن تعدلهما، مطلقًا. أما شعر الوجه ففيه تفصيل: إن كان فيه شيء من المثلة، التشويه، مثل اللحية تنبت لها أو شارب فلها أن تزيل ذلك، تزيل هذا لأجل المثلة والتشويه، أما الشيء العادي في الوجه، فليس لها أن تتعرض له بشيء، لأنه من النمص. أما إذا كان سيشوه، نبت لها لحية،نبت لها شارب، فلها أن تزيلهما. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17442/حكم-ازالة-المراة-شعر-الوجه-وشيىا-من-الحاجبين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_732/nour_73214.mp3","categories":["اللباس والزينة"]},{"id":18383,"question":"تقول عن نفسها: أنا امرأة مسلمة، وأعمل، فما هي مواصفات الملابس الإسلامية التي يجب أن أرتديها؟ هل لبس الملابس الملونة الزاهية الألوان حرام؟ أم لا؟وهل لبس الملابس الحريرية اللامعة حلال؟ أم لا؟ وهل لبس الملابس المزركشة حلال؟ أم حرام؟ وجهوني حول هذا الموضوع، جزاكم الله خيرًا.","title":"اللباس الشرعي للمرأة المسلمة وحكم عملها بين الرجال","answer":"الجواب: إذا كنت بين النساء تلبسين ما يسر الله لك، والأولى أن يكون لباسًا معتدلًا، ليس فيه تكلف، ولا شهرة؛ لأن هذا قد يشوش على العاملين معكِ؛ قد يدعوهم إلى أن يتكلفوا مثلك، فالبسي لباسًا معتدلًا، مقاربًا لزميلاتك؛ حتى لا يحصل التشويش عليهن، أو إلجاؤهن إلى أن يتشبهن بك فيتكلفن، البسي اللباس المعتاد، المناسب، الذي ليس فيه تكلف. أما بين الرجال فلا تعملي بينهم، إن كان العمل بين الرجال؛ فلا تعملي بين الرجال، بالكلية، التمسي عملًا آخر ليس بين الرجال؛ فإن وجودك بين الرجال سكرتيرة، أو طبيبة بين الأطباء، أو ممرضة بين ممرضين رجال، هذا فيه خطر عظيم، وفتنة، فأنصحك بالحذر من هذا الشيء. أما بين النساء فالحمد لله، الأمر واسع، ولكن ننصح بأن تكون الملابس مقاربة، ليست فيها شهرة، ولا تكلف، بل مقاربة للباس الزميلات. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17445/اللباس-الشرعي-للمراة-المسلمة-وحكم-عملها-بين-الرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_732/nour_73215.mp3","categories":["قضايا المرأة","النظر والخلوة والاختلاط","اللباس والزينة"]},{"id":18470,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الأخ أحمد محمود الوكيل من الدمام، أخونا يناقش في قضية سبق أن تفضلتم بالإجابة عنها فيقول سماحة الشيخ:قال سماحتكم إن مسبل الإزار لا يشترط أن تكون نيته الكبر، وإن من علق الإسبال على الكبر فقد غلط في قول الرسول ﷺ: من جر ثوبه خيلاء لم ينظر الله إليه يوم القيامة، وقد ثبت أن العقوبات لمسبل الإزار دون قصد الخيلاء كعقوبة من يسبله بقصد الخيلاء؛ لأن عقوبة الحديث السابق عدم نظر الله إليه يوم القيامة، وقد قال الرسول ﷺ: ثلاثة لا يكلمهم الله يوم القيامة ولا ينظر إليهم ولا يزكيهم ولهم عذاب أليم ، قال الصحابة: خابوا وخسروا، من هم؟ قال: المسبل والمنان والمنفق سلعته بالحلف الكاذب، ولم يعلق الإسبال بالكبر فكيف تكون عقوبة الإسبال بدون كبر كعقوبته بالكبر في الحديث الأول؟وما يدل على ذلك أيضًا عندما قال الرسول ﷺ: من جر ثوبه خيلاء لم ينظر الله إليه يوم القيامة ، فقال أبو بكر: يا رسول الله! إن إزاري يسترخي إلا أن أتعاهده، فقال له الرسول ﷺ: إنك لست ممن يفعله خيلاء رواه البخاري، وهنا نفى الرسول ﷺ العقوبة عن أبي بكر ؛ لأنه لا يفعله خيلاء، فما تقولون يا سماحة الشيخ بارك الله فيكم ورحمنا وإياكم إنه هو الغفور الرحيم؟","title":"حكم إسبال الثياب لغير الخيلاء","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فقد صحت الأحاديث التي ذكرت عن رسول الله عليه الصلاة والسلام، وكلها دالة على تحريم الإسبال، وأنه إذا كان عن خيلاء لم ينظر الله إلى صاحبه يوم القيامة، وجاءت أحاديث أخرى ليس فيها هذا القيد، كالحديث الذي ذكرت، وهو حديث أبي ذر عن النبي عليه الصلاة والسلام أنه قال: ثلاثة لا يكلمهم الله يوم القيامة ولا ينظر إليهم ولا يزكيهم ولهم عذاب أليم: المسبل، والمنان فيما أعطى، والمنفق سلعته بالحلف الكاذب . وهكذا ما رواه البخاري في الصحيح عن النبي ﷺ أنه قال: ما أسفل من الكعبين من الإزار فهو في النار ولم يقيد بالخيلاء، والحديث الآخر حديث ابن عمر: من جر ثوبه خيلاء لم ينظر الله إليه يوم القيامة، ولا منافاة بين الأحاديث، وهكذا قصة أبي بكر حيث قال له النبي ﷺ: إنك لست ممن يفعله خيلاء. ووجه الجمع بين ذلك: أن من جر ثوبه خيلاء فيه الوعيد الصريح الشديد، ومن أسبل ثيابه أطلق النبي ﷺ فيه الوعيد أيضًا. والسر في ذلك والله أعلم: أن الغالب على المسبلين هو قصد الخيلاء والتكبر والترفع على الناس، وهذه نية محلها القلب لا يعلمها إلا الله  وقد يصرح المسبل بما يدل على قصده الخيلاء والتكبر، وإذا لم يصرح فالعلم بذلك إلى الله ، فهو تظاهر بمظهر أصحاب الخيلاء فالواجب منعه من ذلك وأمر قلبه إلى الله . فعلى المسلمين أن يمنعوا ما منعه الرسول ﷺ من الإسبال، وإذا قال: إنه لم يقصد الخيلاء فأمره إلى الله لكنه أظهر مظهر أصحاب الخيلاء وخالف الرسول فيما نهى عنه عليه الصلاة والسلام فوجب منعه ويعمه الخبر في قوله ﷺ: ثلاثة لا يكلمهم الله، وفي قوله ﷺ: ما أسفل من الكعبين من الإزار فهو في النار لعدم القيد، وكونه قيد في بعض الروايات لا يدل على قيد الروايات الأخرى؛ لأن تقييد بعض أفراد العام لا يقيد جميع أفراده كلها بل يكون صاحب القيد أشد في العذاب وأشد في النكال إذا كان عن خيلاء، وإذا جره عن غير خيلاء فالمنع عام والعقوبة عامة والوعيد عام لكن لا يلزم أن يكونوا في العقوبة سواء. فمن كان قصده الخيلاء فإن عقوبته تكون أشد، ومن لم يقصد ذلك وإنما تساهل وجر ثوبه ولم يبال فإنه تعمه الأحاديث ولا يلزم أن تكون عقوبته مثل عقوبة ذاك، فقد تكون العقوبة أخف؛ لأنه لم يقصد الخيلاء لكن المنع عام للجميع والتحريم عام للجميع. أما الصديق  فإنه لا يتعمد جر ثوبه وإنما يتفلت عليه الثوب ويسترخي من غير قصد فلم يدخل في هذا الوعيد، بخلاف الذي يتعمد إسبال ثيابه.. إسبال سراويله.. إسبال بشته.. إسبال إزاره فإن هذا يعمه الوعيد لتعمده الباطل، أما من ينفلت عليه ثوبه ويسترخي عليه ثوبه في بعض الأحيان من غير قصد بل لخلل فيما حصل من رفع الثوب أو لأسباب أخرى حصل بها الخلل حتى انسحب ثوبه فهذا لا يعمه الخبر لكونه لم يقصد ولم يتعمد وإنما حصل له ذلك من غير قصد، كاسترخاء الثوب الذي قد خبن عليه وربط ولكن حصل به خلل فاسترخى، أو لشق فيه حصل بسببه الارتخاء أو لغير هذا من الأسباب. وبهذا يتضح أن الإسبال ممنوع ومحرم لعموم الأحاديث، وأما العقوبة فهي متفاوتة ولا يلزم أن تكون متساوية فإنه ليس من قصد الخيلاء كمن لم يقصد، هذا أمر معلوم ولكن الجميع ممنوعون وليس لهم سحب ثيابهم ولا بشوتهم ولا سراويلهم، بل يجب أن يرفعوا ذلك وأن لا تكون أنزل من الكعب؛ لقوله عليه الصلاة والسلام: ما أسفل من الكعبين من الإزار فهو في النار هذا أصل أصيل يجب التمسك به. ولا يجوز أن يقال: إن مفهوم حديث ابن عمر من جر ثوبه خيلاء أنه يجيز لنا ما سوى ذلك، هذا لا يجوز بل يجب سد الباب وحماية المسلمين من هذا الفساد ومن هذا الإسراف، وأخذ العموم من الأحاديث الصحيحة عن رسول الله عليه الصلاة والسلام لعل المسلم يرتدع عن هذا الجرم ويبتعد عن هذا السبيل الخطير الذي يورده النار ولا حول ولا قوة إلا بالله، نسأل الله للجميع التوفيق والهداية. نعم. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/17556/حكم-اسبال-الثياب-لغير-الخيلاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_866/nour_86601.mp3","categories":["اللباس والزينة"]},{"id":18501,"question":"هنا رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: أنا المستمع (د. ل. م) مصري أعمل في الخبر، أخونا يقول: للدكتور يوسف القرضاوي كتاب الحلال والحرام، باب إبداء المرأة للزينة الظاهرة، روى أبو داود عن عائشة رضي الله عنها أن أسماء بنت أبي بكر دخلت على رسول الله ﷺ وعليها ثياب رقاق فأعرض عنها رسول الله ﷺ وقال لها: يا أسماء ! إن المرأة إذا بلغت المحيض لم يصلح أن يرى منها إلا هذا وهذا وأشار إلى وجهه وكفيه.ولكني سمعت منكم أن كشف وجه المرأة حرام، أرجو أن ترشدوني، جزاكم الله خيرًا.","title":"حكم كشف المرأة لوجهها وكفيها","answer":"الجواب: سبق أن نبهنا على هذا الحديث وبينا في حلقة سابقة بل في حلقات أن هذا الحديث لا يصح عن النبي ﷺ وأنه ضعيف جدًّا من وجوه كثيرة، وأن الواجب على من يذكره في أي كتاب أن يبين ضعفه وأنه لا يصلح أن يحتج به؛ لأن في سنده انقطاعًا وضعفًا يوجب عدم الاحتجاج به وعدم الاعتماد عليه، فهو من رواية خالد بن دريك عن عائشة ولم يسمع منها، فهو منقطع، والمنقطع عند أهل العلم لا يحتج به؛ يسمى ضعيفًا. وفي إسناده رجل ضعيف يقال له: سعيد بن بشير لا يحتج به أيضًا، وفي إسناده قتادة عن خالد وهو مدلس وقد عنعن، هذه ثلاث علل، وعلة رابعة: وهي أن هذا الحديث لو صح لكان محمولًا على ما كان قبل الحجاب؛ لأن المرأة قبل الحجاب كانت تبدي وجهها وكفيها ثم نسخ ذلك بقوله تعالى: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]، وبقوله سبحانه: يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلابِيبِهِنَّ ذَلِكَ أَدْنَى أَنْ يُعْرَفْنَ فَلا يُؤْذَيْنَ [الأحزاب:59]، وبقوله سبحانه في سورة النور: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ أَوْ أَبْنَائِهِنَّ أَوْ أَبْنَاءِ بُعُولَتِهِنَّ.. [النور:31] الآية، فليس لهن إبداء الزينة لغير المحارم، والوجه من أعظم الزينة. فعلم بذلك أن ذكر هذا الحديث من دون تنبيه على ضعفه وعلى أنه لو صح كان قبل نزول آية الحجاب غلط، ما كان ينبغي لمن ذكره إلا أن يبين ضعفه. وهناك علة خامسة: وهي أن مثل هذا العمل لا يظن بـأسماء رضي الله عنها؛ فإنها امرأة صالحة فقيهة معروفة، وهي أخت عائشة الكبرى، وهي زوجة الزبير بن العوام حواري الرسول ﷺ وهو أحد العشرة المشهود لهم بالجنة، فلا يليق منها بعد الحجاب أن تدخل على النبي ﷺ في ثياب رقيقة أو مكشوفة الوجه واليدين، فهذا مما يبين عدم صحة هذا الحديث، وأنه لا أساس له كما تقدم بيان ذلك وأنه معلول بعلل متعددة، والله المستعان. المقدم: إذًا الأفضل للمرأة والحالة هذه أن تستر وجهها؟ الشيخ: هذا هو الواجب عليها، هذا الواجب عليها الواجب أنه حجاب؛ لأن الوجه هو عنوانها الدال على جمالها أو على دمامتها، وقد ثبت في الصحيحين عن عائشة رضي الله عنها أنها قالت لما سمعت صوت صفوان يسترجع لما رآها حين تخلفت عن الجيش قالت: فلما سمعت صوته خمرت وجهي وكان قد رآني قبل الحجاب فعلم بهذا أنه قبل الحجاب كانوا يكشفون الوجوه، أما بعد الحجاب فكانوا يسترونه. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/17593/حكم-كشف-المراة-لوجهها-وكفيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_867/nour_86706.mp3","categories":["اللباس والزينة","الحكم على الأحاديث","قضايا المرأة"]},{"id":18516,"question":"السائلة التي رمزت لاسمها بـ (س. ح. م) من شقراء تقول في هذا  بالنسبة لإزالة الشعر الغير مرغوب فيه بالنسبة للمرأة، ما حكم إزالة هذا الشعر بصورة نهائية؟ يعني: لا يعود للنمو مرة أخرى؛ وذلك بمستحضرات التجميل مثل الكريمات والأعشاب، هل في ذلك تغيير لخلق الله؟","title":"حكم إزالة المرأة للشعر غير المرغوب فيه","answer":"الجواب: لا بأس بهذا، لا حرج، ليس هذا من التغيير المنهي عنه، فإذا أزالت شعر الإبط بما يزيله بالكلية فلا حرج في ذلك، فالسنة إزالته، وأن لا يترك أكثر من أربعين ليلة، شعر الإبط، شعر العانة، والظفر، والشارب هكذا وقت النبي ﷺ للناس، فإذا أزال الرجل أو المرأة شعر الإبط أو العانة بما يمنع نباته مرة أخرى، فلا بأس ولا حرج في ذلك، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17611/حكم-ازالة-المراة-للشعر-غير-المرغوب-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_786/nour_78612.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":18523,"question":"أختنا نعرض سؤالها الأخير في هذه الحلقة الذي تقول فيه: هل يجوز تفصيل الملابس عند خياط رجل؛ لأن وجود النساء ليس بكثرة، وإن وجد يكون بعيدًا عن المنطقة التي نكون فيها؟نرجو التوجيه، جزاكم الله خيرًا.","title":"حكم تفصيل المرأة ملابسها عند الخياط","answer":"الجواب: أما كونه يفصل عليها، ويلمسها هذا لا يجوز، أما كونها ترسل إليه المقاييس، ويفصل، أو يذهب بها الزوج أو الولد حتى تفصل لا بأس، أما كونها تحضر بنفسها، وهو يتولى المقاييس عليها، واللمس لها، فهذا لا يجوز، وفيه فتنة وشر، وهكذا الخلوة به أمر منكر أيضًا، ولكن إذا بعثت بالملابس إليه من طريق الزوج، أو من طريق الأخ، أو من طريق أخرى، مع المقاييس حتى يفصلها على مقاييسها ويخيطها، فلا بأس بذلك. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17636/حكم-تفصيل-المراة-ملابسها-عند-الخياط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_870/nour_87009.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":18528,"question":"يوجد مجموعة من الأخوات الملتزمات يلبسن الثياب الواسع في الكلية، مع العلم بأن هذه الكلية للبنات ولا يوجد فيه اختلاط، فهل نستنتج من ذلك أنه لا يجوز لبس التنورة التي تبين شكل الخصر، أو لبس الملابس الضيقة؟ مع العلم أننا إذا خرجنا نلبس العباءة الطويلة الساترة التي لا توضح أي شيء من شكل الجسم، فما هو رأي سماحتكم؟","title":"حكم لبس الطالبة الملابس الضيقة في الجامعات النسائية","answer":"الجواب: لا ريب أنه ينبغي للمرأة أن تلبس الملابس الساترة الضافية السابغة التي لا تبين حجم أعضائها وعورتها، ويكون لبسها متوسطًا لا ضيقًا يبين حجم العورة، ولا واسعًا يبين العورة أيضًا، ولكن يكون بين ذلك، وهذا في جميع الأحوال عند محارمها وعند النساء.  أما إذا كان عند الأجنبية، فالواجب عليها التستر الكامل بشيء لا يبين حجم العورة، ولا يكون ضيقًا يفصل أعضاءها، فإنه يفتن، ولكن يكون بين ذلك لا ضيقًا ولا واسعًا، وإذا كان فوقه العباءة أو الجلباب، وهو ما يسمى الجلال كان ذلك أكمل في الستر مع التخمر، مع تخمير الرأس والوجه حتى لا يراها الأجنبي، يعني: الذي هو غير محرم لها، نعم.","link":"https://binbaz.org.sa/fatwas/17632/حكم-لبس-الطالبة-الملابس-الضيقة-في-الجامعات-النساىية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_870/nour_87005.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":18532,"question":"أختنا نعرض سؤالها الأخير في هذه الحلقة الذي تقول فيه: هل يجوز تفصيل الملابس عند خياط رجل؛ لأن وجود النساء ليس بكثرة، وإن وجد يكون بعيدًا عن المنطقة التي نكون فيها؟نرجو التوجيه، جزاكم الله خيرًا.","title":"حكم تفصيل المرأة ملابسها عند الخياط","answer":"الجواب: أما كونه يفصل عليها، ويلمسها هذا لا يجوز، أما كونها ترسل إليه المقاييس، ويفصل، أو يذهب بها الزوج أو الولد حتى تفصل لا بأس، أما كونها تحضر بنفسها، وهو يتولى المقاييس عليها، واللمس لها، فهذا لا يجوز، وفيه فتنة وشر، وهكذا الخلوة به أمر منكر أيضًا، ولكن إذا بعثت بالملابس إليه من طريق الزوج، أو من طريق الأخ، أو من طريق أخرى، مع المقاييس حتى يفصلها على مقاييسها ويخيطها، فلا بأس بذلك. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17636/حكم-تفصيل-المراة-ملابسها-عند-الخياط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_870/nour_87009.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":18537,"question":"يوجد مجموعة من الأخوات الملتزمات يلبسن الثياب الواسع في الكلية، مع العلم بأن هذه الكلية للبنات ولا يوجد فيه اختلاط، فهل نستنتج من ذلك أنه لا يجوز لبس التنورة التي تبين شكل الخصر، أو لبس الملابس الضيقة؟ مع العلم أننا إذا خرجنا نلبس العباءة الطويلة الساترة التي لا توضح أي شيء من شكل الجسم، فما هو رأي سماحتكم؟","title":"حكم لبس الطالبة الملابس الضيقة في الجامعات النسائية","answer":"الجواب: لا ريب أنه ينبغي للمرأة أن تلبس الملابس الساترة الضافية السابغة التي لا تبين حجم أعضائها وعورتها، ويكون لبسها متوسطًا لا ضيقًا يبين حجم العورة، ولا واسعًا يبين العورة أيضًا، ولكن يكون بين ذلك، وهذا في جميع الأحوال عند محارمها وعند النساء.  أما إذا كان عند الأجنبية، فالواجب عليها التستر الكامل بشيء لا يبين حجم العورة، ولا يكون ضيقًا يفصل أعضاءها، فإنه يفتن، ولكن يكون بين ذلك لا ضيقًا ولا واسعًا، وإذا كان فوقه العباءة أو الجلباب، وهو ما يسمى الجلال كان ذلك أكمل في الستر مع التخمر، مع تخمير الرأس والوجه حتى لا يراها الأجنبي، يعني: الذي هو غير محرم لها، نعم.","link":"https://binbaz.org.sa/fatwas/17632/حكم-لبس-الطالبة-الملابس-الضيقة-في-الجامعات-النساىية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_870/nour_87005.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":18542,"question":"هل للمرأة أن تستعمل المكياج في وجهها لتتزين أمام زوجها؟جزاكم الله خيرًا.","title":"حكم استعمال المرأة المكياج أمام زوجها","answer":"الجواب: لا بأس بهذا المكياج لا بأس به، وهكذا.... بالكحل.. غسل الوجه وغيره بالصابون غيره..، بالشامبو، وغسل الرأس، المقصود: هذه الأشياء لا حرج فيها استعمال الشيء الذي ينظف الوجه وينوره أو الرأس كل هذا لا حرج فيه إذا كان مباحًا، إذا كان ما فيه محذور، أما إذا كان نجس لا يستعمل...، من المسكرات لا يستعمل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17643/حكم-استعمال-المراة-المكياج-امام-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_733/nour_73315.mp3","categories":["اللباس والزينة"]},{"id":18551,"question":"أختنا تقول: إني متحجبة، ولكن لا أغطي فمي وأنفي، فهل هذا حرام؟جزاكم الله خيرًا.","title":"حكم كشف المرأة وجهها أمام غير محارمها","answer":"الجواب: الصواب وجوب تغطية الوجه؛ لأنه عنوان المرأة جمالًا ودمامة، وقد اختلف الناس في ذلك. والصواب: هو أنه يجب أن تغطي المرأة وجهها جميعًا؛ لقول الله  في كتابه العظيم في سورة الأحزاب: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] ولم يستثن سبحانه الوجه ولا غيره. وقال : يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلابِيبِهِنَّ [الأحزاب:59]، والجلباب يغطى به الرأس والبدن والوجه والأيدي هو عام، وكذلك قوله -جل وعلا-: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ [النور:31] الآية. وفي أولها يقول سبحانه: وَقُلْ لِلْمُؤْمِنَاتِ يَغْضُضْنَ مِنْ أَبْصَارِهِنَّ وَيَحْفَظْنَ فُرُوجَهُنَّ وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنْهَا وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَى جُيُوبِهِنَّ وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ [النور:31] الآية، فقوله سبحانه: إِلَّا مَا ظَهَرَ مِنْهَا [النور:31] قد تعلق بعض أهل العلم، وقالوا: إن المراد بذلك الوجه والكفان، ولكن هذا ليس بصحيح، ولهذا قال عبد الله بن مسعود : «إن المراد بذلك الملابس الظاهرة »، وقال ابن عباس  -فيما روي عنه-: «إن المراد به الوجه والكفان» قال بعض أهل العلم: إنما أراد ابن عباس قبل النسخ، قبل نزول آية الحجاب، كانت المرأة يباح لها إظهار الوجه والكفين، وبعد ما نزلت آية الحجاب منعت من ذلك، وهذا هو الأقرب، والأظهر فيما رآه ابن عباس أن المراد يعني: فيما مضى قبل نزول آية الحجاب، أما بعد نزول آية الحجاب فالوجه داخل في الزينة التي قال الله فيها: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ [النور:31] الآية. ثم يدل على ذلك ما ثبت في الصحيحين عن عائشة -رضي الله عنها- أنها قالت لما سمعت صوت صفوان بن المعطل في غزوة الإفك؛ لما سمعت صوته قالت: «خمرت وجهي»، قالت: «وكان قد رآني قبل الحجاب» فهذا يدل على أنهم بعد الحجاب مأمورون بتخمير الوجه. والأمة تبع لأزواج النبي ﷺ في ذلك، الحكم للجميع. فالحاصل: أن الأرجح والأظهر من الأدلة الشرعية هو وجوب ستر المرأة وجهها وكفيها وبقية بدنها؛ لأنها عورة وفتنة، والله -سبحانه وتعالى- أرشدها إلى أسباب النجاة، وأسباب السلامة والعفة، حتى قال في آخر الآية: وَلا يَضْرِبْنَ بِأَرْجُلِهِنَّ لِيُعْلَمَ مَا يُخْفِينَ مِنْ زِينَتِهِنَّ [النور:31] قال أهل العلم: معناه أنها لا تضرب برجلها حتى يسمع صوت الخلخال؛ لأن السامع قد يفتن بذلك. وأما قوله سبحانه: وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَى جُيُوبِهِنَّ [النور:31] معنى الخمر: ما يغطى به الرأس، فضرب الخمار على الجيوب، معناه على الوجه والرأس؛ لأن الجيب مدخل الرأس، هذا الجيب -من الجوب وهو الشق- وجيوبهن: مدخل الرأس، فالمعنى: ليضربن بخمرهن على موضع الجيب؛ وذلك هو الرأس والوجه، هو موضع الجيب، فإنه يخرج من الرأس، ويبدو منه الوجه، هذا هو محل التخمير. وأما قول بعضهم: إنه لم يقل: على وجوههن، فلا يحتاج إلى هذا؛ لأنه لو قال: على وجوههن لقال آخرون: لما لم يقل على رؤوسهن، فيبقى الأمر أيضًا يحتاج إلى أن يقول: على رؤوسهن، وكلام الله أحكم وأعظم  فقال: وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَى جُيُوبِهِنَّ [النور:31] يعني: على محل الجيب، وهو الرأس والوجه هو الذي خرج من الجيب، وشق من أجله الجيب، فيخرج الرأس من هذا المحل، فيغطى بالخمار الذي هو ستر الرأس والوجه، وما قد يبدو من الصدر. وأما حديث الخثعمية، وأن الفضل نظر إليها، وصرف النبي ﷺ وجه الفضل، فليس في حديث الخثعمية أنها كانت سافرة كاشفة وجهها، بل الأظهر والأصل في ذلك أنها ساترة وجهها، ولو فرضنا أنها سافرة لكان هذا في الإحرام، وقد قال بعض أهل العلم: إنه يجوز لها كشف وجه في الإحرام؛ لقوله -عليه الصلاة والسلام-: لا تنتقب المرأة[1] ولا تلبس القفازين قالوا: نهيها عن النقاب يقتضي إسفارها، فيكون هذا في حال الإحرام، وهي قادمة من مزدلفة ما بعد رمت الجمرة، ولا بعد تحللت. فلو فرضنا أنها كاشفة لكان هذا في الإحرام، مع أن الصواب أن المحرمة تستر وجهها بغير النقاب، كما جاء عن عائشة -رضي الله عنها- أنها قالت: «كنا مع النبي ﷺ في حجة الوداع إذا حاذانا الرجال سدلت إحدانا خمارها من فوق رأسها على وجهها، فإذا بعدوا عنا كشفنا» هكذا روي عن أم سلمة أيضًا. فالمقصود: أن هذا يدل على أنهن يسترن بغير النقاب، وهو الخمار الذي يوضع على الرأس والوجه، أما النقاب فهو شيء يصنع للوجه، ويخاط للوجه يقال له: النقاب، ويقال له: البرقع، يجعل على الوجه، هذا هو الذي يمنع منه، تمنع منه المحرمة، أما كونها تستر وجهها بغير ذلك فهذا باق على أصله مأمورة به، حذرًا من الفتنة، وسدًا لباب الفتنة. وبهذا يعلم القارئ ويعلم المؤمن أنه ليس فيما ادعاه من رأى الكشف، ليس في حديث الخثعمية حجة في ذلك، والصواب: أنها ليست سافرة، ولو فرضنا أنها سافرة لكان ذلك في حال الإحرام، والمحرمة قد قال بعض أهل العلم: بأنها تكشف وجهها، فلا حجة في ذلك في كشفه خارج الإحرام. والصواب: أنها لا تكشف لا في الإحرام، ولا في غيره، وأن حديث الخثعمية ليس فيه صراحة بأنها سافرة، وإنما النظر يمكن أن تنظر إليه، وينظر إليها من دون كشف الوجه، فالنظر ممكن بأن تدير وجهها إليه، ويدير وجهه إليها، إما لحسن صوتها وأدبها حين سألت النبي ﷺ، وإما لأسباب أخرى، ولا يلزم من ذلك أن تكون سافرة الوجه، كما أنه لا يلزم منه أن تكون كاشفة الرأس أيضًا، نعم. المقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/17658/حكم-كشف-المراة-وجهها-امام-غير-محارمها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_916/nour_91602.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":18560,"question":"نعود في هذه الحلقة إلى رسالة المستمع (ض. أ. ع. ج) من جمهورية مصر العربية، أخونا بعث بأسئلة جيدة إلى هذا البرنامج، عرضنا جزءًا كبيرًا منها، وبقي له في هذه الحلقة عدد لا بأس به من الأسئلة، فيسأل ويقول: النقاب هل هو فرض أم مكرمة؟","title":"حكم النقاب للمرأة","answer":"الجواب: النقاب فرض على النساء في غير الحج والعمرة؛ لأنه ستر لهن عن الفتنة؛ ولهذا يقول -سبحانه وتعالى-: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]، فالحجاب أطهر لقلوب الرجال، وقلوب النساء، وأعظم ما في المرأة من الزينة وجهها، فالواجب هو ستره، والتنقب بالحجاب الساتر حتى لا تفتن ولا تفتن. وكان النساء قبل نزول آية الحجاب يكشفن وجوههن وأيديهن عند الرجال، ثم إن الله  أمرهن بالحجاب، وأنزل قوله سبحانه: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] الآية من سورة الأحزاب، وأنزل في هذا سبحانه: يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلابِيبِهِنَّ ذَلِكَ أَدْنَى أَنْ يُعْرَفْنَ فَلا يُؤْذَيْنَ [الأحزاب:59]، وهكذا قوله -جل وعلا-: وَقُلْ لِلْمُؤْمِنَاتِ يَغْضُضْنَ مِنْ أَبْصَارِهِنَّ وَيَحْفَظْنَ فُرُوجَهُنَّ وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنْهَا وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَى جُيُوبِهِنَّ [النور:31]. الخمار ما يضرب على مخرج الرأس وهو الجيب، والذي يخرج من الجيب هو الرأس والوجه، فتضرب بخمارها على شعورها وعلى وجهها حتى تستر ذلك من الرجال، والجيب هو الشق، جاب البلاد: شقها، جاب الصخر، شق الصخر، فالمقصود بالجيب: هو ما يشق لإخراج الرأس معه عند لبس القميص، فهذا هو محل الستر، يعني: تلقي جلبابها على رأسها ووجهها الذي هو محل الجيب، وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ[النور:31] الآية، والزينة يشمل الوجه ويشمل غيره من زينتها من شعرها ومن صدرها وقدمها ويدها وحليها وشبه ذلك مما يفتن، حتى قال في آخر الآية: وَلا يَضْرِبْنَ بِأَرْجُلِهِنَّ لِيُعْلَمَ مَا يُخْفِينَ مِنْ زِينَتِهِنَّ [النور:31] حتى نهى عن ضرب الرجل لقصد إسماع الخلخال الذي يكون في الرجل لأنه يفتن أيضًا. فالشيء الذي يفتن الرجال بالرؤية أو بالسماع تمنع منه المرأة حتى لا تفتن ولا تفتن؛ ولهذا يحرم عليها الخضوع بالقول؛ لأنه يفتن الرجال؛ ولهذا قال سبحانه: يَا نِسَاءَ النَّبِيِّ لَسْتُنَّ كَأَحَدٍ مِنَ النِّسَاءِ إِنِ اتَّقَيْتُنَّ فَلا تَخْضَعْنَ بِالْقَوْلِ فَيَطْمَعَ الَّذِي فِي قَلْبِهِ مَرَضٌ [الأحزاب:32] أي: مرض الشهوة، وهكذا غيرهن من باب أولى، إذا كان نساء النبي ﷺ مع تقواهن لله، وكونهن من أكمل النساء فغيرهن أحوج إلى هذا، والخطر عليهن أكبر. وفي الصحيحين عن عائشة -رضي الله عنها- أنها قالت: لما سمعت صوت صفوان بن المعطل في غزوة الإفك يسترجع لما رآها قد تخلفت عن الغزو، قالت: «فلما سمعت صوته خمرت وجهي، وكان قد رآني قبل الحجاب»، فعلم بذلك أن النساء كن قبل الحجاب لا يخمرن وجوههن، وبعد الحجاب صرن يخمرن وجوههن، وهكذا كان الصحابة كان الصحابيات في حجة الوداع مع النبي ﷺ يخمرن وجوههن عن الرجال. أما ما في حديث ابن عمر: ولا تنتقب المرأة ولا تلبس القفازين فالمراد النهي عن النقاب الذي هو مخيط للوجه لا تلبسه، ولكن تغطي وجهها بغير ذلك كالجلباب والخمار. المقدم: في الحج خاصة. الشيخ: في الحج في الإحرام؛ لأن عائشة -رضي الله عنها- أخبرت أنهن كن مع رسول الله ﷺ في حجة الوداع، وكن إذا دنا منهن الركبان سدلت إحداهن خمارها من على رأسها على وجهها، فإذا بعدوا كشفت، وهكذا جاء في حديث أم سلمة وجاء في حديث فاطمة بنت المنذر زوجة هشام بن عروة بن الزبير كل هذا يدل على أنهن معتادات التستر والحجاب في الإحرام وغيره، وإنما المنهي عنه النقاب الذي هو المخيط على قدر الوجه، فهذا تتركه وقت الإحرام في الحج والعمرة، وتكتفي بالخمار الذي يرخى عند الحاجة، وينزع عند عدم الحاجة. وسمي نقابًا لأنه ينقب فيه للعينين، هذا يترك وقت الإحرام وتستر وجهها بغير ذلك، وهكذا اليدان ما يلبس فيهما القفازان، ولكن يستران بغير ذلك من الجلباب ونحوه، ولا تلبس القفازين في حال الإحرام؛ لأن القفاز يسترها دائمًا ربما شق عليها، فتسترهما بغير القفازين كالخمار والجلباب والعباءة، ونحو ذلك. وأما حديث ابن عباس في قصة الخثعمية حين سألت النبي ﷺ في طريقه إلى منى منصرفًا من مزدلفة، فجعل الفضل ينظر إليها، وهي تنظر إليه، فهذا لا يدل على أنها كاشفة ولا يلزم من النظر إليه وإليها الكشف، بل الواجب أن يحمل ذلك على أنها كانت متسترة بغير النقاب، كما في حديث عائشة وأم سلمة، نعم. المقدم: جزاكم الله خيرًا. إذًا: على هذا فالنقاب فرض لا مكرمة فقط؟ الشيخ: نعم، فرض واجب على النساء، النقاب، أو ما يقوم مقامه من الخمر، فالمقصود ستر الوجه، نعم. المقدم: نعم ما يقوم مقام الحجاب؟ الشيخ: نعم ما يسمى حجاباً، نعم. المقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/17670/حكم-النقاب-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_917/nour_91702.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":18583,"question":"السائلة من جدة رمزت لاسمها بـ (ش) جدة تقول: سماحة الشيخ! لزوجي ابن أخت عمره ما يقارب من ثلاثة عشر عامًا، وأنا لا أحتجب منه، وأشعر بضيق من هذا؛ لأنني أخاف أن أكون قد وقعت في الإثم، تقول: فأرجو من سماحتكم إعلامنا بالسن الذي يجب على المرأة أن تحتجب فيه عن الأطفال؟ مأجورين.","title":"ما سن الأطفال الذين يجب على المرأة أن تحتجب عندهم؟","answer":"الجواب: يقول الله -جل وعلا- في كتابه العظيم في سورة النور: وَإِذَا بَلَغَ الأَطْفَالُ مِنْكُمُ الْحُلُمَ فَلْيَسْتَأْذِنُوا كَمَا اسْتَأْذَنَ الَّذِينَ مِنْ قَبْلِهِمْ[النور:59] فإذا بلغ الحلم خمسة عشر سنة، أو أنزل المني عن شهوة، أو أنبت الشعرة؛ وجب الاحتجاب عنه، ووجب عليه الاستئذان حتى يحتجبوا. وما دام لم يبلغ خمسة عشر سنة، ولم ينبت الشعرة، ولم يحتلم؛ يعني: لم ينزل المني؛ فإنه طفل لا يحتجب عنه، وإذا كان بلغ ثلاثة عشر سنة وأنت لا تعلمين حاله، فالاحتجاب أحوط؛ لأنه قد يكون أنبت، قد يكون احتلم ابن ثلاثة عشر وابن اثنى عشر حري بأن يحتلم، من عشر فما فوق، إذا بلغ عشرًا فما فوق حري أن يحتلم، فإذا احتجبت عنه من عشر فأكثر من باب الاحتياط حسن، وإلا فلا يجب إلا عن ابن خمسة عشر سنة فأكثر؛ لأنه هو الذي متيقن أنه احتلم أنه بلغ الحلم، أو شخص يقر ويعترف أنه احتلم، أنزل المني، أو يقر أنه أنبت، فهذا يكون قد بلغ يحتجب عنه. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17701/ما-سن-الاطفال-الذين-يجب-على-المراة-ان-تحتجب-عندهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_786/nour_78622.mp3","categories":["اللباس والزينة"]},{"id":18622,"question":"السائلة أم أحمد لها هذا السؤال تقول: ما معنى في الحديث: مائلات مميلات رؤوسهن كأسنمة البخت المائلة؟","title":"معنى قوله ﷺ: \"مائلات مميلات ...\"","answer":"الجواب: هذا فيه النهي مثل هؤلاء الذين أخبر عنهم النبي -عليه الصلاة والسلام- في الحديث الصحيح، المائلة: التي تميل إلى الفاحشة والمميلة: تميل غيرها إلى الفواحش رؤوسهن كأسنمة البخت المائلة يعني: يعظمن الرؤوس يضخمنها بأشياء يجعلونها عليها. فالواجب على الرجل أن يختار المرأة الطيبة التي سمعتها حسنة، يسأل عنها حتى تتزوج المرأة الصالحة، مثل ما قال ﷺ: تنكح المرأة لأربع: لمالها، ولجمالها، ولحسبها، ولدينها، فاظفر بذات الدين تربت يداك فالمؤمن يلتمس المرأة الصالحة، ويسأل عنها؛ حتى لا تكون امرأة تتهم بالشر والفساد، بل يسأل عنها أهل خبرة، وأهل معرفة بها، فإذا وصفت له بأنها امرأة صالحة تزوجها فاظفر بذات الدين تربت يداك نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17735/معنى-قوله-ﷺ-ماىلات-مميلات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_787/nour_78708.mp3","categories":["شروح الحديث","قضايا المرأة","اللباس والزينة"]},{"id":18626,"question":"مجموعة من الفتيات يقلن في هذا  نحن نحضر حفلات الزفاف التي فيها دف وأناشيد، وهذه الأناشيد ليس فيها كلام فاحش -إن شاء الله- وأحيانًا يكون الحفل خارج المنطقة، هل يجوز لنا ذلك؟","title":"حكم الدف للنساء في الأعراس","answer":"الجواب: الدف مشروع للنساء في الزواج، وإن كان فيه أغاني سليمة، أو أناشيد سليمة لا بأس، وأما استعمال آلات الملاهي الأخرى فلا تجوز، ولكن الدف كافٍ، والحمد لله في إعلان النكاح، أقره النبي ﷺ والأناشيد والأغاني التي في مدح الزوج أو الزوجة أو أهل الزوج أو أهل الزوجة ليس فيها محذور، الحمد لله، أما آلات الملاهي الأخرى كالموسيقى وغيرها والطبول، لا، نعم.","link":"https://binbaz.org.sa/fatwas/17734/حكم-الدف-للنساء-في-الاعراس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_918/nour_91825.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":18645,"question":"تسأل أختنا عن حكم من يستهزئ بالنساء المتحجبات، وخاصة من تغطي وجهها.","title":"حكم الاستهزاء بالمتحجبات","answer":"الجواب: هذا على كل حال حكمه أنه غالط، وأتى منكرًا. فالواجب عليه التوبة إلى الله من ذلك، وأن يشجعهن على الحجاب، وليس له ولا لغيره الاستهزاء بالمتحجبات، بل الواجب شكرهن وتشجيعهن على التحجب، لما في ذلك من المصلحة العظيمة؛ ولما في ذلك أيضًا من اتباع الشرع، والتمسك بالأوامر التي جاء بها الكتاب والسنة. كما قال الله سبحانه في كتابه العظيم: وَقَرْنَ فِي بُيُوتِكُنَّ وَلا تَبَرَّجْنَ تَبَرُّجَ الْجَاهِلِيَّةِ الأُولَى [الأحزاب:33] وقال سبحانه: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]، فالحجاب للمرأة فيه خير عظيم، ومصالح جمة لها وللمسلمين، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17760/حكم-الاستهزاء-بالمتحجبات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_735/nour_73503.mp3","categories":["اللباس والزينة","الأخلاق المذمومة"]},{"id":18652,"question":"يسأل أخونا ويقول: التلفزيون وسيلة إعلامية ترفيهية تظهر من خلاله صور النساء والرجال والحيوانات، وغير ذلك، ماذا تقولون عن هذه الصور المتحركة، ظهور النساء في التلفزيون بزيهن العادي أو بحجابهن الإسلامي بأصواتهن المثيرة؟","title":"حكم ظهور النساء على التلفاز","answer":"الجواب: ظهور النساء في التلفاز متبرجات أو سافرات لا يجوز، أما ظهورهن متحجبات مستورات البدن والوجه في خطبة أو في كلام أو في توجيه وإرشاد أو إخبار عن شيء، فلا يضر، كما تخبر في مجلس من المجالس أو في مكان من الأمكنة أنها فعلت كذا.. أو أنها قالت كذا.. ونحو ذلك. أما ظهورها متبرجة سافرة فهذا لا يجوز، لا في التلفاز ولا في غيره بالنسبة إلى الأجانب، حتى ولو في بيتها ولو في مجلسها لا يجوز لها ذلك، ففي التلفاز أشر؛ لأنها تظهر لمن لا يحصى من الناس، فهو منكر عظيم ولا يجوز فعله. وإذا كانت متبرجة متحسنة متجملة صار أشد في الإثم وأقبح وأشد في الفتنة، وهكذا الرجل -كما تقدم- لو ظهر في التلفاز مكشوف العورة، كما قد يقع في بعض الألعاب مثل لعب الرياضة.. وغير ذلك، هذا أيضًا لا يجوز، حتى ولو هو رجل، كأن تظهر عورته فخذه أو عورته الفاحشة هذا منكر لا يجوز، بل يجب أن يكون على الأقل مستور العورة ما بين السرة والركبة. وهكذا ظهور المردان الذين يفتنون الناس في ملابس ضيقة أو شفافة، أو يظهر الفخذ، كل هذا فتنة لا يجوز؛ لأن الأمرد قد تكون فتنته أشد من المرأة؛ فيجب الحذر وأن يكون بعيدًا عن أسباب الفتنة، لا في ملابسه ولا فيما يتعلق بالتحسينات التي قد يتعاطاها في وجهه، أو غير ذلك مما يفتن الناس، بل يجب أن يحذر أسباب الفتنة؛ لأن كثيرًا من الناس قد يفتن بالأمرد أكثر مما يفتن بالمرأة. فالواجب على الرجال والنساء البعد عن أسباب الفتنة، وأن يكون خروجه في التلفاز على وجه لا يضر الناس، ولا تحصل فيه فتنة لا من جهة المرأة ولا من جهة الرجل، نسأل الله للجميع الهداية والعافية. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17784/حكم-ظهور-النساء-على-التلفاز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_872/nour_87205.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":18654,"question":"نعود إلى رسالة أحد الإخوة المستمعين من جمهورية السودان أخونا يقول: الضي حسن أحمد فضل الله، عرضنا جزءًا من أسئلته في حلقة مضت، وفي هذه الحلقة له مجموعة من الأسئلة يسأل مثلاً ويقول:من ضمن عاداتنا في مراسيم العرس يوضع للعريس هلال مصنوع من الذهب على جبينه، أو صدره لفترة مؤقتة لا تتعدى ساعات قلائل، وهي ساعات الزفاف والدخلة، ثم ينزعه، ويكون ملكًا بعد ذلك للعروس، فهل لبس الذهب في هذه الحالة المؤقتة يعتبر حرامًا، أم ماذا تقولون؟ أثابكم الله.","title":"حكم لبس الرجل للذهب في زفافه اتباعًا للأعراف","answer":"الجواب: نعم، نعم لا يجوز؛ لأن الرسول ﷺ قال: أحل الذهب والحرير لإناث أمتي، وحرم على ذكورهم وأخذ مرة شيئًا من الحرير في يده اليمنى، وشيئًا من الذهب في يده اليسرى، ثم قال:  هذان حل لإناث أمتي، حرام على ذكورهم. فالذهب والحرير حل للإناث، يتزين به للأزواج، تلبس الحرير، وتلبس الذهب زينة للرجل، أما الذكر فليس له لبس الحرير، وليس له لبس الذهب لا على سبيل وقت العرس، ولا في يده، ولا في أذنه، ولا في رجله، ولا في غير ذلك، ولا في ملابسه، ليس الذهب من شأنه، الذهب من شأن النساء. وثبت عنه ﷺ أنه رأى في يد رجل خاتمًا من ذهب، فأخذه وطرحه، وقال: يعمد أحدكم إلى جمرة من النار، فيضعها في يده فقال بعض الناس للرجل: خذ خاتمك، قال: لا آخذه، وقد طرحه رسول الله ﷺ فتركه. نفورًا مما نفر منه النبي ﷺ، وحذر منه، وكمال في المتابعة والامتثال، حتى إنه لم يأخذه من شدة كراهته لما كرهه النبي -عليه الصلاة والسلام-، خرجه مسلم في صحيحه من حديث ابن عباس -رضي الله تعالى عنهما-. وثبت في الصحيحين عن رسول الله -عليه الصلاة والسلام-: \"أنه نهى عن التختم بالذهب\" وهذه القطعة التي توضع على جبهته أعظم من الخاتم، فالواجب ترك ذلك. وهكذا كل عادة سيئة تخالف الشرع يجب تركها، العوائد يجب أن تخضع لحكم الله ورسوله، فما كان منها موافقًا للشرع فلا بأس به، وما كان منها مخالفًا للشرع، فالواجب تركه كهذه العادة، وكعادة بعض الناس إذا تزوج يبقى أيامًا وليالي لا يحضر الجماعة، ولا يصلي في المسجد، وهذا غلط ومنكر، بل عليه أن يظهر، ويصلي مع الناس في الفجر وبقية الصلوات في أول ليلة وفي غيرها، فالعرس لا يمنع ولا يسوغ ترك الواجب، فالمؤمن يقوم بما يطلب منه في الزواج، وما جرت به العادة مما أباح الله، ولكنه لا يترك ما أوجب الله عليه من أجل عرس، بل يصلي مع الناس، ويؤدي الواجبات الأخرى، ويؤدي حق أهله، ولا تنافي بين هذا وهذا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17775/حكم-لبس-الرجل-للذهب-في-زفافه-اتباعا-للاعراف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_872/nour_87203.mp3","categories":["اللباس والزينة"]},{"id":18670,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين وضع في نهاية رسالته حرفين هما: (أ) و (س) أخونا رسالته أيضًا من الرسائل المطولة ملخصها:الحديث عن الأسواق التجارية الخاصة بالنساء، والتي لا يعمل فيها إلا النساء، ويرجو من سماحة الشيخ التوجيه بخصوصها، فإن استحسنتموها -كما يقول- شجعوا عليها، جزاكم الله خيرًا.","title":"حكم إقامة أسواق خاصة بالنساء","answer":"الجواب: هذه موجودة، ولا مانع منها إذا سلمت من الشر، لا مانع منها، حتى يقصدها النساء، ويقضين حاجتهن منها، وعلى الهيئات، وعلى ولاة الأمور أن يراقبوها عما يخشى منه من الخطر، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17771/حكم-اقامة-اسواق-خاصة-بالنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_919/nour_91909.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":18680,"question":"ما حكم لبس الحجاب في الخارج بحيث يكون اللبس محتشمًا، والوجه خالٍ من الزينة؛ لأن تغطية الوجه بالكامل يجعل الآخرين ينظرون إلى المتغطية بشك وريبة، وربما يتبعونها بشكل مجموعات، نرجو التوضيح في هذه المسألة، جزاكم الله خيرًا، وهل يجوز وضع النقاب -اللثمة- بحيث تظهر العينان فقط؟","title":"حكم كشف المرأة لوجهها في الدول الأجنبية","answer":"الجواب: الحجاب واجب في السفر والحضر، وعند الأجانب وغير الأجانب، من الكفرة وغيرهم، ليس للمرأة أن تكشف الحجاب عند الكفرة في بلاد الكفار، بل عليها أن تستر بدنها ووجهها كما تستره عند المسلمين، وليس لها أن تحتج باستنكارهم لذلك، فهؤلاء المشركون وهؤلاء الكافرات إذا جاؤوا إلى بلاد المسلمين يبقون على حالهم وعلى زيهم وهم كفار، فالمرأة المؤمنة أولى وأولى بأن تلزم زيها الإسلامي، ولو سخر منها من سخر، ولو استنكره من استنكره من الكفرة. ولا مانع من لبس البرقع لإظهار عين، أو عينين فقط، مع ستر جميع الوجه كما تقدم، ولكن الحجاب الكامل هو أفضل منه؛ لأن بعض الناس قد يفتن بالعين، فإذا سترت وجهها بالخمار؛ كان أكمل، وإذا أبدت العين أو العينين فلا حرج في ذلك، وإن جعلت فوق ذلك خمارًا أو غيره لا يمنع الرؤية؛ فلا بأس فهو أكمل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17822/حكم-كشف-المراة-لوجهها-في-الدول-الاجنبية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_873/nour_87308.mp3","categories":["اللباس والزينة"]},{"id":18681,"question":"ما حكم لبس البرقع بدون وضع كحل في العين أو أي نوع من الزينة؟ وما حكم الكحل إن وضع؟","title":"حكم لبس البرقع مع وضع الكحل في العينين","answer":"الجواب: البرقع لا بأس به عند الحاجة إليه، والخمار الساتر أفضل منه إذا تيسر الخمار الكامل مع كونها تبصر الطريق، ولا خطر عليها، فهو أولى وأكمل، كما كان الصحابيات يسدلن خمرهن على وجوههن، فإذا دعت الحاجة إلى البرقع لإظهار العين أو العينين للطريق والنظر لما أمامها؛ فلا بأس بذلك، على أن تكون العين ساذجة ليس فيها ما يجملها ويزينها ويسبب الفتنة بها من كحل أو غيره، نعم.","link":"https://binbaz.org.sa/fatwas/17821/حكم-لبس-البرقع-مع-وضع-الكحل-في-العينين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_873/nour_87307.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":18685,"question":"نعود أيضًا في هذه الحلقة إلى رسالة الأخت إيمان سلطان سعود من الدمام، أختنا في حلقة مضت عرضنا لها ثلاثة أسئلة، وفي هذه الحلقة تسأل وتقول: ما حكم التعطر بالعطور التي تباع في الأسواق، وكما هو معروف إن بها نسبة من الكحول؟","title":"حكم استعمال العطور التي بها نسبة من الكحول","answer":"الجواب: هذا فيه تفصيل: فإذا علم أن هذا العطر فيه شيء مما يسكر كثيره؛ لم يجز، إذا كان المشتري والمستعمل يعلم أن هذا العطر فيه شيء من المسكر الذي يسكر كثيره، أما الشيء القليل الذي لا يسكر كثيره؛ فهو معفو عنه، كما قال النبي ﷺ: ما أسكر كثيره فقليله حرام. فدل على أن الذي لا يسكر كثيره لا يكون محرمًا، لكن ما عرف أنه يسكر كالكالونيا المعروف الذي يستعمله بعض الناس، وفيه من الإسبير ما يسكر هذا معروف، فالواجب تركه وعدم استعماله، إلا إذا علم أن الذي فيه قليل لا يسكر كثيره؛ فلا بأس، أو علم أنه ليس فيه شيء فلا حرج. أما ما هو معروف الآن من كونه يسكر، ويتعاطاه بعض السفهاء، ويسكرون بهذه المادة المعروفة مادة الكالونيا؛ هذا لا يجوز استعماله، حتى يسأل أهل البصيرة أهل الخبرة، فإذا شهد أهل الخبرة أن هذا ليس به شيء، أو به شيء لا يسكر كثيره فلا بأس.  أما العطور التي لا يعرف حالها، فاستعمالها لا بأس به حتى يعلم أن بها شيئًا يسكر كثيره، وإلا فالأصل الإباحة. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17803/حكم-استعمال-العطور-التي-بها-نسبة-من-الكحول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_873/nour_87303.mp3","categories":["اللباس والزينة"]},{"id":18732,"question":"يسأل في آخر أسئلته هذا السائل من جمهورية مصر العربية عن الحكم الشرعي في تعطير الرأس والشخص محرم.","title":"حكم تعطير الرأس حال الإحرام","answer":"الجواب: لا يجوز للمسلم وهو في حال إحرامه أن يتعطر لا في رأسه، ولا في بدنه، الواجب الكف عن هذا؛ لأن الإحرام حرم عليه الطيب حتى يحل من إحرامه، حتى يتحلل من عمرته، أو يتحلل من حجه باثنين من ثلاثة، أما أنه يتطيب وهو بحال الإحرام لا، إذا تعمد هذا عليه الفدية الكفارة، وهي إطعام ستة مساكين، أو ذبح شاة، أو صيام ثلاثة أيام، إلا إذا كان جاهلًا أو ناسيًا فلا شيء عليه. المقصود: أن هذا ليس له التطيب بعد إحرامه، إنما الطيب عند الإحرام قبل أن يحرم، يستحب له الطيب عند الإحرام، وبعد التحلل يتطيب، أما بعد الإحرام ليس له أن يتطيب، بعدما يعقد إحرامه يعني: بعدما ينوي الدخول في الحج أو في العمرة هذا عقد الإحرام، يعني: بعد نية الدخول في الحج والعمرة، لا يتطيب بعد ذلك، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17811/حكم-تعطير-الراس-حال-الاحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_788/nour_78811.mp3","categories":["اللباس والزينة","محظورات الإحرام","قضايا المرأة"]},{"id":18765,"question":"هذا السائل يقول في سؤاله من السودان: من عادة الزواج لدينا بأن الرجل يحني يديه ورجليه يوم الزواج، ما رأي الإسلام في نظركم في ذلك؟","title":"حكم الحناء للرجال يوم الزواج إذا كان عادة بينهم","answer":"الجواب: إذا كان هذه عادة بين الجميع ما فيها تشبه بالنساء، هذا يفعلها الرجال، وليس هذا خاص بالنساء؛ فلا بأس، لكن إذا توقف الرجال، وتركوه للنساء يكون أحوط، وأحسن، كما في البلدان الأخرى، فإذا كان في السودان الرجال يفعلون هذا، ومشوا عليه، ولا يعتبر تشبه قد صار سجية لهم وعادة لهم لم يكن تشبه، صار هذا من العادة المشتركة، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17891/حكم-الحناء-للرجال-يوم-الزواج-اذا-كان-عادة-بينهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_790/nour_79017.mp3","categories":["اللباس والزينة"]},{"id":18767,"question":"يقول السائل: هل يجوز استخدام الصابون الذي له رائحة أثناء الإحرام، وكذلك معجون الأسنان وهو فيه رائحة؟","title":"حكم استخدام صابون له رائحة أثناء الإحرام","answer":"الجواب: لا حرج في ذلك؛ لأنه لا يسمى طيبًا، استعمال الصابون أو معجون الأسنان لا يسمى طيبًا، فلا يضر، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17896/حكم-استخدام-صابون-له-راىحة-اثناء-الاحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_791/nour_79102.mp3","categories":["اللباس والزينة","محظورات الإحرام","قضايا المرأة"]},{"id":18782,"question":"أخونا يسأل عن حكم أولئك الذين يقولون: إن تقصير الثياب لا يقصد به إلا دفع الخيلاء، هل ذلك صحيح؟ وهل من توجيه حول هذا؟جزاكم الله خيرًا.","title":"حكم إطالة الثياب تحت الكعبين بغير قصد الخيلاء","answer":"الجواب: الأحاديث الواردة في ذلك عن رسول الله -عليه الصلاة والسلام- عامة، ولا تخص من أراد الخيلاء فقط؛ ولهذا قال -عليه الصلاة والسلام- في الحديث الصحيح: ما أسفل من الكعبين من الإزار فهو في النار رواه البخاري في صحيحه، ولم يقيد ذلك بالكبر، وقال -عليه الصلاة والسلام-: ثلاثة لا يكلمهم الله، ولا ينظر إليهم يوم القيامة، ولا يزكيهم، ولهم عذاب أليم: المسبل إزاره، والمنان فيما أعطى، والمنفق سلعته بالحلف الكاذب خرجه مسلم في صحيحه، وفي حديث جابر بن سليم عنه -عليه الصلاة والسلام- أنه قال: إياك والإسبال، فإنه من المخيلة فسمى الإسبال من المخيلة. أما قوله ﷺ: من جر ثوبه خيلاء لم ينظر الله إليه يوم القيامة هذا لا يقتضي تقييد الأحاديث الأخرى، بل يدل على أن من جر ثوبه خيلاء يكون إثمه أكثر وأعظم، ولا شك أن التساهل في الإسبال وسيلة إلى الخيلاء، فإن الغالب أن الذين يسبلون ملابسهم إنما يحملهم على ذلك التكبر والترفع والتعاظم، وسد الذرائع أمر لازم في الشريعة، وواجب في الشريعة؛ ولأن في إسبال الثياب إسرافًا وتعريضًا لها للوسخ وللنجاسة؛ ولهذا جاء عن عمر  أنه رأى شابًّا يمس ثوبه الأرض، فقال: «ارفع ثوبك، فإنه أتقى لربك، وأنقى لثوبك ». أما حديث الصديق  حين قال: «يا رسول الله، إن إزاري قد يتفلت عليّ إلا أن أتعاهده، فقال له -عليه الصلاة والسلام-: إنك لست ممن يفعله خيلاء هذا معناه: أن الذي ينحسر إزاره بعض الأحيان من غير قصد الخيلاء مع تعهده له لا يضره ذلك، وليس معناه الإذن في إسبال الثياب إذا كان لا يقصد الخيلاء. فالواجب على المؤمن أن يحذر ما حرم الله عليه، وأن يتباعد عن صفة المتكبرين، وأن يحذر التساهل في المعاصي، فإن عاقبتها وخيمة، نسأل الله السلامة والعافية، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17909/حكم-اطالة-الثياب-تحت-الكعبين-بغير-قصد-الخيلاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_906/nour_90602.mp3","categories":["اللباس والزينة"]},{"id":18792,"question":"تسأل أختنا وتقول: إذا لم ترتد المرأة الخمار، هل تكون آثمة؟","title":"حكم المرأة إذا لم تلبس الحجاب","answer":"الجواب: نعم، لا بد من ستره ......، أما في الصلاة فلا بأس أن تكشف وجهها في الصلاة إذا كان ما عندها أجنبي، فإن السنة أن تصلي مكشوفة الوجه. أما القدمان فيستران في الصلاة، وهكذا الكفان إذا سترتهما يكون أفضل وإن كشفتهما في الصلاة فالصواب أنه لا حرج في ذلك، ولكن الستر أفضل.  وأما الوجه فالسنة كشفه في الصلاة، وأما إذا كان عندها أجنبي فإنها تستر الجميع في الصلاة وخارجها، نعم.","link":"https://binbaz.org.sa/fatwas/17914/حكم-المراة-اذا-لم-تلبس-الحجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_906/nour_90607.mp3","categories":["اللباس والزينة","ستر العورة للمصلي","قضايا المرأة"]},{"id":18801,"question":"يقول هذا السائل -سماحة الشيخ-: نسأل عن حكم الحجاب بالنسبة للنساء، وماذا يجب على أولئك الذين يقولون بأن هذه تقاليدنا تحرم وتعيب لبس الحجاب؟فوجهونا في ضوء هذا السؤال.","title":"الرد على القائلين بمخالفة الحجاب للتقاليد","answer":"الجواب: الواجب على المرأة الحجاب عن الرجل الأجنبي، وليس لها أن تبدي له زينتها، هذا هو الواجب؛ لقول الله : وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ[النور:31] الآية، والوجه والشعر وبقية بدنها من الزينة، ولقوله -جل وعلا- في سورة الأحزاب: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ[الأحزاب:53]. وكانوا في أول الإسلام يباح للمرأة أن تكشف للرجل، ثم نزلت آية الحجاب، ومنع النساء من الكشف، في قصة عائشة لما قال فيها أهل الإفك ما قالوا أخبرت: أن صفوان بن المعطل لما رآها استرجع، لما رآها وحدها قد مشى الجيش قد ارتفع الجيش عنها، وبقيت في محلها؛ لأن الجيش في بعض غزوات النبي ﷺ هي ذهبت تقضي حاجتها فجاء الذين يرحلون هودجها، فرحلوا هودجها يحسبونها في هودجها، فلما جاءت وقد مضى الجيش لزمت مكانها، ونامت، وقالت: إنهم سيفقدونها فيرجعون، وكان صفوان المعطل في آخر الجيش، فلما رآها استرجع، قالت: فلما سمعت استرجاعه فاستيقظت وخمرت وجهها، قالت: وكان قد رآني قبل الحجاب، فعرف أنها عائشة -رضي الله عنها-. فدل على أن المرأة منعت بعد الحجاب، بعدما نزلت آية الحجاب منع النساء من الكشف، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17927/الرد-على-القاىلين-بمخالفة-الحجاب-للتقاليد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_791/nour_79113.mp3","categories":["قضايا المرأة","ردود وتعقيبات","اللباس والزينة"]},{"id":18816,"question":"السائلة التي رمزت لاسمها بأم عبد العزيز من الرياض تقول في سؤالها الأول: بالنسبة للمرأة التي تدرس عند مدرس كفيف، ما حكم الحجاب عن المدرس الكفيف؟","title":"حكم حجاب المرأة من الرجل كفيف البصر","answer":"الجواب: ليس عن الكفيف حجاب، الحجاب عن النظر يحتجب عمن ينظر، أما من لا ينظر ليس عنه حجاب؛ لقوله ﷺ لفاطمة بنت قيس: اعتدي عند ابن أم مكتوم؛ فإنه رجل أعمى، تضعين ثيابك فلا يراك ولقوله ﷺ: إنما جعل الاستئذان من أجل النظر فالذي لا يبصر ليس عنه حجاب، ليس على المرأة أن تحتجب عنه، وأما ما يروى عنه ﷺ أنه قال لـعائشة وزوجة أخرى معها لما دخل ابن أم مكتوم: احتجبا عنه ألستما تبصرانه فهو حديث ضعيف لا يحتج به، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17950/حكم-حجاب-المراة-من-الرجل-كفيف-البصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_791/nour_79122.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":18817,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الكويت، وباعثتها إحدى الأخوات من هناك، تقول: (ع. ص. ع) أختنا لها مجموعة من الأسئلة، في سؤالها الأول تقول: هل يجوز وضع المساحيق -المكياج- والذهاب إلى الكوافير، علمًا بأني متغطية وأرتدي اللباس الشرعي؛ وذلك في الحفلات والأعراس، علمًا بأنه لا يوجد رجال في العرس، ولا في الكوافير (صوالين الحلاقة)؟أرجو التكرم بتوجيهنا، جزاكم الله خيرًا.","title":"حكم استعمال المرأة المساحيق والذهاب إلى الكوافير","answer":"الجواب: بسم الله الرحمن الرحيم  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فما يتعلق بالمساحيق هذا شيء فيه تفصيل: إن كانت هذه المساحيق أشياء مباحة ليس فيها محذور، ولا تؤثر ضررًا على المرأة في وجهها فلا بأس. أما إن كانت مساحيق من أشياء مسكرة، أو أشياء تضر الوجه، وتسبب فيه بقعًا سودًا، أو أشياء تضر المرأة؛ فإنها لا تجوز؛ لقول النبي ﷺ: لا ضرر ولا ضرار فالمؤمن والمؤمنة كلاهما لا يجوز لهما أن يتعاطيا شيئًا يضرهما لا في الوجه، ولا في غيره من البدن، فإذا كان هذا المكياج -الذي هو المساحيق- ينور الوجه، ولا يضره بشيء، وليس من مادة محرمة؛ فلا حرج في ذلك. أما الذهاب إلى الكوافير هذا أمر خطير، ولا ينبغي الذهاب إليها، ولا ينبغي فتح هذا الباب؛ لأنه يترتب عليه شر عظيم، وإضاعة أموال، وربما صار وسيلة إلى شر كثير، وفساد عظيم إذا تولاه من لا يؤمن.  فالحاصل: أني أنصح بعدم فتح الكوافير، وبعدم الذهاب إليها، وأن كل امرأة تكتفي بما جرت به العادة في بيتها مع أهلها وأخواتها وأمها ونحو ذلك، ولا حاجة إلى الكوافير، ولا ينبغي فتح الكوافير، ولا ينبغي للدولة السماح بذلك؛ لأن هذا يترتب عليه أخطار عظيمة، نسأل الله للجميع الهداية والعافية. المقدم: اللهم آمين، جزاكم الله خيرًا، إذًا تنصحون الأخوات بعدم الذهاب إلى هذه المحلات؟ الشيخ: نعم، ننصحهن ألا يذهبن إليها، وأن تكتفي المرأة في بيتها بما جرت به العادة من إصلاح نفسها بالغسل والنظافة، وطريقة الناس في تعديل الشعر، وتصليح الشعر بما جرت به العادة فيما بينهن. وقد أغنى الله الأولين عن هذا، ولم يحتاجوا إلى الكوافير، نعم. المقدم: نعم، نعم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17939/حكم-استعمال-المراة-المساحيق-والذهاب-الى-الكوافير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_877/nour_87701.mp3","categories":["اللباس والزينة"]},{"id":18821,"question":"ماذا علي إذا اضطررت للبس مخيط في لبس الإحرام لعذر شرعي كالمرض؟","title":"حكم من اضطر إلى لبس المخيط وهو محرم","answer":"الجواب: إذا وجد عذر للإنسان ليلبس المخيط فلا بأس، وعليه الفدية، وهي صيام ثلاثة أيام، أو إطعام ستة مساكين كل مسكين له نصف الصاع من التمر أو الأرز أو الحنطة، أو ذبح شاة يعني: جذع ضأن أو ثني معز. تذبح في مكة للفقراء، أحد هذه الثلاثة، إذا احتاج إلى أن يغطي رأسه من أجل المرض، أو يلبس مخيط لمرض فإنه يفعل هذه الكفارة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17948/حكم-من-اضطر-الى-لبس-المخيط-وهو-محرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_736/nour_73603.mp3","categories":["اللباس والزينة","محظورات الإحرام","قضايا المرأة"]},{"id":18825,"question":"قبل التحلل الأول نتفت شعرة أو شعرتين من جسدي دون تعمد، فماذا علي؟","title":"حكم نتف الحاج للشعر قبل التحلل الأول","answer":"الجواب: ليس عليك شيء، إن كان عن نسيان أو جهل ليس عليك شيء، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17957/حكم-نتف-الحاج-للشعر-قبل-التحلل-الاول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_736/nour_73605.mp3","categories":["اللباس والزينة","محظورات الإحرام","قضايا المرأة"]},{"id":18874,"question":"هنا رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: أنا المستمع: (د. ل. م) مصري أعمل في الخبر، أخونا يقول: للدكتور يوسف القرضاوي كتاب: الحلال والحرام (باب إبداء المرأة للزينة الظاهرة): روى أبو داود عن عائشة -رضي الله عنها-: أن أسماء بنت أبي بكر دخلت على رسول الله ﷺ وعليها ثياب رقاق؛ فأعرض عنها رسول الله ﷺ وقال لها: يا أسماء إن المرأة إذا بلغت المحيض، لم يصلح أن يرى منها إلا هذا وهذا وأشار إلى وجهه وكفيه، ولكني سمعت منكم أن كشف وجه المرأة حرام. أرجو أن ترشدوني، جزاكم الله خيرًا.","title":"الرد على من يستدل بحديث أسماء على كشف وجه المرأة","answer":"الجواب: سبق أن نبهنا على هذا الحديث، وبينا في حلقة سابقة -بل في حلقات- أن هذا الحديث لا يصح عن النبي ﷺ وأنه ضعيف جدًا من جوه كثيرة، وأن الواجب على من يذكره في أي كتاب أن يبين ضعفه، وأنه لا يصلح أن يحتج به؛ لأن في سنده انقطاعًا وضعفًا يوجب عدم الاحتجاج به، وعدم الاعتماد عليه، فهو من رواية خالد بن دريك عن عائشة، ولم يسمع منها؛ فهو منقطع، والمنقطع عند أهل العلم لا يحتج به، يسمى ضعيفًا، وفي إسناده رجل ضعيف يقال له: سعيد بن بشير لا يحتج به أيضًا، وفي إسناده قتادة عن خالد، وهو مدلس وقد عنعن، هذه ثلاث علل. وعلة رابعة: وهي أن هذا الحديث لو صح لكان محمولًا على ما كان قبل الحجاب؛ لأن المرأة قبل الحجاب كانت تبدي وجهها وكفيها، ثم نسخ ذلك بقوله تعالى: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] وبقوله سبحانه: يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلابِيبِهِنَّ ذَلِكَ أَدْنَى أَنْ يُعْرَفْنَ فَلا يُؤْذَيْنَ [الأحزاب:59] وبقوله سبحانه في سورة النور: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ أَوْ أَبْنَائِهِنَّ أَوْ أَبْنَاءِ بُعُولَتِهِنَّ.. [النور:31] الآية، فليس لهن إبداء الزينة لغير المحارم، والوجه من أعظم الزينة، فعلم بذلك: أن ذكر هذا الحديث من دون تنبيه على ضعفه -وعلى أنه لو صح كان قبل نزول آية الحجاب- غلط، ما كان ينبغي لمن ذكره إلا أن يبين ضعفه. وهناك علة خامسة: وهي أن مثل هذا العمل لا يظن بـأسماء -رضي الله عنها- فإنها امرأة صالحة فقيهة معروفة، وهي أخت عائشة الكبرى، وهي زوجة الزبير بن العوام حواري الرسول ﷺ وهو أحد العشرة المشهود لهم بالجنة، فلا يليق منها -بعد الحجاب- أن تدخل على النبي ﷺ في ثياب رقيقة، أو مكشوفة الوجه واليدين، فهذا مما يبين عدم صحة هذا الحديث، وأنه لا أساس له -كما تقدم بيان ذلك- وأنه معلول بعلل متعددة، والله المستعان. المقدم: إذًا: الأفضل للمرأة والحالة هذه أن تستر وجهها. الشيخ: هذا هو الواجب عليها، هذا الواجب عليها؛ الواجب لأنه حجاب؛ لأن الوجه هو عنوانها الدال على جمالها أو على دمامتها، وقد ثبت في الصحيحين عن عائشة -رضي الله عنها- أنها قالت لما سمعت صوت صفوان يسترجع لما رآها حين تخلفت عن الجيش، قالت: \"فلما سمعت صوته خمرت وجهي، وكان قد رآني قبل الحجاب\" فعلم بهذا أنهم قبل الحجاب كانوا يكشفون الوجوه، أما بعد الحجاب فكانوا يسترونها، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/18029/الرد-على-من-يستدل-بحديث-اسماء-على-كشف-وجه-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_880/nour_88006.mp3","categories":["اللباس والزينة","الحكم على الأحاديث","قضايا المرأة"]},{"id":18907,"question":"ما حكم الخمار في الإسلام؟ أي: بمعنى هل هو فرض كالحجاب مثلًا، أو هو شيء مستحب فقط؟ وإن كان فرض، فهل تضعه أمام زوج أختها، وأبناء عمها، وأبناء خالها، أم تضعه فقط في الشارع والأماكن العامة؟ وما دليل ذلك من القرآن أو السنة؟","title":"حكم الخمار في الإسلام","answer":"الجواب: الخمار سمي خمارًا؛ لأنه يستر ما وراءه، ومنه: تخمير الإناء ستر الإناء، ومنه الخمر؛ لأنها تستر العقل، وتضيع العقل، فالخمار: هو الستر الذي يوضع على الرأس والوجه؛ حتى يستر ذلك عن الناس، والمرأة مأمورة بالستر والخمار عن غير محارمها؛ لقول الله : وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ  فالحجاب: الخمار أو الباب أو الجدار، أو ما أشبه ذلك، مما يسترها: ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] هكذا في سورة الأحزاب بين سبحانه: أن الحجاب أطهر لقلوب الرجال والنساء، فهو واجب على المرأة أن تحتجب، وأن تستتر عن غير محارمها في بدنها كله. وزوج أختها ليس من محارمها، وهكذا بنو عمها، وبنو خالها، وبنو خالتها، وبنو عمتها، ليسوا محارمًا لها، وهكذا أخو زوجها، وعم زوجها، وخال زوجها، ليسوا محارمًا. وإنما المحرم: أبو زوجها، وجد زوجها، وابن زوجها، وابن ابن زوجها، وابن بنت زوجها، يعني: أولاده وأولاد أولاده، ذكورهم وإناثهم، وآباؤه وأجداده، هؤلاء محارم، وهكذا أبوها هي وأجدادها، وبنوها وبنو أبنائها وبنو بناتها، وهكذا إخوتها وأبناء إخوتها، وأبناء أخواتها، وهكذا أخوالها وأعمامها، هؤلاء محارم. أما ابن العم وابن الخال وابن العمة وابن الخالة، فليسوا محارم، بل له أن يتزوجها، والحكمة في ذلك -والله أعلم- كما هو معلوم: أن الحجاب أطهر للقلوب، وأبعد عن الفاحشة والفتنة، فإن المرأة إذا كشفت وأسفرت؛ ربما افتتن بها من يراها، وتعلق قلبه بها؛ فتقع الفتنة والفساد، فمن رحمة الله أن شرع الحجاب حتى لا تقع الفتن، وحتى لا يتعلق قلب الرجل بالمرأة التي ليست صالحة له، أو محرمة عليه، والمؤمن والمؤمنة كلاهما مأمور بتقوى الله، والحذر مما يسبب غضبه  والكشف للأجانب من أسباب غضب الله، ومن أسباب وقوع الفواحش، والله ولي التوفيق، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18048/حكم-الخمار-في-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_881/nour_88103.mp3","categories":["اللباس والزينة"]},{"id":18940,"question":"أختنا تقول: سماحة الشيخ، يعلم الله كم أحبك في الله، وأطلب منك يا شيخنا أن توجه إلي نصيحة لوجه الله، كما تنصح إحدى بناتك في ديني وخلقي، أرجو ذلك.","title":"نصيحة للفتاة المسلمة","answer":"الجواب: أحبك الله الذي أحببتنا له، الله -جل وعلا- أخبر على لسان نبيه ﷺ أن المتحابين في جلاله من السبعة الذين يظلهم الله في ظله، يوم لا ظل إلا ظله، يقول ﷺ: سبعة يظلهم الله في ظله يوم لا ظل إلا ظله ذكر منهم اثنين تحابا في الله، اجتمعا في ذلك، وتفرقا عليه، ويقول ﷺ: يقول الله يوم القيامة: أين المتحابون بجلالي؟ اليوم أظلهم في ظلي، يوم لا ظل إلا ظلي. فالتحاب في الله من أفضل خصال الإيمان، ومن أفضل القربات. ونصيحتي لك -أيها الأخت- ولغيرك من الأخوات تقوى الله في جميع الأحوال والاستقامة على دينه  والمحبة فيه والبغضاء فيه، وإحسان الخلق مع الناس، والقيام بما يلزم من بر الوالدين، وصلة الرحم حسب الطاقة، وحفظ الوقت عما لا ينبغي، والإكثار من ذكر الله . هكذا ينبغي للمؤمن وهكذا ينبغي للمؤمنة حفظ الوقت حتى يشغل بطاعة الله وذكره  وحفظ الجوارح عما حرم الله والاستكثار من طاعة الله ، كما قال الله : إِنَّ الَّذِينَ قَالُوا رَبُّنَا اللَّهُ ثُمَّ اسْتَقَامُوا تَتَنَزَّلُ عَلَيْهِمُ الْمَلائِكَةُ أَلَّا تَخَافُوا وَلا تَحْزَنُوا وَأَبْشِرُوا بِالْجَنَّةِ الَّتِي كُنْتُمْ تُوعَدُونَ  ۝  نَحْنُ أَوْلِيَاؤُكُمْ فِي الْحَيَاةِ الدُّنْيَا وَفِي الآخِرَةِ وَلَكُمْ فِيهَا مَا تَشْتَهِي أَنفُسُكُمْ وَلَكُمْ فِيهَا مَا تَدَّعُونَ  ۝  نُزُلًا مِنْ غَفُورٍ رَحِيمٍ [فصلت:30-32].  هذا جزاء من استقام على دين الله في ليله ونهاره، وفي جميع أوقاته، فحفظ الجوارح عن محارم الله، وشغل لسانه وجوارحه بطاعة الله وذكره، ووقف عند حدود الله، وأحب في الله، وأبغض في الله، ووالى في الله، وعادى في الله، وأعطى لله، ومنع لله، وأدى الحق الذي عليه لوالديه، ولقراباته ولجاره ولإخوانه المسلمين.  فوصيتي لك ولغيرك هو ما ذكر، هو تقوى الله -جل وعلا- والحرص على أداء الواجب في كل وقت وحين، وحفظ الوقت عما لا ينبغي، وإشغاله بذكر الله وطاعته  نسأل الله للجميع التوفيق والهداية. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18095/نصيحة-للفتاة-المسلمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_924/nour_92408.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":18967,"question":"هل قص الشعر للمرأة من أجل التزين لزوجها حد معين، كأن يكون مثلًا: يغطي الرقبة، أو دون ذلك، أو أن يكون متشابكًا للشعر؟","title":"حكم قص المرأة لشعرها للتزين لزوجها","answer":"الجواب: المشروع لها ترك شعرها يطول؛ لأنه زينة لها إلا إذا طال جدًا كثيرًا، فلا بأس بالأخذ من أطرافه، كما جاء عن أزواج النبي ﷺ أنهن أخذن من أطرافه بعد موته ﷺ لما طال.  أما الشعر العادي لا يؤخذ منه شيء، هذا جمال لها، وزينة لها، ولا يقص المقدم ولا غيره، نعم.","link":"https://binbaz.org.sa/fatwas/18099/حكم-قص-المراة-لشعرها-للتزين-لزوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_882/nour_88223.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":18970,"question":"أخت لنا بعثت برسالة مطولة في الواقع، فهمت من الرسالة سماحة الشيخ: أنها مطلقة، وحامل، وتحكي للناس وكأنها لا زالت مع زوجها السابق، وتسأل: هل هذا من الكذب؟","title":"حكم إخفاء المطلقة أن زوجها قد طلقها","answer":"الجواب: هذا يختلف إن كان صرحت بذلك أنها مع زوجها، وأن زوجها ما طلقها، فهذا كذب، أما كونها تحكي حكايات توهم المستمعين أنها مع الزوج، ولكن ليست صريحة، وإنما تخبر عن حالها مع زوجها، وتصرف زوجها معها قبل أن يطلقها، ونحو ذلك، وليس قصدها الكذب، وإنما قد يفهم المستمع أنها مع الزوج ولم تقصد الكذب، مثل أن تقول: كنا نفعل كذا، كنا نأكل الطعام في وقت كذا، كنا نأكل كذا وكذا، كنا نعمل كذا وكذا، مما يباح الكلام فيه، فهذا لا بأس به، وليس من شرطه أن تقول: إنه طلقني يوم كذا، أو يوم كذا، إذا أخبرت عن حالها مع زوجها فلا يضر ذلك. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18082/حكم-اخفاء-المطلقة-ان-زوجها-قد-طلقها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_924/nour_92405.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":18977,"question":"أخت لنا من حائل بعثت برسالة تقول فيها: المرسلة: (ص. ب. و) رسالتها مطولة في قالب القصة، ملخصها: أنها تخفي اسمها في كثير من الأحيان، فهل هذا يعد من الكذب؟","title":"حكم إخفاء المرأة اسمها","answer":"الجواب: هل فيه تفصيل: يعني لا يمكن الجزم في هذا، فإذا كانت تخفي اسمها، وتذكر كنية، أو تقول: بنت فلان؛ لأن لها غرضًا في ذلك ومصلحة في ذلك، فلا بأس: أنا بنت فلان، ولا يضر غيرها ذلك، أما إذا كان هذا الإخفاء يتضمن جحد حق يجب عليها الإقرار به، فلا يجوز لها ذلك، بل يجب عليها أن تقر بالحق الذي عليها يخصها هي، ولا يجوز لها أن تخفي اسمها في حق يلزمها. وإن كان ذلك لمقاصد شرعية وإسلامية، ولا يتضمن إسقاط حق لأحد، ولا ظلم أحد، فلا بأس، ليس عليها أن تبين اسمها لكل أحد، ولكن لا بد أن تلاحظ أن إخفاء اسمها لا يبطل حقًا لأحد ولا يوقعها في محرم، ولا يضر غيرها، والله المستعان، نعم. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18103/حكم-اخفاء-المراة-اسمها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_924/nour_92411.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":18984,"question":"أختنا تقول عن نفسها: الحمد لله رب العالمين أنا ملتزمة بالحجاب، ولكن والدي كان يرفض ذلك، وسمعت كلام والدي وتركته مدة بسيطة، ثم لبسته وزال عتب الوالد، ولم يرفض مرة أخرى، أفيدوني هل سأحاسب عن تلكم المدة التي تركتها أو لا؟","title":"حكم من ألزمها والدها بترك الحجاب فأطاعته","answer":"الجواب:   عليك التوبة، والتوبة تجب ما قبلها، والحمد لله، والتوبة معناها: الندم على الماضي، والعزم ألا تعودي فيه، وبذلك يعفى عنك -إن شاء الله-؛ لأن التائب من الذنب كمن لا ذنب له، وينبغي أن تعلمي أنه لا طاعة لمخلوق في معصية الخالق، فالمعصية لا يطاع فيها أحد، لا أب ولا زوج ولا أمير ولا غيرهم؛ لأن الرسول -عليه الصلاة والسلام- قال: إنما الطاعة في المعروف وقال -عليه الصلاة والسلام-: لا طاعة لمخلوق في معصية الخالق. فإذا قال الزوج: اكشفي لأخي أو لعمي أو لخالي أو لزوج بنتي أو أختي، وما أشبه ذلك؛ فلا تطيعينه في ذلك، وهكذا لو قال الأب: اكشفي للناس، أو اكشفي لفلان وفلان، وهم ليسوا محارم لا يطاع، إنما الطاعة في المعروف، وزوج بنت زوجك ليس محرمًا لك إذا كان ما هي بنتك، أما إذا كانت بنتك فزوجها محرم لك، أما بنت زوجك من غيرك فزوجها ليس محرمًا لك.   فالمقصود: أنه إذا قال الزوج أو الأب أو العم أو الأخ للمرأة: اكشفي أو اشربي الخمر، أو استعملي الدخان، أو ما أشبه ذلك من المعاصي، لا يطاع في هذا، لا أب ولا زوج ولا غيرهم، إنما الطاعة في المعروف، هكذا يقول النبي ﷺ، نعم. \nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18134/حكم-من-الزمها-والدها-بترك-الحجاب-فاطاعته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_925/nour_92506.mp3","categories":["اللباس والزينة"]},{"id":18997,"question":"يقول أخونا: بعض العلماء يفتون بأن الحجاب للمرأة إذا ما تركته ليس هو بحرام بإجماع العلماء مستدلين بحديث النبي ﷺ الذي معناه: \"إن المرأة إذا بلغت لا يجوز أن يظهر منها إلا الوجه والكفان\"؟ أثابكم الله تعالى، والسلام عليكم ورحمة الله وبركاته.","title":"مناقشة القول بجواز كشف المرأة لوجهها وكفيها","answer":"الجواب: هذا القول غلط، المرأة عليها الحجاب؛ لقول الله  في كتابه الكريم في سورة الأحزاب: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ[الأحزاب:53] فبيَّن سبحانه أنه لا بد من الحجاب، ولم يقل: إلا الوجه أو الكفين بل أطلق فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ[الأحزاب:53] جدار أو خمار، أو جلباب تستر به نفسها، أي حجاب يحصل به المقصود حتى لا ترى زينتها فالحمد لله. ثم بيَّن سبحانه أن هذا أطهر لقلوب الجميع، بين العلة، قال: ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ[الأحزاب:53] يعني: أطهر من الميل إلى الفاحشة، والوقوع في الفاحشة، وأسلم للجميع؛ لأن بروز المرأة من أسباب الفتنة، فإذا احتجبت كان هذا من أسباب سلامة القلوب، ولهذا في الآية الأخرى في سورة النور يقول سبحانه: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ أَوْ أَبْنَائِهِنَّ أَوْ أَبْنَاءِ بُعُولَتِهِنَّ أَوْ إِخْوَانِهِنَّ أَوْ بَنِي إِخْوَانِهِنَّ أَوْ بَنِي أَخَوَاتِهِنَّ ..[النور:31] الآية. أما الحديث الذي ذكره السائل فهو حديث ضعيف لا يصح عن النبي ﷺ، وهو ما يروى عن عائشة رضي الله عنها أن أسماء أختها بنت أبي بكر الصديق  جميعًا دخلت على النبي ﷺ وعليها ثياب رقاق، فأعرض عنها النبي ﷺ وقال: يا أسماء: إن المرأة إذا بلغت المحيض لم يصلح أن يرى منها إلا هذا وهذا وأشار إلى وجهه، وكفيه. احتج بهذا بعض الناس على أن المرأة الأجنبية لها أن تكشف وجهها وكفيها عند الأجنبي كأخي زوجها، وزوج أختها، وابن عمها، وغيرهم من الناس، وهذا غلط، والحديث ضعيف لا يصح عن النبي ﷺ؛ لأن فيه عللًا كثرة: إحداها: أنه منقطع؛ لأنه من رواية خالد بن دريك عن عائشة، ولم يسمع منها. الثاني: أن في سنده سعيد بن بشير، وهو ضعيف لا يحتج بروايته. الثالث: العلة الثالثة: أنه من رواية قتادة عن خالد بن دريك، وهو مدلس بالعنعنة. العلة الرابعة: أن هذا منكر في متنه؛ لأنه لا يليق من أسماء وهي المرأة الصالحة زوجة الزبير، امرأة معروفة بالخير والاستقامة؛ لا يليق منها أن تدخل على النبي ﷺ في ثياب رقاق، هذا منكر المتن، شاذ مخالف للأحاديث الصحيحة والآيات. خامسًا: أن هذا يحتمل أن يكون قبل نزول آية الحجاب، أن هذا كان حين كانت المرأة يباح لها أن تكشف، ثم نزل الحجاب، وأمر النساء بالتستر. فهذه علل خمس في هذا الحديث، فهو مخالف لنص الآية الكريمة، وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ[الأحزاب:53] مع ما فيه من العلل، ومع المخالفة؛ لقوله تعالى: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ..[النور:31] الآية، والوجه من الزينة، والكفان من الزينة، نسأل الله للجميع الهداية والتوفيق. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم. الشيخ: الله المستعان.","link":"https://binbaz.org.sa/fatwas/18156/مناقشة-القول-بجواز-كشف-المراة-لوجهها-وكفيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_794/nour_79402.mp3","categories":["اللباس والزينة"]},{"id":19041,"question":"يا سماحة الشيخ! السائل خالد من القصيم يقول: سماحة الشيخ حفظكم الله! ما حكم صبغ اللحية بصبغة سوداء قاتمة؟","title":"ما حكم صبغ اللحية بصبغة سوداء قاتمة؟","answer":"الجواب: لا يجوز صبغ اللحية ولا غيرها بالسواد، يقول النبي ﷺ: غيروا هذا الشيب واجتنبوا السواد، هكذا أمر ﷺ لما جيء إليه بوالد الصديق ورأسه ولحيته كالثغامة بياضًا، قال لأبي بكر: غيروا هذا الشيب واجتنبوا السواد، فلا يجوز تغيير الشيب بالسواد لا من المرأة ولا من الرجل، لكن بالسواد مع الحمرة يكون بين السواد والحمرة ليس بالسواد قاتم، بل بين السواد والحمرة أو بالحمرة أو بالصفرة لا بأس.","link":"https://binbaz.org.sa/fatwas/18213/ما-حكم-صبغ-اللحية-بصبغة-سوداء-قاتمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_883/nour_88310.mp3","categories":["اللباس والزينة"]},{"id":19057,"question":"رسالة .... [وردت من إحدى الأخوات المستمعات مفادها: ما حكم كشف المرأة الرأس والساق والعضد أمام محارمها أو أمام النسوة؟ وما هو المباح للمرأة أن تكشفه أمام من تقدم؟.....].....","title":"هل يجوز كشف المرأة رأسها وساقيها وعضديها لمحارمها؟","answer":"الجواب: ......: وعند النساء، ولكن ستر ذلك أحوط للمؤمنة؛ لأنه قد يجر إلى الفتنة، فالأولى بها ستر الساق وستر العضد عند المحارم، وستر الرأس عند المحارم، هذا هو الأفضل ....... ستره وهكذا العضد ستره أولى وأحوط لئلا يجر إلى فتنة. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18226/هل-يجوز-كشف-المراة-راسها-وساقيها-وعضديها-لمحارمها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_928/nour_92809.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":19062,"question":"بعد هذا رسالة وصلت إلى البرنامج من ليبيا باعثتها إحدى الأخوات المستمعات وقعت في نهاية رسالتها بقولها: أختكم في الله (حواء . م. م) تسأل سماحتكم عن الخياطة للنساء إذا طلبت المرأة من هذه المرأة التي تعمل في الخياطة أن تخيط لها ملبسًا على الموضة كما يقال عند النساء، فما هو توجيهكم هل تستجيب لها؟ أم كيف تتصرف؟ جزاكم الله خيرًا.","title":"حكم خياطة المرأة ملابس النساء على الموضة","answer":"الجواب: إذا كانت الموضة تخالف الشرع؛ لا تستجيبي، تخيط لها خياطة توافق الشرع لا تخالفه، فإذا كانت الخياطة التي تريدها المرأة تخالف الشرع المطهر بأن كونها تبدي شيئًا من العورة؛ وهذه الخياطة يبدأ منها ما بين السرة والركبة هذا لا يجوز، أو ضيقة جدًا تبدي حجم الأعضاء وحجم العورة لا يجوز هذا أيضًا. وأما إذا كانت الخياطة لا يحصل بها ذلك، بل موضة تناسب الحريم وليس فيها إظهار العورة ولا تضييق يبين حجم العورة فلا حرج في ذلك، لكل ناس لهم شكلهم ولهم عادتهم، والملابس أمور عادية لكل أهل بلد ولكل قوم عوائد في هذا الشيء، فإذا خاطت لهم على عوائدهم وطريقتهم التي يلبسونها في قمصهم وسراويلهم؛ فلا بأس بشرط أن يكون ذلك القميص الذي تخيطه ليس فيه ما يبين العورة التي بين السرة والركبة. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم. الشيخ: والمقصود يعني: عورة المرأة فإن عورة المرأة مع المرأة ما بين السرة والركبة. نعم. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18235/حكم-خياطة-المراة-ملابس-النساء-على-الموضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_737/nour_73702.mp3","categories":["اللباس والزينة"]},{"id":19078,"question":"يقول هذا السائل: يوجد في بلدي البعض من النساء ترتدي ما يسمونه بالقناع: وهو عبارة عن قطعة من القماش الأسود، ويكون مقاس هذا القناع متر في متر، هل يغني ذلك عن الحجاب مع أنه يغطي الوجه، ولكن تبقى اليدين ونصف الوجه العلوي، أفتونا يا سماحة الشيخ؟","title":"حكم لبس المرأة القناع بدل الحجاب","answer":"الجواب: لابد من لباس يسترها كلها يستر رأسها ووجهها ويديها عن الرجال سواء سمي قناع وإلا غيره لابد أن تعتني بما يسترها، ويستر كفيها وقدميها -نعم- كما تستر وجهها تستر كفيها وقدميها؛ لأنها عورة كلها، النبي ﷺ... يقول: المرأة عورة. نعم.","link":"https://binbaz.org.sa/fatwas/18243/حكم-لبس-المراة-القناع-بدل-الحجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_883/nour_88319.mp3","categories":["اللباس والزينة"]},{"id":19216,"question":"إحدى الأخوات المستمعات تقول: المرسلة أختكم (حياة . م. س. ح)، أختنا لها مجموعة من الأسئلة، في سؤال لها تقول: هل يجوز للمرأة أن تغطي وجهها وكفيها بقفازين عندما تذهب للحج أو للعمرة؟ وهي بذلك ليست مكرهة، بل إن وليها أعطاها حرية الخيار بين أن تكشف أو تغطي وجهها؟ أفيدونا جزاكم الله خيرًا.","title":"حكم انتقاب المرأة ولبسها القفازين في الحج والعمرة","answer":"الجواب: المرأة في الإحرام ليس لها أن تغطي وجهها بالنقاب أو البرقع، وليس لها أيضًا أن تلبس القفازين في اليدين؛ لأن الرسول عليه الصلاة والسلام نهى عن ذلك، قال عليه الصلاة والسلام فيما أرشد إليه المحرم: ولا تنتقب المرأة ولا تلبس القفازين يعني: في الإحرام. ولكنها تغطي وجهها بغير ذلك من الخمار ونحوه، تغطي يديها بغير ذلك من جلبابها أو عباءتها أو نحو ذلك. أما القفازان فلا، وهكذا النقاب وهو ما يصنع للوجه المخيط الذي يصنع للوجه هذا لا تلبسه المحرمة لا في العمرة ولا في الحج. قالت عائشة رضي الله عنها: «كنا مع النبي ﷺ في حجة الوداع، وكنا إذا دنا منا الركبان سدلت إحدانا خمارها من على رأسها على وجهها، فإذا بعدوا كشفنا» فالمرأة هكذا إذا كان يقرب منها رجال تغطي وجهها بالخمار ونحوه لا بالنقاب المصنوع للوجه. ولا تغطي يديها بالقفازين ولكن بغيرهما، وهكذا الرجل لا يغطي وجهه وهو محرم ولا يغطي رأسه وهو محرم، ولا يغطي يديه بالقفازين وهو محرم، ولكن يغطي يديه بغير القفازين لو غطى يديه بالرداء أو بالإزار أو بشيء آخر لا بأس بذلك. فالمرأة مثله نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18391/حكم-انتقاب-المراة-ولبسها-القفازين-في-الحج-والعمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_933/nour_93311.mp3","categories":["اللباس والزينة","محظورات الإحرام","قضايا المرأة"]},{"id":19223,"question":"أخت لنا من ليبيا تقول: ( أم كلثوم . س. س) تسأل وتقول: إنها تعمل في الخياطة، وتخيط للناس حسب أذواقهم ورغباتهم، منهم من يريد الواقي، ومنهم من يريد العاري الفاضح، هل عليها إثم إذا استجابت للصنف الثاني، وأعطتهم أو واشتغلت لهم على رغباتهم؟","title":"حكم خياطة الملابس العارية","answer":"الجواب: نعم، نعم. عليها إثم؛ لأنها معينة على الإثم والعدوان، والله يقول سبحانه: وَلا تَعَاوَنُوا عَلَى الإِثْمِ وَالْعُدْوَانِ [المائدة:2]، فليس لها أن تعين المرأة التي قد ذهب حياؤها، ورق دينها وضعف خوفها من الله ، ليس لها أن تعينها على الفجور وأسباب الفجور، فاللباس العاري هذا فجور وشر عظيم وبلاء كبير ووسيلة إلى الفساد العظيم، فليس لها أن تعينها على ذلك، لا في الخياطة ولا في التفصيل، ولا في الكلام أيضًا، ولا في تسهيل الأمر، بل عليها أن تمتنع من ذلك، وأن تشدد في ذلك وأن تحذر من ذلك. فالمؤمن والمؤمنة كلاهما يأمران بالمعروف وينهيان عن المنكر، كما قال الله سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71]، فهذا من هذا الباب من باب الأمر بالمعروف والنهي عن المنكر، وليس لها أن تتساهل في هذا الأمر من أجل الطمع في المال، بل يجب عليها أن تنبه على هذا الأمر وأن لا يعان المسلمون على معصية. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18419/حكم-خياطة-الملابس-العارية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_890/nour_89007.mp3","categories":["اللباس والزينة"]},{"id":19224,"question":"سماحة الشيخ! أخواتنا في أسئلتهن يعرجن إلى فتوى ذكرت أن الوجه والكفين ليسا بعورة، رأيكم في هذا وتوجيهكم لو تكرمتم؟","title":"حكم كشف المرأة للوجه والكفين لغير المحارم","answer":"الجواب: لا شك أن هذا عورة، وقد تكلمت في هذا مرات كثيرة، وكتبنا في هذا رسالة وسميناها السفور والحجاب، فالوجه والكفان عورة، وهذا هو الحق الذي عليه المحققون من أهل العلم، وقد دل عليه قوله تعالى: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ [الأحزاب:53]، ما قال الرب: إلا وجهها وكفيها، ثم قال: ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]، فذكر أنه أطهر لقلوب الرجال والنساء جميعًا، والطهارة مطلوبة للجميع. وقد قال الله سبحانه في كتابه العظيم: وَقُلْ لِلْمُؤْمِنَاتِ يَغْضُضْنَ مِنْ أَبْصَارِهِنَّ وَيَحْفَظْنَ فُرُوجَهُنَّ وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنْهَا [النور:31]، قال ابن مسعود: الملابس، وقال ابن عباس: الوجه والكفين، وقال بعض أهل العلم: المراد يعني: قبل الحجاب، أما بعد الحجاب فلا وجه ولا كفين، رواية ابن عباس .. قبل الحجاب. وعلى فرض أنه أراد بعد الحجاب فقوله مرجوح، وقول ابن مسعود هو الصواب، ويدل عليه ظاهر القرآن والسنة، ويدل عليه حديث عائشة رضي الله عنها لما وقعت وقعة الإفك وتكلم فيها بعض المنافقين وبعض من اغتر بالمنافقين، رموها بـصفوان بن المعطل لما وجدها صفوان متخلفة عن الجيش وحملها حتى وصلها الجيش، فرماها أهل الإفك بما رموها به، وهي البراء رضي الله عنها، وهي المرأة الحرة المصونة التي صانها الله وحماها وكذب من رماها بالفاحشة، قالت رضي الله عنها: (فلما سمعت صوت صفوان المعطل استرجع لما رآها، قالت: فخمرت وجهي، وكان قد رآني قبل الحجاب)، هكذا رواه الشيخان في الصحيحين، وهذا يدل على أنهم كانوا قبل الحجاب يكشفون وجوههم وبعد الحجاب ستروا الوجوه، وهذا هو الصواب. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18418/حكم-كشف-المراة-للوجه-والكفين-لغير-المحارم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_890/nour_89006.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":19243,"question":"أخونا يسأل عن البنطلون إذا طال، هل يعد إسبالاً أو لا؟","title":"حكم إسبال البنطال تحت الكعب","answer":"الجواب: الإسبال هو أن ينزل الثوب عن الكعب في حق الرجل، إذا نزل اللباس عن الكعب في حق الرجل فهذا هو الإسبال، سواء كان الثوب قميصًا أو بنطلونًا أو سراويل أو إزارًا أو غير ذلك مما يلبسه الرجل. فالواجب أن ينتهي عند الكعب، من نصف الساق إلى الكعب، وما دون الركبة كله ليس بعورة، الركبة وما تحتها ليس بعورة، والأفضل أن يكون اللباس إلى نصف الساق فأنزل إلى الكعب، وما زاد على هذا يكون منكرًا وإسبالًا. قال النبي عليه الصلاة والسلام في الحديث الصحيح: ما أسفل من الكعبين من الإزار فهو في النار، رواه البخاري في الصحيح، والإزار مثال يشمل الإزار والسراويل والبشت والقميص والبنطلون وغير ذلك. الواجب الوقوف عند الحد الذي حده الشرع، فإذا كان مع إرخاء الملابس نية التكبر والخيلاء والتعاظم صار الإثم أعظم، كما قال النبي ﷺ: من جر ثوبه خيلاء لم ينظر الله إليه يوم القيامة، وإن تساهل في هذا ولم يقصد الخيلاء لكن تساهل فهو ممنوع أيضاً؛ لأنه إسراف؛ ولأنه وسيلة إلى الخيلاء؛ والغالب أنه يفعل خيلاء ولأنه يعرض الملابس إلى القاذورات والنجاسات فلا يجوز إرخاؤها تحت الكعب. أما لو ارتخت من غير قصد منه، بأن انحل حبل قميصه وتعاهده وحرص عليه فهذا لا يضره كما قال الصديق  لما سمع الحديث قال يا رسول الله! إن إزاري يتفلت علي إلا أن أتعاهده، قال: لست ممن يفعله كبرًا. فالمقصود أنه إذا كان انحل عليه إزار أو غيره ثم تعاهده وحرص وتلافاه فهذا لا يضره، أما من يتعمد ذلك ويتركه ويسحبه هذا هو المنكر وهذا هو الجريمة، فلا يجوز ذلك أبدًا، نسأل الله للجميع الهداية. أما المرأة فلا بأس أن ترخي ملابسها حتى تغطي أقدامها؛ لأن الرسول ﷺ سئل عن ذلك فأرخص للنساء شبرًا، فقال بعضهن: إنها تنكشف أقدامهن، فرخص في الذراع من دون زيادة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18431/حكم-اسبال-البنطال-تحت-الكعب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_891/nour_89102.mp3","categories":["اللباس والزينة"]},{"id":19246,"question":"يسأل عن حكم استخدام الأسنان الصناعية ما حكم ذلك جزاكم الله خيرًا، ولاسيما إذا كان من أجل الزينة؟","title":"حكم استخدام الأسنان الصناعية","answer":"الجواب: الأسنان الصناعية لا بأس بها إذا كانت من غير الذهب للرجل، أما الرجل فينبغي له ترك الذهب وليتخذ أسنانًا من غير الذهب، إلا عند الضرورة كما أقر النبي ﷺ بعض الصحابة على اتخاذ أنف من الذهب لما قطع أنفه. فالحاصل: أن الأسنان الصناعية لا بأس بها عند الحاجة، أما للزينة فلا ينبغي، اتخاذ شيء للزينة ....... إذا كانت الأسنان سليمة فلا ينبغي أن تقلع لوضع أسنان للزينة، بل ينبغي أن يحمد الله على نعمته، وأن يبقي أسنانه ولا ينزعها للزينة لإبدالها، أقل أحوال هذا الكراهة، أقل أحواله الكراهة. أما إذا كانت الأسنان سقطت، وأراد أن يركب أسنانًا بدلًا منها فلا بأس أن يركب أسنانًا من المعدن، من المعادن الجائزة إلا الذهب تركه أولى إلا عند الضرورة إليه في حق الرجل. نعم. المقدم: جزاكم الله خيرًا، ما الحكم إذا كانت الأسنان مشوهة سماحة الشيخ؟ الشيخ: إذا كان الأسنان مشوهة لا بأس بإزالة التشويه، إذا كانت طويلة أو متقدمة أو متأخرة يعدلها لا بأس. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18439/حكم-استخدام-الاسنان-الصناعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_738/nour_73809.mp3","categories":["اللباس والزينة"]},{"id":19269,"question":"بعض النساء عندما نقول لهن: إن كشف الوجه لا يجوز، يقلن: إن الرسول ﷺ كان يجتمع بالنساء وكن يجاهدن في سبيل الله، وكن يعالجن المرضى، ما هو توجيهكم؟","title":"ما الرد على من يرى جواز كشف المرأة وجهها؟","answer":"الجواب: كان النساء في أول الإسلام وفي أول الهجرة مباح لهن الكشف، ثم نزلت آية الحجاب، فكونهن يكشفن في المجتمعات كان أولًا، تكشف عن وجهها ويديها، ثم إن الله  أمر بالحجاب حماية للمرأة وصيانة لها، عن الابتذال وعن فتنة الرجال بها، فأنزل في هذا  قوله تعالى: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]، وأنزل في هذا قوله تعالى: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ .. [النور:31]، والزينة: هي المحاسن من شعرٍ ووجه ويد وقدم وصدر ونحو ذلك. فالواجب على النساء بعد نزول هذه الآيات هو الحجاب، والوجه أحسن الزينة، وهو عنوان المرأة، عنوان جمالها ودمامتها، فالواجب ستره عملًا بهذه الآيات، وقد ثبت عن عائشة رضي الله تعالى عنها أنها لما سمعت صوت صفوان المعطل في غزوة الإفك، لما تخلفت عن الغزو ورآها صفوان المعطل متخلفة استرجع، قال: إنا لله وإنا إليه راجعون، فلما سمعت صوته؛ خمرت وجهها، قالت: وكان قد رآني قبل الحجاب، هكذا جاء في الصحيحين عن عائشة. فدل ذلك على أن المرأة كانت قبل الحجاب يرى وجهها، أما بعد الحجاب فقد منع من ذلك الرجل، ولا يجوز أن يقال: إن هذا خاص بأمهات المؤمنين فإنهن وغيرهن سواء في هذا، ولم يرد ما يدل على التخصيص، والأصل عدم التخصيص؛ ولهذا قال  في المؤمنات: لا يُبْدِينَ زِينَتَهُنَّ [النور:31]، وعمم، ولم يقل: أزواج النبي ﷺ فالحكم عام لجميع المؤمنات، من أزواج النبي ﷺ وغيرهن. ومن قال: إنه خاص بهن فعليه الدليل، ولا دليل يخصهن بذلك، بل هو قول بغير علم وبغير حقيقة، وبغير دليل، ثم عمل المسلمين على ذلك من عهده ﷺ بعدما نزلت هذه الآيات على الحجاب، وعدم سفور المرأة؛ لأن ذلك مما يسبب الفتنة بها، ووقوع الفواحش، وتطلب الرجل للمرأة بسبب ما يرى من جمالها وحسنها، والواجب على الرجال والنساء العمل بأسباب السلامة، والحذر من أسباب الفتنة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18463/ما-الرد-على-من-يرى-جواز-كشف-المراة-وجهها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_892/nour_89208.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":19279,"question":"يسأل ويقول: هل تجوز الصلاة خلف إنسان مسبل، وحالق للحيته؟ وضحوا لنا هذا الأمر جزاكم الله خيرًا.","title":"حكم الصلاة خلف من حلق اللحى وأسبل الثوب","answer":"الجواب: حلق اللحى معصية، وقصها معصية، وهكذا الإسبال معصية، والإسبال: هو إرخاء الملابس تحت الكعب في حق الرجل، كل هذا معصية، يقول النبي ﷺ: قصوا الشوارب وأعفوا اللحى خالفوا المشركين متفق على صحته، ويقول ﷺ: قصوا الشوارب، ووفروا اللحى، خالفوا المشركين خرجه البخاري في الصحيح، ويقول أيضًا عليه الصلاة والسلام: جزوا الشوارب، وأرخوا اللحى، خالفوا المجوس معنى أعفوا معنى أرخوا معنى وفروا، يعني: اتركوها على حالها وافرة معفاة مرخاة. هكذا يكون المسلم طاعة لله جل وعلا، وطاعة لرسوله عليه الصلاة والسلام، وابتعادًا عن مشابهة المشركين من المجوس وغيرهم، ولو وفروها ما نقصها نحن نوفرها ولو وفروها، لكن الغالب عليهم قصها وحلقها، لكن لو قدر أن المشركين وفروها ما نخالفهم بالقص، لا نبقيها وافرة إذا شابهونا لا بأس نحب منهم أن يدخلوا في الإسلام أيضًا، ويصلوا معنا، ويصوموا معنا. فالحاصل: أن علينا أن نخالفهم، لكن إذا وافقونا هم ما نخالف ديننا نبقى على ديننا، لا نخالف ديننا من أجلهم، بل نبقى على ديننا وإن وافقونا في إرخائها نرخيها ونوفرها، وهكذا لا نقصها قصًا بل نعفيها لا نقص، ولا نحلق. وهكذا الإسبال لا نرخي الإزار، ولا السراويلات، ولا القمص، ولا الجبة، ولا البشت، ولا العباءة ولا غير ذلك، يجب أن تكون كلها بحد الكعب لقول النبي ﷺ: ما أسفل من الكعبين من الإزار فهو في النار، فما جاوز الكعب فهو الإسبال مطلقًا، وإذا كان معه نية التكبر صار أعظم في الإثم؛ لقول النبي ﷺ: من جر ثوبه خيلاء لم ينظر الله إليه يوم القيامة، لكن إذا كان من دون خيلاء يكون الذنب أخف مع أنه محرم مطلقاً، هذا هو الصواب محرم وإن لم يقصد التكبر لقوله ﷺ: ما أسفل من الكعبين من الإزار فهو في النار رواه البخاري في الصحيح ولم يشترط أن يكون عن تكبر، ولقوله ﷺ في الحديث الآخر: إياك والإسبال فإنه من المخيلة جعل الإسبال من المخيلة من التكبر لأنه وسيلة إلى التكبر وإن لم يقصد ذلك. وفي الحديث الآخر يقول ﷺ: ثلاثة لا يكلمهم الله ولا ينظر إليهم يوم القيامة ولا يزكيهم ولهم عذاب أليم: المسبل إزاره، والمنان فيما أعطى، والمنفق سلعته بالحلف الكاذب رواه مسلم في الصحيح، هذا وعيد عظيم يدل على أنه كبيرة أن الإسبال كبيرة من كبائر الذنوب، ذكر الإزار لأن غالب العرب يلبسون الأزر، وإلا فالمقصود: إسبال الثياب مطلقًا إزار، أو قميص، أو سراويل، أو بشت أو غير ذلك. وأما المنان فيما أعطى هو الذي يمن بالعطية يعطي ويمن على يقول: أعطيتك، فعلت بك؛ يمن عليه.\nوالمنفق سلعته بالحلف الكاذب معناه: الذي يدرج يعني يمشيها بين الناس بأيمانه الكاذبة والعياذ بالله، حتى يشتروها والله إن ناس أدوا كذا وهو يكذب، والله إنها علي بكذا حتى تشترى منه بأكثر الثمن، نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18452/حكم-الصلاة-خلف-من-حلق-اللحى-واسبل-الثوب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_800/nour_80002.mp3","categories":["اللباس والزينة"]},{"id":19281,"question":"أخونا يسأل سماحتكم فيقول: حدثوني عن الأدلة الشرعية على وجوب النقاب؟","title":"الأدلة الشرعية على وجوب النقاب","answer":"الجواب: أعظم دليل وأوضح دليل قوله تعالى في كتابه الكريم: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]، وقوله : وَالْقَوَاعِدُ مِنَ النِّسَاءِ اللَّاتِي لا يَرْجُونَ نِكَاحًا فَلَيْسَ عَلَيْهِنَّ جُنَاحٌ أَنْ يَضَعْنَ ثِيَابَهُنَّ غَيْرَ مُتَبَرِّجَاتٍ بِزِينَةٍ [النور:60]، فإذا كان العجائز -وهن القواعد اللاتي لا يرجون نكاحًا- عليهن الحجاب إذا كن يرجون النكاح أو عليهن الزينة ولا يباح لهن الكشف إلا عند كونهن قواعد عجائز وكونهن لا يرجون نكاحًا وغير متبرجات؛ علم بذلك أن غير القواعد يلزمهن التستر والحجاب سواء كن متبرجات أو غير متبرجات، يجب عليهن التستر وعدم إظهار الملابس الجميلة الفاتنة، وعدم كشف الوجه أو الصدر أو الساق أو اليد أو غيرها؛ لأن هذا تبرج، قال الله جل وعلا: وَلا تَبَرَّجْنَ تَبَرُّجَ الْجَاهِلِيَّةِ الأُولَى [الأحزاب:33]، قال العلماء: التبرج معناه: إظهار المحاسن والمفاتن من رأس أو وجه أو نحوه. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18477/الادلة-الشرعية-على-وجوب-النقاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_739/nour_73905.mp3","categories":["اللباس والزينة"]},{"id":19320,"question":"أختنا تسأل وتقول: لماذا الأحكام في الإسلام على المرأة مشددة، ومع ذلك فإن أكثر أهل النار من النساء؟","title":"الرد على شبهة أن الإسلام شدد على المرأة","answer":"الجواب: ليست الأحكام مشددة في حقها، وأين التشديد؟ بل هي مسامحة في أشياء، المرأة مسامحة في أشياء، إذا حاضت لا تصلي، ولا تصوم حتى تطهر، وإذا طهرت بقي عليها الصوم فقط والصلاة تسقط عنها، والعقيقة لا يجب لها إلا واحدة، وعن الذكر ثنتين -في العقيقة- أين التشديد؟! ... فيه التسامح، وديتها خمسون، هذا من التسامح وليس من التشديد ديتها نصف دية الرجل، نصف خمسون من الإبل، هذا من التسامح وليس من التشديد. وهي مأمورة أيضًا بطاعة زوجها والاستقامة على طاعة ربها  والبقاء في البيت، والبعد عما حرم الله عليها، كل هذا من تسهيل الله عليها وتيسيره، ما كلفها بأشياء تؤذيها وتضرها، ما كلفها بأن تخرج تعمل مع الرجال، تنفق على زوجها، الزوج الذي ينفق عليها، هذا من خدمة زوجها لها، ومن إكرام الله لها، فالله يسر عليها ولم يشدد  بل يسر عليها وأكرمها وجعل الزوج هو الذي يخدم ويعمل ويكدح وينفق عليها ويقوم بحاجاتها، وهي تقوم في البيت بحال البيت وحال الأولاد، وتهيئ الشيء للزوج من طعام وغيره. فهي في الحقيقة مخدومة وخادمة، تخدم زوجها في حدود طاقتها وما شرع الله لها، والزوج يخدمها في تعب كبير، يذهب ويكدح ويعمل ويخاطر لطلب الرزق حتى ينفق عليها وعلى أولادها. أما كون النساء أكثر أهل النار كما قاله النبي ﷺ فقد بين النبي ﷺ ذلك، قال في خطبته: يا معشر النساء! تصدقن وأكثرن الاستغفار؛ فإني رأيتكن أكثر أهل النار. فقالت امرأة: ولم يا رسول الله؟ قال: لأنكن تكثرن اللعن وتكفرن العشير -يعني: الزوج- لو أحسن إلى إحداكن الدهر، ثم رأت منه شيئًا قالت: ما رأيت منك خيرًا قط فهذا عبارة عن الأكثر، وهذا مشاهد نعرف هذا، ويعرفه الناس، أن المرأة إذا رأت من زوجها ما يكدرها نسيت إحسانه الأول وقالت: أنت الذي فيك ما فيك، ولا رأيت منك كذا، ولا رأيت منك كذا، إلا من هداه الله منهن. واللعن، والكذب فيهن كثير، والسب للأزواج وللأولاد وللناس، ولذا قال: تكثرن اللعن يعني: الشتم والسب والكلام السيء، اللعن: يطلق على الكلام السيء ولو ما فيه: لعن الله فلان، كما قال الله في القرآن: وَالشَّجَرَةَ الْمَلْعُونَةَ فِي الْقُرْآنِ [الإسراء:60] وهي مذمومة في القرآن، ذمها الله وعابها، قال: إِنَّ شَجَرَةَ الزَّقُّومِ ۝ طَعَامُ الأَثِيمِ ۝ كَالْمُهْلِ [الدخان:45] ، فذمها، فسمى هذا لعنًا، فالذم للشيء وسبه بالكلام الذي ما هو بزين، مثل: أخزاه الله، مثل: ما فيه خير، مثل: فلان بخيل، فلان جبان، كل هذا يسمى سب، ولو ما قال: لعنه الله، يسمى: سب. فالمقصود أنهن يكثرن اللعن، يعني: يكثرن الكلام السيء والأذى مع الزوج ومع الأولاد، وربما فعلت ذلك مع الأقارب ومع الجيران، والغالب أن هذا من جهل وقلة الدين وضعفه، ولكن فيهن خيرات طيبات...","link":"https://binbaz.org.sa/fatwas/18529/الرد-على-شبهة-ان-الاسلام-شدد-على-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_895/nour_89502.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":19333,"question":"رسالة وصلت إلى البرنامج من جمهورية مصر العربية محافظة البحيرا، المرسل يونس عبد الحافظ علي أخونا يونس بعد مقدمة في رسالته يقول: لي ثلاثة أسئلة، في سؤاله الأول يقول: أديت بفضل الله تعالى فريضة الحج، وأثناء المبيت بمنى يوم التروية شعرت في آخر الليل ببرد شديد؛ لأني كنت نائمًا في الخلاء وعندما أحسست بشدة البرد قمت بتغطية نفسي ببطانية كانت معي غطيت جسدي كله بما في ذلك رأسي وأنا محرم، وأعلم أن كشف الرأس واجب حال الإحرام، فما الحكم وإن كان علي دم فهل يجوز لي أن أذبح في مصر التي أقيم بها أو أن أوكل غيري ممن يسافرون للحج بالذبح عني بمكة المكرمة؟ جزاكم الله خيرًا.","title":"حكم تغطية المحرم رأسه لشدة البرد","answer":"الجواب: المحرم ليس له أن يغطي رأسه كما هو معلوم، وليس له أن يلبس المخيط كما هو معلوم إذا كان ذكرًا، لكن إذا اضطر إلى ذلك لمرض أصابه احتاج معه إلى تغطية رأسه أو برد اشتد به حتى اضطر إلى تغطية رأسه فلا حرج عليه، ولكن عليه فدية وهذه الفدية مخيرة بين صيام ثلاثة أيام أو إطعام ستة مساكين أو ذبح شاة، كما في قوله جل وعلا: فَمَنْ كَانَ مِنْكُمْ مَرِيضًا أَوْ بِهِ أَذًى مِنْ رَأْسِهِ فَفِدْيَةٌ مِنْ صِيَامٍ أَوْ صَدَقَةٍ أَوْ نُسُكٍ [البقرة:196]. وجاء في حديث كعب بن عجرة في الصحيحين: أن الرسول عليه الصلاة والسلام أمره لما اشتد به الأذى في رأسه أن يحلق رأسه وأن يتصدق بثلاثة آصع من التمر بين ستة مساكين لكل مسكين نصف صاع، أو يصوم ثلاثة أيام أو يذبح شاة، فهذا هو الحكم فيمن احتاج إلى تغطية الرأس أو حلق الرأس أو لبس المخيط أو الطيب أو قلم الأظفار، حكمه حكم ما جاء في حديث كعب بن عجرة ، يخير بين ثلاثة أمور:\nإحداها: صيام ثلاثة أيام في أي مكان يصومها في مصر أو في غيرها. الثانية: إطعام ستة مساكين، يعني: ستة فقراء لكل مسكين نصف صاع من قوت البلد من تمر أو أرز أو حنطة أو شعير ونحو ذلك، وهذا في مكة هذا يعطاه فقراء مكة.\nالثالثة: ذبح شاة والذبح يكون في مكة أيضًا لفقراء الحرم. فعليك أيها السائل! أن تصوم ثلاثة أيام في بلادك وإن شئت أن تطعم ستة مساكين أو تذبح شاة فهذا يكون في الحرم عليك أن توكل ثقة يقوم بهذه المهمة أو تحضر بنفسك فتقوم بهذه المهمة، أما الصيام فلك أن تصوم في بلادك والحمد لله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18538/حكم-تغطية-المحرم-راسه-لشدة-البرد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_897/nour_89702.mp3","categories":["اللباس والزينة","محظورات الإحرام","قضايا المرأة"]},{"id":19368,"question":"أخت لنا من السودان تقول: سودانية مقيمة في المملكة تسأل أختنا تقول: إنها تعيش في قرية يكثر فيها الجهل، وهي وزميلة معها بدأن بالحجاب، لكن كثيرًا ما يواجهن بعض المصائب، وبعض المصاعب، ويرجين من سماحة الشيخ التوجيه؟","title":"الحث على الالتزام بالحجاب وإن وجدت المصاعب","answer":"الجواب: الواجب على المؤمنة تقوى الله في كل شيء ومن ذلك الحجاب؛ لأن الله يقول سبحانه: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ[الأحزاب:53]، وليس هذا خاصًا بأمهات المؤمنين كما يقول بعض الناس لا، بل هو عام، لأن الطهارة مطلوبة للجميع لأمهات المؤمنين ولغيرهن من المؤمنات، مثلما في الآية الأخرى: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ[النور:31] .. الآية. فالجميع مطلوب منهن التستر، وعدم التبرج، وعدم التكشف للأجناب، بل على كل واحدة من المؤمنات التستر، والحجاب، وعدم الخضوع بالقول لغير محرمها، وعدم التبرج كل هذا أمر معلوم.\nفالواجب على المؤمنة أن تحتسب الأجر، وأن تصبر، حتى ولو أوذيت في ذلك، ولو استهزئ بها، فقد سخر المجرمون من الأنبياء عليهم الصلاة والسلام، وسخروا من المؤمنين فما ضرهم ذلك. فالواجب على المؤمن والمؤمنة الاستقامة على تقوى الله، وعلى أداء فرائضه، وعلى ترك محارمه ولو سخر من سخر ولو آذى من آذى ..","link":"https://binbaz.org.sa/fatwas/18589/الحث-على-الالتزام-بالحجاب-وان-وجدت-المصاعب","audio":"","categories":["قضايا المرأة","اللباس والزينة"]},{"id":19382,"question":"أخت لنا من الرياض رمزت إلى اسمها بالحروف (خ. أ. ع) تقول في أسئلة لها: هل يجوز كشف العضد أو الساق عند المحارم؟","title":"ما يجوز للمرأة كشفه عند محارمها","answer":"الجواب: الأولى للمؤمنة ستر الساق والعضد؛ لأن فيه خلاف بين أهل العلم منهم من يجوزه للمحرم، ومنهم من لا يجوزه، والمقام فيه خطورة، فينبغي للمؤمنة ستر ذلك عن المحارم؛ لئلا يحصل به فتنة؛ لأن بعض المحارم قد يفتن بذلك. فينبغي ستر العضد والساق، وأن لا يرى منها إلا الوجه والكفان والقدمان لمحارمها، هذا هو الأحوط لها والأحسن لها؛ بعدًا عن الشر والخطر. ولو رأى رأسها لا بأس، لكن إذا سترت ذلك واحترزت يكون هذا أحسن وأسلم وأبعد عن الفتنة، ولاسيما في هذا العصر الذي ضعف فيه الدين، وقلت فيه خشية الله، وكثر فيه المحارم والفساق والمنحلون من الدين. فينبغي للمرأة أن تجتهد في أسباب السلامة، وأن تكون في صفة محتشمة عند محارمها، حتى تكون بعيدة عن الخطر. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18600/ما-يجوز-للمراة-كشفه-عند-محارمها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_934/nour_93409.mp3","categories":["اللباس والزينة"]},{"id":19413,"question":"ما حكم قص الشعر من الأمام أي: القصة على الوجه؛ لأني سمعت أن في ذلك تشبهًا بـاليهود والنصارى؟ وهل إذا كانت نيتي صالحة للتجمل، وليس إلى التشبه سبيل؛ لأن الأعمال بالنيات فهل أكون آثمة؟","title":"حكم قص المرأة شعرها","answer":"الجواب: قص الشعر إذا كان لمصلحة وليس فيه تشبه بالكافرات لا بأس، وإذا كان لها زوج لابد من مراعاة رضاه، أما إذا كان القص تشبه بالكافرات فلا يجوز؛ لقوله ﷺ: من تشبه بقوم فهو منهم وقد ثبت عن أمهات المؤمنين أزواج النبي ﷺ أنهن بعد وفاته قصصن من رءوسهن للتخفيف. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18640/حكم-قص-المراة-شعرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_936/nour_93609.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":19423,"question":"من هم الأشخاص الذين يجوز للمرأة أن تصافحهم؟","title":"الأشخاص الذين يجوز للمرأة مصافحتهم","answer":"الجواب: ليس لها أن تصافح إلا وليها ومحارمها بس، زوجها ومحارمها، الزوج والمحارم؛ أبي الزوج، ابن الزوج، أبوها، ولدها، أخوها، عمها، خالها.. المحارم أو النساء، أما أن تصافح زوج أختها أو تصافح أخا زوجها، أو ابن عمها، أو ابن خالها، أو .....، هذا لا ما يجوز، المصافحة ما تكون للرجال إلا للمحارم خاصة، ولهذا لما بايع النبي ﷺ النساء ومدت إليه امرأة أبى وقال: إني لا أصافح النساء، وقالت عائشة رضي الله عنها: ما مست يد رسول الله يد امرأة قط ما كان يبايعهن إلا بالكلام عليه الصلاة والسلام. وهذا كثير ما يقع وهذا يقع كثيرًا من بعض النساء في الجنوب، وفي البادية، فينبغي الحذر من هذا، المصافحة لا تكون إلا للمحارم؛ كالأب والأخ والعم، والزوج، وأبي الزوج، وابن الزوج، وهكذا مع النساء. أما مصافحة الأجنبي الذي يحل له زواجها كابن عمها وزوج أختها لو طلقها جاز له أن ينكح أختها، لو طلقها أو ماتت جاز له أن ينكح أختها، فلا تصافح أخا زوجها ولا عم زوجها ولا خال زوجها، ولا زوج أختها، كل هذا لا يجوز؛ لأنهم أجانب، كما لا تصافح جيرانها، ولا أبناء عمها، ولا سائقها ولا خادمها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18657/الاشخاص-الذين-يجوز-للمراة-مصافحتهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_937/nour_93705.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":19471,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يسأل فيها ويقول: لقد عرفت أن المرأة المسلمة يجب عليها أن لا تقلد الغرب؛ لأنهم نصارى أو يهود، و هل إذا لبست المرأة المسلمة الثوب الأبيض في ليلة زفافها يكون داخلًا في الحرمة حتى لو كان ذلك أصبح عرفًا؟","title":"حكم لبس المرأة الثوب الأبيض ليلة زفافها","answer":"الجواب: لا شك أن التشبه بأعداء الله من الكفرة أمر لا يجوز سواء كانوا يهودًا، أو نصارى، أو وثنيين، أو شيوعيين، أو غيرهم من أنواع الكفرة؛ لقول النبي ﷺ: من تشبه بقوم فهو منهم ولأدلة أخرى جاءت تحذر من التشبه بأعداء الله، وهو يعم الرجال والنساء. وجاءت أحاديث صحيحة تدل على تحريم تشبه النساء بالرجال، والرجال بالنساء، فلا يجوز للمرأة أن تلبس لبسة تشبه لبسة الرجل، ولا يجوز للرجل أن يلبس لبسة تشبه لبسة المرأة، وقد لعن النبي من فعل ذلك عليه الصلاة والسلام. واللباس الأبيض يختلف فإذا كان على الزي الذي يشبه الرجال حرم، وإذا كان على زي يختص به النساء فلا تحريم، وهكذا الأسود، والأحمر، والأصفر، والأخضر، جميع الألوان ما كان منها على زي الرجال حرم لبس النساء له، وما كان منها على زي النساء حرم لبس الرجال له، وهذا هو الفاصل في جميع الألوان، يجب عن الرجل أن يبتعد عن مشابهة المرأة في زيها، ولباسها ونحو ذلك، ويجب على المرأة أن تبتعد عن مشابهة الرجل في زيه، أو كلامه، أو مشيه أو نحو ذلك. وقد لعن الرسول ﷺ المتشبهين من الرجال بالنساء، ولعن ﷺ المتشبهات من النساء بالرجال، فكونها تلبس ليلة الزفاف لبسًا خاصًا اعتاده النساء لا يشبه لبس الرجال لا حرج سواء كان أسود، أو أخضر، أو أبيض أو غير ذلك، إذا كان من زي النساء ومن ملابس النساء، لكن يجب أن ينتبه المسلمون إلى أمر يفعله بعض الناس وهو تشييع المرأة على الطريقة المعروفة الآن بحيث تجعل على منصة مرتفعة لها لباس خاص، ويحضر الزوج وبعض من معه من أقاربه حتى يجلسوا عندها بين النساء، وكثير منهن سافرات؛ هذا لا يجوز هذا فتنة، وقد كتبنا في هذا ما يسر الله ونشر للتحذير من هذا العمل السيئ. أما كونها تجلس بينهم بلباس خاص حتى تعرف بين النساء فلا بأس، لكن لا يجوز السماح للرجال بالدخول على النساء في هذه الحالة لا الزوج ولا غيره، والزوج يدخل عليها في محل خاص غرفة خاصة محل خاص، يدخل على زوجته. أما جعلها في محل مرتفع يأتي الزوج، ويجلس معها؛ ربما لمسها، أو ربما قل حياؤه وقبلها عند الناس، أو ربما حضر معه أبوه، أو أخوه، أو إخوته، هذا أمر فيه خطر كبير، ولا يجوز، وفيه تعريضه لرؤية النساء اللاتي يكشفن هناك، أو يكن شبه عاريات هناك، وربما أفضى ذلك إلى فتنة له تجعله يزهد في زوجته ويرغب عنها لما شاهد من النساء الأخريات. فالحاصل أن هذا منكر لا ينبغي فعله، بل ينبغي طرح هذه العادة، وتركها، وأن تكون المرأة في محل خاص يدخل عليها فيه دون المحل الذي بين النساء، وأما وجودها بين النساء في صفة خاصة، أو لباس خاص ليس معهن رجال؛ فلا حرج في ذلك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18731/حكم-لبس-المراة-الثوب-الابيض-ليلة-زفافها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_945/nour_94505.mp3","categories":["اللباس والزينة"]},{"id":19491,"question":"يسأل السائل ويقول: ما حكم إزالة المرأة لشعر رجليها ويديها؟","title":"حكم إزالة المرأة شعر يديها ورجليها","answer":"الجواب: لا حرج في ذلك، إزالة شعر الأيدي والأرجل لا بأس والظهر والبطن. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18736/حكم-ازالة-المراة-شعر-يديها-ورجليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_939/nour_93921.mp3","categories":["اللباس والزينة"]},{"id":19500,"question":"يقول السائل: هل مصافحة الأجنبي تنقض الوضوء، مع العلم بأن المرأة التي صافحتها ليس من عادتها أن تصافح الأجانب؟","title":"حكم مصافحة الرجل المرأة الأجنبية","answer":"الجواب: ليس للرجل أن يصافح المرأة الأجنبية، أما أن يصافح أمه، أو أخته فلا بأس، أما مصافحة الأجنبية فلا تجوز، وليس للمرأة أن تصافح الأجنبي؛ لأن هذه المصافحة من وسائل الشر يقول النبي ﷺ: إني لا أصافح النساء وتقول عائشة رضي الله عنها: والله ما مست يد رسول الله يد امرأة قط، ما كان يبايعهن إلا بالكلام. أما مع المحارم فلا بأس أن يصافح زوجته، وأمه، وأخته، وبنته لا بأس. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18752/حكم-مصافحة-الرجل-المراة-الاجنبية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_946/nour_94603.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":19505,"question":"يقول السائل يا سماحة الشيخ: ما حكم لبس خاتم الفضة، مع كتابة اسم الزوجة في هذا الخاتم؟","title":"حكم لبس خاتم الفضة للرجل وكتابة اسم الزوجة عليه","answer":"الجواب: الخاتم من الفضة جائز للرجل والمرأة، وللمرأة خاتم الذهب أيضًا خاصة المرأة.\nأما الفضة يجوز للرجل والمرأة جميعًا، ويضع اسمه فيه لا بأس، وتضع اسمها فيه لا بأس. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18749/حكم-لبس-خاتم-الفضة-للرجل-وكتابة-اسم-الزوجة-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_939/nour_93928.mp3","categories":["اللباس والزينة"]},{"id":19534,"question":"يقول هذا السائل: هل يجوز أن نستعمل الصبغة السوداء إذا كان الشعر لونه أسود طبيعي وفيه القليل من الشيب؛ لأن هذا البنت التي تستعمل هذه الصبغة السوداء لا تستطيع أن تغير لون شعرها بلون آخر؛ لأنه لا يليق بها، هل يجوز لها ذلك؟","title":"هل يجوز استعمال الصبغة السوداء؟","answer":"الجواب: إذا كان فيها شيب لا يجوز لها ذلك، تغيره بشيء بين السواد، والحمرة، أو بالأحمر، أما سواد خالص لا، إذا كان فيها شيب؛ لأن النبي  قال: غيروا هذا الشيب واجتنبوا السواد. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18795/هل-يجوز-استعمال-الصبغة-السوداء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_946/nour_94625.mp3","categories":["اللباس والزينة"]},{"id":19545,"question":"مستمع كتب في أعلى رسالته يقول: أرجو عدم ذكر اسمي، يسأل ويقول: إنني شاب طائع لله ورسوله بكل شيء، وأحافظ على الصلوات ولله الحمد، لكن يكون بعض الثياب التي ألبسها طويلة تحت الكعبين، فهل أكون من الذين لا ينظر الله إليهم ومن أهل النار؛ لحديث الرسول ﷺ: ما أسفل الكعبين ففي النار وهل لا يقبل الله الصلوات التي يصلي بها الإنسان وثوبه طويل؛ لأنني سمعت حديثًا عن الرسول ﷺ حيث قال: لا يقبل الله صلاة رجل مسبل إزاره أفيدونا جزاكم الله خيرًا، وأرجو أن يكون بتفصيل واضح؟","title":"التحذير من الإسبال وحكم صلاة المسبل","answer":"الجواب: الإسبال من المحرمات ومن المنكرات وهو نزول الملابس عن الكعبين يقال له: إسبال، كالبشت والقميص والإزار والسراويل كل هذا لا يجوز أن ينزل عن الكعبين للحديث الذي ذكرت وهو قول النبي ﷺ: ما أسفل من الكعبين من الإزار فهو في النار وإذا كان عن تكبر وعن خيلاء صار أشد في الإثم وأعظم، وقال عليه الصلاة والسلام: ثلاثة لا يكلمهم الله ولا ينظر إليهم يوم القيامة ولا يزكيهم ولهم عذاب أليم: المسبل إزاره، والمنان فيما أعطى، والمنفق سلعته بالحلف الكاذب رواه مسلم في صحيحه. فالواجب التحفظ من ذلك، وأن تكون الملابس حدها الكعب لا تنزل، وأن تحذر من الكبر والخيلاء أيضًا في جميع أحوالك وفي ملابسك. أما الحديث الذي ذكرته في عدم قبول الصلاة فهو حديث فيه ضعف، وإن صححه النووي أو حسنه فهو حديث ضعيف؛ لأن في إسناده مدلسًا وقد عنعن وفي إسناده من هو مجهول. فالحاصل أن الوعيد بعدم قبول الصلاة لو صح فهو دليل على شدة التحريم، وأنه ينبغي للمؤمن أن يحذر الإسبال وهو من باب الوعيد، والوعيد قد يعفو الله عن صاحبه، وقد ينفذ عليه وعيده، فالمسلم المصلي على خطر إذا خالف الأوامر ووقع في النواهي، فالواجب عليه أن لا يرتكب المحظور وأن لا يترك المأمور. وقد روي عنه ﷺ: أنه أمر المسبل أن يتوضأ، أن يعيد الوضوء، ولكن لم يأمره أن يعيد الصلاة، وهذا لو صح لكان من باب التحذير ومن باب الترهيب وفيه العلة التي سمعت. فالصواب أن صلاته صحيحة، وأنه أخطأ في إسباله، ولكن لا تلزمه الإعادة إنما هو صحيح مثل بقية المعاصي، لو صلى وفي ثوبه درهم من حرام، أو في ثوب مغصوب أو في أرض مغصوبة، فالصواب أن صلاته صحيحة؛ لأن الإثم يتعلق بالغصب لا بالصلاة فهو أمر منهي عنه مطلقًا في الصلاة وخارجها، فإذا صلى في ثوب مغصوب أو أرض مغصوبة، أو ثوب فيه درهم حرام صحت الصلاة مع الإثم فهو آثم لأجل تعاطيه ما حرم الله عليه من الغصب والكسب الحرام ولكن الصلاة صحيحة؛ لأن هذا لا يتعلق بالصلاة يتعلق بموضوع تعاطيه ما حرم الله عليه من الغصب والكسب الحرام. وهكذا لو صلى في ثوب فيه نجاسة ناسيًا، ناسيًا لها أو جاهلًا بها حتى فرغ من صلاته صحت صلاته، كما ثبت في حديث أبي سعيد عند أحمد وأبي داود بإسناد صحيح: «أنه صلى عليه الصلاة والسلام ذات يوم ثم خلع نعليه وهو في الصلاة، فخلع الناس نعالهم، فلما سلم سألهم عن ذلك، فقالوا: رأيناك خلعت نعليك فخلعنا نعالنا، فقال: إن جبرائيل أتاني فأخبرني أن بهما قذرًا فخلعتهما، فإذا أتى أحدكم المسجد فلينظر في نعليه، -أو قال: فليقلب نعليه- فإن رأى فيهما قذرًا فليمسحه ثم يصلي فيهما. ولم يعد الصلاة عليه الصلاة والسلام، ولم يستأنفها بل استمر فيها، فدل ذلك على أن من وجد في ثوبه شيئًا ولم يعلم إلا بعد الصلاة فصلاته صحيحة، وإن علم في أثنائها وخلعه فصلاته صحيحة كما خلع النبي ﷺ نعليه.\nفالمؤمن يتحفظ ويحرص على أن يكون سليم الثياب من النجاسة سليم البقعة، سليم البدن، ولكن متى نسي شيئًا من النجاسة حتى فرغ من صلاته أو جهل ذلك فصلاته صحيحة، بخلاف الحدث، لو صلى محدثًا فإنه يعيد، لو صلى يحسب أنه على وضوء ثم تبين أنه على غير وضوء فإنه تلزمه الإعادة. وهكذا لو صلى جُنب يحسب أنه مغتسل ثم بان له أنه لم يغتسل أعاد؛ لأن الطهارة لابد منها شرط في الصلاة، الطهارة من الأحداث شرط في الصلاة، ولهذا قال عليه الصلاة والسلام: لا تقبل صلاة أحدكم إذا أحدث حتى يتوضأ وقال عليه الصلاة والسلام: لا تقبل صلاة بغير طهور بخلاف النجاسة في الثوب والبدن والبقعة فإنها أسهل إذا نسيها أو جهلها مثل الحديث الذي عرفت حديث أبي سعيد في قصة نعلي النبي ﷺ وما حصل فيهما من القذر، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18796/التحذير-من-الاسبال-وحكم-صلاة-المسبل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_940/nour_94007.mp3","categories":["اللباس والزينة","مسائل متفرقة في الصلاة"]},{"id":19553,"question":"تقول السائلة بالنسبة للبس الضيق بالنسبة للمرأة، وذلك أمام النساء فقط، والمحارم، والثياب المفتوحة بالنسبة للمرأة؟","title":"حكم لبس المرأة الضيق والمفتوح من الثياب","answer":"الجواب: المشروع للمرأة اللباس المتوسط، لا الواسع جدًا، ولا الضيق، بل تتحرى اللباس الذي يستر حجم أعضائها، ولا يبينها يسترها، ولا تلبس الضيق الذي يبين حجم أعضائها، بل تتحرى الوسط في ملابسها.","link":"https://binbaz.org.sa/fatwas/18805/حكم-لبس-المراة-الضيق-والمفتوح-من-الثياب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_947/nour_94704.mp3","categories":["قضايا المرأة","اللباس والزينة"]},{"id":19554,"question":"هذه السائلة أختكم (ش. الشمراني) أبها تقول: يا سماحة الشيخ هل صبغ الوجه بالمكياج بالنسبة للمرأة والكريمات السائلة يمنع من وصول الماء للبشرة أثناء الوضوء؟","title":"حكم استعمال ما يمنع وصول الماء للبشرة","answer":"الجواب: الشيء الذي يمنع الماء لا يجوز؛ فإذا مسحت وجهها بشيء لا يمنع الماء فلا بأس، أما شيء يبقى له جسم يمنع الماء لا يجوز، لا في الوجه، ولا في الذراع، ولا في الرجل، بل يجب أن يكون الذراع، والوجه، والقدم خاليًا مما يمنع الماء، فإن استعملت شيئًا ينور الوجه، ويطيب الوجه، ويحسنه لكن ليس له جسم يمنع الماء فلا بأس.","link":"https://binbaz.org.sa/fatwas/18804/حكم-استعمال-ما-يمنع-وصول-الماء-للبشرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_947/nour_94703.mp3","categories":["فروض الوضوء وصفته","اللباس والزينة"]},{"id":19571,"question":"تقول يا سماحة الشيخ: ما معنى كلمة المعصفر في حديث النهي عن لبس الثوب المعصفر بالنسبة للرجال، وهل يشمل جميع الملابس الحمراء للرجال، سواء كانوا كبارًا أو صغارًا؟","title":"حكم لبس المحادة الثوب المعصفر","answer":"الجواب: هذا تنهى عنه المرأة في حال الإحداد، ولا تلبس ثوب معصفر، المعصفر: هو المصبوغ بصبغ يكون جميلًا، يكون به جميلًا فلا تلبس الثوب المصبوغ صبغًا يجمله، أما إذا كان ثوبًا ليس فيه جمال فلا يضر هذا بالنسبة إلى المحادة، تلبس ثيابًا ليس فيها جمال. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18843/حكم-لبس-المحادة-الثوب-المعصفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_947/nour_94725.mp3","categories":["اللباس والزينة","العِدَد"]},{"id":19589,"question":"بالنسبة يا فضيلة الشيخ! يقول: إلى استعمال الصابون المعطر والشامبو للمحرم أيضًا هل فيه بأس؟","title":"حكم استعمال الصابون والشامبو المعطر للمحرم","answer":"الجواب: الصابون ليس من الطيب، والشامبو ليس بطيب، لكن ما يسمى الممسك إذا تركه.... لا بأس وإلا فليس بطيب. نعم.","link":"https://binbaz.org.sa/fatwas/18851/حكم-استعمال-الصابون-والشامبو-المعطر-للمحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_949/nour_94908.mp3","categories":["اللباس والزينة","محظورات الإحرام","قضايا المرأة"]},{"id":19590,"question":"هذا أخ سائل يقول: يا سماحة الشيخ! ما حكم تعطير الرأس والشخص محرم؟","title":"حكم الطيب للمحرم","answer":"الجواب: لا بأس، كان النبي ﷺ يطيب رأسه وبدنه وهو محرم، الممنوع اللباس، لا يطيب اللباس، أما إذا وضع الطيب في رأسه أو في مفارقه فلا حرج فيه، كما أخبرت عائشة عن النبي ﷺ أنه وضع الطيب في مفارقه حين إحرامه ورأت ذلك في مفارقه بعد إحرامه اللهم صل عليه وسلم.","link":"https://binbaz.org.sa/fatwas/18849/حكم-الطيب-للمحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_949/nour_94907.mp3","categories":["اللباس والزينة","محظورات الإحرام","قضايا المرأة"]},{"id":19591,"question":"ما حكم شرب القهوة بالزعفران للمحرم يا شيخ؟","title":"حكم شرب القهوة مع الزعفران للمحرم","answer":"الجواب: لا يضع فيها الزعفران (القهوة)، الزعفران من الطيب. نعم.","link":"https://binbaz.org.sa/fatwas/18855/حكم-شرب-القهوة-مع-الزعفران-للمحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_949/nour_94910.mp3","categories":["اللباس والزينة","محظورات الإحرام","قضايا المرأة"]},{"id":19631,"question":"سماحة الشيخ! تقول السائلة أم العنود المستمعة للبرنامج ما حكم فرق الشعر على الجنب؟ وما معنى قول الرسول ﷺ: مائلات مميلات؟","title":"معنى حديث: (مائلات مميلات) وحكم فرق المرأة شعرها على الجنب","answer":"الجواب: معنى: مائلات عن الحق، عن العفة، مميلات لغيرهن عن العفة، ما هو بالفرقة، مائلات عن الرشد، وعن العفة؛ إلى الفساد والزنا، أما الفرقة فأمرها سهل لكن الأفضل أن تكون متوسطة حتى لا يتشبه الإنسان بأعداء الله، تكون الفرقة متوسطة مما يلي الأنف وسط هذا هو الأفضل. وأما حديث: مائلات مميلات ما هو بالفرقة، مائلات عن العفة، وعن الخير؛ إلى الزنا والفواحش، نعم. المقدم: حفظكم الله يا سماحة الشيخ!","link":"https://binbaz.org.sa/fatwas/18902/معنى-حديث-ماىلات-مميلات-وحكم-فرق-المراة-شعرها-على-الجنب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_948/nour_94833.mp3","categories":["شروح الحديث","قضايا المرأة","اللباس والزينة"]},{"id":19701,"question":"ما حكم الأخذ من الحاجبين والفاصل بينهما بالنسبة للمرأة؟","title":"ما حكم الأخذ من الحاجبين والفاصل بينهما للمرأة؟","answer":"الجواب:  أخذ الحاجبين لا يجوز؛ لأن الرسول لعن النَّامصة والمتنمّصة، والنَّمص: أخذ شعر الحاجبين والوجه، أما ما بينهما -الفاصل بينهما- فقد أجازه بعضُ أهل العلم؛ لأنه ليس من الحاجبين، ولأنه يُفضي إلى منظرٍ مكروهٍ ومُستقبحٍ، فالذي يلي الأنف والحاجز بينهما أمره واسع، أما الحاجبان فلا يُؤخذ منهما شيء.\nوكذلك شعر الوجه لا يُنتف ولا يُتعرض له، إلا إذا كانت فيه مُثلة -فيه تشويه- كشعر الشَّارب واللّحية، إذا نبتت للمرأة لحيةٌ أو نبت لها شاربٌ فلا بأس بإزالة ذلك؛ لأنه يُشوه الخلقة ويضرُّها.\nأما الرجل فليس له أخذ اللحية، بل يجب عليه إكرام اللحية وتوفيرها وإرخاؤها، ولا يجوز له قصّها ولا حلقها، أما الشارب فالسنة للرجل أن يقصَّه، وأن يتعاهده، أما المرأة فلا مانع من إزالة الشَّارب، فإذا ظهر لها شاربٌ أو لحيةٌ تُزيل ذلك؛ لأنه يضرُّها ذلك، ويُسبب منظرًا سيئًا، وهو في حقِّها كالمثلة والتشويه.","link":"https://binbaz.org.sa/fatwas/20622/ما-حكم-الاخذ-من-الحاجبين-والفاصل-بينهما-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0553%D9%85%D8%A7%20%D8%AD%D9%83%D9%85%20%D8%A7%D9%84%D8%A3%D8%AE%D8%B0%20%D9%85%D9%86%20%D8%A7%D9%84%D8%AD%D8%A7%D8%AC%D8%A8%D9%8A%D9%86%20%D9%88%D8%A7%D9%84%D9%81%D8%A7%D8%B5%D9%84%20%D8%A8%D9%8A%D9%86%D9%87%D9%85%D8%A7%20%D8%A8%D8%A7%D9%84%D9%86%D8%B3%D8%A8%D8%A9%20%D9%84%D9%84%D9%85%D8%B1%D8%A7%D8%A9%D8%9F%D9%81%D8%AA%D8%A7%D9%88%D9%89%20%D8%A7%D9%84%D9%85%D8%AD%D8%A7%D8%B6%D8%B1%D8%A7%D8%AA.mp3","categories":["اللباس والزينة"]},{"id":19726,"question":"يقول هذا السائل: كيف يكون لباس الرجل في الصلاة يا سماحة الشّيخ ؟الشّيخ: كيف؟المقدم: يقول: كيف يكون لباس الرجل في الصلاة؟","title":"كيف يكون لباس الرجل في الصلاة؟","answer":"الجواب: اللباس المعتاد: قميص، أو إزار ورداء، كله كافي، يستر عورته ما بين السرة إلى الركبة، عورة الرجل، ويكون على كتفيه رداء لقوله ﷺ: لا يصلين أحدكم في الثوب الواحد ليس على عاتقه منه شيء فإذا جعل رداء على عاتقيه وصلى في الإزار أو في السراويل كفى صحت صلاته، وإذا لبس ما هو أجمل، كالقميص الزيادة كان أكمل وأفضل، وهكذا لبس العمامة؛ لأن الله يقول: يَا بَنِي آدَمَ خُذُواْ زِينَتَكُمْ عِندَ كُلِّ مَسْجِدٍ[الأعراف: 31]، يعني: عند كل صلاة، فإذا لبس غترته يعني عمامته وقميصًا وصلى في ذلك فهذا حسن، ويكفي في ذلك الإزار والرداء، أو القميص، يكفي، ولو كان مكشوف الرأس. المقدم: جزاكم الله خير يا شيخ عبد العزيز قد يقصد هذا السائل لبس البنطلونات بالنسبة للعمال في المساجد أيضًا؟ الشيخ: لا بد أن يكون اللباس ساترًا، فالعورة ما بين السرة والركبة، والبنطلون إذا كان ما فيه تشبه بالكفرة إذا كان من لباس المسلمين وستر ما بين السرة والركبة أجزأ مع ستر المنكبين أو أحدهما بالرداء.  المقدم: جزاكم الله خيرًا","link":"https://binbaz.org.sa/fatwas/29228/كيف-يكون-لباس-الرجل-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/%D9%83%D9%8A%D9%81%20%D9%8A%D9%83%D9%88%D9%86%20%D9%84%D8%A8%D8%A7%D8%B3%20%D8%A7%D9%84%D8%B1%D8%AC%D9%84%20%D9%81%D9%8A%20%D8%A7%D9%84%D8%B5%D9%84%D8%A7%D8%A9%D8%9F.mp3","categories":["ستر العورة للمصلي","اللباس والزينة","قضايا المرأة"]}]
